-- AP&E glossary — Machine B batch 1 — PASTE FILE 1 of 6
-- Paste this whole file into the Supabase SQL editor and Run. Order between files does not matter.
-- Idempotent: safe to re-run. Backup already exists (glossary_backup_mb_batch1_20260721).
BEGIN;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"1b62ae02-6831-4aaa-8221-7a2aefa3dbde": {"definition": "The unwanted capture by a microphone of sound from sources other than the one it is intended to record; also called bleed or leakage. It occurs whenever multiple sources are recorded together in one acoustic space and off-axis sound reaches each mic.", "plain_english": "When a mic set up for one instrument also picks up the sound of others playing nearby. Like trying to record just the singer, but the drums leak into the vocal mic too.", "purpose_function": "Spill is an unavoidable consequence of recording several sources acoustically at once; recognizing and managing it is what preserves separation between tracks and prevents phase and comb-filtering artifacts when the mics are combined.", "practical_application": "On a live-tracking session a technician minimizes spill with close miking, directional (cardioid/figure-8) patterns, gobos and screens, and greater mic spacing, and checks phase whenever two mics hear the same source.", "category": "Recording technique", "related_terms": ["Close miking", "Isolation", "Comb filtering", "Phase", "Gobo", "Polar pattern"], "common_mistakes": ["Assuming spill is always bad; a controlled amount of natural bleed can help glue a live ensemble recording together.", "Flipping polarity to 'fix' a spill/phase problem by guesswork instead of repositioning the mic and listening.", "Gating hard to remove bleed and cutting off the intended source's natural decay and tails."], "scenario_contexts": ["Recording a live band in one room where the acoustic guitar mic also captures the drum kit.", "Tracking a string quartet with spot mics that each pick up the neighboring players.", "Overdubbing through open headphones where the click track bleeds into the vocal mic."]}, "a18f95f9-102e-4207-b09f-f7826e0058d4": {"definition": "Any tuning of a guitar or related fretted string instrument to a set of pitches other than the standard EADGBE, including drop tunings (e.g., Drop D), open tunings (e.g., Open G, Open D) and modal tunings such as DADGAD. Retuning changes the open-string pitches, available chord voicings and the instrument's resonances.", "plain_english": "Tuning your strings to different notes than the usual standard tuning to get new chord shapes, droning open strings, or a deeper, richer ring. For example, dropping the low E to D for a heavier sound.", "purpose_function": "It exists to give players open-string drones, easier fingerings for particular keys or chords, extended low range, and altered resonance that standard tuning cannot provide.", "practical_application": "A technician tracking a guitarist in an alternate tuning notes the tuning on the take sheet, expects changed string tension and intonation, and re-checks tuning and mic placement as the instrument's low end and sustain shift.", "category": "Tuning", "related_terms": ["Standard tuning", "Drop D", "Open tuning", "Capo", "Intonation", "String gauge"], "common_mistakes": ["Assuming intonation stays perfect after retuning; raised or lowered string tension shifts intonation and often needs re-checking.", "Detuning strings far below pitch, leaving them slack and prone to fret buzz and tuning instability.", "Tuning strings well above standard pitch, over-stressing the string and neck and risking breakage."], "scenario_contexts": ["A singer-songwriter records fingerstyle pieces in DADGAD for its droning, modal ring.", "A rock guitarist uses Drop D for heavier riffs and one-finger power chords.", "A slide guitarist tunes to Open G for open-chord slide work."]}, "f543625b-a52e-4056-a7fa-a703df484ee2": {"definition": "The tone produced when a string instrument is played with the bow (arco, Italian for 'bow'), as opposed to plucked (pizzicato); it is a sustained, continuous tone arising from the bow's stick-slip (Helmholtz) excitation of the string. In a score, 'arco' instructs the player to resume bowing after a pizzicato passage.", "plain_english": "The smooth, singing sound a violin or cello makes when played with the bow rather than plucked with the fingers. 'Arco' just means 'with the bow.'", "purpose_function": "Bowing lets a string sustain a note and shape its dynamics and vibrato continuously, giving strings their long, expressive lines; in notation the arco marking exists to cancel a preceding pizzicato instruction.", "practical_application": "When recording arco strings a technician places mics to capture bow detail and body resonance without harshness, expecting long sustained tones and a wider dynamic range than the short transients of pizzicato.", "category": "Articulation", "related_terms": ["Pizzicato", "Bowing", "Sustain", "Vibrato", "String ensemble", "Spot mic"], "common_mistakes": ["Confusing arco with a specific dynamic or vibrato; arco only specifies that the bow is used.", "Close-miking arco strings too tightly, over-emphasizing bow scratch and losing the body and room bloom.", "Forgetting that 'arco' in a part cancels a previous 'pizz.' instruction, so the passage is bowed again."], "scenario_contexts": ["Tracking a cello section playing sustained legato lines with the bow.", "A part marked 'pizz.' then 'arco' where the player switches back to bowing.", "Recording a solo violin's long bowed melody for a film cue."]}, "27d06236-5026-479b-97ef-b69414d66cac": {"definition": "The small, floating (unglued) wooden bridge that rests on the banjo's tensioned head and supports the strings, coupling their vibration into the head where it is radiated as sound. Its mass and stiffness, together with the head, shape the timbre, including formant-like features in the upper midrange.", "plain_english": "A little wooden piece that sits loose on the banjo's drum-like head and holds the strings up, passing their vibration into the head so you hear it. It isn't glued down; string tension holds it in place.", "purpose_function": "It transfers the strings' energy into the head so the membrane can radiate it as sound, and its placement sets the vibrating string length that determines intonation.", "practical_application": "A setup tech positions and holds the floating bridge at the correct spot for intonation, and when miking a banjo aims near the bridge/head area to capture its bright attack and punch.", "category": "Instrument anatomy", "related_terms": ["Banjo head", "Banjo bridge position", "Banjo head tension", "Floating bridge", "Intonation", "Tone ring"], "common_mistakes": ["Thinking the banjo bridge is glued or fixed; it is held only by string tension and can shift or fall when strings go slack.", "Slackening all strings at once during a string change and losing the bridge's set position and intonation.", "Fitting an overly heavy or mismatched bridge and dulling the banjo's characteristic bright tone."], "scenario_contexts": ["Setting up a banjo and locating the bridge for correct intonation before a session.", "Changing strings and re-seating the floating bridge to its reference marks.", "Close-miking near the bridge and head to capture the banjo's attack."]}, "969624e6-676c-4c5c-94d6-2dde17dd74a3": {"definition": "The precise placement of the floating bridge on the banjo head, which sets the vibrating string length and therefore the intonation; it is located so the nut-to-bridge distance equals the nut-to-12th-fret distance doubled, with slight compensation for string action and gauge. Small shifts make fretted notes play sharp or flat relative to the open strings.", "plain_english": "Where you place the loose bridge on the banjo head. Put it in the right spot and notes up the neck play in tune; move it and the instrument goes sharp or flat.", "purpose_function": "Correct bridge position exists to make fretted notes match their intended pitches across the whole neck; because the bridge is not fixed, its position is the banjo's primary intonation adjustment.", "practical_application": "A tech sets intonation by comparing the 12th-fret harmonic to the fretted 12th-fret note and sliding the bridge toward or away from the neck until they match, often lightly marking the position for future string changes.", "category": "Setup & intonation", "related_terms": ["Banjo bridge", "Intonation", "Scale length", "12th-fret harmonic", "Compensation", "Banjo head"], "common_mistakes": ["Measuring only to the near edge of the bridge instead of the actual string contact point, leaving intonation off.", "Setting the bridge by eye and skipping the 12th-fret harmonic versus fretted-note check.", "Ignoring compensation for heavier strings or high action, so fretted notes run sharp."], "scenario_contexts": ["Intonating a banjo before recording so fretted chords stay in tune up the neck.", "Re-seating the bridge after a full string change using the 12th-fret check.", "Correcting a banjo that is in tune open but sharp when fretted."]}, "ed40ed1a-a9c9-4c4a-834e-90c437dba0eb": {"definition": "The reduction of string or head vibration on a banjo to shorten sustain or control ringing, whether inherent (energy is lost rapidly into the tensioned head, giving the banjo its characteristically short decay) or applied by the player (palm/heel muting, fingertip damping, or internal mutes and foam).", "plain_english": "Cutting short the banjo's ring. This can happen on its own, because the drum head soaks up the strings' energy fast, so notes fade quickly. Or the player does it on purpose by touching the strings or head to stop the sound.", "purpose_function": "Damping controls note length and clarity; the head's natural damping gives the banjo its crisp, punchy, fast-decaying sound, while deliberate damping lets a player mute unwanted ring, tighten rhythm, or play staccato.", "practical_application": "A player mutes strings with the picking-hand heel or fretting fingers for a tighter tone, and an engineer may add or remove head damping (foam, mutes) to manage sustain and reduce excessive ring reaching the mics.", "category": "Playing technique", "related_terms": ["Banjo head", "Banjo head tension", "Sustain", "Palm muting", "Decay", "Attack"], "common_mistakes": ["Assuming a banjo should sustain like a guitar; its short decay is inherent to the head's damping, not a fault.", "Over-damping the head with too much internal foam and killing the instrument's projection and tone.", "Confusing damping (stopping vibration) with lowering head tension, which changes pitch and tone rather than simply muting."], "scenario_contexts": ["A player heel-mutes the strings for a tight, staccato bluegrass backup rhythm.", "An engineer adds light internal damping to tame excessive ring on a bright banjo.", "Muting strings by hand to cut sustain between phrases during a take."]}, "96985edb-407d-437d-a946-98f1a4acd907": {"definition": "The circular membrane (historically animal skin, now usually Mylar/polyester, sometimes frosted or coated) stretched under tension over the banjo's rim, on which the bridge rests; it is the banjo's primary sound-radiating surface, functioning like a drumhead. Its material, tension and the rim/tone-ring assembly largely determine loudness and timbre.", "plain_english": "The tight, drum-like skin stretched across the round part of a banjo. The bridge sits on it, and it is what actually pushes the sound out into the air, like the head of a drum.", "purpose_function": "The head radiates the string energy delivered through the bridge as sound; being a light, tensioned membrane it makes the banjo loud and bright, and its tension sets much of the tone.", "practical_application": "A tech sets head tension to taste, replaces worn or torn heads, and when miking aims at the head near or slightly off the bridge to capture the banjo's projection and attack.", "category": "Instrument anatomy", "related_terms": ["Banjo bridge", "Banjo head tension", "Tone ring", "Rim", "Membrane", "Banjo damping"], "common_mistakes": ["Assuming banjo heads are always skin; most modern heads are Mylar/synthetic and react differently to humidity.", "Overtightening the head chasing brightness and risking cracking the head or distorting the rim and hardware.", "Miking only dead-center on the head, missing the balance of attack and body a slightly off-bridge position gives."], "scenario_contexts": ["Replacing a torn banjo head before a session.", "Miking the head to capture the banjo's bright projection.", "Choosing a coated versus clear head to warm up or brighten the recorded tone."]}, "32fedb67-ac41-4af3-857c-26512b6513b5": {"definition": "The degree to which the banjo head is stretched over the rim, adjusted by tightening the tension hoop via the bracket nuts and often set with a drum/dial gauge or by tap-tuning the head to a pitch. Higher tension raises the head's mode frequencies and radiation efficiency for a brighter, louder, more cutting tone; lower tension gives a warmer, softer, less projecting sound.", "plain_english": "How tightly the banjo's drum head is stretched. Tighter means brighter and louder with more snap; looser means warmer and mellower, just like tuning a drum.", "purpose_function": "Head tension is the main way to tune a banjo's tone and volume, letting a player or tech dial brightness, sustain and projection to suit the music without changing the instrument.", "practical_application": "A tech tightens the bracket nuts evenly to a target gauge reading or tap-tuned pitch, checks the head is even all the way around, and then re-checks bridge intonation, which shifts slightly with tension changes.", "category": "Setup & intonation", "related_terms": ["Banjo head", "Banjo bridge", "Tone ring", "Sustain", "Bracket", "Timbre"], "common_mistakes": ["Tightening bracket nuts unevenly, warping the head and rim and creating dead spots or buzzes.", "Overtightening for maximum brightness and cracking the head or over-stressing the hardware and rim.", "Changing head tension right before tracking and forgetting to re-check bridge intonation."], "scenario_contexts": ["Brightening a dull-sounding banjo by evenly raising head tension before a session.", "Setting head tension to a consistent gauge reading for repeatable recorded tone.", "Loosening a harsh head slightly to warm the recorded sound."]}, "69bdddfd-2ca2-4057-95f6-fa3295291cda": {"definition": "The sharp initial transient of a banjo note, produced when the string is plucked with fingerpicks (metal or plastic) or bare fingertips; the banjo's rapid energy transfer to the head yields a fast, percussive attack with a broadband transient burst that is central to its characteristic sound. Pick material, angle and force shape the attack's brightness and hardness.", "plain_english": "The bright, percussive 'pluck' you hear at the very start of each banjo note. Using metal fingerpicks makes it snappier and louder than bare fingers.", "purpose_function": "The attack gives the banjo its punch, clarity and rhythmic drive; because notes decay quickly, the strong attack carries much of the instrument's presence and definition in a mix.", "practical_application": "A technician controls the attack with pick choice and mic placement and tames harsh transients with gentle compression or by angling the mic slightly off the bridge rather than dulling the tone with heavy EQ.", "category": "Playing technique", "related_terms": ["Attack", "Transient", "Fingerpick", "Banjo damping", "Banjo bridge", "Compression"], "common_mistakes": ["Over-compressing to tame the banjo's attack and squashing the percussive life out of the track.", "Miking too close to the bridge and exaggerating a harsh, clacky attack.", "Blaming a harsh attack on the mic when pick material, angle or playing force is the real cause."], "scenario_contexts": ["Recording bluegrass rolls where the crisp attack drives the rhythm.", "Using light compression to even out sharp banjo transients in a mix.", "Adjusting mic distance to balance attack against body and ring."]}, "c09bf679-ec93-497a-b802-de46ff0b4967": {"definition": "The group of lower-pitched, typically wound strings on a stringed instrument (on a six-string guitar, the E, A and D strings) and the lower-frequency register they produce. It is contrasted with the treble-string region formed by the higher, thinner strings.", "plain_english": "The thicker, lower-sounding strings on a guitar or similar instrument, and the deep tones they make. Think of the left-hand end of a piano, but for strings.", "purpose_function": "It labels the low end of a stringed instrument so players and engineers can tune, discuss, and capture those notes separately, since the wound bass strings carry the harmonic foundation and behave differently from treble strings.", "practical_application": "An engineer positions or angles a mic to balance the bass-string region against the treble strings, and may use EQ so the wound low strings do not sound boomy or dull in the recording.", "category": "String register", "related_terms": ["Bass-string section", "Open string", "Course imbalance", "Drop tuning", "Palm muting"], "common_mistakes": ["Assuming the bass-string region only needs low-frequency EQ, when its note fundamentals and playing noise span a wide range", "Confusing the bass-string region of a guitar with a separate bass guitar", "Miking only over the soundhole, which exaggerates the boom from the wound low strings"], "scenario_contexts": ["Balancing the low strings against the high strings when close-miking an acoustic guitar", "Applying gentle EQ so the wound E and A strings do not dominate a fingerpicked part", "Discussing which strings carry the low end during a tracking session"]}, "15b7789f-ae54-4bd7-b7bd-721cb36c9d35": {"definition": "The set of an instrument's lower-pitched bass strings treated as a single group, such as the wound bass strings of a guitar or the long, thick strings on the bass side of a piano or harp. The term refers to the strings themselves rather than to a frequency range.", "plain_english": "The bunch of thick, low-sounding strings on an instrument, grouped together. On a piano these are the long strings at the left end.", "purpose_function": "Grouping the bass strings lets players, tuners, and engineers address the low strings as a unit for tuning, damping, or miking, because they share construction and tonal behavior.", "practical_application": "When recording a grand piano or harp, an engineer places or aims a microphone to capture the bass-string section evenly with the rest of the instrument.", "category": "String register", "related_terms": ["Bass-string region", "Course imbalance", "Open string", "Pedal harp", "Pizzicato"], "common_mistakes": ["Treating the bass-string section as a separate instrument rather than part of the whole", "Placing a mic so close to the bass strings that the section overpowers the treble strings", "Forgetting that wound bass strings lose brightness as they age and dull the section's tone"], "scenario_contexts": ["Positioning a piano mic to balance the bass-string section against the treble", "Checking tuning across the bass-string section of a harp before a take", "Explaining to a client why the low strings sound duller than the high strings"]}, "81c87375-6e58-42ef-808c-7726e730323d": {"definition": "The orientation, or axis, in which a wind or brass instrument's bell is aimed. Because such instruments radiate their higher harmonics as a directional beam that projects along the bell's axis, the bell direction largely determines where the instrument sounds brightest and loudest.", "plain_english": "Which way the open flared end (bell) of a horn is pointing. A trumpet or trombone throws its bright, loud sound mostly straight out of the bell, so where the bell points is where it sounds strongest.", "purpose_function": "Describes the primary direction of high-frequency sound radiation from a bell-loaded instrument; the concept matters because that radiation is directional rather than uniform, which affects both listeners and microphone placement.", "practical_application": "An engineer positions a microphone relative to the bell direction — on-axis for the brightest, most detailed capture and off-axis or slightly across the bell to tame harshness and blend the tone.", "category": "Sound Radiation", "related_terms": ["Bell flare", "On-axis response", "Off-axis coloration", "Directivity", "Polar pattern", "Close-miking"], "common_mistakes": ["Assuming a brass instrument radiates equally in all directions and placing the mic anywhere around it.", "Aiming the mic straight down the bell axis at close range, capturing a harsh, blaring tone with excessive high harmonics.", "Forgetting that players swing the bell during performance, so a fixed on-axis mic can produce large level and tone changes."], "scenario_contexts": ["Miking a trumpet or trombone section and choosing on- versus off-axis placement relative to each bell.", "Positioning a saxophone mic while remembering that on woodwinds much sound also leaves the tone holes, not only the bell.", "Recording a live horn player who sways, causing the bell to move on and off the microphone axis."]}, "2a0d8350-d9ec-4f5c-a40c-02f75fc61e93": {"definition": "The rapidly widening, trumpet-shaped end section of a brass (and some woodwind) instrument's air column. Its curved flare acts as an acoustic impedance transformer that improves radiation of the higher harmonics into the surrounding air and shapes the instrument's characteristic bright timbre.", "plain_english": "The cone-shaped opening at the end of a horn. This flared shape helps the instrument push its bright, higher tones out into the room efficiently.", "purpose_function": "Matches the high acoustic impedance of the narrow bore to the low impedance of open air so upper harmonics radiate efficiently; it makes the instrument loud and bright and influences which notes resonate.", "practical_application": "Most of a brass instrument's high-frequency energy leaves at the flare, so engineers aim close mics at or just off the bell mouth and account for the flare when judging tone and proximity.", "category": "Instrument Component", "related_terms": ["Bell direction", "Bore", "Impedance matching", "Harmonics", "Close-miking", "Directivity"], "common_mistakes": ["Believing the flare generates the pitch; pitch is set by the vibrating lips and the full air-column length, while the flare mainly affects radiation and timbre.", "Thinking a wider or longer flare simply makes an instrument louder at all frequencies, when it chiefly boosts higher-harmonic radiation.", "Miking too far inside the bell mouth and capturing an unnaturally harsh, hollow tone."], "scenario_contexts": ["Explaining why a trumpet sounds brighter and more directional than a French horn, whose bell faces backward.", "Choosing mic distance from the bell flare of a trombone to balance brightness against blare.", "Comparing the tonal effect of different bell tapers when recording brass overdubs."]}, "b7340853-82c7-4671-8097-cf0ae12cf473": {"definition": "On accordions, concertinas, bandoneons and other free-reed instruments, the opening (draw) and closing (press) of the pleated bellows that pumps air across the reeds. The direction, speed and force of the bellows movement set the air pressure driving the reeds and therefore control loudness, articulation and phrasing.", "plain_english": "Pulling open and pushing shut the folding 'lung' in the middle of an accordion. How fast and hard you move it is how you make the instrument louder, softer and expressive — it is the accordion's version of breath.", "purpose_function": "Supplies and regulates the airflow that sets the free reeds vibrating; the reeds make no sound without moving air, so the bellows is both the power source and the main dynamic and expressive control.", "practical_application": "A recordist mics the instrument to capture reed tone while managing the low-frequency air 'huff' and mechanical thumps that bellows direction changes produce, and coaches players toward consistent bellows control for even levels.", "category": "Playing Technique", "related_terms": ["Free reed", "Reed block", "Bellows shake", "Dynamics", "Air noise", "Articulation"], "common_mistakes": ["Assuming loudness comes from key pressure; on a free-reed instrument dynamics come almost entirely from bellows movement.", "Ignoring the audible air 'huff' and valve or mechanical noise at bellows direction changes when placing microphones.", "Expecting a steady tone as the bellows runs out of travel, forcing an abrupt, audible direction reversal."], "scenario_contexts": ["Recording a folk or tango accordion and positioning mics to catch reed detail without excessive bellows air noise.", "Coaching a player to plan bellows direction changes so they fall on rests rather than sustained notes.", "Capturing expressive dynamic swells produced by accelerating the bellows rather than by the keyboard."]}, "ada9395c-8100-4101-ae38-779c9c0089ce": {"definition": "A resonator-guitar bridge design in which the string saddle is mounted on a small round wooden disc — the 'biscuit,' usually maple — that sits at the apex of a single inverted (cone-down) resonator cone. String vibration passes through the saddle and biscuit into the cone, which radiates the sound.", "plain_english": "On a metal-bodied resonator guitar, a little maple button called a biscuit sits on the point of a spun-metal cone and holds the string saddle. The strings shake the biscuit, the biscuit shakes the cone, and the cone acts like a built-in speaker.", "purpose_function": "Couples string energy to the resonator cone at a single central point, defining the instrument's loud, cutting resonator tone; it is the single-cone alternative to the tricone and spider-bridge designs.", "practical_application": "A tech sets action and intonation by shaping the biscuit's saddle slot and keeps the biscuit and cone seat flat for full volume; an engineer mics the biscuit/cone area and the body to capture the characteristic metallic resonance.", "category": "Instrument Component", "related_terms": ["Resonator cone", "Spider bridge", "Tricone", "Saddle", "Coverplate", "Slide guitar"], "common_mistakes": ["Confusing the single-cone biscuit bridge with the spider bridge, which uses an aluminum spider on a cone-up resonator.", "Over-tightening the biscuit screw or leaving an uneven cone seat, which chokes the cone and kills volume and sustain.", "Filing the saddle unevenly so slide/bar action varies from string to string."], "scenario_contexts": ["Setting up a National single-cone resonator for bottleneck slide blues.", "Diagnosing lost volume traced to a warped biscuit or an uneven cone seat.", "Miking a resonator guitar and balancing the biscuit/cone spot against the coverplate holes for tone."]}, "6a58f127-5918-4897-bead-c894a8129f70": {"definition": "The practices used to minimize spill — sound from one source leaking into microphones intended for other sources — during multi-mic recording or live sound. Methods include microphone placement and spacing, directional polar patterns, physical isolation, close-miking, and downstream tools such as gates and expanders.", "plain_english": "Bleed control keeps each microphone hearing mostly its own instrument. The idea is to keep out the rest of the room. You do it with smart mic placement and directional mics. Screens, booths, and noise gates help too.", "purpose_function": "Preserves separation between tracks so each can be processed and balanced independently, and reduces the comb-filtering and phase problems that arise when the same sound reaches several mics at different times.", "practical_application": "An engineer uses directional (cardioid/figure-8) patterns aimed to null nearby sources, follows the 3:1 spacing guideline, adds gobos or isolation booths, moves loud sources apart, and applies gates only after acoustic measures are exhausted.", "category": "Recording Technique", "related_terms": ["Spill", "Polar pattern", "3:1 rule", "Comb filtering", "Gobo", "Noise gate"], "common_mistakes": ["Relying on a noise gate to fix bleed that should have been reduced acoustically first, leaving audible artifacts and gated-in spill.", "Placing mics too close together relative to their source distance, so bleed arrives with delays that cause comb filtering when summed.", "Aiming a mic's null at the wrong source, or forgetting a cardioid's limited rear rejection, so rejection is lost."], "scenario_contexts": ["Tracking a live band in one room and using gobos plus tight cardioid placement to separate the guitar amp from the drums.", "Miking a drum kit where each close mic captures neighboring drums and cymbals.", "Recording a string ensemble and managing spill between adjacent players' spot mics."]}, "5b263ea1-7077-4b95-aa93-5519d9cf0fe2": {"definition": "A low-frequency thump or percussive sound produced when the body of an acoustic stringed instrument (guitar, double bass, cello) is struck, tapped or bumped, exciting the instrument's enclosed-air and top-plate resonances. In recording it appears either as a deliberate percussive element or as unwanted contact/handling noise captured by close microphones.", "plain_english": "The dull thud you get when someone taps or knocks the wooden body of a guitar or bass. Sometimes it is played on purpose for rhythm; other times it is an accidental bump the mic picks up.", "purpose_function": "Names the transient, body-resonance sound as distinct from the strings, so a player can use it musically or an engineer can identify and control it as noise.", "practical_application": "When it is noise, an engineer reduces it with mic placement away from the striking area, shock/handling isolation and a high-pass filter; when it is intentional percussion, they position a mic to capture the body thump cleanly.", "category": "Recording Artifact", "related_terms": ["Body resonance", "Tap tone", "Handling noise", "High-pass filter", "Percussive fingerstyle", "Transient"], "common_mistakes": ["Mistaking body-knock thumps for low-string content and boosting the lows, which worsens the noise.", "Removing all low end with an over-aggressive high-pass filter and thinning the instrument's natural body warmth.", "Placing a mic right over the area the player taps, so incidental knocks overwhelm the string sound."], "scenario_contexts": ["Recording percussive fingerstyle guitar where body knocks are part of the groove.", "Cleaning up a singer-songwriter take marred by the guitar bumping the mic stand.", "Miking a double bass and separating intentional body slaps from unwanted contact noise."]}, "28b93718-6eef-43b8-ba12-6aba27ed622e": {"definition": "The downward force the bow hair applies to the string on a bowed instrument (violin, viola, cello, double bass). Together with bow speed and the bow-to-bridge distance it is one of the primary parameters controlling loudness and timbre; physicists more precisely call it 'bow force.'", "plain_english": "How hard the player presses the bow into the string. Press harder for a fuller, louder, grittier sound; press too little and the note thins out or whistles; press too much and it crushes into a scratch.", "purpose_function": "Sets the friction coupling between bow and string that sustains the string's stick-slip (Helmholtz) vibration; it is a core expressive control, balanced against bow speed and contact point to shape dynamics and tone.", "practical_application": "Players and engineers relate bow pressure to captured tone — light pressure near the fingerboard gives an airy sul-tasto sound, firm pressure near the bridge gives an edgy, harmonic-rich tone — and choose mic distance accordingly.", "category": "Playing Technique", "related_terms": ["Bow speed", "Sounding point", "Sul ponticello", "Sul tasto", "Helmholtz motion", "Timbre"], "common_mistakes": ["Treating bow pressure as the only loudness control and ignoring bow speed and contact point, producing a crushed tone.", "Using too little bow force for the chosen bridge distance, so the string never locks into stable Helmholtz motion and the tone is thin or 'surface-sounding.'", "Assuming more pressure always means more volume, when past the maximum-force limit the tone breaks up into raucous noise."], "scenario_contexts": ["A cellist adjusting pressure and sounding point to move between warm and edgy timbres during a take.", "An engineer hearing scratchy attacks and recognizing excessive bow force rather than a mic problem.", "Capturing quiet sul-tasto passages that need close miking because low bow pressure yields little level."]}, "8ba3cd8d-32cb-4bdc-a7d8-0b6ce4e8e9f6": {"definition": "The audible change in loudness (and slight change in timbre) that occurs as a bowed-string player reverses bow direction. Because a note's loudness follows bow speed, the bow decelerating to a stop and reversing at each up-bow/down-bow change causes a momentary dip in level, while down-bow and up-bow strokes also carry inherent dynamic tendencies (a down-bow near the frog naturally sounds stronger).", "plain_english": "A bow only moves one way at a time. When a violin or cello player flips the bow's direction, the sound dips for a moment and its tone can shift a little. It is like the tiny pause you hear when someone saws a board back and forth.", "purpose_function": "It is an inherent artifact of how a bow drives a string: since volume tracks bow speed, the speed passing through zero at each reversal creates a natural articulation point that players either use musically or smooth over for seamless legato.", "practical_application": "Engineers recording strings listen for these dips as uneven seams in sustained lines and address them with mic placement, comping, or gentle gain riding rather than heavy compression, which would pump the room tone.", "category": "Bowing technique", "related_terms": ["Bowing position", "Bowed-string scratchiness", "Bridge radiation", "Helmholtz motion", "Sul ponticello", "Legato"], "common_mistakes": ["Assuming up-bow and down-bow are dynamically identical, so a natural bow-change dip gets mistaken for a bad take or player error", "Reaching for heavy compression to hide bow-change dips, which pumps the room and dulls articulation instead of smoothing the line", "Ignoring bow direction when editing or comping, so splice points land on a bow-change dip and create awkward level jumps"], "scenario_contexts": ["Tracking a solo violin legato line where audible dips at each bow change need transparent gain rather than aggressive compression", "A cello section sounding uneven because down-bows land louder than up-bows on a repeated figure", "Editing a string overdub and choosing splice points that avoid a bow-change level dip"]}, "566a464d-49fe-4c33-9cbf-8e79baea2be6": {"definition": "A harsh, noisy, poorly pitched quality in bowed-string tone produced when bow force, bow speed, and distance from the bridge fall outside the range that sustains clean Helmholtz (slip-stick) string motion. It typically results from excessive bow force for the chosen bow speed and bow-to-bridge distance, which turns the note into a raucous 'crunch' rather than a clear pitch; too little force gives a thin, whistling 'surface sound' instead.", "plain_english": "The scratchy, crunchy sound a violin or cello makes when the bow is used wrong. Press too hard or drag it badly and you get noise instead of a clear, smooth note.", "purpose_function": "Recognizing it matters because it marks the boundary of playable tone described by Schelleng's bow-force limits, so its presence signals that technique, rosin, or bow position, not the microphone, is the cause.", "practical_application": "On a session an engineer hearing scratchiness first checks player technique, rosin, and bow-bridge position before suspecting the signal chain, and may move a mic slightly off-axis or further back to reduce captured bow noise.", "category": "Bowing technique", "related_terms": ["Bowing position", "Bow-direction level change", "Sul ponticello", "Helmholtz motion", "Bridge radiation", "Rosin"], "common_mistakes": ["Blaming a scratchy string recording on the mic or preamp when it is bow force or position producing surface noise", "Over-rosining the bow, which increases grip and can worsen scratch and dust artifacts", "Close-miking on-axis directly over the bridge, which exaggerates captured bow-contact scratch"], "scenario_contexts": ["A student violinist's take sounds harsh because bow force is too high for how close the bow is to the bridge", "Setting mic distance and angle on a fiddle session to tame captured bow scratch", "Diagnosing whether harshness on a string stem is a technique problem or a signal-chain fault"]}, "4b900ccb-3ad5-49c4-a4be-12226729d9ce": {"definition": "The point along the string where the bow contacts it, expressed as its distance from the bridge as a fraction of the vibrating string length. It ranges from near the bridge (sul ponticello, brighter, thinner, harmonically rich) to over the fingerboard (sul tasto, softer, rounder, fewer high harmonics), and it sets the usable minimum and maximum bow force for a clear tone.", "plain_english": "Where between the bridge and the fingerboard the player draws the bow. Closer to the bridge is brighter and edgier; over the fingerboard is softer and mellower.", "purpose_function": "It is a primary tone control for bowed strings: bow position governs harmonic content and how much bow force the string tolerates before the note breaks up or thins, so players use it for both timbre and dynamics.", "practical_application": "Engineers exploit it by asking a player to move sul tasto for a soft pad or sul ponticello for an edgy effect, and by aiming or placing mics aware that near-bridge playing radiates more high-frequency energy.", "category": "Bowing technique", "related_terms": ["Bowed-string scratchiness", "Bow-direction level change", "Bridge radiation", "Bridge area", "Helmholtz motion", "Sul ponticello"], "common_mistakes": ["Confusing bowing position (bridge-to-fingerboard contact point) with the fingering position of the left hand on the string", "Assuming closer to the bridge simply means louder, when it means brighter and demands more, better-controlled force", "Fixing mic placement without accounting for how far from the bridge the part is actually played"], "scenario_contexts": ["Directing a violinist sul tasto for a soft, airy sustained texture", "Capturing an aggressive sul ponticello effect for a film cue", "Choosing mic distance on strings where the player varies bow position across a phrase"]}, "e469482e-87dd-4994-8ce5-81e0dd7b22f9": {"definition": "The region of a stringed instrument immediately surrounding the bridge, where string vibration is transferred into the top plate or soundboard and radiated as sound. In recording it is a common microphone and pickup placement zone, and in playing, bowing or picking closer to the bridge yields a brighter, more articulate, harmonically richer tone.", "plain_english": "The part of a guitar or violin right around the bridge, the small mount the strings rest on. It is a favorite spot to point a mic, and playing near it sounds brighter and snappier.", "purpose_function": "It matters because the bridge is where string energy enters the body, making the surrounding area acoustically live, a strong and articulate source for miking and the zone where playing distance most changes brightness and attack.", "practical_application": "Engineers place or aim a mic, or clip a contact pickup, near the bridge to get a direct, attack-rich sound on acoustic guitar or upright bass, balancing it against a warmer, fuller position further from the bridge.", "category": "Instrument anatomy", "related_terms": ["Bridge radiation", "Bowing position", "Sul ponticello", "Soundboard", "Contact pickup", "Twelfth-fret miking"], "common_mistakes": ["Miking directly over the bridge or soundhole on acoustic guitar and getting a boomy, boxy tone instead of moving toward the 12th fret for balance", "Assuming the bridge area sounds the same as over the soundhole, when the two positions capture very different tonal balances", "Confusing the bridge with the nut or saddle when describing a placement"], "scenario_contexts": ["Positioning a small-diaphragm condenser near the bridge of an acoustic guitar for attack and clarity", "Clipping a contact pickup at the bridge area of an upright bass for live reinforcement", "Comparing bridge-area versus 12th-fret mic positions to dial in an acoustic guitar's brightness"]}, "987069e0-d7db-4f5a-a479-786b4f3da51b": {"definition": "The process by which a stringed instrument's bridge couples string vibration into the body and thereby into radiated sound. Driven by the string, the bridge rocks and bounces on the top plate to excite the body's radiating modes, and its own resonances create a broad 'bridge hill' response peak around 2-3 kHz that shapes brightness and presence.", "plain_english": "The bridge is the small part the strings rest on. It passes the strings' shaking into the body, which then moves the air so you can hear it. The bridge also rings a little on its own, adding brightness around 2 to 3 kHz.", "purpose_function": "It exists because strings alone move too little air to be heard; the bridge acts as a mechanical coupler and filter that transfers and colors string energy on its way to the radiating body, strongly influencing tone and projection.", "practical_application": "Knowing the bridge hill sits near 2-3 kHz helps an engineer understand where a violin's presence and edge live, guiding mic choice and gentle EQ, and explains why adding a bridge mute rolls off the highs by many decibels.", "category": "Instrument acoustics", "related_terms": ["Bridge area", "Bowing position", "Soundboard", "Bridge hill", "Helmholtz motion", "Practice mute"], "common_mistakes": ["Treating the bridge as a passive mount rather than an active, resonant coupler that colors the tone", "Assuming a heavier bridge or a mute only lowers volume, when it also strongly attenuates high frequencies", "Expecting EQ alone to fully restore the presence lost when a mute damps bridge radiation"], "scenario_contexts": ["Explaining why a muted violin loses air and edge on a recording", "Choosing a mic and a gentle EQ move that flatters the 2-3 kHz bridge-hill presence region", "Comparing two violins whose brightness differs largely because of bridge mass and setup"]}, "ccd1e1f2-d1c1-4a32-b379-dd913643b832": {"definition": "A brass-instrument mute (used on trumpet, cornet, and trombone) consisting of a cylindrical container packed with sound-absorbing material such as cotton or felt that clips onto or fits over the bell. It absorbs high frequencies to give a soft, dark, veiled tone without significantly altering pitch.", "plain_english": "A padded cup that clips over the open end of a trumpet or trombone. It makes the sound soft, warm, and far-away, like hanging a blanket in front of the horn.", "purpose_function": "It exists to darken and soften a brass instrument's timbre for mellow, subdued passages, filtering out bright high harmonics while the player still articulates normally.", "practical_application": "In tracking or live sound a bucket-muted horn is much softer and duller, so the engineer moves the mic closer or adds gain and eases off the high-frequency EQ used for an open horn.", "category": "Brass mute", "related_terms": ["Straight mute", "Cup mute", "Harmon mute", "Bell", "Timbre"], "common_mistakes": ["Confusing the bucket mute (absorbent cylinder over the bell) with a cup mute (hard cup), which sound different", "Miking a bucket-muted horn as if it were open and getting a thin, distant, low-level signal", "Assuming any mute drastically changes tuning, when the bucket mute mainly changes timbre and level"], "scenario_contexts": ["A big-band trumpet section using bucket mutes for a soft ballad backing", "Recording a muted trombone where the engineer must add gain and back off treble EQ", "Selecting among straight, cup, and bucket mutes to match a soft, dark tone brief"]}, "19636605-66ad-4f37-8040-6290cd403cf5": {"definition": "A guitar signal-chain device containing a unity-gain buffer amplifier, a stage with very high input impedance and low output impedance that copies the signal's voltage without changing its level. It isolates a high-impedance magnetic pickup from cable capacitance and following loads, preserving high-frequency content over long cables and true-bypass pedal chains.", "plain_english": "A small box that strengthens a guitar's signal without making it louder. It lowers the signal's impedance so the sound can run through long cables and many pedals without losing its bright, sparkly highs.", "purpose_function": "It exists to solve tone loss: a passive pickup has high impedance, and long cables and stacked bypassed pedals form a filter that dulls the highs, so a buffer's low output impedance drives that load cleanly and keeps the signal bright and strong.", "practical_application": "Players place a buffer near the start (and sometimes end) of a large true-bypass pedalboard, or use a pedal with a good built-in buffer, to stop the rig sounding dull, and engineers reference it when a guitar loses clarity over long runs.", "category": "Guitar electronics", "related_terms": ["Impedance", "True bypass", "DI box", "Pickup", "Signal chain", "Cable capacitance"], "common_mistakes": ["Thinking a buffer boosts volume, when it is unity gain and changes impedance, not level", "Assuming true-bypass is always best, when a long all-true-bypass chain can dull tone that a buffer would preserve", "Placing a buffer before a fuzz or vintage wah that needs to see the guitar's high impedance, changing how those effects respond"], "scenario_contexts": ["A large pedalboard sounding dull, fixed by adding a buffer to drive the cable load", "Long cable runs on a stage darkening a guitar tone", "Deciding buffer placement so a fuzz pedal still interacts properly with the pickups"]}, "d2fd5d07-95d3-4e9c-9d4c-5f4c8453c568": {"definition": "A clamp fitted across all the strings of a guitar or similar fretted instrument at a chosen fret, shortening the vibrating string length to raise the pitch of every string by the same interval. It lets a player use familiar open-string chord shapes in a higher key.", "plain_english": "A clamp that presses down all the strings at one fret. This makes the whole guitar sound higher. Now easy chord shapes work in a new key. Think of it as a spare finger laid across the neck.", "purpose_function": "It exists to transpose an instrument up in fixed semitone steps without new fingerings, keeping the ringing open-string sound in keys that would otherwise require barre chords.", "practical_application": "In the studio a capo lets a guitarist match a singer's key while keeping bright open voicings, and engineers note capo position because it shifts the instrument's register and resonances, affecting mic placement and doubling.", "category": "Guitar accessory", "related_terms": ["Fret", "Nut", "Transposition", "Barre chord", "Intonation", "Open tuning"], "common_mistakes": ["Clamping too hard or off-center behind the fret, which pulls strings sharp and causes buzzing; place it just behind the fret with minimal pressure", "Assuming a capo needs no tuning check, when fitting it can pull strings slightly sharp and require retuning", "Forgetting the capo changes the sounding key, causing transposition errors when reading chord charts"], "scenario_contexts": ["A session guitarist capoing up to keep open-chord voicings in the vocalist's key", "Doubling a part with one guitar open and another capoed for a shimmering layered sound", "Rechecking tuning right after fitting a capo before a take"]}, "39664d4a-d432-4609-accb-12660a725511": {"definition": "In an accordion, a tone chamber (Italian cassotto, literally 'little house') built into the treble side through which one or more reed banks, usually the lower 16-foot and/or 8-foot sets, sound. The chamber acts as a passive acoustic filter that attenuates high overtones, giving a warmer, rounder, more mellow timbre.", "plain_english": "A small sound box inside nicer accordions. Some of the reeds play through it. This gives a warmer, softer, less nasal tone, a bit like singing into a cupped hand.", "purpose_function": "It exists to refine tone: by enclosing certain reeds it softens their bright, reedy overtones so those registers sound rounder and more vocal, a feature prized on higher-end instruments.", "practical_application": "When miking an accordion an engineer captures a notably darker sound from the cassotto reed banks than from the brighter non-cassotto reeds, and may mic the treble side to balance the two.", "category": "Accordion", "related_terms": ["Reed block", "Register", "Timbre", "Overtone", "Bellows", "Treble side"], "common_mistakes": ["Assuming cassotto changes pitch or tuning, when it only shapes timbre and tone color", "Expecting every reed bank to sound through the chamber, when typically only the 16-foot and 8-foot banks are in cassotto", "Miking an accordion at one fixed spot and missing the tonal difference between cassotto and non-cassotto registers"], "scenario_contexts": ["Recording a jazz or musette accordionist and choosing cassotto registers for a warm solo tone", "Balancing mics across the treble side to blend cassotto and non-cassotto reeds", "Explaining why a premium accordion sounds mellower than an entry-level one"]}, "79de6e06-44f4-4759-9068-acd303956e35": {"definition": "A humbucker wiring option that disconnects (typically shunts to ground) one of the pickup's two coils, leaving a single coil active. This produces a brighter, lower-output tone closer to a true single-coil, at the cost of the humbucker's hum cancellation.", "plain_english": "A switch that shuts off one half of a two-coil (humbucker) pickup. With half turned off, the sound gets thinner and brighter, like a single-coil pickup.", "purpose_function": "Gives one guitar two voices — full humbucker or brighter single-coil-like tone — from a single pickup, widening tonal range without swapping pickups.", "practical_application": "A tech wires a push-pull pot or mini-toggle so activating it shunts one coil to ground; when tracking, the engineer selects the split setting for a cleaner, glassier rhythm tone.", "category": "Guitar electronics", "related_terms": ["Coil tap", "Humbucker", "Single-coil pickup", "Push-pull potentiometer", "Series/parallel wiring"], "common_mistakes": ["Confusing coil split with coil tap — splitting disables one whole coil of a humbucker, while tapping accesses a partial winding of a single coil.", "Expecting a split humbucker to sound identical to a genuine single-coil; it is lower output and no longer hum-cancelling.", "Forgetting to reconnect the coil-link/ground lead during the mod, leaving the pickup noisy or dead."], "scenario_contexts": ["Wiring a push-pull tone pot on a Les Paul so each humbucker can be split for cleaner rhythm parts.", "Recording a rhythm layer where a brighter, thinner tone cuts through a dense mix.", "A player using split mode for clean/funk passages and full humbucker for lead."]}, "3ca2fbb6-85f3-480b-a3fb-e2a056c53707": {"definition": "A pickup construction/wiring method in which an extra lead is connected to an intermediate point in a single coil's winding, allowing selection between the full number of turns (higher output, darker) and the tapped, partial winding (fewer turns, lower output, brighter). It is distinct from coil splitting, which disables one coil of a humbucker.", "plain_english": "A pickup with an extra wire joined partway along its coil. It lets you switch between full power and a lower, brighter setting.", "purpose_function": "Lets one pickup offer two output levels and voicings — a hotter modern sound and a lower-output vintage-like sound — from a single coil.", "practical_application": "A tech connects the pickup's tap lead to a switch (often a push-pull pot); an engineer chooses the tapped setting for cleaner headroom or a brighter, vintage-flavoured track.", "category": "Guitar electronics", "related_terms": ["Coil split", "Single-coil pickup", "Humbucker", "Push-pull potentiometer", "Pickup output"], "common_mistakes": ["Using 'coil tap' and 'coil split' interchangeably — they are electrically different.", "Expecting a dramatic change; tapping mainly reduces output/turns, a subtler shift than splitting.", "Assuming any pickup can be tapped — only pickups wound with a tap lead support it."], "scenario_contexts": ["Selecting a tapped setting to reduce a hot pickup's output for a cleaner amp tone.", "Wiring a switchable tap for two distinct output levels.", "Blending a tapped, brighter tone into a layered rhythm track."]}, "beda4548-e14f-4558-ae5f-4f2faa238b82": {"definition": "A bowed-string playing technique in which the player uses the wooden stick of the bow on the strings instead of the hair. Two forms exist: col legno battuto (striking the string with the stick for a percussive, dry attack) and the rarer col legno tratto (drawing the wood across the string for a thin, glassy sustained sound).", "plain_english": "Playing a string instrument with the wooden stick of the bow, not the hair. You tap or drag the wood on the strings. This gives a dry, clicky, spooky sound.", "purpose_function": "Provides a distinctive percussive/colouristic string effect used for special orchestral and film-score textures.", "practical_application": "When miking strings for a col legno passage, a technician uses a close mic to capture the quiet wood-on-string transient that a distant room mic would miss.", "category": "Bowing technique", "related_terms": ["Pizzicato", "Sul ponticello", "Spiccato", "Arco", "Con sordino"], "common_mistakes": ["Assuming col legno always means striking (battuto); tratto (drawn wood) is a separate, sustained variant.", "Over-worrying bow damage — many players use a secondary bow, but light battuto on a normal bow is standard practice.", "Under-miking the effect; its low level and sharp transient need close, careful gain staging."], "scenario_contexts": ["Recording a horror or suspense film cue calling for eerie col legno strings.", "A section playing col legno battuto for a rhythmic, percussive passage.", "Close-miking a solo cello to catch the subtle wood-on-string attack."]}, "043d3420-746e-4e65-8a4a-69ef9d45fdde": {"definition": "On an instrument with paired or grouped strings (a course), an unevenness between the strings of the same course in loudness, tuning, tone, or string age, so the pair no longer sounds as one unified note. It commonly appears on 12-string guitars, mandolins, and lutes.", "plain_english": "On instruments where strings come in pairs, it is when the two strings of a pair do not match. One may be louder or slightly out of tune, so the pair sounds uneven.", "purpose_function": "The term flags a specific fault so it can be diagnosed and corrected; a balanced course produces the rich, chorused sound that paired strings are meant to give.", "practical_application": "A tech listens for beating or a weak string within each course and fixes it by tuning both strings precisely, matching string gauges, or replacing a dead string before tracking.", "category": "String balance", "related_terms": ["Open string", "Drop tuning", "Dry tuning", "Bass-string section"], "common_mistakes": ["Tuning only the main string of a course and ignoring its octave or unison partner", "Blaming the room or mic for a beating, uneven sound that is really a course imbalance", "Mixing a fresh string with a worn one in the same course, causing a tone and volume mismatch"], "scenario_contexts": ["Prepping a 12-string guitar before recording so each pair rings evenly", "Diagnosing a beating, phasey chord on a mandolin during tracking", "Checking octave-pair balance after changing one broken string"]}, "89ad30e5-ee21-4749-9ed4-f98c573ec9e3": {"definition": "A brass mute consisting of a straight-mute-like cone with an added cup that partly covers the bell of a trumpet, trombone, or similar instrument. It attenuates and rounds the tone, reducing upper harmonics to give a soft, muffled, mellow timbre darker than a straight mute.", "plain_english": "A cup-shaped mute that fits over the bell of a trumpet or trombone to make it sound soft, muffled and mellow.", "purpose_function": "Shapes brass timbre and lowers level for blended, subdued passages, common in jazz and big-band writing.", "practical_application": "For a cup-muted horn, a technician may move the mic slightly off the bell axis and raise gain, since the mute both lowers output and darkens the tone.", "category": "Brass mute", "related_terms": ["Straight mute", "Harmon mute", "Plunger mute", "Con sordino", "Bell (brass)"], "common_mistakes": ["Confusing a cup mute with a straight mute; the cup adds a covering that darkens the sound further.", "Miking a cup-muted horn as if it were open, then over-compensating for the lower, duller output.", "Assuming all cup mutes are fixed — some have adjustable cups for varying the muffling."], "scenario_contexts": ["Recording a big-band trumpet section written for cup mutes on a soft ballad.", "A trombonist switching to cup mute for a mellow backing figure.", "Setting mic gain for the reduced output of cup-muted brass."]}, "b9df23a3-f6e8-4b8f-aed8-c8e5f2b26618": {"definition": "On a tonewheel (Hammond-type) organ, the set of sliding controls — typically nine per manual — that adjust the loudness of individual harmonic partials, labelled by organ-pipe footages (e.g., 16', 8', 4', 2 2/3'). Drawing bars out mixes these partials in an additive-synthesis fashion to build the instrument's timbre.", "plain_english": "The sliders on a Hammond organ. Each one adds a different overtone to the sound. You mix them like faders to shape the tone you want.", "purpose_function": "Give the player real-time additive control of tone colour by setting the balance of harmonics, from a pure flute-like tone to a full, bright registration.", "practical_application": "When recording organ, an engineer notes the drawbar registration (e.g., 888000000) for recall and may re-voice the drawbars to fit the track rather than EQ heavily.", "category": "Organ controls", "related_terms": ["Tonewheel", "Leslie speaker", "Additive synthesis", "Registration", "Hammond percussion"], "common_mistakes": ["Thinking drawbars are overall volume/EQ rather than level controls for individual harmonics.", "Reading footage labels (16', 8', 4') as pure octaves while ignoring the 2 2/3' and 1 3/5' mutation ranks that add non-octave harmonics.", "Failing to log drawbar settings, then being unable to reproduce a registration on overdub."], "scenario_contexts": ["Dialing an 888000000 setting for a classic jazz organ tone.", "Documenting a Hammond registration for later overdubs.", "Adjusting drawbars instead of channel EQ to change organ brightness at the source."]}, "9634cf1e-ba20-4f70-ac1c-08c2168628ee": {"definition": "A guitar or bass tuning in which one or more strings are lowered below standard pitch, most commonly the lowest string. In Drop D the 6th string is lowered a whole tone from E to D, giving a low root and one-finger power chords on the bottom three strings; deeper variants (Drop C, Drop B) transpose the whole set down and then drop the 6th.", "plain_english": "Tuning a guitar's lowest string down to a lower pitch. Sometimes you drop all the strings. This gives a heavier, deeper sound and easy power chords.", "purpose_function": "Extends the instrument's low range and simplifies power-chord fingering, central to hard rock and metal styles.", "practical_application": "A tech sets up a guitar for drop tuning with heavier-gauge strings plus truss-rod and intonation adjustment so the slackened strings stay stable and in tune.", "category": "Guitar tuning", "related_terms": ["Standard tuning", "Drop D", "String gauge", "Intonation", "Guitar setup"], "common_mistakes": ["Dropping to low tunings on light strings, causing floppy tension, poor intonation and fret buzz.", "Skipping re-intonation and setup after a large tuning change.", "Confusing Drop D (only the 6th string lowered) with a full-step-down tuning (all strings lowered)."], "scenario_contexts": ["Setting up a metal player's guitar in Drop C with heavier strings.", "Retuning to Drop D for a single song's low riff.", "Tracking a heavy rhythm part built on drop-tuned power chords."]}, "a2350ff2-5f22-46f0-a22d-7992442b1619": {"definition": "In accordion and related free-reed instruments, a tuning in which the multiple reeds sounding a given note are set in strict unison (and octaves) with no deliberate offset, producing a clean tone with little or no tremolo beating. It contrasts with wet (musette) tuning, where reeds are intentionally detuned to create a beating, shimmering tremolo.", "plain_english": "An accordion setup where each pair of reeds is tuned to the exact same pitch. The sound comes out clean and steady, with no wobble.", "purpose_function": "Gives a straight, focused tone favoured in jazz, classical and some folk styles, avoiding the wavering tremolo of wet tuning.", "practical_application": "When recording a dry-tuned accordion, an engineer captures a stable, non-warbling tone that sits cleanly in a mix without the chorus-like movement of a wet instrument.", "category": "Reed tuning", "related_terms": ["Wet tuning", "Musette", "Free reed", "Beating (acoustics)", "Tremolo"], "common_mistakes": ["Assuming every accordion has the wavery 'musette' sound; dry-tuned instruments are deliberately beat-free.", "Confusing dry/wet reed tuning with added studio effects such as chorus or detune.", "Trying to 'fix' the tremolo with EQ — it is built into the reed tuning, not the frequency balance."], "scenario_contexts": ["Recording a jazz accordionist who prefers a clean, dry-tuned tone.", "Choosing a dry-tuned instrument to blend with a tightly tuned ensemble.", "A tuner setting reeds in unison for a dry registration."]}, "58bcf038-87c9-4191-89a6-d707b1644b54": {"definition": "A violin that produces its output primarily through electronic pickups (commonly piezoelectric transducers at the bridge, or magnetic systems) rather than an acoustic resonating body. Many are solid-body with minimal acoustic output, requiring amplification; some add extra strings (5-, 6-, or 7-string) to extend the range downward.", "plain_english": "A violin that is quiet on its own. A pickup turns its shaking into a signal, which you send to an amp. Think of it as the electric-guitar version of a violin.", "purpose_function": "Allows loud amplified performance without acoustic feedback and easy connection to effects, mixers and recording gear.", "practical_application": "A technician takes the electric violin's output through a preamp/DI into a console or interface, and often adds reverb or effects since the raw solid-body signal is dry and direct.", "category": "Electric strings", "related_terms": ["Piezoelectric pickup", "Direct box (DI)", "Preamp", "Solid-body", "Five-string violin"], "common_mistakes": ["Plugging a high-impedance piezo output straight into a low-impedance mic/line input, loading the pickup and thinning the tone — use a proper high-impedance preamp/DI.", "Expecting an acoustic violin tone from a bare solid-body signal, which is dry and needs reverb/EQ.", "Assuming electric (solid-body) and electro-acoustic (acoustic with a fitted pickup) violins are the same thing."], "scenario_contexts": ["DI'ing a solid-body electric violin into an interface for a pop session.", "Amplifying a violinist on a loud stage without acoustic feedback.", "Adding effects to an electric violin for a film or electronic production."]}, "14eeb028-525f-4523-bf2f-327e41bae6eb": {"definition": "A control input, wired as a 1/4-inch TRS (tip-ring-sleeve) jack, that reads the position of a passive expression pedal by treating the pedal's internal potentiometer as a variable voltage divider; the host device supplies a reference voltage on one conductor and measures the wiper voltage returned on another to derive a continuous control value.", "plain_english": "A jack on a pedal, amp, or keyboard for a rocking foot pedal. Rock it with your foot to sweep an effect like volume or wah, hands-free. It works like a dimmer switch for a light.", "purpose_function": "It gives a musician continuous, real-time foot control over a parameter (volume, wah, filter, delay mix) so both hands stay on the instrument; it exists because performers need to shape effects live while playing.", "practical_application": "A technician patches an expression pedal to this jack with a TRS cable (a mono TS cable will not work) and confirms the pedal's polarity, resistance, and minimum setting match the host so the full sweep is usable.", "category": "Control interface", "related_terms": ["Volume pedal", "Wah-wah pedal", "TRS connector", "Potentiometer", "MIDI continuous controller", "Control voltage"], "common_mistakes": ["Using a mono TS instrument cable instead of a TRS cable, so the pedal reads no sweep or sticks at one value", "Assuming any expression pedal fits any device when pedal resistance/taper and polarity must match the host", "Confusing an expression-pedal input with a latching or momentary footswitch input", "Leaving the pedal's MIN/heel setting wrong so part of the sweep does nothing"], "scenario_contexts": ["Assigning a floor multi-effects unit's expression pedal to sweep delay feedback during a solo", "Wiring a keyboard's EXP jack to control filter cutoff live", "Troubleshooting a dead expression pedal that turns out to be connected with a TS cable"]}, "2e5eb236-5ddf-4175-83f9-e046c9e26ad6": {"definition": "The sound radiated outward through the f-shaped openings in the top plate of violin-family instruments and archtop guitars; near the instrument's main air (Helmholtz-type) resonance the enclosed air pumps in and out through these holes, so the f-holes act as the acoustic ports that couple the body cavity's low-frequency output to the surrounding air.", "plain_english": "The f-shaped slots on a violin or archtop guitar are not just for looks. Much of the low, deep sound escapes through them. They act like the port hole on a speaker cabinet.", "purpose_function": "The f-holes let the body's internal air resonance radiate efficiently, reinforcing the instrument's lower register; their elongated shape concentrates air motion along the long edges, which radiates that resonance more effectively than a round hole of equal area.", "practical_application": "When close-miking a violin, cello, or archtop, an engineer accounts for the strong low-frequency energy emerging from the f-holes and avoids aiming a mic straight into one, which over-emphasizes boxy low-mids and captures airflow noise.", "category": "Instrument acoustics", "related_terms": ["Helmholtz resonance", "Guitar body resonance", "Sound hole", "Main air resonance", "Close miking", "Proximity effect"], "common_mistakes": ["Placing the microphone directly over an f-hole, capturing a boomy, unrepresentative low-mid buildup", "Believing the f-holes mainly radiate high frequencies when they dominate the low-frequency air resonance", "Assuming the f-holes and the vibrating top plate radiate the same spectrum"], "scenario_contexts": ["Choosing mic distance and angle for a cello where f-hole output boosts the low register", "Recording an archtop jazz guitar acoustically and balancing f-hole versus top-plate radiation", "Explaining why a violin sounds boxy when a clip-on mic sits too close to an f-hole"]}, "23d7f1d2-9137-4004-811f-df5015010c7a": {"definition": "The onset transient of a note plucked with the fingertip, flesh, or fingernail rather than a pick; because the finger is a wider, softer, more compliant exciter, it releases the string more gradually and excites fewer strong high harmonics, giving a rounder, less percussive attack than a hard, narrow plectrum.", "plain_english": "How the start of a note sounds when you pluck a string with your finger, not a pick. It is usually softer and warmer. You lose the sharp click that a pick gives.", "purpose_function": "It describes a core tonal and dynamic characteristic the player controls with the picking hand; understanding it lets engineers and players predict a note's transient content and dynamic range.", "practical_application": "When tracking fingerstyle guitar or bass, an engineer chooses gentler compression settings and mic placement to preserve the softer transient and expects more level variation between fingers than with a pick.", "category": "Playing technique", "related_terms": ["Attack (envelope)", "Transient", "Plectrum", "Pick attack", "Compression", "Palm muting"], "common_mistakes": ["Over-compressing fingerstyle takes with a very fast attack, flattening the natural dynamic swells that define the style", "Assuming fingerstyle always means quieter or duller when nail attack can be very bright and percussive", "Confusing the attack (onset transient) with the sustain when describing tone"], "scenario_contexts": ["Recording a fingerpicked acoustic ballad where soft attacks must stay intact", "Comparing DI tones for pick versus fingerstyle bass in a mix", "Coaching a player to use nails versus flesh to change the brightness of the attack"]}, "8715c831-bba4-4b92-a629-8bfa46db5e5c": {"definition": "An organ pipe that produces sound by aerodynamic (air-jet) excitation rather than a vibrating reed: pressurized wind is forced through a narrow slit called the flue or windway to form a thin air sheet that strikes the sharp upper lip of the pipe's mouth, and the resulting oscillating jet drives the standing wave in the pipe's air column, the same mechanism as a recorder or whistle.", "plain_english": "The most common kind of organ pipe. Air blows across a sharp edge and makes the pipe sing, like a whistle or a recorder. Reed pipes are different, since they buzz a metal tongue.", "purpose_function": "Flue pipes generate the organ's principal, flute, and string tone colors; the pipe length sets the pitch while the mouth and jet geometry and the pipe scaling set the timbre and harmonic content.", "practical_application": "When recording a pipe organ, an engineer positions mics to capture the blend of flue pipes across a division and manages the initial chiff transient and the strong low-frequency fundamentals of large flue ranks.", "category": "Instrument acoustics", "related_terms": ["Reed pipe", "Edge tone", "Standing wave", "Air column resonance", "Helmholtz resonance", "Organ rank"], "common_mistakes": ["Thinking all organ pipes contain a vibrating reed when flue pipes have no reed at all", "Assuming a flue pipe's pitch comes from the jet speed rather than the resonant length of the air column", "Confusing the chiff (attack transient) with a fault"], "scenario_contexts": ["Miking a church pipe organ and balancing flue versus reed stops", "Explaining why a Principal or Flute stop speaks like a whistle", "Managing the initial chiff transient when recording flue ranks"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"a655c256-3701-4306-8fa2-318423ab81a1": {"definition": "The set of coupled mechanical and air resonances of an acoustic guitar's body that amplify and color the strings' vibration; the lowest is the main air (Helmholtz-type) resonance formed by the air mass in the soundhole coupling to the cavity's compliance (commonly near 90 to 110 Hz), followed by the main top-plate (soundboard) resonance and higher body modes.", "plain_english": "The notes where a guitar's hollow body rings the most on its own. The wooden box and the air inside it boom at these pitches. This gives an acoustic guitar its warmth and deep low end.", "purpose_function": "These resonances turn the strings' tiny motion into radiated sound and shape the instrument's low-end response and projection; they exist because the body and enclosed air act as coupled resonators driven through the bridge.", "practical_application": "Engineers use body resonance to guide mic placement, aiming near the 12th fret rather than straight at the soundhole to avoid the boomy main-air peak, and may notch it with EQ when it dominates the low-mids.", "category": "Instrument acoustics", "related_terms": ["Helmholtz resonance", "F-hole radiation", "Soundboard", "Main air resonance", "Sound hole", "Wolf note"], "common_mistakes": ["Miking straight into the soundhole and capturing an unbalanced, boomy main-air resonance", "Assuming the body resonance is a single frequency rather than several coupled modes", "Cutting the low end broadly with EQ instead of notching the specific resonant peak"], "scenario_contexts": ["Positioning a small-diaphragm condenser off the 12th fret to tame the body resonance", "Diagnosing a boomy note on a dreadnought during tracking", "Explaining why a guitar sounds boxy in a small room near its air-resonance frequency"]}, "dc9356df-837c-460d-a202-80d62561b52c": {"definition": "A passive treble-cut control on an electric or electro-acoustic guitar consisting of a potentiometer in series with a fixed capacitor, wired to shunt the high-frequency portion of the pickup signal to ground; rolling the control down lets more treble bleed away, forming a variable low-pass filter that darkens the tone.", "plain_english": "The knob that makes a guitar sound warmer or duller. Turn it down and it bleeds off the bright, high part of the sound. What is left is a rounder, softer tone.", "purpose_function": "It lets a player tailor brightness at the instrument without changing volume; it exists so the tone can be softened for rhythm, jazz, or lead sounds directly from the guitar.", "practical_application": "A tech verifies the tone pot and capacitor by ear and meter, knowing a smaller cap cuts less treble and a larger one darkens more, and checks for a scratchy pot or failed cap that leaves the control ineffective; typical values are 250k pots with single-coils, 500k with humbuckers, and tone caps around 0.022 to 0.047 microfarads.", "category": "Guitar electronics", "related_terms": ["Guitar volume control", "Potentiometer", "Capacitor", "Low-pass filter", "Pickup", "Treble bleed"], "common_mistakes": ["Assuming the passive tone control can add treble when it can only remove it", "Thinking pot value does not matter, when 250k versus 500k noticeably changes brightness", "Blaming the amp for a dull sound when a rolled-off or faulty tone control is the cause", "Confusing a scratchy (dirty) tone pot with a wiring fault"], "scenario_contexts": ["Rolling the tone down for a warm jazz archtop sound", "Servicing a guitar whose tone knob does nothing because the tone capacitor has failed", "Choosing a tone-cap value when rewiring a guitar for a darker or brighter response"]}, "7ecb3c1b-893b-4cf0-a09c-f60b6d89e4d2": {"definition": "A potentiometer on the guitar wired as a variable voltage divider between the pickup's hot output and ground, with the wiper feeding the output jack; it sets how much of the pickup signal reaches the output, from full level to silence.", "plain_english": "The guitar's volume knob. It drains off part of the pickup's signal to control how loud the guitar is. So you can turn the guitar up or down without touching the amp.", "purpose_function": "It gives the player level control at the instrument for swells, for cleaning up an overdriven amp, and for quick muting; it exists so dynamics and gain can be managed from the guitar itself.", "practical_application": "A tech chooses an audio (logarithmic) taper so the sweep sounds even and knows that rolling the volume down can also dull the highs because of cable capacitance, which is why players fit treble-bleed networks; scratchy pots are cleaned or replaced.", "category": "Guitar electronics", "related_terms": ["Guitar tone control", "Potentiometer", "Pickup", "Audio taper", "Treble bleed", "Output jack"], "common_mistakes": ["Fitting a linear-taper pot where an audio taper is wanted, so most of the level change crowds into a small part of the rotation", "Not realizing that lowering the volume can also roll off treble due to cable and load capacitance", "Assuming a dead output is the pickup when a failed volume pot or jack is the cause"], "scenario_contexts": ["Using volume swells for pad-like guitar parts", "Backing the guitar volume off to clean up an overdriven amp", "Replacing a crackling volume pot during a setup"]}, "4e3bc4fb-f2ac-4b99-84c2-356ef343de6f": {"definition": "The practice of wrapping a hand around the grille or head of a handheld microphone; the cupped hand blocks the rear and side ports that give a directional (cardioid) mic its pattern, pushing it toward omnidirectional, and forms a small resonant cavity that boosts a midrange peak, together sharply increasing feedback and coloring the sound.", "plain_english": "Wrapping your hand around the ball of a mic. It ruins the way the mic aims and adds a honky ring. That is why it makes live sound squeal with feedback.", "purpose_function": "It is mainly described as a fault to avoid, because a directional mic relies on unobstructed rear and side ports; some players such as blues-harp performers cup deliberately for a lo-fi tone, but it trades away feedback rejection and neutral response.", "practical_application": "A live engineer coaches performers not to cup the grille, since it collapses the polar pattern and lowers the gain available before feedback, and recognizes the resulting boxy midrange as a cause of ringing on a vocal mic.", "category": "Microphone technique", "related_terms": ["Cardioid pattern", "Polar pattern", "Feedback", "Proximity effect", "Handheld microphone", "Gain before feedback"], "common_mistakes": ["UNSAFE: Cupping the grille on a loud stage, which collapses the mic's directional pattern and can trigger sudden feedback and hazardous SPL spikes through the PA", "Believing cupping makes the mic louder or warmer with no downside", "Blaming the mixer for feedback when a cupped mic caused it", "Cupping a mic and expecting its rated directional pattern to hold"], "scenario_contexts": ["A singer cups the mic and the stage monitors immediately ring with feedback", "A blues harmonica player cups the mic and harp for a gritty tone while the engineer manages feedback", "Explaining to a guest speaker why holding the mic head degrades intelligibility"]}, "03ea5989-5136-4521-974b-6ecf8628e99e": {"definition": "A hollow metal (typically aluminum) mute for trumpet or trombone that seals the entire bell opening with a ring of cork so all of the player's air is forced through the mute; it has a central tube or stem that can be pulled out or left in, and, especially with the stem removed, produces a thin, buzzy, distant timbre rich in upper harmonics, with a wah-wah effect available by opening and closing the hand over the stem cup.", "plain_english": "A metal cup that plugs a trumpet's open end, made famous by Miles Davis. It gives a small, buzzy, far-away sound. Cover and uncover its little tube with your hand to make the classic wah.", "purpose_function": "It transforms the instrument's tone into a quiet, focused, harmonically bright color used heavily in jazz and film scoring; the cork seal and stem act as an acoustic filter that suppresses the fundamental and emphasizes the upper harmonics.", "practical_application": "Because a Harmon-muted trumpet is quiet and highly directional, an engineer close-mics it, often just off the axis of the stem, and may add gain and gentle EQ while watching for the piercing high-harmonic wah peaks.", "category": "Instrument mutes", "related_terms": ["Straight mute", "Cup mute", "Plunger mute", "Brass instrument", "Close miking", "Timbre"], "common_mistakes": ["Confusing the Harmon (metal, cork-sealed, wah-wah) mute with a straight or cup mute", "Recording it from a distance when the muted level is low and needs close miking", "Forgetting the stem can be removed or adjusted, which changes the tone substantially", "Assuming the mute mainly lowers volume rather than reshaping the harmonic spectrum"], "scenario_contexts": ["Miking a jazz trumpet using a stemless Harmon mute for an intimate ballad", "A brass section using Harmon mutes with hand wah for a big-band effect", "Adjusting gain and EQ for the quiet, bright output of a Harmon-muted trumpet"]}, "62e5b204-6017-4914-89bf-bf4d9c66b66f": {"definition": "A harp glissando is a rapid sweep of the fingers across successive strings, sounding a run of adjacent notes; on a concert (pedal) harp the seven pedals are pre-set — often using enharmonic equivalents — so the swept strings sound a chosen scale or chord rather than every chromatic pitch.", "plain_english": "It's the shiny sweep of sound you make by dragging your fingers across the harp strings. The harp player sets the foot pedals first. That way the whoosh lands on the right notes.", "purpose_function": "It produces the harp's signature cascading, arpeggiated texture and lets a player sound the notes of a whole scale or chord almost instantly, an idiomatic gesture made possible by the pedal mechanism.", "practical_application": "When recording it, an engineer captures the full sweep from the low to the high strings, watching level and stereo image so the run reads clearly and the soundboard's low-end bloom stays balanced against the string attack.", "category": "Playing technique", "related_terms": ["Harp soundboard", "Leakage", "Stereo miking", "Room microphone", "Transient response"], "common_mistakes": ["Assuming the harpist can play any scale in a glissando on demand; the sounding pitches are fixed by the current pedal settings, so the wrong pedal setup gives the wrong glissando.", "Miking only the top of the harp and missing the low strings and soundboard, so the sweep sounds thin and loses its bloom.", "Applying a gate or heavy noise reduction that chops the natural decay and mechanism resonance which make the gliss sound continuous."], "scenario_contexts": ["Tracking a solo pedal harp for a film score where the composer has notated specific glissando chords.", "Overdubbing a harp glissando as a transitional sweep effect in a pop production.", "Recording an orchestral session where the harp's glissandi must sit within the string section without excessive bleed."]}, "662109a5-5736-4c76-b22a-d8bbfba10b68": {"definition": "The harp soundboard is the thin resonating wooden panel forming the front face of the harp's body, to which the lower ends of the strings are anchored; it transforms the strings' vibration into radiated sound and largely shapes the instrument's tone and projection.", "plain_english": "It's the flat wooden front of the harp, and the strings pull against it. Like the top of a guitar, it turns the shaking strings into the sound you hear.", "purpose_function": "By coupling the strings to a large radiating surface, the soundboard amplifies and colors the string vibrations, giving the harp its loudness and characteristic warm resonance.", "practical_application": "Because most of the harp's radiated low end and body comes off the soundboard, engineers often aim one microphone toward the lower soundboard for warmth while a second mic nearer the strings captures attack and detail.", "category": "Instrument acoustics", "related_terms": ["Harp glissando", "Resonance", "Microphone placement", "Proximity effect", "Room microphone"], "common_mistakes": ["Treating the soundboard like a guitar's soundhole and expecting one 'sweet spot'; the harp radiates over a large area, so a single close mic rarely captures the whole instrument.", "Placing a mic so close to the soundboard that proximity effect and mechanical/pedal noise dominate over the strings.", "Ignoring the low-frequency bloom from the soundbox, producing a boxy or boomy recording."], "scenario_contexts": ["Choosing mic distance so the soundboard's low-end resonance is captured without becoming boomy.", "Explaining to a student why the harp needs open space around its back and soundbox to project.", "Diagnosing a thin harp recording that under-captured the soundboard's radiation."]}, "278f2cc2-26cd-4f15-ba2f-5047ae1c6334": {"definition": "The output of a passive electric guitar or bass (magnetic pickups, no onboard preamp) is a high-impedance, unbalanced signal whose source impedance is high and frequency-dependent, so it requires a high-impedance load — typically around 1 MΩ — to avoid loading down the pickup and rolling off high frequencies.", "plain_english": "A normal electric guitar sends out a weak, fussy signal. It needs a jack with very high resistance. Plug it into the wrong low-resistance jack and it sounds dull and quiet.", "purpose_function": "Passive magnetic pickups are inductive sources, so a high-impedance interface preserves their level and tone, which is why guitar amps and instrument/DI inputs present roughly 1 MΩ.", "practical_application": "A technician routes a passive guitar into a Hi-Z instrument input or a DI box rather than a mic or line input, keeps the unbalanced cable short to limit noise and high-frequency loss, then lets the DI convert it to a balanced low-impedance feed.", "category": "Signal I/O", "related_terms": ["Instrument direct output", "Instrument line output", "Impedance", "DI box", "Pickup"], "common_mistakes": ["Plugging a passive guitar into a low-impedance mic or line input, which loads the pickup and dulls and weakens the tone.", "Running a long unbalanced guitar cable to the console; high-impedance signals pick up noise and lose highs over distance, so keep the run short (roughly under 8 m / 25 ft).", "Assuming a guitar's output is line level; it is instrument level and far lower, so it needs preamp gain."], "scenario_contexts": ["Deciding whether a guitar can go straight into an interface's instrument/Hi-Z input or needs a DI.", "Troubleshooting a dull, low guitar signal traced to a low-impedance input.", "Setting up a long cable run from a passive bass to front-of-house through a DI box."]}, "2e113362-d1d4-4e3e-a9c8-1b0142b6dbc9": {"definition": "An instrument direct output (direct/DI output) is a feed that sends an instrument's signal straight to a mixer, interface or recorder — typically via a direct box that converts the unbalanced, high-impedance instrument signal to a balanced, low-impedance mic-level signal — instead of, or alongside, miking an amplifier.", "plain_english": "It's a way to plug an instrument straight into the mixing desk with no mic. A small box reshapes the signal. Then it can travel far without picking up noise.", "purpose_function": "It captures a clean, hum-resistant version of the instrument and lets the signal run long distances (up to about 100 m / 300 ft) without adding appreciable noise, and it can split the signal to feed both an amp and the console.", "practical_application": "On stage or in the studio a tech plugs the bass, acoustic guitar or keyboard into a DI, sends the balanced XLR to the console for a clean channel, and optionally uses the DI's thru jack to also feed the player's amp.", "category": "Signal I/O", "related_terms": ["High-impedance guitar output", "Instrument line output", "DI box", "Balanced signal", "Ground lift"], "common_mistakes": ["Confusing a DI/direct output (balanced, mic level) with a line output; plugging it into a line input yields a very low signal.", "Assuming a passive DI boosts the signal; it converts impedance and balance but adds no gain, so the console preamp still supplies the gain.", "Overdriving a passive DI's transformer with a hot active source and clipping it instead of engaging the input pad."], "scenario_contexts": ["Recording DI bass alongside a miked cabinet for re-amping flexibility.", "Sending an acoustic guitar's pickup to front-of-house through a DI on a live stage.", "Splitting a keyboard so a clean DI feed goes to the console and a second feed goes to a stage amp."]}, "c7b3d09b-1208-4452-988f-33c323187235": {"definition": "An instrument headphone output is a headphone-amplifier jack on an instrument amp, modeler, preamp or interface that drives a pair of headphones for private monitoring; inserting a plug typically mutes the built-in speaker so the player can practice or track silently.", "plain_english": "It's the headphone socket on a practice amp. Plug in and the speaker usually goes quiet. So you can play without bugging anyone.", "purpose_function": "It lets a player hear their instrument — often with amp and effects modeling — at any level without acoustic output from a speaker, and it provides a convenient monitor feed when recording.", "practical_application": "A tech uses it for silent practice or as a scratch monitor while tracking a DI, setting a safe level for the headphones and confirming the speaker mutes so nothing bleeds into the room during a take.", "category": "Signal I/O", "related_terms": ["Instrument line output", "Instrument direct output", "Monitor mix", "Amp modeling", "Leakage"], "common_mistakes": ["UNSAFE: monitoring at high headphone levels for extended periods, which risks permanent hearing damage; keep levels conservative and take breaks in line with hearing-conservation practice.", "Using the headphone out as a line or DI feed to a console; its level and impedance differ from a line output and can add noise or a mismatched level.", "Assuming every headphone jack mutes the amp's speaker; on some devices it does not, so unwanted sound bleeds into takes."], "scenario_contexts": ["Silent late-night practice on a modeling amp through headphones.", "Using an amp modeler's headphone out as a quick monitor while tracking a DI signal.", "Confirming the speaker mutes when headphones are inserted so nothing bleeds into an open microphone."]}, "7cf836f9-dfe6-4e30-b231-559135445ac7": {"definition": "An instrument line output is a jack that provides a device's signal at nominal line level — professional +4 dBu or consumer -10 dBV — for connection to a mixer or interface line input, as distinct from an instrument-level, speaker-level or headphone output.", "plain_english": "It's the 'line out' that sends a full-strength signal, ready to record. It goes to a mixer or an interface. This is much stronger than the weak signal a guitar puts out.", "purpose_function": "It delivers a standardized, higher-level signal so the receiving line input needs little or no added gain, giving a clean, low-noise interconnection between pieces of gear.", "practical_application": "A tech patches an amp modeler's or preamp's line output into a console or interface line input, matching +4 dBu versus -10 dBV levels so the signal is neither too hot nor too quiet, rather than using an instrument or mic input.", "category": "Signal I/O", "related_terms": ["High-impedance guitar output", "Instrument direct output", "Left/mono output", "Line level", "Impedance"], "common_mistakes": ["Plugging a line output into a mic input, overloading the preamp and distorting; use a line input or a pad.", "Ignoring the +4 dBu versus -10 dBV difference, so the level ends up too low (noisy) or too hot (clipping).", "Treating a line output as a high-impedance instrument output and expecting guitar-amp tone from it."], "scenario_contexts": ["Connecting an amp modeler's line out to an interface for a clean, DI-style record.", "Matching a -10 dBV instrument line output to a +4 dBu console input.", "Choosing between a line out and a miked cabinet when recording a modeler."]}, "bff9f97f-f5d2-4937-9525-eba4588778a1": {"definition": "An isolation shield is a portable acoustic barrier — an absorptive (sometimes absorptive/reflective composite) panel placed around a microphone or between sound sources — used to reduce room reflections and leakage from nearby instruments during recording.", "plain_english": "It's a padded screen you put around a mic, or between players. It blocks room echo. It also stops other instruments from spilling into the mic.", "purpose_function": "It improves separation between sources recorded at the same time and tames early reflections, yielding cleaner, more independently controllable tracks.", "practical_application": "A tech sets absorptive shields or gobos around a guitar amp or vocal mic, or between a harp and a nearby instrument, to cut bleed and reflections without needing a separate isolation booth.", "category": "Studio acoustics", "related_terms": ["Leakage", "Isolation booth", "Gobo", "Reflection filter", "Room microphone"], "common_mistakes": ["Expecting a small mic-mounted shield to fully isolate a source; it mainly reduces early reflections and modest bleed, not low-frequency spill.", "Placing the shield so close that it colors the sound with its own reflections or comb filtering.", "Relying on shields instead of distance, directional mics and arrangement to control heavy leakage."], "scenario_contexts": ["Reducing bleed between a guitar amp and a vocalist tracking live in one room.", "Taming a live room's reflections around an acoustic guitar microphone.", "Separating a harp from other instruments in an ensemble session without a booth."]}, "bd17dc8f-b1ce-4b16-bdf7-fb4f9adfd0ea": {"definition": "Leakage (also called bleed or spill) is unwanted sound from one source picked up by a microphone intended for a different source — for example, drums appearing in a vocal mic — during simultaneous recording or amplification.", "plain_english": "It's when a mic picks up sounds it isn't meant to. One example is the guitar amp bleeding into the singer's mic.", "purpose_function": "Leakage is an unavoidable consequence of open microphones sharing a space, and it matters because it sets the limit on track separation and creates phase/comb-filtering when one source appears in several mics, so controlling it is central to clean multitrack work.", "practical_application": "Engineers manage leakage with mic choice and pattern (directional mics with nulls aimed at offending sources), distance, isolation shields, gobos and booths, and arrangement, while weighing useful leakage that glues a live ensemble against the loss of independent control.", "category": "Recording technique", "related_terms": ["Isolation shield", "Isolation booth", "Polar pattern", "Comb filtering", "Phase"], "common_mistakes": ["Trying to fix heavy leakage only with a gate or EQ in the mix instead of controlling it at the source with placement and isolation.", "Ignoring phase and comb-filtering when the same source leaks into several mics, causing a hollow or thin sound once tracks are combined.", "Assuming close-miking alone eliminates leakage; loud nearby sources still bleed in."], "scenario_contexts": ["Tracking a live band in one room and hearing the drum kit in the guitar and vocal mics.", "Deciding mic patterns and gobo placement to minimize spill in a string ensemble.", "Diagnosing a hollow combined mix caused by one source leaking into multiple mics."]}, "2b5a8a15-54e4-4f93-bc16-7ea03afe32cf": {"definition": "On a stereo device, the Left/Mono (L/MONO) output is the jack designated for mono operation: when only that single jack is connected, the device provides a mono feed there, while using both jacks gives a stereo pair.", "plain_english": "This is the jack to use when you only have one cable. Plug into the L/MONO jack and you get a mono signal. That way you don't lose half the sound.", "purpose_function": "It lets a stereo instrument or effect feed a single mono input — an amp, mixer channel or interface input — without discarding content that would otherwise only appear on the right channel.", "practical_application": "When a keyboard, drum machine or stereo pedal must go to one mono channel, a tech connects only the L/MONO jack as the manufacturer's manual specifies, rather than taking just the left channel and dropping right-panned material.", "category": "Signal I/O", "related_terms": ["Instrument line output", "Instrument direct output", "Mono", "Stereo", "Summing"], "common_mistakes": ["Taking only the plain L (left) jack of a stereo pair that does not sum, which drops all right-channel content; confirm whether the jack is a true L/MONO summing jack.", "Assuming every jack labeled L/MONO sums L+R; some simply pass the left channel, so behavior varies by device and the manual should be checked.", "Leaving both outputs connected but sending only one to the desk, then wondering why panned parts vanish."], "scenario_contexts": ["Sending a stereo keyboard to a single mono console channel through its L/MONO output.", "Connecting a stereo effects pedal into one amp using the mono output.", "Wiring a drum machine's L/MONO out to a mono DI for a live feed."]}, "d7e91412-d2ea-4fe9-b0ee-619732c1525f": {"definition": "A lever harp is a diatonically strung harp fitted with a manually operated lever (a sharping or blade lever) at the top of each string; engaging a lever shortens the string's vibrating length to raise that pitch by a semitone, giving limited chromatic flexibility without the foot-pedal mechanism of a concert (pedal) harp. It is also known as the folk or Celtic harp.", "plain_english": "A smaller harp with strings tuned to one key. Each string has a little flip-lever at the top. Flipping one raises that note by a half-step to change keys. A big concert harp uses foot pedals instead.", "purpose_function": "It provides a portable, mechanically simpler and cheaper harp on which the player raises pitches by hand-operated levers, giving enough chromatic flexibility for folk, Celtic, and small-ensemble music.", "practical_application": "In the studio a technician mics a lever harp much like other acoustic harps but positions mics to capture the soundboard while anticipating audible mechanical clicks when the player flips levers mid-piece, and plans for its typically lower output than a concert harp.", "category": "String instrument", "related_terms": ["Pedal harp", "Soundboard", "Diatonic tuning", "Sharping lever", "Concert pitch", "Master tuning"], "common_mistakes": ["Confusing a lever harp with a pedal (concert) harp: levers raise pitch a semitone by hand, whereas pedals do it by foot and give full chromatic control", "Assuming a lever harp is fully chromatic; it is tuned diatonically and can only reach the notes its levers provide", "Forgetting that flipping levers produces mechanical noise that a close mic will capture during a take"], "scenario_contexts": ["Recording a Celtic or folk session where the harpist re-levers between tunes", "Choosing a lever harp over a pedal harp for a small or touring ensemble on budget and weight grounds", "Miking a lever harp's soundboard while managing lever-click noise"]}, "d3f5f4f3-5527-4473-83eb-30179d4cb1d8": {"definition": "A line output is a signal output that delivers audio at line level, a nominal operating level of about +4 dBu (professional) or -10 dBV (consumer), from a low source impedance, intended to drive the line-level input of another device such as a mixer, audio interface, or power-amplifier input. It is distinct from microphone-level and loudspeaker-level outputs.", "plain_english": "The normal-strength audio output on gear, like the jacks on a keyboard or interface. It sends a healthy signal meant for another device's line input. This signal is much stronger than a mic's. But it is far weaker than what drives a speaker.", "purpose_function": "It presents a standardized, relatively strong, low-impedance signal so audio can pass between devices with good signal-to-noise ratio and minimal loss, matching the line inputs those devices expect.", "practical_application": "A technician patches a keyboard, DI box, or interface line output into a mixer or amplifier line input, matching +4 dBu or -10 dBV settings between the two devices to avoid clipping or an overly quiet, noisy signal.", "category": "Signal & I/O", "related_terms": ["Line level", "Mic level", "Line input", "Instrument level", "DI box", "Balanced connection"], "common_mistakes": ["Plugging a line output into a mic input without a pad: the far hotter line signal overloads the mic preamp and distorts", "Connecting an amplifier's loudspeaker output into a line input; the high speaker-level voltage can damage the line input", "Confusing line level with instrument level and expecting a guitar-level input to handle a line output cleanly", "Ignoring the +4 dBu versus -10 dBV difference, causing level mismatches that are too quiet and noisy or too hot and clipping"], "scenario_contexts": ["Sending a synth's line output to a channel line input on the mixing console", "Feeding a DI or interface line output to the line input of a powered speaker or amplifier", "Setting a device's output switch to +4 dBu or -10 dBV to match the receiving equipment"]}, "07b87eea-21c6-42db-ad47-a2da9380bf8c": {"definition": "Local Control is a MIDI function (Control Change 122) on an instrument that has both a keyboard/controller and an internal sound engine; when Local Control is On the keyboard directly plays the internal sounds, and when Off the keyboard and sound engine are internally disconnected so the keyboard only transmits MIDI while the sound engine responds only to incoming MIDI.", "plain_english": "A switch on a keyboard-synth. It decides if pressing the keys plays the synth's own sounds. Turn Local Control off and the keys stop playing those sounds. Now they just send MIDI out. People do this with a computer to stop each note sounding twice.", "purpose_function": "It exists to prevent doubled or echoed notes when the instrument is used with a DAW or sequencer that echoes MIDI back to it, by letting the physical keyboard and the tone generator be addressed independently.", "practical_application": "When a synth plays each note twice while tracking into a DAW with MIDI echo enabled, the technician sets Local Control Off on the synth so the keys route through the computer and back rather than also triggering the internal sounds directly.", "category": "MIDI", "related_terms": ["MIDI", "Control Change", "MIDI echo", "Sequencer", "Tone generator", "MIDI channel"], "common_mistakes": ["Leaving Local Control Off and then wondering why the keyboard makes no sound when played on its own", "Blaming a double-note problem on the DAW when the real fix is setting Local Control Off", "Assuming Local Control changes MIDI output; the keyboard still transmits MIDI regardless, and only the internal keyboard-to-sound link is broken"], "scenario_contexts": ["Recording a MIDI performance into a DAW that echoes MIDI, where notes double until Local Control is turned Off", "Using the synth as a master controller for external modules while silencing its own voices", "Troubleshooting a keyboard that suddenly will not sound after a session left Local Control Off"]}, "6df2ca5a-21cd-4b9a-bf05-e10856dcf647": {"definition": "The low-B string is the lowest string of a five-string bass guitar, tuned to B0 (approximately 30.87 Hz), a perfect fourth below the E string of a standard four-string bass, extending the instrument's range down to B. The term is also used for the low B string of a seven-string guitar, which is tuned an octave higher at B1.", "plain_english": "The extra-thick bottom string on a 5-string bass. It is tuned to a low B, a few notes below a normal 4-string bass. So the player can reach deeper notes without retuning.", "purpose_function": "It extends a bass's range downward by five semitones without retuning, letting players reach low B, C, and D notes demanded by modern styles and by parts written for extended-range instruments.", "practical_application": "When recording or reinforcing a five-string bass, a technician makes sure the signal path and monitors can reproduce roughly 31 Hz cleanly, watches for excess subsonic energy and rattle on the low B, and may high-pass or manage headroom accordingly.", "category": "Strings", "related_terms": ["Five-string bass", "Bass guitar", "Open string", "String gauge", "Drop tuning", "Fundamental frequency"], "common_mistakes": ["Expecting the low B (around 31 Hz) to reproduce on small speakers or earbuds, whose drivers cannot output that fundamental", "Confusing the bass low B (B0) with a guitar's low B (B1), which is an octave higher", "Fitting too light a string gauge on the low B, giving a floppy, pitch-unstable, buzzy note"], "scenario_contexts": ["Tracking a five-string bass and setting up monitoring or subwoofers able to reproduce roughly 31 Hz", "Managing low-frequency headroom and high-pass filtering when the player uses the low B", "Selecting a heavier string gauge to keep the low B tight and in tune"]}, "3951811a-c281-4705-97fd-672b6602826a": {"definition": "The mandolin chop (chop chord) is a percussive rhythm technique in which the player strikes a closed, fully fretted chord, typically on beats 2 and 4, and immediately releases left-hand finger pressure to damp the strings, producing a short, sharp, snare-like accent instead of a ringing chord. It is a defining rhythmic role of the mandolin in bluegrass.", "plain_english": "A choppy, drum-like way to play rhythm on the mandolin. You hit a muted chord on the offbeats. Then you deaden the strings right away. It sounds like a quick chuck, not a ringing chord. In a bluegrass band it acts like the snare drum.", "purpose_function": "It gives a drummer-less string band its backbeat and rhythmic drive, letting the mandolin act as a percussion voice by emphasizing beats 2 and 4.", "practical_application": "When recording bluegrass, an engineer treats the chop as a fast transient, percussive source, choosing and placing a mic that handles quick attacks and watching for the sharp peaks it adds on the backbeat.", "category": "Playing technique", "related_terms": ["Mandolin course", "Backbeat", "Muting", "Tremolo", "Closed chord", "Rhythm playing"], "common_mistakes": ["Letting the chord ring instead of damping it immediately, which loses the percussive chop character", "Using an open chord shape that cannot be muted cleanly; the chop needs a closed, fully fretted shape", "Placing the chop on beats 1 and 3 rather than on the backbeat of 2 and 4"], "scenario_contexts": ["A bluegrass rhythm section where the mandolin chop supplies the backbeat instead of drums", "Recording the chop as a percussive transient that needs fast-transient mic handling", "A jam where the mandolinist alternates between chop rhythm and lead tremolo"]}, "e4d4cd94-6b9c-4079-8e88-01dcb8c1eeec": {"definition": "A course is a group of strings, on the mandolin a pair, set close together, tuned to the same pitch (in unison), and fretted and picked together as a single voice; the mandolin has four courses (eight strings) tuned G-D-A-E, in the same intervals as a violin.", "plain_english": "On a mandolin the strings come in doubled pairs, and each pair is called a course tuned to the same note, so the eight strings really act like four fat strings. That doubling gives the mandolin its shimmering tone.", "purpose_function": "Pairing and tuning two strings in unison per course increases loudness and creates a natural chorus and shimmer from the slight differences between the two strings, giving the mandolin family its bright, sustaining tone.", "practical_application": "A technician tuning or recording a mandolin checks that both strings of each course match, since a mistuned course produces beating or an out-of-tune chorus that a close mic will expose.", "category": "Strings", "related_terms": ["Mandolin chop", "Unison", "String gauge", "Twelve-string guitar", "Open string", "Master tuning"], "common_mistakes": ["Treating the eight strings as eight separate pitches rather than four unison-tuned pairs (courses)", "Tuning only one string of a course, leaving the pair beating against itself", "Confusing a course (here a doubled pair) with a single string"], "scenario_contexts": ["Tuning each mandolin course so both strings match to avoid beating", "Diagnosing a chorusy, out-of-tune sound traced to one string of a course", "Comparing the mandolin's doubled courses to a twelve-string guitar's paired courses"]}, "2219ad69-ec83-454c-a63d-3019acc17de5": {"definition": "Master tuning (master tune) is a global parameter on an electronic instrument that shifts the pitch reference of the entire instrument, all voices and parts together, usually calibrated to A4 = 440 Hz and adjustable in hertz or cents so the instrument can be matched to other instruments or an ensemble's tuning. In MIDI it corresponds to the Master Fine and Master Coarse Tuning messages.", "plain_english": "One setting that shifts the whole keyboard's pitch up or down at once. For example, from A = 440 Hz to A = 442 Hz. This helps it match a piano, an orchestra, or other instruments tuned a bit differently.", "purpose_function": "It lets a player match an electronic instrument's overall pitch to acoustic instruments or a house tuning standard without transposing or retuning individual notes.", "practical_application": "Before a session the technician sets the synth's master tune to the reference in use, such as A = 442 Hz to match an orchestra, so all keyboards and outboard gear share one pitch center.", "category": "Tuning", "related_terms": ["Concert pitch", "Cent", "Transpose", "Fine tuning", "MIDI", "Musette tuning"], "common_mistakes": ["Confusing master tuning, which shifts the whole instrument's pitch reference, with transpose, which shifts by whole semitones or keys", "Leaving a session-specific master tune (such as 442 Hz) engaged and then recording out of tune with everything else at 440", "Adjusting individual voice tunings when a single master-tune change was intended"], "scenario_contexts": ["Matching a synth to an orchestra tuned to A = 442 Hz", "Aligning several keyboards and modules to one pitch reference before tracking", "Correcting an instrument found slightly sharp or flat by trimming master tune in cents"]}, "1ff7db0e-6dcb-4d3a-86f7-198f5f992908": {"definition": "A mixture is a compound organ stop that sounds several ranks of pipes, commonly two to five, for each key pressed, tuned to octaves and fifths above the unison (the fifth-sounding ranks being mutation pitches) to reinforce the upper harmonics of the chorus and add brilliance. A Roman numeral (for example Mixture IV) gives the number of ranks, and the ranks 'break' back to lower pitches as the player ascends the keyboard.", "plain_english": "A single organ stop that, for every key, sounds several small high-pitched pipes at once. Those extra high notes add sparkle and brightness to the organ's full sound rather than adding new melody notes.", "purpose_function": "It crowns the organ's principal chorus by adding high, harmonic-reinforcing ranks, giving the ensemble clarity and brilliance that single-rank stops cannot provide.", "practical_application": "When recording a pipe organ, an engineer expects mixtures to add strong high-frequency energy and to break at points across the compass, so mic placement and levels must accommodate their brightness without harshness.", "category": "Organ stop", "related_terms": ["Rank", "Principal chorus", "Mutation stop", "Pipe organ", "Registration", "Stop"], "common_mistakes": ["Thinking a mixture plays extra melody notes; it only adds fixed higher harmonics (octaves and fifths) to whatever is played", "Assuming one stop equals one rank, when a mixture is several ranks per note", "Ignoring the break-back and expecting the high ranks to keep rising indefinitely up the keyboard"], "scenario_contexts": ["Adding a mixture to brighten the full-organ (plenum) registration", "Capturing the extra high-frequency content of mixtures when recording a pipe organ", "Reading 'Mixture IV' on a stop knob and knowing it draws four ranks per key"]}, "6311ee30-a99f-42af-86d1-95913333752a": {"definition": "Musette tuning is a tremolo, or 'wet', tuning of an accordion's middle-register (8') reeds in which two or three reeds sounding the same note are deliberately detuned from one another, one on pitch and the other(s) slightly sharp (and sometimes one slightly flat), so the beating between them produces a shimmering, vibrato-like tone. The amount of detuning, measured in cents, ranges from near-unison (dry) to a strong wet French-musette effect.", "plain_english": "An accordion setup where two or three reeds play the same note. They are tuned very slightly apart. So they beat against each other. This makes that warbling, shimmering cafe-accordion sound. More detuning gives a wetter, shakier tone.", "purpose_function": "It thickens and animates the accordion's tone through controlled beating between detuned reeds, producing the characteristic chorused, tremolo sound of French musette and many folk styles.", "practical_application": "A technician recording an accordion notes that a strongly wet musette registration already contains built-in beating and chorus, so added modulation effects are usually unnecessary, and checks that the paired reeds hold the intended amount of detune in cents.", "category": "Tuning", "related_terms": ["Reed rank", "Beating", "Cent", "Master tuning", "Tremolo", "Register"], "common_mistakes": ["Assuming musette tuning is out-of-tune or a defect, when the detuning is intentional and defines the sound", "Confusing the accordion musette tuning with the pipe-organ Musette reed stop, a different use of the name", "Trying to 'correct' the beating to perfect unison, which removes the musette effect"], "scenario_contexts": ["Selecting a wet musette register for a French or folk accordion track", "Setting the amount of detune in cents when an accordion's reeds are tuned or serviced", "Deciding not to add chorus in the mix because the musette reeds already provide it"]}, "ee42e329-58e0-45dd-8f30-ef9db725b803": {"definition": "Unwanted residual sound that remains audible even though a source or channel has been muted, for example a damped or muted note still leaking into other open microphones, or a console/DAW mute that does not fully attenuate the signal.", "plain_english": "Sound you still hear even after something has been muted. It sneaks through because the mute is not complete, or because it leaks into a nearby mic.", "purpose_function": "The term names a common capture and mixing fault so engineers can track down why a supposedly silenced part is still audible and fix the routing, gating, or mic setup.", "practical_application": "When a palm-muted guitar or a muted string still shows up in the drum or room mics, an engineer improves isolation, repositions mics, or gates the offending channel to stop the bleed.", "category": "Signal isolation", "related_terms": ["Bleed control", "Palm muting", "Onboard speaker bleed", "Open string", "Body knock"], "common_mistakes": ["Assuming a channel mute removes a sound that is actually leaking into other open mics", "Relying on a noise gate to hide mute bleed instead of improving isolation at the source", "Confusing intentional palm-mute tone with unwanted mute bleed"], "scenario_contexts": ["Tracking a full band live, where a muted guitar amp still bleeds into the drum overheads", "Editing a multitrack and hearing a muted section still faintly present", "Setting up mic screens or isolation to reduce bleed from a damped instrument"]}, "bc25bf66-1a64-4ff8-9667-c0c6ce6afa4a": {"definition": "The structural junction where a stringed instrument's neck attaches to its body, carrying constant string tension and coupling the neck to the body's vibration. Common guitar types are the glued set neck (dovetail or mortise-and-tenon), the bolt-on (screwed) neck, and neck-through construction in which the neck timber runs the full length of the body.", "plain_english": "The place where a guitar's neck meets its body, and how it is fixed on — glued in, bolted on, or running all the way through. This joint influences the guitar's tone, sustain and how easily it can be repaired or adjusted.", "purpose_function": "It anchors the neck against the strings' continuous pull and sets the neck angle that determines string height (action), while its rigidity and mass affect sustain and how vibration transfers between neck and body.", "practical_application": "When close-miking an acoustic or diagnosing high action, buzzes, or a shifting neck angle, a technician inspects the joint area; on electrics, knowing whether a guitar is bolt-on, set, or neck-through guides setup, expected sustain, and repair approach.", "category": "Guitar construction", "related_terms": ["Action", "Neck relief", "Sustain", "Fretboard", "Bridge"], "common_mistakes": ["Confusing the three joint types (bolt-on, set neck, neck-through) or assuming joint type alone dictates tone", "Assuming a bolt-on neck is always inferior to a glued/set neck", "Ignoring that a loose or shifting neck joint changes neck angle and action rather than treating it as a truss-rod issue"], "scenario_contexts": ["Recording or setting up an acoustic guitar with action or intonation problems", "Comparing bolt-on vs set-neck electrics for a session", "Repairing a loose or separating neck joint"]}, "75c63b74-b8b4-4723-9898-4f514080476e": {"definition": "An acoustic guitar strung with nylon or nylon-core (often silver-plated-copper-wound bass) strings rather than steel, the family that includes the classical and flamenco guitar. Compared with a steel-string it uses much lower string tension, a wider flat fingerboard usually without a truss rod, and a lightly fan- or lattice-braced top, giving a warmer, mellower tone.", "plain_english": "The soft-stringed acoustic guitar used for classical and flamenco music. Its nylon strings are gentle on the fingers. They make a warm, round sound. A steel-string acoustic is brighter and louder.", "purpose_function": "The lower tension of nylon strings allows a lightly braced, responsive top and the wide neck suited to fingerstyle classical technique, delivering the mellow tone and fine dynamic nuance that this repertoire demands.", "practical_application": "When recording one, engineers commonly place a small-diaphragm or quality condenser near where the fingerboard meets the body and treat it as a quiet, wide-dynamic-range source needing careful gain and low noise; its setup differs greatly from a steel-string because tension is far lower.", "category": "Guitar type", "related_terms": ["Steel-string guitar", "Fingerstyle", "Condenser microphone", "Soundhole", "Bridge"], "common_mistakes": ["Fitting steel strings to a guitar built for nylon, whose lighter bracing and bridge can be damaged by the far higher tension", "Expecting a truss-rod adjustment on an instrument that has none", "Miking it as loud as a steel-string and under-gaining the quieter, more dynamic source"], "scenario_contexts": ["Classical guitar recording session", "Flamenco or Latin fingerstyle tracking", "Solo fingerstyle overdub needing a warm, intimate tone"]}, "85e3bfd6-4fe3-4a55-92c1-6b44e9b287f1": {"definition": "Leakage from a device's built-in (onboard) loudspeaker, such as a combo amplifier, keyboard, or practice amp with an integrated speaker, into microphones capturing other sources on a session. It is a specific form of mic bleed caused by the source monitoring itself through its own speaker.", "plain_english": "When a mic picks up sound coming from a speaker built into an instrument or amp nearby. That built-in speaker leaks into recordings of other things in the room.", "purpose_function": "The term pinpoints the source of unwanted leakage so an engineer can isolate or reposition the noisy built-in speaker and keep other tracks clean.", "practical_application": "To stop onboard speaker bleed, a tech turns down or mutes the built-in speaker, uses a DI or line out instead, or moves the device out of the live room.", "category": "Signal isolation", "related_terms": ["Bleed control", "Mute bleed", "Direct guitar track", "Re-amping", "Speaker cabinet isolation"], "common_mistakes": ["UNSAFE: Draping blankets over a tube amp's vents or built-in speaker to block bleed, which traps heat and creates a fire and burn hazard", "Forgetting a keyboard's onboard speaker is on and letting it leak into vocal mics", "Assuming a DI signal is bleed-free while the instrument's own speaker still feeds the room"], "scenario_contexts": ["Recording vocals while a guitarist's combo amp speaker leaks into the vocal mic", "Capturing a DI keyboard part while its onboard speaker bleeds into room mics", "Isolating an amp in a separate room to remove its speaker bleed from drum mics"]}, "c7cf81fe-c6f9-497b-844c-a1c21d14aa55": {"definition": "On a brass instrument, the natural unmuted and unstopped state of the bell — no mute inserted and, on the horn, the hand not stopping the bell — sounding the instrument's full, open tone. In notation the marking 'open' (often 'o') cancels a preceding muted or hand-stopped passage.", "plain_english": "A brass instrument played normally, with nothing pushed into or covering the bell. It is the opposite of using a mute or, on French horn, hand-stopping the bell.", "purpose_function": "The open bell gives the instrument its full, unaltered projection and timbre and acts as the default reference sound against which muted or stopped tone colours are contrasted.", "practical_application": "When miking brass, an engineer aims near the open bell (often slightly off-axis to tame harshness) and must re-check level and tone whenever a player switches between open and muted passages, since output and directivity change.", "category": "Brass technique", "related_terms": ["Mute", "Stopped horn", "Bell", "Off-axis", "Directivity"], "common_mistakes": ["Confusing 'open' (unmuted/unstopped) with 'bells up' (raising the bell for projection)", "Forgetting that a mute-to-open change alters level and tone at the mic and needs a gain/EQ check", "Miking straight into a bright open bell and capturing a harsh, edgy tone"], "scenario_contexts": ["Recording a brass section that alternates open and muted phrases", "Horn passages moving between open and stopped notes", "Setting mic distance and angle on a bright solo trumpet"]}, "e841b7a7-22c7-41ae-8888-436697fc3429": {"definition": "A string sounded at its full vibrating length with no finger stopping it on the fingerboard, so it produces the pitch to which that string is tuned. On a standard-tuned guitar these are E-A-D-G-B-E; on the violin family they are the four tuned strings.", "plain_english": "A string you play without pressing it down anywhere, so it rings at its natural full-length pitch. On a normal guitar those open notes are E, A, D, G, B and E.", "purpose_function": "Open strings give fixed tuning-reference pitches, offer the longest, most resonant sustain, and enable techniques (drones, open-position chords, natural harmonics) unavailable on stopped notes, with a brighter timbre than a fretted note of the same pitch.", "practical_application": "Players and engineers use open strings as tuning and intonation references, weigh their brighter, longer-sustaining tone when balancing a recorded part, and mute unwanted open-string ringing (sympathetic resonance) that can muddy a take.", "category": "String technique", "related_terms": ["Fretting", "Harmonics", "Intonation", "Tuning", "Capo"], "common_mistakes": ["Assuming an open string and a fretted note of the same pitch have identical timbre and sustain", "Letting open strings ring sympathetically and blur a recorded part", "Confusing an open string with a natural harmonic played on that string"], "scenario_contexts": ["Tuning and checking intonation before a take", "Playing open-position chords or a droning open-string part", "Muting sympathetically ringing open strings during recording"]}, "090c023d-bb35-408d-a028-75ff4d60d7e9": {"definition": "A banjo whose drum-like body (pot) has no resonator plate closing the back, leaving the rear of the head open. This gives a softer, warmer, more mellow tone with less volume and forward projection than a resonator banjo, and it is the type favoured in clawhammer and old-time playing.", "plain_english": "A banjo with an open back — no cover plate behind the drum head. It sounds softer and mellower and is quieter than the closed-back 'resonator' banjos used in bluegrass.", "purpose_function": "Leaving the back open lets sound radiate rearward and be partly absorbed by the player's body, reducing projection and producing the gentler, plunkier tone suited to old-time and clawhammer styles.", "practical_application": "Because it is quieter and radiates from both front and back, an engineer mics it closer and mainly toward the front of the pot while watching for room bleed; a player's open-back-vs-resonator choice is a tone-and-volume decision the tech should anticipate.", "category": "String instrument", "related_terms": ["Banjo", "Resonator", "Drumhead", "Bridge", "Clawhammer"], "common_mistakes": ["Treating open-back as a lower-quality or beginner instrument rather than a tonal choice", "Expecting bluegrass-level volume and projection from it", "Miking only the front and missing that it also radiates from the open rear"], "scenario_contexts": ["Recording old-time or clawhammer banjo", "Folk sessions wanting a soft, warm banjo tone", "Choosing open-back vs resonator for a bluegrass vs old-time part"]}, "ca33765b-2d16-499d-890b-72bdc19b0ab7": {"definition": "On a wind instrument, forcing the air column to vibrate at a higher normal mode (harmonic) than its fundamental by raising blowing pressure and air speed and adjusting the embouchure, usually aided on woodwinds by opening a register or octave vent, so the same fingering sounds a note in a higher register. Conical-bore and open cylindrical instruments overblow at the octave (2nd mode), while stopped cylindrical instruments such as the clarinet overblow at the twelfth (3rd mode).", "plain_english": "Blowing harder, and often pressing a register key, so a wind instrument jumps to a higher note. Most instruments jump up one octave. The clarinet jumps a twelfth because of how it is built.", "purpose_function": "Overblowing extends a wind instrument's playable range well beyond its lowest register by reusing fingerings at higher harmonics, and register keys/vents exist specifically to make these mode jumps speak cleanly and reliably.", "practical_application": "Players and engineers expect timbre and dynamics to shift across register breaks; overblown upper-register notes are often brighter or edgier and may call for adjusted mic placement or gain, and an unintended squeak is essentially an accidental overblow.", "category": "Wind technique", "related_terms": ["Harmonics", "Register key", "Embouchure", "Fundamental frequency", "Partials"], "common_mistakes": ["Assuming every wind instrument overblows at the octave, when the clarinet overblows a twelfth", "Confusing intentional overblowing with an accidental squeak", "Expecting timbre to stay uniform across the register break"], "scenario_contexts": ["Playing or recording the upper register of a flute or saxophone", "Negotiating the clarinet's register break in a take", "Adjusting mic or gain for brighter overblown notes"]}, "e0f5d73e-dcb6-4480-99fb-1e1f5c2afea6": {"definition": "A guitar technique in which the picking-hand palm rests lightly on the strings just ahead of the bridge/saddle while picking, damping the strings to shorten their sustain and produce a tight, muffled, percussive tone. Widely used in rock and metal rhythm playing, it is usually marked 'P.M.' in notation and tab.", "plain_english": "Resting the side of your picking hand on the strings right by the bridge as you play, so the notes come out short, chunky and muted instead of ringing out. It's the classic 'chugging' rock and metal rhythm sound.", "purpose_function": "By damping the strings near the bridge the player controls sustain and tone — tightening the low end, adding percussive attack, and creating dynamic contrast against open, ringing passages.", "practical_application": "It is central to tight electric rhythm tones; engineers find palm-muted parts have controlled sustain and strong transient and low-mid energy, which affects gain staging, compression, and how much of the amp's low end needs taming.", "category": "Guitar technique", "related_terms": ["Damping", "Bridge", "Sustain", "Distortion", "Rhythm guitar"], "common_mistakes": ["Resting the palm too far from the bridge, choking the note into a dull thud", "Uneven palm pressure making notes speak inconsistently", "Confusing picking-hand palm muting with fretting-hand (left-hand) muting"], "scenario_contexts": ["Tracking tight metal or rock rhythm guitar", "Funk or pop muted-strum parts", "Adding dynamic contrast between muted and open sections of an arrangement"]}, "e23ad24b-e407-4a1b-b4db-57d29d167cc6": {"definition": "The difference in output level between one patch (preset/program) and another on a synthesizer, sampler, or amp/effects modeler, so that switching patches changes the perceived loudness even at the same played dynamics.", "plain_english": "When you switch sounds on a synth or modeler, some presets are louder than others. That change in volume between presets is patch level variation.", "purpose_function": "Recognizing this helps players and engineers level-match presets so a performance stays consistent and no patch jumps out or disappears in the mix.", "practical_application": "Before a session or show, a tech auditions each patch and adjusts its output or a gain stage so all patches sit at a similar level when switched.", "category": "Gain & level", "related_terms": ["Patch-change transient", "Direct guitar track", "Re-amping", "Coil tap"], "common_mistakes": ["Assuming all factory patches are level-matched out of the box", "Setting record levels on one loud patch and then clipping or under-recording quieter ones", "Confusing patch level variation with a performer simply playing louder"], "scenario_contexts": ["Level-matching amp-modeler presets before tracking a guitar", "Balancing synth patches during a live set so no sound jumps out", "Gain-staging a keyboard rig where presets differ in output"]}, "5b7077e3-4def-4e14-903e-9882926b33de": {"definition": "The momentary audio artifact — a click, gap, or abrupt jump in level or timbre — that can occur at the instant a synthesizer switches to a new patch, typically triggered by a MIDI Program (or Bank) Change, when currently held notes are cut off or the incoming patch's level and envelope state differ from the outgoing one.", "plain_english": "The little glitch, pop, or sudden change in loudness you sometimes hear right when a synth jumps to a new sound.", "purpose_function": "Recognising this transient matters because it can intrude on a live performance or a recording; understanding what causes it guides players and sound designers in switching sounds without an audible glitch.", "practical_application": "To avoid patch-change transients on stage, a keyboardist changes programs during rests, uses a synth's seamless/gapless sound-transition feature, or keeps a sustaining part on a separate layer while switching the other.", "category": "MIDI/synthesis", "related_terms": ["Program Change", "Patch", "MIDI", "Transient", "Envelope"], "common_mistakes": ["Changing patches while notes are still held, which cuts them off audibly in the middle of a phrase", "Assuming the click is a hardware fault rather than a normal consequence of the switch and of level/envelope differences between patches", "Not enabling a synth's seamless or gapless patch-change mode when the instrument provides one"], "scenario_contexts": ["A live keyboard player switching between song sections hears the held chord cut off at the program change", "Building a set list so that program changes land on rests rather than under sustained notes", "Editing a MIDI mock-up where a mid-note program change leaves an audible glitch in the render"]}, "94e9a8cc-e174-42ea-867a-3d40ef6f0e0d": {"definition": "In a pipe (or electronic) organ, the division of the instrument played from the pedalboard with the feet, having its own set of stops and ranks and typically supplying the low bass foundation of the instrument.", "plain_english": "The part of an organ the player works with the feet. You press a big footboard of keys. It usually plays the deep bass notes. It has its own set of pipe sounds.", "purpose_function": "It exists so the organist can play an independent bass line with the feet while the hands play the manuals, and it houses the large low-pitched stops that give the organ its deep foundation.", "practical_application": "When recording an organ, the engineer chooses low-frequency-capable microphones and monitoring to capture the pedal division's very low fundamentals (a 16' or 32' stop can extend well below 32 Hz) while managing room modes and structural rumble.", "category": "Pipe organ", "related_terms": ["Manual", "Pipe rank", "Stop", "Pedalboard", "Pipe speech transient"], "common_mistakes": ["Confusing the pedal division (played by the feet) with a manual (played by the hands)", "Assuming the pedal division always sounds the lowest octave, when its pitch depends on which stops (8', 16', 32') are drawn", "Specifying microphones or monitors that cannot reproduce the 16' and 32' pedal fundamentals, so the true low end is never heard"], "scenario_contexts": ["Recording a large pipe organ and capturing the pedal division's sub-bass in a reverberant space", "Reinforcing an organ recital where a 32' pedal stop challenges the PA's low-frequency headroom", "Reviewing an organ mix to confirm the pedal line is present and not lost to room rumble or filtering"]}, "98de405d-24c5-4e3a-ba59-ba755b3c90cf": {"definition": "A concert harp fitted with seven pedals — one for each note name — that, through a double-action mechanism, mechanically shorten the sounding strings to raise each pitch class by a semitone (flat, natural, or sharp), enabling the diatonically strung instrument to play in all keys.", "plain_english": "The large orchestral harp with seven foot pedals. Each pedal retunes all the strings of one note. For example, all the C's, or all the D's. It shifts them up or down by a half-step. This lets the player play in any key.", "purpose_function": "The pedal mechanism exists to give a diatonically strung harp full chromatic capability without adding strings, letting one instrument produce the sharps and flats of every key.", "practical_application": "When recording a pedal harp, engineers place microphones to balance the bright attack near the soundboard against the body's resonance, and must account for audible mechanical pedal and action noise during quiet passages.", "category": "String instrument", "related_terms": ["Concert harp", "Glissando", "Pizzicato", "Soundboard", "Enharmonic"], "common_mistakes": ["Confusing the pedal (concert) harp with the lever (folk/Celtic) harp, which changes pitch with hand-operated levers rather than pedals", "Thinking each pedal changes only one string, when a pedal changes every string of that note name across all octaves", "Failing to plan for mechanical pedal-mechanism noise, which close mics readily capture in quiet passages"], "scenario_contexts": ["Miking a solo concert harp for a classical recording", "Placing the harp in an orchestral session and managing bleed from adjacent sections", "Troubleshooting audible pedal or action clicks captured during a quiet studio take"]}, "88574ae2-8786-467f-8c61-0388b7b2c698": {"definition": "The electrical switching convention — normally-open or normally-closed — by which a sustain or footswitch pedal signals its pressed and released states to a keyboard or module, and the matching 'pedal polarity' setting on the instrument that ensures the pedal is interpreted the correct way round.", "plain_english": "Whether a foot pedal's switch is 'open' or 'closed' when you step on it. If the keyboard's polarity setting does not match the pedal, sustain works backwards — notes hold when your foot is off and stop when you press.", "purpose_function": "The setting exists because sustain pedals from different makers use opposite switching conventions; matching the polarity lets any pedal operate correctly instead of inverted.", "practical_application": "When a newly connected sustain pedal behaves backwards, a technician sets the keyboard's pedal-polarity parameter, or connects the pedal before power-up so the instrument's auto-detect reads the correct rest state.", "category": "MIDI control", "related_terms": ["Sustain pedal", "Damper pedal", "MIDI CC 64", "Footswitch", "Continuous controller"], "common_mistakes": ["Assuming a backwards-working pedal is faulty, when it is actually a polarity mismatch between pedal and keyboard", "Hot-plugging the pedal after power-on so the instrument's auto-detect latches the wrong rest state — connect the pedal before switching on when relying on auto-detect", "Confusing pedal polarity (a switch convention) with audio signal polarity or phase in cable wiring"], "scenario_contexts": ["A guest keyboardist's third-party sustain pedal sustains inverted on the house synth", "Configuring a stage keyboard rig so every pedal behaves consistently before a show", "Setting the polarity parameter on a digital piano after switching to a different-brand pedal"]}, "028634d8-843c-4413-8e4a-8ce38dd81872": {"definition": "The bright, brilliant, penetrating timbral quality characteristic of the piccolo — the small transverse flute pitched an octave above the concert flute — arising from its high playing register and the strong high-frequency content of its spectrum.", "plain_english": "The piccolo has a very high, whistle-like, cutting tone. It rides easily on top of a full band or orchestra.", "purpose_function": "This brightness lets the piccolo project above large ensembles and add sparkle to the top of the texture, which is why it is used to reinforce and brighten the highest melodic lines.", "practical_application": "When recording or mixing piccolo, engineers manage its brightness and high output level with suitable mic placement (backed off and slightly off-axis from the embouchure) and gentle high-frequency control to avoid harsh, sibilant peaks.", "category": "Woodwind timbre", "related_terms": ["Piccolo", "Flute", "Timbre", "Harmonics", "Register"], "common_mistakes": ["Placing a mic directly in front of the embouchure hole, capturing excessive breath noise and a harsh, over-bright tone", "Boosting high frequencies on an already-bright piccolo and pushing it into harshness", "UNSAFE: monitoring a close-mic'd piccolo at high levels without hearing protection — its high-SPL output concentrated in the ear-sensitive 2–4 kHz region can contribute to hearing damage over long sessions (OSHA 29 CFR 1910.95)"], "scenario_contexts": ["Recording piccolo doublings in a wind ensemble where it must sit brightly above the flutes", "Taming a harsh piccolo in a film-score mix with de-essing and gentle EQ", "Positioning microphones in an orchestral session to balance piccolo brilliance against the rest of the woodwinds"]}, "af7dc31d-49e2-4e1a-929f-beff46499a3b": {"definition": "In a pipe organ, a rank is a complete set of pipes of uniform construction and tone colour, arranged one pipe per note across the compass of a keyboard; drawing a stop brings one rank — or, in the case of a mixture, several ranks — into play.", "plain_english": "A rank is one full row of organ pipes. They all share the same sound. There is one pipe for every key. Pulling a stop turns a rank on.", "purpose_function": "Ranks organise an organ's pipes into consistent voices so that each stop selects a distinct timbre; combining ranks builds up the instrument's overall tone and volume.", "practical_application": "When recording or documenting an organ, technicians identify ranks by their stop names and pitch length (for example an 8' Principal) to understand the tonal and spatial layout of the pipes being captured.", "category": "Pipe organ", "related_terms": ["Stop", "Manual", "Pedal division", "Mixture", "Pipe speech transient"], "common_mistakes": ["Confusing a rank (a set of pipes) with a stop (the control that brings ranks into play), when one stop can draw more than one rank in a mixture", "Assuming one rank equals one pipe, when a rank has one pipe per note across the whole keyboard", "Misreading pitch designations (8', 4', 2') as pipe counts, when they describe the sounding pitch of the rank"], "scenario_contexts": ["Cataloguing an organ's stop list before a recording session", "Spot-miking individual ranks or divisions on a large instrument", "Discussing with an organ builder which ranks contribute unwanted mechanical or wind noise"]}, "bac846cd-e431-435f-b324-fdaa704ea6de": {"definition": "The brief, tonally complex onset that occurs as an organ pipe begins to sound ('speaks'), before it settles into steady tone — often including a transient 'chiff' of noise and momentarily unstable harmonics that is characteristic of the pipe's voicing.", "plain_english": "The small burst of sound an organ pipe makes at the very start of a note. It happens before the pipe settles into its steady tone. You may hear it as a soft 'chiff.'", "purpose_function": "The speech transient is central to how a pipe's onset is heard and recognised; voicers deliberately shape it to give a rank its characteristic attack and clarity.", "practical_application": "When recording an organ, engineers preserve these onset transients with fast, transient-accurate microphones and minimal limiting, since over-compression or slow-settling capture blurs the pipe's articulation.", "category": "Pipe organ", "related_terms": ["Pipe rank", "Transient", "Attack", "Voicing", "Pedal division"], "common_mistakes": ["Treating the speech transient as noise to be removed, when it is an intrinsic and musically important part of a pipe's tone", "Confusing 'speech' (the onset of tone) with the pipe's steady-state sound", "Applying heavy limiting or slow-attack processing that smears the transient and robs the organ of articulation"], "scenario_contexts": ["Choosing microphones and preamps that preserve fast onset transients when recording a tracker organ", "Evaluating a sampled organ library for realistic pipe speech and attack behaviour", "Discussing voicing and regulation of chiff with an organ builder"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"7347d240-868d-4b5f-bb0f-15e6937861f7": {"definition": "A performance technique on bowed string instruments in which the player plucks the strings with a finger (or occasionally the thumb) instead of drawing the bow across them, producing a short, percussive, quickly decaying note.", "plain_english": "Instead of using the bow, the player plucks the strings with a fingertip. It's like plucking a guitar. This gives a short, punchy note that fades fast.", "purpose_function": "It provides a contrasting articulation to bowed (arco) playing, offering a percussive, rhythmic, quickly decaying sound; it is one of the core expressive techniques of the string family.", "practical_application": "When recording strings, an engineer captures the fast attack and short decay of pizzicato with close or spot mics, and avoids the heavy compression that would kill its natural transient and quick decay.", "category": "Playing technique", "related_terms": ["Arco", "Bowing", "Transient", "Spot microphone", "Double bass"], "common_mistakes": ["Confusing pizzicato with staccato — pizzicato means plucking the string, while staccato is a short articulation that can be played either arco or pizzicato", "Assuming pizzicato applies to only one instrument, when it is used across the whole bowed-string family (violin, viola, cello, double bass)", "Over-compressing pizzicato in the mix, which flattens the fast attack and quick decay that define the sound"], "scenario_contexts": ["Tracking a string quartet where the cellist alternates between arco and pizzicato passages", "A film-score session requiring tight, rhythmic pizzicato from the double-bass section", "Editing a sampled-string MIDI part that switches to a pizzicato articulation via a keyswitch"]}, "5b3bf15f-322e-4c64-8c28-a7bd98199526": {"definition": "The sharp, percussive onset transient of a note produced by plucking a string instrument (pizzicato) rather than bowing it; the finger releases the string impulsively, giving a very fast rise time and an initial burst rich in high-frequency content that decays quickly into the note's short sustain.", "plain_english": "It is the quick, snappy 'pop' you hear at the very start of a plucked note. You hear it when a violinist plucks the string instead of using the bow.", "purpose_function": "It defines the character, clarity and articulation of a plucked string note, so capturing it faithfully is what makes pizzicato sound present and defined in a recording rather than dull.", "practical_application": "When tracking pizzicato strings, engineers leave extra headroom and set converter and limiter levels for the transient peak, which sits well above the note's sustained level, and choose mic placement that preserves the fast attack.", "category": "String articulation", "related_terms": ["Pluck transient", "Transient", "Attack", "Sustain", "Pizzicato"], "common_mistakes": ["Setting record levels by the sustained note and then clipping the much louder attack transient", "Using heavy compression with a slow attack that dulls the pluck and makes pizzicato sound soft and lifeless", "Treating the whole note as 'the attack' — the pizzicato attack is only the first few milliseconds of onset"], "scenario_contexts": ["Tracking a string quartet's pizzicato passage and needing headroom for transient peaks", "Editing a sampled string library so each pizzicato attack starts cleanly without a click", "Mixing a track where plucked strings must cut through without over-compressing the transient"]}, "866d8ede-910a-4c0a-bfbc-ff1e396fd582": {"definition": "The brief, high-amplitude burst of energy at the onset of a plucked-string note (guitar, bass, harp, harpsichord, pizzicato strings), produced when the released string snaps into vibration; it has a very fast rise time and broadband, predominantly high-frequency content that decays within milliseconds into the steady tone.", "plain_english": "It is the quick, bright 'snap' at the front of every plucked note, before the note settles into its ringing tone.", "purpose_function": "This transient carries much of a plucked instrument's attack, definition and perceived articulation, so preserving it keeps the instrument sounding clear and punchy rather than soft.", "practical_application": "Technicians pick fast-transient mics, leave adequate headroom, and set compressor attack times deliberately so the pluck transient is captured or shaped on purpose instead of being smeared or clipped.", "category": "Transient response", "related_terms": ["Pizzicato attack", "Transient", "Attack", "Headroom", "Compression"], "common_mistakes": ["Setting input gain by the sustained note and clipping the converter on the transient peak", "Choosing a compressor attack time carelessly, so a fast attack kills the snap or a slow attack lets the peak through then squashes the body", "Assuming the transient is unwanted noise and filtering it out, which removes attack definition and note clarity"], "scenario_contexts": ["Recording fingerstyle acoustic guitar where the pick or nail attack defines the performance", "Tracking electric bass through a DI and judging headroom for slap-and-pop transients", "Setting a limiter on a harp or harpsichord take to tame peaks without dulling the attack"]}, "7fba5240-6153-4811-b1c5-1e4e6c38a75c": {"definition": "A shallow, cup-shaped mute for brass instruments — historically the rubber cup of a plumber's/sink plunger — held by hand over the bell of a trumpet or trombone and moved toward and away from the bell to open and close the sound, producing the characteristic 'wah-wah' or vocal, talking effect.", "plain_english": "It is a rubber cup, like the top of a sink plunger. A brass player holds it over the bell. They waggle it to make the classic 'wah-wah' talking sound.", "purpose_function": "It lets a brass player continuously vary tone colour and volume by hand, creating expressive open-and-closed (wah) effects rather than one fixed muted timbre.", "practical_application": "In the studio, engineers mic the bell a little further back and off-axis than usual because the hand motion changes level and directivity, and they may ride gain to even out the wah effect.", "category": "Brass mute", "related_terms": ["Practice mute", "Harmon mute", "Cup mute", "Straight mute", "Bell"], "common_mistakes": ["Confusing the plunger with the Harmon (wah-wah) mute — the plunger is hand-held over the bell, the Harmon fits inside the bell", "Miking too close and on-axis, so the level jumps drastically as the player closes the plunger", "Marking only 'muted' and omitting the open and closed (o / +) symbols the plunger technique needs"], "scenario_contexts": ["Recording a jazz or big-band trumpet or trombone 'wah' solo", "Reproducing an early-jazz 'growl' brass style in a session", "Live-miking a horn section where a player switches to plunger for a chorus"]}, "fbc6327e-ef36-456f-af17-359e45e33c19": {"definition": "On electric guitar and bass pickups fitted with adjustable pole pieces (individual magnetic slugs or threaded screws under each string), the act of raising or lowering each pole piece to set its magnetic sensing distance to that string, evening out string-to-string output and shaping tone.", "plain_english": "It is turning or raising the little metal studs under each string on a pickup. You do this so every string comes through at the same volume.", "purpose_function": "It corrects uneven string-to-string loudness caused by string gauge, fretboard radius and pickup position, giving a balanced output across the neck.", "practical_application": "A tech sets overall pickup height first, then, on pickups with adjustable poles, tweaks individual pole pieces (often roughly following the fretboard radius) while playing each string, checking that no pole sits so close it disturbs the string.", "category": "Pickup setup", "related_terms": ["Pickup height", "Single-coil pickup", "Humbucker", "String action", "Fretboard radius"], "common_mistakes": ["Setting the pole pieces or whole pickup too close to the strings, so the magnets' pull dampens string vibration and causes warbling, false overtones and intonation problems, worst on the low strings", "Adjusting pole pieces to fix a volume imbalance that is actually caused by uneven pickup height or setup", "Trying to force fixed, non-adjustable pole pieces, risking damage to the pickup"], "scenario_contexts": ["Balancing string output after a guitarist switches to a different string gauge", "Evening out a Strat-style bridge single-coil that sounds thin on the high E", "Setting up a bass so the D and G strings match the E and A in level"]}, "dcfb442d-31bd-4512-a20d-6c6d48b64a1a": {"definition": "A heavy, sound-damping mute designed to reduce an instrument's output to a very low level for quiet practice, prioritising volume reduction over tone quality; on brass it is a dense mute that seals much of the bell, and on bowed strings it is a heavy metal or rubber-covered mute clamped onto the bridge.", "plain_english": "It is a heavy mute you fit to a brass or string instrument. It lets you practise quietly without bothering others. The trade-off is that it changes the normal tone.", "purpose_function": "It exists purely to let a player rehearse fingering, articulation and endurance quietly, such as in a hotel or apartment, where full volume is not possible.", "practical_application": "Players and techs know practice mutes are not for recording or performance because they choke the tone and raise blowing or bowing resistance, and many brass practice mutes also push the pitch sharp.", "category": "Instrument mute", "related_terms": ["Plunger mute", "Straight mute", "Sordino", "Bridge", "Mute"], "common_mistakes": ["Using a practice mute as a performance or recording mute — it deadens the tone and is not meant to be heard", "On brass, ignoring that a tight practice mute raises back-pressure and typically pushes pitch sharp", "Over-tightening a heavy metal string practice mute onto the bridge, risking bridge damage"], "scenario_contexts": ["A trumpeter practising quietly in a hotel room", "A violinist warming up backstage without disturbing others", "A student doing late-night endurance and technique drills in an apartment"]}, "99df89f7-2311-44ab-bcaf-1c09f95efa73": {"definition": "On a pipe organ, the Principal (also called Diapason) is the foundational family of open, cylindrical flue stops that produces the organ's characteristic, distinctly 'organ-like' tone — neither flute-like nor string-like; principals of different pitches together form the 'principal chorus' that is the backbone of the organ's sound.", "plain_english": "It is the classic core 'organ' sound. It comes from the main set of pipes that give an organ its trademark voice. It is fuller than the softer flute or thinner string sounds.", "purpose_function": "The principal chorus provides the organ's tonal foundation and blend, the reference sound against which flutes, strings and reeds are balanced.", "practical_application": "When recording or reinforcing an organ, engineers treat the principal chorus as the core body of the sound and place main mics to capture its blend in the room, since it carries the fundamental weight of the instrument.", "category": "Organ stop", "related_terms": ["Registration", "Diapason", "Flue pipe", "Rank", "Register switch"], "common_mistakes": ["Confusing the Principal (diapason) with flute stops — principals have a fuller, more focused 'organ' tone", "Assuming 8' is the only principal pitch; principals exist at 16', 8', 4', 2' and within mixtures", "Treating 'principal' as one pipe rather than a whole rank spanning the keyboard"], "scenario_contexts": ["Choosing the principal chorus as the foundation when registering a hymn accompaniment", "Placing main mics to capture a pipe organ's diapason chorus in a cathedral", "Balancing an organ's principals against added reeds for a full 'plenum' sound"]}, "ef75a95b-6c7d-4498-882f-411a02b6af9c": {"definition": "On a woodwind instrument, a key that opens a small vent (register or speaker hole) to help the air column overblow to a higher register; on the clarinet the register (speaker) key sounds a twelfth higher, while on oboe, bassoon and saxophone the equivalent octave key or keys sound an octave higher.", "plain_english": "It is a key, usually for the left thumb. A woodwind player presses it to jump a note up into the higher range.", "purpose_function": "It destabilises the fundamental so the pipe more readily sounds a higher harmonic, extending the instrument's range beyond its lowest register.", "practical_application": "Players and repair techs check that the register-key vent seals when closed and opens fully when pressed, since a leaking or misadjusted register key causes squeaks, poor response and tuning problems in the upper register.", "category": "Woodwind key", "related_terms": ["Register switch", "Octave key", "Tone hole", "Overblowing", "Pad"], "common_mistakes": ["Calling the clarinet's register key an 'octave key' — it produces a twelfth, not an octave", "Blaming squeaks solely on embouchure when a leaking register-key pad is the real cause", "Overlooking that a bent or misadjusted register vent throws the whole upper register out of tune"], "scenario_contexts": ["A clarinettist crossing the 'break' from the chalumeau into the clarion register", "A repair tech regulating and re-padding a leaking register or speaker key", "A saxophonist using the automatic octave mechanism to reach the upper octave"]}, "f6d924f4-dbec-4daf-8081-5969960e1ef6": {"definition": "A switch, tab, slide or coupler that selects which set(s) of reeds or pipes (registers, or ranks) sound on an instrument, changing its timbre and/or octave; it is most familiar as the register switches (couplers) on accordions and harmoniums and as the register tabs on organs, which turn ranks on and off.", "plain_english": "It is a button or lever that turns sets of reeds or pipes on and off. It changes the instrument's sound or octave. The tabs on an accordion work this way.", "purpose_function": "It lets a player instantly reconfigure the instrument's voice — brighter, mellower, or shifted an octave — without changing fingering, by combining or isolating registers.", "practical_application": "When miking an accordion or organ, engineers note that engaging different register switches changes both the frequency content and the level, so they re-check tone and gain as registrations change.", "category": "Register control", "related_terms": ["Register key", "Registration", "Principal stop", "Coupler", "Rank"], "common_mistakes": ["Confusing a register switch (which selects whole ranks) with a woodwind register key (which vents a single note up)", "Assuming register switches only change octave — many change timbre by adding or removing reed or pipe ranks", "On accordion, forgetting that changing registers mid-performance shifts level and tone, affecting mic balance"], "scenario_contexts": ["An accordionist switching from a single-reed 'clarinet' register to a full 'musette'", "Selecting register tabs on a combo or electronic organ for a given song", "Balancing mics on a harmonium as the player changes register stops"]}, "b112f458-a434-4505-8364-4e525413cd58": {"definition": "In organ (and by extension harpsichord and accordion) playing, registration is the art and act of selecting and combining an instrument's stops (registers) to produce a desired tone colour, volume and pitch for a piece or passage; it also names the specific combination of stops chosen.", "plain_english": "Registration means choosing which stops to switch on. Stops are sets of pipes or reeds. You pick them to get the sound you want from an organ for a piece.", "purpose_function": "It gives the organist control over timbre and dynamics on an instrument that has no touch-sensitive volume, by combining ranks rather than by playing harder or softer.", "practical_application": "Organists mark registration changes in the score and use preset combination pistons to switch quickly, and engineers recording an organ follow those changes because they alter the captured frequency balance and level.", "category": "Organ technique", "related_terms": ["Principal stop", "Register switch", "Stop", "Coupler", "Diapason"], "common_mistakes": ["Confusing registration (the selection of stops) with 'register' (a pitch range of the instrument)", "Assuming louder registration just means more stops — balance and blend matter more than sheer number", "Ignoring that adding high-pitched stops such as mixtures changes brightness, not just volume"], "scenario_contexts": ["An organist setting combination pistons before a recital for quick registration changes", "Choosing a soft flute registration for an accompaniment versus full organ for a final hymn verse", "A recording engineer tracking registration changes that shift the organ's spectral balance"]}, "82a241d1-cf6b-485d-b6e5-fa1896549e91": {"definition": "A banjo fitted with a resonator — a bowl- or dish-shaped back (usually wood, sometimes metal) attached to the rear of the pot/rim that encloses the back of the head and reflects the sound forward toward the listener. Compared with an open-back banjo it gives greater volume, projection and a brighter, more cutting tone, and is the type most associated with bluegrass playing.", "plain_english": "A banjo with a rounded back bolted on behind the drum-like head. That back acts like a bowl that throws the sound forward, making it louder and punchier than an open-back banjo.", "purpose_function": "The resonator redirects sound that would otherwise escape out the back of the instrument, increasing loudness and forward projection and reinforcing higher frequencies for a crisper attack.", "practical_application": "A resonator banjo is louder and more directional, so in the studio a technician mics it from the front (often angled toward the head near the bridge) and manages its bright, transient-rich attack; the resonator can usually be unbolted for head maintenance or a softer, open-back sound.", "category": "Acoustic instruments", "related_terms": ["Resonator cone", "Single-cone resonator", "Sound hole", "Banjo head", "Bridge"], "common_mistakes": ["Confusing the banjo resonator with a resonator (resophonic) guitar cone — the banjo resonator is a solid reflective back, not a vibrating aluminum diaphragm", "Assuming every banjo has a resonator; clawhammer and old-time players often use open-back banjos, which sound and mic quite differently", "Cross-threading or overtightening the resonator thumbscrews/lugs when removing or refitting the back"], "scenario_contexts": ["Close-miking a bluegrass resonator banjo in the studio and taming its loud, bright attack", "Choosing between an open-back and a resonator banjo to match a track's volume and tone", "Removing the resonator to replace or re-tension the head during maintenance"]}, "03c455ff-5cbe-4a0d-9a12-16f1c8effbb6": {"definition": "The spun aluminum cone at the heart of a resonator (resophonic) guitar that serves as a mechanical loudspeaker diaphragm: the bridge transfers the strings' vibration to the cone, which radiates it as sound. Designs use either a single cone (with a 'biscuit' or an inverted 'spider' bridge) or three linked cones (tricone).", "plain_english": "A thin metal cone inside a resonator guitar. It works like a small loudspeaker. The strings shake the bridge. The bridge shakes the cone. Then the cone pushes air to make the loud, metal sound.", "purpose_function": "It mechanically amplifies and colors the string energy so the guitar projects louder than a wooden-top acoustic, giving the characteristic bright, metallic 'bark'; it was originally devised to make guitars loud enough to cut through a band before electric amplification.", "practical_application": "A technician recording a resophonic guitar aims a mic near the coverplate/cone area (often with a second mic on the neck) and keeps the cone and bridge correctly seated and pre-loaded, since a loose or wrongly pressured cone rattles or buzzes.", "category": "Instrument components", "related_terms": ["Single-cone resonator", "Resonator banjo", "Sound hole", "Spider bridge", "Biscuit bridge"], "common_mistakes": ["Thinking the cone is a passive reflector like a banjo resonator; it is an active vibrating diaphragm driven by the bridge", "Setting incorrect spider- or biscuit-to-cone pressure, causing buzzes, rattles or weak output", "Denting or mishandling the thin aluminum cone, which permanently changes its tone"], "scenario_contexts": ["Miking a Dobro/National-style resonator guitar for a blues or bluegrass track", "Diagnosing a buzz traced to a misseated cone or bridge during setup", "Comparing single-cone and tricone tone when selecting an instrument for a session"]}, "63396b21-003a-4a69-835f-550de8ba358e": {"definition": "A loudspeaker system, exemplified by the Leslie, in which sound is projected through rotating elements — typically a spinning treble horn and a spinning bass drum/rotor — so their motion imposes continuous amplitude and pitch (Doppler) modulation on the sound. It produces the swirling tremolo/chorale effect classically paired with the Hammond organ, and is also used on guitar and other sources.", "plain_english": "A speaker whose horn and drum physically spin, so the sound seems to swirl and wobble as it reaches you. It is the whooshing, rotating effect famous on Hammond organs.", "purpose_function": "The mechanical rotation creates natural Doppler (pitch) and volume modulation that a fixed speaker cannot, giving a rich, animated 'sound in motion' rather than a static tone.", "practical_application": "In the studio a rotary/Leslie cabinet is usually captured with separate mics on the upper (horn) and lower (bass) rotors — often two on top for stereo and one on the bottom — to catch the swirl; the effect is also emulated by pedals and plug-ins.", "category": "Amplification", "related_terms": ["Rotor speed", "Rotary-speaker brake", "Doppler effect", "Tremolo", "Amplifier"], "common_mistakes": ["Calling the swirl 'tremolo' only — it is combined amplitude AND Doppler pitch modulation produced by the physical rotation", "Miking a rotary cabinet with a single static mic, which misses the stereo swirl created by separating the horn and bass rotors", "UNSAFE: reaching into an open Leslie cabinet while the horn/drum are spinning, or servicing/moving it without unplugging — the rotors and the internal tube amp present moving-part and mains/high-voltage shock hazards"], "scenario_contexts": ["Recording a Hammond organ through a Leslie with top and bottom mics", "Using a rotary speaker on electric guitar or vocals for a swirling texture", "Switching between chorale and tremolo during a solo for expressive effect"]}, "f952a847-e290-4ba9-8eb7-060dbc146191": {"definition": "A control mode on a rotary (Leslie-type) speaker or its emulation that stops the rotors, holding the horn and drum stationary so the sound becomes fixed and un-modulated. On many cabinets it is a third position (Stop/Brake) alongside Slow (chorale) and Fast (tremolo), sometimes with an adjustable braking time.", "plain_english": "A 'stop' setting that halts the spinning parts of a rotary speaker, so the swirl freezes and you hear a plain, steady tone.", "purpose_function": "It lets the player instantly kill the rotation for a dry, static sound — useful for held chords or a sudden contrast — instead of waiting for the rotors to coast down on their own.", "practical_application": "A keyboardist footswitches the brake to stop the swirl on a sustained passage; a technician setting up a modern Leslie or a plug-in can dial the brake/stop time — how long the rotors take to halt.", "category": "Amplification", "related_terms": ["Rotary speaker", "Rotor speed", "Doppler effect", "Tremolo"], "common_mistakes": ["Assuming 'brake' means the slow speed — brake stops the rotors entirely, whereas slow (chorale) still rotates", "Expecting an instant stop; real rotors, especially the heavy bass drum, coast for a second or more unless a fast brake time is set", "Confusing the momentary stop with power-off — braking holds the rotors while the amplifier stays live"], "scenario_contexts": ["Footswitching a Leslie to a dead stop for a sustained organ chord", "Setting the brake/stop time on a Leslie 2101 or a rotary plug-in", "Contrasting a static braked passage against a fast tremolo build"]}, "97d0951a-af75-408c-8601-b543dbccce36": {"definition": "The rate of rotation of a rotary speaker's horn and bass rotors, conventionally switchable between two settings: 'slow' (chorale), a gentle warble of roughly 40 RPM, and 'fast' (tremolo), on the order of 340–400 RPM. The horn and bass rotors run at somewhat different speeds and accelerate/decelerate at different rates when the setting is changed.", "plain_english": "How fast the spinning parts of a rotary speaker turn. There are two speeds — a slow, gentle wobble and a fast, intense whirl — and you switch between them for effect.", "purpose_function": "Changing rotor speed changes the depth and rate of the swirl; switching from slow to fast, and the ramp in between, is a core expressive gesture of the Hammond/Leslie sound.", "practical_application": "A player toggles chorale/tremolo mid-performance; an engineer or programmer setting up a real or emulated Leslie adjusts the target RPMs and the acceleration (rise/fall) times to match a classic cabinet.", "category": "Amplification", "related_terms": ["Rotary speaker", "Rotary-speaker brake", "Doppler effect", "Tremolo"], "common_mistakes": ["Believing the horn and bass rotor spin at the same speed — they run at different RPMs, which is part of the characteristic sound", "Ignoring the ramp: the effect is as much about the acceleration between slow and fast as the final speeds", "Confusing 'stop/brake' with 'slow' — slow still rotates, whereas stop halts the rotors"], "scenario_contexts": ["Switching from chorale to tremolo during an organ solo", "Dialing target RPM and ramp times when configuring a Leslie emulation", "Matching a plug-in's rotor speeds to a vintage Leslie for a session"]}, "c01b4822-3487-44a3-9de7-9f6819541d7a": {"definition": "A headphone (and usually line/aux) output built into a 'silent' or practice instrument or amplifier that carries the pickup signal for private monitoring, so the player hears the instrument through headphones while it makes little or no acoustic sound in the room. Yamaha's SILENT Guitar and SILENT Violin series are typical, pairing a non-resonant body with an onboard preamp, a PHONES jack and often an aux input for playing along.", "plain_english": "A headphone jack on a quiet practice instrument or amp. You can hear yourself through earphones. This lets you play without bothering anyone. The instrument itself barely makes any sound out loud.", "purpose_function": "It allows realistic practice at any hour without acoustic noise, and doubles as a convenient direct output to an amp, mixer or recorder.", "practical_application": "A player plugs headphones into the PHONES jack of a Silent Guitar or Violin — often feeding a backing track into the aux input — to practice quietly; an engineer can instead take the LINE OUT of the same instrument straight into a DI or interface for recording.", "category": "Instrument features", "related_terms": ["Solid-body violin", "Sound hole", "Line out", "Aux in", "Piezo pickup"], "common_mistakes": ["Assuming the headphone output means the instrument is truly silent — the strings still make a faint acoustic sound", "Plugging the headphone/line output into a mic-level input and overloading it (or the reverse) instead of matching levels", "Forgetting the output is only active when the onboard preamp/battery is powered on"], "scenario_contexts": ["Practicing a Silent Violin or Guitar on headphones late at night", "Feeding a backing track into the aux input while monitoring on headphones", "Taking the instrument's line output directly into an audio interface to record"]}, "36452dd2-e482-4c3d-8a0a-76cd20a2e05f": {"definition": "A resonator (resophonic) guitar design that uses one resonator cone rather than three (tricone). Two variants exist: the 'biscuit' type, where the bridge sits on a small wooden 'biscuit' at the apex of an outward-facing cone, and the 'spider' type, where a cast aluminum 'spider' bridge rests on the rim of an inward-facing (concave) cone.", "plain_english": "A resonator guitar built around a single metal cone instead of three. The one cone can face outward with a small bridge on its point (biscuit) or face inward with a spider-shaped bridge across it.", "purpose_function": "The single-cone layout gives a louder, punchier, more mid-forward and metallic voice than the sweeter three-cone (tricone) design, and is simpler to build; it is the classic sound of blues (biscuit) and bluegrass Dobro (spider) playing.", "practical_application": "When recording, the technician identifies whether it is a biscuit or spider single-cone (they project and sound differently) and positions mics accordingly, and during setup ensures correct cone/bridge pressure and seating to avoid buzzes.", "category": "Acoustic instruments", "related_terms": ["Resonator cone", "Resonator banjo", "Sound hole", "Spider bridge", "Biscuit bridge"], "common_mistakes": ["Assuming all resonator guitars have one cone — tricone models use three linked cones and sound noticeably sweeter and quieter", "Mixing up biscuit and spider single-cones; the cone faces opposite directions and the bridges are completely different", "Setting up a spider bridge with the wrong pressure, causing rattles or a choked, weak tone"], "scenario_contexts": ["Recording a biscuit single-cone National for slide blues", "Recording a spider-cone Dobro for a bluegrass session", "Choosing single-cone versus tricone based on the desired volume and brightness"]}, "b27596eb-4ab1-4b1a-8230-535104af7bd1": {"definition": "An electric violin built on a solid (non-hollow) body with no acoustic soundbox, so it produces very little sound on its own and relies on a pickup — typically a piezo transducer under the bridge — feeding an amplifier or interface. The absence of a resonating cavity reduces feedback and lets the amplified tone be shaped electronically.", "plain_english": "An electric violin with a solid body and no hollow space inside. So it is almost silent unless you plug it in. A pickup turns the string shakes into a signal for an amp. This works much like a solid-body electric guitar.", "purpose_function": "The solid body makes the instrument quiet acoustically (good for silent practice and loud stages) and highly resistant to feedback, while the pickup and preamp let the player amplify and tailor the sound.", "practical_application": "On a loud stage a solid-body electric violin resists the feedback that plagues a mic'd acoustic violin; in the studio the engineer records it via DI from its pickup output, adding reverb and EQ to restore an acoustic-like body.", "category": "Electric instruments", "related_terms": ["Silent practice output", "Sound hole", "Piezo pickup", "Line out", "Direct box (DI)"], "common_mistakes": ["Expecting an acoustic violin tone straight from the pickup — with no soundbox the raw signal is thin and usually needs EQ and reverb", "Miking a solid-body violin like an acoustic one, when a direct line/pickup feed is the correct approach", "Assuming 'solid body' means completely silent; the bowed strings still produce a faint acoustic sound"], "scenario_contexts": ["Playing amplified on a loud stage without feedback", "Silent practice through headphones on an electric violin", "Recording the pickup output via DI and adding reverb in the mix"]}, "f697edc8-e094-4683-833d-2ce8e43c53fd": {"definition": "An opening cut in the soundboard (top) of a stringed instrument — a round hole on a guitar, paired f-holes on the violin family — that couples the enclosed body air to the outside. With the body cavity it forms a Helmholtz-type resonator whose lowest air resonance (around 100 Hz on a guitar) reinforces the low end and helps radiate sound.", "plain_english": "The hole (round on a guitar, the two f-shaped slots on a violin) in the instrument's top. It lets the air inside pump in and out, boosting the low notes and helping the sound get out — like blowing across a bottle to make a tone.", "purpose_function": "It vents the vibrating air mass inside the body so the cavity acts as a Helmholtz resonator, adding a low-frequency resonance that strengthens the bass and radiates energy the top plate alone would not.", "practical_application": "A recording engineer treats the sound hole as a low-frequency hotspot: aiming a mic straight into it gives a boomy, bass-heavy sound, so mics are usually placed toward the 12th fret or bridge instead, and a soundhole cover can be fitted to fight feedback when the instrument is amplified.", "category": "Instrument components", "related_terms": ["Resonator cone", "Solid-body violin", "Soundboard", "Bridge", "Helmholtz resonance"], "common_mistakes": ["Miking directly at the sound hole and capturing an overly boomy, bass-heavy recording", "Thinking the hole simply 'lets sound out' — it actually forms a tuned air (Helmholtz) resonance with the body cavity", "Covering the sound hole without realizing it shifts the low-frequency response (though a cover is a valid anti-feedback tool)"], "scenario_contexts": ["Positioning an acoustic-guitar mic away from the sound hole to avoid boom", "Fitting a soundhole cover to stop feedback on an amplified acoustic", "Explaining why a guitar has a strong low-frequency 'air' resonance around 100 Hz"]}, "18df5655-a080-438b-a47e-9b9764d78953": {"definition": "A removable disc or plug fitted over or into the sound hole of an acoustic (or acoustic-electric) guitar to damp the instrument's principal air (Helmholtz) resonance; it is used chiefly to suppress low-frequency acoustic feedback when the guitar is amplified.", "plain_english": "A cap that seals the round hole of an acoustic guitar. Blocking the hole tames the boomy resonance that makes an amplified acoustic guitar howl with feedback.", "purpose_function": "The guitar body and sound hole form a Helmholtz resonator with a strong low-frequency peak; covering the hole shifts and damps that peak so the amplified signal is far less likely to build into feedback. It exists to let acoustic guitars be played at higher stage levels without runaway feedback.", "practical_application": "A technician or player fits a sound-hole cover when an acoustic-electric guitar feeds back through the PA or monitors, trading a little unplugged low-end response for much greater gain-before-feedback.", "category": "Guitar accessory", "related_terms": ["Soundboard", "Steel-string acoustic guitar", "Stage volume", "Acoustic feedback", "String resonance"], "common_mistakes": ["Assuming a sound-hole cover cures all feedback; it mainly tames the low-frequency body/air resonance, not higher-frequency top or room-mode feedback", "Expecting no tonal change, when blocking the sound hole clearly reduces the acoustic low-end and overall unplugged loudness", "Forcing an ill-fitting cover into the hole hard enough to scratch or crack the top around the rosette"], "scenario_contexts": ["An acoustic-electric guitar howls through the monitors at a loud stage volume, and fitting a sound-hole cover restores usable gain", "A guitarist DI'd into a small PA in a boomy room uses a cover to cut low-frequency feedback", "A player who gigs amplified keeps a cover in the case even though the same guitar records fine uncovered"]}, "697925db-efee-4466-97b2-38b78a44efca": {"definition": "The thin, resonant plate (the top or belly) of a stringed instrument — such as a guitar top, violin belly, or piano soundboard — that receives string vibration through the bridge and radiates it efficiently as sound.", "plain_english": "The large flat piece of wood the strings sit over. The strings alone are too thin to be loud, so their vibration is passed to this board, which moves a lot of air and makes the sound you hear.", "purpose_function": "A vibrating string moves very little air by itself; the soundboard couples that vibration to a large radiating surface, greatly increasing acoustic output and shaping the instrument's tone. It exists to turn faint string motion into audible, timbrally rich sound.", "practical_application": "When miking an acoustic guitar, piano, or violin, engineers aim at or around the soundboard because that surface, not the strings, radiates most of the sound; its bracing and wood largely set the instrument's character.", "category": "Instrument acoustics", "related_terms": ["Steel-string acoustic guitar", "Sound-hole cover", "String resonance", "Spider bridge", "Bridge"], "common_mistakes": ["Confusing the instrument soundboard with a mixing 'soundboard' (console); they are unrelated uses of the word", "Believing the strings produce the volume, when the soundboard and body do the radiating", "Close-miking only the strings or neck and missing the main radiating surface"], "scenario_contexts": ["Choosing acoustic-guitar mic placement by referencing the soundboard rather than the strings", "Explaining why a solid-top guitar is louder and more resonant than a laminate-top one", "Understanding why resting a hand on the top of an instrument reduces its output"]}, "02542491-f422-4917-81b5-ec94492f02b9": {"definition": "A cast-aluminum, spider-shaped bridge used on single-cone resonator guitars, whose several legs radiate outward to rest on the rim of an inverted ('Dobro-style') resonator cone; the saddle sits at the hub, so string vibration is carried down the legs to the perimeter of the cone.", "plain_english": "This is a metal, spider-legged piece on a resonator (Dobro) guitar. It sits on top of the cone. The strings press down on its center. Its legs carry the shaking out to the edge of the metal cone. That cone gives the guitar its loud, ringing tone.", "purpose_function": "It transfers string energy to the outer edge of an inverted resonator cone, which then radiates the characteristic bright, cutting resonator sound; the spider drives the cone at its rim rather than its center. It is the mechanical link between strings and cone in spider-type resonators.", "practical_application": "A tech setting up a Dobro-style resonator adjusts action by shaping the maple saddle in the spider and seats the spider squarely on the cone for clean coupling; this contrasts with the 'biscuit' bridge used on forward-facing single cones.", "category": "Resonator guitar hardware", "related_terms": ["Soundboard", "Steel-string acoustic guitar", "Bridge", "Resonator cone", "Biscuit bridge"], "common_mistakes": ["Confusing the spider bridge (inverted cone, driven at the rim) with the biscuit bridge (forward-facing cone, driven at the center)", "Misseating the spider so it does not sit flat on the cone, which kills volume and sustain", "Assuming any resonator cone fits, when spider cones and biscuit cones are not interchangeable"], "scenario_contexts": ["Setting string action on a bluegrass Dobro by shaping the spider's wooden saddle", "Diagnosing a buzzing or dead resonator traced to a spider not seated flat on the cone", "Choosing the correct cone-and-bridge system when repairing a spider-type resonator guitar"]}, "49fa7647-8a3b-4200-82f2-ce690e91790f": {"definition": "The acoustic sound-pressure level present on stage — produced by instrument amplifiers (backline), drums, and stage monitors — as distinct from the level the main PA delivers to the audience.", "plain_english": "How loud it really is on the stage itself. This sound comes from the amps, the drums, and the monitor speakers. It is not about how loud the speakers are for the crowd.", "purpose_function": "Stage volume is what the musicians hear and what leaks into the microphones, so managing it is central to monitor mixing, gain-before-feedback, and hearing safety. It matters because excessive stage volume degrades the front-of-house mix and endangers hearing.", "practical_application": "A live engineer works to keep stage volume down — asking players to turn down backline, deploying in-ear monitors, or angling amps — so open microphones pick up less bleed and the PA, not the stage, defines what the audience hears.", "category": "Live sound", "related_terms": ["Sound-hole cover", "Stage monitor", "In-ear monitors", "Acoustic feedback", "Microphone bleed"], "common_mistakes": ["UNSAFE: Tolerating very high stage volume without hearing protection; sustained high SPL on stage risks noise-induced hearing loss and must be managed within OSHA 29 CFR 1910.95 occupational-noise limits", "Believing louder backline improves the audience mix, when it usually just adds bleed and feedback and muddies front-of-house", "Answering 'I can't hear myself' by turning up rather than fixing the monitor mix, which escalates the whole stage level"], "scenario_contexts": ["A loud guitar amp causes vocal mics to feed back, so the engineer reduces stage volume", "A band switches to in-ear monitors to lower stage volume and clean up front-of-house", "Setting up in a small, hard-walled room where high stage volume overwhelms the PA"]}, "7086ab9d-a3ee-4e57-826f-473569b0eed5": {"definition": "An acoustic guitar strung with steel (metal) strings rather than nylon, typically built with a strengthened, X-braced top to withstand the higher string tension; it produces a brighter, louder, more sustaining tone than the nylon-string classical guitar.", "plain_english": "The common folk acoustic guitar. It has bright metal strings. A classical guitar uses softer nylon strings instead. The metal strings pull harder. So the body is built stronger. The sound is louder and brighter too.", "purpose_function": "Steel strings and X-bracing give the volume, brightness, and sustain suited to folk, country, rock, and pop; the reinforced top and neck exist specifically to handle the greater tension steel strings impose.", "practical_application": "In the studio it is the default 'acoustic guitar,' usually recorded with a condenser near the 12th fret and soundboard; a tech fits steel-appropriate strings and sets neck relief accordingly, never fitting nylon-guitar strings.", "category": "Acoustic instrument", "related_terms": ["Soundboard", "Sound-hole cover", "String resonance", "Spider bridge", "Classical guitar"], "common_mistakes": ["Fitting steel strings to a guitar built for nylon, whose far higher tension can bow or crack a classical guitar's lightly built top and neck", "Assuming all acoustic guitars are steel-string, when classical and flamenco guitars use nylon and are built lighter", "Treating string gauge as the only tone factor and ignoring body size, bracing, and wood"], "scenario_contexts": ["Recording a singer-songwriter track with a condenser on a steel-string acoustic", "Restringing and setting neck relief on a dreadnought before a session", "Choosing between a steel-string and a nylon classical for a bright, cutting rhythm part"]}, "41e3628f-4616-4b05-b548-4b8e8e1003a5": {"definition": "In the pipe organ, a stop is a complete rank (set) of pipes of one tone colour together with its controlling mechanism; drawing the stop knob admits wind so that rank can sound, and pushing it in silences that rank.", "plain_english": "On a pipe organ, a 'stop' is one full set of pipes that share a sound, plus the knob that turns it on or off. Pulling the knob out lets that set play; pushing it in shuts it off — the origin of 'pulling out all the stops.'", "purpose_function": "Stops let the organist select and combine tone colours and pitches (registration) by choosing which sets of pipes speak. They exist to give a single keyboard access to many voices and volumes.", "practical_application": "An organist or technician refers to individual stops by name and pitch (for example an 8-foot Diapason) when registering a piece or diagnosing a rank that will not sound; a stuck stop action is a common service call.", "category": "Organ", "related_terms": ["String stop", "Rank", "Registration", "Diapason", "Soundboard"], "common_mistakes": ["Thinking a stop is a single pipe, when it is an entire rank plus its control", "Assuming 'pulling out a stop' changes the pitch of the keys, when it selects which rank or voice sounds", "Confusing an organ 'stop' with a string player 'stopping' a note; these are unrelated concepts"], "scenario_contexts": ["Registering a hymn by drawing and retiring specific stops", "A technician tracing why one stop's rank fails to speak", "Explaining 'pull out all the stops' when introducing organ registration"]}, "26bfd732-eb1b-4b0f-91d8-12bf1bc28823": {"definition": "A hollow, cone-shaped mute — traditionally spun aluminum, also fibre or cardboard — held in the bell of a brass instrument by strips of cork; it partially closes the bell to reduce volume and produce a bright, nasal, penetrating tone rich in upper harmonics.", "plain_english": "A cone you push into the bell of a trumpet or trombone, held by little cork strips. It makes the instrument quieter and gives it a thin, buzzy, edgy sound.", "purpose_function": "The straight mute both lowers overall level and reshapes the timbre, emphasizing high partials for a pinched, brilliant colour used throughout orchestral and jazz writing. It exists to give brass a distinct muted voice on demand.", "practical_application": "A brass player inserts a straight mute where a part is marked muted or con sordino; in recording, its brighter, more directional output often calls for adjusted mic placement or a little high-frequency taming.", "category": "Brass mute", "related_terms": ["Cup mute", "Harmon mute", "Bell", "Con sordino", "Stop"], "common_mistakes": ["Confusing the straight mute's bright, nasal sound with the cup mute's darker, more muffled sound", "Assuming a mute only lowers volume, when it also strongly changes timbre", "Forcing the mute in too far or using damaged cork, which jams it in the bell and alters intonation"], "scenario_contexts": ["A trumpet section adds straight mutes for a bright, biting fanfare", "Adjusting a mic on a muted trumpet whose tone is thinner and more directional", "Reading 'straight mute' in a score and selecting it over a cup or Harmon mute"]}, "c2652ee6-7674-435a-b81f-c8dc4796591f": {"definition": "The tendency of a string to vibrate at its natural (resonant) frequencies; in practice it most often refers to sympathetic resonance, in which an undamped string is set ringing by sound at one of its natural frequencies produced elsewhere on the same or a nearby instrument.", "plain_english": "When you play one note, other strings tuned to related pitches start humming along on their own. That sympathetic ringing is string resonance.", "purpose_function": "String resonance enriches and sustains an instrument's tone by adding sympathetic overtones, but uncontrolled it also creates unwanted ringing; understanding it lets players and engineers either exploit or suppress it.", "practical_application": "When recording guitar or piano, engineers hear open, undamped strings ringing sympathetically and may mute them (capo, felt, or palm) to clean up a track, or leave them for a fuller, more resonant sound.", "category": "Instrument acoustics", "related_terms": ["Soundboard", "Steel-string acoustic guitar", "Sound-hole cover", "Sympathetic vibration", "Damping"], "common_mistakes": ["Confusing sympathetic string resonance with feedback; resonance is acoustic coupling between strings and bodies, not an amplified loop", "Blaming 'ringing' on a fault when it is simply undamped open strings resonating sympathetically", "Forgetting to mute unused strings, leaving sympathetic ring in a recorded take"], "scenario_contexts": ["Muting open strings on an acoustic guitar to stop sympathetic ring in a close-miked take", "Noticing that lifting piano dampers lets strings resonate sympathetically", "Deliberately allowing string resonance for a fuller, sustaining acoustic tone"]}, "fdb3a87d-d95f-4892-ad25-6398271a4458": {"definition": "In the pipe organ, a string stop (string-toned stop) is a flue stop of narrow ('keen') scale voiced to imitate the bright, thin, sustained tone of orchestral strings; examples include the Salicional, Viola or Gamba, and Dulciana.", "plain_english": "On a pipe organ, this is a set of thin pipes. They are tuned to sound like violins or violas. The tone is thin and keen, like strings. It is not a full flute or trumpet sound.", "purpose_function": "String stops add a keen, quiet, string-like colour to the organ's palette for accompaniment and orchestral effects, and several combined build up organ string tone. They exist to give the organ imitative orchestral-string voices.", "practical_application": "An organist selects string stops (for example a Salicional against a Céleste) for soft, shimmering accompaniment, and a technician voices their narrow-scale pipes to obtain the characteristic keen edge.", "category": "Organ", "related_terms": ["Stop", "Rank", "Registration", "Diapason", "Céleste"], "common_mistakes": ["Confusing string stops (thin, keen) with flute or diapason stops (fuller, rounder)", "Assuming 'string' means actual strings, when organ string stops are narrow-scale pipes imitating strings", "Expecting loud output, when most string stops are relatively quiet, accompanimental voices"], "scenario_contexts": ["Registering a soft accompaniment with a Salicional string stop", "Combining a string stop with a Céleste for a shimmering effect", "Voicing a narrow-scale rank to achieve keen string tone during organ service work"]}, "532dc553-1fcf-495e-bbd5-4d6742466d78": {"definition": "The primary stereo microphone array placed out in front of a string section (or the full body of orchestral strings) to capture the ensemble's overall blended tone, depth and stereo image, as distinct from close 'spot' mics on individual desks. Common realisations include the Decca tree, spaced omnidirectional pairs (A-B) and coincident/near-coincident pairs (XY, ORTF, Blumlein), set at a distance and height that balance direct sound against room sound.", "plain_english": "The main pair of mics placed out front. They catch how the whole string group sounds together in the room. They do not catch each player up close.", "purpose_function": "It establishes the foundational stereo image, sense of space and natural blend of the section, so that spot mics only reinforce detail; the main pair therefore defines the recording's overall tonal balance.", "practical_application": "An engineer sets the main pair (for example a Decca tree or an ORTF pair) at a chosen distance and height, gets that balance right first, then blends in spot mics against it as the reference around which the mix is built.", "category": "Microphone technique", "related_terms": ["Decca tree", "Spot microphone", "ORTF pair", "Spaced pair (A-B)", "Stereo imaging", "Room microphone"], "common_mistakes": ["Placing the main pair too close to the section, which narrows the stereo image and loses the natural room blend and depth.", "Treating the main pair as an afterthought and building the sound from spot mics, which produces an unnatural, phasey balance.", "Ignoring the spacing/angle spec of the chosen array (e.g. ORTF's 17 cm spacing and 110-degree angle), causing a weak or exaggerated image and mono-compatibility problems."], "scenario_contexts": ["Recording a film-score string section on a scoring stage using a Decca tree as the main pair, with outriggers and desk spots added underneath.", "Capturing a string quartet or small ensemble in a good-sounding room with a single near-coincident main pair.", "Balancing a live orchestral broadcast where the main pair carries the stereo image and spot mics add clarity."]}, "030d0966-d876-45e3-a6a2-bec0d6cd53c8": {"definition": "An Italian string-playing instruction meaning 'on the bridge', directing the player to bow very close to (or right on) the bridge. Exciting the string near its termination emphasises the upper harmonics over the fundamental, producing a thin, glassy, metallic timbre.", "plain_english": "A bowing instruction to play right next to the bridge, giving a brittle, glassy, slightly eerie tone.", "purpose_function": "It is a coloristic technique used to change the timbre of a bowed note, exploiting the harmonic-rich sound produced when the string is bowed close to its fixed end; the marking 'modo ordinario' returns the player to normal bowing.", "practical_application": "When an engineer sees 'sul pont.' in a score they can expect a bright, harmonic-heavy sound with strong high-frequency content, and may choose mic placement or gentle EQ to keep it characterful without becoming harsh.", "category": "Bowing technique", "related_terms": ["Sul tasto", "Pizzicato", "Col legno", "Tremolo", "Natural harmonics", "Bowing technique"], "common_mistakes": ["Confusing sul ponticello (on the bridge, bright and glassy) with sul tasto (over the fingerboard, soft and flute-like) — they are opposite timbres.", "Treating it as a dynamic marking; it changes tone colour, not loudness.", "EQ'ing away the characteristic high-harmonic content in the mix, which removes the very effect the composer asked for."], "scenario_contexts": ["A film composer writes a sul ponticello tremolo in the low strings for a tense, shimmering texture.", "Recording a contemporary quartet where sul ponticello passages demand careful mic placement to avoid excessive harshness.", "A player returns to normal bowing after a marked sul ponticello passage within the same phrase."]}, "2f28c2b2-c076-4c56-8b65-db0398a40dca": {"definition": "An Italian string-playing instruction meaning 'on the fingerboard', directing the player to bow over the fingerboard, well away from the bridge. Bowing far from the bridge suppresses the upper harmonics and favours the fundamental, yielding a soft, veiled, flute-like tone (also called flautando).", "plain_english": "A bowing instruction to bow out over the fingerboard. This gives a soft, airy, flute-like tone.", "purpose_function": "It is a coloristic technique used to soften and darken the timbre of a bowed note; because the string is excited far from the bridge, higher partials are weakened, producing a gentle, less-focused sound.", "practical_application": "Seeing 'sul tasto' tells the engineer to expect a quieter, darker, less-present sound with reduced highs, which may need a closer or lower-noise mic setup and gentle handling in the mix.", "category": "Bowing technique", "related_terms": ["Sul ponticello", "Flautando", "Pizzicato", "Natural harmonics", "Tremolo", "Bowing technique"], "common_mistakes": ["Confusing sul tasto (over the fingerboard, soft and flute-like) with sul ponticello (on the bridge, bright and glassy).", "Treating it as a volume marking; it is primarily a timbral change, although the sound is naturally softer.", "Boosting the highs to 'brighten' a sul tasto part in the mix, defeating the intended veiled character."], "scenario_contexts": ["An arranger marks sul tasto for a hushed, atmospheric string pad under a vocal.", "Recording a slow movement where sul tasto passages need extra gain and low-noise mics because of the reduced level and high-frequency content.", "A score alternates sul tasto and ordinario to shift colour within a single phrase."]}, "7175ef95-2bbd-467b-86c0-467b9596e192": {"definition": "The additional ringing resonance produced on a piano when the sustain (damper) pedal is depressed, which lifts all the dampers so that struck strings ring on and the remaining undamped strings vibrate sympathetically with the played notes' harmonics, enriching and prolonging the tone. Sampled and physically modelled pianos reproduce this as a dedicated 'sustain' or 'sympathetic' resonance layer.", "plain_english": "The rich, ringing sound you hear when a pianist holds down the right pedal. That pedal lifts the dampers off the strings. Now all the other strings are free to buzz along. This adds a fuller sound.", "purpose_function": "It gives the piano its full, blended, sustained character; lifting every damper both prolongs the played notes and frees all other strings to resonate in sympathy, thickening the overall sound.", "practical_application": "Recording engineers hear increased sustain and sympathetic ring with the pedal down and mic and balance for it, while sample-library designers record dedicated pedal-down layers to capture the effect realistically.", "category": "Instrument acoustics", "related_terms": ["Sympathetic resonance", "Sustain pedal", "Damper", "Sostenuto pedal", "Overtones"], "common_mistakes": ["Assuming the sustain pedal only prolongs the notes actually played; it also frees every other string to vibrate sympathetically, adding resonance.", "Confusing the sustain (damper) pedal with the sostenuto (middle) pedal, which sustains only the keys already held when it is pressed.", "In sampled pianos, leaving sympathetic/pedal-resonance modelling switched off and then wondering why the tone sounds thin and unrealistic."], "scenario_contexts": ["Close-miking a grand piano for a ballad where heavy sustain-pedal use creates a rich sustained wash that must be balanced against clarity.", "A sample-library developer records dedicated pedal-down layers to capture sustain-pedal resonance.", "A pianist uses half-pedalling to control how much sympathetic resonance builds up."]}, "1af976ad-5318-4dcc-bb33-d4a0da78fb7e": {"definition": "In a pipe organ, an enclosure fitted with movable louvered shutters (swell shades) around a division of pipes; opening and closing those shutters with the swell (expression) pedal varies the loudness of the enclosed pipes. Because organ pipes cannot be made louder or softer by touch, the swell box supplies dynamic control; the enclosed division is commonly the 'Swell'.", "plain_english": "A box built around a set of organ pipes. Its front has slats like window shutters. The organist opens or closes them with a foot pedal. This makes those pipes louder or softer.", "purpose_function": "It gives an otherwise fixed-loudness instrument continuous crescendo and diminuendo, by mechanically opening or closing shutters to let more or less of the enclosed pipes' sound escape.", "practical_application": "When recording a pipe organ, engineers note which divisions are enclosed in a swell box, because the operator's use of the shades changes the dynamics and high-frequency content reaching the microphones.", "category": "Pipe organ", "related_terms": ["Swell pedal", "Expression pedal", "Swell division", "Pipe organ", "Crescendo pedal"], "common_mistakes": ["Thinking the swell box changes pitch or registration; it only controls the loudness/expression of the enclosed pipes.", "Assuming every division is enclosed — typically only some (e.g. the Swell) sit in a box, while the Great is often unenclosed.", "Confusing the swell box (the enclosure) with the swell pedal (the control that operates its shutters)."], "scenario_contexts": ["Recording a church organ where the organist uses the swell shades for crescendos, needing mics positioned to capture the dynamic change.", "A registration relies on the enclosed Swell division for expressive solos over the unenclosed Great.", "An organ technician services the swell-box shutter mechanism and its motor and linkage."]}, "bb7cad32-1464-433e-aa85-e3a21f38aff3": {"definition": "On a pipe organ, the balanced foot pedal (a type of expression pedal) that operates the swell-box shutters, opening them to increase and closing them to decrease the loudness of the enclosed division. By extension, a 'swell' or 'volume' pedal on other instruments (pedal steel, electronic organ, guitar) is a foot pedal that varies output level to create the same swelling of loudness.", "plain_english": "A foot pedal on an organ. It opens and closes the shutters of the swell box. This makes the sound grow louder or softer. Guitar and pedal steel use the same idea with a volume pedal.", "purpose_function": "It provides continuous, hands-free dynamic control, by mechanically opening and closing the swell shutters on an organ, or by varying signal level on an electric instrument.", "practical_application": "An organist rocks the swell pedal for crescendos and diminuendos, while a pedal-steel or guitar player uses a volume (swell) pedal to fade notes in for the characteristic swell effect that engineers capture as smooth level rises.", "category": "Expression control", "related_terms": ["Swell box", "Expression pedal", "Volume pedal", "Swell shades", "Pipe organ"], "common_mistakes": ["Confusing the swell pedal (the control) with the swell box (the shuttered enclosure it operates).", "On an organ, expecting the swell pedal to affect the whole instrument — it only controls divisions enclosed in a swell box.", "Confusing the swell/expression pedal with the crescendo pedal, which progressively adds stops rather than opening shutters."], "scenario_contexts": ["An organist uses the swell pedal to shape a long crescendo during a hymn.", "A pedal-steel or guitar player uses a volume (swell) pedal to fade notes in for pad-like swells the engineer records as smooth level rises.", "An organ technician checks that the swell-pedal linkage tracks the shutters smoothly across the full travel."]}, "de485b7b-1a9b-42ac-968a-3a1076ab3640": {"definition": "A control on electronic keyboards, synthesizers and MIDI/DAW systems that shifts the pitch of everything played up or down by a set number of semitones (and often octaves) without changing the fingering, so a part can sound in a different key from the one performed. It typically re-maps the output note numbers rather than physically retuning the instrument.", "plain_english": "A setting that shifts every note you play up or down. It moves them by a set number of half-steps. So you can play in an easy key but hear a different one. It works like a capo for a keyboard.", "purpose_function": "It lets a performer match a singer's key, or play a transposing instrument's part at concert pitch, by offsetting the played notes by a fixed interval without relearning the part.", "practical_application": "A keyboardist sets transpose (for example +2 semitones) to accommodate a vocalist, or a producer transposes a MIDI track in the DAW; the engineer must note the setting so tuning and key references stay consistent.", "category": "Keyboard function", "related_terms": ["Octave shift", "MIDI note number", "Master tuning", "Pitch bend", "Capo"], "common_mistakes": ["Confusing transpose (shifting pitch by whole semitones) with fine/master tuning (adjusting overall pitch in cents).", "Forgetting the transpose is still engaged, so a later part plays back in the wrong key.", "Assuming transpose rewrites recorded MIDI note data — on many instruments it offsets the output/playback while the underlying part still reads the original notes."], "scenario_contexts": ["A keyboard player transposes up two semitones so a song sits better in the singer's range without relearning it.", "A producer transposes a MIDI instrument track in the DAW to try the arrangement in a new key.", "Using transpose to play a part written for a transposing instrument at concert pitch."]}, "43336a4e-f444-4777-b4d8-492389dc915b": {"definition": "A small circuit — a capacitor, often combined with a parallel or series resistor — wired across the input and wiper terminals of a guitar's volume potentiometer to form a high-pass path, so that high frequencies bypass the pot as the volume is turned down and the treble loss that normally occurs at low settings is prevented. Typical values are on the order of 500 pF to 1 nF capacitance, sometimes with a roughly 100 kOhm to 150 kOhm resistor, tuned by ear.", "plain_english": "A tiny electronic part added across a guitar's volume knob. It keeps the sound bright when you turn the volume down. Without it, the tone goes dull and muddy.", "purpose_function": "It keeps the tone bright and consistent at reduced volume; because a passive volume control together with the guitar cable forms a treble-shedding filter as you turn down, the network shunts the highs around the pot.", "practical_application": "A tech solders a treble-bleed capacitor (and optional resistor) across the volume pot's lugs when a player finds the guitar goes dull as they roll back the volume, then adjusts the values to taste.", "category": "Guitar electronics", "related_terms": ["Volume potentiometer", "Tone capacitor", "Potentiometer taper", "Passive pickup", "High-pass filter", "Guitar wiring"], "common_mistakes": ["Using too large a capacitor value, which passes so much treble that the guitar sounds harsh or thin at low volume.", "Wiring the capacitor to the wrong terminals (e.g. to ground), which alters the tone control instead of preserving treble.", "Assuming one 'correct' value exists — the best capacitor, and whether to add a resistor, depends on the pickups, pot values and taste.", "UNSAFE: Soldering the network without ventilation or eye protection — work per IPC/J-STD-001 practice, avoid inhaling flux fumes, and wash hands after handling lead-bearing solder."], "scenario_contexts": ["A guitar tech installs a treble-bleed on a Stratocaster so the player can use the volume knob for cleanup without losing high end.", "A player who rides the volume control for dynamics adds a treble-bleed to keep the tone consistent from 10 down to 3.", "Comparing a capacitor-only network with a capacitor-plus-resistor network to find the right feel across the volume sweep."]}, "59720aca-91a3-4658-b364-ad30b6401189": {"definition": "The higher-pitched strings, or upper register, of a stringed instrument, as opposed to its bass strings — for example the treble strings of a piano, harp or guitar. On a piano the treble region uses the shorter, thinner strings strung three-to-a-note (trichords); on a standard six-string guitar the treble strings are typically the top three (G, B and high E).", "plain_english": "The higher notes on an instrument like a piano, harp, or guitar. These are the thin, bright strings. They are not the thick, low bass strings.", "purpose_function": "It denotes the instrument's upper register, whose short, thin strings produce the bright, higher-frequency notes; on a piano these are grouped three-to-a-note to boost the otherwise weaker volume and sustain of the top end.", "practical_application": "Engineers position mics to balance the treble-string region against the bass strings — for instance one mic over the treble strings of a grand piano — so the top end has clarity without harshness.", "category": "Instrument anatomy", "related_terms": ["Bass-string region", "Trichord", "Register", "Soundboard", "String scaling"], "common_mistakes": ["Assuming all piano strings are single — treble notes typically use three strings per note while the lowest notes use one or two.", "Miking only the treble strings and losing the bass (or the reverse), instead of balancing both registers.", "Confusing the treble-string region (a pitch register) with string gauge alone — treble strings are thinner, but the term refers to the higher register."], "scenario_contexts": ["Miking a grand piano with one mic over the bass strings and one over the treble-string region for balance.", "A piano tuner addresses false beats and the tuning of the trichords in the treble region.", "Voicing the treble strings of a piano to even out brightness across the register."]}, "05190a26-fbc7-48b1-9652-4fa28fd9447f": {"definition": "In piano construction, the treble-string section is the upper-register portion of the string scale strung with plain (unwound) high-tensile steel wire, in which most notes use three identically tuned unison strings per key (a trichord); it is distinguished from the copper-wound, single- or double-strung bass section.", "plain_english": "The group of high-note strings in a piano. They are thin, bare steel wires. Most notes here use three wires each. They make the bright, high notes. The low strings are thick and wrapped in copper.", "purpose_function": "Using thin plain wire at high tension and grouping three strings per note gives the upper register enough loudness, sustain and bright tone while keeping string length and inharmonicity manageable.", "practical_application": "When miking or tuning a piano, a technician treats this region as the source of note attack and brightness, often favouring a mic position over the treble bridge, and tunes each trichord's unison strings tightly so they do not beat or sound chorused.", "category": "Piano", "related_terms": ["Bass-string section", "Trichord", "Soundboard", "Inharmonicity", "Upright piano", "Una corda"], "common_mistakes": ["Assuming every treble note has three strings — the extreme top and the bass-to-treble transition may have two, so unisons must be checked individually.", "Confusing the plain-steel treble strings with the copper-wound bass strings when restringing or ordering wire gauges.", "UNSAFE: Cutting or releasing high-tension piano wire without eye protection and gloves; a snapping string can whip and cause eye or hand injury."], "scenario_contexts": ["Close-miking a grand piano and placing a mic over the treble strings to capture note clarity and attack.", "A piano technician tuning the treble trichord unisons to eliminate audible beating.", "Replacing a broken plain-wire treble string on a studio upright before a session."]}, "ba0aacd0-fde1-4b61-ae52-86c3298ca04c": {"definition": "A plucked-string technique in which a single note (or a pair of notes) is sounded with very rapid, repeated plectrum or finger strokes — typically fast alternating down-up motion — to produce a sustained, shimmering tone from an instrument whose notes would otherwise decay quickly.", "plain_english": "You pick one note over and over, as fast as you can. A single pluck fades fast. But fast picking makes it sound like one long, buzzing note.", "purpose_function": "It exists to create sustain and a continuous, tremulous timbre on plucked instruments such as the mandolin, guitar and bouzouki, which cannot hold a note the way a bowed or wind instrument can.", "practical_application": "Recording tremolo-picked mandolin or surf/metal guitar means capturing a dense stream of pick attacks, so a technician gain-stages for the transients and watches for string and pick noise that becomes obvious under compression.", "category": "Playing Technique", "related_terms": ["Alternate picking", "Tremolo", "Mandolin", "Sustain", "Transient", "Palm muting"], "common_mistakes": ["Confusing tremolo picking (rapid repeated picking of a note) with a vibrato/'whammy' bar or with an amplitude-tremolo effect pedal — they are unrelated.", "Confusing tremolo (rapid repetition) with vibrato (pitch variation).", "Applying heavy limiting or a slow-responding chain that smears the individual pick attacks into mush."], "scenario_contexts": ["Tracking a mandolin melody whose sustained notes are produced entirely by tremolo picking.", "Recording surf or black-metal guitar built on continuous tremolo-picked lines.", "Editing a comp where tremolo-picked passages must be time-aligned by their pick transients."]}, "1af127a8-7b83-42fb-999f-81e50b792d4a": {"definition": "A metal-bodied resonator guitar design that uses three small spun-aluminum cones linked at their apexes by a T-shaped bridge assembly to mechanically amplify and radiate the strings' vibration in place of a conventional wooden soundboard.", "plain_english": "A metal guitar with three thin metal cones under the bridge. The cones work a bit like small speakers. A normal guitar uses a wooden top instead. This gives a loud, ringing, metal sound.", "purpose_function": "It was created by National in the late 1920s to make an acoustic guitar loud enough to cut through a band before electric amplification, and its three coupled cones give a smoother, more sustaining tone than single-cone designs.", "practical_application": "When recording a tricone for blues, bluegrass or Hawaiian slide, a technician typically mics both the coverplate/cone area and the neck or body to balance the metallic cone resonance against string and slide noise, and allows for the instrument's strong ringing sustain.", "category": "Resonator Guitar", "related_terms": ["Resonator guitar", "Single-cone resonator", "Biscuit bridge", "Spider bridge", "Slide guitar", "Coverplate"], "common_mistakes": ["Assuming all resonator guitars are tricones — single-cone biscuit and spider (Dobro-style) designs are mechanically and tonally different.", "Thinking the cones are steel; they are very thin spun aluminum (well under half a millimetre) and are easily dented or deformed by rough handling.", "Miking only the coverplate holes and missing the string and slide attack, or vice versa."], "scenario_contexts": ["Close-miking a National tricone for a Delta-blues slide session.", "Recording lap-style Hawaiian tricone where the cone resonance is central to the tone.", "Choosing a tricone over a single-cone guitar for a smoother, more sustaining part in an acoustic arrangement."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"4887d07c-ca2c-40b1-932e-2ba0e939bb50": {"definition": "The set of low-frequency acoustic resonances of a ukulele's hollow body — principally the Helmholtz-type air resonance of the enclosed cavity coupled to the fundamental flexural modes of the top plate and back — which shape and radiate the instrument's tone; because the body is small, these resonances lie at relatively high frequencies compared with a guitar.", "plain_english": "The natural boom of the ukulele's little box. The air inside and the wooden top shake together. This gives the uke its warm yet bright sound.", "purpose_function": "These body resonances reinforce and radiate the string energy, particularly in the low-mids, and largely determine the ukulele's loudness and tonal character.", "practical_application": "A technician chooses mic type and distance around the soundhole and lower bout to capture or tame these body resonances, since aiming a mic into the soundhole exaggerates the boomy air resonance while moving out and toward the 12th fret evens the tone.", "category": "Instrument Acoustics", "related_terms": ["Helmholtz resonance", "Soundhole", "Top plate", "Ukulele strumming transient", "Proximity effect", "Body resonance"], "common_mistakes": ["Aiming the mic straight into the soundhole and capturing a boomy, unnatural low-mid buildup dominated by the air resonance.", "Assuming a ukulele has the same body resonance frequencies as a guitar — the smaller body pushes them higher.", "Blaming 'boominess' on the room when it is actually the instrument's own Helmholtz air resonance."], "scenario_contexts": ["Positioning a small-diaphragm condenser off-axis from the soundhole to control body-resonance boom while tracking ukulele.", "EQing a recorded ukulele to tame a resonant low-mid peak from the body air mode.", "Comparing soprano and tenor ukuleles whose different body sizes shift the resonant character."]}, "1f2d08e0-61a6-4bdf-b318-6857de139ca5": {"definition": "The brief, high-amplitude broadband attack produced at the onset of a strummed ukulele chord — the composite of finger/nail-and-nylon contact noise and the rapid sequential excitation of the strings — occurring before the tone settles into its sustained, body-resonant portion.", "plain_english": "The sharp little burst you hear the instant a ukulele chord is strummed, before the ringing note settles in.", "purpose_function": "The transient carries much of the rhythmic feel and perceived attack of ukulele strumming, and its short, spiky nature is what lets a strummed uke sit as a percussive rhythm layer in a mix.", "practical_application": "Because these transients peak well above the sustained level, a technician leaves ample headroom, sets converters and preamps to avoid transient clipping, and dials compressor attack/release so the strum's snap is controlled without being flattened.", "category": "Instrument Acoustics", "related_terms": ["Transient", "Attack", "Headroom", "Compression", "Ukulele body resonance", "Peak level"], "common_mistakes": ["Setting levels to the average/RMS reading and letting the sharp strum transients clip the converter or preamp.", "Using a very fast compressor attack that swallows the transient and kills the strum's rhythmic snap.", "Trusting slow/averaging meters that under-read the true transient peak level."], "scenario_contexts": ["Gain-staging a ukulele track and leaving headroom so strum transients do not clip the interface.", "Dialing compressor attack and release to preserve the percussive snap of a strummed rhythm part.", "Choosing a mic and preamp with good transient response for a bright, articulate strummed track."]}, "533c0c68-d611-4836-b805-b3312e9a6f8c": {"definition": "The soft (left) pedal of a grand piano; depressing it shifts the whole keyboard and action sideways so the hammers strike two of the three unison strings (historically only one, hence 'una corda,' Italian for 'one string') and contact a less-worn strip of hammer felt, reducing loudness and softening timbre. On most upright pianos the equivalent pedal instead moves the hammers closer to the strings (a 'half-blow') and is not a true una corda.", "plain_english": "The left piano pedal. It makes the sound softer and mellower. On a grand piano, it slides the hammers sideways. Then each hammer hits fewer strings.", "purpose_function": "It gives the player a distinct soft, veiled tone colour — not merely lower volume — by changing how many strings are struck and which part of the hammer felt strikes them.", "practical_application": "A recording engineer learns to hear the una corda's timbral shift and knows that on a grand it changes attack and string coupling, whereas on an upright the 'soft pedal' only lightens the blow — useful when a producer asks for that softer colour.", "category": "Piano", "related_terms": ["Soft pedal", "Sustain pedal", "Sostenuto pedal", "Treble-string section", "Upright piano", "Hammer"], "common_mistakes": ["Believing a modern grand strikes literally one string on una corda — it typically shifts to strike two of the three unison strings.", "Assuming an upright's 'soft pedal' works like a grand's una corda; the upright uses a half-blow, not a lateral action shift.", "Confusing the una corda (left) pedal with the sostenuto (middle) pedal."], "scenario_contexts": ["A pianist engaging the una corda for a hushed passage while the engineer captures the timbral change.", "Producing a soft, intimate piano track and asking for the una corda pedal on a grand.", "Diagnosing a mechanical rattle when the una corda shift leaves the hammers misaligned on a studio grand."]}, "9de36243-90dc-4be9-a8e7-bc28d14b4b17": {"definition": "A piano in which the strings, soundboard and frame are mounted vertically in a case behind the keyboard rather than horizontally as in a grand, typically with the bass strings overstrung (crossing diagonally over the treble strings) to fit a longer speaking length into a compact height; its action relies on springs and bridle straps to return the hammers because it cannot use gravity.", "plain_english": "A piano that saves space. Its strings stand up straight behind the keys. So it fits neatly against a wall. A grand piano lies flat instead.", "purpose_function": "The vertical layout makes a full-range acoustic piano compact and affordable for homes, schools and studios, trading some of the grand's action speed, string length and tonal power for a smaller footprint.", "practical_application": "When recording an upright, a technician often removes the top lid and/or lower front panel and mics over the exposed strings or the open back, working around the vertical soundboard and the action noise that sits close to the strings.", "category": "Piano", "related_terms": ["Grand piano", "Soundboard", "Overstringing", "Treble-string section", "Una corda", "Piano action"], "common_mistakes": ["Miking an upright only through the closed front and getting a dull, boxy sound instead of opening the case to reach the strings.", "Expecting an upright's action to repeat notes as fast as a grand's — the vertical spring-return action is slower.", "Overlooking pedal and action noise, which on an upright is physically close to the strings and mics."], "scenario_contexts": ["Recording a studio upright by removing panels and placing a stereo pair over the strings.", "Capturing a deliberately 'honky-tonk' upright piano character for a track.", "Choosing mic placement to minimize an upright's action noise during quiet passages."]}, "990d90a3-8ec3-4252-a78f-42f918d6d7c9": {"definition": "A transfer function inside a MIDI keyboard/controller or sound engine that converts the measured speed or force of a key strike into a transmitted or applied MIDI velocity value (0–127); selectable curves (for example light/soft, medium, heavy/hard, or fixed) change how readily hard or soft playing reaches high or low velocities.", "plain_english": "The setting that turns your playing strength into MIDI numbers. These numbers say how hard you hit a key. A light curve makes soft playing sound loud. A heavy curve makes you press harder for loud notes.", "purpose_function": "It lets a keyboard match its velocity output to the player's touch and to the target sound, so the same physical playing can be made more or less sensitive without changing technique.", "practical_application": "A technician sets or edits the velocity curve on a controller (or remaps it in the DAW) so a player's dynamics translate naturally into a sampled instrument, or selects a fixed curve to record parts such as hi-hats at a constant velocity.", "category": "MIDI", "related_terms": ["Velocity response", "MIDI velocity", "Note On", "Aftertouch", "Dynamics", "MIDI controller"], "common_mistakes": ["Confusing the velocity curve (input touch-to-velocity mapping) with the sound engine's velocity response (how it turns velocity into loudness and timbre).", "Blaming a soft-sounding recording on the instrument when the controller's velocity curve is limiting the transmitted velocity range.", "Leaving a 'fixed' velocity curve engaged and then wondering why no dynamics are being recorded."], "scenario_contexts": ["Adjusting a MIDI controller's velocity curve so a light-touch player can reach full velocity.", "Setting a fixed velocity curve to program drum parts at a constant level.", "Remapping velocity in the DAW when a controller's curve does not suit a particular sampled instrument."]}, "3de3d511-9cd2-454c-a0ae-146b50fb4946": {"definition": "The way an instrument, sampler or sound engine reacts to incoming note velocity — the relationship between the velocity value (0–127) and the resulting sound, typically loudness plus, in many instruments, timbre changes, sample-layer selection, or envelope/filter modulation. The MIDI specification defines velocity but does not standardize this mapping, so response varies widely between devices.", "plain_english": "How the sound changes when you play harder or softer. Harder playing is usually louder. It is often brighter too. The instrument reads the velocity numbers to do this.", "purpose_function": "It is what makes an electronic or virtual instrument feel dynamic and expressive, translating a performer's touch into changes in level and tone rather than a flat, uniform sound.", "practical_application": "A technician auditions and edits an instrument's velocity response (velocity-to-volume, velocity layers, velocity-to-filter) so programmed or performed MIDI reads as musically dynamic, and compensates when different synths respond very differently to the same velocities.", "category": "MIDI", "related_terms": ["Velocity curve", "MIDI velocity", "Velocity layers", "Dynamics", "Note On", "Sample library"], "common_mistakes": ["Assuming every instrument responds identically to a given velocity — dynamic range and tone mapping vary greatly between devices.", "Confusing velocity response (the engine's reaction to velocity) with the controller's velocity curve (how touch becomes velocity).", "Treating velocity purely as volume and ignoring that it often also drives brightness, sample layers and articulation."], "scenario_contexts": ["Programming piano or string samples and editing velocity layers so soft and hard notes change tone, not just level.", "Matching the velocity response of two synths so a doubled MIDI part sounds even.", "Adjusting velocity-to-filter on a synth patch so harder notes open up brighter."]}, "4d68e59a-b5b7-42f3-be0d-bfba229a38bc": {"definition": "A hollow metal mute for brass instruments — better known as the Harmon mute — held in the bell by a ring of cork and fitted with a movable central stem or tube; covering and uncovering the end of the stem with a hand or plunger while playing produces the vowel-like 'wah-wah' effect, and the stem may be removed for a thinner, buzzier stemless sound.", "plain_english": "A metal mute for a trumpet or trombone. It has a little tube sticking out of it. The player waves a hand over the tube. This makes the horn talk with a wah-wah sound.", "purpose_function": "It seals the bell and concentrates the brass tone into a thin, nasal, buzzy timbre, and its movable stem lets the player shape expressive, vocal-like 'wah' inflections, a sound closely associated with jazz brass playing.", "practical_application": "On a jazz or big-band session a technician close-mics a trumpet or trombone using a Harmon (wah-wah) mute; because the muted tone is bright and concentrated, mic choice and working distance are set to tame the piercing highs and any low-end proximity buildup.", "category": "Brass mute", "related_terms": ["Harmon mute", "Straight mute", "Cup mute", "Plunger mute", "Bucket mute"], "common_mistakes": ["Assuming the mute produces 'wah' on its own — the effect comes from the player covering and uncovering the stem with a hand or plunger.", "Confusing the Harmon/wah-wah mute with the rubber plunger mute; both give vocal effects but are different tools with different tone.", "Forgetting the stem is removable, so the classic diffuse 'stemless Harmon' tone and the wah-wah technique are two distinct uses of the same mute.", "Miking it like an open horn and being surprised by the harsh, concentrated high-frequency beam a Harmon mute produces."], "scenario_contexts": ["A jazz session where the arranger calls for a Harmon (wah-wah) mute on a muted trumpet solo.", "A big-band brass section using wah-wah mutes with plunger-style hand movement for a talking, expressive line.", "A recording engineer positioning a mic on a Harmon-muted trumpet to control its thin, nasal, piercing tone."]}, "e8834edd-e094-4cf7-a7dc-4531fd252340": {"definition": "The intentional detuning of one sound source slightly sharp or flat relative to a nearly identical one — such as two organ ranks, two accordion reed banks, or two synthesizer oscillators — so the pitches beat against each other and produce an undulating, shimmering 'chorused' tone; heavier detuning and faster beating give a 'wetter' sound, while near-unison tuning is 'dry'.", "plain_english": "You tune two voices of an instrument a bit apart on purpose. Then they gently wobble against each other. This gives a rich, shimmering sound. A plain, flat tone would sound dull instead.", "purpose_function": "It thickens and animates an otherwise static tone by exploiting the acoustic beating between two almost-identical pitches, an undulation the ear tends to hear as warm and pleasant.", "practical_application": "An accordionist selects musette (wet) tuning for a French-café sound, an organist draws a celeste stop, or a producer detunes synth oscillators; when recording such a source the engineer preserves the intended beating rather than 'correcting' it with a tuner or pitch software.", "category": "Tuning", "related_terms": ["Celeste", "Voix céleste", "Beating", "Detune", "Chorus effect", "Musette tuning"], "common_mistakes": ["Confusing 'wet' meaning detuned/beating with 'wet' meaning the effected (reverb/delay) signal in a mix.", "Hearing the deliberate beating as an instrument being simply out of tune or defective, rather than an intended effect.", "Over-detuning until the shimmer becomes an unpleasant, seasick warble instead of a gentle undulation.", "Trying to 'fix' the beating in a recording with a tuner or pitch correction, which destroys the intended sound produced between the two sources."], "scenario_contexts": ["Selecting musette (wet) tuning on an accordion to get a bright, shimmering French-café sound.", "Drawing an organ's celeste / voix céleste stop to add shimmer to a string rank.", "Building a synth pad from detuned oscillators for a 'fat', chorused texture.", "Recording a celeste or detuned source and choosing not to correct the beating, since it is the desired effect."]}, "fcd61c4e-476c-41b8-b1df-5dd68032c99f": {"definition": "An unstable, warbling or stuttering note on a bowed string instrument — most notoriously the cello, but also viola and double bass — that occurs when the frequency of a played note nearly coincides with a strong resonance of the instrument body, so energy cycles between the string and the body and the note breaks up into periodic beating; on the cello it typically appears around E to F-sharp on the G or C string.", "plain_english": "A note on a cello that seems to fight back. Instead of a clean tone, you get a shaky, stuttering sound. It happens because that pitch matches a strong buzz in the body of the instrument.", "purpose_function": "It is not a designed feature but a coupling phenomenon; recognizing it explains why certain notes on certain instruments break up, and why devices such as wolf eliminators are fitted to tame them.", "practical_application": "A luthier or technician identifies the offending pitch and fits a wolf eliminator (a small tuned mass) on the string's afterlength below the bridge, while the engineer may adjust mic placement and the player alters bow pressure and contact point to minimize the wolf during a take.", "category": "String acoustics", "related_terms": ["Wolf eliminator", "Body resonance", "Helmholtz resonance", "Sympathetic resonance", "Beating", "Sustain"], "common_mistakes": ["Blaming the player's bowing or a poor setup for the warble, when a wolf tone is a structural resonance of the instrument itself.", "Believing a wolf eliminator removes the body resonance, when it actually shifts and damps it away from the played pitch.", "Assuming only cheap instruments have wolf tones — fine, responsive cellos often exhibit pronounced ones.", "Trying to fix a wolf in the mix with EQ, when it is a time-varying instability at the source rather than a fixed frequency imbalance."], "scenario_contexts": ["Recording a cello and hearing a warbling, stuttering note near F to F-sharp; a wolf eliminator is fitted on the afterlength to tame it.", "A player and engineer adjusting bow pressure, contact point and mic position to minimize a wolf on a sustained note during a take.", "A double bass or cello breaking up when a held note matches the instrument's main air or body resonance."]}, "94ef41d5-b5f3-4f29-b342-82926c550e9e": {"definition": "On an electronic (tonewheel) organ, the percussion circuit is a keyed transient generator that adds a short, exponentially decaying burst of a single selectable harmonic — the second or third — to the attack of a note, on top of the sustained drawbar tone. Introduced on Hammond consoles such as the B-3/C-3/A-100 and M-series, it is switchable for harmonic (2nd/3rd), volume (normal/soft) and decay (fast/slow), works on the upper (solo) manual only, and is single-triggering, so it re-sounds only after all keys are released.", "plain_english": "It is a part of an electric organ. It adds a short, bright 'ping' at the start of each note. The ping fades fast. Then the note settles into its steady tone. It is a bit like the knock you hear when a mallet hits a vibraphone bar. You can set the ping high or low in pitch. You can also make it loud or soft. And you can make it fade fast or slow.", "purpose_function": "It exists to give the organ's otherwise steady, sustained tone a percussive attack, imitating the struck or plucked onset of instruments like the vibraphone, marimba or harpsichord and adding articulation and 'bite'. Without it the drawbar registration starts and stops with no transient character.", "practical_application": "A player or tech sets it at the console — picking second/third harmonic and fast/slow decay to shape a part — while a service technician traces dead or weak percussion to the keying tube/transistor, the matching transformer or the trigger capacitor, and remembers that legato playing suppresses the effect by design. When recording or sampling an organ they capture the chosen percussion setting deliberately, because the transient onset defines the attack and cannot be added convincingly afterward.", "category": "Electronic organ", "related_terms": ["Drawbar", "Tonewheel generator", "Harmonic", "Attack transient", "Leslie speaker", "Additive synthesis"], "common_mistakes": ["Expecting percussion to sound on every note when playing legato; it is single-triggering, so held or overlapping notes suppress it and it only re-fires once all keys are released.", "Forgetting that switching percussion on disconnects one of the upper-manual drawbar harmonics, which slightly changes the sustained registration.", "Treating percussion as an effect you can add later in the mix, when it is a per-note keyed transient that must be set before the take.", "UNSAFE: servicing the percussion/keying stage on a live tube chassis — plate/B+ supplies exceed 100 V DC and the chassis is tied to the mains; de-energize, unplug and discharge filter capacitors before probing, per the service manual and NFPA 70E."], "scenario_contexts": ["Dialing 3rd-harmonic, fast-decay percussion on a B-3 (or a clonewheel) for a bright, articulate jazz or gospel comp, or 2nd-harmonic soft for a rounder attack.", "A studio engineer recording a Hammond through a Leslie commits to the percussion setting on the way in, because the transient onset is part of the performance.", "A service technician diagnosing 'no percussion' on a vintage console, checking the percussion tab switches, keying stage, matching transformer and trigger capacitor.", "A sound designer recreating single-triggering percussion behavior in a virtual/clonewheel organ so phrasing responds authentically to legato playing."]}, "c1487ddb-3d53-4114-b251-f43a5e4cbf02": {"definition": "A free-reed aerophone (mouth organ) sounded by the player's breath, in which blowing and drawing air past tuned metal reeds fixed in slots on reed plates makes the reeds vibrate to produce pitches; 'acoustic' denotes capturing its natural, unamplified and undistorted sound (typically close-miked) as opposed to the cupped-mic amplified blues approach.", "plain_english": "A normal harmonica recorded on its own natural sound. You put a mic in front of it instead of plugging it into an amp. When you blow and draw air, tiny metal reeds shake to make the notes.", "purpose_function": "It produces melody and chords from vibrating free reeds; treating it 'acoustically' aims to capture its true, clean tone with natural dynamics and breath detail intact.", "practical_application": "Engineers close-mic an acoustic harmonica with a condenser or dynamic microphone, watching for breath noise and plosive blasts and managing proximity effect and the wide level swings between soft and loud passages.", "category": "Harmonica", "related_terms": ["Chromatic harmonica", "Amplified harmonica", "Free reed", "Close miking", "Condenser microphone", "Proximity effect"], "common_mistakes": ["Placing the mic too close and getting excessive breath noise and boominess from proximity effect", "Setting gain for quiet passages, then clipping when the player blows a loud chord", "Assuming a harmonica is delicate and quiet; strong playing produces high SPL that can overload a close mic"], "scenario_contexts": ["Overdubbing a clean folk or country harmonica line onto a singer-songwriter track", "Close-miking harmonica in a studio for a blues ballad without amp distortion", "Capturing a harmonica in an acoustic ensemble where its natural tone must blend with guitar and vocal"]}, "e72234d6-3bf1-48b9-8efb-9c859baba192": {"definition": "A harmonica whose sound is picked up by a microphone — classically a cupped high-impedance 'bullet' dynamic mic held together with the instrument in the hands — and reproduced through an amplifier (often a tube guitar amp), commonly driven into overdrive to produce the gritty, midrange-heavy, distorted tone of electric blues 'harp.'", "plain_english": "A harmonica played into a small hand-held mic. The mic feeds a guitar-style amp. The amp is turned up until it distorts. This gives that raw, growly blues sound.", "purpose_function": "It turns the quiet acoustic instrument into a loud, saturated electric voice that can cut through a band and sit alongside electric guitars.", "practical_application": "The player cups a bullet mic such as the Shure 520DX 'Green Bullet' with the harmonica into a small amp; the engineer usually mics the amplifier rather than the harmonica, and manages stage level and feedback.", "category": "Harmonica", "related_terms": ["Acoustic harmonica", "Bullet microphone", "Chromatic harmonica", "Overdrive", "Feedback", "High-impedance microphone"], "common_mistakes": ["Treating a stand-mounted vocal mic as equivalent to a cupped bullet mic; the tight hand cup and high-impedance element are central to the tone", "Running high stage volume with an omnidirectional bullet mic and triggering runaway feedback instead of controlling gain and position", "UNSAFE: opening a tube amplifier chassis to troubleshoot — filter capacitors can retain lethal voltage even when unplugged; only qualified personnel should service it after proper discharge", "UNSAFE: prolonged exposure to loud amplified harp on stage without hearing protection, risking noise-induced hearing loss"], "scenario_contexts": ["Tracking a Chicago-blues harmonica part through a cranked tube amp for a distorted tone", "A live blues gig where the player cups a bullet mic into a stage amp that is then miked to the PA", "Re-amping a clean harmonica recording through an overdriven amp to add grit in the mix"]}, "a02ce934-da72-4ab7-9720-a204c7830f1f": {"definition": "A descriptive term for the aggressive, edgy, cutting quality at the front of a brass note, arising from the sharp attack transient of tonguing/articulation combined with strong upper-midrange to high-frequency harmonic energy; it is what makes brass read as punchy and forward.", "plain_english": "The sharp, snappy 'edge' at the start and top of a trumpet or trombone note. It makes the sound aggressive. It helps the note cut through a mix.", "purpose_function": "It names the attack and high-frequency character engineers listen for to make brass feel present and exciting, and which they shape with mic choice, placement and EQ.", "practical_application": "To add bite an engineer mics closer and more on-axis to the bell and lifts upper-mid/presence frequencies; to tame harshness they move off-axis or cut those bands.", "category": "Brass timbre", "related_terms": ["Brass brightness", "Brass projection", "Attack transient", "Equalization", "Presence", "Brass section balance"], "common_mistakes": ["Confusing 'bite' (attack and upper-mid edge) with overall 'brightness' (broadband high-frequency content)", "Chasing bite with extreme presence-band EQ boosts that make the brass harsh and fatiguing", "Miking dead-on-axis at the bell and capturing only harsh edge with no body"], "scenario_contexts": ["Adding aggression to a funk horn stab so it cuts through a dense mix", "Choosing a mic and angle for a lead trumpet that needs an edgy, forward attack", "EQing a trombone section to restore articulation lost to distant miking"]}, "2a5086d7-21a7-48d6-bc66-0a7d818c3ebe": {"definition": "The timbral quality of brass set by the relative strength of its high-frequency harmonics; brass grows markedly brighter as playing level rises because nonlinear sound propagation in the bore steepens the waveform and transfers energy into higher harmonics (the 'brassy' effect), raising the spectral centroid at forte and fortissimo.", "plain_english": "How bright or brilliant a brass instrument sounds. The louder you play it, the brighter it gets. That is because more high overtones show up.", "purpose_function": "It explains why brass timbre changes with dynamics, letting engineers judge tone and match recorded brightness to the musical intent through mic distance and EQ.", "practical_application": "Because brass brightens at high SPL, engineers set levels and mic distance for the loudest passages and may apply dynamic control so fortissimo brass does not turn harsh.", "category": "Brass timbre", "related_terms": ["Brass bite", "Brass projection", "Spectral centroid", "Harmonic overtones", "Equalization", "Dynamic range"], "common_mistakes": ["Assuming a brass instrument has one fixed timbre and not expecting it to brighten sharply as it gets louder", "Setting mic distance and gain at a mezzo level, then having fortissimo passages sound harsh and clip", "Boosting highs to add brightness when moving the mic closer to the bell axis would do it more naturally"], "scenario_contexts": ["Anticipating a fortissimo brass swell so the recorded tone stays musical rather than harsh", "Comparing a distant, mellow orchestral brass sound with a close, bright pop-horn sound", "Using distance and EQ to dial back brightness on an overly bright trumpet overdub"]}, "ea29c417-71ea-426d-99ed-8cc8ece53cb0": {"definition": "The efficient, directional radiation of sound from a brass instrument's bell, which becomes increasingly beamed forward along the bell axis at higher frequencies while lower frequencies radiate more omnidirectionally; this forward directivity is why brass 'projects' and reads as loud and present out front.", "plain_english": "How strongly a brass instrument throws its sound forward out of the bell. High notes and overtones shoot straight ahead. That is why brass carries so far.", "purpose_function": "It describes the instrument's directivity, which governs mic placement and how far and how brightly the sound travels in a room.", "practical_application": "Engineers place brass mics near and roughly on the bell axis to capture full brightness, and account for the strong on-axis high-frequency beam when choosing angle to avoid a result that is too bright or too dull.", "category": "Brass acoustics", "related_terms": ["Brass brightness", "Brass bite", "Directivity", "Off-axis response", "Microphone placement", "Brass section balance"], "common_mistakes": ["Placing a mic off to the side of the bell and then wondering why the brass sounds dull and lacks high end", "Treating brass as an omnidirectional source and mispredicting bleed and room excitation", "Getting the player to point the bell away from the audience or mic and losing projection and brightness"], "scenario_contexts": ["Aiming a mic along the bell axis of a trumpet to capture its bright, projecting tone", "Positioning section mics for a horn line where each bell fires in a slightly different direction", "Judging how far brass carries in a live room to set distant/room mic distances"]}, "f21ac1e6-4de9-4679-b669-ed2befc53d3b": {"definition": "The relative loudness and blend of the individual instruments within a brass section (e.g., trumpets, horns, trombones, tuba) so that no part dominates and the section reads as a unified whole; it is achieved by the players' dynamic control and, in recording, by mic placement, panning and level control.", "plain_english": "Getting the horns in a brass group to sit at the right volumes. Each one is set so they blend as one section. That way no single horn sticks out.", "purpose_function": "It ensures ensemble blend and correct voicing of chords, so inner harmony parts and bass brass stay audible under the lead line.", "practical_application": "The engineer balances section and/or spot mics, pans for width, and rides levels so lead, harmony and bass brass are all present and blended, complementing the players' own dynamic balance.", "category": "Brass recording", "related_terms": ["Brass projection", "Brass brightness", "Blend", "Microphone placement", "Panning", "Gain staging"], "common_mistakes": ["Spot-miking only the lead trumpet and letting inner harmonies disappear in the mix", "Ignoring that a higher, brighter instrument (lead trumpet) will mask lower parts unless balanced deliberately", "Assuming equal fader levels equal balance, when projection and brightness differences mean each part needs different treatment"], "scenario_contexts": ["Balancing a four-piece pop horn section so the harmony parts support rather than fight the lead", "Blending a big-band brass section captured with a section mic plus spot mics", "Correcting a mix where the lead trumpet overpowers the trombones and inner voices"]}, "dbc86637-4587-4bda-a49d-92d80c41dfb2": {"definition": "A harmonica fitted with a spring-loaded, button-operated slide that, when pressed, diverts the airflow from one set of reeds to a second set tuned a semitone higher, giving the player the full twelve-note chromatic scale from a single instrument (unlike the fixed-key diatonic harmonica).", "plain_english": "A harmonica with a button on the side. Press it and the note goes up by a half step. So you can play every note, all the sharps and flats. You are not stuck in one key.", "purpose_function": "It provides access to all chromatic pitches for jazz, classical and melodic playing without switching harmonicas or relying solely on note-bending.", "practical_application": "It is recorded like other harmonicas — close condenser mic or the player's cupped mic — and engineers may hear the faint mechanical click of the slide and slight timbre differences between the natural and slide-in reed sets.", "category": "Harmonica", "related_terms": ["Acoustic harmonica", "Amplified harmonica", "Free reed", "Slide mechanism", "Diatonic harmonica", "Close miking"], "common_mistakes": ["Confusing the chromatic (slide-operated, fully chromatic) with the diatonic harmonica (fixed key, relies on bending)", "Miking so close that the slide's mechanical click and air leakage become distracting", "Expecting the natural and slide-in reed sets to be timbrally identical when their tone can differ slightly"], "scenario_contexts": ["Recording a jazz solo that needs the full chromatic range from one instrument", "Capturing a legato melodic line where slide changes must stay quiet relative to the notes", "Doubling a chromatic harmonica melody with strings or piano in a film cue"]}, "128ce68d-4519-48ae-9faf-5716ebb5066f": {"definition": "The contribution of the clarinet's barrel — the short, often slightly tapered bore section joining the mouthpiece to the upper joint — to the instrument's resonant air column; because the clarinet behaves as a cylindrical pipe effectively closed at the reed end, the barrel forms part of the resonating column, so its length provides the main tuning adjustment (pulling it out lengthens the column and flattens pitch) while its bore dimensions and taper influence intonation and response.", "plain_english": "The barrel is the small removable piece just under the mouthpiece. It is part of the tube of air that makes the sound. Slide it in or out to tune the clarinet. Pulling it out makes the pitch flatter. Its shape also changes tone and tuning a little.", "purpose_function": "It gives the player the primary fine-tuning adjustment and, through its bore, helps shape the clarinet's resonant behavior and intonation.", "practical_application": "Players tune by pulling the barrel out a millimeter or two; players and techs swap barrels of different length or bore to correct intonation or tailor response, and engineers should expect a clarinet's pitch to rise slightly as it warms up.", "category": "Clarinet acoustics", "related_terms": ["Cylindrical bore", "Register", "Intonation", "Tuning", "Woodwind miking", "Mouthpiece"], "common_mistakes": ["Thinking barrel length alone sets tuning; barrels of equal length can have different bores and tuning tendencies", "Pushing the barrel fully in to raise a warm, sharp instrument rather than the intended small adjustment", "Assuming the barrel is merely a spacer rather than part of the resonating air column"], "scenario_contexts": ["A clarinettist pulling the barrel out to tune down to a slightly flat ensemble", "A player swapping to a different-bore barrel to fix throat-tone intonation", "Tracking a clarinet where pitch drifts sharp as the instrument warms during a long take"]}, "51c6d728-e961-4aba-98a1-89c9936d04b1": {"definition": "The tone captured from a grand piano recorded with its lid closed (or nearly closed) rather than raised on the prop stick; closing the lid reduces radiated high-frequency openness and yields a more contained, mellow, intimate tone, and it also cuts spill/bleed from other instruments into the piano mics during multi-instrument sessions.", "plain_english": "How a grand piano sounds when you record it with the big lid shut. It sounds darker, warmer, and more close-up. A shut lid also keeps other instruments from leaking into the piano mics.", "purpose_function": "It is a recording choice used to get a tighter, more intimate or vintage piano tone and to isolate the piano from bleed when tracking with a band in one room.", "practical_application": "Engineers close the lid — often placing mics inside near the hammers and strings, or using boundary mics on the closed lid — for pop, jazz and singer-accompaniment sounds and for isolation when tracking a full band live.", "category": "Piano recording", "related_terms": ["Grand piano", "Lid position", "Spill / bleed", "Close miking", "Boundary microphone", "Isolation"], "common_mistakes": ["Closing the lid for isolation but leaving mics far away so the sound is boxy and dead", "Expecting a big, bright open-lid tone from a closed-lid setup", "UNSAFE: reaching inside a grand without confirming the lid prop is seated or the lid is secured; a heavy lid can drop and injure hands"], "scenario_contexts": ["Recording piano and a live band together, closing the lid to reduce drum and vocal bleed", "Getting an intimate, mellow piano tone for a ballad or singer-songwriter track", "Using boundary mics on a closed lid in a small room to control leakage"]}, "9b916df1-ad1f-4e71-a1ee-09dac071182d": {"definition": "A small free-reed wind instrument, typically with ten chambers, each holding a pair of thin metal reeds fixed at one end over a close-fitting slot — one reed sounded by blowing (positive pressure) and one by drawing (negative pressure) — with the reeds tuned to the notes of a single diatonic (major) scale in one key. Air flow drives the appropriate reed to vibrate through its slot to produce the tone.", "plain_english": "A small hand-held 'blues harp' you play by breathing in and out. Each hole gives one note when you blow. It gives a different note when you draw. The whole harmonica is tuned to one musical key.", "purpose_function": "It provides a compact, portable melodic wind instrument tuned to one key, so a player can sound scale notes just by choosing a hole and blowing or drawing, with the fixed reeds setting the pitches so no keys or fingerings are needed.", "practical_application": "A technician records a diatonic harmonica either acoustically with a small-diaphragm condenser at a short distance for a clean sound, or, for blues, with a cupped high-output 'bullet' mic into an amp for a gritty tone, while managing the player's hand cupping and breath noise.", "category": "Free-reed instrument", "related_terms": ["Harmonica overblow", "Harmonica overdraw", "Harmonica distortion", "Chromatic harmonica", "Bullet microphone"], "common_mistakes": ["Assuming one diatonic harmonica can play every chromatic note in tune — it cannot without bends, overblows and overdraws", "Thinking you must play only in the harp's stamped key; blues players use 'cross harp' (second position) on a harp pitched a fourth below the song's key", "Blowing or drawing too hard, which pushes reeds out of tune and can permanently crack or damage a reed", "Confusing the 10-hole diatonic harmonica with the button-operated chromatic harmonica"], "scenario_contexts": ["Recording a blues harmonica solo cupped into a bullet mic and small tube amp for a dirty tone", "Overdubbing a folk or country harmonica part with a small-diaphragm condenser for a clean, natural sound", "A player swapping harps between songs to match each song's key", "Miking a cupped harmonica in a live blues band while controlling feedback"]}, "69bd68c3-10e3-4be2-a0c5-e9884c680fe7": {"definition": "An electronic keyboard instrument that reproduces the sound and touch of an acoustic piano, generating notes from stored digital samples (or physical models) of piano tones and typically using a weighted, hammer-action keyboard to emulate the feel of an acoustic piano action.", "plain_english": "An electronic piano that plays real-piano sounds through speakers or headphones. The sounds are recorded or made by a computer. The keys are heavy and push back like real piano keys. So it feels a lot like a real piano to play.", "purpose_function": "It gives players an acoustic-piano-like sound and feel without the size, weight, tuning needs and cost of an acoustic piano, and adds practical features such as volume control, silent headphone practice, and direct line and MIDI outputs.", "practical_application": "In the studio a technician usually records a digital piano by taking its balanced line output or USB/MIDI directly into the interface rather than miking it, and often captures MIDI so the performance can be re-voiced or edited later.", "category": "Keyboard instrument", "related_terms": ["Grand piano", "MIDI", "Weighted keys", "Sampling", "DI box"], "common_mistakes": ["Confusing a digital piano (weighted, piano-focused) with a synth or arranger keyboard (light keys, many sounds)", "Miking a digital piano's built-in speakers instead of taking the clean line or DI output", "Ignoring the difference between fully weighted/graded-hammer actions and semi-weighted or unweighted actions when selecting an instrument", "Forgetting that MIDI carries note and performance data, not audio, so a sound source is still required"], "scenario_contexts": ["Tracking a piano part via the digital piano's stereo line outputs straight into the interface", "Capturing MIDI so a producer can change the piano sound or fix timing afterward", "Using a digital piano on stage through a DI or its line out into the console", "Silent late-night practice through headphones"]}, "0ad386e3-8023-4037-8407-1f47f9b9fec8": {"definition": "A sound-generating mouthpiece made of two thin cane (or synthetic) blades bound together so a narrow slit remains between them; blown air makes the blades vibrate against each other, repeatedly opening and closing the aperture to pulse the air stream that drives the instrument's air column. It is the reed system of instruments such as the oboe, bassoon, English horn and bagpipe chanter.", "plain_english": "Two thin strips of cane tied together with a tiny gap between them. You blow through the gap. The two strips beat against each other. This makes the buzzy tone of the oboe and bassoon.", "purpose_function": "The double reed acts as the vibrating valve that converts the player's steady breath pressure into rapid puffs of air, exciting and sustaining the standing wave in the instrument's bore.", "practical_application": "When recording oboe or bassoon a technician usually places the mic off the bell and more toward the body and keywork, because much of the tone radiates from the tone holes rather than the bell, and expects reed and breath noise up close.", "category": "Woodwind reed", "related_terms": ["Single reed", "Reed", "Woodwind instrument", "Embouchure", "Flute embouchure hole"], "common_mistakes": ["Calling any woodwind reed a 'double reed' — clarinets and saxophones use a single reed against a mouthpiece", "Miking straight down the bell, which misses much of the true oboe/bassoon tone radiating from the tone holes", "Assuming reeds are consistent — cane double reeds vary greatly and players constantly adjust or hand-make them", "Confusing the reed (the vibrating cane) with the whole mouthpiece/staple assembly"], "scenario_contexts": ["Positioning a condenser mic on an oboe for an orchestral or overdub session", "Recording a bassoon and choosing mic height to balance body tone against key noise", "A player scraping and adjusting a double reed between takes to fix intonation or response", "Isolating a double-reed instrument within an ensemble recording"]}, "77b109fe-623c-4c58-ae3d-c7ff2d40bf6c": {"definition": "The oval blow-hole cut into the head joint of a transverse flute (in the raised lip plate on a modern metal flute) across which the player directs a narrow air jet; the jet striking the far edge of the hole sets up an edge tone that excites and sustains the standing wave in the flute's air column. It is also called the mouth hole or blow hole.", "plain_english": "The hole you blow across at the top of a flute. You blow across it, not into it. Your breath splits on the far edge, and that makes the sound. It works like blowing across the top of a bottle.", "purpose_function": "It is the flute's sound generator — the point where the player's air jet is turned into the oscillating air motion that drives the pipe, so its size and shape and the player's aim strongly affect tone and pitch.", "practical_application": "Because a strong jet of air and breath noise comes off the embouchure hole, a technician usually positions the mic slightly above and out toward the far end of the flute rather than right at the mouth, balancing airy 'chiff' against body tone and avoiding wind blasts.", "category": "Flute component", "related_terms": ["Embouchure", "Head joint", "Edge tone", "Double reed", "Air jet"], "common_mistakes": ["Thinking the player blows into the hole rather than across its outer edge", "Placing the mic right at the embouchure hole, capturing excessive wind and breath blast", "Confusing the embouchure hole (the blow hole) with the tone holes and keys along the body", "Assuming 'embouchure' means only the lips — here it names the instrument's blow-hole"], "scenario_contexts": ["Miking a concert flute for a classical recording, offset above and past the mouth", "Managing breath and key noise on a close-miked flute overdub", "Explaining to a beginner why aiming the air jet at the edge produces the tone", "Choosing placement to capture the airy 'chiff' of the embouchure for a jazz or pop flute sound"]}, "9f193053-6c94-49de-8ddd-6d26a9715ff7": {"definition": "A large acoustic piano whose strings, cast-iron frame and soundboard lie horizontally and whose keys drive felt hammers through a repetition action; string length increases toward the bass, and sizes range from small 'baby grands' (roughly 1.5 m) to concert grands (roughly 2.7 m). Pressing a key throws a hammer against the strings and lifts the damper, and the string vibration is radiated acoustically by the soundboard.", "plain_english": "A full-size piano that lies flat. The long strings and soundboard sit flat under a lid that lifts. Press a key and a felt hammer flicks up at the strings. The big wooden soundboard makes the sound loud.", "purpose_function": "The horizontal frame allows longer bass strings and a fast, gravity-assisted repetition action, giving grands greater volume, dynamic range, sustain and control than upright (vertical) pianos.", "practical_application": "A technician typically records a grand with the lid on the stick and a stereo pair over the strings (often one mic toward the bass strings and one toward the treble/hammers), adjusting distance for the desired blend of attack, body and room.", "category": "Keyboard instrument", "related_terms": ["Digital piano", "Soundboard", "Stereo miking", "Damper pedal", "Hammer action"], "common_mistakes": ["UNSAFE: Lifting a grand's lid or moving the instrument without enough help or proper technique — lids are heavy and grands can tip; use a crew and piano dollies/skid boards and secure the lid prop", "Placing both mics too close, exaggerating hammer attack and losing the instrument's blend", "Failing to seat the lid prop stick properly, so it can slip and slam", "Judging low-end from a short baby grand as if it matched a concert grand's bass response"], "scenario_contexts": ["Setting a stereo pair inside a grand for a pop or rock session with the lid on the short or long stick", "Close-miking a concert grand for a jazz trio while controlling bleed from drums", "Recording solo classical piano with a more distant pair to capture the room", "Moving a grand into a live room safely with a crew and dollies"]}, "62f69b63-6c49-402d-9926-81766212762b": {"definition": "The deliberately overdriven, harmonically saturated tone characteristic of amplified blues and rock harmonica, produced when the harmonica signal is clipped — most often by cupping a high-output, high-impedance 'bullet' microphone tightly around the harp and driving a tube amplifier into overload. The clipping adds harmonic and intermodulation distortion and compresses the signal, giving the thick, gritty 'dirty harp' sound.", "plain_english": "The fat, growling harmonica tone in blues and rock. You cup a special mic tight around the harp. Then you push a tube amp until it distorts. The sound comes from the amp, not the harmonica itself.", "purpose_function": "It exists as a deliberate creative effect: overdriving the amp thickens and sustains the harmonica tone, adds edge and warmth, and helps the instrument cut through a loud band.", "practical_application": "A technician sets it up with a bullet mic into a small tube amp (or an amp sim / overdrive pedal) and then mics the amp; managing feedback from the tightly cupped mic and taming harsh upper harmonics with EQ are the main tasks.", "category": "Amplified harmonica", "related_terms": ["Diatonic harmonica", "Bullet microphone", "Clipping", "Overdrive", "Tube amplifier"], "common_mistakes": ["Thinking the distortion comes from the harmonica reeds rather than the mic and amp overload", "UNSAFE: Running a tube amp with no speaker load or a mismatched load to force distortion, which can destroy the output transformer or tubes", "Boosting harsh high-frequency content instead of shaping it, producing an ice-pick, feedback-prone tone", "Using a modern low-impedance vocal mic and wondering why the classic cupped 'dirty' tone will not appear"], "scenario_contexts": ["Recording a Chicago-blues harp solo through a bullet mic and small tube amp", "Re-amping a clean harmonica DI through an overdrive plug-in for grit in the mix", "Controlling feedback during a loud live blues set with a cupped bullet mic", "Blending a clean condenser track with a distorted amp track for size"]}, "619e6397-7816-484f-9590-a241af22d295": {"definition": "An advanced diatonic-harmonica technique in which precise breath and vocal-tract control forces the normally silent draw (inhale) reed of a hole to sound on a blow (exhale) breath, speaking as an 'opening' reed about a semitone above its natural draw pitch. This yields chromatic notes — mainly in the middle octave — not available from the standard blow and draw reeds or from bending.", "plain_english": "A hard trick to learn. You shape your mouth and breath just right. This makes a note come out that is not normally there. It fills in missing sharps and flats without switching harps.", "purpose_function": "The overblow lets a diatonic harmonica play the full chromatic scale, so a player can perform jazz and other chromatic music on a single 10-hole diatonic harp instead of switching instruments.", "practical_application": "For a technician it means the player may need a well-set-up (gapped) harp and very quiet handling, since overblows are soft and easily lost; close, clean miking and low ambient noise help capture them.", "category": "Harmonica technique", "related_terms": ["Diatonic harmonica", "Harmonica overdraw", "Note bending", "Chromatic harmonica", "Reed gapping"], "common_mistakes": ["Confusing an overblow with simply blowing harder — it is a controlled resonance change, not brute force", "Assuming any stock harmonica overblows easily; most need reed gapping or embossing to respond", "Thinking the overblow sounds on the blow reed, when it actually comes from the draw reed of the hole", "Expecting overblows to be as loud as normal notes and setting gain too low to catch them"], "scenario_contexts": ["A jazz harmonica player using overblows to play chromatic lines on one diatonic harp", "Setting up (gapping) a harmonica so overblows respond reliably before a session", "Close-miking quietly to capture soft overblown notes", "Explaining why a harp part needs a well-adjusted instrument to reach certain notes"]}, "b24121a3-d6b1-41d2-9d4a-9b8287565aa3": {"definition": "The upper-register counterpart of the overblow: an advanced diatonic-harmonica technique in which breath and vocal-tract control force the blow (exhale) reed of a hole to sound on a draw (inhale) breath, as an opening reed about a semitone above its natural blow pitch. Overdraws supply missing chromatic notes in the harmonica's high register.", "plain_english": "Like an overblow, but at the high end and reversed. You inhale in a special way to make an extra note come out. It fills in the sharps and flats at the top of the harmonica.", "purpose_function": "Together with overblows, overdraws complete the chromatic scale on a diatonic harmonica, letting a player cover all twelve notes across the instrument's range without switching harps.", "practical_application": "Overdraws are the softest, most delicate notes on the harp and demand a precisely set-up instrument; a technician captures them best with a low-noise signal path, careful gain staging and minimal ambient noise.", "category": "Harmonica technique", "related_terms": ["Diatonic harmonica", "Harmonica overblow", "Note bending", "Reed gapping", "Chromatic harmonica"], "common_mistakes": ["Mixing up overdraw (high register, sounding on the blow reed) with overblow (mid register, sounding on the draw reed)", "Trying to overdraw on a stock harp without gapping or embossing the reeds first", "Drawing too aggressively and knocking the note out or damaging the reed", "Setting record levels too low to capture the very quiet overdrawn notes"], "scenario_contexts": ["A player using overdraws to reach high chromatic notes in a jazz solo", "Preparing a high-register harp so overdraws speak in the studio", "Capturing delicate overdrawn notes with a clean, quiet mic chain", "Troubleshooting why a specific high note will not sound on an un-set-up harmonica"]}, "7a8c2e1b-7435-4a87-83e8-8a57cdc95b59": {"definition": "A passive level control — typically an L-pad, a series-plus-shunt resistor network that attenuates the driver while presenting a roughly constant impedance to the crossover — placed ahead of the high-frequency horn/compression driver in a loudspeaker to reduce (attenuate) its output so its higher sensitivity is matched to the less-sensitive low-frequency driver. It may be a fixed pad or a rotary/switchable HF level control.", "plain_english": "A volume trim inside a speaker. It turns the high 'horn' driver down, because horns are usually louder than the woofer. The L-pad type does this and still keeps a steady load for the crossover.", "purpose_function": "Compression-driver horns are commonly several dB more sensitive than the woofer, so the attenuator pads the horn down to balance the two and give a flat, even frequency response instead of a bright, harsh top end.", "practical_application": "A technician uses a horn/HF attenuator when voicing a passive two-way cabinet or monitor — setting the fixed pad value or the rotary HF control to match the horn to the woofer for the room — and checks it when a box suddenly sounds too bright or too dull.", "category": "Loudspeaker component", "related_terms": ["L-pad", "Compression driver", "Passive crossover", "Sensitivity", "Biamping"], "common_mistakes": ["Using a plain series resistor or a simple potentiometer instead of an L-pad, which changes the driver's load impedance and shifts the crossover behavior", "UNSAFE (gear damage): fitting a pad resistor with too low a power rating, so it overheats and fails under drive", "Assuming a bright cabinet needs EQ when the horn attenuator/L-pad is simply set too high", "Confusing this loudspeaker HF attenuator with an inline mic/line pad or with a brass-instrument mute"], "scenario_contexts": ["Voicing a passive two-way PA top so the horn matches the 15-inch woofer", "Adjusting the rotary HF level control on a stage monitor to tame harshness", "Matching a high-sensitivity compression driver to a lower-sensitivity woofer in a crossover build", "Diagnosing an overly bright loudspeaker traced to a mis-set HF attenuator"]}, "218fa973-3d25-48c5-a648-5260fa256b11": {"definition": "The rotating cylindrical core inside a rotary valve on a French (orchestral) horn; when the player's lever turns it, drilled ports in the rotor redirect the airflow through added tubing, lowering the pitch by lengthening the instrument.", "plain_english": "A French horn has round valves. Inside each one is a spinning part called the rotor. When the player presses a lever, the rotor turns and sends air through extra tubing. That makes the note lower, as if the horn got longer.", "purpose_function": "It lets the player instantly add or remove lengths of tubing to change pitch, extending the horn's range and giving smooth, quick note changes.", "practical_application": "During close-miking, moving rotors and their linkage can click audibly, so engineers mic the bell from the side or behind and watch for valve noise while players keep rotors lightly oiled and fast.", "category": "Brass instrument", "related_terms": ["Rotary valve", "French horn", "Bell (brass)", "Valve slide", "Brass mic placement"], "common_mistakes": ["Confusing the rotor of a rotary valve with the tuning slides", "Using heavy or wrong oil that gums up and slows the rotor", "Forgetting that rotor and linkage clicks get captured in quiet close-miked passages"], "scenario_contexts": ["Hearing faint valve clicks when close-miking a soft horn section", "A player oiling the rotors before a session to keep them quiet and fast", "Tracing a sluggish or noisy note change to a dry or worn rotor"]}, "575ea25d-a508-41e8-8c7a-faa177daec03": {"definition": "The line-level audio output on an electronic keyboard or synthesizer that delivers the instrument's internal sound at nominal line level (roughly -10 dBV to +4 dBu) on 1/4-inch or XLR jacks for connection to a mixer, audio interface, or amplifier.", "plain_english": "This is the audio jack on a keyboard. It sends the keyboard's sound out at a fairly strong level called line level. You plug it into a mixer or an audio interface to record it. It is the keyboard's main sound socket.", "purpose_function": "It provides the keyboard's finished mono or stereo sound at a standard level so it can feed a console, interface, or PA directly, with no microphone needed.", "practical_application": "A technician patches the keyboard line outputs into line-level channels or a DI box, sets the keyboard's own volume near maximum, and trims gain at the console to avoid clipping.", "category": "Keyboard I/O", "related_terms": ["Line level", "DI box", "Keyboard output level", "Balanced connection", "Audio interface"], "common_mistakes": ["Plugging a line-level output into a mic input and overloading the preamp", "Running long unbalanced 1/4-inch cables from the keyboard and picking up hum (use a DI)", "Leaving keyboard volume low and cranking console gain, which adds noise"], "scenario_contexts": ["Recording a stage piano by taking its line outputs into an interface", "Sending keyboard line outs to a DI box for a long stage run to front of house", "Setting gain structure between a synth output and a mixer channel"]}, "d646f10d-0c1c-4ff4-be23-2fe2f3d8d465": {"definition": "The nominal signal strength present at a keyboard's audio output, typically line level (around -10 dBV consumer or +4 dBu professional), though many keyboards deliver a hotter or variable level set by their onboard volume control.", "plain_english": "This is how strong the sound signal is when it leaves the keyboard. Most keyboards send out line level, a medium-strong signal. The keyboard's own volume knob can make it stronger or weaker. Getting this level right keeps the sound clean.", "purpose_function": "Knowing the output level lets an engineer match the keyboard to the right input and set gain so the signal stays well above noise but does not distort.", "practical_application": "The technician checks the keyboard's master volume, meters the signal at the console or interface, and adjusts input gain or engages a pad so peaks sit safely below clipping.", "category": "Keyboard I/O", "related_terms": ["Line level", "Keyboard line output", "Gain staging", "Clipping", "Pad (attenuator)"], "common_mistakes": ["Assuming every keyboard outputs the same level; some are much hotter than others", "Turning the keyboard volume all the way up and clipping the input", "Ignoring gain staging so the recorded level is noisy or too low"], "scenario_contexts": ["Matching a hot synth output to a console input by engaging a pad", "Balancing two keyboards that output very different levels in a live rig", "Setting record levels for a keyboard part in a DAW"]}, "01064c72-c080-4761-a443-9619c920cb1b": {"definition": "A division of a pipe organ placed remotely from the main instrument, usually at the opposite end of the room such as a rear gallery, and playable from the same console so it can answer or contrast with the main organ in call-and-response (antiphonal) fashion.", "plain_english": "A pipe organ can have a set of pipes placed far from the main organ. It often sits at the other end of the room. The player controls it from the same desk. It answers the main organ, like two choirs singing back and forth.", "purpose_function": "It creates spatial and antiphonal effects, with sound arriving from a second location, giving the organist dramatic contrast and dialogue across a large space.", "practical_application": "When recording, the engineer adds mics near the antiphonal division and blends them with the main-organ mics, watching for timing and phase differences caused by the distance between them.", "category": "Pipe organ", "related_terms": ["Organ division", "Organ console", "Organ stop", "Swell box", "Ambient miking"], "common_mistakes": ["Thinking it is a separate organ; it is one instrument played from one console", "Miking only the main organ and missing the antiphonal answer", "Ignoring the time delay between distant divisions, causing phase smear when mixed"], "scenario_contexts": ["Recording a cathedral organ with pipes in both the chancel and the rear gallery", "Blending antiphonal and main mics for a wide, immersive organ image", "A service using the antiphonal division for call-and-response passages"]}, "caa34078-d7d7-4466-893c-038758b3c845": {"definition": "The grilled or screened tone opening through which sound from an enclosed organ chamber (a room or recess housing pipework) passes into the main room; its size, position, and covering strongly affect how much and how clearly the pipe sound reaches listeners.", "plain_english": "Many organ pipes sit inside a hidden room called a chamber. Sound escapes through a covered opening, usually behind a grille or cloth. This opening works like a doorway for the sound. Its size and cover change how loud and clear the organ sounds.", "purpose_function": "The opening couples the chamber's pipe sound to the room; builders size and place it to project the organ evenly while keeping the pipework out of sight.", "practical_application": "Engineers often mic near or just outside the chamber opening to catch direct pipe sound, then mix it with room mics for depth; a dense grille cloth can dull the highs they capture.", "category": "Pipe organ", "related_terms": ["Organ chamber", "Swell box", "Grille cloth", "Organ speaker placement", "Close miking"], "common_mistakes": ["Confusing the chamber opening with the swell shades inside it", "Pressing a mic dead-center against a grille and getting a boxy, blocked tone", "Forgetting that grille cloth absorbs high frequencies"], "scenario_contexts": ["Miking a divided organ whose pipes speak through chamber grilles high on the walls", "Comparing a mic just outside the opening with a distant room mic", "Troubleshooting a muffled organ sound traced to a dense grille covering"]}, "8d50a5ea-577c-4338-8d37-547b2b7f9ac9": {"definition": "The control desk of a pipe or electronic organ, containing the manual keyboards, the pedalboard, and the stop controls (drawknobs, tabs, or tilting tablets), plus pistons and swell pedals, from which the organist plays and selects the instrument's sounds.", "plain_english": "The console is the organ's control desk. It has the hand keyboards, the foot pedals, and the knobs that turn sounds on and off. The player sits here to run the whole organ. Think of it as the cockpit of the organ.", "purpose_function": "It gathers every control in one place so the player can operate keyboards, pedals, and stops that may connect to pipes located far away in the room.", "practical_application": "For recording and live sound, the console's key and stop action and the blower can add mechanical noise, so engineers keep mics away from the desk and aimed toward the pipes.", "category": "Pipe organ", "related_terms": ["Manual (keyboard)", "Pedalboard", "Organ stop", "Organ division", "Swell pedal"], "common_mistakes": ["Assuming the sound comes from the console; the pipes, often distant, make the sound", "Close-miking the console and capturing key clatter instead of music", "Forgetting a detached console can sit far from the pipes, adding sound delay"], "scenario_contexts": ["Recording a recital where the console sits in the chancel but pipes speak from the gallery", "Placing player-cue mics at the console while main mics face the pipes", "Managing key-action and blower noise on a quiet studio organ take"]}, "bb87bada-83ae-422d-bdcf-4eb1d8577948": {"definition": "The low bass notes produced by an organ's pedal division, played with the feet on the pedalboard and typically voiced by large 16-foot and 32-foot stops; a 32-foot stop's lowest note reaches into the deep sub-bass near 16 Hz.", "plain_english": "These are the deep bass notes the organ player makes with their feet. The feet press big pedals, which sound the largest pipes. The lowest ones are so low you feel them more than hear them. A 32-foot pipe can reach about 16 Hz.", "purpose_function": "Pedal tones give the organ its powerful bass foundation, anchoring the harmony and adding weight and rumble that fill a large room.", "practical_application": "Capturing pedal tones needs mics and monitors with real low-frequency reach, so engineers use large-diaphragm or omni mics, high-pass only if truly needed, and check for room resonances and rumble.", "category": "Pipe organ", "related_terms": ["Pedalboard", "Organ stop", "Organ division", "Subwoofer", "Low frequency"], "common_mistakes": ["UNSAFE: Sustained high-level 32-foot pedal tones can over-excite PA subwoofer drivers; respect amp and driver limits to avoid damage", "Using mics or monitors that roll off below 40 Hz and missing the true fundamental", "High-passing too aggressively and stripping away the pedal's power"], "scenario_contexts": ["Recording an organ work with prominent 16-foot and 32-foot pedal lines", "Checking that studio monitors and subs reproduce the lowest pedal notes", "Taming a room mode excited by a sustained low pedal tone"]}, "19b778ef-9d38-4f1c-a61c-064bc3045524": {"definition": "The positioning of the loudspeaker or loudspeakers that reproduce an electronic or electric organ, most notably a Hammond organ's Leslie rotary-speaker cabinet, chosen so the sound projects naturally into the room and can be effectively miked, since a rotary cabinet's spinning horn and bass rotor radiate differently in each direction.", "plain_english": "Many electric organs, like a Hammond, use a separate speaker cabinet. A Leslie cabinet even has spinning speakers inside. Where you put that cabinet changes how it sounds in the room. Good placement helps it fill the space and makes it easier to record.", "purpose_function": "Proper placement lets the organ's speaker project evenly and, for rotary cabinets, lets the swirling motion develop in the room so it sounds full and can be captured cleanly.", "practical_application": "To record a Leslie, engineers place mics on the top rotating horn (often two for stereo) and one or two on the lower bass rotor, keeping the cabinet off walls and out of corners to reduce boom.", "category": "Electronic organ", "related_terms": ["Leslie speaker", "Rotary speaker", "Hammond organ", "Speaker miking", "Stereo miking"], "common_mistakes": ["Pushing a Leslie or organ cabinet into a corner, causing boomy, uneven bass", "Miking only the top horn and missing the bass rotor's body", "UNSAFE: A Leslie cabinet is heavy and tips easily; secure it and lift with proper technique to avoid injury or damage"], "scenario_contexts": ["Setting up a Hammond and Leslie for a studio session", "Positioning a church electronic organ's speakers for even coverage", "Stereo-miking a rotary cabinet's top horn and bottom rotor"]}, "5ab5e078-1255-404a-9efa-dbe5b7ed2cea": {"definition": "A control (a drawknob, tilting tablet, or slider) that admits wind to a particular rank or ranks of pipes, and by extension the set of pipes it governs; each stop has a characteristic tone color and pitch, marked by a name and a foot-length such as 8' for unison pitch or 16' for an octave lower.", "plain_english": "An organ stop is a control that turns one set of pipes on or off. Each set has its own sound and pitch. The name comes from stopping the sound until you pull the stop out. Pulling more stops adds more sounds together, which is where \"pull out all the stops\" comes from.", "purpose_function": "Stops let the organist choose and combine tone colors and pitches, building anything from a single soft flute to the full, blazing sound of the whole organ.", "practical_application": "The chosen stops set the tonal balance, so as the organist changes registration from soft flutes to full principals and reeds, engineers adjust mic distance and EQ to match.", "category": "Pipe organ", "related_terms": ["Rank", "Organ division", "Organ console", "Registration", "Organ pipe"], "common_mistakes": ["Confusing a stop (a whole voice) with a single pipe or a single key", "Thinking the foot number is loudness; it marks pitch, not volume", "Assuming one stop equals one rank; mixture stops draw several ranks at once"], "scenario_contexts": ["Reading a score's registration to know which stops will sound and how loud", "Re-miking as the organist shifts from a single 8' flute to full organ", "Explaining why a 16' stop sounds an octave below the keys played"]}, "53bd0463-a6eb-4fe1-a5e2-3762f48e9ffe": {"definition": "A swell box is a wooden (or masonry) enclosure built around a division of pipe-organ pipes, fronted by hinged Venetian-blind-style shutters that the organist opens and closes with an expression (swell) pedal to vary that division's loudness; pipes so enclosed form an expressive or 'swell' division.", "plain_english": "A box with slatted doors built around a set of organ pipes. The player uses a foot pedal to open or close the slats. This makes those pipes louder or softer. It is like opening and closing a window on the sound.", "purpose_function": "Each organ pipe sounds at a fixed loudness, so the swell box exists to give the organist continuous dynamic control (crescendo and diminuendo) over an enclosed division without having to change stops.", "practical_application": "When recording or reinforcing an organ, a technician accounts for the swell shutters because the enclosed division's level and brightness change dramatically as the pedal moves, which affects mic choice, placement and gain staging.", "category": "Pipe organ", "related_terms": ["Reed stop", "Reed pipe", "Pipe organ reverberation", "Flue pipe", "Organ stop"], "common_mistakes": ["Assuming the swell box sets loudness electronically; it is a purely mechanical acoustic shutter, and closing it also rolls off high frequencies, not just level.", "Confusing the enclosed Swell division with the whole organ; only pipes inside a swell box respond to the expression pedal.", "Setting a close mic without allowing for the large level and tone swing as the shutters open and close, leading to unexpected clipping or a dull sound."], "scenario_contexts": ["Recording a church pipe organ where the organist uses the swell pedal for crescendos during a hymn.", "Miking a theatre organ whose Swell and Solo divisions each sit in their own swell box.", "Troubleshooting why a captured organ track's level and brightness fluctuate even though no stops were changed."]}, "a74802eb-aa72-4d9d-947c-e233b11d5572": {"definition": "The angle at which a grand piano's top lid is propped, typically full stick (fully raised), short or half stick (partially raised), or closed, which determines how sound radiating from the strings and soundboard reflects off the underside of the lid and projects into the room or toward microphones.", "plain_english": "It is how far the big top lid of a grand piano is opened. Fully up throws the sound out brightly and loudly; propped on the short stick or closed keeps it quieter and more contained.", "purpose_function": "The lid works as both a reflector and a shutter for the piano's sound, so its position controls tone, projection and, in multi-instrument settings, how much the piano is heard versus isolated.", "practical_application": "An engineer chooses lid position to trade a bright, open sound (full stick) against spill control and a mellower tone (short stick or closed), then places mics to suit the reflections off the lid.", "category": "Piano recording", "related_terms": ["Piano phase interaction", "Piano monitor spill", "Spill", "Stereo miking", "Soundboard"], "common_mistakes": ["Recording on full stick within a live band and then fighting excessive drum and vocal spill that a shorter stick would have reduced.", "Forgetting that closing the lid darkens the tone and lowers high-frequency output, then trying to fix it entirely with EQ.", "UNSAFE: Failing to seat the lid stick fully in its notch, risking the heavy lid dropping and crushing fingers or damaging the instrument."], "scenario_contexts": ["Setting up a solo grand recording with the lid on full stick for maximum brightness and stereo image.", "Tracking piano with a live rhythm section and lowering to short stick to reduce spill from nearby instruments.", "Miking a piano in a jazz club where the lid is kept closed for a warm, contained sound."]}, "9aa58bc6-ad58-495a-b529-3a36f0a2e589": {"definition": "Piano monitor spill is unwanted sound from stage monitor (foldback) loudspeakers leaking into the piano's open microphones; because grand-piano mics are sensitive and the raised lid presents a large open pickup area, monitor content re-enters the piano channel, degrading isolation and reducing gain-before-feedback.", "plain_english": "It is when the piano mics pick up sound from the stage monitor speakers. So the monitors bleed into the piano channel. This also makes feedback easier to set off.", "purpose_function": "Understanding monitor spill matters because it sets practical limits on monitor level, mic placement and lid position, and it directly affects feedback stability and mix cleanliness in live sound.", "practical_application": "A technician controls piano monitor spill by aiming monitors away from the open lid, lowering the lid to short stick or closed, choosing directional or boundary mics, and limiting the number of open mics to preserve gain-before-feedback.", "category": "Piano recording", "related_terms": ["Spill", "Piano lid position", "Gain before feedback", "Stage monitor", "Comb filtering"], "common_mistakes": ["Raising monitor level for the pianist without repositioning the wedges, which pushes the system into feedback through the open piano mics.", "Leaving the lid on full stick pointed at a monitor and then blaming the mics for a muddy, feedback-prone channel.", "Ignoring that spill from monitors arrives late and out of phase, causing comb filtering that thins the amplified piano tone."], "scenario_contexts": ["A live gig where the keyboard player asks for more monitor and the piano channel starts to ring.", "Setting up an open grand on a loud stage and choosing directional mics to reject wedge spill.", "Mixing front-of-house and noticing the piano fader also brings up bleed from the vocal monitor."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"3260bbd2-9038-4661-a330-51d18f0509cf": {"definition": "Piano phase interaction is the constructive and destructive interference that arises when two or more microphones (or a mic plus reflections) capture the same piano at slightly different distances; the resulting time offsets produce comb filtering that alters the summed frequency response and can hollow out or thin the tone.", "plain_english": "When you use more than one mic on a piano, each mic hears the sound at a slightly different time. Mixing them makes some frequencies get louder. It makes other frequencies cancel out. If the mics are placed badly, the piano can sound thin or hollow.", "purpose_function": "Managing phase interaction keeps a multi-mic piano sounding full and natural when the mics are summed to mono or blended, avoiding comb-filter coloration.", "practical_application": "Engineers minimize it by observing the 3:1 rule (space the mics at least three times as far apart as each mic sits from the source), checking mono compatibility, and nudging placement or polarity to find the fullest sound.", "category": "Piano recording", "related_terms": ["Comb filtering", "3:1 rule", "Polarity", "Piano lid position", "Stereo miking"], "common_mistakes": ["Spacing two piano mics close together without the 3:1 ratio, then hearing a hollow, comb-filtered tone when they are summed.", "Assuming a polarity flip fixes all phase problems; polarity inversion is not the same as a time or distance offset and only helps in specific cases.", "Judging the sound only in stereo and missing severe cancellation that appears when the mix folds to mono."], "scenario_contexts": ["Blending a close mic and a room mic on a grand and finding the low mids disappear when summed.", "Setting a spaced pair inside the piano and applying the 3:1 rule to control comb filtering.", "Checking mono compatibility of a piano stereo mix before broadcast."]}, "1fee5c67-feff-4c84-9207-7ffba1c07151": {"definition": "Pipe organ reverberation refers to the persistence of reflected sound in the large, hard-surfaced spaces (churches, cathedrals, concert halls) that pipe organs occupy; because organ tone is sustained and the instrument is voiced to its room, the space's reverberation time is an integral part of the perceived sound rather than an added effect.", "plain_english": "Pipe organs sit in big stone rooms that echo for a long time. That natural echo is part of how the organ is meant to sound. The instrument and the room work together.", "purpose_function": "The reverberant space blends the many pipes into a cohesive, sustained tone, which is why organs are voiced for their specific acoustic and why the reverberation must be respected when capturing them.", "practical_application": "When recording an organ, engineers place mics to balance direct pipe sound against the room's reverberation, often using distant or spaced mics rather than close-miking as with a small instrument.", "category": "Pipe organ", "related_terms": ["Reverberation time", "Organ swell box", "Reed pipe", "Room acoustics", "Ambient miking"], "common_mistakes": ["Close-miking a pipe organ like a guitar amp, capturing pipe chiff and wind noise but losing the blend and grandeur the room provides.", "Adding artificial reverb to a recording that already needs the real room's tail, producing a smeared, unnatural result.", "Assuming the console position sounds the same as the audience area; organ balance and reverberation vary greatly with mic distance and height."], "scenario_contexts": ["Recording a cathedral organ recital with a distant main pair to capture the natural reverberation.", "Deciding mic distance for an organ in a highly reverberant church versus a drier concert hall.", "Balancing organ and choir where the long reverberation time affects intelligibility."]}, "367b937c-fc53-40ba-8530-4de2bd519b9c": {"definition": "A prepared piano is a piano whose timbre has been temporarily altered by placing objects such as screws, bolts, rubber, felt or coins between or on the strings, changing pitch, harmonic content and decay to yield percussive or altered sounds; the technique was systematized by composer John Cage.", "plain_english": "An ordinary piano with small objects stuck onto the strings. People use bolts, rubber, or screws. This turns the normal notes into buzzy, muted, or drum-like sounds.", "purpose_function": "Preparation exists to expand the piano's sonic palette into percussive and unpitched territory for composition and experimental music without permanently modifying the instrument.", "practical_application": "A recording engineer capturing a prepared piano places mics close to the strings to catch the varied and often quiet percussive sounds, and works with the performer to ensure the preparations do not damage strings, hammers or dampers.", "category": "Piano technique", "related_terms": ["Piano lid position", "Piano phase interaction", "Extended technique", "Close miking", "Soundboard"], "common_mistakes": ["Using sharp or oversized objects that scratch strings or bend hammers and dampers; preparations must be chosen and placed so the instrument is not harmed.", "Expecting consistent tuning and level, since prepared notes vary widely and gain staging set on normal notes may clip or be too quiet.", "Miking from a distance as for a normal piano and missing the subtle percussive detail that close mics reveal."], "scenario_contexts": ["Recording a contemporary-classical work written for prepared piano with bolts between the strings.", "Reproducing a John Cage sonata that specifies exact preparation objects and positions.", "Capturing experimental percussive textures for a film score using a prepared grand."]}, "78759bd7-8def-40eb-848e-71818498b372": {"definition": "A reed pipe (lingual pipe) is a class of organ pipe in which sound is produced by a vibrating metal tongue (the reed) beating against the shallot inside the pipe's boot; the vibrating reed modulates the air stream and a resonator above shapes the timbre, in contrast to flue pipes, which sound like a whistle or flute.", "plain_english": "An organ pipe that makes sound with a small vibrating metal tongue. It works like the reed in a woodwind. It does not blow across an edge like other pipes. This gives brassy or buzzy voices, like trumpet or oboe stops.", "purpose_function": "Reed pipes provide the organ's assertive brass- and woodwind-like colors (chorus and solo reeds), broadening the tonal palette beyond the flute-like flue pipes.", "practical_application": "When miking an organ, a technician notes that reed pipes are richer in harmonics and more directional and edgy than flue pipes, so their location in the case affects captured brightness and balance.", "category": "Pipe organ", "related_terms": ["Reed stop", "Reed plate", "Organ swell box", "Flue pipe", "Shallot"], "common_mistakes": ["Confusing a reed pipe's beating metal tongue with the free reeds of a harmonium; organ reed pipes use a beating reed on a shallot with a resonator.", "Assuming all organ pipes behave the same, when reed pipes go out of tune with temperature more readily than flue pipes and need retuning.", "Close-miking a reed rank and capturing harsh buzz because reeds are harmonically rich and directional."], "scenario_contexts": ["Identifying the Trumpet or Oboe rank (reed pipes) when balancing an organ recording.", "Diagnosing a single dead or out-of-tune reed pipe whose tongue has slipped.", "Choosing mic distance to tame the edge of a chorus reed division."]}, "ac8b6fff-1ebb-43e9-b110-1f168e465f85": {"definition": "A reed plate is the metal frame in a free-reed instrument that carries one or more reed tongues, each riveted at one end over a closely matching slot cut through the plate; air flowing past sets the tongue vibrating freely in and out through its slot to produce the note. Reed plates are used in harmonicas, accordions, concertinas and reed organs/harmoniums.", "plain_english": "The metal plate in a harmonica or accordion that holds the thin vibrating tongues, called reeds. Each reed sits over a matching slot. It swings back and forth through the slot to make sound.", "purpose_function": "The reed plate mounts and aligns the free reeds precisely over their slots so they can vibrate cleanly, forming the sound-producing core of free-reed instruments.", "practical_application": "When recording a harmonica or accordion, an engineer mics close to the reed plates or grille to capture the reeds' tone, aware that each reed sounds on only one air direction (blow or draw, press or pull).", "category": "Free-reed instruments", "related_terms": ["Reed pipe", "Reed stop", "Free reed", "Harmonica", "Accordion"], "common_mistakes": ["Confusing the free reed on a reed plate with an organ reed pipe's beating reed; free reeds vibrate through the slot and do not strike the frame.", "Expecting a single reed to sound in both air directions, when a given reed responds to only one direction with a separate reed for the other.", "Miking too far off and losing reed detail, or too close and hot and capturing wind and valve noise from the plate."], "scenario_contexts": ["Close-miking a diatonic harmonica and hearing the blow and draw reeds on their plates.", "Recording an accordion where multiple reed plates per note create the characteristic beating tremolo tuning.", "Servicing a harmonium and gapping the reeds seated on their reed plates."]}, "7c1f4c55-0e4a-4268-bc62-4908daa05b65": {"definition": "A reed stop is an organ stop that controls a rank of reed pipes, as opposed to a flue stop controlling flue pipes; drawing it admits wind to reed pipes whose vibrating metal tongues produce brass- or woodwind-like voices such as Trumpet, Oboe, Clarinet, Bassoon or Vox Humana.", "plain_english": "It is the knob or tab that turns on a set of the organ's reed pipes. These pipes sound like trumpets, oboes, or clarinets. The other kind, flue stops, sound more like flutes.", "purpose_function": "Reed stops let the organist select the instrument's reed voices, adding the powerful chorus reeds and characterful solo colors that a flue-only organ would lack.", "practical_application": "A technician balancing or recording an organ tracks which reed stops are drawn, since chorus reeds greatly raise level and brightness and, being reed pipes, are the most sensitive to temperature-related tuning drift.", "category": "Pipe organ", "related_terms": ["Reed pipe", "Organ swell box", "Pipe organ reverberation", "Flue pipe", "Organ stop"], "common_mistakes": ["Confusing the stop (the control that selects a rank) with the pipes themselves; the reed stop draws wind to a whole rank of reed pipes.", "Setting record levels with flue stops only and then clipping when loud chorus reed stops are added.", "Assuming reeds hold tune like flues, when reed stops often need touch-up tuning as the room temperature changes."], "scenario_contexts": ["An organist adding the Trumpet reed stop for a fanfare, sharply raising the recorded level.", "Identifying which reed stops are engaged when diagnosing tuning drift in a recording.", "Balancing a chorus of reed stops against the flue chorus in a full-organ passage."]}, "24efb917-f138-483c-90de-c8f7db86c1da": {"definition": "A single-reed system uses one flat cane or synthetic reed clamped against a mouthpiece; air pressure makes the reed vibrate against the mouthpiece opening and drive the instrument's air column. Clarinets and saxophones are the main single-reed woodwinds, as distinct from double-reed instruments such as the oboe and bassoon.", "plain_english": "It is a mouthpiece with one thin strip of cane. Your breath makes that strip flap fast, and the buzz starts the note. Clarinets and saxes work this way.", "purpose_function": "The single reed acts as a pressure-controlled valve that turns steady breath into a vibrating sound source, setting the air column inside the instrument into oscillation to make pitched tones.", "practical_application": "When recording clarinet or saxophone, engineers treat the reed as the sound's starting point and place mics toward the tone holes and body, not only the bell, because sound leaves the whole instrument.", "category": "Woodwind instruments", "related_terms": ["Double reed", "Woodwind blend", "Woodwind projection", "Mouthpiece", "Embouchure"], "common_mistakes": ["Thinking the reed sets the pitch, when the tube length and open tone holes set pitch while the reed drives the vibration.", "Assuming single and double reeds sound alike, when reed type strongly shapes tone and technique.", "Miking only the bell, which misses much of a single-reed instrument's true sound."], "scenario_contexts": ["Recording a jazz saxophone solo in a studio.", "Setting up a clarinet mic for a chamber-music session.", "Explaining why a clarinet and an oboe are grouped in different reed families."]}, "575acec9-2a22-49b7-982f-525853a095db": {"definition": "A stage piano is a purpose-built electronic keyboard optimized for live performance, pairing high-quality piano and core keyboard sounds with a weighted, hammer-action keybed. It stresses gigging features such as line or balanced outputs, fast sound selection, and rugged build rather than the deep sound libraries of a workstation.", "plain_english": "It is an electronic piano made for playing shows. The keys feel heavy like a real piano. It is built tough and simple so it holds up on stage.", "purpose_function": "It exists to give players a portable, robust instrument with realistic piano feel and sound for live use, without the weight and fragility of an acoustic piano.", "practical_application": "On a gig, a technician takes the stage piano's stereo line or balanced outputs into DI boxes or the console and may split a feed to the player's monitor.", "category": "Keyboard instruments", "related_terms": ["Stereo keyboard output", "Tonewheel organ", "DI box", "Weighted action", "Workstation keyboard"], "common_mistakes": ["Confusing a stage piano with a full workstation, when stage pianos focus on piano and core sounds, not deep production tools.", "Plugging a line-level output into a mic input, which overloads the preamp and distorts.", "Assuming it has speakers, when most stage pianos have none and need a PA or monitor."], "scenario_contexts": ["A keyboardist gigging with a band at a club.", "A worship team running a stage piano through the house PA.", "A studio session where a stage piano is DI'd for a clean piano track."]}, "d4b2ebce-4af1-446a-a79c-072768a73e77": {"definition": "Stereo keyboard output is the pair of left and right audio signals produced by an electronic keyboard whose sound engine, samples, and effects are spread across a stereo field. Capturing both channels preserves the intended width, movement, and stereo effects such as chorus or reverb.", "plain_english": "Many keyboards send out two signals, a left and a right. Together they make the sound wide, like it is spread across two speakers. You capture both to keep that width.", "purpose_function": "It lets an instrument deliver its built-in stereo width and effects to a mixer or recorder, so listeners hear the sound as designed instead of collapsed to one point.", "practical_application": "Engineers take both the left and right jacks into two DI boxes or two console channels, pan them hard left and right, and check that a mono fold-down still sounds right.", "category": "Keyboard recording", "related_terms": ["Stage piano", "Tonewheel organ", "DI box", "Line level", "Mono compatibility"], "common_mistakes": ["Recording only the left output, which can drop half the sound or key effects.", "Skipping a mono check, so the mix thins out on mono systems.", "Panning both channels to center, which throws away the stereo image."], "scenario_contexts": ["DI'ing a synth's left and right outputs for a stereo pad.", "Setting up a keyboard rig with two console channels for stereo.", "Checking mono compatibility of a stereo patch before a broadcast."]}, "2e092648-2683-4e19-83fa-728b8610080f": {"definition": "A tonewheel organ is an electromechanical organ, exemplified by the Hammond, that generates each pitch with a spinning toothed metal wheel (tonewheel) next to a magnetic pickup, inducing an alternating voltage. Nine drawbars mix near-sine harmonics by additive synthesis to build the timbre.", "plain_english": "It is an old-style electric organ. Spinning metal wheels sit next to magnets and make the sound. Sliders called drawbars mix these tones to shape the voice.", "purpose_function": "The tonewheel system produces stable, continuously sustained tones and lets the player build custom timbres with drawbars, giving the instrument its signature jazz, gospel, and rock sound.", "practical_application": "In the studio or on stage, its sound is usually taken from a rotating-speaker cabinet, close-miked on the treble horn and bass rotor, rather than from a direct output.", "category": "Keyboard instruments", "related_terms": ["Drawbar", "Rotary speaker", "Stage piano", "Additive synthesis", "Stereo keyboard output"], "common_mistakes": ["Thinking it is a synthesizer, when the tones come from spinning wheels, not oscillators.", "DI'ing the organ and skipping the rotary speaker, which is central to the sound.", "UNSAFE: Servicing a vintage tube amplifier or rotary cabinet without discharging the capacitors first, since they can hold a lethal charge even when unplugged."], "scenario_contexts": ["Miking a rotary-speaker cabinet for a gospel session.", "Recording a Hammond B-3 for a rock track.", "Setting drawbars to dial in a jazz organ tone."]}, "14c9b4c0-7800-4635-8add-fc8071a19fad": {"definition": "Treble reeds are the free reeds on the treble (right-hand) side of an accordion or harmonium, which sound the melody and higher pitches. They are grouped in reed banks at different octave footings that register switches combine, as distinct from the instrument's bass reeds.", "plain_english": "These are the reeds that make the higher, tune-playing notes on an accordion. They sit on the right-hand side. The left-hand side has separate bass reeds.", "purpose_function": "They provide the melodic voice of a free-reed keyboard instrument, and their multiple banks let the player thicken or brighten the tone with register switches.", "practical_application": "When miking an accordion, engineers place a mic near the treble grille to capture the melody reeds, often adding a second mic on the bass side for balance.", "category": "Free-reed instruments", "related_terms": ["Tremolo harmonica", "Single reed", "Register switch", "Woodwind blend", "Free reed"], "common_mistakes": ["Confusing treble reeds with a single reed like a clarinet's, when free reeds vibrate freely in a slot and are not blown against a mouthpiece.", "Miking only one side of an accordion and missing the treble melody.", "Assuming one reed sounds per key, when several banks can sound at once."], "scenario_contexts": ["Miking an accordion's treble side for a folk recording.", "Choosing register switches to brighten the melody voice.", "Explaining why accordion tone changes with different reed banks."]}, "a5d238d5-5be6-456b-88ce-9edb542bd834": {"definition": "A tremolo harmonica has two reeds for each note, mounted in paired upper and lower holes and tuned slightly apart. The small pitch difference makes the two tones beat against each other, producing its characteristic wavering, shimmering tremolo sound.", "plain_english": "This harmonica has two reeds for every note. One is tuned a tiny bit higher than the other. The two notes clash gently, giving a wavy, trembling sound.", "purpose_function": "The paired detuned reeds create a built-in tremolo effect, giving the instrument a rich, folk-style voice with no electronics.", "practical_application": "Engineers record it with a single close mic and expect the natural beating; heavy pitch correction or processing fights the intended wavering tone.", "category": "Free-reed instruments", "related_terms": ["Treble reeds", "Single reed", "Beating", "Detuning", "Woodwind blend"], "common_mistakes": ["Thinking the wavering is a fault, when the detuned reed pair is intentional.", "Trying to pitch-correct it, which destroys the tremolo character.", "Confusing it with a chromatic harmonica, which uses a slide instead of paired reeds."], "scenario_contexts": ["Recording a folk tremolo harmonica part.", "Explaining why the instrument sounds wet or shimmering.", "Choosing a tremolo versus a diatonic harmonica for a session."]}, "14087efb-cf4f-4b5d-8939-4e32d73ad17c": {"definition": "Woodwind blend is the degree to which the timbres of woodwind instruments fuse into a single, unified section sound rather than being heard as separate voices. It depends on matched dynamics, tuning, and articulation, and in recording on microphone choice and placement.", "plain_english": "Blend is how well woodwinds melt into one smooth sound together. When it works, you hear the group, not each player. Good tuning and matching help it happen.", "purpose_function": "Blend gives a woodwind section a cohesive, even color, which composers and engineers use to create smooth pads and unified lines.", "practical_application": "Engineers often record a woodwind section with a shared main mic pair for natural blend, adding spot mics only when a line needs support.", "category": "Woodwind recording", "related_terms": ["Woodwind projection", "Single reed", "Spot mic", "Room mic", "Main pair"], "common_mistakes": ["Close-miking every player, which separates the sound and hurts blend.", "Ignoring tuning and dynamic differences that break the unified color.", "Assuming more mics always sound better, when a main pair often blends best."], "scenario_contexts": ["Recording a woodwind quintet for a film score.", "Balancing flutes and clarinets so they fuse in a mix.", "Choosing a main-pair setup for a natural section sound."]}, "dc8cb628-bd8c-404e-ab70-16b6ff537be9": {"definition": "Woodwind projection is how effectively a woodwind instrument radiates sound outward into a space, set by its acoustic power output and directivity. Because sound leaves from the open tone holes and the bell, projection changes with register, dynamics, and direction, which affects how the instrument carries and how it is miked.", "plain_english": "Projection is how well a woodwind pushes its sound out into a room. Some notes carry far, others stay close. Where the sound comes out changes where you point a mic.", "purpose_function": "Understanding projection helps players fill a hall and helps engineers place mics where the instrument radiates most of its sound.", "practical_application": "Because low notes and soft passages radiate mainly from the open tone holes rather than the bell, engineers aim mics at the body and keys, not just the end of the instrument.", "category": "Woodwind recording", "related_terms": ["Woodwind blend", "Single reed", "Directivity", "Spot mic", "Tone holes"], "common_mistakes": ["Miking the bell like a trumpet, when most woodwind sound comes from the tone holes.", "Ignoring that projection changes with register, so mic balance shifts across the range.", "Assuming louder always means better projection, when direction and tone also matter."], "scenario_contexts": ["Placing a flute mic for even level across its range.", "Deciding mic distance for a clarinet in a live room.", "Explaining why a bassoon needs mics near its body, not just the bell."]}, "ea51e527-2d0d-4506-9086-1354e69b6bd3": {"definition": "A portable, freestanding acoustic device placed around a microphone or sound source to absorb and block room reflections and unwanted spill, giving a drier, more controlled recording.", "plain_english": "A movable padded screen you set behind or around a mic. It soaks up echoes from the room so the recording sounds cleaner.", "purpose_function": "It reduces early reflections and bleed reaching the microphone, so a source can be recorded cleanly without treating the whole room.", "practical_application": "An engineer stands or clamps a shield behind a vocal or amp mic in an untreated room to cut room sound and get a tighter, more usable take.", "category": "Acoustic treatment", "related_terms": ["Reflection control panel", "Portable vocal screen", "Gobos", "Bleed", "Acoustic treatment", "Early reflections"], "common_mistakes": ["Expecting a small shield to soundproof a room; it only reduces nearby reflections and spill, not sound passing through walls.", "Placing the shield too far from the mic, so it has little effect on reflections.", "Over-absorbing close to the mic, which can make a source sound dull or boxy."], "scenario_contexts": ["Recording vocals in an untreated bedroom or project studio.", "Tightening up a guitar amp mic in a live tracking room.", "Capturing voiceover or podcast audio in a reflective office."]}, "4eab1066-58de-4943-ad05-1a384452c08b": {"definition": "A barrier of transparent acrylic or polycarbonate panels placed in front of or around a drum kit to acoustically isolate it, reducing sound spill into other microphones and lowering the drums' loudness in the room.", "plain_english": "Clear plastic walls set around a drum kit. They work like a see-through fence that keeps the loud drum sound from leaking everywhere.", "purpose_function": "It contains and blocks the drums' high sound level so nearby mics pick up less drum bleed and the stage or room stays quieter.", "practical_application": "In tracking or on a live or worship stage, a tech positions acrylic panels around the kit to control bleed and tame stage volume for the mix.", "category": "Acoustic isolation", "related_terms": ["Gobos", "Bleed", "Isolation screen", "Acoustic isolation", "Stage volume", "Baffle"], "common_mistakes": ["UNSAFE: Fully enclosing a drummer with panels and a lid can raise sound levels and heat inside the enclosure; watch hearing exposure and ventilation.", "Thinking a shield soundproofs the drums; hard panels mostly reflect and redirect sound rather than absorb it.", "Placing panels too close to cymbals, creating harsh reflections back at the drummer."], "scenario_contexts": ["Isolating a loud kit during multitrack studio tracking.", "Reducing drum volume on a church or theater stage.", "Cutting drum bleed into vocal and acoustic mics in a small room."]}, "0e7e149e-8b57-404c-9e0f-3c5f9a643aaf": {"definition": "Freestanding, movable acoustic baffles positioned between performers or instruments in a studio to reduce sound leakage between sources and control reflections; the name comes from 'go-between', and many have an absorptive side and a harder reflective side.", "plain_english": "Movable padded panels you stand between players. They work like room dividers that stop each instrument's sound from spilling into the other mics.", "purpose_function": "They provide acoustic separation so instruments recorded together bleed less into each other's mics, giving cleaner isolated tracks and easier mixing.", "practical_application": "When a band tracks live in one room, the engineer arranges gobos around the drums, amp, or vocalist to keep each mic focused on its own source.", "category": "Acoustic isolation", "related_terms": ["Studio gobo", "Bleed", "Isolation screen", "Acoustic shield", "Baffle", "Live tracking"], "common_mistakes": ["Expecting gobos to fully soundproof sources; they reduce bleed but do not stop all sound.", "Using only the reflective side and adding harshness when absorption is needed.", "Leaving large gaps or low panels, so sound simply travels over or around them."], "scenario_contexts": ["Separating a drum kit from guitar amps during live band tracking.", "Building a temporary vocal area in an open live room.", "Controlling reflections around a brass or string section."]}, "f9790cd4-42e0-4712-bc38-11d52b911cf3": {"definition": "A portable acoustic panel or screen used to isolate a microphone or sound source from the rest of the room, reducing bleed from other instruments and unwanted room reflections.", "plain_english": "A standalone panel you place by a mic or player. It blocks sound from other instruments and cuts room echo so the recording is cleaner.", "purpose_function": "It creates local acoustic separation so a source can be recorded with less spill and room sound, without needing a separate isolation room.", "practical_application": "An engineer stands an isolation screen between a singer and a drum kit, or around an amp, to keep each mic focused on its intended source.", "category": "Acoustic isolation", "related_terms": ["Gobos", "Acoustic shield", "Portable vocal screen", "Bleed", "Vocal booth panel", "Acoustic isolation"], "common_mistakes": ["Assuming a screen soundproofs the source; it lowers bleed and reflections but sound still passes around it.", "Positioning it too far from the mic or source to be effective.", "Confusing isolation, which blocks spill, with full room treatment."], "scenario_contexts": ["Recording a vocalist and guitarist together in one room.", "Reducing amp bleed into overhead drum mics.", "Capturing a cleaner overdub in a shared, untreated space."]}, "40d1cdda-55d1-4290-8a08-60dd884c4b8a": {"definition": "A freestanding, movable sound-absorbing panel used to temporarily treat a space, controlling reflections and reverberation around a microphone or listening position.", "plain_english": "A padded panel on a stand that you can move where you need it. It soaks up echoes so a room or mic spot sounds less boomy.", "purpose_function": "It provides on-demand absorption to tame reflections and room ring where fixed acoustic treatment is not installed or is not enough.", "practical_application": "A tech sets a few portable panels around a vocal or drum position, or beside monitors, to improve the sound of an untreated or temporary space.", "category": "Acoustic treatment", "related_terms": ["Reflection control panel", "Acoustic treatment", "Portable vocal screen", "Absorption", "Early reflections", "Gobos"], "common_mistakes": ["Expecting absorption panels to block sound between rooms; they treat reflections, not transmission through walls.", "Placing too few panels to make an audible difference.", "Over-damping a space, so recordings sound dead and lifeless."], "scenario_contexts": ["Treating a hotel or location room for a remote recording.", "Improving a home studio's vocal area.", "Reducing reflections near nearfield monitors at the mix position."]}, "693cf381-d9f3-41ac-afcc-5d9415315ff8": {"definition": "A portable absorptive panel positioned around a vocal microphone to reduce room reflections reaching the mic, producing a drier, more focused vocal recording; it is often called a reflection filter.", "plain_english": "A curved padded shield that wraps behind a vocal mic. It catches echoes from the room so the singer's voice sounds clean and close.", "purpose_function": "It controls early reflections and some spill near the mic so vocals can be tracked cleanly in rooms that lack proper acoustic treatment.", "practical_application": "A vocalist records with a portable vocal screen mounted on the mic stand just behind the microphone in a home or project studio.", "category": "Acoustic treatment", "related_terms": ["Reflection control panel", "Acoustic shield", "Isolation screen", "Bleed", "Early reflections", "Vocal booth panel"], "common_mistakes": ["Believing it soundproofs the room; it mainly reduces reflections just behind and beside the mic.", "Mounting it too far behind the mic to be effective.", "Relying on it alone in a very loud or very reflective space."], "scenario_contexts": ["Tracking lead vocals in an untreated bedroom studio.", "Recording voiceover or podcasts on location.", "Adding reflection control to a mobile or temporary vocal setup."]}, "09cbb47c-df68-4c72-9f10-d9ae0a7747ad": {"definition": "An absorptive acoustic panel designed to control early reflections around a microphone, source, or listening position, reducing the amount of reflected room sound in the signal.", "plain_english": "A sound-soaking panel aimed at the first echoes off nearby surfaces. It stops those early bounces from muddying the recording or the mix.", "purpose_function": "It targets early reflections that blur clarity and imaging, cleaning up a recorded source or tightening a monitoring position.", "practical_application": "An engineer places reflection control panels at the first reflection points beside a mic or between the speakers and the mix position.", "category": "Acoustic treatment", "related_terms": ["Portable acoustic panel", "Portable vocal screen", "Acoustic treatment", "Early reflections", "Absorption", "Acoustic shield"], "common_mistakes": ["Treating them as soundproofing; they absorb reflections but do not block transmission.", "Ignoring the actual first reflection points, so panels sit where they do little.", "Over-treating and making the sound unnaturally dead."], "scenario_contexts": ["Cleaning up a vocal or instrument recording in a live-sounding room.", "Treating first reflection points around a mix position.", "Reducing comb filtering from a nearby hard surface during tracking."]}, "4697d78a-637c-4c27-a7d1-a7866cb6ed88": {"definition": "A freestanding acoustic baffle used in a recording studio to provide separation between instruments or performers and to control reflections; typically a movable panel, often with one absorptive and one reflective face. 'Gobo' derives from 'go-between'.", "plain_english": "A movable studio panel placed between players. It acts like a portable wall that keeps sounds from bleeding into the wrong mics.", "purpose_function": "It gives acoustic separation during multi-source recording so each microphone captures mostly its own instrument, aiding cleaner tracks.", "practical_application": "During live band tracking, an engineer arranges studio gobos around the kit, amps, or a singer to reduce bleed and shape the local sound.", "category": "Acoustic isolation", "related_terms": ["Gobos", "Isolation screen", "Acoustic shield", "Bleed", "Baffle", "Live tracking"], "common_mistakes": ["Expecting full isolation; a gobo reduces bleed but does not fully block sound.", "Using the reflective face when absorption is needed, which adds harshness.", "Setting panels too low or with gaps, so sound passes over and around them."], "scenario_contexts": ["Isolating drums from guitar amps in one-room tracking.", "Making a temporary vocal spot in an open live room.", "Shaping reflections around a horn or string section."]}, "6e37d51f-68a9-431f-812e-bbea252dbddb": {"definition": "An acoustic panel used to build, line, or form a vocal isolation booth, providing absorption and some isolation so a vocalist can be recorded with minimal room sound and spill.", "plain_english": "A padded panel used to make or line a small singing booth. It soaks up echoes and helps block outside noise so vocals record clean.", "purpose_function": "It supplies the absorption and partial isolation that make a booth's interior dry and quiet, keeping room reflections and bleed out of the vocal.", "practical_application": "A studio assembles vocal booth panels into a small enclosure, or lines an existing booth with them, so singers can track cleanly.", "category": "Acoustic treatment", "related_terms": ["Portable vocal screen", "Isolation screen", "Acoustic treatment", "Absorption", "Reflection control panel", "Bleed"], "common_mistakes": ["Thinking absorptive panels alone make a booth soundproof; blocking outside noise needs mass and sealing, not just absorption.", "Over-damping a booth, so vocals sound lifeless and boxy.", "Leaving gaps and reflective surfaces that let bleed and echo in."], "scenario_contexts": ["Assembling a portable vocal booth in a project studio.", "Lining a closet or small room for vocal overdubs.", "Setting up a temporary iso booth on a remote session."]}, "5943310c-2143-40e9-bc66-c74226f6dc52": {"definition": "The gradual accumulation of sustained high-frequency energy from cymbals during a performance or recording, in which their long wash and overlapping overtones add up so the top end becomes cluttered, harsh, or masks other instruments.", "plain_english": "When cymbals keep ringing, their bright hiss piles up over time. It can bury the rest of the kit. Think of many people all talking at once until you cannot hear anyone clearly.", "purpose_function": "It names a common problem that engineers watch for; spotting it helps them keep the high end clear and stop the cymbal wash from swamping the mix.", "practical_application": "A technician manages it through cymbal choice and placement, overhead mic position, high-frequency EQ, or by gating and riding overhead levels so the wash does not overwhelm the drums.", "category": "Cymbals", "related_terms": ["Cymbal decay", "Cymbal sizzle rivets", "Drum bleed", "Overhead miking", "Cymbal mute"], "common_mistakes": ["Thinking more or bigger cymbals always sound better; excessive wash accumulates and clutters the top end.", "Trying to fix buildup with EQ alone instead of addressing cymbal choice, playing, and mic placement at the source.", "Placing overheads too close to loud crashes, so cymbals dominate the drum sound and pile up."], "scenario_contexts": ["Mixing a busy rock track where crashes ring into each other and hide the vocal.", "Recording a heavy-handed drummer whose overheads become harsh and washy.", "Choosing darker, thinner cymbals for a session to reduce clutter in the top end."]}, "b488412f-2639-42bb-8c5d-5d5a2a0119e1": {"definition": "A playing technique in which the drummer strikes a cymbal (usually a crash) and immediately grabs its edge to stop it ringing, producing a short, abrupt accent; on electronic kits it is a triggered feature that mutes the sampled cymbal in the same way.", "plain_english": "The drummer hits a cymbal, then grabs it fast to cut the sound short. It is like clapping your hand over a ringing bell to make it stop.", "purpose_function": "It gives a sharp, staccato accent that punctuates a beat or ends a phrase tightly, instead of leaving a long ring.", "practical_application": "Engineers must capture the choke cleanly on the overhead or crash mic, and on electronic pads they program the choke trigger so it mutes the cymbal sample when the edge is grabbed.", "category": "Cymbals", "related_terms": ["Cymbal decay", "Cymbal mute", "Cymbal edge blast", "Overhead miking", "Drum bleed"], "common_mistakes": ["Gating the overhead too hard so the short choke gets cut off or lost.", "On electronic kits, failing to enable the choke zone, so the pad rings out instead of stopping.", "Confusing a choke with a mute; a choke is a live hand grab, while a mute is a fixed accessory on the cymbal."], "scenario_contexts": ["A metal drummer choking a crash for tight, punchy stabs between riffs.", "Setting up an electronic drum pad so its choke zone mutes the sampled crash.", "Editing a drum take where the choked accent must stay short and defined."]}, "b2bffea3-b4cf-41ba-a828-86601c8952c2": {"definition": "The gradual fading of a cymbal's sound after it is struck, as the vibrating metal loses energy; the decay time is how long the tone rings out before falling silent.", "plain_english": "It is how long a cymbal keeps ringing after you hit it. A big crash rings for a long time. A tight cymbal fades away fast.", "purpose_function": "Decay shapes a cymbal's character and sustain, so knowing it helps players and engineers judge note length and how much wash a part adds.", "practical_application": "Engineers weigh decay when placing overheads, setting reverb tails, and choosing gate release times; long decay can smear fast passages, so darker or muted cymbals may be picked.", "category": "Cymbals", "related_terms": ["Cymbal buildup", "Cymbal mute", "Cymbal sizzle rivets", "Drum damping", "Overhead miking"], "common_mistakes": ["Setting a gate release too short, which chops off the natural decay and sounds unnatural.", "Assuming all cymbals decay the same; thickness, size, and alloy change the ring time a lot.", "Ignoring long decay in fast parts, so the wash blurs the groove."], "scenario_contexts": ["Choosing a fast-decaying cymbal for a quick, articulate jazz passage.", "Setting reverb so it does not fight a crash's own long decay.", "Timing a fade-out so the last cymbal is allowed to ring fully."]}, "c95ee755-3829-4d58-83f0-4accde1dfe0a": {"definition": "Striking a cymbal at its outer edge — typically with the shoulder of the stick on a crash or china — to produce the loudest, fullest, most explosive attack with the widest spread of overtones, as opposed to the more controlled tone from the bow or bell.", "plain_english": "Hitting a cymbal right on its outer rim for the biggest, loudest crash. The edge is the springiest part, so it gives the most powerful smash.", "purpose_function": "The edge moves the most when struck, so playing there gives maximum volume and a wide burst of sound used for accents and big impacts.", "practical_application": "Engineers expect high peak levels from edge hits, so they set overhead gain and any limiting with headroom, and may choose sturdier cymbals and careful mic placement to avoid clipping.", "category": "Cymbals", "related_terms": ["Cymbal choke", "Cymbal buildup", "Cymbal decay", "Overhead miking", "Drum bleed"], "common_mistakes": ["Leaving no headroom on overheads, so a hard edge hit clips the recording.", "Assuming edge and bow hits sound the same; the edge is louder and washier while the bow is more defined.", "Placing an overhead directly over the edge, exaggerating loud crashes over the rest of the kit."], "scenario_contexts": ["A rock drummer smashing crash edges for big chorus accents.", "Setting overhead gain to survive loud edge blasts without clipping.", "Choosing thicker crashes that hold up to hard edge playing."]}, "b7c55bcf-6512-4d93-aa42-a709f51c1253": {"definition": "Any accessory or method used to shorten a cymbal's sustain and tame its overtones, such as adhesive gel pads, tape, rubber rings, or clip-on mutes placed on the metal to absorb vibration.", "plain_english": "Anything stuck on a cymbal to make it ring less and sound shorter. It works like resting a finger on a guitar string to stop it buzzing.", "purpose_function": "It reduces unwanted wash and sustain, giving a drier, more controlled cymbal sound that fits denser mixes or quieter rooms.", "practical_application": "A technician adds mutes when overheads capture too much ring or when a cymbal clashes with the mix, trimming sustain without changing mic placement.", "category": "Cymbals", "related_terms": ["Cymbal decay", "Cymbal buildup", "Drum damping", "Cymbal choke", "Overhead miking"], "common_mistakes": ["Over-muting, which kills the cymbal's tone and life instead of just trimming the ring.", "Confusing a mute with a choke; a mute is a fixed accessory, while a choke is a live hand grab.", "Using tape residue that gums the cymbal and dulls it unevenly over time."], "scenario_contexts": ["Adding gel pads to a ride that rings too long in a close-miked studio.", "Taming a bright crash so it stops masking the vocal in a dense mix.", "Quieting cymbals for a low-volume rehearsal or podcast recording."]}, "d2e0f99a-80de-4778-8fd7-63da5a31712b": {"definition": "Small metal rivets fitted loosely through holes drilled near the edge of a cymbal — most often a ride — that rattle against the metal when it is struck, adding a sustained sizzling wash on top of the cymbal's normal tone.", "plain_english": "Little metal pins set loose in a cymbal so they buzz when it is hit. They add a long, sizzly hiss, like a snare's rattle riding on top of the cymbal.", "purpose_function": "The rivets extend and color the cymbal's sustain, giving a shimmering wash prized in jazz and ballads without needing an added effect.", "practical_application": "Engineers mic a sizzle ride knowing the extra high-frequency wash lingers, adjusting overhead placement, EQ, or gating so the sizzle sits in the mix rather than smearing it.", "category": "Cymbals", "related_terms": ["Cymbal decay", "Cymbal buildup", "Cymbal mute", "Overhead miking", "Drum bleed"], "common_mistakes": ["Expecting a sizzle ride to sound clean; the rivets add constant wash that fills the top end.", "Gating the overheads so hard that the sizzle tail is cut off unnaturally.", "Adding too many rivets, which drowns the cymbal's core tone in rattle."], "scenario_contexts": ["Recording a jazz ride whose rivets add shimmer under a brushed groove.", "Micing a ballad kit where the sizzle wash needs to sit softly behind the vocal.", "Deciding whether a sizzle ride's wash will clash with a busy arrangement."]}, "b04105ba-ad9d-49ae-a1ea-26969aa5f99d": {"definition": "A tom-tom fitted with both a batter (top) head and a resonant (bottom) head so the shell is enclosed at both ends; this two-head design gives more sustain, a fuller tone, and a pronounced pitch bend compared with a single-headed (open concert) tom.", "plain_english": "A tom with a drum skin on both the top and the bottom. Closing both ends makes it ring longer and sound fuller than a tom that is open underneath.", "purpose_function": "The resonant head lets the shell ring and reinforce the note, producing the warm, singing tone and sustain most drum kits are built around.", "practical_application": "A technician tunes both heads in relation to each other to set pitch and sustain, and decides whether to mic only the top or add a bottom mic to capture the resonant head.", "category": "Toms", "related_terms": ["Drum damping", "Drum bleed", "Resonant head", "Batter head", "Overhead miking"], "common_mistakes": ["Ignoring the bottom head when tuning, which leaves the tom ringing badly or choked.", "Assuming a bottom mic is always needed; the top head often captures enough of the tone.", "Confusing it with a single-headed concert tom, which has no resonant head and far less sustain."], "scenario_contexts": ["Tuning a rack tom's two heads for a warm, sustaining rock tone.", "Deciding to add a bottom mic to capture a floor tom's resonant head.", "Damping a double-headed tom that rings too long for a close-miked session."]}, "93025126-1e4f-494a-b2bb-adc2274499c6": {"definition": "Sound from one drum or source that is picked up by a microphone aimed at a different one — for example the snare leaking into the tom mics or into the overheads; also called spill or leakage.", "plain_english": "When a mic meant for one drum also picks up the others nearby. It is like a phone catching your neighbor's voice, not just yours.", "purpose_function": "Bleed is a natural result of close-miking many loud sources near each other; understanding it lets engineers control the balance and glue of a kit.", "practical_application": "Engineers manage bleed with mic choice, polar pattern, placement, gates, and phase checks, since too much leakage muddies the mix while a little can make a kit sound cohesive.", "category": "Microphone technique", "related_terms": ["Overhead miking", "Drum damping", "Cymbal buildup", "Phase cancellation", "Gate"], "common_mistakes": ["Assuming all bleed is bad; a controlled amount can make a kit sound natural and glued together.", "Ignoring phase between mics, so bleed causes cancellation and a thin, hollow sound.", "Gating aggressively to kill bleed, which chops transients and sounds unnatural."], "scenario_contexts": ["Snare leaking heavily into the tom mics on a tightly packed kit.", "Checking phase because hi-hat bleed thins out the overheads.", "Choosing cardioid mics to reduce bleed from nearby cymbals."]}, "e7151d04-f87a-4939-a44d-538b3c552aaa": {"definition": "The deliberate reduction of a drumhead's sustain and unwanted overtones using muffling materials — gel pads, dampening rings, tape, or a pillow or blanket inside the kick — to give a shorter, more focused tone.", "plain_english": "Adding something soft to a drum so it rings less and sounds tighter. It is like pressing a towel on a drum to stop the long boom.", "purpose_function": "It controls ring and boom that can clash in a mix, letting a technician tune the length and focus of a drum's sound at the source.", "practical_application": "Engineers add moongel, rings, or a kick pillow when a drum rings too long or muddies the track, tightening the sound before reaching for EQ or gates.", "category": "Drum tuning", "related_terms": ["Cymbal mute", "Double-headed tom", "Drum bleed", "Resonant head", "Gate"], "common_mistakes": ["Over-damping, which chokes the drum and kills its natural tone and sustain.", "Reaching for EQ to fix ring that should be tamed at the source with damping.", "Using heavy tape that leaves residue and dampens unevenly across the head."], "scenario_contexts": ["Adding a pillow inside the kick to tighten a boomy, ringing bass drum.", "Placing moongel on a snare that rings too long for a pop track.", "Fitting a dampening ring on a tom to control overtones before miking."]}, "eb92bd41-cc23-408a-bd05-4415a2381726": {"definition": "Drum muffling is the deliberate damping of a drumhead or shell to shorten sustain and tame unwanted overtones, using gels, tape, felt strips, internal dampers, muffle rings, or material placed inside the drum (such as a pillow or towel in a bass drum).", "plain_english": "Drum muffling means adding something like tape, a gel pad, or a folded towel to a drum so it rings less. It makes each hit sound shorter and more controlled.", "purpose_function": "It exists to control the length and pitch of a drum's ring so the recorded sound is tighter and sits better in a mix, trading raw sustain and resonance for focus and punch.", "practical_application": "An engineer applies a small gel or a strip of tape near the head's edge, or drops a pillow against the bass drum batter head, listening back on the mics until the ring is controlled without deadening the tone.", "category": "Drum Damping", "related_terms": ["Drum ring", "Drum shell resonance", "Kick batter head", "Kick boom", "Floor tom"], "common_mistakes": ["Over-muffling a drum until it sounds dead and lifeless, removing the resonance that gives it body and pitch.", "Assuming muffling can fix a badly tuned drum; tuning the heads should come first, with muffling used only for fine control.", "Placing tape or gel in the center of the head instead of near the edge, which chokes the fundamental tone rather than just the overtones."], "scenario_contexts": ["Taming a ringy snare in a bright room by adding a small gel near the rim before tracking.", "Dropping a pillow inside a bass drum through a ported front head to shorten the kick's sustain.", "Recording a jazz session where the engineer removes muffling to let the toms ring more openly."]}, "42244eee-73d2-43f3-95e0-b94d24f5e5de": {"definition": "A drum ring is the sustained, often high-pitched overtone a drum (typically a snare or tom) continues to produce after the initial attack, arising from the head's resonant modes; engineers frequently damp it to achieve a tighter, more focused sound.", "plain_english": "A drum ring is the high, singing tone a drum keeps making after you hit it. Engineers often try to tame it so the drum sounds tight instead of ringy.", "purpose_function": "The ring is a natural product of the head vibrating in its resonant modes; recognizing it matters because it can either add life to a drum or clash with a mix, which is why controlling it is a routine tracking decision.", "practical_application": "When a snare rings too long on the recorded track, a technician adds an O-ring, a gel, or a touch of tape and re-checks the mic, keeping enough ring for character but removing what smears the sound.", "category": "Drum Damping", "related_terms": ["Drum muffling", "Drum shell resonance", "Floor tom", "Kick boom", "Kick bleed"], "common_mistakes": ["Treating all ring as a problem; a controlled ring is part of a drum's natural tone and pitch.", "Killing ring with heavy muffling when the real cause is uneven head tension that could be fixed by tuning.", "Confusing a genuine tuning-related ring with a rattle from loose lugs or snare wires, and damping the head instead of tightening the hardware."], "scenario_contexts": ["Removing an annoying snare ring that only becomes obvious once the drum is close-miked.", "Deciding how much tom ring to keep for a rock ballad versus a fast punk track.", "Diagnosing whether a persistent ring is coming from the top head, the resonant head, or sympathetic buzz from another drum."]}, "5cf0d327-1f38-4052-a8cf-4cf26e41fe2b": {"definition": "Drum riser resonance is the low-frequency vibration and coloration introduced when a drum kit is set on a raised platform (riser) that mechanically couples with the drums and floor, often adding rumble, boom, or a hollow low-end resonance to the recorded sound.", "plain_english": "A drum riser is the raised platform a kit sits on. Riser resonance is the low rumble or boom that happens when that platform shakes along with the drums.", "purpose_function": "Risers exist to raise the drummer for sightlines and staging, but a hollow or poorly built one becomes an unwanted resonator that couples to the kick and floor tom, so understanding its resonance helps a technician keep the low end clean.", "practical_application": "A technician may fill or damp a hollow riser, add mass, or decouple it with rubber or foam when kick and floor-tom mics pick up excessive boom or a resonant rumble.", "category": "Drum Acoustics", "related_terms": ["Drum shell resonance", "Kick boom", "Floor tom", "Kick bleed", "Drum muffling"], "common_mistakes": ["Blaming a boomy low end on room modes when a hollow riser under the kit is actually resonating.", "Building or using a lightweight hollow riser that acts like a large drum, coloring the kick and floor tom.", "Trying to fix riser boom only with EQ instead of decoupling or damping the platform at the source."], "scenario_contexts": ["Recording a band on a stage riser and hearing a resonant boom couple into the kick mic.", "Filling a hollow drum riser with sandbags or damping material to reduce low-frequency rumble.", "Floating a riser on foam or rubber pads to isolate it from a resonant studio floor."]}, "92d25124-f9b1-4c8f-92ab-893bfa81e31f": {"definition": "Drum shell resonance is the natural vibration of a drum's shell at its characteristic frequencies, which combines with the vibrating heads to shape the drum's fundamental pitch, sustain, and tonal color; shell material, thickness, depth, and bearing edges all influence it.", "plain_english": "Every drum shell has a natural tone it likes to vibrate at. That built-in ringing is called shell resonance, and it helps shape the drum's main sound.", "purpose_function": "Shell resonance is what gives a drum much of its body and character beyond the heads, so knowing how a shell resonates helps a technician choose and place drums for the desired tone.", "practical_application": "When a drum sounds thin or boxy on tape, a technician may swap to a shell of different material or depth, or adjust head tuning to work with the shell's resonant pitch rather than fight it.", "category": "Drum Acoustics", "related_terms": ["Drum ring", "Drum muffling", "Floor tom", "Kick boom", "Drum riser resonance"], "common_mistakes": ["Believing the drumheads alone make the sound and ignoring how much the shell contributes to tone and sustain.", "Expecting every shell material to sound the same; maple, birch, and metal shells resonate quite differently.", "Trying to change a drum's core character with EQ alone when the shell's resonant behavior is the real limit."], "scenario_contexts": ["Choosing a birch versus maple kit for a session because of their different shell resonance and tone.", "Explaining to a client why a thin vintage shell rings longer and warmer than a thick modern one.", "Tuning a tom so its heads reinforce, rather than fight, the shell's natural resonant pitch."]}, "b329b175-75ef-4bdc-b096-fe5c8715893e": {"definition": "The floor tom is the largest and lowest-pitched tom-tom in a standard drum kit, typically 14 to 18 inches in diameter, that stands on its own legs on the floor (or is suspended) and provides the deep, sustained low-tom voice in fills and grooves.", "plain_english": "The floor tom is the biggest, lowest tom in a kit. It stands on the floor on its own legs and gives those deep, booming tom hits.", "purpose_function": "It exists to supply the low end of the tom range, adding weight and depth to drum fills and grooves that the smaller rack toms cannot reach.", "practical_application": "A technician close-mics the floor tom from above near the rim and may gate or damp it, because its long low-frequency sustain can ring on and bleed into other mics.", "category": "Drum Components", "related_terms": ["Drum shell resonance", "Drum muffling", "Kick bleed", "Drum ring", "Kick boom"], "common_mistakes": ["Miking a floor tom too far from the head, capturing more sustain and bleed than attack.", "Over-tightening the resonant head, which robs the floor tom of the deep sustain that defines it.", "Forgetting to control its long ring, so the floor tom booms under the whole kit and muddies the mix."], "scenario_contexts": ["Setting up a close mic on the floor tom before tracking a rock drum fill.", "Damping a floor tom's long sustain so it stops booming into the overhead mics.", "Choosing an 18-inch floor tom for extra low-end weight on a heavy track."]}, "b587864c-629f-49f7-ae37-117194c9f210": {"definition": "The kick batter head is the drumhead on the beater side of a bass drum, i.e. the head struck by the pedal beater; its type and tuning largely determine the attack, punch, and feel of the kick sound.", "plain_english": "The batter head is the drumhead the pedal hits on a bass drum. It is the side the beater strikes to make the sound.", "purpose_function": "It provides the surface the beater strikes and, together with the resonant front head, sets the kick's attack and sustain, which is why its choice and tuning are central to shaping the kick tone.", "practical_application": "A technician selects a batter head (single or double ply, with or without built-in damping) and tunes it low, sometimes adding a patch where the beater strikes, to get the desired amount of attack and thud.", "category": "Drum Components", "related_terms": ["Kick beater type", "Kick boom", "Kick bleed", "Drum muffling", "Drum shell resonance"], "common_mistakes": ["Confusing the batter head with the front (resonant) head; the batter is the side the beater strikes.", "Tuning the batter head too tight for a modern kick, producing a boingy, ringy tone instead of a tight thud.", "Skipping an impact patch, so the beater dents and wears through a bare batter head quickly."], "scenario_contexts": ["Fitting a pre-muffled batter head to get a tight, punchy kick without extra internal damping.", "Adding a felt or plastic impact patch where the beater strikes the batter head to protect it and sharpen the attack.", "Retuning the batter head lower to change a thin kick into a deeper, punchier one before tracking."]}, "b6eb5d52-305c-44f4-bac6-4310b0b9de90": {"definition": "Kick beater type refers to the material and shape of the bass drum pedal's beater head, such as felt, wood, plastic, or rubber, which directly affects the attack, click, and tonal character of the kick sound.", "plain_english": "The beater is the part of the bass drum pedal that hits the head. Its material, like felt, wood, or plastic, changes how punchy or clicky the hit sounds.", "purpose_function": "The beater is the striking element of the pedal, and its hardness and mass shape the balance between low thud and high-frequency click, which is why beater choice is a quick way to change kick attack.", "practical_application": "A technician swaps a soft felt beater for a hard plastic or wood one, or adds an impact patch, when a track needs more click and definition to cut through a dense mix.", "category": "Drum Hardware", "related_terms": ["Kick batter head", "Kick boom", "Kick bleed", "Drum muffling", "Drum shell resonance"], "common_mistakes": ["Reaching for EQ to add click when simply switching to a harder beater would create the attack naturally.", "Using a hard plastic beater on a bare, unpatched head, which speeds up wear and can dent the head.", "Ignoring how beater hardness changes the beater's rebound and feel for the drummer, not just the tone."], "scenario_contexts": ["Switching to a hard plastic beater to get more click for a metal track's kick.", "Choosing a soft felt beater for a warm, boomy jazz or soul kick sound.", "Pairing a wood beater with an impact patch to sharpen attack while protecting the head."]}, "4fca6fd7-373b-40c8-9989-0d7915280825": {"definition": "Kick bleed is the leakage of the bass drum's sound into microphones intended for other sources (such as snare, tom, or overhead mics), or conversely other drums bleeding into the kick mic, caused by the mics' proximity and the kick's high sound-pressure level.", "plain_english": "Kick bleed is when the loud kick drum leaks into microphones meant for other drums. It is like one voice getting picked up by someone else's microphone.", "purpose_function": "Bleed is an unavoidable result of close-miking a kit in one space, and understanding it matters because it affects phase, mix control, and how cleanly each drum can be balanced or processed.", "practical_application": "A technician reduces kick bleed with a directional (often cardioid or hypercardioid) mic inside a ported front head, careful placement, tunnels or blankets, and gating, while checking that the bleed still sums in phase with the other mics.", "category": "Microphone Technique", "related_terms": ["Kick boom", "Kick batter head", "Floor tom", "Drum muffling", "Drum riser resonance"], "common_mistakes": ["Assuming a noise gate fully removes kick bleed; gating cleans up gaps but bleed still colors the drum's live sound.", "Ignoring phase when the kick bleeds into overheads, which can thin or hollow out the low end when tracks are summed.", "Cranking gain on a distant kick mic and capturing more room and snare bleed than actual kick."], "scenario_contexts": ["Building a kick tunnel with a blanket-covered stand to reduce bleed and room in the kick mic.", "Checking that kick bleed in the overheads is in phase before committing to a mix.", "Choosing a hypercardioid kick mic and placement to minimize snare and hi-hat spill."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"a921bda5-7142-4fed-8619-82b53d38f159": {"definition": "Kick boom is the low-frequency body and resonance of a bass drum, generally centered in the low bass region around 60 to 100 Hz, that gives the kick its weight and depth as distinct from the higher-frequency beater click.", "plain_english": "Kick boom is the deep, low thump you feel from a bass drum. It is the big low-end part of the sound, not the click of the beater.", "purpose_function": "The boom carries the kick's power and low-end weight in a mix, so managing it is essential to a kick that is felt without becoming muddy or overpowering the bass guitar.", "practical_application": "A technician shapes kick boom with head tuning, damping, mic placement, and EQ, boosting or cutting the low bass region and carving space so the kick and bass guitar do not mask each other.", "category": "Drum Acoustics", "related_terms": ["Kick batter head", "Kick beater type", "Kick bleed", "Drum riser resonance", "Drum muffling"], "common_mistakes": ["Adding too much low-frequency boost so the kick booms and masks the bass guitar in the mix.", "Confusing boom (the low body) with attack (the beater click); they live in different frequency ranges and need separate control.", "Blaming an uncontrolled boom on the drum when a resonant riser or room mode is exaggerating the low end."], "scenario_contexts": ["EQing the 60 to 100 Hz region to dial in kick weight without masking the bass guitar.", "Adding internal damping to shorten a boomy, ringing low end on the bass drum.", "Diagnosing whether excess boom comes from the drum, the riser, or a room mode before reaching for EQ."]}, "e3d7a756-0717-4cb2-9863-954c2949e47c": {"definition": "A kick drum trigger is a piezoelectric or acoustic-drum sensor mounted on the bass drum's hoop, shell, or beater-side head that converts each beater impact into an electronic pulse, which a drum module or DAW instrument uses to layer or replace the acoustic kick sound.", "plain_english": "A small sensor that clips onto the kick drum. It feels each hit of the beater. Then it sends a signal that plays a stored kick sound. Players use it to make the kick louder or more even.", "purpose_function": "It turns the physical beater hit into a trigger signal so an engineer can reinforce or replace a weak, boomy, or inconsistent acoustic kick with a controlled, repeatable sample.", "practical_application": "A technician clamps the trigger to the hoop or mounts it inside the drum, sets sensitivity and threshold on the trigger module, and blends or replaces the miked kick with a sample in live sound or recording.", "category": "Kick drum", "related_terms": ["Kick-drum pillow", "Kick port", "Kick resonant head", "Ported kick head", "Kick phase alignment"], "common_mistakes": ["Setting the threshold too low, so bleed from the snare or nearby toms causes false triggers and double hits.", "Mounting the sensor loosely, so its output level jumps around and it misses softer hits.", "Assuming a trigger replaces good tuning and miking; a poorly tuned drum still triggers erratically."], "scenario_contexts": ["Reinforcing a soft acoustic kick at a loud live show so it cuts through the mix.", "Layering a sampled sub-thump under a recorded kick in a DAW for a modern pop production.", "Fully replacing a bleed-heavy or inconsistent kick during drum editing in post."]}, "6a79137d-bb3c-4d6d-af2d-4825cfb89643": {"definition": "Kick phase alignment is the practice of time-aligning the multiple microphone signals capturing one bass drum — such as an inside beater mic and an outside resonant-head mic, plus overheads and room mics — so their low-frequency waveforms sum constructively instead of partially cancelling.", "plain_english": "A kick is often caught by more than one mic. Each mic sits a bit farther away, so the sound reaches them at slightly different times. If they fight, the low end gets thin. Lining them up keeps the bass strong.", "purpose_function": "Because sound takes time to travel between mics, their signals can arrive out of phase and cancel the low end; aligning them preserves punch, weight, and a solid mono-compatible bottom end.", "practical_application": "An engineer flips a mic's polarity switch, nudges one track earlier in the DAW, or uses a phase tool while watching the waveforms and listening in mono until the kick sounds fullest.", "category": "Kick drum", "related_terms": ["Kick drum trigger", "Kick port", "Kick resonant head", "Ported kick head", "Kick tunnel"], "common_mistakes": ["Judging phase only in solo and stereo; low-end cancellation shows up most when the whole mix is heard in mono.", "Flipping polarity at random instead of choosing the setting that gives the fullest, loudest low end.", "Forgetting that the outside mic is often reversed in polarity relative to the inside mic."], "scenario_contexts": ["Blending an inside and an outside kick mic on a rock session so the two sum to a punchy low end.", "Aligning the kick close mics against the overheads before committing a drum mix.", "Checking mono compatibility of a kick for broadcast or club playback."]}, "04ae4098-3a81-4a84-8556-2aca7fe3db9c": {"definition": "A kick port is a hole cut into the front (resonant) head of a bass drum, typically several inches across and offset from the centre, that lets an engineer place a microphone inside the drum and lets internal air escape on each hit.", "plain_english": "A round hole cut in the front skin of the kick drum. It lets a mic reach inside near the beater. It also lets air puff out with each hit. This gives more attack and less long boom.", "purpose_function": "It gives microphone access to the beater impact and vents internal air pressure, which shortens sustain and adds attack for a tighter, more focused kick sound.", "practical_application": "A technician cuts or fits a pre-made ported head, threads a mic through the port toward the beater, and adjusts the mic depth to trade attack against body.", "category": "Kick drum", "related_terms": ["Ported kick head", "Kick resonant head", "Kick tunnel", "Kick-drum pillow", "Kick drum trigger"], "common_mistakes": ["Cutting the port dead-centre, which weakens the head and chokes tone; an offset hole is standard.", "Cutting the hole too large, killing most of the resonance and low-end sustain.", "Assuming a port is always needed; a solid front head gives more sustain and low end when that is wanted."], "scenario_contexts": ["Setting up a rock kick so an engineer can get a mic close to the beater.", "Adding attack and reducing boom on a jazz or funk kick for a tighter sound.", "Running both an inside port mic and an outside sub mic on a large studio session."]}, "b80192c6-4f13-478d-866b-f24d757da9fc": {"definition": "The kick resonant head is the front drumhead of a bass drum — the one not struck by the beater — whose vibration shapes the drum's sustain, low-end tone, and overall resonance.", "plain_english": "The front skin of the kick drum. The beater never hits this one. It rings after each hit and sets how long the boom lasts. A whole, tight head rings more; a ported or damped one rings less.", "purpose_function": "It couples the vibrating batter head and the enclosed air to the outside, setting how much sustain, pitch, and body the kick produces.", "practical_application": "An engineer chooses and tunes the resonant head — solid, ported, or damped — to dial sustain and pitch, and often places an outside mic a short distance from it to capture low-end weight.", "category": "Kick drum", "related_terms": ["Kick port", "Ported kick head", "Kick-drum pillow", "Kick tunnel", "Single-headed tom"], "common_mistakes": ["Tuning the resonant head much too loose, causing a flabby, pitch-less kick with uncontrolled wrinkles.", "Removing the resonant head entirely and expecting the same low end; the front head builds body and sustain.", "Blaming a boomy kick only on mic choice while ignoring the resonant head's tuning."], "scenario_contexts": ["Tuning a bass drum's front head to set sustain before a recording session.", "Deciding between a solid or ported front head for a given musical style.", "Placing an outside mic in front of the resonant head to capture sub-low energy."]}, "899ae81a-fc4f-4d42-b929-7cf40ffb849f": {"definition": "A kick tunnel is an enclosure — often an extra bass-drum shell, a purpose-built frame, or a heavy blanket over a stand — placed in front of the kick drum's resonant head to shield the outside mic from stage or room bleed and to reinforce low-end capture.", "plain_english": "A tunnel or box built around the front of the kick drum. It wraps the outside mic in its own little room. This blocks sound from cymbals and other drums. It also traps low end for a bigger boom.", "purpose_function": "It isolates the front kick mic from bleed and builds up low-frequency pressure around it, giving a cleaner, weightier kick that is easier to process.", "practical_application": "An engineer drapes a heavy moving blanket over a mic stand or uses a second shell to form a short tunnel between the drum and the outside mic, especially on loud stages or in untreated rooms.", "category": "Kick drum", "related_terms": ["Kick resonant head", "Kick port", "Kick-drum pillow", "Kick phase alignment", "Kick drum trigger"], "common_mistakes": ["Sealing the tunnel so tightly that trapped low pressure overloads the mic and muddies the sound.", "Letting the blanket or shell touch and rattle against the resonant head, adding buzz.", "Expecting a tunnel to fix a poor drum sound instead of isolating an already good one."], "scenario_contexts": ["Isolating the kick mic on a loud live stage with close cymbals.", "Recording drums in an untreated room where bleed and reflections are a problem.", "Chasing a large, controlled low-end kick sound in a rock or metal production."]}, "cd36a367-8ecc-4ceb-b664-8e3cd8cc1c36": {"definition": "A kick-drum pillow is a pillow, folded blanket, or foam dampener placed inside the bass drum, usually resting against the batter or resonant head, to absorb resonance and shorten the drum's sustain.", "plain_english": "A pillow or blanket stuffed inside the kick drum. It presses against a skin and soaks up the ring. This makes the kick shorter and punchier. It cuts the long boom that can wash out a mix.", "purpose_function": "It controls unwanted ring and low-end sustain, tightening the kick into a focused thump that sits cleanly in a mix.", "practical_application": "A technician slides a pillow through the port or an open head, moves it toward more or less head contact to set the damping, and wedges it so it does not shift during playing.", "category": "Kick drum", "related_terms": ["Kick port", "Kick resonant head", "Ported kick head", "Kick tunnel", "Kick drum trigger"], "common_mistakes": ["Overstuffing the drum until the kick is dead and lifeless, with no tone or sustain left.", "Leaving the pillow loose so it slides during the take and changes the sound between hits.", "Using a pillow to hide a badly tuned head instead of tuning first, then damping."], "scenario_contexts": ["Tightening a boomy kick for a pop or rock recording.", "Quickly taming an unfamiliar house kit at a live gig.", "Adjusting damping to trade attack against sustain during tracking."]}, "2926d746-4333-4188-a13c-30f2954842ca": {"definition": "A ported kick head is a bass-drum resonant (front) head that has a port hole cut or moulded into it, combining the tonal role of the resonant head with a built-in opening for microphone access and air venting.", "plain_english": "A front kick skin that already has a hole in it. It works like a normal front head but vents air through the port. The hole lets a mic reach inside. It also trims the long boom for more attack.", "purpose_function": "It gives the shorter, punchier, mic-friendly response of a ported drum without cutting a hole by hand, offering a consistent factory port.", "practical_application": "An engineer fits a ready-made ported head so the kick has repeatable venting and easy inside-mic placement from session to session.", "category": "Kick drum", "related_terms": ["Kick port", "Kick resonant head", "Kick-drum pillow", "Kick tunnel", "Kick drum trigger"], "common_mistakes": ["Confusing a ported head with a fully open, headless front; the port only vents part of the head.", "Choosing a large offset port when a smaller hole would keep more low-end sustain.", "Assuming every style needs a port; some genres want a solid, fuller-ringing front head."], "scenario_contexts": ["Buying a pre-ported front head so a studio kick is mic-ready out of the box.", "Standardising kick venting across a rehearsal-room or rental kit.", "Getting an attack-forward kick for rock without modifying a solid head."]}, "4a98ec8e-d0cb-4792-8923-d2df1aa9ec61": {"definition": "A rack tom is a tom-tom mounted above or in front of the drummer — typically suspended from the bass drum or a stand — as opposed to a floor tom that stands on its own legs; rack toms are usually the smaller, higher-pitched toms of the kit.", "plain_english": "A tom drum held up on a stand or on top of the kick drum. It sits in front of the drummer, up high. These are the smaller, higher toms. They are the ones a drummer rolls across in a fill.", "purpose_function": "It provides higher-pitched melodic tom voices within easy reach above the snare, filling out the kit's range for fills and grooves.", "practical_application": "A technician mounts, tunes, and mics each rack tom, often close from the top, and checks that the mount does not choke the shell's resonance.", "category": "Toms", "related_terms": ["Single-headed tom", "Kick resonant head", "Kick phase alignment", "Kick-drum pillow", "Kick port"], "common_mistakes": ["Over-tightening a bass-drum tom mount, which chokes the shell and kills sustain; isolation mounts help.", "Miking every rack tom without checking phase against the overheads, thinning the kit's sound.", "Tuning rack toms with no interval relationship, so fills sound uneven and muddy."], "scenario_contexts": ["Setting up and close-miking the high toms for a rock drum session.", "Tuning the rack toms in clear intervals for smooth-sounding fills.", "Gating and phase-checking rack-tom tracks during a drum mix."]}, "dc0ce674-d07f-467c-b688-160a37e903bd": {"definition": "A single-headed tom, also called a concert tom, is a tom-tom fitted with only a batter head and no resonant (bottom) head, giving a shorter, more sharply pitched, faster-decaying sound with an open shell underneath.", "plain_english": "A tom with just a top skin and no bottom skin. The shell is open underneath. It rings for a shorter time and speaks fast. Its pitch is clear and it is easy to mic from below.", "purpose_function": "It gives a punchy, articulate tom with quick decay and simple tuning, popular in certain rock and studio setups and easy to mic through the open shell.", "practical_application": "An engineer can place a mic inside or under the open shell and tune only the single batter head, trading the fuller sustain of a two-headed tom for speed and attack.", "category": "Toms", "related_terms": ["Rack tom", "Kick resonant head", "Kick phase alignment", "Ported kick head", "Kick port"], "common_mistakes": ["Expecting the long sustain of a double-headed tom; single-headed toms decay quickly by design.", "Overlooking the open shell, which lets more bleed from other drums into the tom mic.", "Tuning the batter head too low, where a tom with no bottom head loses focus and pitch."], "scenario_contexts": ["Recording a 1970s-style rock kit that uses concert toms.", "Miking toms from inside the open shell to reduce cymbal bleed.", "Choosing single-headed toms for fast, articulate fills with quick decay."]}, "60d31988-52a3-45ee-95f2-d448c90238c9": {"definition": "The top drumhead of a snare drum — the upper membrane struck with the stick — usually a thicker, often coated single- or double-ply head; it sits opposite the thin snare-side (resonant) head, and its type and tuning largely set the drum's attack, pitch and sustain.", "plain_english": "The top skin of a snare drum. It is the one the drummer hits with the stick. It is thicker than the bottom skin. Its tuning shapes the drum's tone and punch.", "purpose_function": "It gives the playing surface that is struck and set vibrating, and its material, ply count, coating and tension decide the snare's attack, tone and feel.", "practical_application": "An engineer or drum tech picks and tunes the batter head for the wanted sound, then places the top snare mic a few centimetres above its edge, angled toward the centre.", "category": "Drum head", "related_terms": ["Snare-side head", "Snare wires", "Snare damping", "Snare ring", "Snare throw-off"], "common_mistakes": ["Confusing the batter head (top, struck) with the snare-side head (thin bottom head the wires rest on).", "Thinking head choice does not matter, when ply, coating and material strongly change attack and sustain.", "Over-tightening the batter head hoping for more crack, which chokes the drum and stresses the head.", "Tightening lugs unevenly, so the head is not seated flat and gives uneven pitch and short life."], "scenario_contexts": ["Swapping a worn coated batter head before a session to restore a fat, focused snare tone.", "Tuning the batter head up or down to suit a song's feel and key.", "Placing a top mic just above the batter head's rim for the main snare sound."]}, "0e934d91-29d9-4958-96bd-5e658f2791cc": {"definition": "The controlled reduction of a snare drum's ring, sustain and stray overtones by adding mass or friction to the batter head — with gel pads, tape, cloth, muffling rings or a wallet — while keeping the drum's attack; the amount is set to taste and to suit the mic and room.", "plain_english": "Ways to calm a snare's ring. You stick a gel pad, tape, or a cloth on the top skin. This shortens the ringing tail. The drum then sounds tighter and more controlled.", "purpose_function": "It tames long metallic ring and stray overtones that can clash with a mix or a mic, so the drum reads as tight and focused while keeping its initial crack.", "practical_application": "When a miked snare rings too long, a tech adds a small gel pad, a strip of tape, or a muffling ring near the edge and listens back until the tail is controlled.", "category": "Damping", "related_terms": ["Snare ring", "Snare batter head", "Snare wires", "Snare-side head", "Snare throw-off"], "common_mistakes": ["Over-damping until the life and tone are gone, leaving a dull, dead thud.", "Damping to fix a tuning problem, when even tuning often controls ring better than muffling.", "Placing damping dead centre where the stick lands, which kills attack and wears the material fast.", "Assuming more damping always records better, when a little ring often sits fine once the kit is in a mix."], "scenario_contexts": ["Adding a gel pad to a ringing snare so it records tight and controlled.", "Taping a folded tissue near the rim to shorten a bright snare's tail for a dry, vintage sound.", "Removing damping to open up a snare that sounds too choked."]}, "cd5b7276-ed00-4e43-b095-dbc4c9390acf": {"definition": "The sustained, often metallic overtone that carries on after the initial snare stroke, produced by the batter head, resonant head and shell resonating together; a moderate ring adds body and sustain, but excessive or dissonant ring is a common problem when close-miking a snare.", "plain_english": "The ringing tone that hangs on after you hit a snare. A little bit adds life. Too much sounds annoying, like a long metallic buzz. Engineers often try to control it.", "purpose_function": "It is a natural result of the heads and shell vibrating; hearing it clearly lets a tech decide how much sustain to keep and how much to remove for a given song or mic setup.", "practical_application": "Hearing an unwanted ring on a close-miked snare, an engineer tunes the heads more evenly, adds light damping, or uses a narrow EQ cut on the ringing frequency.", "category": "Drum acoustics", "related_terms": ["Snare damping", "Snare batter head", "Snare-side head", "Snare wires", "Snare throw-off"], "common_mistakes": ["Trying to remove ring only with heavy damping when uneven head tuning is the real cause.", "Confusing pleasant sustain with the harsh, dissonant ring that clashes with a mix.", "Reaching for EQ first when a small tuning change at the lugs fixes the ring more musically.", "Assuming all ring is bad, when some sustain gives the snare body and helps it carry."], "scenario_contexts": ["Chasing an annoying overtone on a close-miked snare during tracking.", "Fine-tuning lugs to even out a snare's ring before recording.", "Using a narrow EQ cut to reduce a ringing frequency in the mix."]}, "9e0cc1c1-ed74-4919-92de-14d94d681541": {"definition": "The lever mechanism on the side of a snare drum — also called the strainer — that pulls the snare wires tight against the snare-side head or releases them; throwing it off drops the wires away so the drum sounds like a tom, and a paired knob sets wire tension.", "plain_english": "The lever on the side of a snare drum. Flip it up and the wires press on the bottom skin, giving the buzzy crack. Flip it off and the wires drop away, so the drum sounds like a plain tom.", "purpose_function": "It engages or disengages the snare wires and sets their tension, letting the player switch between the snappy snare sound and an unsnared, tom-like sound and dial in buzz and sensitivity.", "practical_application": "Before a take a drummer or tech sets wire tension with the throw-off's knob and checks that the lever throws cleanly; a loose or rattling throw-off is a common cause of buzz and is tightened or serviced.", "category": "Drum hardware", "related_terms": ["Snare wires", "Snare-side head", "Snare batter head", "Snare damping", "Snare ring"], "common_mistakes": ["Confusing the throw-off (the lever) with the snare wires themselves.", "Setting wire tension too tight with the throw-off, which chokes the wires and kills the buzz.", "Ignoring a worn or loose throw-off that lets wires rattle and buzz during a take.", "Throwing the strainer on or off harshly, which can knock the tuning or damage the wires over time."], "scenario_contexts": ["Disengaging the throw-off so the snare plays like a tom for a song part.", "Adjusting the strainer's fine-tune knob to dial in snare wire tension before tracking.", "Servicing a rattling throw-off that is causing unwanted buzz on a recording."]}, "21bc70a8-0d41-4f77-8eab-f9a29058829c": {"definition": "The polarity relationship between a mic on the snare's batter (top) head and one on the snare-side (bottom) head; because the two heads move in opposite directions, the mics capture opposite pressure swings, so the bottom mic's polarity is normally inverted to stop the two signals cancelling and to keep body and snap when they are combined.", "plain_english": "When you mic a snare on top and bottom, the two skins move opposite ways. So the two mics fight each other and can cancel out. Flipping the bottom mic's polarity fixes this. The snare then sounds full instead of thin.", "purpose_function": "Inverting the bottom mic's polarity lines the two snare signals up so they add instead of subtract, preventing a thin, weak sound and preserving low-end body and high-end snap when the mics are summed.", "practical_application": "After placing top and bottom snare mics, an engineer flips the polarity switch on the bottom mic's channel and listens for the fullest, punchiest blend, often checking both settings to hear which is stronger.", "category": "Recording technique", "related_terms": ["Snare-side head", "Snare batter head", "Snare wires", "Snare damping", "Snare ring"], "common_mistakes": ["Forgetting to invert the bottom snare mic, so the two mics partly cancel and the snare sounds thin.", "Assuming a polarity flip is always right, when mic distance also shifts phase and you should just listen.", "Confusing polarity inversion (flipping the waveform) with time-based phase from mic spacing.", "Inverting the wrong channel, or both, which undoes the correction."], "scenario_contexts": ["Setting up top and bottom snare mics and flipping the bottom mic's polarity for a fuller sound.", "A/B testing the polarity switch to hear which setting gives more body and snap.", "Troubleshooting a thin, hollow snare that turns out to be the top and bottom mics cancelling."]}, "2887134a-d862-4dc2-a3be-0fec053023bd": {"definition": "A drum trigger — a piezo or similar transducer — fixed to the snare drum (clamped to the rim or mounted on the shell or head) that turns each strike into an electronic pulse used to fire a sampled or synthesized snare from a drum module, sampler or software, either replacing or reinforcing the acoustic snare.", "plain_english": "A small sensor fixed to the snare drum. Every time the drum is hit, the sensor sends an electric signal. That signal plays a snare sample from a module or computer. It can add to or replace the real drum sound.", "purpose_function": "It turns an acoustic hit into a control signal, so a tech can add consistent sample reinforcement, replace a poor sound, or drive fully electronic drums, helping get a strong, even snare in loud or difficult settings.", "practical_application": "A tech clamps a trigger to the snare rim, runs it to a drum module or triggering software, and sets sensitivity and threshold so it fires on real hits but not on bleed from other drums.", "category": "Electronic percussion", "related_terms": ["Snare-gate mistriggering", "Snare batter head", "Snare wires", "Snare damping", "Snare ring"], "common_mistakes": ["Setting sensitivity too high, so hits on nearby drums (crosstalk) fire the snare sample falsely.", "Setting the threshold too high, so soft ghost notes are missed.", "Mounting the trigger loosely, which gives weak or double triggers.", "Assuming a trigger captures dynamics perfectly, when poor setup can flatten the drummer's touch."], "scenario_contexts": ["Clamping a trigger to the snare to reinforce a weak acoustic drum in a loud live mix.", "Using a trigger to replace a bleed-heavy snare with a clean sample during mixing.", "Dialing in threshold and sensitivity so the trigger fires on hits but not on tom bleed."]}, "f90e9dcc-0060-4b79-bee5-96f45b195137": {"definition": "The set of thin coiled metal wires (also called snares or the 'snappy') stretched across the outside of the snare-side head; when the batter head is struck, the resonant head vibrates against these wires to produce the bright, buzzing rattle that gives the snare drum its name and character.", "plain_english": "The coiled metal wires stretched under a snare drum. When you hit the top skin, the bottom skin buzzes against these wires. That buzz is the snare's signature crack and rattle. Loosen or remove them and it sounds like a tom.", "purpose_function": "They add the sharp, buzzy snap to each stroke; their tension and the number of strands set the drum's sensitivity, sustain and how tight or loose the buzz sounds.", "practical_application": "A drum tech sets wire tension with the throw-off to balance snap and buzz, and an engineer may add a bottom mic to capture the wires' detail while watching for sympathetic buzz from other drums.", "category": "Drum hardware", "related_terms": ["Snare throw-off", "Snare-side head", "Snare batter head", "Snare damping", "Snare ring"], "common_mistakes": ["Over-tightening the wires, which chokes them into a short, lifeless snap.", "Leaving the wires too loose, giving a sloppy, buzzy rattle that trails after every hit.", "Blaming the room for sympathetic snare buzz when detuning or a light touch on the wires would fix it.", "Confusing the snare wires with the snare-side head they rest against."], "scenario_contexts": ["Adjusting snare-wire tension to balance crisp snap against buzz before a take.", "Adding a bottom snare mic to capture the detail of the wires.", "Muting sympathetic wire buzz that rings when the toms or bass are played."]}, "90ac4a32-b976-4408-aacf-62a55c15f15e": {"definition": "A fault in which a noise gate on the snare channel opens or closes at the wrong moments — false-opening on hi-hat or tom bleed, chattering, or failing to open on soft ghost notes — because its threshold, timing or key/sidechain filtering is not set correctly for the drum's dynamics and the surrounding spill.", "plain_english": "A noise gate should open only when the snare is hit. Mistriggering is when it opens at the wrong time. Loud hi-hat or tom bleed can trip it. Or it may miss quiet snare hits. Both leave the snare sounding wrong.", "purpose_function": "Spotting mistriggering matters because a snare gate is meant to cut bleed between hits; when it misfires it lets in spill or chops off wanted hits, so the tech must retune the gate rather than trust it blindly.", "practical_application": "When a snare gate chatters or drops ghost notes, an engineer adjusts threshold, attack, hold and release, and uses a key filter or the bottom mic as the trigger source so only real snare hits open the gate.", "category": "Mixing", "related_terms": ["Snare trigger", "Snare wires", "Snare batter head", "Snare damping", "Snare-side head"], "common_mistakes": ["Setting the threshold between the snare's loud and soft hits, so ghost notes are cut off.", "Not using a key filter, so loud hi-hat or tom bleed keeps false-opening the gate.", "Setting the release too fast, which makes the gate chatter and clip the snare's tail.", "Trusting the gate untended instead of checking it across the whole performance's dynamics."], "scenario_contexts": ["A snare gate false-opening every time the hi-hat is hit during mixdown.", "Ghost notes disappearing because the gate threshold is set too high.", "Adding a key/sidechain filter so only snare hits open the gate."]}, "78ae085e-1516-43b9-9d8a-468ac10381d7": {"definition": "The thin lower drumhead of a snare drum — also called the resonant or snare head — mounted opposite the batter head with the snare wires resting against its outer surface; being very thin (typically around 2–3 mil), it responds readily to the batter head's vibration and drives the wires that create the drum's buzz.", "plain_english": "The thin bottom skin of a snare drum. The metal snare wires sit against it. When the top skin is hit, this thin skin vibrates and rattles the wires. That is what makes the snare buzz.", "purpose_function": "Its thinness lets it react quickly to the struck batter head and pass that energy to the snare wires; its tuning strongly affects the drum's sensitivity, snare response and sustain.", "practical_application": "A drum tech tunes the snare-side head fairly tight for a crisp, responsive buzz, handles it carefully because it tears easily, and an engineer may place a bottom mic near it to capture wire detail.", "category": "Drum head", "related_terms": ["Snare batter head", "Snare wires", "Snare throw-off", "Snare top-bottom polarity", "Snare damping"], "common_mistakes": ["Confusing the snare-side (bottom) head with the batter (top) head that is struck.", "Tuning the very thin snare-side head like a thick batter head and tearing it.", "Detuning it too loose, which gives a sloppy, buzzy, unresponsive snare.", "Striking the snare-side head to play it, when it is a resonant head, not a playing surface."], "scenario_contexts": ["Replacing a torn snare-side head and tuning it tight for crisp wire response.", "Placing a bottom mic near the snare-side head to capture the wires.", "Adjusting snare-side head tension to change the snare's sensitivity and buzz."]}, "004ab7a1-e1c5-42c7-accf-75ebba5a9d2e": {"definition": "The degree of tightness applied to the snare wires (the coiled metal strands stretched across the resonant bottom head of a snare drum) via the strainer/throw-off, which sets how freely the wires vibrate against the head and thus controls the drum's snare response, sensitivity, and buzz.", "plain_english": "Snare wires are the springy metal strands under a snare drum. Tighter wires give a crisp, short snap. Looser wires give a buzzy, rattly sound.", "purpose_function": "It sets how the metal snares react to the head's vibration, tuning the balance between a crisp attack and a buzzy sustain so the snare suits the song and the mic.", "practical_application": "Before tracking, the engineer or drummer adjusts the strainer tension to get an even snare response with no excess buzz; too loose sounds sloppy, too tight chokes the drum.", "category": "Snare Tuning", "related_terms": ["Resonant head", "Snare buzz", "Drum tuning", "Batter head", "Top-bottom head relationship"], "common_mistakes": ["Cranking the wires very tight to kill buzz, which chokes the drum and kills its natural response.", "Blaming snare buzz on the wires when the real cause is a poorly tuned resonant head or sympathetic vibration from other drums.", "Leaving the strainer too loose, giving an uneven, sloppy rattle instead of a crisp snare."], "scenario_contexts": ["Dialing in the strainer before tracking so the snare responds crisply without excess buzz.", "Loosening the wires slightly for a looser, more open snare on a vintage or roots session.", "Chasing sympathetic snare buzz during tom hits by adjusting wire tension and tuning."]}, "1860d2ee-8347-4627-9382-30df2141655b": {"definition": "The controlled reduction of a tom-tom's ring and sustain by adding energy-absorbing material (gel pads, tape, foam, external or internal mufflers, or dampening rings) to the drumhead, which shortens decay and tames unwanted overtones.", "plain_english": "Damping means adding a gel pad, tape, or foam to a tom so it does not ring so long. It is like putting your hand on a bell to make it stop humming.", "purpose_function": "It tames long ring and stray overtones so toms record tight and controlled, helping them sit better in a dense mix.", "practical_application": "The engineer sticks a gel pad or a strip of tape near the edge of the head to shorten decay when a tom rings too much, and removes it if the drum starts to sound dead.", "category": "Drum Damping", "related_terms": ["Tom ring", "Tom sustain", "Drum tuning", "Dampening ring", "Resonant head"], "common_mistakes": ["Over-damping toms with too much gel or tape, leaving them dead and lifeless with no tone.", "Using damping to fix a badly tuned tom instead of tuning the heads first.", "Assuming more damping always cleans up the mix; some ring gives toms their body and pitch."], "scenario_contexts": ["Adding a gel pad to a rack tom that rings too long during a dense rock track.", "Removing damping to open up floor toms for a big, ambient recording.", "Taping a small strip near the head edge to tame one ugly overtone without deadening the drum."]}, "8c207d98-7bd7-4108-9efb-71928ea6132f": {"definition": "A noise gate applied to a tom-tom channel that mutes the signal below a set threshold and opens only when the tom is struck, removing bleed from cymbals, snare, and the rest of the kit during passages when the tom is not played.", "plain_english": "A gate is an automatic switch on the tom mic. It stays shut and opens only when the tom is hit. That way you do not hear the rest of the kit leaking in.", "purpose_function": "Toms are only played now and then, so their open mics pick up bleed; a gate keeps those channels silent until the tom is struck, cleaning up the recorded or live sound.", "practical_application": "The engineer sets the threshold above the bleed level and dials in attack, hold, and release so the gate opens fast on the hit and closes cleanly without cutting the tom's decay.", "category": "Signal Processing", "related_terms": ["Noise gate", "Threshold", "Microphone bleed", "Tom trigger", "Attack and release"], "common_mistakes": ["Setting the threshold too low, so cymbal and snare bleed keeps opening the gate.", "Setting the release too fast, which chops off the tom's natural decay and makes it sound clipped.", "Setting the threshold too high, so soft or ghost hits never open the gate and get lost."], "scenario_contexts": ["Gating each tom channel in a multitrack rock mix to remove cymbal bleed between fills.", "Setting up live tom gates so open tom mics don't muddy the front-of-house sound.", "Adjusting gate hold and release so a tom fill's decay stays intact."]}, "6b845103-ee3d-4dad-a136-98eb3e2b0ff9": {"definition": "The time and phase alignment between the multiple microphones capturing a tom (for example a close mic against the overheads and room, or a top and bottom tom mic), where differences in arrival time cause constructive or destructive interference that changes the recorded tom's tone and level.", "plain_english": "The same tom hit reaches each mic at a slightly different time. If the mic signals do not line up, they can fight each other. That can make the tom sound thin and weak.", "purpose_function": "Several mics capture each tom, and how their signals line up in phase decides whether frequencies add up or cancel; getting it right keeps the tom full and punchy.", "practical_application": "When a bottom tom mic or the overheads are out of phase with the close mic, the engineer flips the polarity switch or nudges the tracks in time until the tom sounds fullest.", "category": "Phase and Alignment", "related_terms": ["Polarity", "Overhead miking", "Phase cancellation", "Close miking", "Microphone bleed"], "common_mistakes": ["Confusing the polarity (phase) button with EQ; flipping it changes how mics combine, not the tone of one mic on its own.", "Ignoring the overhead-to-close-mic phase, so toms turn thin once all mics are combined.", "Fixing phase by ear on a single tom but never checking the whole kit summed to mono."], "scenario_contexts": ["Checking polarity between the close tom mic and the overheads to keep toms full in mono.", "Nudging a bottom tom mic track in the DAW to align it with the top mic.", "Flipping the polarity switch on a tom channel and keeping whichever setting sounds fuller."]}, "fc873259-2c77-4bfe-a989-62b09e12eb9a": {"definition": "A tom mounting system that suspends the tom from its rim or tension rods through rubber-isolated brackets rather than clamping hardware into the shell, isolating the shell from the stand so it can resonate more freely.", "plain_english": "A rim mount holds the tom by its metal hoop instead of drilling into the drum body. Freeing the shell lets the tom ring longer and more openly, like holding a wine glass by the stem.", "purpose_function": "Traditional shell-mounted brackets choke a tom's resonance; a rim or isolation mount lets the shell vibrate freely for more sustain and a fuller, more open tone.", "practical_application": "Techs fit isolation mounts so toms ring out fully; on a session this yields a more resonant, sustaining tom at the mic, and choked toms are often traced to a bracket bolted through the shell.", "category": "Drum Hardware", "related_terms": ["Tom sustain", "Shell resonance", "Isolation mount", "Tom ring", "Drum hardware"], "common_mistakes": ["Believing any tom holder isolates the shell; a bracket bolted through the shell still chokes resonance.", "Over-tightening the mount hardware so the rubber grommets can no longer isolate the shell.", "Expecting a rim mount to fix a dead-sounding tom that is really just tuned or damped wrong."], "scenario_contexts": ["Swapping stock shell mounts for isolation mounts to get more open, sustaining toms on a session.", "Suspending rack toms from their rims so the shells ring freely at the mic.", "Troubleshooting choked toms and finding a shell-mounted bracket is the cause."]}, "91e8185f-c664-4ea7-831a-4ddf06e464bb": {"definition": "The sustained resonant overtone a tom produces after the initial attack, made up of the drum's decaying modal frequencies and often heard as a pitched, humming tone, especially when the drum is tuned high or left undamped.", "plain_english": "Ring is the humming tone a tom makes after you hit it. It is the drum's own note singing on after the first thump.", "purpose_function": "Ring is the tom's natural resonance; a little gives toms life and pitch, but too much muddies a recording, so engineers manage it with tuning and damping.", "practical_application": "If toms ring too long or clash with the song's key, the engineer retunes the heads or adds light damping to control the ring while keeping the tone.", "category": "Drum Acoustics", "related_terms": ["Tom sustain", "Tom damping", "Overtones", "Drum tuning", "Resonant head"], "common_mistakes": ["Treating all ring as bad and damping it out, losing the tom's pitch and body.", "Trying to remove ring with EQ alone when tuning or light damping is the real fix.", "Ignoring that toms tuned to clash with the song's key make ring sound worse in the mix."], "scenario_contexts": ["Retuning toms whose ring clashes with the song's key during tracking.", "Deciding how much ring to keep for a big, open tom sound versus a tight modern one.", "Adding light damping to control ring on close-miked toms in a dense mix."]}, "30af459b-923d-446b-8568-d25f3663f76c": {"definition": "The length of time a tom-tom keeps sounding and decaying after it is struck, governed by head tuning, shell resonance, the mounting system, and any damping applied.", "plain_english": "Sustain is how long a tom keeps ringing before it fades out. A well-tuned, open tom rings for a long time.", "purpose_function": "Sustain gives toms their body and note length; controlling it through tuning, mounting, and damping sets how long each tom rings in the track.", "practical_application": "For big, open toms the engineer maximizes sustain with resonant tuning and isolation mounts; for tight modern tones the engineer shortens it with damping or gating.", "category": "Drum Acoustics", "related_terms": ["Tom ring", "Tom damping", "Tom rim mount", "Resonant head", "Drum tuning"], "common_mistakes": ["Killing all sustain with heavy damping, then wondering why the toms sound small and boxy.", "Expecting more sustain from tuning alone while ignoring a shell-choking mount.", "Gating away too much of the natural decay, leaving unnaturally short toms."], "scenario_contexts": ["Maximizing floor tom sustain for an ambient, roomy drum recording.", "Shortening tom sustain with damping for a tight, punchy pop production.", "Comparing sustain before and after fitting isolation mounts."]}, "278c9574-74cc-4708-a2e6-2d4f59e95806": {"definition": "A drum trigger mounted on a tom-tom that uses a transducer (typically a piezo sensor) to convert each hit into an electronic pulse, which fires a sampled or synthesized tom sound from a drum module to reinforce or replace the acoustic tom.", "plain_english": "A trigger is a small sensor stuck on the tom. Each hit sends a signal that plays a recorded drum sound. You can use it instead of, or on top of, the real drum.", "purpose_function": "Triggers turn each hit into a pulse a module can read, giving clean, consistent, bleed-free tom sounds live and allowing reinforcement or replacement of weak acoustic toms in the studio.", "practical_application": "The engineer clips a trigger on the tom and feeds a module so each hit fires a clean sample, or blends a sampled tom under a weak or poorly recorded acoustic track.", "category": "Drum Triggering", "related_terms": ["Tom gate", "Drum replacement", "Piezo sensor", "Drum module", "MIDI"], "common_mistakes": ["Mounting the trigger loosely or in the wrong spot, causing missed hits or double-triggers.", "Setting the module sensitivity wrong so soft hits are missed and hard hits max out.", "Assuming a trigger always replaces the acoustic tom; it can also just reinforce it."], "scenario_contexts": ["Adding triggered tom samples under weak acoustic toms during a mix.", "Using triggers live to get clean, bleed-free tom sounds through the PA.", "Replacing poorly recorded toms with triggered samples in post."]}, "4a8124b2-3281-4fcb-a20e-117ccdb8e3c4": {"definition": "The tuning relationship between a drum's batter (top) head and resonant (bottom) head, whose relative pitches set the drum's fundamental pitch, its pitch bend or glide as it decays, its sustain, and its overall tonal character.", "plain_english": "Every drum has a top head you hit and a bottom head under it. How their tunings compare sets the drum's pitch. It also sets how long the drum rings.", "purpose_function": "The interval between the two heads shapes fundamental pitch, sustain, and pitch bend; matching them gives an even sustain, while tuning the resonant head higher raises pitch and adds a downward bend.", "practical_application": "When tuning toms, the tech sets the top and bottom heads to a chosen relationship, equal for maximum even sustain or the resonant head higher for a pitch drop, to get the wanted tone.", "category": "Drum Tuning", "related_terms": ["Batter head", "Resonant head", "Drum tuning", "Tom sustain", "Snare-wire tension"], "common_mistakes": ["Tuning only the top head and ignoring the resonant head, so pitch and sustain never settle.", "Assuming the bottom head does nothing; it strongly affects pitch, sustain, and pitch bend.", "Cranking both heads to pull out wrinkles without listening to the interval between them."], "scenario_contexts": ["Tuning toms with the resonant head slightly higher for a downward pitch bend.", "Matching top and bottom heads for maximum, even sustain on open toms.", "Adjusting the resonant head to raise a tom's pitch without changing the batter feel."]}, "4728f8dd-138f-4322-b3df-52f5ec3c7da8": {"definition": "A bass drum resonant (front) head that has no hole or port cut into it, so the head stays a full, intact membrane. Because the shell is sealed, the drum sustains and resonates more, and a microphone cannot be placed inside it.", "plain_english": "It is the front skin of a kick drum with no hole cut in it. A solid front skin makes the drum ring longer and boom more, and you cannot put a mic inside.", "purpose_function": "Keeping the front head solid maximizes the drum's natural sustain, low-end resonance, and open tone, giving a fuller sound than a ported head. It is the standard tuned setup when the goal is the drum's full acoustic voice rather than a tight, mic-focused sound.", "practical_application": "An engineer facing an unported kick must mic it from outside the resonant head or add a boundary or subkick mic, since there is no port to place a mic inside, and often applies light internal muffling to tame the extra ring.", "category": "Kick Drum Tuning", "related_terms": ["Resonant head", "Batter head", "Ported kick head", "Kick drum microphone", "Drum muffling", "Subkick microphone"], "common_mistakes": ["Assuming a mic can be slid inside an unported kick; with no port, the mic must sit outside the resonant head or a subkick must be used.", "Over-muffling with pillows or blankets to kill the extra sustain, which chokes the low end instead of tuning the drum.", "Expecting the same tight, punchy attack as a ported kick; the sealed head naturally gives more ring, boom, and sustain.", "Cutting a port into the head to fix mic access when the session actually called for the fuller, sealed sound."], "scenario_contexts": ["Jazz or vintage-style sessions where an open, resonant, full-bodied kick tone is wanted.", "Recording a kit whose drummer prefers a solid front head, forcing the engineer to mic outside or add a subkick.", "Tuning a deep kick for a boomy, long-sustaining low end rather than a tight modern thud.", "A live or studio setup where a sealed front head is kept for maximum low-frequency resonance."]}, "15c52bb2-9e9f-4814-bea1-4efb9e898453": {"definition": "An active bass is an electric bass guitar with onboard active electronics, typically a battery-powered preamp and often an onboard equalizer, that buffer and amplify the pickup signal before it leaves the instrument; this yields a low output impedance, a hotter and more consistent output, and boost/cut tone control, in contrast to a purely passive bass whose signal comes straight from the pickups.", "plain_english": "A bass guitar with a small battery-powered preamp built inside. The battery boosts the signal and often adds tone controls. It gives a louder, cleaner output than a plain passive bass.", "purpose_function": "The onboard preamp exists to lower the output impedance and drive cables and inputs more strongly, reducing high-frequency loss and noise while adding boost/cut tone shaping the player controls from the instrument.", "practical_application": "An engineer recording an active bass keeps a fresh 9V battery in it, unplugs the instrument cable when idle because the jack switches the battery on, and may engage a pad on the DI or preamp since the hot output can overload an input.", "category": "Electric bass", "related_terms": ["Passive bass", "DI box", "Input impedance", "Preamp", "Pickup", "Pad"], "common_mistakes": ["Leaving the cable plugged in when not playing, which keeps the battery circuit switched on and drains it flat before or during a session.", "Confusing active electronics with phantom power; an active bass runs on its own internal battery, not the console's 48V phantom.", "Feeding a hot active output into a sensitive input without a pad, causing clipping and distortion that a passive bass would not produce."], "scenario_contexts": ["Tracking a modern slap-bass part where the player's active EQ is used to add high-end sparkle.", "Sound-checking a bass rig and discovering weak, distorted tone caused by a dying onboard battery.", "Choosing a DI with enough headroom and a pad to handle the strong output of an active bass on stage."]}, "5b1e3aee-c1cf-4979-92ee-c4d8e4fea50c": {"definition": "An amp track is a recorded track captured by placing a microphone in front of a guitar or bass amplifier's loudspeaker, so it carries the amplifier and cabinet's actual sound; it is distinguished from a DI track, which is the instrument's direct signal taken before amplification.", "plain_english": "A recorded track made by placing a microphone in front of a guitar or bass amp. It captures the amp's real speaker sound. That is different from the clean signal taken straight from the instrument.", "purpose_function": "The amp track captures the tone, drive and cabinet character that a speaker and microphone add, giving a mix the amplified sound of the instrument rather than a clean direct feed.", "practical_application": "An engineer records an amp track by miking the speaker, often blends it with a DI track for weight and clarity, and can re-amp a stored DI later to create a fresh amp track without the player present.", "category": "Recording technique", "related_terms": ["DI track", "Re-amping", "Cabinet miking", "Bass phase switch", "Comb filtering", "Blend"], "common_mistakes": ["Combining an amp track with a DI track without checking polarity, so the two cancel and the low end goes thin.", "Placing the mic without noting speaker position, then getting a dull or harsh tone that must be fixed later with EQ.", "Recording only the amp track and keeping no DI, leaving no option to re-amp or fix tone problems afterward."], "scenario_contexts": ["Miking a guitar cabinet to record an amp track alongside a clean DI for a rock rhythm part.", "Re-amping a saved bass DI through a real amp to build an amp track during mixing.", "Aligning an amp track and a DI track in the DAW so they sum without phase cancellation."]}, "16d5418e-b054-4824-b507-dd26079cc9a1": {"definition": "A bass amplifier ground lift is a switch, on the amp's balanced XLR DI output or on an outboard DI box, that disconnects the audio cable's shield/signal ground (pin 1) at that end to break a ground loop between the amp and the mixing console, reducing hum and buzz; it lifts only the audio signal ground and must never disconnect the amplifier's mains protective earth.", "plain_english": "A switch that stops a low humming noise when a bass amp is plugged into a mixer. It cuts one ground wire in the audio cable to break a hum loop. It must never be used to cut the amp's power-cord safety ground.", "purpose_function": "Ground loops form when two devices share both an audio-cable shield and separate mains grounds, letting current flow in a loop and induce hum; the ground lift breaks that loop at the audio interconnect while leaving the mains safety earth fully intact.", "practical_application": "When a bass DI feeding the console hums, a technician flips the DI or amp ground-lift switch to break the loop, and if hum remains addresses grounding at the source rather than ever removing the amplifier's earth pin.", "category": "Grounding and safety", "related_terms": ["Ground loop", "DI box", "Shield", "Balanced connection", "Hum", "Protective earth"], "common_mistakes": ["UNSAFE: Defeating the amplifier's mains earth with a 3-to-2 cheater adapter or by clipping the ground pin to kill hum; this removes the protective earth and can leave the chassis and metal strings live at a lethal voltage.", "Treating ground lift as a tone or level control; it only changes the shield connection to fight hum and does nothing to the sound quality of a clean signal.", "Lifting the ground on every device at once, which can leave shields floating and increase noise and RF pickup instead of curing the hum.", "Reaching for the ground lift first when the real cause is a faulty cable or a shared circuit with lighting dimmers."], "scenario_contexts": ["A bass DI feeding front-of-house hums, and the tech engages the DI's ground lift to break the loop.", "Recording a bass amp's XLR DI into an interface on the same mains outlet, where ground lift removes loop hum.", "Troubleshooting stage buzz caused by a musician's cheater plug, and fixing it by restoring the safety ground and using a proper DI ground lift."]}, "7b923b89-e6d2-4817-a65f-76119bbe8f6f": {"definition": "Bass body resonance is the set of natural mechanical resonant frequencies of a bass guitar's body and neck structure; when a fretted note's fundamental coincides with a strong structural resonance, energy transfers from the string into the vibrating wood, which can reinforce tone but also creates 'dead spots' where that note's sustain is noticeably shortened.", "plain_english": "Every bass guitar body and neck naturally vibrates at certain pitches. When a played note matches that pitch, the wood soaks up the string's energy. That note then fades faster than the others. These weak spots are called dead spots.", "purpose_function": "Understanding body resonance explains why some notes ring longer or shorter than their neighbours, which matters for judging an instrument's sustain and evenness and for predicting how a recorded bass line will decay.", "practical_application": "A technician hearing a note that dies quickly recognises a dead spot from body/neck resonance and works around it by changing the fretting position, adding mass to the headstock, or using compression and note choice rather than blaming the amp.", "category": "Instrument acoustics", "related_terms": ["Dead spot", "Sustain", "Bass compression", "Resonant frequency", "Fundamental", "Neck relief"], "common_mistakes": ["Blaming a fast-decaying note on the strings or amplifier when it is actually a structural dead spot from body and neck resonance.", "Assuming a solid-body electric bass has no meaningful body resonance; the neck and body still resonate enough to create dead spots.", "Trying to fix an uneven-sustaining note entirely with EQ, which cannot restore energy the resonating structure has already absorbed."], "scenario_contexts": ["Tracking a sustained bass note that dies early and identifying it as a dead spot around the fourth to sixth fret of the G string.", "Comparing two basses in the studio and choosing the one whose body resonance gives more even note-to-note sustain.", "Applying compression to smooth out the uneven decay caused by body resonance in a recorded bass part."]}, "9534a2fe-374e-4796-ac71-c06e7a37ff6d": {"definition": "A bass cabinet horn is a high-frequency compression driver mounted behind a horn (or a tweeter) inside a bass speaker cabinet, fed through a crossover to reproduce the frequencies above the woofer's range; it is commonly fitted with an L-pad attenuator so the player can adjust or defeat its level.", "plain_english": "A small tweeter speaker built into some bass amp cabinets. It plays the high, bright sounds that the big woofer cannot. Many cabinets have a knob to turn the horn up or down.", "purpose_function": "The horn extends the cabinet's high-frequency response so bright playing styles such as slap, pick attack and effects come through clearly, since the large bass woofer alone cannot reproduce those top frequencies.", "practical_application": "A technician sets the horn's L-pad to taste, dialling it up for slap brightness or down to reduce hiss and harshness, and keeps clipped or heavily distorted signals in check because sustained high-frequency energy can damage the compression driver.", "category": "Bass amplification", "related_terms": ["Compression driver", "Crossover", "L-pad", "Woofer", "Tweeter", "Bass cabinet"], "common_mistakes": ["Leaving the horn wide open and then blaming the amp for a harsh, clanky top end that the L-pad could tame.", "UNSAFE for the driver: running a clipped or heavily distorted signal at high level, whose excess high-frequency energy can overheat and destroy the compression driver.", "Assuming the horn is broken when it is simply turned all the way down at its L-pad attenuator."], "scenario_contexts": ["Setting up a bass rig for slap playing and raising the cabinet horn to bring out string brightness.", "Turning the horn's L-pad down to reduce hiss during a quiet fingerstyle passage.", "Diagnosing a cabinet with no high end and finding the horn's attenuator backed fully off."]}, "d2811c74-a7ce-4c83-90f4-1cf5d41c37ed": {"definition": "Bass compression is the use of a compressor to reduce the dynamic range of a bass part by automatically turning down signal that exceeds a threshold, evening out level differences between notes and strings; controls for threshold, ratio, attack and release set how much and how quickly the gain is reduced.", "plain_english": "A tool that turns down the loudest notes so the bass sounds even. It stops some notes from jumping out too loud. This helps the bass stay steady and sit well in a song.", "purpose_function": "Compression exists to control the bass's wide dynamics so quiet and loud notes sit at a more consistent level, adding perceived sustain and helping the low end hold a steady place in the mix.", "practical_application": "An engineer patches a compressor or pedal on the bass DI or channel and sets a moderate ratio with an attack slow enough to preserve the pluck, adjusting release to the tempo so the level stays even without obvious pumping.", "category": "Dynamics processing", "related_terms": ["Compressor", "Threshold", "Ratio", "Attack", "Release", "Limiting"], "common_mistakes": ["Setting the attack too fast, which clamps the initial pluck and robs the bass of its note definition and punch.", "Over-compressing so heavily that the part pumps and loses all natural dynamics.", "Printing heavy compression while recording, which cannot be undone if it turns out to be too much."], "scenario_contexts": ["Evening out an uneven fingerstyle bass take so every note sits at a similar level.", "Adding gentle compression to a slap part to tame the loud pops without killing the attack.", "Using a bass compressor pedal live to keep stage and front-of-house level consistent."]}, "9ad4f56c-111c-4db4-8cd9-c728a5103ab8": {"definition": "A bass phase switch is a polarity-invert control on a bass amp, DI box or preamp that flips the signal's polarity by 180 degrees; it is used to realign two captures of the same bass, such as a DI and a miked cabinet, or the bass against another source, so their combined low end reinforces instead of cancelling. Strictly it inverts polarity rather than shifting phase across frequency.", "plain_english": "A button that flips the bass signal upside down. Engineers use it when a bass is recorded two ways at once, like a mic plus a direct feed. Flipping one keeps them from canceling out and sounding thin.", "purpose_function": "The switch exists to correct polarity mismatches between combined signals, preventing the destructive cancellation that thins or hollows the low end when two versions of the bass are summed.", "practical_application": "A technician engages the switch while listening or watching a meter, choosing the setting that gives the fuller low end when a bass DI and mic, or the bass and kick, are blended together.", "category": "Phase and polarity", "related_terms": ["Polarity", "Phase", "Comb filtering", "DI box", "Amp track", "Mono compatibility"], "common_mistakes": ["Confusing polarity inversion with true phase or time alignment; the switch flips polarity and cannot fix a delay between two mics.", "Flipping the switch by rule instead of by ear, and locking in the setting that actually thins the sound.", "Assuming it changes tone on its own; with a single source it makes no audible difference until that source is combined with another."], "scenario_contexts": ["Blending a bass DI with a miked cabinet and using the switch to find the setting with the strongest low end.", "Aligning bass and kick drum polarity so their low frequencies add rather than cancel.", "Checking a bass mix folds to mono cleanly by testing the phase switch position."]}, "c04bc865-33ca-4beb-94b8-c1f02fdba031": {"definition": "In free-reed instruments such as the accordion, harmonium/reed organ and bass harmonica, the bass reeds are the larger, lower-tuned free reeds — thin metal tongues riveted over slots in a reed plate — that sound the instrument's low notes; being longer and more massive than the treble reeds, they vibrate more slowly to produce lower pitches.", "plain_english": "The larger metal tongues inside an accordion or reed organ that make the low notes. Air rushing past each reed makes it vibrate and sound a pitch. The longer, heavier reeds give the deep bass tones.", "purpose_function": "The bass reeds provide the low-frequency foundation of a free-reed instrument, so their size and tuning set how deep and strong the instrument's bass register sounds.", "practical_application": "When recording an accordion or harmonium, an engineer mics near the bass side or bass grille to capture the bass reeds, aware that each reed sounds on only one air direction and that these low reeds carry strong low-frequency energy.", "category": "Free-reed instruments", "related_terms": ["Free reed", "Reed plate", "Accordion", "Harmonium", "Bass harmonica", "Reed organ"], "common_mistakes": ["Confusing free bass reeds, which vibrate through their slot, with an organ reed pipe's beating reed that strikes a shallot.", "Expecting one reed to sound on both air directions, when a separate reed handles press versus pull or blow versus draw.", "Miking the bass side too closely and capturing valve slap and air noise instead of a clean low reed tone."], "scenario_contexts": ["Close-miking the bass side of an accordion to capture the low reeds for a folk recording.", "Servicing a harmonium and gapping or tuning a sluggish bass reed on its reed plate.", "Recording a bass harmonica and managing the strong low-frequency output of its bass reeds."]}, "aefbe9f1-69da-400c-81f2-89b45b1eb40f": {"definition": "The bass rotor is the rotating low-frequency element in a rotary (Leslie-type) loudspeaker cabinet: a motor-driven drum or scoop baffle mounted below a fixed bass woofer that spins to project the low frequencies around the room, producing the Doppler pitch modulation and amplitude tremolo characteristic of the effect, paired with a separate rotating treble horn for the highs.", "plain_english": "The spinning drum inside a rotary speaker cabinet, like a Leslie. It throws the low sounds around the room as it turns. This swirling motion gives organ and guitar tones their classic wobble.", "purpose_function": "By physically rotating the low-frequency output, the bass rotor creates continuous Doppler and level modulation that gives the rotary-speaker effect its warm, swirling movement in the bass register.", "practical_application": "An engineer recording a rotary cabinet places one or more mics on the lower bass-rotor drum and separate mics on the treble horn, and notes that the rotor's slow (chorale) and fast (tremolo) speeds change the movement captured.", "category": "Rotary speaker", "related_terms": ["Leslie speaker", "Treble rotor", "Doppler effect", "Tremolo", "Woofer", "Cabinet miking"], "common_mistakes": ["Confusing the bass rotor drum with the treble horn; the rotor handles lows while the upper horn handles highs, and they are miked separately.", "Assuming the woofer itself spins, when the driver is fixed and only the drum or scoop baffle below it rotates.", "Miking only one side of the cabinet and losing the full stereo swirl the moving rotor produces."], "scenario_contexts": ["Miking a Leslie cabinet's lower bass rotor and upper horn separately to capture the full rotary effect.", "Recording a Hammond organ through a rotary speaker and switching between chorale and tremolo rotor speeds.", "Sending a guitar through a rotary cabinet and capturing the bass rotor's swirl for a psychedelic tone."]}, "9f4374b9-bfea-4b15-a779-9adcd5289368": {"definition": "A recording of an electric guitar or bass captured straight from the instrument through a direct box (DI), taken before any amplifier or speaker, so the track holds the raw, unamplified instrument signal.", "plain_english": "It is the clean guitar sound recorded straight from the guitar, with no amp added. You can send it through an amp later to shape the tone.", "purpose_function": "It captures a clean, uncolored version of the performance so tone decisions such as amp and effects can be made or changed later, and it provides a pristine signal for re-amping.", "practical_application": "Engineers split the guitar signal and record the DI to its own track alongside the miked amp, so they can re-amp or blend it during mixing.", "category": "Recording technique", "related_terms": ["Re-amping", "Re-amp box", "Passive bass", "Off-axis pickup", "Speaker cabinet isolation"], "common_mistakes": ["Recording only the DI and no amp, then having no usable tone if you cannot re-amp later", "Plugging a high-impedance guitar into a low-impedance line input, which weakens and dulls the signal", "Assuming the raw DI sound is a finished guitar tone rather than a starting point"], "scenario_contexts": ["Tracking a guitar part with both a miked amp and a DI so the producer can revisit the tone in the mix", "Recording a bass DI for a clean, tight low end that sits well with the drums", "Capturing a scratch guitar quietly at home for later re-amping in a studio"]}, "fb0da409-3625-40dd-8493-527118996603": {"definition": "A bass guitar whose fingerboard has no metal frets, so the player's finger stops the string directly against the smooth board; this allows continuous pitch, slides, and vibrato but requires precise finger placement for accurate intonation.", "plain_english": "It is a bass with a smooth neck and no metal frets. The player must place each finger in exactly the right spot to play in tune. Notes can slide smoothly, a bit like a singing voice.", "purpose_function": "It gives a smooth, singing tone with expressive slides and vibrato (the characteristic 'mwah' sound) that a fretted bass cannot produce, at the cost of harder intonation.", "practical_application": "An engineer records a fretless bass much like any bass but watches tuning closely, often using a clean DI and gentle compression to capture the finger-slide and 'mwah' character.", "category": "Instrument", "related_terms": ["Passive bass", "Direct guitar track", "Re-amping"], "common_mistakes": ["Expecting perfect intonation without careful finger placement, since there are no frets to fix the pitch", "Confusing a fretless bass with a lined fretless; the lines only mark positions and are not frets", "Choosing bright, clanky processing that hides the smooth, vocal tone the instrument is known for"], "scenario_contexts": ["Recording a jazz or fusion bassline that needs smooth slides between notes", "Tracking a ballad where the singing, expressive fretless tone supports the vocal", "Editing a fretless take where slight tuning drift must be checked before comping"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"c4b35316-fff6-4ea5-b723-e4eec23fe0ab": {"definition": "A small, reusable, self-adhesive gel pad applied to a vibrating surface, most often a drumhead, to absorb vibration and tame unwanted overtones, ring, and sustain. The best-known example is the Moongel-type damping pad.", "plain_english": "A soft, sticky gel square you press onto a drum to calm down extra ringing. It works like putting a finger on a wine glass to stop it humming.", "purpose_function": "It gives a quick, removable way to control overtones and shorten sustain without permanently altering the head, so a drum or surface sounds more focused on the recording.", "practical_application": "An engineer sticks one or more gel dampers near the edge of a snare or tom head, moving or adding pads until the ring is controlled without deadening the tone.", "category": "Damping & tone control", "related_terms": ["Kick click control", "Kick beater definition", "Palm muting", "Body knock"], "common_mistakes": ["Using too many gel dampers and deadening the drum completely", "Placing the gel in the center of the head instead of near the edge, killing tone and volume", "Assuming a gel damper replaces proper drum tuning"], "scenario_contexts": ["Taming snare ring during a tracking session", "Controlling tom overtones for a tighter recorded sound", "Quickly adjusting damping between takes without changing heads"]}, "42b1138e-dc8e-4e7b-bf97-d9b783748898": {"definition": "Sound captured by a microphone from directions away from its central front axis (the on-axis line it points along); because most microphones are less sensitive and less bright off-axis, off-axis pickup sounds darker and quieter than on-axis pickup.", "plain_english": "It is the sound a mic picks up from the side or at an angle instead of straight ahead. That angled sound is usually quieter and less bright than sound hitting the mic head-on.", "purpose_function": "Understanding off-axis pickup lets an engineer shape tone and control bleed by aiming a mic toward or away from a source, since the off-axis level and frequency response differ from on-axis.", "practical_application": "On a guitar cab, an engineer angles the mic off-axis to the speaker cone to tame harsh highs, and points mics away from other instruments to reduce their off-axis bleed.", "category": "Microphone technique", "related_terms": ["Speaker cabinet isolation", "Direct guitar track", "Re-amping"], "common_mistakes": ["Assuming a mic hears all directions equally, when off-axis sound is quieter and often duller", "Ignoring that off-axis pickup colors tone unevenly, so different frequencies drop by different amounts", "Blaming the amp for a dull recording when the mic was simply aimed too far off-axis"], "scenario_contexts": ["Angling a dynamic mic off the center of a guitar speaker to soften harsh highs", "Positioning a vocal mic so a nearby amp lands off-axis and bleeds in less", "Choosing the mic angle on a cab to balance brightness against a boomy on-axis tone"]}, "20bcefaa-5ecb-4e7d-809a-12868d405d4c": {"definition": "A bass guitar that uses passive pickups and passive tone and volume controls with no onboard powered preamp or battery; its high-impedance output relies entirely on the magnetic pickups and simple passive circuitry.", "plain_english": "It is a bass with no battery and no powered circuit inside it. The pickups make the sound on their own. The signal is weaker, so it needs a good input to sound full.", "purpose_function": "It delivers a natural, traditional bass tone and simple, reliable operation, but its weak high-impedance signal needs a proper high-impedance input to avoid tone loss.", "practical_application": "When recording a passive bass, the engineer uses an instrument-level, high-impedance DI input so the pickups are not loaded down, keeping the low end and clarity intact.", "category": "Instrument", "related_terms": ["Fretless bass", "Direct guitar track", "Re-amp box"], "common_mistakes": ["Plugging a passive bass into a low-impedance line input, which loads the pickups and dulls the tone", "Expecting the loud, hot output of an active bass and setting the preamp gain too low", "Thinking passive means lower quality, when many classic bass tones come from passive instruments"], "scenario_contexts": ["Recording a vintage-style passive bass through a high-impedance DI for a classic tone", "Setting preamp gain higher to match the lower output of a passive bass", "Troubleshooting a thin, dull bass DI caused by an input impedance that is too low"]}, "d892d2d9-79a0-4a26-8729-9e0e2fe3d7af": {"definition": "A device that converts a recorded line-level, low-impedance signal (from an interface or console output) back into an instrument-level, high-impedance signal, so a dry DI recording can be sent out to guitar pedals and amplifiers; it is essentially a reverse DI box, typically using a transformer, a level control, and a ground-lift switch.", "plain_english": "It is a small box that turns a recorded guitar track back into a normal guitar-level signal. That lets you feed the recording into a real amp or pedals. It works as if the guitar were plugged in live.", "purpose_function": "It matches the studio's line-level output to the instrument-level input an amp expects, avoiding the harsh, weak, or noisy result of plugging a line output straight into an amp.", "practical_application": "The engineer patches the interface output through the re-amp box, then into a pedalboard and amp, adjusting the box's level so the amp sees a normal guitar signal.", "category": "Studio hardware", "related_terms": ["Re-amping", "Direct guitar track", "Speaker cabinet isolation", "Off-axis pickup"], "common_mistakes": ["Plugging a line output straight into an amp instead of using a re-amp box, which causes an impedance mismatch and poor tone", "Confusing a re-amp box with a DI box, since they convert signals in opposite directions", "Ignoring hum from a ground loop between the interface and amp instead of using the box's ground-lift switch"], "scenario_contexts": ["Sending a recorded DI guitar out to several amps to audition tones after tracking", "Using the box's ground-lift to kill hum when connecting the studio to a guitar amp", "Reshaping a bass DI through a real amp and cabinet during mixdown"]}, "b894ff78-613d-4cb3-b4e3-5b6ce17c16bc": {"definition": "The process of playing a previously recorded dry signal (usually a DI guitar or bass) back out through a re-amp box into an amplifier, pedals, or effects, then miking and recording the result to a new track; it lets amp and tone choices be made or redone after the performance is captured.", "plain_english": "It means running a clean guitar recording through a real amp later, then recording that amp sound. You can change or perfect the tone after the player has gone home.", "purpose_function": "It separates the performance from the tone, so engineers can try different amps, mics, and settings without asking the musician to replay the part.", "practical_application": "After tracking a DI, the engineer re-amps it through chosen amps and mic positions during mixing, dialing in the exact tone the song needs.", "category": "Recording technique", "related_terms": ["Re-amp box", "Direct guitar track", "Off-axis pickup", "Speaker cabinet isolation"], "common_mistakes": ["Trying to re-amp from a line output without a re-amp box, causing an impedance mismatch and a weak, harsh tone", "Not recording a clean DI in the first place, leaving nothing to re-amp later", "UNSAFE: Running a loud amp at high volume during long re-amping sessions without hearing protection; sustained high sound levels risk permanent hearing damage."], "scenario_contexts": ["Re-amping a scratch DI guitar through a boutique amp to upgrade the final tone", "A producer re-amping bass through multiple cabs to blend a clean and a distorted tone", "Fixing a good performance recorded with a bad amp sound by re-amping it later"]}, "0714eca9-1532-4e4f-b260-d4ea26649c7b": {"definition": "Techniques and enclosures used to acoustically isolate a guitar or bass speaker cabinet so it can be miked at high volume without excessive bleed into the room or other microphones; methods range from isolation cabinets (iso boxes) to separate rooms, baffles, and acoustic enclosures.", "plain_english": "It is any way to box off or separate a speaker cabinet. That keeps its loud sound from leaking into other mics or the room. You can crank the amp and still get a clean recording.", "purpose_function": "It lets an engineer capture a driven amp tone at realistic volume while controlling bleed, room sound, and noise for the players and neighbors.", "practical_application": "The engineer places the cab in an iso box or separate room, mics it inside, and monitors from the control room, keeping stage volume low during tracking.", "category": "Acoustic isolation", "related_terms": ["Off-axis pickup", "Re-amping", "Re-amp box", "Direct guitar track"], "common_mistakes": ["Cramming a cab into a small sealed box without treatment, creating boxy resonances that ruin the tone", "Forgetting that isolation reduces the natural room sound many amp tones rely on", "UNSAFE: Sealing an amp inside an unventilated enclosure for long periods, which lets it overheat and risks equipment damage or fire; keep manufacturer-specified ventilation clear."], "scenario_contexts": ["Using an isolation cabinet so a loud amp can be miked in a home studio at night", "Placing the guitar cab in a separate room to stop it bleeding into the drum mics", "Recording a full-volume tube amp tone in a small studio without disturbing neighbors"]}, "8db809f6-01e3-4299-a89b-de06cb91f063": {"definition": "A supplementary recorded or programmed part added to emphasize specific moments in an arrangement, such as a downbeat, a section change, or a lyrical hook, rather than to play throughout the song. It reinforces impact at chosen points while leaving the core arrangement otherwise unchanged.", "plain_english": "An accent layer is an extra sound added just at key moments to make them stand out, like a cymbal crash or a quick synth stab when the chorus hits. It is not meant to play the whole time.", "purpose_function": "It exists to pull the listener's ear to important spots and add energy or surprise without cluttering the rest of the track.", "practical_application": "A producer drops in an accent layer, such as a tambourine hit or reversed cymbal, on the transition into a chorus, then mutes it during quieter sections.", "category": "Arrangement", "related_terms": ["Ambience layer", "Background texture", "Attack reinforcement", "Acoustic-trigger blend", "Background-vocal alignment"], "common_mistakes": ["Leaving the accent layer playing through the whole song so it stops feeling special", "Mixing it so loud it competes with the lead part instead of supporting it", "Stacking so many accent layers that the arrangement becomes cluttered"], "scenario_contexts": ["Adding a cymbal swell and synth stab on the first downbeat of the final chorus", "Dropping a tambourine hit on section changes in a pop track", "Placing an orchestral hit under a key lyric to underline it"]}, "90aa9663-9733-4bdf-84dd-7e784449848d": {"definition": "The process of balancing, equalizing, and placing a recorded acoustic guitar within a mix so its body, string detail, and dynamics sit clearly against the other instruments. It typically involves controlling low-mid boom, taming pick or finger noise, and setting the guitar's stereo position and level for its role as either a rhythm bed or a featured part.", "plain_english": "Acoustic-guitar mixing means shaping a recorded acoustic guitar so it sounds clear and full without booming or getting lost. You usually cut some low mud, control harsh string noise, and set how loud and how wide it sits.", "purpose_function": "It exists to make the acoustic guitar's natural tone fit the arrangement, supporting the song whether the guitar is the main instrument or a background layer.", "practical_application": "An engineer high-passes the guitar to remove rumble, dips the lower mids to reduce boxiness, and pans a doubled rhythm part left and right to widen the bed.", "category": "Mixing", "related_terms": ["Acoustic-instrument mix", "Acoustic-trigger blend", "Ambience layer", "Background texture", "Attack reinforcement"], "common_mistakes": ["Boosting the highs so much that pick and fret noise becomes distracting", "Leaving low-frequency boom in that clashes with the bass and kick drum", "Panning a single acoustic to the center where it fights the lead vocal instead of moving it aside"], "scenario_contexts": ["Fitting a strummed acoustic under a lead vocal in a pop ballad", "Blending doubled acoustic guitars into a wide rhythm bed", "Featuring a fingerpicked acoustic as the main instrument in a singer-songwriter track"]}, "a15cc83b-6669-4fcb-bfce-d80118bfae02": {"definition": "An approach to mixing that preserves the natural tone, dynamics, and room character of acoustically produced instruments such as guitar, piano, strings, or upright bass, rather than heavily processing them. It emphasizes accurate level balance, gentle equalization, and controlled dynamics so the instruments sound realistic and cohesive.", "plain_english": "An acoustic-instrument mix keeps real instruments sounding natural. It avoids making them sound heavily electronic or processed. You aim for a good balance and only light changes, so a guitar or piano still sounds like itself.", "purpose_function": "It exists to deliver a believable, organic sound for styles like folk, jazz, or acoustic pop, where realism and natural dynamics matter more than heavy effects.", "practical_application": "A technician uses light compression and minimal EQ, keeps some natural room ambience, and balances the instruments mostly with faders to protect their real dynamics.", "category": "Mixing", "related_terms": ["Acoustic-guitar mixing", "Ambience layer", "Background texture", "Acoustic-trigger blend", "Alto section balance"], "common_mistakes": ["Over-compressing until the instruments lose the natural dynamics that make them sound live", "Adding heavy effects that make acoustic sources sound artificial", "Removing all room ambience so the mix sounds sterile and lifeless"], "scenario_contexts": ["Mixing a folk trio of acoustic guitar, upright bass, and fiddle", "Balancing a jazz combo where natural dynamics carry the feel", "Preparing a live acoustic session for release with minimal processing"]}, "cd518a99-e008-42ea-9558-c1cd4737b6d8": {"definition": "The technique of mixing a drum's natural acoustic microphone signal with a triggered sample of the same drum, combining the two to reach a desired balance of realism and consistency. The blend ratio is adjusted so the sample reinforces weight or attack while the live mic keeps the instrument's natural character.", "plain_english": "An acoustic-trigger blend mixes the real recorded drum sound with a matching sample fired from that same hit. You dial in how much of each so the drum keeps its natural feel but gains extra punch or an even level from the sample.", "purpose_function": "It exists to fix weak, inconsistent, or poorly captured drum sounds, often the kick or snare, without losing the human feel of the original performance.", "practical_application": "An engineer uses a trigger plugin to fire a sample in time with the recorded snare, then balances the sample and live-mic faders until the snare has body and an even level across the song.", "category": "Drum production", "related_terms": ["Attack reinforcement", "Accent layer", "Acoustic-instrument mix", "Ambience layer", "Acoustic-guitar mixing"], "common_mistakes": ["Setting the trigger threshold so it misfires or misses ghost notes", "Using so much sample that the drums sound fake and lose the room feel", "Ignoring polarity so the sample and the live mic partly cancel each other out"], "scenario_contexts": ["Reinforcing a dull kick drum recorded in a poor-sounding room", "Evening out an inconsistent snare level across a long take", "Adding weight to live drums that were captured with only a few microphones"]}, "7ed05112-822b-4275-b04b-6584417b4310": {"definition": "The setting of the relative levels and blend of the alto voices, or alto-range parts, within an ensemble so they support the harmony without overpowering or disappearing beneath the adjacent sections. It concerns the internal balance of the middle harmony line against the soprano, tenor, and bass parts.", "plain_english": "Alto section balance means setting the right level for the alto singers, who sing the middle voices. They should fill out the harmony. But they must not cover the melody or get lost under the other parts.", "purpose_function": "It exists to keep the middle harmony audible and even, giving a choir or vocal group a full, well-blended sound.", "practical_application": "When mixing a choir or stacked backing vocals, the engineer rides the alto level so the inner harmony is present but the soprano melody still leads.", "category": "Vocal production", "related_terms": ["Background-vocal alignment", "Background texture", "Ambience layer", "Accent layer", "Acoustic-instrument mix"], "common_mistakes": ["Mixing the altos too low so the harmony sounds thin and hollow", "Pushing the altos so loud they mask the soprano melody", "Judging the balance in solo instead of in the full mix, where masking really happens"], "scenario_contexts": ["Balancing a four-part choir recording", "Setting levels for stacked backing-vocal harmonies in a pop chorus", "Blending a horn section's alto-range parts against the lead lines"]}, "b92652f7-d8b7-4b07-8abd-5e4ce62b7420": {"definition": "A track or group of tracks, such as room microphones, reverb returns, or recorded environmental sound, added beneath an arrangement to create a sense of space, depth, and natural or atmospheric context. It sits low in the mix and provides continuity rather than a distinct musical part.", "plain_english": "An ambience layer is background sound, like room mics, reverb, or soft atmosphere, added under a song to give it a sense of space. It usually sits quietly and makes the mix feel more real or wider.", "purpose_function": "It exists to add depth and glue to a mix, making separately recorded parts feel like they share one space.", "practical_application": "An engineer blends in room-mic tracks or a long reverb return under the drums and vocals to widen the sound and connect the elements.", "category": "Arrangement", "related_terms": ["Background texture", "Accent layer", "Acoustic-instrument mix", "Attack reinforcement", "Acoustic-trigger blend"], "common_mistakes": ["Turning the ambience up so loud it washes out clarity and detail", "Adding so much reverb that the mix sounds distant and muddy", "Forgetting to filter low rumble out of room tracks before blending them in"], "scenario_contexts": ["Adding room mics under close-miked drums for depth", "Layering soft atmosphere or crowd noise under a live-style mix", "Using a reverb return as a shared space for the vocals and guitars"]}, "75d8cda0-7426-4b36-8931-c117b276a155": {"definition": "The strengthening of the initial transient, the attack, of a sound so it cuts through a mix more clearly, using transient shaping, layering, or careful compression. It emphasizes the very start of a note or hit to improve definition and rhythmic clarity.", "plain_english": "Attack reinforcement means boosting the very start of a sound, the initial hit, so it stands out better in the mix. You might layer a sharper sound on top or use a tool that lifts the punchy front of each note.", "purpose_function": "It exists to restore or add clarity and punch to sounds whose attack is weak, helping them stay defined and rhythmically tight against the other parts.", "practical_application": "An engineer uses a transient shaper to raise the attack of a soft kick, or layers a short click sample under it so each hit reads clearly.", "category": "Mixing", "related_terms": ["Acoustic-trigger blend", "Accent layer", "Ambience layer", "Acoustic-guitar mixing", "Background texture"], "common_mistakes": ["Overdoing the transient boost until hits sound clicky and unnatural", "Reinforcing the attack so hard it triggers harsh distortion on the peaks", "Forgetting that too much attack can make a part feel harsh and tiring to hear"], "scenario_contexts": ["Making a soft kick drum punch through a dense rock mix", "Adding definition to a slap bass that lacks bite", "Sharpening the pick attack on a rhythm guitar buried in the mix"]}, "1bb9a868-9d20-4df5-9cd6-5e7b9af0e317": {"definition": "A subtle, sustained layer, such as a pad, drone, soft synth, or atmospheric sound, placed low in an arrangement to add richness and fill space without drawing attention as a distinct part. It supports the main elements by providing harmonic or tonal context in the background.", "plain_english": "A background texture is a quiet, steady sound, like a soft pad or drone, added under a song to fill it out and make it feel fuller. You are not really meant to notice it on its own.", "purpose_function": "It exists to add fullness, mood, and glue to an arrangement, filling the gaps between the featured parts.", "practical_application": "A producer layers a low synth pad or filtered noise under the verse to keep it from sounding empty, mixed quietly beneath the vocals and drums.", "category": "Arrangement", "related_terms": ["Ambience layer", "Accent layer", "Acoustic-instrument mix", "Background-vocal alignment", "Attack reinforcement"], "common_mistakes": ["Making the texture too loud so it competes with the main parts", "Choosing a busy texture that clutters the arrangement instead of supporting it", "Letting the texture clash harmonically with the chords underneath"], "scenario_contexts": ["Adding a soft pad under a sparse verse to fill space", "Layering atmospheric noise beneath a breakdown for mood", "Using a sustained drone to connect two song sections"]}, "5e78416c-1597-4f42-8fcb-c5e4d627451c": {"definition": "The adjusting of the timing, and often the pitch, of backing-vocal tracks so they lock tightly to each other and to the lead vocal. It ensures that stacked harmonies and doubles start, phrase, and end together for a cohesive blend.", "plain_english": "Background-vocal alignment means tightening the timing of the backing vocals so they land together and match the lead singer. When the words and notes start and stop at the same time, the harmonies sound like one smooth blend.", "purpose_function": "It exists to make layered harmonies and doubles sound unified rather than sloppy or smeared, which is essential for a polished vocal production.", "practical_application": "An engineer nudges backing-vocal takes in the DAW, or uses time-alignment tools, so the consonants and note endings match the lead, then checks tuning across the stack.", "category": "Vocal production", "related_terms": ["Alto section balance", "Background texture", "Accent layer", "Ambience layer", "Acoustic-instrument mix"], "common_mistakes": ["Aligning the timing so rigidly the vocals sound robotic and lifeless", "Fixing the timing but ignoring tuning differences that still smear the blend", "Aligning to the wrong reference so the stack drifts off the lead vocal"], "scenario_contexts": ["Tightening stacked harmony takes in a pop chorus", "Lining up double-tracked backing vocals so they sound as one", "Matching a group's backing phrases to the lead vocal's timing"]}, "c6f57177-bb46-4a9f-bc26-2f4293869c43": {"definition": "The use of a DAW's automation to vary the level, mute state, or effect parameters of background-vocal tracks across a song, so their balance follows the arrangement moment to moment rather than sitting at one fixed setting.", "plain_english": "This means telling your software to move the backing-vocal volume or effects on its own as the song plays. It works like a helper riding the faders for you, so the harmonies rise in the chorus and drop back in quiet parts.", "purpose_function": "It keeps background vocals sitting correctly against the lead and the band at every point in the song, instead of settling for one static fader level that only works in some sections.", "practical_application": "An engineer draws or records automation to push the harmonies up in a chorus, pull them down under a busy verse, or open a delay throw on the last word of a line.", "category": "Background Vocal Mixing", "related_terms": ["Background-vocal bus", "Background-vocal production", "Background-vocal reverb", "Background-vocal delay", "Lead vocal"], "common_mistakes": ["Setting one average level for the whole song and never automating, so the harmonies vanish in loud sections and stick out in quiet ones.", "Automating only the group bus fader when the real problem was the balance between individual tracks, baking in a bad blend.", "Writing jumpy, stepped level changes that sound unnatural instead of smooth fader rides."], "scenario_contexts": ["Riding a harmony stack up a couple of dB only during a pop chorus.", "Ducking backing vocals under a lead ad-lib in the final chorus.", "Automating a reverb or delay send so it blooms on a held note at the end of a phrase."]}, "d69969da-9723-4c0f-8d52-cc8b6e13f509": {"definition": "An aux or group bus that sums all background-vocal channels to a single signal path, allowing shared processing, level control, and routing of the combined backing vocals as one unit.", "plain_english": "This is one channel that all your backing-vocal tracks flow into. It lets you shape and set the level of the whole group of harmonies with a single fader, instead of touching each track one by one.", "purpose_function": "It exists so an engineer can treat many backing-vocal tracks as one blended part, applying shared EQ, compression, or effects and moving them together in the mix.", "practical_application": "The engineer routes every harmony and double to a stereo group bus, then adds glue compression and a high-pass filter there so the whole stack sits as one unit behind the lead.", "category": "Background Vocal Mixing", "related_terms": ["Background-vocal compression", "Background-vocal automation", "Background-vocal equalization", "Background-vocal reverb", "Background-vocal production"], "common_mistakes": ["Processing each vocal separately and never bussing them, making the stack hard to balance and glue.", "Routing lead and backing vocals to the same bus, so bus compression on the harmonies also pumps the lead.", "Leaving the bus mono, which collapses wide-panned harmonies to the center."], "scenario_contexts": ["Summing eight harmony tracks to one group so a single compressor works the whole stack.", "Sending the backing-vocal bus to a shared reverb for one unified space.", "Riding one fader to drop all harmonies under a spoken bridge."]}, "8128910a-7a67-4426-ad20-eec2b9a86c57": {"definition": "Dynamic-range compression applied to background-vocal tracks or their bus to even out level differences, so the harmonies sit consistently and cohesively behind the lead vocal.", "plain_english": "This means using a compressor to make the loud and soft parts of the backing vocals more even. It works like an automatic volume knob that turns down the loudest words, so the harmonies stay steady and blend together.", "purpose_function": "It controls the natural level swings of sung harmonies so they stay present and glued in the mix without jumping out or fading away.", "practical_application": "An engineer often compresses the backing-vocal bus fairly firmly to push the stack back and make it feel like one smooth, blended layer under the lead.", "category": "Background Vocal Mixing", "related_terms": ["Background-vocal bus", "Background-vocal equalization", "Background-vocal de-essing", "Lead vocal", "Background-vocal production"], "common_mistakes": ["Over-compressing until the harmonies sound flat, lifeless, and pumping.", "Compressing each track and then the bus so hard that gain builds up and the noise floor rises.", "Setting the attack too fast and squashing the natural consonants and breath of the vocals."], "scenario_contexts": ["Adding a few dB of gain reduction on the harmony bus to blend a layered stack.", "Using a slower attack to keep clarity on rhythmic backing chants.", "Parallel-compressing backing vocals to keep them audible without pushing them forward."]}, "16c9501a-fd41-4894-9d57-0258aa036244": {"definition": "The targeted reduction of sibilance, the harsh energy from \"s,\" \"sh,\" and \"t\" sounds around 5 to 10 kHz, on background-vocal tracks or bus, using a de-esser or frequency-dependent compressor.", "plain_english": "This tames the harsh, hissy \"s\" and \"sh\" sounds in the backing vocals. A de-esser works like a fast volume knob that only turns down those sharp sounds, so stacked harmonies do not add up into a painful hiss.", "purpose_function": "It stops sibilance from piling up when many vocal layers are stacked, which would otherwise create a harsh, whistling top end in the mix.", "practical_application": "The engineer places a de-esser on the backing-vocal bus, and sometimes on bright individual tracks, to control combined sibilance before reverb or bright EQ makes it worse.", "category": "Background Vocal Mixing", "related_terms": ["Background-vocal equalization", "Background-vocal compression", "Background-vocal bus", "Background-vocal reverb", "Background-vocal production"], "common_mistakes": ["De-essing so hard that the singers seem to develop a lisp and lose clarity.", "De-essing only individual tracks and ignoring how sibilance adds up on the stacked bus.", "Adding bright EQ or reverb before de-essing, so the harshness gets boosted first."], "scenario_contexts": ["Taming stacked 's' sounds on a doubled, tripled harmony chorus.", "De-essing before a bright plate reverb to stop sibilant tails.", "Setting the de-esser threshold so it acts only on the sharpest consonants."]}, "f2655ed2-1792-4d89-862e-0b7d350805f2": {"definition": "A time-based (echo) effect applied to background vocals, adding one or more delayed repeats, often tempo-synced, to create depth, width, or rhythmic interest behind the lead.", "plain_english": "This adds echoes to the backing vocals. Like a short repeat of a word bouncing back, it can make the harmonies feel wider and deeper, and the repeats are often timed to the beat of the song.", "purpose_function": "It pushes background vocals back in the depth of the mix and can widen them or add rhythm, without the wash that heavy reverb brings.", "practical_application": "The engineer sends harmonies to a tempo-synced delay, such as a quarter or eighth note, on an aux, often filtering the repeats darker so they support rather than clutter the lead.", "category": "Background Vocal Mixing", "related_terms": ["Background-vocal reverb", "Background-vocal panning", "Background-vocal bus", "Background-vocal automation", "Background-vocal production"], "common_mistakes": ["Setting the delay time off the tempo, so repeats fight the groove and muddy the track.", "Leaving the repeats full-range and bright, so they mask the lead vocal.", "Feeding back too much, burying the mix in a wash of repeats."], "scenario_contexts": ["Adding a ping-pong delay to spread a harmony line across the stereo field.", "Throwing a timed delay on the last word of a backing phrase.", "Using a slapback delay to thicken doubled backing vocals."]}, "266631fb-f1a5-48c5-8cb4-e8a615f4fe41": {"definition": "The use of EQ to shape the tone of background-vocal tracks or bus, commonly high-passing low rumble and carving competing midrange, so the harmonies support the lead vocal without masking it.", "plain_english": "This means using EQ to change the tone of the backing vocals. Engineers often cut low rumble and some middle tones so the harmonies leave room for the lead voice instead of covering it up.", "purpose_function": "It carves a tonal space for backing vocals so they blend and add richness while leaving the lead vocal clear and up front.", "practical_application": "The engineer high-passes the backing-vocal bus, dips tones that clash with the lead, and may roll off some brightness so the stack sits softly behind the main voice.", "category": "Background Vocal Mixing", "related_terms": ["Background-vocal bus", "Background-vocal compression", "Background-vocal de-essing", "Lead vocal", "Background-vocal production"], "common_mistakes": ["Boosting the same presence range on backing vocals as the lead, so they mask each other.", "Not high-passing the stack, letting low rumble and pops build up across many tracks.", "EQing each track bright, so the combined stack turns harsh and sibilant."], "scenario_contexts": ["High-passing harmonies around 100 to 150 Hz to clean up the low end of a stack.", "Dipping the 2 to 4 kHz range on backing vocals to keep the lead's presence clear.", "Darkening backing vocals so they sit softly behind a bright lead."]}, "e9806221-daef-4ddc-b372-6fab47ec2c8d": {"definition": "The placement of background-vocal tracks across the stereo field, often spreading doubles and harmonies left and right, to create width and separate them from the typically centered lead vocal.", "plain_english": "This is about where the backing vocals sit from left to right in the stereo picture. Spreading the harmonies out to the sides makes the mix feel wide and keeps them clear of the lead voice, which usually sits in the middle.", "purpose_function": "It widens the vocal arrangement and separates harmonies from the lead, so the backing vocals add size without crowding the center of the mix.", "practical_application": "The engineer pans matched double takes hard left and right, or spreads a harmony stack across the field, keeping the lead centered so it stays focused and up front.", "category": "Background Vocal Mixing", "related_terms": ["Background-vocal bus", "Background-vocal delay", "Background-vocal reverb", "Lead vocal", "Background-vocal production"], "common_mistakes": ["Leaving all harmonies in the center, so they pile up on top of the lead vocal.", "Panning a single unmatched take hard to one side, which unbalances the mix.", "Spreading so wide that the vocals fade out when the mix is played in mono."], "scenario_contexts": ["Panning a left and right double of a harmony hard to each side for width.", "Spreading a four-part stack evenly across the stereo field.", "Checking a wide backing-vocal spread in mono for a club or broadcast."]}, "56377c2f-0f9c-4160-8d07-fa316425a963": {"definition": "The overall craft of arranging, recording, layering, and processing background vocals, choosing harmonies, doubles, and stacks and shaping them so they support the lead vocal and the song's arrangement.", "plain_english": "This is the whole job of creating the backing vocals, from writing the harmonies to recording and mixing them. It is like building a soft bed of extra voices that sits behind the main singer and makes the song feel fuller.", "purpose_function": "It exists to add depth, harmony, and energy to a song, reinforcing hooks and choruses while keeping the lead vocal clear and central.", "practical_application": "A producer plans which lines get harmonized, records doubles and stacks for width and power, then blends them with EQ, compression, and effects so they lift the song without swamping the lead.", "category": "Background Vocal Mixing", "related_terms": ["Background-vocal bus", "Background-vocal automation", "Background-vocal panning", "Background-vocal reverb", "Lead vocal"], "common_mistakes": ["Stacking too many layers, so the backing vocals overpower the lead and clutter the mix.", "Recording sloppy, untuned harmonies and expecting the mix to fix the blend.", "Ignoring the arrangement, so backing vocals play all the time instead of lifting key sections."], "scenario_contexts": ["Layering a doubled three-part harmony to make a pop chorus bigger.", "Recording call-and-response backing lines for a soul or gospel track.", "Adding subtle unison doubles to thicken a lead in the final chorus."]}, "55fa4756-2d04-47cb-bab7-a123fb345551": {"definition": "Reverberation applied to background vocals to place them in a sense of space and depth, commonly through a send to a shared reverb so the harmonies sit back behind a drier lead vocal.", "plain_english": "This adds a sense of room or space to the backing vocals, like the echo you hear when you sing in a large hall. It makes the harmonies feel further back, behind the lead voice, which usually stays drier and closer.", "purpose_function": "It creates depth and blends stacked harmonies into a shared space, pushing them behind the lead so the arrangement feels three-dimensional.", "practical_application": "The engineer sends the backing-vocal bus to a reverb such as a plate or hall, often pre-delayed and filtered, so the stack sits back and glues together without washing out the lead.", "category": "Background Vocal Mixing", "related_terms": ["Background-vocal delay", "Background-vocal bus", "Background-vocal panning", "Background-vocal de-essing", "Background-vocal production"], "common_mistakes": ["Drowning the harmonies in reverb, pushing them so far back they lose impact.", "Using the same bright reverb without filtering, so sibilant tails build up.", "Putting reverb on each track separately instead of a shared send, wasting CPU and blurring the blend."], "scenario_contexts": ["Sending a harmony stack to a plate reverb to sit it behind a dry lead.", "Using a longer hall reverb on backing vocals for a ballad's space.", "Adding pre-delay so the harmonies stay clear before the reverb tail blooms."]}, "47cf2256-83f3-497e-9751-149eb18c0893": {"definition": "The deliberate application of harmonic saturation (subtle harmonic distortion from tape, tube, or a plug-in emulation) to backing-vocal tracks, adding harmonic content and perceived density so the vocals blend and sit behind the lead.", "plain_english": "It means adding a gentle, warm fuzz to the backing vocals. This gives them extra tone and thickness so the voices blend together. Think of it as a soft glow that helps them sit behind the main singer.", "purpose_function": "It thickens and glues stacked backing vocals and pushes them slightly back in the mix, so they support the lead vocal without competing with it for clarity.", "practical_application": "An engineer sends the backing-vocal group through a tape or tube saturation plug-in and adds a small amount, checking that it enriches the blend without adding harshness.", "category": "Mixing technique", "related_terms": ["Background-vocal stack", "Background-vocal subgroup", "Harmonic saturation", "Lead vocal", "Parallel processing"], "common_mistakes": ["Adding so much saturation that the backing vocals turn harsh and distract from the lead", "Saturating each track separately and on the group, stacking up distortion until it sounds gritty", "Confusing saturation with volume, and pushing the effect up until the backing vocals jump forward"], "scenario_contexts": ["Warming up a thin stack of backing vocals so it blends into a dense chorus", "Adding a touch of tape drive to help layered harmonies sit behind the lead", "Using gentle saturation to glue several harmony takes into one texture"]}, "8a3fbf73-2abe-4f5e-8707-b66ce70ca4bd": {"definition": "A group of multiple recorded backing-vocal takes—often the same part sung several times, or harmony parts doubled and layered—combined into one thick, unified vocal texture that supports the lead vocal.", "plain_english": "It is a pile of backing vocals made by singing the same part many times and layering the takes. Stacked together they sound big and full. It is like many people singing the same line at once.", "purpose_function": "Layering several takes averages out tiny timing and pitch differences to build a wide, powerful, choir-like backing texture that a single take cannot give.", "practical_application": "The engineer records several passes of each harmony, then groups and balances them so the stack sounds unified and full behind the lead vocal.", "category": "Vocal arrangement", "related_terms": ["Background-vocal subgroup", "Background-vocal width", "Background-vocal saturation", "Vocal doubling", "Lead vocal"], "common_mistakes": ["Stacking so many layers that the backing vocals overpower and mask the lead vocal", "Recording every layer exactly the same way, so the stack sounds phasey instead of wide", "Not tuning and timing the layers, leaving the stack cluttered and smeared"], "scenario_contexts": ["Building a big chorus by tripling each harmony part and blending them", "Layering soft 'oohs' and 'aahs' to thicken a sparse verse", "Doubling a hook line several times for a wall-of-vocals effect"]}, "cc890491-84cc-4b8b-a9c6-1380ed2eebd3": {"definition": "A subgroup (audio bus) that sums all backing-vocal tracks to a single fader and shared processing chain, so the whole backing-vocal section can be balanced and processed together as one unit.", "plain_english": "It is one channel that all the backing vocals feed into. From there you control their total volume and sound with a single fader. It is like gathering many singers under one group control.", "purpose_function": "It lets the engineer set level, EQ, compression, and effects for the entire backing-vocal section at once, keeping the blend consistent and simplifying the mix.", "practical_application": "The engineer routes every backing-vocal channel to the subgroup, then rides that one fader and adds shared processing instead of adjusting each track separately.", "category": "Signal routing", "related_terms": ["Background-vocal stack", "Background-vocal width", "Bass bus", "Subgroup", "Lead vocal"], "common_mistakes": ["Processing each channel and the subgroup as well, causing double compression or EQ", "Routing the lead vocal into the backing-vocal subgroup by mistake, so it gets buried", "Forgetting to assign every backing track, leaving some voices loud in the main mix"], "scenario_contexts": ["Compressing all backing vocals on one bus so they breathe as a unit", "Riding a single fader to lift the whole harmony section in the chorus", "Sending one reverb from the subgroup so every backing voice shares the same space"]}, "5f9663f7-46c5-4eb9-b9a8-06941bdbb323": {"definition": "The perceived left-to-right stereo spread of the backing vocals, created by panning layered takes across the stereo field, hard-panning doubles, or applying stereo effects, so the backing vocals occupy the sides while the lead stays centred.", "plain_english": "It is how far the backing vocals spread out to the left and right. Panning the layers wide makes the voices feel big and surround the main singer in the middle. It is like a choir spread across a stage.", "purpose_function": "Widening the backing vocals opens space in the centre for the lead vocal and creates a bigger, more immersive sense of the vocal arrangement.", "practical_application": "The engineer pans matched double takes hard left and right, keeps the lead centred, and checks that the backing vocals feel wide without pulling focus.", "category": "Stereo imaging", "related_terms": ["Background-vocal stack", "Background-vocal subgroup", "Vocal doubling", "Panning", "Stereo image"], "common_mistakes": ["Widening with a stereo effect that collapses in mono, so the backing vocals vanish on mono systems", "Panning the layers so wide that the arrangement feels hollow in the middle", "Confusing loudness with width, and pushing the sides up until they mask the lead"], "scenario_contexts": ["Hard-panning double-tracked harmonies to frame a centred lead vocal", "Checking mono compatibility after widening a stacked chorus", "Narrowing the backing vocals in verses and opening them wide in the chorus"]}, "6ee342bd-0048-4faf-864b-a89fc87a6b92": {"definition": "A recorded track capturing an electric bass played through a bass amplifier and speaker cabinet, picked up by a microphone and/or the amp's line output, preserving the amp's tone and colouration; it is often recorded alongside a clean DI track.", "plain_english": "It is the bass sound recorded from a real amp and speaker, caught with a microphone. This gives the growl and grit of the amp. Engineers often record it next to a clean plugged-in track and blend the two.", "purpose_function": "It captures the character, drive, and midrange of a bass amp that a clean DI lacks, giving the mix engineer an amp-flavoured tone to blend with the DI for the final sound.", "practical_application": "The engineer mics the bass cabinet, records it to its own track next to the DI, and checks phase alignment so the two can be blended without cancellation.", "category": "Recording technique", "related_terms": ["Bass bus", "Bass attack layer", "Bass definition enhancement", "Direct guitar track", "Off-axis pickup"], "common_mistakes": ["Not phase- or time-aligning the amp track with the DI, so combining them thins the low end", "Recording only the amp track, leaving no clean signal to re-amp or blend later", "UNSAFE: Running the bass amp loud close to the ears for long tracking sessions without hearing protection, which risks permanent hearing damage; keep exposure within OSHA limits."], "scenario_contexts": ["Miking a bass cabinet for grit while a DI captures the clean low end", "Blending an amp track and DI to get both attack and body", "Aligning the amp and DI tracks before committing the bass sound"]}, "29fc3201-179c-4dd7-b127-2905fc993313": {"definition": "A separate signal or track dedicated to the bass's upper-frequency attack—the pick or finger transient and string articulation—typically made by high-pass filtering, distortion, or an added layer, then blended under the main bass body to increase clarity and definition.", "plain_english": "It is a layer that carries only the click and bite of the bass notes. You mix it under the deep body of the bass to help each note cut through. It is like adding a sharp edge back onto a soft sound.", "purpose_function": "It lets the engineer control the bass's attack and definition apart from its low-end weight, so the notes stay clear on small speakers without adding boom.", "practical_application": "The engineer splits the bass, high-pass filters or distorts one copy to isolate the attack, and blends it under the low body, automating it louder in busy sections.", "category": "Mixing technique", "related_terms": ["Bass definition enhancement", "Bass amplifier track", "Bass bus", "Parallel processing", "Bass automation"], "common_mistakes": ["Pushing the attack layer so hard the bass sounds clanky and thin", "Not high-pass filtering the attack layer, so it doubles the low end and causes buildup", "Leaving the attack layer out of phase with the body, weakening the combined tone"], "scenario_contexts": ["Adding a distorted high layer so a bass is audible on phone speakers", "Blending in pick attack to help the bass lock with the kick drum", "Automating the attack layer up in a dense chorus for extra articulation"]}, "e85962a9-f097-404e-b06f-a315e8aefa05": {"definition": "The use of mix automation to change bass parameters over time—most often level, but also EQ, sends, or plug-in settings—so the bass stays even and correctly balanced across a song's sections.", "plain_english": "It is setting the bass volume and controls to change on their own through the song. The mix remembers those moves and repeats them every playback. It is like an extra hand riding the bass fader for you.", "purpose_function": "It keeps the bass consistent from note to note and section to section, evening out uneven notes and lifting or dipping the bass where the arrangement needs it.", "practical_application": "The engineer writes level automation to even out weak or loud bass notes and to raise the bass slightly in choruses, so it sits right throughout the song.", "category": "Mixing technique", "related_terms": ["Bass bus", "Bass attack layer", "Bass definition enhancement", "Volume automation", "Fader ride"], "common_mistakes": ["Leaning on automation to fix a badly tracked or poorly compressed bass instead of recording it well", "Writing so many tiny volume moves that the bass sounds jumpy and unnatural", "Automating the bus and the channel at once, so the two sets of moves fight each other"], "scenario_contexts": ["Evening out one loud open string that jumps out of the bassline", "Nudging the bass up a decibel in each chorus for more drive", "Riding the bass down under a busy vocal line to keep the low end clear"]}, "fb358a51-a625-4730-8d82-d7442aabe4aa": {"definition": "A subgroup bus that sums all bass-related tracks (for example DI, amp, and attack layers) to a single fader and shared processing chain, so the whole bass sound is controlled and processed as one element.", "plain_english": "It is one channel that all the bass tracks feed into. You set the total bass level and add shared effects there in one place. It is like a single master control for everything bass.", "purpose_function": "It lets the engineer glue the separate bass layers together, apply common compression or EQ, and manage the overall bass level with one fader.", "practical_application": "The engineer routes the DI, amp, and attack tracks to the bass bus, adds gentle bus compression to glue them, and rides that fader for the whole bass level.", "category": "Signal routing", "related_terms": ["Bass amplifier track", "Bass attack layer", "Bass automation", "Background-vocal subgroup", "Subgroup"], "common_mistakes": ["Heavy bus compression that pumps and squashes the whole low end", "Processing each bass track and the bus so much that the sound is over-compressed", "Forgetting to phase-check the layers before summing them on the bus"], "scenario_contexts": ["Gluing a DI and amp track together with light compression on the bass bus", "Sending the whole bass to one bus for a single level ride", "Placing one EQ on the bass bus to shape the combined low end"]}, "49429c2b-a244-4850-8297-2dbb391d9d15": {"definition": "Techniques that increase the clarity and note articulation of bass in a mix—such as midrange and upper-harmonic EQ boosts, harmonic exciters or saturation, and parallel distortion—so the bassline stays audible and distinct, including on small speakers with little low-frequency output.", "plain_english": "It means making each bass note clearer and easier to hear. Engineers add higher tones with EQ or gentle distortion so the bass shows up even on small speakers. It is like sharpening a blurry picture so the shape stands out.", "purpose_function": "It ensures the bassline can be followed on any playback system, especially phones and laptops that cannot reproduce deep bass, by adding harmonics the ear reads as the low note's pitch.", "practical_application": "The engineer boosts around 700 Hz to a few kHz, or adds a saturator or exciter, then checks on small speakers that the notes read clearly without becoming harsh.", "category": "Mixing technique", "related_terms": ["Bass attack layer", "Bass bus", "Bass amplifier track", "Harmonic saturation", "Parallel processing"], "common_mistakes": ["Boosting only the deep lows for a 'big' bass, then losing the notes on small speakers", "Over-driving the saturation until the bass sounds fizzy and harsh", "Adding definition with EQ while ignoring the clash with guitars in the same range"], "scenario_contexts": ["Adding harmonics so a bassline is audible on laptop speakers", "Boosting upper-mids to help the bass cut through a dense rock mix", "Using parallel distortion to bring a dull DI bass forward"]}, "e9c7b7bd-d515-453d-a814-2d084853ff20": {"definition": "A bass DI track is a recorded track of the bass guitar taken as a direct feed through a DI (direct injection) box or preamp instrument input, capturing the instrument's signal before any amplifier or speaker; it is distinguished from a miked amp track, which carries the amplifier and cabinet sound.", "plain_english": "This is a bass part recorded straight from the instrument, not from an amp. A small box called a DI sends the clean signal to the recorder. It keeps a pure copy of the bass that you can shape later.", "purpose_function": "It captures a clean, direct, noise-free bass signal with full low end and matched impedance, giving the mix a solid foundation and preserving a signal that can be re-amped or reprocessed after the session.", "practical_application": "An engineer patches the bass through a DI box, records the direct track, and often blends it with a miked amp track for weight and bite, keeping the DI so tone can be re-amped or edited later.", "category": "Recording technique", "related_terms": ["DI box", "Amp track", "Re-amping", "Input impedance", "Ground lift", "Bass equalization"], "common_mistakes": ["Recording the DI too hot so the input clips, baking distortion into a track that was meant to stay clean.", "Using a passive DI on a weak passive bass and losing high-frequency detail when a buffered active DI would have preserved it.", "Blending the DI with a miked amp track without checking polarity, so the low end thins out from phase cancellation."], "scenario_contexts": ["Tracking a rock band and capturing a clean bass DI alongside a miked amp for later blending.", "Keeping only a DI feed during a fast session so the bass tone can be re-amped after the band leaves.", "Recording bass direct in a small room where a loud amp would bleed into the drum and vocal mics."]}, "3b53f97c-a279-4c8a-bd17-1f10f0b39d7c": {"definition": "Bass distortion is the deliberate nonlinear processing of a bass signal (via overdrive, fuzz, saturation, or clipping) to add harmonic content and grit; it generates new harmonics above the fundamental, increasing perceived loudness and helping the bass cut through a dense mix.", "plain_english": "This is grit or fuzz added to the bass sound on purpose. It adds extra tones that help the bass cut through a busy mix. Think of it like the growl in a hard rock bass line.", "purpose_function": "It exists to add harmonics and edge so the bass stays audible on small speakers and through loud guitars, and to give the tone character and aggression that a clean signal lacks.", "practical_application": "A technician adds distortion with a pedal, amp, or plugin, and commonly distorts only a parallel copy of the bass so the clean low end stays intact while the gritty layer adds presence.", "category": "Signal processing", "related_terms": ["Bass distortion track", "Harmonic distortion", "Saturation", "Overdrive", "Parallel processing", "Bass harmonic enhancement"], "common_mistakes": ["Distorting the whole bass signal so the deep low end disappears, leaving a thin, buzzy tone.", "Adding heavy distortion without high-passing or filtering it, letting the fuzz smear the sub frequencies.", "Overdriving until the note pitch is lost, so the bass no longer defines the harmony clearly."], "scenario_contexts": ["Adding fuzz to a rock bass so it drives the song alongside distorted guitars.", "Saturating a bass part lightly so it reads on phone and laptop speakers.", "Blending a distorted bass layer under a clean DI to add bite without losing weight."]}, "a72dbbbf-c8c7-4271-bb8b-7de52061d912": {"definition": "A bass distortion track is a separate track carrying a distorted or saturated version of the bass, usually run in parallel with a clean bass track so the two can be blended; the distorted layer supplies harmonics and midrange bite while the clean layer holds the low-frequency foundation.", "plain_english": "This is a second bass track with the grit added. You keep the clean bass on one track and the fuzzy one on another. Then you blend the two to get both weight and bite.", "purpose_function": "It lets an engineer control clean low end and distorted harmonics independently, so the bass gains presence and audibility on small speakers without losing its deep foundation.", "practical_application": "An engineer splits the bass, distorts one copy, often high-passes that distorted track, and mixes it under the clean track to add grind that survives on phones and earbuds.", "category": "Recording technique", "related_terms": ["Bass distortion", "Bass DI track", "Parallel processing", "Re-amping", "Saturation", "Bass layering"], "common_mistakes": ["Not aligning the distorted track with the clean track, so timing or phase differences cause cancellation and a hollow low end.", "Leaving low frequencies in the distorted track, which fights the clean bass and muddies the sub range.", "Pushing the distortion layer too loud so the blended bass sounds harsh and buzzy instead of full."], "scenario_contexts": ["Re-amping a stored bass DI through a fuzz pedal to create a distortion track after tracking.", "High-passing a saturated bass track and blending it under the clean bass for laptop-speaker presence.", "Automating the distortion track up only in the loud chorus to add energy where the song needs it."]}, "52a568d9-3d78-4a39-b2a7-df7a50822c05": {"definition": "Bass dynamic equalization is the use of a dynamic equalizer on a bass signal, where the gain of a chosen frequency band changes automatically in response to the signal's level, so a band boosts or cuts only when the audio in that band crosses a threshold; it combines the frequency selectivity of an EQ with the level-dependent action of a compressor.", "plain_english": "This is a smart tone control that only acts when a sound gets too strong. It might cut a boomy note only on the loudest hits. The rest of the time it leaves the bass alone.", "purpose_function": "It tames problem frequencies that appear only on certain notes or louder passages, controlling boom, resonance, or mud without permanently changing the tone the way a fixed EQ would.", "practical_application": "A technician sets a dynamic EQ band on a boomy note and a threshold so it cuts only when that note rings out, keeping the overall bass tone consistent from note to note.", "category": "Signal processing", "related_terms": ["Bass equalization", "Multiband compression", "Compressor", "Threshold", "Resonance", "Bass envelope control"], "common_mistakes": ["Confusing dynamic EQ with a static EQ and expecting a constant cut, when the band only moves when the level crosses the threshold.", "Setting the threshold so low that the band acts on every note, which turns it into an ordinary fixed EQ.", "Using wide bands with fast settings so the processing pumps and audibly changes tone."], "scenario_contexts": ["Controlling one boomy note on a bass that rings louder than the others in a room.", "Cutting low mud only during dense chorus sections while leaving sparse verses untouched.", "Reducing a resonant peak that jumps out only on the hardest-played notes."]}, "f7932f6f-fcde-495d-bff4-b90d403338bc": {"definition": "Bass envelope control is the shaping of a bass note's amplitude envelope over time, chiefly its attack and sustain, using tools such as transient shapers, compressors, or envelope processors; it adjusts how sharply a note begins and how it decays without necessarily changing pitch or timbre.", "plain_english": "This shapes how a bass note starts and fades. You can make the pluck sharper or softer, and the note ring longer or shorter. It is like changing how hard and how long each note is hit.", "purpose_function": "It controls the punch and length of bass notes so they lock with the kick drum and groove, adding attack for definition or evening out sustain for a steady, consistent low end.", "practical_application": "A technician uses a transient shaper or compressor attack and release settings to bring out the finger or pick attack, or to smooth uneven note lengths so the bass sits tightly with the drums.", "category": "Signal processing", "related_terms": ["Transient shaper", "Attack", "Sustain", "Compressor", "Bass dynamic equalization", "Bass level ride"], "common_mistakes": ["Adding too much attack so every note clicks and competes with the kick drum.", "Over-extending sustain so notes run together and blur the groove.", "Confusing envelope shaping with EQ, and reaching for tone controls when the real issue is note punch and length."], "scenario_contexts": ["Sharpening the attack of a finger-style bass so it defines the beat against a busy drum kit.", "Evening out uneven sustain on a bass part where some notes ring longer than others.", "Shortening note decay so the bass stays tight in a fast, up-tempo song."]}, "3160e036-c15c-45fd-b349-c0276eeddaf1": {"definition": "Bass equalization is the adjustment of the frequency balance of a bass signal by boosting or cutting selected frequency bands with an equalizer; it shapes the low end, controls mud and boom, and carves space so the bass sits clearly in the mix relative to the kick drum and other instruments.", "plain_english": "This is turning bass tones up or down with tone controls. You might boost the deep lows or cut a boomy note. It helps the bass sit well next to the drums and the rest of the song.", "purpose_function": "It corrects tonal problems and shapes the bass so its low end supports the track without masking the kick drum or clouding the midrange, giving the bass a defined place in the frequency spectrum.", "practical_application": "A technician high-passes unneeded sub rumble, cuts problem mud around the low mids, and boosts a band for definition, often coordinating the bass EQ with the kick so the two do not fight.", "category": "Signal processing", "related_terms": ["Equalizer", "High-pass filter", "Bass dynamic equalization", "Frequency masking", "Kick drum", "Bass DI track"], "common_mistakes": ["Boosting the deep lows heavily on studio monitors, then finding the bass is overpowering everywhere else.", "Cutting so much low end that the bass loses weight and power in the mix.", "EQing the bass in isolation instead of against the kick drum, so the two mask each other in the full mix."], "scenario_contexts": ["Carving a dip in the bass where the kick drum's punch lives so both stay clear.", "High-passing infrasonic rumble from a bass track to clean up the low end.", "Boosting upper harmonics so the bass line is audible on small speakers."]}, "0b8785fd-dd03-4fe5-82c4-fc90a6b50e8b": {"definition": "Bass harmonic enhancement is the generation of upper harmonics from a bass signal, using saturation, exciters, or dedicated harmonic generators, so that overtones related to the low fundamental are added; because small speakers cannot reproduce deep fundamentals, these harmonics let the ear infer the bass pitch through the missing-fundamental effect.", "plain_english": "This adds bright extra tones on top of the deep bass. Small speakers cannot play the deepest lows, so these extra tones let people still hear the bass line. So even on a phone speaker, listeners can still follow the bassline.", "purpose_function": "It makes the bass translate across playback systems by adding overtones the ear links to the low note, so listeners perceive the bass even on devices that cannot reproduce its true low frequency.", "practical_application": "A technician runs the bass through a saturator or bass enhancer, often on a parallel track limited to a chosen harmonic band, and checks the result on small speakers to confirm the low end still reads.", "category": "Signal processing", "related_terms": ["Missing fundamental", "Harmonic distortion", "Saturation", "Exciter", "Bass distortion", "Parallel processing"], "common_mistakes": ["Adding so many harmonics that the bass turns harsh and buzzy instead of warm and clear.", "Assuming enhancement replaces real low end, when full-range systems still need the fundamental present.", "Applying the harmonics across the whole spectrum instead of a focused band, cluttering the midrange."], "scenario_contexts": ["Making a sub-heavy bass audible on phone and laptop speakers before releasing a track.", "Adding overtones to a bass so it survives a car stereo and earbud playback.", "Using an exciter on a parallel bass track to boost presence while keeping the clean sub."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"de2a81c0-855e-4f69-a266-3d56ded2b78a": {"definition": "Bass layering is the technique of combining two or more bass sounds or tracks into a single perceived bass part, typically assigning each layer a role, such as one layer holding the deep sub fundamental and another supplying midrange grit or attack, so the blended result is fuller and more consistent than any single source.", "plain_english": "This is stacking two or more bass sounds to make one fuller part. One sound covers the deep lows and another adds bite up higher. Together they sound bigger than either one alone.", "purpose_function": "It lets an engineer build a bass that works on every speaker by splitting duties, deep weight from one layer and audible presence from another, so the bass is both powerful on big systems and clear on small ones.", "practical_application": "A technician layers a clean sub bass with a grittier or synth bass, matches their tuning and timing, and often filters each layer to its own frequency range so they combine without clashing.", "category": "Arrangement technique", "related_terms": ["Bass distortion track", "Bass harmonic enhancement", "Parallel processing", "Sub bass", "High-pass filter", "Phase"], "common_mistakes": ["Layering two basses in the same frequency range without filtering, so they overlap and turn muddy.", "Not checking polarity between layers, so the low end cancels and the bass sounds weaker combined.", "Leaving the layers out of tune or out of time with each other, which blurs the note and the groove."], "scenario_contexts": ["Stacking a clean sub bass under a distorted bass so the part has both weight and grit.", "Adding a synth bass layer to a recorded electric bass to fill out a pop production.", "Splitting a bass into a low layer and a high layer, each filtered to its own band, for better translation."]}, "10acca63-fed5-4fba-a46d-8fce921e7634": {"definition": "A bass level ride is the manual adjustment of the bass track's fader (gain riding) over the course of a song to keep its loudness consistent, raising softer notes and lowering louder ones; it is a form of hands-on level automation used in place of, or alongside, a compressor.", "plain_english": "This is slowly moving the bass volume up and down by hand as the song plays. You lift the soft notes and pull back the loud ones. It keeps every bass note easy to hear.", "purpose_function": "It evens out note-to-note and section-to-section level differences so the bass stays steady in the mix, giving transparent control that avoids the tone changes a heavy compressor can add.", "practical_application": "An engineer writes fader automation on the bass, nudging weak notes up and strong notes down, and often rides levels before or after a compressor to fix moments the compressor misses.", "category": "Mixing technique", "related_terms": ["Fader automation", "Gain riding", "Compressor", "Bass envelope control", "Bass equalization", "Automation"], "common_mistakes": ["Relying only on a heavy compressor for consistency instead of riding levels, which can dull the tone and pump.", "Making sudden fader jumps that are audible as level steps rather than smooth moves.", "Riding the bass in solo instead of against the full mix, so the moves do not match what the song needs."], "scenario_contexts": ["Lifting a few quiet bass notes that got lost under a loud chorus.", "Pulling the bass down slightly in a sparse verse so it does not overpower the vocal.", "Riding the bass fader ahead of a compressor to smooth big level swings before compression."]}, "5b8a27c6-b2ec-45bc-b794-7931d2c81ed2": {"definition": "The application of a limiter to a bass instrument's signal to cap its peaks at a set threshold, holding the loudest notes back so the low end keeps a consistent level and does not consume excess headroom.", "plain_english": "Using a limiter to hold back the loudest bass notes. This keeps the bass at a steady level so it never jumps out of the mix.", "purpose_function": "It controls short peaks in the bass so the instrument stays even in level and leaves enough headroom for the rest of the mix.", "practical_application": "A tracking or mix engineer places a limiter on the bass DI or channel and sets the threshold to catch only the strongest peaks, tightening the low end before the master bus.", "category": "Dynamics Processing", "related_terms": ["Bass mixing", "Bass multiband compression", "Bass note consistency", "Limiter", "Headroom", "Threshold"], "common_mistakes": ["Setting the threshold so low that the limiter squashes every note and removes the bass's natural dynamics", "Confusing limiting with compression; a limiter uses a very high ratio to act as a ceiling, not gentle level control", "Heavily limiting the bass channel and again on the master, causing audible pumping in the low end"], "scenario_contexts": ["Taming an aggressive slap or pick bass part that has occasional loud peaks", "Locking the bass to a steady level so it supports the kick drum without spikes", "Controlling a DI bass before a loud PA to protect subwoofers from transient overshoot"]}, "41b27b26-e1e9-41fc-adf4-56b875160d7a": {"definition": "The use of equalization, high-pass filtering, and dynamics to shape and restrain the lowest frequencies of a bass instrument (roughly below 100 Hz), managing sub-bass energy so it stays tight and defined rather than boomy or excessive.", "plain_english": "Shaping the deepest part of the bass sound so it stays tight, not boomy. Engineers cut or control the very low notes so the low end feels solid but clean.", "purpose_function": "It keeps sub-bass energy under control so the mix has a firm foundation without wasting headroom or muddying the sound on large speakers.", "practical_application": "An engineer uses a high-pass filter to remove sub-sonic rumble, then EQ or compression around 40 to 100 Hz to keep the deep bass even and defined.", "category": "Equalization", "related_terms": ["Bass mixing", "Bass mud reduction", "Bass multiband compression", "High-pass filter", "Subwoofer", "Equalization"], "common_mistakes": ["Boosting very low frequencies on small speakers where they cannot be heard, leaving too much sub energy in the mix", "UNSAFE: Failing to high-pass sub-sonic rumble, which wastes headroom and can overload and damage subwoofer drivers", "Cutting so much low end that the bass sounds thin on full-range systems"], "scenario_contexts": ["Tightening a boomy bass guitar recorded through a DI in a small room", "Managing sub energy on a synth bass before a club or festival PA", "Cleaning sub-sonic rumble from a bass track before mastering"]}, "40ce7747-5aff-47b3-a8a4-807940606955": {"definition": "The midrange harmonic content of a bass sound (roughly 500 Hz to 3 kHz), often emphasized or added through EQ, distortion, or a duplicated parallel track, so the bass stays audible on small speakers that cannot reproduce deep lows.", "plain_english": "The middle part of the bass tone, not the deep boom. Engineers boost or add it so you can still hear the bass on phones and laptop speakers.", "purpose_function": "It gives the bass presence and definition that carries on small speakers and earbuds, so the bassline is still heard when the deep low end is missing.", "practical_application": "An engineer adds mild distortion or a parallel EQ'd layer to bring out upper harmonics around 700 Hz to 2 kHz, helping the bass translate across playback systems.", "category": "Tone Shaping", "related_terms": ["Bass mixing", "Bass mud reduction", "Bass low-frequency control", "Parallel processing", "Harmonic distortion", "Translation"], "common_mistakes": ["Relying only on deep lows, so the bass disappears on phones and laptop speakers", "Adding so much distortion that the midrange layer sounds fizzy or harsh", "Boosting midrange without checking that it does not clash with guitars or vocals in the same range"], "scenario_contexts": ["Making a sub-heavy synth bass audible on earbuds and phone speakers", "Adding grit to a clean DI bass so it cuts through a dense rock mix", "Checking a mix on small speakers and finding the bass only through its midrange"]}, "d22560be-000e-4677-baa7-b9b061f6b30d": {"definition": "The process of balancing, shaping, and controlling a bass instrument within a mix using level, EQ, dynamics, and stereo placement so it locks with the drums and supports the harmonic foundation without masking other elements.", "plain_english": "The job of fitting the bass into the whole song. You set its volume and tone so it works with the drums and does not cover the other instruments.", "purpose_function": "It gives the mix a solid low-end foundation and ties the bass to the kick drum, so the rhythm section feels tight and the song has power and groove.", "practical_application": "An engineer sets the bass level against the kick, carves EQ so each has its own space, and uses compression to keep the bass steady under the vocal and guitars.", "category": "Mixing", "related_terms": ["Bass limiting", "Bass mud reduction", "Bass phase alignment", "Bass mono compatibility", "Kick drum", "Frequency masking"], "common_mistakes": ["Mixing the bass too quietly because it sounds loud on bass-heavy monitors that are not accurate", "Letting the kick and bass fight for the same frequencies instead of giving each its own space", "Judging the bass on only one speaker system instead of checking several"], "scenario_contexts": ["Balancing bass and kick so the low end is powerful but clear", "Setting up a rough mix during a band tracking session", "Reworking a bass part to sit under a busy vocal and guitar arrangement"]}, "2928c603-1199-4c6a-bf3a-027d7e94c813": {"definition": "The practice of keeping the low-frequency content of the bass summed to mono, or centered and phase-coherent, so it stays full and does not partially cancel when a stereo mix is played on mono systems.", "plain_english": "Keeping the bass in the center so it stays strong when played in mono. If the low notes are spread in stereo, they can get weaker or vanish on a mono speaker.", "purpose_function": "It prevents phase cancellation of the low end on mono playback such as clubs, phones, and PA systems, so the bass stays powerful everywhere.", "practical_application": "An engineer uses a mono-maker or elliptical EQ to sum everything below about 100 to 150 Hz to mono, then checks the mix on a mono monitor for level loss.", "category": "Stereo Imaging", "related_terms": ["Bass mixing", "Bass phase alignment", "Bass low-frequency control", "Phase cancellation", "Mono compatibility", "Elliptical EQ"], "common_mistakes": ["Widening or adding stereo effects to the deep bass, which cancels on mono systems", "Never checking the mix in mono, so low-end loss goes unnoticed until playback", "Assuming a wide stereo bass sounds bigger, when it often sounds weaker in mono"], "scenario_contexts": ["Preparing a dance track for club systems that sum the subs to mono", "Checking a stereo-recorded bass for low-end cancellation in mono", "Making sure a mix holds up on a mono phone speaker or single PA cabinet"]}, "86c0df7a-de70-4219-b1fa-f31826ba45a5": {"definition": "The reduction of excess low-midrange energy (roughly 150 to 500 Hz) in the bass through EQ cuts or dynamic control, clearing the buildup that makes a mix sound thick, boxy, or undefined.", "plain_english": "Cutting the thick, cloudy part of the bass in the low mids. Removing it makes the mix sound clearer and less boomy.", "purpose_function": "It clears the low-mid buildup where bass, guitars, and other instruments pile up, so the mix sounds clean and each part is easier to hear.", "practical_application": "An engineer sweeps a narrow EQ band through 150 to 400 Hz to find the boxy frequency, then cuts it, sometimes with a dynamic EQ so the cut acts only when the mud appears.", "category": "Equalization", "related_terms": ["Bass mixing", "Bass low-frequency control", "Bass midrange layer", "Dynamic EQ", "Frequency masking", "Equalization"], "common_mistakes": ["Cutting too much low-mid, which leaves the bass thin and lifeless", "Blaming the bass for mud that is actually coming from guitars or room resonance", "Making big EQ cuts while soloed instead of checking the change in the full mix"], "scenario_contexts": ["Cleaning a boomy bass and guitar buildup in a dense rock mix", "Fixing a boxy sound from a bass recorded in an untreated room", "Opening up a muddy mix so the vocal and drums sit clearly"]}, "f0cc8ab2-4929-47a0-8032-71bea7666b58": {"definition": "Compression of the bass signal split into separate frequency bands, allowing independent dynamic control of the sub, low, and upper regions, so the deep lows can be evened out without affecting the note attack or midrange.", "plain_english": "Compressing the bass in separate frequency zones instead of all at once. This lets you steady the deep lows while leaving the punch and mids alone.", "purpose_function": "It controls uneven low-end energy in just the problem band, keeping the deep notes consistent while preserving the attack and tone of the rest of the bass.", "practical_application": "An engineer splits the bass around 120 Hz and compresses only the low band to tame notes that boom, leaving the upper band's dynamics and pick attack intact.", "category": "Dynamics Processing", "related_terms": ["Bass limiting", "Bass note consistency", "Bass mixing", "Multiband compression", "Crossover", "Dynamic EQ"], "common_mistakes": ["Over-compressing the low band until every note is the same level and the groove feels dead", "Setting crossover points carelessly, causing bands to overlap and create phase issues", "Using multiband when a simple EQ cut or single compressor would solve the problem"], "scenario_contexts": ["Evening out a bass where only the low E and open strings boom", "Controlling sub energy on a synth bass without dulling its attack", "Fixing a bass that is uneven only in the deep register"]}, "461247ae-1cc9-4070-84bf-8c720aa10f98": {"definition": "The evenness of level and tone from note to note across a bass performance, achieved through compression, dynamic control, and sometimes editing, so no single note booms or disappears in the mix.", "plain_english": "Making every bass note come through at a steady volume. Compression and edits stop some notes from booming while others get lost.", "purpose_function": "It ensures each note in the bassline is heard clearly and at a balanced level, giving the low end a solid, dependable feel under the song.", "practical_application": "An engineer uses compression, and sometimes clip-gain or volume automation, to lift weak notes and hold back loud ones so the bassline is even.", "category": "Dynamics Processing", "related_terms": ["Bass limiting", "Bass multiband compression", "Bass mixing", "Compression", "Volume automation", "Gain staging"], "common_mistakes": ["Fixing uneven notes with heavy compression alone when the real cause is a room resonance or an uneven instrument", "Ignoring that some notes ring louder because of the recording space, not the playing", "Flattening every note so completely that the bassline loses its natural feel"], "scenario_contexts": ["Evening out a bass part where some fretted notes are much louder than others", "Smoothing a DI bass so every note supports the kick equally", "Preparing a bass track so no note jumps out during the final mix"]}, "e30bef14-2427-44ef-874f-425ab09399f8": {"definition": "The time and polarity alignment of multiple bass signals, or of the bass relative to the kick drum, so their low-frequency waveforms add constructively rather than partially cancelling, preserving a full and punchy low end.", "plain_english": "Lining up the timing of bass signals so their low notes add up instead of cancelling. When they are out of line, the bass sounds thin and weak.", "purpose_function": "It prevents phase cancellation between combined bass sources, or between bass and kick, keeping the low end powerful and defined instead of hollow.", "practical_application": "When blending a bass DI and a miked amp, an engineer time-aligns the tracks and checks polarity, nudging one so the low end is fullest; the same is done between kick and bass.", "category": "Phase Alignment", "related_terms": ["Bass mixing", "Bass mono compatibility", "Bass low-frequency control", "Phase cancellation", "Polarity", "Kick drum"], "common_mistakes": ["Forgetting to check polarity between the DI and amp tracks, leaving the low end hollow", "Assuming a polarity flip fixes everything, when a timing offset also needs alignment", "Aligning by eye on the waveform without listening for the fullest low end"], "scenario_contexts": ["Blending a bass DI with a miked bass amp cabinet", "Aligning the kick and bass so the low end hits together", "Combining two mics on a bass cabinet without losing low end"]}, "d35b7ad0-d299-4b2e-96b8-a9e850cd7482": {"definition": "Setting the correct polarity, and matching the timing, between two or more bass signals — such as a direct (DI) track and a miked bass amp, or bass and kick — so their low frequencies add together instead of cancelling.", "plain_english": "When you record bass two ways at the same time, the two tracks can fight and thin out the low end. Flipping the polarity switch usually gets them to line up and sound full again. Sometimes the timing of one track also needs a small nudge.", "purpose_function": "It makes the low end of combined bass sources sum fully and predictably, because mismatched polarity causes partial cancellation that leaves the bass weak and hollow.", "practical_application": "The engineer toggles the polarity switch on the DI or amp channel and keeps the setting that sounds fullest, or slides one track in the DAW so its waveform lines up with the other.", "category": "Phase Alignment", "related_terms": ["Bass reamping", "Bass section balance", "Bass sub layer", "Direct injection (DI)", "Phase cancellation", "Kick-bass relationship"], "common_mistakes": ["Assuming the DI and amp are automatically in polarity when they are almost never perfectly aligned.", "Flipping polarity by ear on headphones only, where low-end cancellation is hard to hear.", "Confusing polarity (a flip) with phase (a time offset) and expecting one switch to fix timing problems.", "Aligning polarity for a full sound in solo but never checking it against the kick and the full mix."], "scenario_contexts": ["Blending a bass DI track with a miked bass cabinet during mixing.", "Lining up bass and kick drum so the combined low end stays solid.", "Combining a clean sub layer with a distorted bass layer."]}, "1d012f12-689b-4e22-998a-da6ba2b60315": {"definition": "Recording a clean bass performance as a direct (DI) signal, then later sending that stored signal back out through a bass amplifier or effects and re-recording the result, so the tone can be shaped after tracking.", "plain_english": "You record the bass clean, straight into the computer first. Later you send that clean take back out through a real amp and record its sound, so you can pick the tone after the player has gone home.", "purpose_function": "It separates the performance from the tone, letting the engineer choose or change the amp sound later without needing the bassist to play the part again.", "practical_application": "The engineer plays the stored DI track out of the interface through a reamp box into a bass amp, mics or DIs the amp, and records the new tone alongside the original DI.", "category": "Bass Tracking", "related_terms": ["Bass polarity alignment", "Direct injection (DI)", "Reamp box", "Bass room layer", "Bass saturation"], "common_mistakes": ["Feeding a line-level DI signal straight into an amp input without a reamp box, causing an impedance mismatch and weak, thin tone.", "Not saving the original clean DI track, so there is nothing left to reamp later.", "Ignoring polarity between the reamped tone and the DI, which can thin the low end when they are blended.", "Creating a ground-loop hum between the interface and amp instead of using a reamp box with a ground lift."], "scenario_contexts": ["Deciding on a bass amp tone during mixing rather than at tracking.", "Rescuing a session where the recorded amp tone did not fit the final mix.", "Trying several amp and pedal tones from one saved DI take."]}, "98f5cddb-7ef5-4a67-a351-51e447542158": {"definition": "The targeted reduction of one or more narrow, over-loud resonant frequencies in a bass track — often caused by the instrument, room, or amp — using a narrow EQ cut or dynamic EQ so the low end stays even across notes.", "plain_english": "Some bass notes ring out much louder than the rest because of an odd peak in the room or the instrument. Fixing it means finding that loud spot and turning it down. Then every note sits at a steady, even level.", "purpose_function": "It evens out note-to-note loudness in the bass so the low end feels smooth and controlled instead of jumping out on certain pitches.", "practical_application": "The engineer sweeps a narrow EQ boost to find the ringing frequency, then cuts it, or sets a dynamic EQ or multiband compressor to pull it down only when it flares up.", "category": "Low-End Processing", "related_terms": ["Bass section balance", "Bass saturation", "Bass sidechain ducking", "Dynamic EQ", "Resonant frequency", "Multiband compression"], "common_mistakes": ["Using a wide EQ cut that removes the resonance but also guts the surrounding low end.", "Cutting a resonance that only stands out when soloed but is not a problem in the full mix.", "Applying one fixed EQ curve to every song instead of finding each song's real resonant note.", "Confusing a room resonance heard on the monitors with a problem in the actual recording."], "scenario_contexts": ["Taming a boomy note that jumps out on a five-string bass.", "Controlling a room mode that colors a miked bass amp.", "Smoothing uneven low end before bus compression."]}, "4ad509fc-d22a-4c7a-b70c-a29f52105e87": {"definition": "An additional recorded track that captures a bass amplifier through one or more distant room microphones, blended with the close-miked or DI bass to add natural room ambience and body.", "plain_english": "This is an extra bass track picked up by a mic placed back in the room, not right on the amp. Mixed in gently, it adds air and a sense of the real space around the close bass sound.", "purpose_function": "It adds depth, ambience, and natural body to the bass by capturing how the amp sounds in the room, which a close mic or DI alone misses.", "practical_application": "The engineer sets a room mic several feet from the bass cabinet, records it on its own track, and blends a little under the DI or close mic while checking polarity and timing.", "category": "Bass Tracking", "related_terms": ["Bass reamping", "Bass polarity alignment", "Room microphone", "Direct injection (DI)", "Bass sub layer"], "common_mistakes": ["Blending the room track without checking polarity and timing, which thins the low end.", "Adding so much room that the bass loses focus and definition.", "Recording in a small, boomy room and capturing mud instead of useful ambience.", "Expecting a room mic to fix a bad amp tone rather than support a good one."], "scenario_contexts": ["Adding natural depth to a rock bass track cut in a good-sounding room.", "Blending ambience under a DI so the bass feels less sterile.", "Capturing a live-band feel when bass and drums are tracked together."]}, "af65f5f6-c177-4449-bb4d-fc2eca3155ce": {"definition": "The deliberate addition of harmonic distortion to a bass signal — via tubes, tape, transformers, or plugins — that generates upper harmonics of the low fundamental, adding warmth, perceived loudness, and presence on small speakers.", "plain_english": "Saturation adds a gentle, musical grit to the bass by creating higher tones tied to its low notes. This makes the bass feel warmer and louder. It also helps the bass show up on small speakers that can barely play deep notes.", "purpose_function": "It generates harmonics above the bass fundamental so the instrument is heard as fuller and louder, and stays audible on speakers too small to reproduce the lowest frequencies.", "practical_application": "The engineer runs the bass through a tube, tape, or transformer emulation, or a saturation plugin, adding drive by ear until the bass feels solid without turning fuzzy.", "category": "Low-End Processing", "related_terms": ["Bass sub layer", "Bass small-speaker translation", "Bass resonance suppression", "Harmonic distortion", "Tape saturation", "Bass reamping"], "common_mistakes": ["Adding so much drive that the bass turns fuzzy and loses its clean low end.", "Saturating the whole bass instead of a parallel or high-passed copy, muddying the sub.", "Assuming saturation can replace good level and EQ balance.", "Judging saturation only on large monitors and missing how harsh it gets on small speakers."], "scenario_contexts": ["Helping a bass cut through on phone and laptop speakers.", "Warming up a sterile DI bass with tape-style drive.", "Adding harmonics so the bass reads on systems that cannot play deep sub."]}, "f885c67a-a5f0-48dd-940f-bd83654480dd": {"definition": "The relative level and frequency balance between the low-end elements of an arrangement — typically the bass instrument, the kick drum, and any sub layer — so they share the low frequencies clearly instead of masking one another.", "plain_english": "This is about getting the bass and kick drum to share the low end without stepping on each other. You set their levels and tones so both stay clear, instead of turning into one big muddy rumble.", "purpose_function": "It keeps the foundation of the mix tight and clear by making sure the kick, bass, and any sub each have a defined role in the low frequencies.", "practical_application": "The engineer sets kick and bass levels together, often carving a little EQ space so one owns the deep sub and the other the punch, then checks the balance on different speakers.", "category": "Mix Balance", "related_terms": ["Bass sidechain ducking", "Bass sub layer", "Bass small-speaker translation", "Kick-bass relationship", "Frequency masking", "Bass resonance suppression"], "common_mistakes": ["Turning the bass up in solo until it sounds huge, then finding it buries the kick in the full mix.", "Letting kick and bass both fight for the same low frequency instead of splitting the range.", "Judging low-end balance on speakers or earbuds that cannot reproduce it.", "Fixing balance only with level and never with EQ or arrangement changes."], "scenario_contexts": ["Setting kick and bass levels early in a rock or pop mix.", "Making room for a sub-bass synth under an electric bass.", "Rebalancing the low end after the drum bus changes."]}, "9a022e69-46a6-46ae-ab7d-b59c05c8ef41": {"definition": "A technique in which a compressor on the bass is triggered by the kick drum through a sidechain input, so the bass level dips briefly each time the kick hits, clearing space for the kick's transient in the low end.", "plain_english": "A compressor listens to the kick drum and turns the bass down for a split second every time the kick hits. This lets the kick punch through cleanly, then the bass jumps right back up, so both stay clear.", "purpose_function": "It stops the bass and kick from clashing in the same low frequencies by momentarily lowering the bass when the kick lands, keeping both punchy and audible.", "practical_application": "The engineer inserts a compressor on the bass, routes the kick to its sidechain (key) input, and sets threshold, ratio, and release so the bass dips just enough on each kick and recovers by the next note.", "category": "Low-End Processing", "related_terms": ["Bass section balance", "Bass sub layer", "Sidechain compression", "Kick-bass relationship", "Compression ratio", "Bass small-speaker translation"], "common_mistakes": ["Setting the release too slow so the bass stays ducked and pumps unnaturally.", "Ducking so hard that the bass audibly disappears on every kick.", "Using sidechain ducking to mask a balance problem that EQ or arrangement should solve.", "Triggering from the wrong source, like the whole drum bus, so the bass ducks on the snare too."], "scenario_contexts": ["Making the kick punch through a busy electronic or pop mix.", "Tightening a muddy low end where kick and bass overlap.", "Creating a rhythmic pumping effect in dance music."]}, "d9f72529-8cac-484d-87d0-849bb68c7c70": {"definition": "How well the bass content of a mix stays audible and balanced on small playback devices — phones, laptops, earbuds — that cannot reproduce the lowest fundamentals and rely instead on their harmonics.", "plain_english": "Small speakers like phones and earbuds can barely play deep bass. Good translation means the bass still comes through on them, because you added higher tones that stand in for the deep notes your ears fill in.", "purpose_function": "It ensures the bass and groove still read on the tiny speakers most listeners use, where the deepest frequencies are simply missing.", "practical_application": "The engineer checks the mix on a phone or small reference speaker and adds saturation or upper-harmonic EQ so the bass line stays present even without true sub reproduction.", "category": "Mix Translation", "related_terms": ["Bass saturation", "Bass sub layer", "Bass section balance", "Reference monitoring", "Harmonic distortion", "Bass resonance suppression"], "common_mistakes": ["Mixing bass only on large monitors and assuming it will translate to phones.", "Relying on deep sub energy that small speakers cannot play, leaving the bass inaudible on them.", "Adding harmonics so aggressively that the bass sounds harsh on full-range systems.", "Judging translation on a single device instead of several small speakers."], "scenario_contexts": ["Checking a final mix on a phone speaker before release.", "Making a bass line groove on laptop speakers.", "Balancing sub energy against harmonics for streaming playback."]}, "5fe3b352-dcd1-4b4a-a0d3-93c5fe6311e5": {"definition": "A dedicated low-frequency track — often a sine-like synth or a filtered copy of the bass — placed beneath the main bass to reinforce the deepest fundamentals (roughly below 60–80 Hz) and add weight.", "plain_english": "This is an extra deep track added under the bass to give it more weight down low. It is usually a simple, clean tone that fills in the very deepest notes the main bass is missing.", "purpose_function": "It adds controlled deep-end weight and consistency to the low frequencies, filling in fundamentals the main bass may lack, especially in genres built on heavy sub.", "practical_application": "The engineer adds a sine sub synth or a low-passed duplicate that follows the bass notes, tunes it to the right pitches, and checks polarity and level so it reinforces rather than cancels the main bass.", "category": "Low-End Arrangement", "related_terms": ["Bass section balance", "Bass saturation", "Bass small-speaker translation", "Bass polarity alignment", "Sub-bass", "Bass sidechain ducking"], "common_mistakes": ["Adding a sub layer out of polarity with the main bass, which cancels the low end.", "Letting the sub play wrong notes because it is not tracked to the bass line.", "Piling on sub energy that sounds huge on big monitors but muddies smaller systems.", "Forgetting to control the sub's level so it eats headroom on the master."], "scenario_contexts": ["Reinforcing the low end of a hip-hop or EDM track.", "Filling in deep fundamentals under a thin electric bass.", "Adding weight to a bass line for club playback."]}, "ff8b323d-ce26-44cb-b837-5c0b10b3fa58": {"definition": "A subgroup (group bus) that combines the bass-related channels—such as a direct (DI) feed and a miked amp, or several bass tracks—onto a single fader for shared level, processing, and routing control.", "plain_english": "It is one fader that controls all the bass tracks at once. It is like putting every bass sound in one folder so you can turn them up or down together and treat them as a group.", "purpose_function": "It lets an engineer balance and process every bass source as a single unit, so the whole low end moves together and shared effects like compression are set once instead of on each channel.", "practical_application": "When tracking a band, an engineer routes the bass DI and amp mic to a bass subgroup, then compresses or rides that one bus rather than each channel separately.", "category": "Signal routing", "related_terms": ["Subgroup", "Direct guitar track", "Bus compression", "VCA group", "Gain staging", "Aux send"], "common_mistakes": ["Routing the individual bass channels to both the subgroup and the main mix, so the signal is counted twice and gets too loud", "Overcompressing on the subgroup without watching gain staging, which squashes the low end", "Confusing a subgroup, which carries audio, with a VCA group, which only links faders"], "scenario_contexts": ["Grouping a bass DI and miked amp to one fader so they can be balanced together during a live band tracking session", "Applying one compressor across the bass subgroup to glue the low end before it hits the mix bus", "Muting the whole bass part quickly by pulling down a single subgroup fader"]}, "e05a43bd-43c3-4bf8-b8c6-d412205ea517": {"definition": "A high-pass (low-cut) filter applied to a bass signal to remove very low, largely inaudible energy below roughly 20–40 Hz that carries no musical content but wastes headroom and can drive loudspeakers into excessive cone excursion.", "plain_english": "It means cutting out the super-low rumble under the bass that you cannot really hear. Clearing that useless deep energy gives your mix and your speakers more room to work.", "purpose_function": "It protects headroom and loudspeakers by stripping subsonic rumble—from handling, stage vibration, or DC offset—before it inflates levels or pushes woofers past their safe limits.", "practical_application": "An engineer sets a steep high-pass around 30 Hz on the bass channel to keep stage rumble and cone flap out of the low end.", "category": "Filtering", "related_terms": ["High-pass filter", "Rumble filter", "Headroom", "Cone excursion", "DC offset", "Bass subgroup"], "common_mistakes": ["Setting the cutoff too high, which thins out the real fundamental notes of the bass", "Using a gentle slope that barely touches the rumble, so subsonic energy still eats headroom", "UNSAFE: Feeding unfiltered subsonic energy to a PA at high level, which can drive woofers past their excursion limit and damage the drivers"], "scenario_contexts": ["High-passing the bass channel at a live show to stop stage-borne rumble from muddying the low end", "Removing DC offset and sub-rumble from a bass DI before compression", "Protecting subwoofers by cutting inaudible sub-20 Hz energy in a loud mix"]}, "0dd6553a-cc3e-4a69-a45f-476b0ed4488d": {"definition": "The management of how long bass notes ring out, achieved through playing technique such as muting or damping, instrument setup, or processing such as compression, gating, or the sustain stage of a transient shaper.", "plain_english": "It is deciding how long each bass note keeps ringing before it fades. You can shorten notes by muting the strings, or stretch them out with a compressor.", "purpose_function": "It lets an engineer or player match note length to the song, so the bass either locks tightly with the kick or holds long, even notes under the arrangement.", "practical_application": "To even out a part where some notes die early, an engineer adds gentle compression that raises the tail, lengthening the sustain of the bass.", "category": "Dynamics processing", "related_terms": ["Compression", "Bass transient shaping", "Gating", "Palm muting", "Bass subgroup", "Envelope"], "common_mistakes": ["Using heavy compression to add sustain, which also pulls up hiss and amp noise in the gaps", "Blaming the instrument for uneven sustain when the real fix is playing technique or damping", "Gating too tightly and chopping off the natural decay of held notes"], "scenario_contexts": ["Compressing a bass take so short, uneven notes ring long enough to sit under the vocal", "Palm muting during tracking to tighten sustain so the bass locks with the kick drum", "Shaping note length on a synth bass so pads and bass do not smear together"]}, "a8b8f302-a6df-4c22-a31e-9e9451405a39": {"definition": "The use of a transient designer or shaper to independently adjust the attack (initial pluck or pick) and sustain portions of a bass signal, changing its punch and note length without relying on a traditional threshold-based compressor.", "plain_english": "It means changing the punch of the bass's first hit and how long each note holds, using a tool made for that job. It is like a volume knob just for the thump at the start of each note.", "purpose_function": "It gives level-independent control over punch and decay, so an engineer can add attack for definition or soften it for a rounder feel regardless of how loud the part is.", "practical_application": "To make a soft bass line cut through, an engineer boosts the attack with a transient shaper so each note's pluck is clearer in the mix.", "category": "Dynamics processing", "related_terms": ["Transient designer", "Bass sustain control", "Compression", "Attack", "Envelope", "Bass subgroup"], "common_mistakes": ["Pushing the attack too far, so the bass clicks and loses body", "Assuming a transient shaper works like a compressor, when it responds to the shape of the note rather than a level threshold", "Boosting attack and sustain heavily at once, which raises noise and overloads the channel"], "scenario_contexts": ["Adding attack to a dull bass DI so each note's pluck reads clearly in a dense mix", "Softening a spiky slap-bass part by pulling down its attack", "Tightening a boomy bass by reducing sustain instead of cutting low EQ"]}, "73100af9-9084-48fe-9505-5e33bd28da11": {"definition": "The drumhead mounted on the top, playing side of a drum, struck directly by the stick, mallet, or beater, as distinct from the resonant head on the bottom.", "plain_english": "It is the top skin of a drum, the one you actually hit. The other head, on the bottom, is not struck and just rings along with it.", "purpose_function": "It is the drum's main sound-producing and playing surface; its type—coated or clear, single or double ply—shapes the attack, tone, sustain, and durability of the drum.", "practical_application": "When micing a snare, an engineer places the top mic just over the edge of the batter head and tunes or dampens that head to control ring.", "category": "Drum component", "related_terms": ["Resonant head", "Bearing-edge problem", "Beater impact", "Drum tuning", "Snare drum", "Coated head"], "common_mistakes": ["Mixing up the batter head with the resonant head when tuning, and changing the wrong side", "Over-tightening tension rods unevenly, so the batter head chokes and will not seat in tune", "Assuming a single mic over the batter head captures the full drum without the resonant side's tone"], "scenario_contexts": ["Choosing a coated batter head to soften attack when tracking a warm snare sound", "Tuning the batter head to change the pitch and feel of a tom during a session", "Placing the close mic over the batter head edge to capture stick attack"]}, "91fc1460-a6c8-4f21-b5fa-912ae18966c9": {"definition": "A defect at the bearing edge—the shaped rim of a drum shell where the head makes contact—such as a nick, warp, or out-of-round or uneven edge, which prevents the head from seating evenly and causes tuning instability, poor tone, and unwanted overtones.", "plain_english": "It is trouble at the rim of the drum shell where the skin rests. If that edge is dented or uneven, the head cannot sit flat, so the drum sounds bad and will not stay in tune.", "purpose_function": "Recognizing a bearing-edge problem explains why a drum resists tuning or rings oddly, pointing to a shell or edge fault rather than the head or hardware.", "practical_application": "When a drum will not tune out despite fresh heads, a technician checks the bearing edge on a flat surface for high spots or warping before recutting or leveling it.", "category": "Drum maintenance", "related_terms": ["Bearing edge", "Batter head", "Resonant head", "Drum tuning", "Drum shell", "Beater impact"], "common_mistakes": ["Blaming the drumhead or lugs for tuning trouble when the bearing edge is the real fault", "Cranking tension to force a warped edge to seat, which only chokes the drum and stresses the shell", "Setting a drum on a rough surface and chipping the bearing edge"], "scenario_contexts": ["Diagnosing why a snare rings unevenly and will not hold tune after a head change", "Checking a used drum's bearing edges before a recording session", "Sending a shell out to have a damaged bearing edge re-cut and leveled"]}, "a0aef90c-e718-4e8e-8a14-6cd0b5b244e7": {"definition": "The strike of a bass-drum pedal beater against the batter head; its character—set by the beater's material (felt, wood, or plastic), hardness, and force—determines the attack, click, and tone of the kick drum.", "plain_english": "It is the moment the kick pedal's beater hits the bass drum skin. A hard plastic beater gives a sharp click, while a soft felt one gives a rounder thump.", "purpose_function": "It shapes the kick's attack and definition, so the choice of beater and how hard it strikes controls how much the kick cuts through a mix.", "practical_application": "To get a kick to punch through a loud band, an engineer or drummer switches to a harder beater and often adds a click pad at the impact point.", "category": "Drum component", "related_terms": ["Batter head", "Kick drum", "Bearing-edge problem", "Drum tuning", "Beater", "Bass subgroup"], "common_mistakes": ["Expecting more click from EQ alone when a softer beater is limiting the attack at the source", "Letting the beater rest buried in the head, which deadens the impact and tone", "Ignoring a worn beater that leaves an uneven or dull impact on the head"], "scenario_contexts": ["Swapping to a plastic beater so the kick clicks through a heavy guitar mix", "Adding a felt impact pad to soften a harsh beater sound for a jazz session", "Adjusting beater force and pedal tension to even out the kick's attack"]}, "076433b0-b0b2-4a6f-9a2d-7665f87be505": {"definition": "Techniques for managing the natural resonant modes of an acoustic instrument's body—such as an acoustic guitar or double bass—during recording, using microphone placement, damping, or EQ to tame boomy or boxy frequencies while keeping the instrument's character.", "plain_english": "It means taming the boomy sounds that an instrument's hollow body makes when you record it. You move the mic or dip a frequency so it does not sound boxy.", "purpose_function": "It keeps one or two strong body resonances from dominating the recorded tone, so the instrument sounds balanced rather than boomy or honky in the mix.", "practical_application": "When an acoustic guitar sounds boomy near the sound hole, an engineer moves the mic toward the neck or dips the offending low-mid frequency to calm the body resonance.", "category": "Recording technique", "related_terms": ["Microphone placement", "Proximity effect", "Parametric EQ", "Bow-noise control", "Sound hole", "Acoustic guitar"], "common_mistakes": ["Micing straight at the sound hole and then fighting the boom with heavy EQ", "Cutting so much low-mid that the instrument loses its natural body and warmth", "Confusing a room resonance with the instrument's own body resonance and treating the wrong one"], "scenario_contexts": ["Moving an acoustic guitar mic off the sound hole to reduce a boomy body resonance", "Dipping a narrow low-mid band on a double bass to control a boxy note", "Placing a small damper inside a resonant instrument to tame a ringing mode"]}, "411febe6-0d68-4214-9563-f5f44639f197": {"definition": "Techniques for reducing the scratchy, scraping bow-on-string noise captured when recording bowed string instruments, using microphone placement and distance, bow technique, rosin management, and selective high-frequency EQ.", "plain_english": "It means cutting down the scratchy sound a bow makes as it drags across the strings. You back the mic off a little or ease off the harsh high frequencies.", "purpose_function": "It keeps unwanted bow scrape from masking the pure tone of a violin, viola, cello, or bass, so the recorded string sound stays smooth and musical.", "practical_application": "When a close-miked violin sounds scratchy, an engineer moves the mic back and slightly off the bow contact point, then gently tames the harsh highs.", "category": "Recording technique", "related_terms": ["Microphone placement", "Body resonance control", "De-esser", "High-frequency EQ", "Rosin", "Close miking"], "common_mistakes": ["Placing the mic too close and right over the bow, which exaggerates the scrape", "Using too much rosin, so the bow grabs the string and adds noise", "Cutting the highs so hard that the strings lose their air and bite"], "scenario_contexts": ["Backing a mic away from a close-miked cello to reduce bow scrape", "Guiding a player to lighten bow pressure during a quiet passage to cut noise", "Taming harsh bow noise on a violin overdub with gentle high-frequency EQ"]}, "8174bbc2-baed-413f-b5b8-b1e8a3bdfef3": {"definition": "The practice of recording a part twice (double-tracking) and keeping both takes panned to the center of the stereo image, so the two performances reinforce one another to thicken and strengthen a central element such as a lead vocal or main line.", "plain_english": "It means playing or singing the same part twice and putting both takes in the middle. The two copies stack up to make that part sound fuller and stronger.", "purpose_function": "It thickens and reinforces a central part without spreading it wide, so a lead vocal or main line sits solid in the middle of the mix.", "practical_application": "To beef up a lead vocal, an engineer records a second identical take and keeps both centered so the vocal sounds fuller.", "category": "Arrangement technique", "related_terms": ["Double-tracking", "Stereo image", "Panning", "Centered harmony", "Center guitar layer", "Layering"], "common_mistakes": ["Thinking a copy-and-paste of one take gives the same thickening as a real second performance", "Spreading the two takes wide when the goal is a solid center", "Doubling a part that is already busy, which muddies the middle of the mix"], "scenario_contexts": ["Double-tracking a lead vocal and keeping both takes centered for a fuller sound", "Stacking two center guitar takes to strengthen a main riff", "Reinforcing a synth bass line by centering a doubled take"]}, "4c78bc54-9dfd-4774-a934-0f58e27cf796": {"definition": "A guitar part placed in the center of the stereo image—often a rhythm or lead layer—that anchors the arrangement while other guitars are panned left and right for width.", "plain_english": "It is a guitar part set in the middle of the mix, not to the left or right. It gives the song a solid guitar center while other guitars sit out to the sides.", "purpose_function": "It anchors the guitar arrangement in the middle so the song has a strong central foundation, leaving the sides open for panned parts.", "practical_application": "When layering guitars, an engineer keeps the main rhythm part centered and pans the doubles left and right to build width around it.", "category": "Arrangement technique", "related_terms": ["Panning", "Stereo image", "Double-tracking", "Center doubling", "Rhythm guitar", "Layering"], "common_mistakes": ["Centering several loud guitars at once, which crowds the middle with the vocal and bass", "Forgetting to pan the supporting guitars, so the whole guitar section stacks in the center", "Confusing a single centered layer with a fully mono guitar mix"], "scenario_contexts": ["Keeping a main rhythm guitar centered while panning its doubles wide", "Placing a lead guitar in the center to sit with the vocal", "Anchoring an acoustic layer in the middle of a dense rock mix"]}, "76d64342-5def-47bc-b56d-566d04a0ee86": {"definition": "Harmony vocal or instrumental parts placed in the center of the stereo image rather than panned to the sides, keeping the supporting harmony aligned directly with the lead.", "plain_english": "It means putting harmony parts in the middle of the mix instead of out to the sides. The harmony then lines up right behind the lead voice.", "purpose_function": "It keeps harmony parts tight against the lead so they support it directly, useful when a solid central blend matters more than stereo width.", "practical_application": "For a close vocal blend, an engineer keeps the harmony stacks centered under the lead rather than spreading them left and right.", "category": "Arrangement technique", "related_terms": ["Harmony", "Panning", "Stereo image", "Center doubling", "Backing vocals", "Choir blend"], "common_mistakes": ["Piling many centered harmonies onto the lead, which clutters the middle", "Assuming centered harmony always sounds better than panned harmony", "Letting a centered harmony fight the lead for the same space"], "scenario_contexts": ["Keeping a two-part harmony centered under a lead vocal for a tight blend", "Centering a background vocal to thicken the lead without adding width", "Placing a harmony line in the middle so it stays glued to the melody"]}, "78a3fbde-8ce3-470d-bbac-ecdd68a1114a": {"definition": "The sense of room and space captured or added around a recorded choir—from natural room reflections and reverberation picked up by distant or ambient microphones, or from added reverb—that conveys the acoustic environment the ensemble sings in.", "plain_english": "It is the roomy, echoing sound around a choir. It comes from the real space the choir sings in, or from added reverb, and it makes the singing feel like a live hall.", "purpose_function": "It places the choir in a believable space and adds a sense of size and blend, so the voices sound like a unified group in a room rather than dry and close.", "practical_application": "To capture choir ambience, an engineer sets a pair of room mics back from the group, or adds hall reverb to the close mics in the mix.", "category": "Recording technique", "related_terms": ["Room microphone", "Reverberation", "Ambient miking", "Choir depth", "Choir blend", "Spaced pair"], "common_mistakes": ["Placing ambient mics too far back, so the choir sounds distant and washed out", "Adding heavy reverb to tracks that are already ambient, which smears the words", "Ignoring the room's own sound and expecting reverb plug-ins to fix a dead space"], "scenario_contexts": ["Setting room mics in a church to capture the natural ambience of a choir", "Adding hall reverb to close-miked choir tracks to restore a sense of space", "Balancing close and ambient choir mics for the right amount of room sound"]}, "abdb4ecc-b944-4812-a860-c934e15ee2ae": {"definition": "The use of mix automation—recorded moves of level, mute, panning, or plug-in settings over time—applied to choir tracks so their balance and processing follow the changing dynamics of an arrangement.", "plain_english": "It means setting the mixer to change the choir's volume and settings on its own as the song plays. The moves are saved once and then repeat exactly every time.", "purpose_function": "It lets an engineer ride the choir's level and effects through a song—up in the choruses, down under a solo—without redoing fader moves by hand on every pass.", "practical_application": "An engineer draws fader automation so the choir swells in the final chorus and drops back during the verses.", "category": "Mix automation", "related_terms": ["Automation", "Fader ride", "Mute automation", "Choir compression", "Subgroup", "Mixdown"], "common_mistakes": ["Writing jumpy automation moves that cause audible level steps", "Automating each choir channel when one subgroup fader would do the job", "Forgetting that a later manual fader move can overwrite the written automation"], "scenario_contexts": ["Automating a choir swell into the last chorus of a song", "Pulling the choir down automatically under a lead vocal line", "Muting the choir bus automatically in sections where it does not sing"]}, "084b1342-fde2-4bd4-8546-7365cd545e49": {"definition": "The degree to which individual voices in a choir merge into a single, unified sound rather than standing out separately, shaped by the singers' balance and tuning and by recording choices such as microphone type and distance.", "plain_english": "It is how well the singers' voices melt together into one smooth sound. Good blend means you hear a single choir, not a bunch of separate voices.", "purpose_function": "It creates the impression of one cohesive ensemble, so the choir reads as a unified section instead of a set of competing soloists.", "practical_application": "To improve blend, an engineer backs the mics off a little and lets the singers balance themselves in the room before capturing them.", "category": "Recording technique", "related_terms": ["Choir ambience", "Choir depth", "Ensemble balance", "Spaced pair", "Centered harmony", "Room microphone"], "common_mistakes": ["Close-miking individual singers, which breaks up the natural blend", "Expecting the mix to fix a blend the choir never achieved in the room", "Boosting one section so hard that it pulls out of the ensemble"], "scenario_contexts": ["Using a distant stereo pair so a choir blends into one sound", "Arranging singers by section to improve blend before recording", "Balancing the choir sections so no single part sticks out"]}, "11222dfb-f7d7-415e-999b-c4fc0927aa76": {"definition": "The application of dynamic-range compression to a choir recording, reducing the difference between its loudest and softest passages so the ensemble sits at a steadier level in the mix.", "plain_english": "It means using a compressor to even out how loud a choir gets. It gently turns down the loudest parts so soft and loud passages stay closer in volume.", "purpose_function": "It controls the wide dynamics of a choir so quiet passages stay audible and loud swells do not jump out, helping the choir sit consistently in a mix.", "practical_application": "An engineer puts gentle bus compression on the choir subgroup to smooth its dynamics before setting its level in the mix.", "category": "Dynamics processing", "related_terms": ["Compression", "Bus compression", "Choir automation", "Threshold", "Makeup gain", "Subgroup"], "common_mistakes": ["Using a fast, heavy setting that pumps and pulls up room noise between phrases", "Squashing the choir so hard it loses its natural swells and expression", "Compressing on the channels and again on the bus until the sound is lifeless"], "scenario_contexts": ["Applying gentle compression to a choir bus to even out its dynamics", "Taming loud choral swells so they do not overpower a lead vocal", "Keeping soft choir passages audible in a dense mix"]}, "604cf70b-e448-47b7-ae0f-616246b68ea4": {"definition": "The use of a de-esser—a frequency-selective compressor targeting the sibilant range—to reduce harsh \"s,\" \"sh,\" and \"t\" sounds on a choir recording, where many voices singing consonants together can build up exaggerated sibilance.", "plain_english": "It means taming the harsh, hissy \"s\" sounds in a choir recording. A de-esser turns down just those sharp sounds when many singers hit an \"s\" at once.", "purpose_function": "It softens exaggerated sibilance that piles up when a whole choir sings consonants together, keeping the top end smooth without dulling the overall tone.", "practical_application": "When a choir's \"s\" sounds turn harsh, an engineer inserts a de-esser tuned to the sibilant range and eases the level of those peaks.", "category": "Dynamics processing", "related_terms": ["De-esser", "Sibilance", "Compression", "Choir compression", "High-frequency EQ", "Choir blend"], "common_mistakes": ["Setting the de-esser too strong, which gives the choir a lisping, dull sound", "Targeting the wrong frequency, so the sibilance is not actually reduced", "Cutting all the highs with broad EQ instead of de-essing only the harsh peaks"], "scenario_contexts": ["De-essing a close-miked choir where the \"s\" sounds have piled up", "Smoothing harsh consonants on a choir bus in a bright mix", "Taming sibilance on layered choir stacks before adding reverb"]}, "847cb51c-d05f-4e6e-bbb3-205ad69355a7": {"definition": "The sense of front-to-back distance and layering in a recorded choir, created by the placement of singers and microphones and by cues such as level, ambience, and reflection that make some voices seem nearer and others farther away.", "plain_english": "It is the feeling of near and far in a choir recording, the sense that some voices sit closer and some sit deeper back. It makes the choir sound three-dimensional instead of flat.", "purpose_function": "It gives a choir a realistic three-dimensional space, so the ensemble sounds layered from front to back rather than pinned to one flat plane.", "practical_application": "An engineer builds depth by blending close mics with a distant ambient pair, letting reflections and level place the sections at different distances.", "category": "Recording technique", "related_terms": ["Choir ambience", "Reverberation", "Ambient miking", "Choir blend", "Stereo image", "Room microphone"], "common_mistakes": ["Using only close mics, which flattens the choir with no sense of distance", "Adding reverb but no level or ambience cues, so the depth still sounds fake", "Placing every section at the same distance, which loses front-to-back layering"], "scenario_contexts": ["Blending close and distant mics to give a choir front-to-back depth", "Using room reflections to place back rows farther away than the front", "Layering ambience so a choir sounds three-dimensional in a mix"]}, "8ef6df9d-d1c7-48ba-9038-7c39a2136c14": {"definition": "The application of frequency-selective gain (EQ) to a recorded or amplified choir to control tonal balance, typically removing low-frequency rumble and boominess, taming harsh upper-mids, and adding presence or air so massed voices sit clearly in a mix.", "plain_english": "Using an equalizer to shape the sound of a choir. You cut or boost certain pitches so the group of singers sounds clear and not muddy.", "purpose_function": "It corrects tonal problems caused by the room and the microphones, and helps the massed voices blend and stay easy to understand within an arrangement.", "practical_application": "An engineer rolls off low rumble with a high-pass filter, dips a few decibels around 200-400 Hz to cut mud, then adds a gentle high shelf for air on the choir bus.", "category": "Signal processing", "related_terms": ["Choir mixing", "Choir hall reverb", "High-pass filter", "Equalization", "Presence", "Choir stereo image"], "common_mistakes": ["Cutting so aggressively that the choir sounds thin and unnatural", "Boosting instead of cutting to fix mud, which just adds harshness", "EQing each microphone in solo rather than in the full mix context"], "scenario_contexts": ["Removing low-end rumble from a choir recorded in a resonant church", "Reducing boxiness before printing a choral stem", "Adding gentle air so massed voices cut through a full band"]}, "082e93fb-00fc-4f15-95b5-8a2088b80824": {"definition": "A reverberation effect, natural or artificial, that places a choir in the acoustic of a large hall or church, adding the long, smooth decay and sense of space listeners associate with those rooms.", "plain_english": "A reverb effect that makes a choir sound like it is singing in a big hall or church. It adds echo and a sense of open space around the voices.", "purpose_function": "It gives massed voices a natural, blended sense of space and depth, matching the grand acoustic that audiences expect from choral music.", "practical_application": "An engineer sends the choir bus to a hall reverb with a long decay time and blends it under the dry signal to add depth without washing out the words.", "category": "Signal processing", "related_terms": ["Choir pre-delay", "Choir mixing", "Choir room microphones", "Reverb", "Decay time", "Choir stereo image"], "common_mistakes": ["Using so much reverb that the words become hard to understand", "Choosing a bright plate reverb that clashes with a natural choral sound", "Adding reverb with no pre-delay, which blurs the attack of the voices"], "scenario_contexts": ["Recreating a cathedral ambience for a choir tracked in a dry studio", "Adding depth to a gospel choir in a pop production", "Matching a spot-mic-heavy recording to a natural hall sound"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"3030ec0d-630c-47e3-ab2f-ffaadfd4a253": {"definition": "The process of balancing, processing, and placing the multiple microphone signals of a choir (main pair, spot, and room mics) into a coherent stereo image with appropriate level, tone, dynamics, and reverb.", "plain_english": "Blending all the microphone signals from a choir into one good-sounding mix. You set the levels, tone, and space so the whole group sounds balanced.", "purpose_function": "It turns separate microphone feeds into a unified, natural-sounding choir that sits correctly within a recording or live mix.", "practical_application": "The engineer sets the main pair as the foundation, adds spot mics for clarity, blends room mics for depth, then applies EQ and reverb across the choir bus.", "category": "Mixing", "related_terms": ["Choir equalization", "Choir hall reverb", "Choir spot microphones", "Choir room microphones", "Choir stereo image", "Bus"], "common_mistakes": ["Pushing spot mics too loud so the natural blend of the main pair is lost", "Ignoring the phase relationships between main, spot, and room mics", "Adding effects before setting a solid level balance"], "scenario_contexts": ["Balancing a 40-piece choir recorded with main, spot, and room mics", "Blending a studio choir stack behind a lead vocal", "Setting up a live worship mix with choir and band"]}, "9af63c5f-b3e6-4621-8031-9aa3ef1c1173": {"definition": "A pair of widely spaced microphones, usually omnidirectional, placed outside the main stereo pair when recording a choir, used to widen the stereo image and capture extra hall ambience and low-frequency warmth.", "plain_english": "Extra wide microphones set up to the far left and right of a choir. They make the recording sound wider and add more of the room's natural sound.", "purpose_function": "They broaden the stereo width and add spaciousness that a central main pair alone cannot capture, filling out the edges of the sound stage.", "practical_application": "When the main pair sounds too narrow over a wide choir, the engineer adds omni outriggers a few meters out to each side and blends them under the mains.", "category": "Microphone technique", "related_terms": ["Choir room microphones", "Choir stereo image", "Decca tree", "Omnidirectional microphone", "Spaced pair", "Choir mixing"], "common_mistakes": ["Spacing them so wide that the center of the choir sounds hollow", "Forgetting to check mono compatibility, which can cause phase problems", "Using directional mics instead of omnis and losing the intended warmth"], "scenario_contexts": ["Widening a Decca tree recording of a large choir", "Filling out the sides of a wide choir in a concert hall", "Adding warmth and width to an orchestral choir session"]}, "a740480f-f71b-459b-87d5-4aaf2ad30ec1": {"definition": "The short time gap, typically about 10-60 ms, set before a choir's reverb tail begins, separating the direct sound of the voices from the onset of reverberation to preserve clarity and intelligibility.", "plain_english": "A tiny pause before the echo on a choir starts. This short gap keeps the words clear before the reverb fills in around the voices.", "purpose_function": "It keeps sung words easy to understand by letting the dry voices be heard first, while still adding the depth and space of reverb.", "practical_application": "The engineer sets pre-delay around 20-40 ms on the choir reverb so consonants stay crisp and the choir does not sound washed out.", "category": "Signal processing", "related_terms": ["Choir hall reverb", "Reverb", "Decay time", "Choir mixing", "Intelligibility", "Choir equalization"], "common_mistakes": ["Setting pre-delay to zero, which smears the words", "Using an extremely long pre-delay that sounds like a slap echo", "Not matching the pre-delay to the song's tempo and phrasing"], "scenario_contexts": ["Keeping a large choir intelligible inside a long hall reverb", "Separating voices from reverb in a dense pop production", "Tuning the reverb onset to a slow ballad's tempo"]}, "e107d573-537d-474f-b1a0-bb425c8269be": {"definition": "Microphones placed at a distance from a choir to capture the reflected sound and reverberation of the performance space rather than the direct sound of the voices, adding natural ambience and depth.", "plain_english": "Microphones placed far back from a choir to record the sound of the room. They pick up the natural echo and space instead of the close-up voices.", "purpose_function": "They capture the acoustic character of the venue so a mix has real depth and a natural sense of space around the choir.", "practical_application": "The engineer places a spaced pair near the back of the hall and blends them under the main and spot mics to add air and ambience.", "category": "Microphone technique", "related_terms": ["Choir outriggers", "Choir spot microphones", "Choir hall reverb", "Ambience", "Spaced pair", "Choir mixing"], "common_mistakes": ["Placing them too close, so they capture direct sound instead of ambience", "Blending them too loud and washing out the clarity of the mix", "Ignoring phase alignment with the main and spot mics"], "scenario_contexts": ["Capturing the natural ambience of a cathedral choir recording", "Adding depth to a close-miked studio choir", "Providing a wide ambient bed for a live album"]}, "cfba6c4e-c591-4ede-8cdf-b0c6cf067a35": {"definition": "Close accent microphones aimed at specific sections or soloists within a choir, such as sopranos, altos, tenors, or basses, used to reinforce clarity and balance that the main pair alone does not provide.", "plain_english": "Close-up microphones pointed at one part of a choir, like the sopranos or basses. They add clarity to a section that the main microphones miss.", "purpose_function": "They reinforce weak or distant sections and improve intelligibility, while the main pair still provides the overall blend.", "practical_application": "The engineer adds a spot mic over the tenors when they sit too far back to be heard, mixing it just under the main pair for balance.", "category": "Microphone technique", "related_terms": ["Choir room microphones", "Choir outriggers", "Choir mixing", "Accent microphone", "Choir stereo image", "Phase"], "common_mistakes": ["Mixing spot mics too loud so a section sounds unnaturally close", "Ignoring the time offset (phase) between the spot and main mics", "Using them as the main sound instead of as reinforcement"], "scenario_contexts": ["Reinforcing a distant tenor section in a large choir", "Adding clarity to a soloist stepping out of the choir", "Balancing a choir section that sits behind an orchestra"]}, "c1960d80-ffb5-4356-ae68-e71b8ca4fc16": {"definition": "A group of layered vocal recordings, with multiple takes, harmonies, and octaves overdubbed and combined, used to build the thick, massed sound of a choir, often from only a few singers.", "plain_english": "Recording the same voices many times and layering them to sound like a full choir. Stacking lots of takes makes a few singers sound like a big group.", "purpose_function": "It creates a large, lush choir texture in a production without hiring a full choir, adding size and richness to an arrangement.", "practical_application": "A producer double-tracks a singer across several harmony parts and octaves, then pans the layers wide to build a choir stack behind the lead vocal.", "category": "Vocal production", "related_terms": ["Choir mixing", "Choir stereo image", "Double-tracking", "Overdub", "Harmony", "Panning"], "common_mistakes": ["Layering identical takes so it sounds like a chorus effect rather than many singers", "Not varying pitch, timing, and vowels between layers, so it sounds fake", "Stacking so many layers that the mix becomes cluttered and loses focus"], "scenario_contexts": ["Building a full gospel choir sound from one session singer", "Thickening a chorus hook with layered harmonies", "Creating a wall of backing vocals in a pop production"]}, "4e877b26-6533-4aaf-9117-29faf858ed2f": {"definition": "The perceived left-to-right placement, width, and depth of a choir within a stereo mix, determined by microphone technique, panning, and the balance of main, spot, and room signals.", "plain_english": "How wide a choir sounds across your left and right speakers. A good stereo image spreads the singers naturally instead of bunching them in the middle.", "purpose_function": "It places and spreads the choir believably across the sound stage so listeners perceive width, position, and depth.", "practical_application": "The engineer relies on the main pair for the spread, pans spot mics to match each section's real position, then checks that the mix still works in mono.", "category": "Stereo imaging", "related_terms": ["Choir outriggers", "Choir spot microphones", "Choir mixing", "Panning", "Mono compatibility", "Spaced pair"], "common_mistakes": ["Panning everything to the center, which makes the choir sound narrow", "Creating such a wide image that it collapses in mono", "Placing spot mics that do not match the singers' real positions"], "scenario_contexts": ["Spreading a choir naturally across a stereo mix", "Checking mono compatibility of a wide choral recording before broadcast", "Positioning choir sections to match their layout on stage"]}, "07e57426-3e42-4e26-a4a4-d9e68c1f7e93": {"definition": "The perceived left-to-right spatial spread of a choir within a stereo image, set by microphone technique, singer placement, and the panning of section spot mics.", "plain_english": "How wide a recorded choir sounds from your left speaker to your right. A wide choir seems to fill the room; a narrow one sounds squeezed into the middle.", "purpose_function": "Width spreads the voice sections across the stereo field so listeners can sense the size and layout of the group, adding a feeling of space.", "practical_application": "An engineer sets choir width by choosing a spaced or coincident mic pair and by panning section spot mics, widening or narrowing the group to fit the mix.", "category": "Stereo Imaging", "related_terms": ["Choral imaging", "Choral realism", "Stereo width", "Panning", "Spaced pair"], "common_mistakes": ["Panning section mics too hard, leaving a hole in the middle of the choir", "Assuming wider always sounds better, when too much width can smear the blend", "Confusing width with depth; front-to-back space is depth, not width"], "scenario_contexts": ["Recording a concert choir with a spaced pair to capture a wide, natural spread", "Narrowing choir width so the group sits behind a solo vocalist", "Setting up a main pair and outriggers over a choir in a hall"]}, "ea4dc8b4-4d7d-462b-8402-90c2a92da059": {"definition": "The way choral singers attack, sustain, and release notes and consonants, such as legato, staccato, or marcato, which shapes how connected or detached the sung line is.", "plain_english": "How a choir starts, holds, and ends each note and word. Smooth singing joins notes together; crisp singing separates them, like gliding versus tapping.", "purpose_function": "Articulation gives a choral line its rhythmic clarity and musical character, letting a group phrase together and match the style of the piece.", "practical_application": "A recordist captures articulation by miking for consonant detail and clean transients, while the director marks legato or staccato passages to unify the ensemble.", "category": "Vocal Technique", "related_terms": ["Choral diction clarity", "Choral dynamics", "Phrasing", "Legato", "Staccato"], "common_mistakes": ["Smearing crisp articulation with heavy reverb", "Confusing articulation with dynamics; one is note shape, the other is loudness", "Miking so far back that consonant attacks get lost"], "scenario_contexts": ["Capturing crisp consonant attacks in a rhythmic choral passage", "Recording a legato hymn where notes must flow smoothly", "Adjusting mic distance to keep staccato singing tight and clear"]}, "1edab665-e576-46d0-93d7-ac0e6b4ef209": {"definition": "The amount of high-frequency energy and treble presence in a choir's sound, which makes voices sound clear and open rather than dark or muffled.", "plain_english": "How bright or crisp a choir sounds in its high tones. A bright choir sounds clear and sparkly; a dull one sounds soft and covered.", "purpose_function": "Brightness helps a choir cut through a mix and keeps words and overtones clear, though too much can sound harsh or sibilant.", "practical_application": "An engineer shapes brightness with mic choice, mic placement, and EQ, boosting highs for air or cutting them to tame harshness.", "category": "Tonal Balance", "related_terms": ["Choral diction clarity", "Equalization", "Sibilance", "Presence", "Choral recording mix"], "common_mistakes": ["Boosting high EQ too much, which makes sopranos harsh and sibilant", "Blaming a dull choir on the mic when the room or placement is the real cause", "Confusing brightness with loudness"], "scenario_contexts": ["Adding a gentle high shelf to open up a choir recorded in a dark hall", "Choosing a condenser mic with an airy top end for a chamber choir", "Cutting harsh highs when close-miking sopranos"]}, "ebd2d879-9a3f-41a8-ab2a-ba878c85fde9": {"definition": "How thick or full a choral texture sounds, set by the number of voices, how many notes are stacked, and how the parts are voiced and doubled.", "plain_english": "How full and thick a choir sounds. Many singers on many notes feel dense and rich; a few voices on simple lines feel thin and open.", "purpose_function": "Density controls the weight and richness of a choral arrangement, helping a section feel powerful or leave room for other parts.", "practical_application": "An arranger adjusts density by adding or removing voice parts and doublings, while an engineer keeps a dense choir clear so parts do not turn to mush.", "category": "Arrangement Texture", "related_terms": ["Choral recording mix", "Choral dynamics", "Voicing", "Doubling", "Texture"], "common_mistakes": ["Stacking too many parts so the texture turns muddy and words vanish", "Thinking more singers always sounds fuller, when spacing and voicing matter more", "Ignoring low-mid buildup when many voices overlap"], "scenario_contexts": ["Thinning a dense choral pad so a lead vocal stays clear", "Arranging a big final chorus with divided parts for maximum fullness", "Managing low-mid mud when a large choir sings close harmony"]}, "2a0fd15c-ac32-4264-a779-4e506c43f6a5": {"definition": "How clearly the words and consonants of a choir can be understood, driven by the singers' enunciation and by mic and mix choices that preserve consonant detail.", "plain_english": "How easy it is to understand the words a choir is singing. Good diction means you can hear each word clearly, not just a wash of sound.", "purpose_function": "Clear diction lets listeners follow the text and gives the choir crisp timing, which matters most in sacred and lyric-driven music.", "practical_application": "An engineer protects diction by miking for consonants and avoiding heavy reverb, while the director drills crisp starts and ends of words.", "category": "Vocal Intelligibility", "related_terms": ["Choral brightness", "Choral articulation", "Intelligibility", "Sibilance", "Reverb"], "common_mistakes": ["Drowning the words in reverb until the text turns mushy", "Cutting too much high EQ, which softens consonants", "Assuming diction is only the singers' job, not the engineer's"], "scenario_contexts": ["Reducing reverb send so a choir's lyrics stay clear in a mix", "Recording a text-heavy anthem where every word must be understood", "Adding slight presence EQ to bring out consonants"]}, "a860d887-7030-47b0-bde7-3190daa57876": {"definition": "The range and control of loud and soft levels in a choir's performance, from quiet pianissimo passages to full fortissimo, including swells and accents.", "plain_english": "How loud or soft a choir sings, and how it moves between the two. Dynamics are the difference between a gentle whisper and a full, powerful sound.", "purpose_function": "Dynamics give choral music its emotion and shape, and they set the recording levels an engineer must capture without clipping or noise.", "practical_application": "An engineer sets gain and watches headroom for loud peaks, and may use gentle compression so soft and loud passages both sit well in the mix.", "category": "Vocal Technique", "related_terms": ["Choral density", "Headroom", "Compression", "Gain staging", "Choral recording mix"], "common_mistakes": ["Setting gain for soft parts, then clipping when the choir hits full volume", "Over-compressing until the music loses its natural swells", "Forgetting to leave headroom for loud fortissimo peaks"], "scenario_contexts": ["Setting record levels with headroom for a choir that swells from soft to loud", "Riding faders to keep a quiet passage audible in a mix", "Using light compression to control a wide dynamic range"]}, "d5fe5e46-030c-41e7-a3a7-427b8391cde2": {"definition": "The stereo placement and spatial layout of a choir in a recording, so listeners can locate each voice section and sense the group's size and position.", "plain_english": "Where each part of a choir seems to sit between your speakers, left to right and near to far. Good imaging lets you point to where the basses are.", "purpose_function": "Imaging recreates the real layout of a choir, giving a mix a believable sense of space and helping voice sections stay separate and clear.", "practical_application": "An engineer builds imaging with a main stereo mic pair and panned spot mics, arranging sections across the field to match how the choir stood.", "category": "Stereo Imaging", "related_terms": ["Choir width", "Choral realism", "Panning", "Stereo width", "Spaced pair"], "common_mistakes": ["Panning spot mics so hard that sections detach from the main pair", "Confusing imaging (left-right) with depth (front-back)", "Ignoring phase between mics, which smears the stereo picture"], "scenario_contexts": ["Placing a main pair over a choir to capture a natural stereo image", "Panning section mics to match the choir's stage layout", "Checking mono compatibility so imaging does not collapse"]}, "e9cf4194-ae8c-4279-8285-133bdfafd25f": {"definition": "How convincingly a choral recording reproduces the natural sound of a live choir, including its tone, blend, space, and depth.", "plain_english": "How much a recording sounds like a real choir in the room with you. High realism feels live and natural, not thin or fake.", "purpose_function": "Realism is the goal of many choral recordings, keeping the blend and hall sound so the listener feels present at the performance.", "practical_application": "An engineer chases realism with natural mic techniques, good room capture, and restrained processing that keeps the choir sounding true to life.", "category": "Sound Quality", "related_terms": ["Choral imaging", "Choir width", "Room acoustics", "Reverb", "Blend"], "common_mistakes": ["Over-processing until the choir sounds artificial", "Adding fake reverb that fights the real hall sound", "Close-miking so tightly that the natural blend is lost"], "scenario_contexts": ["Recording a choir in a fine hall to capture its natural sound", "Choosing gentle processing to keep a choir sounding lifelike", "Blending room mics with a main pair for a realistic sense of space"]}, "7508a078-aadf-453f-b1ef-d5ef37a37cb5": {"definition": "The balanced combination of a choir's captured tracks, such as the main pair, spot mics, and room mics, blended in level, EQ, panning, and reverb into a finished stereo recording.", "plain_english": "The final blend of all the mics used to record a choir, set so the group sounds balanced and clear. It is like joining many photos into one good picture.", "purpose_function": "The mix turns separate mic feeds into one cohesive choral sound, controlling tone, space, and level for the listener.", "practical_application": "An engineer builds the mix around the main pair, adds spot mics for detail and room mics for space, then balances levels, EQ, and reverb.", "category": "Mixing", "related_terms": ["Choral imaging", "Choral density", "Choir width", "Reverb", "Equalization"], "common_mistakes": ["Leaning on spot mics so hard the main-pair blend is lost", "Adding so much reverb the words and detail wash out", "Mixing too bright, making sopranos harsh"], "scenario_contexts": ["Balancing main and spot mics into a finished choir recording", "Blending room mics for a sense of space in a choral mix", "Setting reverb and EQ so a choir sounds cohesive"]}, "cdac5a21-33bf-4285-a484-ceeb8d829546": {"definition": "The management of unwanted sympathetic resonances and room-driven frequency build-up in a recorded or reinforced choir, so sustained massed voices do not accumulate boomy or ringing tones. It is achieved through microphone placement, room treatment, and narrow-band equalization on the combined vocal signal.", "plain_english": "A choir singing together can make some notes ring out too strongly in a room. Controlling that means taming those boomy or ringing tones so the voices stay clear.", "purpose_function": "It keeps a massed vocal sound clean and easy to understand by stopping certain frequencies from building up and hiding the words.", "practical_application": "An engineer uses careful mic placement and gentle EQ cuts to remove ringing low-mid frequencies when tracking a choir in a live room.", "category": "Choral Recording", "related_terms": ["Choral warmth", "Choral transparency", "Room acoustics", "Equalization", "Reverberation"], "common_mistakes": ["Cutting too aggressively and making the choir sound thin and lifeless", "Blaming the microphones for boom when the room is the real cause", "Using one narrow EQ notch and missing that the resonance shifts with the note being sung"], "scenario_contexts": ["Tracking a church choir in a reverberant sanctuary", "Taming low-mid build-up on a massed backing-vocal stack", "Cleaning up a live choral feed before it reaches the main PA"]}, "56bdeb8e-bfa5-4c59-b7d5-f1cd45491ff3": {"definition": "The physical arrangement and distance between singers in a choir, together with the matching microphone spacing used to capture them, which shape blend, width, and stereo image. Correct spacing merges individual voices into a unified section while preserving depth.", "plain_english": "Choral spacing is how far apart the singers stand and how far apart the mics are set. Getting it right helps the voices blend into one smooth sound instead of clumps.", "purpose_function": "It controls how well the voices blend and how wide the choir sounds, so the section reads as one instrument rather than separate people.", "practical_application": "When setting up, an engineer positions a spaced or coincident mic pair at a distance that matches how the choir is arranged on the risers.", "category": "Choral Recording", "related_terms": ["Choral resonance control", "Choral transparency", "Stereo miking", "Blend", "Microphone placement"], "common_mistakes": ["Placing mics too close so single voices stick out of the blend", "Ignoring riser height so the back rows sound distant", "Assuming wider mic spacing always means better blend"], "scenario_contexts": ["Arranging singers on risers for a studio choral session", "Choosing spaced-pair distance for a large ensemble", "Balancing front and back rows of a school choir"]}, "81127c0d-8df7-410c-a8da-d11d19801de5": {"definition": "The practice of retaining the natural reverberant decay, or tail, of a choir's sustained notes when editing, gating, or processing, so sung phrases end with their full ambient bloom rather than being cut short. It treats the room's decay as part of the choral character.", "plain_english": "When a choir holds a note and stops, the sound keeps ringing in the room for a moment. Preserving the tail means keeping that natural fade instead of chopping it off.", "purpose_function": "It keeps the choir sounding natural and connected to its space by not cutting off the reverb that gives the sound its bloom.", "practical_application": "An engineer sets long gate release times or edits crossfades carefully so the decay after each phrase is not clipped.", "category": "Choral Recording", "related_terms": ["Reverberation", "Noise gate", "Choral warmth", "Decay time", "Crossfade"], "common_mistakes": ["Setting a noise gate's release too short so the tails get chopped", "Editing phrase ends with hard cuts instead of crossfades", "Mistaking the natural room tail for unwanted noise and removing it"], "scenario_contexts": ["Gating a live choral mic without killing the decay", "Comping choral takes while keeping phrase endings smooth", "Preserving hall ambience on a classical choir recording"]}, "6c7b9995-5d93-48c6-96a0-53e229c58036": {"definition": "The quality of a choral recording or mix in which individual vocal lines and words stay clear and distinct within the massed sound, without muddiness or masking. It reflects good intelligibility and separation across the section.", "plain_english": "Transparency means you can still hear the words and the different parts clearly, even with many voices singing at once. The sound is clear, not muddy.", "purpose_function": "It lets listeners follow the lyrics and harmony parts, which is why clarity is prized when capturing and mixing a choir.", "practical_application": "An engineer improves transparency with careful mic choice, gentle low-mid EQ, and controlled reverb so the choir stays clear.", "category": "Choral Recording", "related_terms": ["Choral resonance control", "Intelligibility", "Equalization", "Masking", "Choral spacing"], "common_mistakes": ["Adding too much reverb and washing out the words", "Boosting low-mids until the choir turns muddy", "Over-compressing so the separate voices blur together"], "scenario_contexts": ["Mixing a choir so the lyrics stay intelligible", "Cleaning up a muddy massed-vocal recording", "Balancing soprano and bass lines in a dense arrangement"]}, "5de58a69-ebe2-4514-972b-39a37b3c7f13": {"definition": "A tonal quality in choral sound marked by full, rich low-mid content and smooth high frequencies, giving the voices a rounded, pleasing body. It is shaped by the room, the microphone choice, and equalization.", "plain_english": "Warmth is a full, rounded feel in the choir's sound, coming mostly from the lower and middle notes. It makes the voices feel cosy rather than thin or harsh.", "purpose_function": "It gives a choir a rich, inviting body that flatters massed voices, which is why engineers aim for it while capturing and mixing.", "practical_application": "An engineer builds warmth by choosing a suitable mic, adding gentle low-mid EQ, and using a room or reverb that adds body without mud.", "category": "Choral Recording", "related_terms": ["Choral transparency", "Equalization", "Choral resonance control", "Reverberation", "Timbre"], "common_mistakes": ["Adding so much low-mid that warmth turns into mud", "Confusing warmth with simply turning up the bass", "Using a harsh microphone and then trying to fix warmth with EQ alone"], "scenario_contexts": ["Warming up a thin-sounding choir recording", "Choosing a ribbon or condenser mic for a fuller choral tone", "Balancing warmth against clarity in a final mix"]}, "b951e7cb-89d5-4e08-a2c6-7d4fd2f7d306": {"definition": "The techniques used to blend an undistorted, or clean, electric or acoustic guitar into a mix, focusing on tone shaping, level, dynamics, and space so the part sits clearly without competing with vocals or other midrange instruments. Clean guitar carries more transient detail and dynamic range than distorted guitar, so it needs different handling.", "plain_english": "A clean guitar has no distortion, so every note and pick attack shows clearly. Mixing it well means shaping its tone and volume so it fits with the singing and the other instruments.", "purpose_function": "It lets a clear, undistorted guitar part support a song without clashing, by controlling its level, tone, and dynamics.", "practical_application": "An engineer uses EQ, light compression, and reverb or delay to place a clean guitar in the mix, often carving space around the lead vocal.", "category": "Guitar Mixing", "related_terms": ["Equalization", "Compression", "Reverberation", "Panning", "Direct injection"], "common_mistakes": ["Leaving clean-guitar dynamics uncontrolled so the levels jump around", "Piling on distortion-style EQ that clutters the midrange", "Forgetting to carve space so the guitar masks the vocal"], "scenario_contexts": ["Mixing a clean arpeggiated guitar under a lead vocal", "Blending a clean rhythm guitar with keys in a pop track", "Placing a clean guitar with delay in a sparse verse"]}, "437fe320-9dec-4606-9dde-39ac0ade01cf": {"definition": "The sound made when the two hi-hat cymbals are held tightly together, usually by pressing the foot pedal, so a struck cymbal gives a short, crisp, tight tick rather than a sustained wash. It is a core timekeeping articulation on the drum kit.", "plain_english": "A hi-hat is two small cymbals on a stand. When they are pressed shut with a foot pedal and hit, they make a short, tight tick used to keep time.", "purpose_function": "It provides a tight, controlled timekeeping sound that drives the rhythm without ringing on, which is why it anchors most drum grooves.", "practical_application": "A drummer plays closed hi-hat for steady eighth or sixteenth notes, while an engineer mics it closely and controls its bleed into the other drum mics.", "category": "Drum Recording", "related_terms": ["Open hi-hat", "Cymbal bleed", "Overhead miking", "Snare drum", "Crash transient"], "common_mistakes": ["Placing the hi-hat mic where the pedal's blast of air hits it", "Ignoring hi-hat bleed into the snare mic", "Confusing closed and open hi-hat sounds when editing a take"], "scenario_contexts": ["Miking a drum kit for a pop session", "Controlling hi-hat bleed in a tight groove", "Programming a closed hi-hat pattern in a DAW"]}, "a400fa67-8804-4721-b453-1b6b44f72d36": {"definition": "A secondary melodic line written to play against the main melody, complementing it with a different rhythm or contour while staying subordinate to the lead. It adds movement and interest to an arrangement without obscuring the main tune.", "plain_english": "A counterline is a second tune that plays along with the main melody. It moves differently to add interest, but it stays in the background so the main tune leads.", "purpose_function": "It enriches an arrangement by adding a complementary melodic layer that fills gaps and adds motion behind the lead line.", "practical_application": "An arranger writes a counterline for a horn or backing vocal to answer the lead melody, and an engineer mixes it below the main line.", "category": "Arrangement", "related_terms": ["Countermelody", "Harmony", "Arrangement", "Melody", "Voicing"], "common_mistakes": ["Writing a counterline so busy that it fights the main melody", "Mixing the counterline as loud as the lead", "Confusing a counterline with simple harmony notes"], "scenario_contexts": ["Arranging a horn line to answer a vocal melody", "Adding a bass counterline under a chorus", "Layering a backing-vocal counterline in a bridge"]}, "e3542aa3-f72a-4669-8e5b-79f421e562e2": {"definition": "The brief, high-energy attack at the very start of a crash cymbal's sound, before it blooms into its sustained wash. This sharp initial spike carries much of the cymbal's peak level and can dominate meters and trigger compressors and limiters.", "plain_english": "When a crash cymbal is hit, the first split second is a sharp, loud burst before the long ringing sound. That quick burst is the crash transient.", "purpose_function": "The transient gives the crash its sense of impact and accent, and recognising it matters because it drives peak levels and how compressors react.", "practical_application": "An engineer watches for crash transients when setting limiter thresholds and overhead levels, since they can cause sudden peaks and pumping.", "category": "Drum Recording", "related_terms": ["Transient", "Overhead miking", "Compression", "Limiter", "Closed hi-hat"], "common_mistakes": ["Setting overhead levels to the wash and then clipping on the transient peak", "Using a fast limiter that squashes the crash's impact", "Ignoring crash transients when gain-staging the drum bus"], "scenario_contexts": ["Gain-staging drum overheads to avoid clipping on crashes", "Setting a limiter that keeps the crash impact intact", "Taming pumping caused by crash peaks on the drum bus"]}, "43080907-333b-412a-9d4b-843db718da3d": {"definition": "The practice of shaping the high-frequency content of cymbals—typically with high-shelf or high-band EQ in the roughly 8–16 kHz region—to set how bright, airy, or sparkling they sound in a mix. It balances cymbal shimmer against the rest of the kit and the overall program material.", "plain_english": "This means changing how bright or sparkly the cymbals sound. You turn the very high tones up or down with an EQ so the cymbals shine just the right amount.", "purpose_function": "It lets the engineer dial in the top-end sheen of the cymbals so they add air and excitement without becoming dull or too glassy. This keeps the kit sitting well with vocals, guitars, and the rest of the mix.", "practical_application": "On overhead or cymbal channels, a technician uses a high-shelf boost to add sparkle or a cut to soften a bright kit, checking the choice against the whole mix on trusted monitors.", "category": "Drum Mixing", "related_terms": ["Overhead microphones", "Equalization", "High-shelf EQ", "Cymbal harshness control", "Cymbal subgroup"], "common_mistakes": ["Boosting the high shelf too much, which turns natural shimmer into thin, glassy fatigue", "Judging cymbal brightness soloed instead of in the full mix, where guitars and vocals already add top end", "UNSAFE: Repeatedly cranking bright high frequencies loud on headphones or monitors while chasing sparkle, which speeds up hearing fatigue and risks noise exposure"], "scenario_contexts": ["Adding air to dark-sounding overheads on a rock drum tracking session", "Taming an overly bright ride cymbal that is poking out of the mix", "Matching cymbal top end between different songs on an album"]}, "79af7896-dfd6-4184-b95d-fd7e2a45dd7e": {"definition": "The reduction of unpleasant, fatiguing energy in cymbals—usually concentrated in the upper-midrange and low treble (roughly 2–8 kHz)—using narrow EQ cuts, dynamic EQ, or de-essing so the cymbals sound smooth rather than piercing.", "plain_english": "Cymbals can sound sharp and hurt your ears. This means using an EQ to turn down the harsh tones so they sound smoother and easier to listen to.", "purpose_function": "It removes the brittle, ear-piercing frequencies that make cymbals tiring to hear, so the kit stays clear and pleasant even at high levels. This protects the listener from fatigue and keeps the mix balanced.", "practical_application": "A technician sweeps a narrow EQ band to find the harsh spot on the overheads and cuts it, or uses a dynamic EQ or de-esser that only reacts when the harsh peak gets loud.", "category": "Drum Mixing", "related_terms": ["Equalization", "Dynamic EQ", "De-essing", "Cymbal brightness control", "Overhead microphones"], "common_mistakes": ["Cutting too wide a band, which dulls the whole cymbal instead of only removing the harsh spot", "Confusing genuine harshness with useful brightness and stripping out all the life", "UNSAFE: Turning the monitors up to hunt for harsh frequencies for long periods, raising the risk of hearing damage"], "scenario_contexts": ["Smoothing a harsh, splashy hi-hat captured by close overheads", "Fixing brittle 3–5 kHz glare on cheap or thin cymbals", "Using dynamic EQ so cymbals only soften on the loudest crashes"]}, "abe3114f-7fb9-48ce-b0e7-b29ca96f1b18": {"definition": "A subgroup (audio bus) to which all cymbal or overhead microphone channels are routed, so their combined level and processing—such as EQ or compression—can be controlled from a single fader.", "plain_english": "This is one fader that controls all the cymbal microphones at once. Instead of moving many faders, you send them to one channel and change them together.", "purpose_function": "It groups related cymbal signals so the engineer can balance them as a unit and apply shared processing, saving time and keeping the whole set of cymbals consistent. This simplifies mixing a busy drum kit.", "practical_application": "A technician routes the overhead and cymbal channels to a stereo group bus, then rides one fader or adds bus EQ and compression to shape all the cymbals together.", "category": "Mix Routing", "related_terms": ["Subgroup", "Bus", "Overhead microphones", "Drum ambience bus", "Auxiliary send"], "common_mistakes": ["Forgetting that other kit mics leak cymbals, so subgroup changes do not fully control cymbal level", "Adding heavy bus compression that pumps the whole kit instead of just gluing the cymbals", "Routing channels to the subgroup and the main mix at the same time, causing doubled signal and level errors"], "scenario_contexts": ["Managing many overhead and spot cymbal mics from one fader in a live show", "Compressing all cymbals together for a cohesive drum overhead sound", "Muting all cymbals quickly during a soundcheck to isolate other kit pieces"]}, "0414d715-111d-4e70-b7a6-a5ab64130493": {"definition": "The collection of techniques for placing overdriven or distorted electric guitars in a mix—EQ carving, stereo panning of double-tracked parts, and level and dynamics control—so the dense harmonic content sits with the drums and vocals without masking them.", "plain_english": "This is how you fit loud, fuzzy electric guitars into a song. You use EQ, panning, and volume so the guitars sound big but do not cover up the singing.", "purpose_function": "Distorted guitars are harmonically dense and can swamp a mix, so these techniques carve out space and spread the guitars wide to keep the mix clear and powerful. This lets guitars feel huge while vocals and cymbals still cut through.", "practical_application": "A technician pans hard-left and hard-right double tracks, cuts competing mids, and manages low end so the guitars leave room for vocals, bass, and the kick.", "category": "Guitar Mixing", "related_terms": ["Double-tracking", "Equalization", "Panning", "Frequency masking", "Double-track alignment"], "common_mistakes": ["Layering many distorted takes, which builds mud instead of size", "Leaving too much low-mid buildup so guitars fight the bass and kick", "Panning a single mono guitar to fake a wide double instead of recording two real takes"], "scenario_contexts": ["Panning two rhythm-guitar takes wide for a big rock wall of sound", "Carving guitar mids so a lead vocal stays clear in a heavy chorus", "Fitting a distorted guitar with bass and drums without losing punch"]}, "8191359a-1d8b-4109-be88-54b82299177c": {"definition": "An error in drum triggering or electronic percussion in which a single strike generates two (or more) trigger events, producing a doubled or stuttered sound. It is caused by excessive trigger sensitivity, head vibration or retriggering, or crosstalk, and is corrected with threshold, retrigger-cancel/mask-time, and scan-time settings.", "plain_english": "A drum trigger is a sensor that plays a sound when you hit a drum. Double triggering is when one hit wrongly plays the sound twice, like a stutter.", "purpose_function": "Understanding it matters because a false second hit ruins the timing and realism of triggered or sampled drums. Fixing it keeps one strike equal to one clean sound.", "practical_application": "A technician who hears drum samples firing twice raises the trigger threshold or retrigger-cancel time and checks sensitivity and crosstalk settings on the trigger module until each hit fires once.", "category": "Drum Triggering", "related_terms": ["Drum trigger", "Trigger threshold", "Crosstalk", "Drum replacement", "Transient detection"], "common_mistakes": ["Setting trigger sensitivity too high, which makes the pad or trigger fire twice on one hit", "Blaming the sample or module when a loose trigger or vibrating head is the real cause", "Ignoring crosstalk so a nearby drum falsely triggers a second sound"], "scenario_contexts": ["A kick trigger firing two samples per pedal stroke during tracking", "Tuning retrigger-cancel time on an electronic drum module", "Cleaning up drum replacement in a DAW where one hit produced two events"]}, "89707b2f-be1f-44c5-999e-f5960914ea3b": {"definition": "The process of timing- (and sometimes phase-) matching two separately recorded takes of the same part so the doubled performance sounds tight, whether done by manual editing and time-warping or with dedicated alignment tools.", "plain_english": "Sometimes a player records the same part twice to make it sound thicker. Alignment means lining up the two takes so they play in time and sound tight together.", "purpose_function": "Two doubled takes never play perfectly together, so alignment tightens their timing to make the double sound solid and wide instead of sloppy and flammy. This gives a fuller sound without smearing.", "practical_application": "A technician nudges or time-warps notes in the second take to match the first, or uses an alignment plug-in, so a doubled guitar or vocal locks tightly to the main take.", "category": "Editing", "related_terms": ["Double-tracking", "Time alignment", "Comping", "Quantization", "Phase"], "common_mistakes": ["Over-tightening the takes until the natural width and thickness of a real double disappears", "Aligning only the starts of notes but leaving the note releases flamming", "Copying one take and detuning it instead of aligning two real performances"], "scenario_contexts": ["Tightening two rhythm-guitar takes for a wide stereo double", "Lining up a doubled lead vocal so consonants land together", "Fixing loose timing between doubled backing vocals before mixing"]}, "9efccb06-c363-4621-9664-63b357534177": {"definition": "An aux or subgroup bus carrying room and ambient drum microphone signals, or reverb returns, blended with the close mics to add the natural space and size of the recording room to the drum sound; it is often heavily compressed for effect.", "plain_english": "This is a channel that carries the room sound of the drums. You mix in some of this roomy sound to make the drums feel big and alive.", "purpose_function": "Close mics can sound dry and small, so the ambience bus adds room tone and depth that makes drums sound bigger and more natural. Keeping it on its own bus lets the engineer blend and compress that space to taste.", "practical_application": "A technician routes room mics to one bus, adds compression and EQ, and rides its level under the close mics to control how big and roomy the kit feels.", "category": "Drum Mixing", "related_terms": ["Room microphones", "Parallel compression", "Reverb", "Subgroup", "Auxiliary send"], "common_mistakes": ["Adding so much room level that the drums lose punch and clarity", "Ignoring phase between the room mics and close mics, which thins the kit", "Compressing the room bus so hard it pumps and distracts instead of adding size"], "scenario_contexts": ["Blending crushed room mics under close drum mics for a big rock sound", "Controlling how live or dry the drums feel from one fader", "Sending drums to a reverb bus to fake room ambience on a dry kit"]}, "ed5334d6-ee4d-4992-9cd9-d44cd74bb8f0": {"definition": "Techniques that emphasize the transient or attack portion of drum hits—transient shaping, compressor attack and release settings, or EQ boosts in the beater and stick 'click' regions—so the drums sound punchier and cut through the mix.", "plain_english": "The attack is the first punchy hit of a drum. This means making that hit sharper and louder so the drums cut through the song.", "purpose_function": "The initial snap of a drum is what makes it feel powerful and defined, so enhancing it helps the kick and snare punch through a dense mix. This adds impact without simply raising overall level.", "practical_application": "A technician uses a transient shaper to add attack, sets a slower compressor attack to let the hit through, or boosts the click frequencies on kick and snare so they cut through loud guitars.", "category": "Drum Processing", "related_terms": ["Transient shaper", "Compression", "Attack (envelope)", "Equalization", "Parallel compression"], "common_mistakes": ["Setting a fast compressor attack that squashes the transient and kills the punch", "Adding so much attack that drums sound clicky and unnatural", "Boosting click frequencies without checking they do not clash with cymbals and guitars"], "scenario_contexts": ["Adding beater click to a kick so it cuts through heavy guitars", "Using a transient shaper to sharpen a dull snare", "Setting compressor attack to keep drum punch during heavy bus compression"]}, "e6673c5b-7c38-43a3-a0f0-d47db364a890": {"definition": "Distortion that occurs when a drum signal exceeds the maximum level a device, converter, or bus can handle, flattening the waveform peaks. It may be unwanted overload or the deliberate use of a hard or soft clipper to tame sharp transients and raise perceived loudness.", "plain_english": "Clipping is when a drum sound is too loud for the gear and the top of the wave gets cut off. This adds a crackly, distorted sound. It can be a mistake, or done on purpose to make drums louder.", "purpose_function": "Knowing clipping matters because accidental clipping ruins a recording, while a controlled clipper can shave sharp drum peaks so the kit sits louder and tighter. Understanding both keeps drums clean or intentionally punchy.", "practical_application": "A technician watches meters to avoid overloading inputs, and may place a clipper on the kick or drum bus to flatten peaks and get more level before a limiter reacts.", "category": "Drum Processing", "related_terms": ["Clipping", "Headroom", "Limiter", "Gain staging", "Transient"], "common_mistakes": ["Recording drums so hot that the converter clips and adds harsh digital distortion", "Confusing accidental converter clipping with a musical clipper used on purpose", "Clipping too much off the transients, which flattens the punch of the drums"], "scenario_contexts": ["Catching a snare peak that is overloading the input during tracking", "Using a clipper on the drum bus to gain loudness before a limiter", "Diagnosing crackly distortion caused by too little headroom on the drum group"]}, "671fb595-bbff-4c0d-940c-d0a4083c2a75": {"definition": "The application of dynamic-range compression to drum signals—individual close mics, drum groups, or the full drum bus—to reduce the level difference between loud transients and quieter body, control peaks, and shape the perceived punch and sustain of the kit.", "plain_english": "Compression makes a drum's loud hits and softer parts closer in volume. On drums it can make each hit sound more even and punchy, so the beat sits steady in a song.", "purpose_function": "It evens out inconsistent drum dynamics so hits sit steadily in a mix, and it lets the engineer emphasize attack or sustain to make drums feel punchier or bigger.", "practical_application": "An engineer inserts a compressor on the snare or drum bus, sets a ratio and threshold, then adjusts attack and release so the cracks come through while overall level stays controlled.", "category": "Dynamics Processing", "related_terms": ["Drum crush bus", "Parallel compression", "Drum bus", "Attack time", "Release time", "Drum limiting"], "common_mistakes": ["Using too fast an attack, which clamps the initial transient and kills the drum's punch.", "Setting release too slow so the compressor never recovers between hits and the groove pumps unnaturally.", "Over-compressing until the kit sounds squashed and lifeless.", "Judging settings by gain-reduction meters instead of by ear."], "scenario_contexts": ["Tightening an uneven snare performance during a rock mix.", "Adding punch to a drum bus in a dense band arrangement.", "Controlling a kick drum's level so it locks with the bass."]}, "3f81abeb-13e7-4165-9fb9-5251fed6b02e": {"definition": "An auxiliary bus carrying a copy of the drum signal that is deliberately over-compressed—often with added saturation and EQ—to an extreme, then blended underneath the main drum sound to add aggression, density, and sustain; a heavily driven form of parallel drum compression.", "plain_english": "A crush bus is a second copy of the drums that gets squashed really hard. You mix a little of it under the normal drums to make them sound bigger and more aggressive.", "purpose_function": "It gives the engineer extra thickness and energy on demand: the crushed copy raises the low-level detail and sustain of the kit while the clean drums keep their natural attack.", "practical_application": "The engineer sends the drums to an aux, inserts a compressor set to heavy gain reduction with a high ratio and often saturation, then blends it under the dry drums to taste.", "category": "Dynamics Processing", "related_terms": ["Parallel compression", "Drum bus", "Drum compression", "Saturation", "Aux send", "Drum mixing"], "common_mistakes": ["Blending in too much crush so the drums lose their natural attack and sound flat.", "Ignoring latency or phase alignment between the dry and crushed paths.", "Treating the crush bus as the main drum sound rather than a support layer."], "scenario_contexts": ["Beefing up a thin drum kit in a heavy rock or metal mix.", "Adding room-like density to close-miked drums.", "Bringing out ghost notes and cymbal wash under the main drums."]}, "7241c93d-c3cb-4ced-a3a5-59381072ed10": {"definition": "The use of a dynamic equalizer on drums, where the boost or cut in a chosen frequency band responds to the signal level in that band, so problem frequencies are attenuated only when they exceed a threshold rather than being altered statically.", "plain_english": "Dynamic EQ only turns a frequency up or down when it gets too loud. On drums it can tame a ringing tone just when it jumps out, then leave the sound alone the rest of the time.", "purpose_function": "It fixes level-dependent problems—like a boomy note or harsh ring that appears only on hard hits—without permanently changing the drum's overall tone.", "practical_application": "An engineer sets a dynamic EQ band over a resonant kick or snare frequency and dials a threshold so it cuts only when that note rings out too loudly.", "category": "Equalization", "related_terms": ["Drum equalization", "Drum multiband compression", "Drum resonance control", "Resonant frequency", "Threshold", "Notch filter"], "common_mistakes": ["Confusing dynamic EQ with static EQ and leaving cuts active all the time.", "Setting the threshold so low the band behaves like a normal fixed EQ cut.", "Using too wide a band so nearby useful frequencies get pulled down too."], "scenario_contexts": ["Taming a snare ring that only appears on hard backbeats.", "Controlling a kick boom that builds during loud sections.", "Reducing cymbal harshness on overhead peaks without dulling quieter hits."]}, "09368231-2486-48b5-8e3e-da9faddc20c2": {"definition": "The adjustment of the frequency balance of drum signals with an equalizer—boosting or cutting specific bands—to shape tone, remove unwanted resonances, and help each drum sit clearly in a mix.", "plain_english": "EQ changes how much of each pitch range you hear. On drums you use it to add thump to a kick, snap to a snare, or cut a ringing tone so each drum sounds clear.", "purpose_function": "It lets the engineer sculpt each drum's tone and carve out space so kick, snare, and cymbals don't mask one another.", "practical_application": "An engineer sweeps an EQ to find a boomy or harsh frequency, cuts it, then adds a gentle boost—for example low-end weight around 60-100 Hz for kick or attack around 3-5 kHz for snare.", "category": "Equalization", "related_terms": ["Drum dynamic equalization", "Drum resonance control", "Drum low-end control", "Parametric EQ", "High-pass filter", "Drum mixing"], "common_mistakes": ["Boosting instead of first cutting problem frequencies, which piles up level and mud.", "Applying big EQ moves before checking mic choice and placement.", "EQ'ing each drum in solo instead of in the context of the full mix."], "scenario_contexts": ["Adding low-end weight to a kick drum in a rock mix.", "Cutting boxy build-up around 400 Hz on toms.", "Brightening dull overheads to bring out cymbal detail."]}, "e7afc30c-4381-4d01-9aac-d2d4ab8f2f6d": {"definition": "The application of a limiter to drum signals to place a firm ceiling on peak level, catching the sharpest transients so they do not exceed a set threshold while leaving the rest of the signal largely untouched.", "plain_english": "A limiter is like a wall the sound can't go past. On drums it catches the loudest, sharpest hits so they don't spike too high or clip your recording.", "purpose_function": "It protects against overloads and controls stray peaks—such as a hard snare crack—so overall drum level can sit higher and steadier without distortion.", "practical_application": "An engineer places a limiter on a peaky drum channel or the drum bus, sets the ceiling just below clipping, and lets it shave only the few loudest transients.", "category": "Dynamics Processing", "related_terms": ["Drum compression", "Drum bus", "Transient", "Peak level", "Clipping", "Drum multiband compression"], "common_mistakes": ["Driving the limiter too hard so transients are flattened and the drums lose punch.", "Confusing limiting with gentle compression and using it for broad tone shaping.", "Setting the ceiling at 0 dBFS instead of leaving safety headroom for downstream stages."], "scenario_contexts": ["Catching occasional snare peaks that would otherwise clip a recording.", "Holding the drum bus under a fixed level in a loud mix.", "Preventing hard tom hits from overloading a channel."]}, "fb4d04a4-4771-4277-97cb-c7cd07681691": {"definition": "The set of techniques used to manage the low-frequency content of a drum kit—chiefly kick and toms—including high-pass filtering, EQ, and dynamics, so the bottom end is powerful and defined without becoming boomy or masking the bass.", "plain_english": "This means keeping the deep, booming part of the drums under control. You trim and shape the low sounds so the kick hits hard but doesn't turn into a muddy rumble.", "purpose_function": "It keeps the kit's bottom end tight and clear so the kick and bass work together instead of clashing or building up mud.", "practical_application": "An engineer high-passes the non-bass drums, shapes the kick's low band with EQ, and may compress or gate to stop low-end ring, checking how it sits against the bass guitar.", "category": "Mixing Technique", "related_terms": ["High-pass filter", "Drum equalization", "Drum resonance control", "Drum multiband compression", "Drum mixing", "Drum compression"], "common_mistakes": ["Boosting kick lows to feel big while ignoring the clash with the bass guitar.", "Not high-passing toms and cymbal mics, letting low rumble pile up.", "Judging low end on small speakers or earbuds that cannot reproduce it."], "scenario_contexts": ["Making the kick and bass share the low end cleanly in a band mix.", "Removing stage rumble from tom mics in live sound.", "Tightening a boomy kick recorded in an untreated room."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"abfb9e06-bed1-4fdb-8f3d-7c91ad52f71e": {"definition": "The process of combining the individual drum-kit tracks—kick, snare, toms, hi-hat, overheads, and room mics—into a balanced, cohesive whole using level, panning, EQ, dynamics, and effects.", "plain_english": "Drum mixing is blending all the separate drum mics into one good-sounding kit. You set volumes, positions, and tone so the drums sound like one instrument, not many.", "purpose_function": "It turns many separate drum recordings into a unified kit with the right balance, width, and impact for the song.", "practical_application": "An engineer sets rough levels, pans the kit to match the drummer's layout, then applies EQ, compression, and reverb before routing everything to a drum bus.", "category": "Mixing Technique", "related_terms": ["Drum bus", "Drum compression", "Drum equalization", "Overhead miking", "Panning", "Drum crush bus"], "common_mistakes": ["Building the mix from close mics first instead of starting with the overheads or room for the core kit sound.", "Ignoring phase relationships between the kick, snare, and overhead mics.", "Over-processing every channel before hearing them together."], "scenario_contexts": ["Mixing a multitrack drum recording for a rock song.", "Balancing a live drum kit through a console at a gig.", "Blending sampled and acoustic drums in a hybrid production."]}, "3a30ada9-edb3-4f6a-ac72-0fe83c7d06dc": {"definition": "The use of a multiband compressor on drums, which splits the signal into separate frequency bands and compresses each independently, so dynamics in the low, mid, and high ranges can be controlled without one band's peaks triggering compression across the whole sound.", "plain_english": "This tool splits the drum sound into low, middle, and high parts and squashes each one on its own. So you can tame a boomy kick without also dulling the cymbals.", "purpose_function": "It lets the engineer control problem dynamics in one frequency range—like a jumpy low end—while leaving other ranges untouched, which a full-band compressor cannot do.", "practical_application": "On a drum bus, an engineer sets the low band to tame kick boom, maybe a mid band for snare body, and leaves the highs light so the cymbals stay open.", "category": "Dynamics Processing", "related_terms": ["Drum compression", "Drum dynamic equalization", "Drum bus", "Crossover", "Drum low-end control", "Drum limiting"], "common_mistakes": ["Setting too many bands with aggressive settings, which makes the kit sound processed and unnatural.", "Confusing multiband compression with EQ and using it for static tone changes.", "Placing crossover points right on important frequencies, creating audible artifacts."], "scenario_contexts": ["Controlling a bass-heavy drum bus that pumps when the kick hits.", "Evening out a drum submix that has both boomy lows and harsh highs.", "Applying mastering-style control to a stereo drum stem."]}, "ee133fc4-872f-47cf-a305-073f57a36585": {"definition": "Techniques for reducing unwanted resonances—ringing, boom, or sustained tonal notes—in drum signals, using narrow EQ cuts, dynamic EQ, gating, or dampening and muffling at the source, so the kit's tone stays clean and controlled.", "plain_english": "This means stopping drums from ringing or booming too much. You find the ringing note and cut it, or dampen the drum itself, so each hit sounds tight.", "purpose_function": "It removes distracting sustained tones so drums sound focused and don't clash with pitched instruments in the mix.", "practical_application": "An engineer sweeps a narrow EQ to find a ringing frequency and cuts it, or has the drummer add muffling such as moongel before re-recording.", "category": "Equalization", "related_terms": ["Drum equalization", "Drum dynamic equalization", "Resonant frequency", "Notch filter", "Drum low-end control", "Drum mixing"], "common_mistakes": ["Cutting too wide, which kills the drum's natural tone along with the ring.", "Trying to fix in the mix what should be tuned or dampened on the drum itself.", "Removing all resonance so the drums sound dead and lifeless."], "scenario_contexts": ["Taming a ringing snare that sustains a clear pitch.", "Reducing tom boom that lingers between hits.", "Cleaning up sympathetic buzz from other drums during recording."]}, "d4106092-4cc0-465a-b768-01ea74215557": {"definition": "A dedicated bus or auxiliary channel to which triggered or replacement drum samples are routed so they can be processed and level-balanced together, separately from the acoustic drum tracks.", "plain_english": "One mixer channel that gathers all the added or fake drum sounds in one place. From there you can shape and balance them together instead of one by one.", "purpose_function": "It keeps drum reinforcement and replacement samples on a single path so their level, tone and effects can be managed as a unit and blended under the live kit.", "practical_application": "When an engineer triggers kick or snare samples to reinforce weak recorded hits, all the sample outputs feed this bus for shared EQ, compression and fader control before joining the main drum mix.", "category": "Signal routing", "related_terms": ["Drum subgroup", "Sample replacement", "Drum trigger", "Parallel compression", "Kick reinforcement"], "common_mistakes": ["Letting sample levels overpower the live drums so the kit sounds artificial", "Forgetting to time-align the samples with the original hits, causing phase smear or flams", "Not high-pass filtering or gating the samples, which adds unwanted low-end or noise"], "scenario_contexts": ["Reinforcing a thin recorded kick with a sample layer in a rock mix", "Blending snare samples across a multitrack to even out inconsistent hits", "Building a consistent drum layer under a live acoustic performance"]}, "1d34f36f-b711-4e54-a116-a4cc145915cb": {"definition": "The deliberate addition of harmonic distortion to drum signals using tape, tube, transformer or clipping-style processing, adding harmonics, perceived loudness and warmth or aggression.", "plain_english": "Adding a bit of controlled grit to the drums. It makes them sound fuller and louder without just turning up the volume, like the warm crunch of tape or a tube amp.", "purpose_function": "It generates extra harmonics that thicken the sound, soften sharp peaks and help the drums cut through a dense mix.", "practical_application": "An engineer drives a saturation plug-in or analog emulation on the snare or the drum bus to add weight and edge, watching that it does not turn into harshness.", "category": "Harmonic processing", "related_terms": ["Drum-bus compression", "Harmonic distortion", "Tape emulation", "Drum transient shaping", "Parallel compression"], "common_mistakes": ["Over-driving until the drums sound fuzzy and lose their punch", "Confusing saturation with clean gain and pushing levels too hot", "Applying heavy saturation across the whole bus instead of the one drum that needs it"], "scenario_contexts": ["Adding tube warmth to a clean sampled kit", "Driving a room mic for aggressive rock drums", "Using gentle tape saturation on the drum bus for glue"]}, "a2a07717-67a9-4f84-a3ce-5ca226503e99": {"definition": "A mix group or bus that sums several individual drum channels onto one set of controls, allowing collective level, dynamics and effects processing of the whole kit.", "plain_english": "One master fader that controls the whole drum kit at once. Instead of moving ten channels, you move one to turn the whole kit up or down.", "purpose_function": "It simplifies control of the many drum mics and lets an engineer process and automate the entire kit as a single unit.", "practical_application": "The engineer routes kick, snare, toms and overheads into a drum subgroup, then rides one fader and adds bus compression or EQ across all of them.", "category": "Signal routing", "related_terms": ["Drum-bus compression", "Drum sample bus", "Aux send", "VCA group", "Mix bus"], "common_mistakes": ["Confusing a subgroup, which sums audio, with a VCA, which only links faders", "Routing drums to both the subgroup and the main output, which doubles the signal", "Clipping the subgroup by summing many hot channels without watching the group meter"], "scenario_contexts": ["Combining all drum mics onto one fader for easy balance", "Applying a single compressor across the whole kit", "Muting the entire kit in one move during arrangement edits"]}, "bc17d084-fef7-49ab-a743-9d89a1564d35": {"definition": "The adjustment of the decay or tail portion of a drum's envelope, typically with a transient designer, to lengthen or shorten how long each hit rings after its initial attack.", "plain_english": "A control that sets how long each drum hit rings out. Turn it down for a tight, dry thud, or up to let the drum ring and breathe longer.", "purpose_function": "It shapes the body and room feel of drums after the attack, tightening loose kits or adding fullness without re-recording.", "practical_application": "An engineer lowers the sustain on a boomy tom to dry it up, or raises it on a dead snare to bring back some ring, using a transient shaper.", "category": "Transient processing", "related_terms": ["Drum transient shaping", "Attack time", "Noise gate", "Drum-bus compression", "Envelope shaper"], "common_mistakes": ["Cutting sustain so hard the drums sound lifeless and gated", "Boosting sustain until room noise and bleed become obvious", "Assuming sustain control is the same as a compressor release setting"], "scenario_contexts": ["Tightening a ringing tom in a rock mix", "Drying out an overly live room sound", "Adding tail back to a heavily damped snare"]}, "11b61388-a1d3-4ace-abc3-cd5485c6ae88": {"definition": "The use of a transient designer to independently boost or cut the attack and sustain portions of drum hits, changing punch and body without threshold-based compression.", "plain_english": "Reshaping the punch and ring of each drum hit. You can make a hit snappier or softer, and its tail longer or shorter, all on purpose.", "purpose_function": "It lets an engineer add attack for punch or reduce sustain for tightness independent of level, going beyond what a normal compressor can do.", "practical_application": "An engineer boosts attack on a soft kick to make it click through the mix, or cuts sustain on toms to tighten them, using a transient designer plug-in.", "category": "Transient processing", "related_terms": ["Drum sustain control", "Attack time", "Drum-bus compression", "Envelope shaper", "Drum saturation"], "common_mistakes": ["Adding so much attack that the drums click harshly and unnaturally", "Forgetting that boosting attack also raises peak level and can clip later stages", "Using a transient shaper on a noisy track, which pumps up the bleed and hiss"], "scenario_contexts": ["Sharpening a dull kick drum's attack", "Tightening loose, ringy toms", "Bringing more snap to an ambient snare"]}, "139bebf6-7602-415e-a25c-2e1990b58580": {"definition": "The recording and playback of time-based changes to drum-bus parameters, such as fader level, compression, EQ or effect sends, so the drum group responds dynamically through a song.", "plain_english": "Programming the drum group to change on its own over time. For example, the drums get louder in the chorus without you touching the fader each time.", "purpose_function": "It keeps the drum group balanced and expressive across a song, letting sections build or pull back without manual moves during every playback.", "practical_application": "An engineer draws automation to raise the drum-bus fader in the chorus, open a reverb send in a fill, or ease off compression in a quiet verse.", "category": "Automation", "related_terms": ["Drum subgroup", "Drum-bus compression", "Fader ride", "Aux send", "Mix bus"], "common_mistakes": ["Writing jumpy automation that causes sudden, unnatural level jumps", "Automating the bus fader when a single channel actually needed the fix", "Leaving old automation active after re-balancing, which fights new fader moves"], "scenario_contexts": ["Lifting the whole kit for a chorus", "Opening a reverb throw on a drum fill", "Pulling drums back under a soft vocal verse"]}, "fb3be9fa-c5b1-4f46-a100-93dfa9621cf5": {"definition": "Compression applied across the summed drum bus rather than individual channels, used to glue the kit together, control dynamics and add punch or density to the whole drum group.", "plain_english": "One compressor placed on the whole drum group. It squeezes the kit so it sounds like one solid, punchy instrument instead of separate pieces.", "purpose_function": "It binds the separate drum mics into a cohesive whole, evens out the overall level and can add energy and sustain to the kit.", "practical_application": "An engineer patches a bus compressor across the drum subgroup with slow attack and fast release to keep transients while pulling the kit together.", "category": "Dynamics processing", "related_terms": ["Drum subgroup", "Parallel compression", "Attack time", "Drum saturation", "Drum-bus density"], "common_mistakes": ["Setting attack too fast, which kills the drum punch and softens hits", "Using too much gain reduction so the kit pumps and breathes unnaturally", "Confusing bus glue compression with heavy individual-channel compression"], "scenario_contexts": ["Gluing a multi-mic kit into one cohesive sound", "Adding punch and energy to a rock drum bus", "Using parallel bus compression to thicken drums under the dry kit"]}, "4e40f173-5a0c-4d71-9b50-7bf85232fe98": {"definition": "The perceived fullness, sustain and cohesion of the drum bus, usually increased through bus compression, saturation or parallel processing that raises low-level detail and thickens the overall sound.", "plain_english": "How thick and full the whole drum group sounds. More density makes the drums feel solid and packed together; less leaves them thin and spaced out.", "purpose_function": "It describes how solid and connected the kit feels, a quality engineers build so drums sit powerfully in a mix rather than sounding sparse.", "practical_application": "An engineer raises drum-bus density by adding bus compression, parallel compression or saturation until the kit feels full and supported without losing punch.", "category": "Dynamics processing", "related_terms": ["Drum-bus compression", "Parallel compression", "Drum saturation", "Drum subgroup", "Drum-bus gain staging"], "common_mistakes": ["Chasing density until the drums sound squashed and lose dynamics", "Confusing density with loudness and simply turning the bus up", "Adding so much parallel signal that the dry punch disappears"], "scenario_contexts": ["Thickening a sparse-sounding kit with parallel compression", "Building a solid drum foundation for a dense rock mix", "Adding sustain and body to a dry, close-miked kit"]}, "403a6ad9-8b73-4c42-afb1-c6b823bac1c4": {"definition": "Setting appropriate signal levels into and out of the drum bus and its processors so each stage runs in its optimal range, avoiding noise at low levels and clipping or unwanted distortion at high levels.", "plain_english": "Setting the right volume at each step through the drum group. Keep it loud enough to stay clean, but not so hot that it distorts.", "purpose_function": "It ensures the drum bus and its plug-ins are fed at their intended level, protecting headroom and keeping the sound clean and consistent.", "practical_application": "An engineer trims the summed drum channels so the bus meter sits with healthy headroom before compression, then matches output level after processing.", "category": "Gain staging", "related_terms": ["Drum subgroup", "Drum-bus compression", "Headroom", "Signal-to-noise ratio", "Metering"], "common_mistakes": ["Summing many hot channels and clipping the bus before any processing", "Ignoring how a plug-in's output gain changes the level feeding the next stage", "Assuming a loud bus is fine as long as the master does not clip"], "scenario_contexts": ["Trimming the drum bus so it does not clip after summing", "Matching input and output levels around a bus compressor", "Leaving headroom on the drum bus for mastering"]}, "09482683-7f97-4496-b1c0-149028aca0f6": {"definition": "The use of light bus compression across the summed drum subgroup, typically at a low ratio with a slow attack and only a few dB of gain reduction, so the individual kit elements move together and cohere as a single instrument.", "plain_english": "It is a gentle squeeze put on all the drum tracks at once so they sound like one tight kit instead of separate parts. Think of it like a rubber band that pulls the drums together into a single group.", "purpose_function": "It exists to make separately miked drum elements behave as one cohesive kit, tightening the ensemble and adding consistency and perceived loudness to the group.", "practical_application": "On the drum subgroup a mixer inserts a bus compressor set for roughly one to three dB of gain reduction with a slow attack, listening for the kit to sound tighter and more unified.", "category": "Drum Bus Processing", "related_terms": ["Drum-bus processing", "Bus compression", "Subgroup", "Parallel compression", "Transient shaping"], "common_mistakes": ["Using too high a ratio or too much gain reduction, which squashes the drums and kills their dynamics.", "Setting a fast attack that clamps the transients and makes the kit sound dull.", "Confusing gentle glue compression with heavy parallel compression, which uses far more gain reduction."], "scenario_contexts": ["Mixing a rock band where the kick, snare and overheads need to feel like one kit.", "Tightening a multi-mic drum recording before placing it in a dense band mix."]}, "e84d41e0-5d79-4537-bc42-1fc79bd0f379": {"definition": "A parallel-processing technique in which a duplicate of the drum subgroup is heavily processed, usually with aggressive compression, and blended underneath the unprocessed drum bus, adding density and sustain while preserving the transients of the dry signal.", "plain_english": "You make a copy of the whole drum mix, squash it hard, then mix a little of it back under the real drums. This adds power without losing the punch of the first hits.", "purpose_function": "It lets an engineer add weight, sustain and aggression to the kit without crushing its natural dynamics, because the untouched dry bus keeps the punch while the squashed copy fills in body.", "practical_application": "An engineer routes the drum bus to an aux with a hard-hitting compressor, then rides that aux fader up under the main drums until the kit gains weight without losing snap.", "category": "Drum Bus Processing", "related_terms": ["Parallel compression", "Drum-bus processing", "New York compression", "Aux send", "Drum-bus glue"], "common_mistakes": ["Phase or timing problems when the parallel path adds latency and smears the transients.", "Blending in so much of the squashed copy that the kit loses its natural punch.", "Forgetting that the dry bus should stay the main sound, with the parallel path only supporting it."], "scenario_contexts": ["Adding weight to a thin drum recording for a modern pop or rock track.", "Giving a drummer's soft verse groove more body without changing the arrangement."]}, "e529c55d-170a-43d0-9499-ab4ff15237cb": {"definition": "Any signal processing, such as EQ, compression, saturation or transient shaping, applied to the summed drum subgroup as a whole rather than to individual kit channels, shaping the overall tone and dynamics of the kit.", "plain_english": "This is any effect, like EQ, squeeze, or grit, added to all the drum tracks together on one channel. It lets you shape the whole kit with a single set of controls.", "purpose_function": "It provides a single point to shape the tone, balance and dynamics of the whole kit, saving time and creating cohesion versus treating every drum channel separately.", "practical_application": "A mixer sums kick, snare, toms and overheads to one drum bus and inserts EQ, compression or saturation there to treat the whole kit at once.", "category": "Drum Bus Processing", "related_terms": ["Drum bus", "Subgroup", "Bus compression", "Drum-bus glue", "Saturation"], "common_mistakes": ["Over-processing the whole bus instead of fixing a single problem drum on its own channel.", "Stacking many plugins on the bus and losing the kit's natural balance.", "Applying bus processing before the individual drums are balanced."], "scenario_contexts": ["Shaping a full drum kit's tone with one EQ and compressor on the subgroup.", "Setting up a drum bus at the start of a band mix session."]}, "afcbc3a0-9f80-44a5-b368-e57b644ca7ad": {"definition": "The perceived transient impact and forward energy of the drum kit, enhanced on the drum subgroup, typically by setting a compressor's attack slow enough to let the initial transients through while the release restores level between hits, or by using a transient shaper.", "plain_english": "This is making the drums hit harder and jump out of the mix. Engineers set the squeeze so the front of each hit stays sharp and strong.", "purpose_function": "It exists to make the drums cut through a dense band mix and feel powerful, giving the rhythm section its sense of impact and drive.", "practical_application": "To add punch a technician sets the drum-bus compressor's attack slow and release faster, or uses a transient shaper, so the initial hit of the kick and snare stays sharp.", "category": "Drum Bus Processing", "related_terms": ["Transient shaping", "Bus compression", "Attack time", "Drum-bus glue", "Drum-bus processing"], "common_mistakes": ["Setting the compressor attack too fast, which removes the transient and kills the punch it was meant to add.", "Relying only on volume rather than transient shaping to create impact.", "Chasing punch on the bus while ignoring poor drum tuning or performance underneath."], "scenario_contexts": ["Making the drums cut through electric guitars in a loud rock chorus.", "Adding impact to a programmed or lightly played drum part."]}, "35f907aa-3b0d-4024-b843-7212b9900b28": {"definition": "The use of mix automation to vary the level, or other parameters, of the room-microphone channel or bus across an arrangement, raising ambience in bigger sections and reducing it elsewhere.", "plain_english": "This means turning the room mic sound up or down at different parts of the song. You might push it louder in a big chorus to make the drums feel huge.", "purpose_function": "It lets the ambience track the energy of the song, so the drums breathe and grow in choruses or big sections without adding clutter in quiet verses.", "practical_application": "During a mix the engineer writes fader automation on the room bus, pulling it down in verses and pushing it up in the chorus to lift the drums.", "category": "Room Mic Processing", "related_terms": ["Room microphone", "Mix automation", "Ambience", "Drum-room compression", "Fader ride"], "common_mistakes": ["Leaving the room mics at one static level so the drums feel flat through the song.", "Automating so aggressively that the ambience jumps and distracts the listener.", "Forgetting to check room-mic phase before automating their level."], "scenario_contexts": ["Pushing the room mics up in a big chorus and pulling them down in a quiet verse.", "Building energy across the sections of a live-tracked band song."]}, "22c5ef0a-6e49-45d6-9f0c-0d6cc0b911af": {"definition": "Compression applied to the room, or ambient, microphones of a drum kit, which raises the level of the decay and ambience relative to the transients, making the kit sound larger and more aggressive.", "plain_english": "This squeezes the sound from the mics placed far from the drums. It makes the room feel bigger and the drums sound more alive and aggressive.", "purpose_function": "It exists to exaggerate the natural ambience and decay of the recording space, turning distant mics into a tool for size, sustain and aggression.", "practical_application": "A mixer inserts a compressor on the room-mic bus and drives it with a fast attack and low threshold, blending the squashed ambience under the close mics for size.", "category": "Room Mic Processing", "related_terms": ["Room microphone", "Parallel compression", "Ambience", "Drum-room gating", "Bus compression"], "common_mistakes": ["Over-compressing the room mics so cymbal wash and noise become louder than the drums.", "Ignoring phase between the room and close mics, which thins the kick and snare.", "Expecting room compression to fix a poor-sounding room."], "scenario_contexts": ["Creating a huge ambient drum sound for a rock or alternative record.", "Adding sustain and aggression to close-miked drums using distant mics."]}, "b4bd7699-c7df-43c7-89f4-90255009b979": {"definition": "Deliberate harmonic distortion or saturation applied to the room-microphone signal of a drum kit to add harmonics, grit and perceived loudness, commonly used for aggressive rock and alternative styles.", "plain_english": "This adds grit or fuzz to the far room mics. It makes the drums sound raw and powerful, like a loud rock record.", "purpose_function": "It adds harmonic energy and perceived loudness to the ambience, giving drums an aggressive, larger-than-life character that a clean signal cannot provide.", "practical_application": "An engineer adds a saturation or distortion plugin, or overdrives a preamp, on the room-mic channel and blends it in for grit on an aggressive rock track.", "category": "Room Mic Processing", "related_terms": ["Saturation", "Harmonic distortion", "Room microphone", "Drum-room compression", "Ambience"], "common_mistakes": ["Adding so much distortion that the drums turn to harsh noise and lose definition.", "Distorting the room without checking phase against the close mics.", "Using distortion to mask a weak drum performance instead of improving the source."], "scenario_contexts": ["Getting a raw, aggressive drum tone for a punk or hard-rock track.", "Adding grit to overly clean room mics in a modern band mix."]}, "1eef34c1-9318-4c25-8638-83d69ba7f809": {"definition": "Dynamic expansion applied to the room microphones, usually downward expansion that reduces level below a threshold, tightening the ambient decay and reducing bleed while keeping the louder room sound on the hits.", "plain_english": "This tool makes quiet room sound even quieter between hits. It cleans up the drums by cutting the leftover noise and bleed in the room mics.", "purpose_function": "It exists to control unwanted ambient bleed and tail length in the room mics, keeping the kit tight while still allowing a big room sound on the loudest hits.", "practical_application": "A technician places an expander on the room mics to shorten the ambient tail and reduce bleed while keeping the loud hits open and full.", "category": "Room Mic Processing", "related_terms": ["Downward expansion", "Noise gate", "Room microphone", "Drum-room gating", "Bleed"], "common_mistakes": ["Setting the expander threshold too high so it chops off the natural room tail.", "Confusing expansion with compression; expansion makes quiet parts quieter, not louder.", "Over-tightening the room mics until the kit loses its sense of space."], "scenario_contexts": ["Tightening a boomy live room so only the loud hits carry ambience.", "Reducing cymbal and bleed noise in the room mics between drum hits."]}, "47cc7b39-0559-42ac-b34e-9f41759fd396": {"definition": "The use of a noise gate on the room, or ambient, microphones so the channel passes signal only when the drums exceed a threshold, controlling the length of the ambience and removing low-level bleed and noise between hits.", "plain_english": "A gate shuts off the room mics when the drums are quiet and opens them when the drums are hit. This stops unwanted background sound from washing over the mix.", "purpose_function": "It exists to control how much room ambience and bleed reaches the mix, letting the engineer dial the perceived room size and remove noise between hits.", "practical_application": "During mixdown the engineer inserts a noise gate on the room mics, setting threshold and hold so the ambience opens on hits and closes to cut bleed and noise.", "category": "Room Mic Processing", "related_terms": ["Noise gate", "Threshold", "Room microphone", "Drum-room expansion", "Bleed"], "common_mistakes": ["Setting the threshold so high the gate chatters and cuts off wanted ambience.", "Ignoring hold and release times, causing an unnatural chopped decay.", "Gating the room so hard the drums sound dry and lifeless."], "scenario_contexts": ["Controlling a long, washy room decay on a fast rock song.", "Removing hum and bleed from room mics during quiet passages."]}, "a9b942b0-f44a-417a-b102-0bf2160f568b": {"definition": "A mix bus (subgroup) that combines the room or ambient microphones of a drum kit onto one set of faders for shared level, dynamics, and effects processing.", "plain_english": "It is one fader that controls all the room mics on a drum kit at once. Think of a power strip: flip one switch and every ambient drum mic moves together.", "purpose_function": "It lets the engineer blend and process the kit's ambient room sound as a single element, controlling drum energy and depth without touching each close mic.", "practical_application": "An engineer routes the room mics to this subgroup, then compresses or rides the fader to push kit ambience up in loud choruses and pull it back in quiet verses.", "category": "Drum Processing", "related_terms": ["Subgroup", "Room microphone", "Drum overheads", "Parallel compression", "Bus processing", "Aux send"], "common_mistakes": ["Routing close mics and room mics to the same subgroup, which removes independent control of the direct drum sound", "Over-compressing the room subgroup so the kit sounds pumped and unnatural", "Ignoring phase between the room mics and close mics, which can make the kit sound hollow or thin"], "scenario_contexts": ["Mixing a live-off-the-floor rock session where room mics add size to the kit", "Adding parallel room ambience under a tight, close-miked pop drum sound", "Automating kit ambience up in a big chorus and down in an intimate verse"]}, "da3a4385-ffe8-474b-bcc0-31a23470ab74": {"definition": "A small, often incidental production detail, such as a reversed cymbal, subtle percussion hit, filtered vocal snippet, or momentary effect, added to a mix to catch the listener's attention and add interest at specific moments.", "plain_english": "It is a tiny extra sound sprinkled into a song to grab your ear for a second. It works like a bit of sparkle, keeping the track fun to listen to again and again.", "purpose_function": "It exists to add novelty, movement, and repeat-listen interest to an arrangement, often marking a transition or filling a gap without changing the core parts.", "practical_application": "A producer drops a reverse cymbal, riser, or vinyl-crackle sample right before a chorus so the new section lands with a small surprise.", "category": "Arrangement", "related_terms": ["Arrangement", "Transition effect", "Automation", "Overdub", "Sound design", "Drum fill"], "common_mistakes": ["Adding so many ear-candy sounds that they clutter the mix and distract from the song", "Placing them too loud so they pull focus from the lead vocal", "Scattering them at random instead of at meaningful moments like transitions"], "scenario_contexts": ["Placing a reverse-reverb swell right before the first chorus drops", "Adding a subtle shaker detail only in the second verse for variety", "Dropping a filtered vocal ad-lib into an instrumental break"]}, "248d97ea-99d3-4312-874a-dc8e8126dfae": {"definition": "The techniques used to place an electric bass guitar in a mix, including level balancing, EQ, compression, and sometimes distortion or amp and DI blending, so it supports the low end and locks with the kick drum.", "plain_english": "It is how you fit the electric bass into a song so it sounds full but not muddy. The goal is to make the bass and the kick drum work as a team, not fight each other.", "purpose_function": "It ensures the bass provides a solid, consistent low-end foundation and rhythmic glue that ties the drums and the harmony together.", "practical_application": "An engineer compresses the bass for steady level, carves EQ so it and the kick sit in different frequencies, and blends a DI track with a miked amp for clarity plus weight.", "category": "Instrument Mixing", "related_terms": ["Kick-bass relationship", "DI box", "Compression", "Low-end management", "Sidechain compression", "Amp miking"], "common_mistakes": ["Boosting sub-bass so much the mix booms on big speakers but vanishes on small ones", "Letting the kick and bass mask each other because both sit in the same frequency range", "Skipping compression, so the bass level jumps from note to note"], "scenario_contexts": ["Getting kick and bass to sit together in a dense rock or pop mix", "Blending a clean DI with a driven amp for a gritty rock bass tone", "Using EQ carving to keep the bass audible on phone and laptop speakers"]}, "48739a73-5d10-4e1e-9b38-ffb0d1749160": {"definition": "The techniques used to place electric guitar parts in a mix, including level, EQ, panning, and effects, so rhythm and lead guitars sit clearly without masking vocals or crowding the midrange.", "plain_english": "It is how you fit electric guitars into a song so they sound big but still leave room for the singer. Often you spread two guitars left and right so they do not pile up in the middle.", "purpose_function": "It manages the guitars' strong midrange energy so they add drive and width while staying out of the way of the lead vocal and other mid-heavy instruments.", "practical_application": "An engineer double-tracks a rhythm part, pans the two takes hard left and right for width, and dips guitar EQ around the vocal's core frequencies to keep words clear.", "category": "Instrument Mixing", "related_terms": ["Double-tracking", "Panning", "Midrange", "Amp miking", "EQ carving", "Reamping"], "common_mistakes": ["Letting loud guitars mask the lead vocal because both live in the midrange", "Stacking many guitar layers until the mix turns into a wall of mush", "Panning a single mono guitar dead center where it competes with vocal and snare"], "scenario_contexts": ["Double-tracking and hard-panning rhythm guitars for a wide rock sound", "Carving guitar EQ so the vocal stays clear in a dense chorus", "Placing a lead guitar in a stereo and frequency space that avoids the vocal"]}, "293df6b9-930a-4e80-a13f-f9ee15fbdeb1": {"definition": "The techniques used to place an electric piano, such as a Rhodes or Wurlitzer, in a mix, including level, EQ, compression, stereo width, and modulation effects, so it fills harmonic space without clashing with guitars, keys, or vocals.", "plain_english": "It is how you fit an electric piano, like a Rhodes, into a song. Because it covers a wide range, you shape it so it supports the track without crowding the singer or guitars.", "purpose_function": "It controls the electric piano's broad midrange and sustain so it adds harmonic body and warmth while leaving room for other mid-range instruments.", "practical_application": "An engineer compresses the part for even sustain, adds chorus or tremolo for character, and EQs out overlapping mids so it and the rhythm guitar do not fight.", "category": "Instrument Mixing", "related_terms": ["Rhodes", "Chorus effect", "Tremolo", "Compression", "Midrange", "Harmonic layering"], "common_mistakes": ["Leaving the part too wide or too effect-heavy so it smears the center of the mix", "Letting it clash with rhythm guitar because both fill the same midrange", "Over-compressing until the natural bell-like dynamics disappear"], "scenario_contexts": ["Fitting a Rhodes part under a vocal in a soul or R&B ballad", "Using EQ to separate electric piano from rhythm guitar in a full band mix", "Adding tremolo and light compression to shape a vintage keyboard tone"]}, "0b0f478e-40dd-4cdc-9ead-14dbb43b5b1a": {"definition": "The degree to which the separate instruments and voices in a mix blend and feel like a single, unified performance rather than a set of disconnected tracks.", "plain_english": "It is how well all the parts of a song feel like one band playing together. When a mix has it, the instruments sound glued, not like separate pieces stuck side by side.", "purpose_function": "It is a mixing goal that makes a multitrack recording sound like a believable, connected group, improving how natural and musical the final mix feels.", "practical_application": "An engineer uses shared reverb, gentle bus compression, and consistent timing and tuning so drums, bass, guitars, and vocals feel like one performance in one space.", "category": "Mix Quality", "related_terms": ["Bus compression", "Glue compression", "Shared reverb", "Ensemble intelligibility", "Blend", "Arrangement"], "common_mistakes": ["Soloing and perfecting each track alone, so the parts never blend as a group", "Using a different reverb on every element, which scatters the instruments into separate spaces", "Ignoring timing and tuning differences that stop the band from locking together"], "scenario_contexts": ["Using a single room reverb to place drums, bass, and guitars in one space", "Applying gentle glue compression on the mix bus to bind a rhythm section", "Aligning timing and tuning so overdubbed parts feel like one live take"]}, "276b7244-9ce6-4070-99c2-e289cb97c2f6": {"definition": "The degree to which each instrument and voice in a full-band mix can be clearly heard and distinguished, so individual parts remain audible within the group.", "plain_english": "It is how easily you can pick out each instrument in a busy song. Good intelligibility means you still hear the vocal, bass, and guitars without them turning into mush.", "purpose_function": "It is a mixing goal that keeps a dense arrangement clear, letting the listener follow the lead vocal and each key part.", "practical_application": "An engineer uses EQ carving, panning, and level balance to give each instrument its own frequency and stereo space so nothing masks the others.", "category": "Mix Quality", "related_terms": ["EQ carving", "Frequency masking", "Panning", "Ensemble cohesion", "Level balancing", "Frequency slotting"], "common_mistakes": ["Boosting every track to make it louder, which just increases masking and mud", "Piling instruments in the center instead of spreading them with panning", "Ignoring frequency overlap so instruments fight in the same range"], "scenario_contexts": ["Carving EQ so vocal, guitar, and keys each own a frequency band", "Panning instruments across the stereo field to separate a busy arrangement", "Balancing levels so the lead vocal stays clear over a full band"]}, "c704665a-ceac-4020-b96c-8c20455b1d41": {"definition": "Techniques for reducing unwanted squeaks and scrapes made by a player's fingers moving on strings, especially wound guitar or bass strings, during recording, using playing technique, string choice, mic placement, and editing or de-noising.", "plain_english": "It is how you cut down the squeaky sounds fingers make sliding on guitar or bass strings. You can fix it while playing, by moving the mic, or by editing the noises out later.", "purpose_function": "It keeps distracting finger squeaks from cluttering an otherwise clean recording, so the instrument's intended tone stays front and center.", "practical_application": "An engineer suggests flatwound or coated strings, angles the mic away from the fretting hand, and edits or automates down any remaining squeaks in the DAW.", "category": "Recording Technique", "related_terms": ["Mic placement", "Coated strings", "De-essing", "Editing", "Noise reduction", "DI recording"], "common_mistakes": ["Trying to EQ squeaks out, which also dulls the instrument's natural high end", "Placing the mic right at the fretting hand where finger noise is loudest", "Ignoring string choice, when coated or flatwound strings would cut the noise at the source"], "scenario_contexts": ["Recording a close-miked acoustic guitar where fret squeaks are obvious", "Editing finger slides out of an exposed fingerstyle bass take", "Choosing coated strings for a quiet, intimate acoustic session"]}, "d3c3f9c1-940c-472d-aab2-75f0d3475054": {"definition": "The signal processing applied to a drum kit's floor tom, typically EQ, gating or transient shaping, and compression, to control its low-frequency resonance and sustain and make it punch clearly through a mix.", "plain_english": "It is the shaping you do to the big low tom in a drum kit. You tighten its long boom and add punch so it hits hard without muddying the song.", "purpose_function": "It manages the floor tom's strong low end and long ring so its hits stay powerful and defined instead of booming over the rest of the kit.", "practical_application": "An engineer gates or shortens the tom's ring, boosts low-end thump and attack with EQ, and compresses it so fills cut through the mix.", "category": "Drum Processing", "related_terms": ["Noise gate", "Transient shaper", "Tom resonance", "Drum tuning", "Compression", "Parametric EQ"], "common_mistakes": ["Setting a gate too tight so the natural decay of the tom is chopped off unnaturally", "Boosting low end without cutting boxy mids, which leaves the tom muddy", "Ignoring cymbal and snare bleed in the tom mic while processing"], "scenario_contexts": ["Gating a floor tom to remove cymbal bleed between hits", "Adding low-end punch to a floor tom for a big rock fill", "Shortening a boomy tom's ring so it fits a tight, modern mix"]}, "c195a967-799d-40ac-b7dc-8323e194bd84": {"definition": "A doubling technique in which a copied vocal or instrument track is processed with a formant shift (moving the resonant timbral peaks up or down without changing pitch) and blended under the original to add width and thickness.", "plain_english": "It means copying a track and nudging its tone color a little, then mixing that copy under the first one. This makes the sound fuller and wider, like two slightly different voices singing as one.", "purpose_function": "It thickens and widens a part without retuning it, letting one performance sound like several stacked voices or instruments.", "practical_application": "An engineer duplicates a lead vocal, shifts the formant up or down with a pitch or formant plugin, and tucks the copy beneath the original to build a bigger chorus.", "category": "Layering technique", "related_terms": ["Vocal doubling", "Formant shifting", "Pitch shifting", "Gang-vocal stack", "Comping"], "common_mistakes": ["Shifting the formant too far, which makes the copy sound cartoonish or robotic", "Layering the copy too loud so it fights the lead instead of supporting it", "Forgetting to time-align the copy, which causes phasing or flamming"], "scenario_contexts": ["Thickening a lead vocal for a big chorus", "Building a wider backing-vocal bed from one take", "Adding size to a doubled guitar or synth line without retuning it"]}, "3acd5862-22ae-4682-b7fa-89de6efe7fff": {"definition": "The practice of minimizing the squeaks, string-slide sounds and finger noise produced on fretted string instruments during tracking, through playing technique, string choice, mic placement, and corrective editing or de-noising.", "plain_english": "Fret noise is the squeak you hear when fingers slide along guitar or bass strings. Controlling it means cutting down those squeaks while recording, or fixing them afterward, so they do not distract from the music.", "purpose_function": "It keeps distracting slide and finger noises from cluttering a recorded guitar or bass part while preserving a natural performance.", "practical_application": "A tracking engineer may suggest coated strings, adjust mic distance, or later ride the level down and use de-noise tools on isolated squeaks.", "category": "Tracking technique", "related_terms": ["Coated strings", "Microphone placement", "De-noising", "Volume automation", "Guitar automation"], "common_mistakes": ["Trying to remove every squeak until the part sounds lifeless and unnatural", "Heavy de-noising that also dulls the guitar's high end", "Blaming the mic when the real fix is the player's technique or old strings"], "scenario_contexts": ["Recording a quiet fingerstyle acoustic passage", "Cleaning up an exposed bass line before mixing", "Tracking a close-miked acoustic guitar in a solo section"]}, "4fe542d3-ef0b-47f7-815b-2f73471bd4c4": {"definition": "A layered group backing vocal built by recording several singers, or several passes of the same singers, shouting or singing a phrase in unison, then stacking the takes to create a large, crowd-like vocal.", "plain_english": "A gang vocal is a group of people singing or shouting the same line together, like a crowd chant. A gang-vocal stack layers many of these takes on top of each other so it sounds like a big group.", "purpose_function": "It creates the impression of a large crowd or group singing, adding energy and size to choruses and hooks.", "practical_application": "An engineer records a few singers several times around one mic, varying positions, then stacks and pans the takes wide for a full, anthemic chorus.", "category": "Layering technique", "related_terms": ["Backing vocals", "Vocal doubling", "Unison", "Panning", "Formant-offset layering"], "common_mistakes": ["Recording every pass identically, so the stack sounds thin instead of big", "Tuning gang vocals too tightly, which removes the natural human spread", "Stacking so many layers that the words become mushy and unclear"], "scenario_contexts": ["Building a crowd-style chorus for a punk or rock song", "Adding shouted hooks to a hip-hop or pop track", "Creating a chant feel in a bridge section"]}, "b5303d0c-8478-4f7f-9014-80a2c3e3eb5a": {"definition": "The use of automation (recorded, time-based changes to mixer or plugin parameters) applied to a guitar track, such as riding volume, panning, or effect levels across a song.", "plain_english": "Automation lets the software change settings on its own over time. On a guitar track it means you set those moves ahead of time, like turning it up in the solo or adding delay in the chorus.", "purpose_function": "It lets an engineer shape a guitar's level, position, and effects moment by moment instead of settling for one fixed setting.", "practical_application": "An engineer draws volume automation to lift a guitar during its solo and pull it back under vocals, or automates reverb sends between sections.", "category": "Mix automation", "related_terms": ["Volume automation", "Panning", "Fader ride", "Mix automation", "Guitar compression"], "common_mistakes": ["Writing jumpy automation that causes sudden, unnatural level jumps", "Automating volume when a compressor would do the job more smoothly", "Forgetting automation is active later and fighting it with new fader moves"], "scenario_contexts": ["Boosting a rhythm guitar under a solo section", "Panning a doubled guitar part during a breakdown", "Automating delay throws on the last word of a phrase"]}, "941bc750-7df0-453b-b143-b47a1afc758a": {"definition": "EQ or saturation processing that boosts or reinforces the low-midrange \"body\" of a guitar, roughly the 100-250 Hz region, to add warmth and fullness.", "plain_english": "The \"body\" of a guitar is its warm, full lower-middle tone. Enhancing it means gently boosting those frequencies so the guitar sounds richer and less thin.", "purpose_function": "It restores warmth and weight to a guitar that sounds thin, helping it feel full in the mix.", "practical_application": "An engineer boosts a few decibels in the low mids, or adds gentle saturation, to give a thin-sounding guitar more warmth and size.", "category": "EQ / tone shaping", "related_terms": ["Equalization", "Low mids", "Guitar boxiness reduction", "Guitar depth control", "Saturation"], "common_mistakes": ["Boosting body so much the guitar turns muddy and masks the bass", "Adding low-mid warmth without cutting boxiness, so the tone gets cluttered", "Enhancing body on every guitar, crowding the same frequency range"], "scenario_contexts": ["Warming up a thin single-coil rhythm track", "Adding fullness to a direct-recorded acoustic guitar", "Giving a small-amp recording more weight"]}, "4f794807-d6ea-40e7-bdd8-eda09bfd9bb8": {"definition": "Corrective EQ that cuts the honky, hollow \"boxy\" frequencies of a recorded guitar, typically in the 300-600 Hz range, to clear up the tone.", "plain_english": "\"Boxy\" is that hollow, cupped sound, like a guitar recorded inside a cardboard box. Reducing it means cutting those middle frequencies so the guitar sounds clearer and more open.", "purpose_function": "It removes a cluttered, cardboard-like quality so the guitar sits cleaner and more defined in the mix.", "practical_application": "An engineer sweeps a narrow EQ cut through the low mids to find the boxy peak, then dips it a few decibels.", "category": "EQ / tone shaping", "related_terms": ["Equalization", "Low mids", "Guitar body enhancement", "Notch filter", "Guitar cabinet resonance control"], "common_mistakes": ["Cutting too wide or too deep, leaving the guitar thin and lifeless", "Confusing boxiness in the low mids with harshness in the high mids", "Removing boxiness on a solo track without checking it in the full mix"], "scenario_contexts": ["Cleaning up a close-miked amp with a low-mid buildup", "Fixing a boomy acoustic recorded too close to a wall", "Tightening layered rhythm guitars that clutter the mids"]}, "215d8a25-e98d-4ebc-8d38-957b6729ddd7": {"definition": "The management of resonant frequency peaks produced by a guitar speaker cabinet, from its enclosed air and panel resonances, through mic placement, cabinet treatment, or corrective EQ.", "plain_english": "A guitar speaker cabinet has certain notes that ring out louder than others. Controlling that means taming those ringing frequencies with mic placement or EQ, so the tone stays even.", "purpose_function": "It evens out ringing peaks from the speaker cabinet so the recorded guitar tone stays balanced.", "practical_application": "An engineer moves the mic across the speaker cone, or notches the resonant frequency with EQ, to reduce a boomy or honky cabinet peak.", "category": "EQ / tone shaping", "related_terms": ["Cabinet miking", "Microphone placement", "Notch filter", "Resonance", "Guitar boxiness reduction"], "common_mistakes": ["Assuming a resonant peak is the room when it is the cabinet itself", "Notching so hard the guitar loses its natural character", "Fixing resonance with EQ when simply moving the mic would work better"], "scenario_contexts": ["Taming a boomy 4x12 cabinet in a small room", "Removing a ringing peak from a combo amp recording", "Balancing an open-back cabinet that emphasizes certain notes"]}, "60e41e43-ed51-4445-bc12-0d1b4558bdfc": {"definition": "Dynamic-range compression applied to a guitar signal, reducing the level difference between loud and soft notes to even out the performance and increase sustain.", "plain_english": "Compression makes the loud notes quieter and lets the soft notes catch up, so the playing sounds more even. On guitar it smooths the volume and helps notes ring on longer.", "purpose_function": "It evens out uneven picking or strumming and adds sustain, helping the guitar sit steadily in the mix.", "practical_application": "An engineer sets a moderate ratio with medium attack and release on a clean guitar to smooth its dynamics, or uses a stompbox compressor while tracking.", "category": "Dynamics processing", "related_terms": ["Compression", "Ratio", "Attack and release", "Sustain", "Guitar automation"], "common_mistakes": ["Over-compressing until the guitar sounds squashed and lifeless", "Using a fast attack that kills the pick attack and transients", "Adding heavy compression on top of an already-compressed amp tone"], "scenario_contexts": ["Smoothing a clean funk rhythm guitar", "Evening out fingerpicked acoustic dynamics", "Adding sustain to a clean arpeggiated part"]}, "ba314504-efaf-4868-ada3-f31190bb296c": {"definition": "The shaping of a guitar's perceived front-to-back position in a mix, its sense of depth, using reverb, delay, level, and EQ to place it closer or farther in the soundstage.", "plain_english": "Depth is how close or far a sound feels in a mix. Controlling a guitar's depth means using reverb, delay, and volume to push it forward or set it further back behind other parts.", "purpose_function": "It positions the guitar in the front-to-back space of a mix so it supports rather than crowds the other instruments.", "practical_application": "An engineer adds reverb and trims the highs to push a rhythm guitar back, or keeps it dry and forward for a lead line.", "category": "Mixing technique", "related_terms": ["Reverb", "Delay", "Depth of field", "Guitar body enhancement", "Panning"], "common_mistakes": ["Adding so much reverb the guitar washes out and loses definition", "Confusing depth, which is front-to-back, with panning, which is left-right", "Pushing every part back, leaving the mix distant and unfocused"], "scenario_contexts": ["Setting a rhythm guitar behind the lead vocal", "Placing an ambient guitar far back in a soundscape", "Keeping a solo guitar dry and up front"]}, "61a88a96-9fd3-4743-84de-670bf90aa3d8": {"definition": "Mixing a guitar's clean direct-injection (DI) signal with its amplified or otherwise processed signal, so the dry unaltered pickup tone and the coloured amp or effects tone combine into one balanced sound. The two paths are time- and phase-aligned so the sum stays clean.", "plain_english": "A DI blend mixes the clean guitar sound, taken straight from the guitar, with the fuller sound from its amp. This lets you keep the sharp pick attack while adding the amp's body and warmth.", "purpose_function": "It gives the engineer both the tight attack of the clean DI and the character of the amp, and it preserves an untouched DI so the tone can be re-amped or changed later.", "practical_application": "A tracking engineer splits the guitar to a DI box and to an amp with a mic, records both at once, then balances the two in the mix and nudges one slightly to fix any phase cancellation.", "category": "Guitar Recording", "related_terms": ["Direct injection", "Re-amping", "Phase alignment", "Amp miking", "Parallel processing"], "common_mistakes": ["Not time-aligning the DI and amp signals, so they partly cancel and sound thin", "Assuming a raw DI alone sounds like an amp, when it needs amp or cabinet processing to be usable", "Blending the two at full level without checking mono compatibility for phase problems"], "scenario_contexts": ["Recording an electric guitar with a DI box plus a miked amp so both are captured for later mixing", "Keeping a clean DI so a producer can re-amp the part through a different rig", "Adding clean DI under a heavily processed amp tone to restore pick attack and note clarity"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"a877fa10-7ce3-40dc-8070-59eb5c46f90c": {"definition": "Combining a distorted guitar signal with a cleaner or differently distorted version of the same part, so the blend keeps the grit and edge of the distortion while retaining the note definition and low-end clarity of the cleaner tone.", "plain_english": "This means mixing a gritty, distorted guitar sound with a cleaner take of the same part. The clean take keeps the notes clear while the distorted one adds bite and power.", "purpose_function": "It exists because heavy distortion can blur the pick attack and low end; adding a cleaner layer restores clarity while the distorted layer supplies aggression.", "practical_application": "A mix engineer runs a rhythm guitar through a clean channel and a distorted channel, or two different amp models, then balances them so chords stay defined without losing edge.", "category": "Guitar Recording", "related_terms": ["Distortion", "Parallel processing", "Guitar double tracking", "Gain staging", "Guitar equalization"], "common_mistakes": ["Adding so much distortion that low notes turn to mush before blending in a clean layer", "Leaving the two layers out of phase, which thins the combined tone", "Overpowering the clean layer so it adds no definition"], "scenario_contexts": ["Blending a clean DI under a distorted amp to keep chords defined in a dense mix", "Layering two distortion tones to get more sustain without extra mud", "Restoring low-end punch on a high-gain metal rhythm guitar"]}, "2a01851b-a482-446a-baf5-ea22762aaf95": {"definition": "Recording the same guitar part two or more separate times as independent performances, then panning the takes apart, often hard left and right, so the small natural timing and pitch differences between performances create a wider, thicker stereo image.", "plain_english": "Double tracking means playing and recording the same guitar part twice. Panning one take to the left and one to the right makes the guitar sound wider and fuller.", "purpose_function": "It widens and thickens guitars in a stereo mix; the tiny human differences between the two takes create width that a single copied track cannot.", "practical_application": "An engineer has the guitarist play a rhythm part twice, pans the two takes left and right, and checks that they lock tightly in time so the part stays clear.", "category": "Guitar Recording", "related_terms": ["Overdubbing", "Panning", "Stereo image", "Comping", "Guitar distortion blending"], "common_mistakes": ["Copying and pasting one take to both sides instead of a real second performance, which gives no true width", "Sloppy second takes that do not line up in time, blurring the part", "Panning both takes near the center, which cancels the widening effect"], "scenario_contexts": ["Tracking a rock rhythm guitar twice and panning hard left and right for a wide wall of sound", "Doubling a clean arpeggio part to add depth in a chorus", "Layering two distorted takes so the guitars fill the stereo field"]}, "7880b528-031e-454a-be69-6f57fd6136da": {"definition": "Equalization of a guitar signal in which the boost or cut in a chosen band changes automatically in response to the signal level in that band, so the EQ acts only when the target frequencies pass a set threshold rather than applying a fixed, constant amount.", "plain_english": "Dynamic EQ turns an EQ band up or down only when it is needed. For example, it can tame a harsh high note only on the loud chords, then leave the quieter parts alone.", "purpose_function": "It fixes problems that come and go, like an occasional harsh or boomy note, without permanently reshaping the tone the way fixed EQ would.", "practical_application": "An engineer sets a dynamic EQ band on a guitar to cut around 2 to 4 kHz only when the tone gets harsh, leaving the rest of the performance untouched.", "category": "Guitar Tone Shaping", "related_terms": ["Guitar equalization", "Multiband compression", "De-essing", "Guitar harshness reduction", "Threshold"], "common_mistakes": ["Setting the threshold so low that the band cuts constantly, acting like plain fixed EQ", "Using too wide a band, so nearby useful frequencies get pulled down as well", "Reaching for a fixed EQ cut when the problem only happens on some notes"], "scenario_contexts": ["Taming an occasional harsh upper-mid on a distorted rhythm guitar only when it spikes", "Controlling a boomy low note that rings out on certain chords", "Keeping a bright lead guitar smooth without dulling its quieter passages"]}, "66a164a3-08d7-4a55-bf20-bf73bdd861a1": {"definition": "The input channel or path that brings an effect's processed (wet) output back into the mixer or DAW, specifically the return carrying time-based or other effects applied to a guitar through an auxiliary or effects send.", "plain_english": "An effects return is the channel that brings a guitar's effect sound, like reverb or delay, back into the mix. The guitar is sent out to the effect, and the return is where that effect sound comes back.", "purpose_function": "It lets one effect unit be shared by several channels through sends, and it lets the returned wet signal be blended against the dry guitar without routing the whole channel through the effect.", "practical_application": "On a console or DAW the engineer sends the guitar to a reverb on an aux, then brings the reverb back on an effects return channel to set its level, EQ and pan.", "category": "Signal Routing", "related_terms": ["Auxiliary send", "Effects send", "Wet/dry balance", "Reverb", "Send and return"], "common_mistakes": ["Turning up the send with no return channel active, so no effect is heard", "Duplicating the dry signal into the return, which doubles the guitar instead of adding pure effect", "Forgetting to mute or manage feedback when routing a return back toward its own send"], "scenario_contexts": ["Bringing a shared reverb back on a return channel and blending it under the guitar", "Setting up a delay send and return so several tracks share one delay", "EQing an effects return to keep the wet reverb from clouding the mix"]}, "1423e6c0-8d9b-4f80-a8e9-887c90924f5b": {"definition": "Adjusting the relative levels of specific frequency bands in a guitar signal to shape its tone, for example cutting low-mid mud, boosting presence, or removing an offending resonance, using shelving, peaking, or filter EQ.", "plain_english": "Guitar EQ means turning certain pitch ranges of the guitar up or down to shape its sound. You might cut boomy lows or add some bite in the highs so the guitar sits well in the song.", "purpose_function": "It shapes a guitar's tone and carves space so the guitar fits with vocals, bass and other instruments without clashing.", "practical_application": "An engineer high-passes a rhythm guitar to clear low-end mud, then dips a boxy midrange so it sits neatly under the vocal.", "category": "Guitar Tone Shaping", "related_terms": ["High-pass filter", "Shelving filter", "Parametric EQ", "Guitar high-cut filtering", "Frequency masking"], "common_mistakes": ["Boosting many bands instead of cutting the ones that cause problems, which builds up level and harshness", "EQing a solo guitar to sound great alone, then finding it clashes in the full mix", "Using very narrow boosts that make the tone sound unnatural"], "scenario_contexts": ["High-passing a rhythm guitar to remove rumble and free up the low end for bass", "Cutting an ugly resonant frequency found by sweeping a boost", "Adding a gentle presence boost so a lead guitar cuts through the mix"]}, "2bc9971a-4a6b-479a-8d62-6cb39c4d0f6a": {"definition": "Attenuating the harsh, buzzy high-frequency content, typically above roughly 5 to 8 kHz, produced by distorted guitar tones and especially amp simulators, usually with a low-pass filter or high-shelf cut, to remove the fizzy edge while keeping useful presence.", "plain_english": "Fizz is the harsh, buzzy hiss on top of a distorted guitar, common with amp modelling. Fizz reduction cuts those very high frequencies so the tone sounds smooth instead of scratchy.", "purpose_function": "It makes distorted guitars, especially digital amp sims, sound smoother and more like a real miked cabinet, which naturally rolls off the extreme highs.", "practical_application": "An engineer places a low-pass filter around 6 to 10 kHz on a distorted guitar and adjusts by ear until the harsh top is gone but the tone stays clear.", "category": "Guitar Tone Shaping", "related_terms": ["Guitar high-cut filtering", "Low-pass filter", "Amp simulator", "Cabinet simulation", "Guitar harshness reduction"], "common_mistakes": ["Cutting so low that the guitar goes dull and lifeless", "Blaming fizz on the amp when a proper cabinet or speaker simulation would fix it", "Fixing fizz with a narrow notch instead of a smooth roll-off, leaving a ragged top end"], "scenario_contexts": ["Taming digital fizz on an amp-sim rhythm guitar to match a real cabinet sound", "Rolling off harsh highs on a high-gain lead so it is easier to listen to", "Cleaning up a re-amped distorted track that picked up extra buzz"]}, "4e127dee-ccbd-4883-aedd-3a43706d7664": {"definition": "Reducing the aggressive, ear-fatiguing energy in a guitar's upper midrange, often around 2 to 5 kHz, typically with a narrow EQ cut or dynamic EQ, to make the tone easier to listen to without dulling its presence.", "plain_english": "Harshness is a sharp, piercing sound some guitars have in the higher mid pitches. Reducing it means gently turning down those pitches so the guitar is easier on the ears.", "purpose_function": "It tames fatiguing frequencies that make a guitar sound painful or brittle, which improves how the guitar sits in a full mix.", "practical_application": "An engineer sweeps a narrow EQ boost to find the harshest spot around 3 kHz, then cuts there, or uses a dynamic EQ so the cut only acts on loud, harsh moments.", "category": "Guitar Tone Shaping", "related_terms": ["Guitar dynamic equalization", "Guitar equalization", "Guitar fizz reduction", "Notch filter", "Upper midrange"], "common_mistakes": ["Cutting too deeply, which leaves the guitar dull and buried in the mix", "Confusing upper-mid harshness with high-end fizz and cutting the wrong range", "Using a fixed cut for harshness that only appears on some notes, when dynamic EQ would be better"], "scenario_contexts": ["Softening a piercing 3 kHz edge on a distorted rhythm guitar", "Making a bright single-coil clean part easier to listen to", "Reducing fatigue on a lead guitar that sounds sharp on loud notes"]}, "ebda4bdf-2aa2-4406-9bd0-66b4f2cea0a4": {"definition": "Applying a low-pass (high-cut) filter to a guitar signal to progressively attenuate frequencies above a chosen corner frequency, removing unwanted high-frequency content such as hiss, fizz, or excessive brightness.", "plain_english": "A high-cut filter lowers everything above a set pitch, so the very high sounds are removed. On guitar it is used to take off hiss or harsh top so the tone is warmer.", "purpose_function": "It cleans up or darkens a guitar tone by removing highs that add hiss, fizz or harshness, or that clash with cymbals and vocals.", "practical_application": "An engineer sets a low-pass filter on a guitar track around 8 to 12 kHz to remove hiss and fizz, moving the corner lower for a warmer, more vintage tone.", "category": "Guitar Tone Shaping", "related_terms": ["Low-pass filter", "Guitar fizz reduction", "High-pass filter", "Guitar equalization", "Corner frequency"], "common_mistakes": ["Setting the corner too low, which makes the guitar dull and lifeless", "Confusing a high-cut (low-pass) with a high-pass filter and cutting the wrong end", "Using a very steep slope that removes air abruptly and sounds unnatural"], "scenario_contexts": ["Rolling off hiss and fizz on a distorted guitar for a smoother top end", "Darkening a bright guitar so it does not fight the cymbals and vocals", "Adding a gentle high-cut for a warm, vintage guitar tone"]}, "48e7ee8f-959d-40dc-878c-49d9b2168389": {"definition": "The practice of positioning recorded guitar parts at specific points across the stereo field — using panning, and where relevant stereo capture or width tools — so each guitar occupies a distinct location and the mix stays balanced from left to right.", "plain_english": "It means deciding where each guitar sits in the left-to-right stereo picture. Like seating players across a stage, you place one guitar a little left and another a little right so they do not clash.", "purpose_function": "It exists to give each guitar its own space in the stereo field, which improves clarity and makes a mix feel wide and organized instead of crowded in the center.", "practical_application": "A mixing engineer pans a rhythm guitar left and a doubled part right, or spreads a stereo-miked acoustic, then checks the placement in mono to confirm it still balances.", "category": "Stereo Imaging", "related_terms": ["Panning", "Guitar quad tracking", "Guitar layering (EF)", "Double tracking", "Mono compatibility"], "common_mistakes": ["Panning both guitars to the center so they mask each other and the mix sounds narrow.", "Placing guitars hard left and right without checking mono, so they thin out or drop on mono systems.", "Copying one part and hard-panning the copy, which is not true stereo width and can cause comb filtering."], "scenario_contexts": ["Mixing a rock song with two rhythm guitars that need to sit on opposite sides.", "Spreading a stereo-miked acoustic guitar in a singer-songwriter track.", "Checking a club PA in mono to confirm panned guitars still translate."]}, "fecdbdd8-9c47-4bd9-b994-be5fe70cca90": {"definition": "The technique of recording and combining several guitar parts — such as different takes, tunings, octaves, or clean and distorted tones — into one blended composite that sounds fuller and richer than a single track.", "plain_english": "Layering means stacking several guitar recordings on top of each other to make a bigger sound. It is like several people singing the same tune together instead of just one voice.", "purpose_function": "It exists to add thickness, width, and richness that a single recording cannot provide, and to blend different tones into one cohesive part.", "practical_application": "An engineer might record the same riff on an electric and an acoustic, then blend them so the acoustic adds attack and the electric adds body.", "category": "Arrangement", "related_terms": ["Double tracking", "Guitar quad tracking", "Guitar image placement", "Overdubbing", "Guitar microphone blend (EK)"], "common_mistakes": ["Layering too many parts until the arrangement turns muddy and cluttered.", "Stacking identical tones that add level but no real width or interest.", "Forgetting to check the layers in mono, where phase between them can cause cancellation."], "scenario_contexts": ["Building a wall of guitars for a chorus by stacking clean and distorted takes.", "Adding an octave or capo part under a main acoustic to thicken it.", "Blending a DI and a miked amp of the same performance."]}, "492ffb89-a273-497c-84ad-a39435917d2f": {"definition": "The use of a high-pass (low-cut) filter to attenuate low-frequency content below a guitar's useful range — typically rumble, handling noise, and low-end buildup — so the guitar sits cleanly without competing with bass and kick drum.", "plain_english": "It means using a filter to cut the deep low sounds out of a guitar track. That clears room for the bass and kick drum, so the low end does not turn into a muddy blur.", "purpose_function": "It exists to remove unwanted low rumble and free up the low end for instruments that belong there, keeping the mix tight and the guitar defined.", "practical_application": "On an electric rhythm guitar a mixer might set a high-pass filter around 80 to 120 Hz, listening so the body of the tone stays while the boom and rumble go.", "category": "EQ & Filtering", "related_terms": ["High-pass filter", "Guitar mud reduction", "Equalization", "Low-frequency buildup", "Guitar presence enhancement"], "common_mistakes": ["Setting the low-cut too high and thinning out the guitar's natural body.", "Applying the same cut frequency to every guitar regardless of its range.", "Skipping the low-cut and letting rumble and mud pile up with the bass and kick."], "scenario_contexts": ["Cleaning up an acoustic guitar that captured floor rumble and proximity boom.", "Tightening two distorted rhythm guitars so they do not clash with the bass.", "Removing stage or handling noise from a live electric feed."]}, "bca1d755-cd00-4b51-afd0-2c4b7bb1d1cf": {"definition": "The technique of mixing the outputs of two or more microphones placed on a guitar or its amplifier — or a mic combined with a direct signal — to build a composite tone with more control over body, attack, and air than any single mic provides.", "plain_english": "It means putting more than one microphone on a guitar and mixing them together. Each mic hears the guitar a bit differently. Blending them is like joining a few photos of the same thing into one better picture.", "purpose_function": "It exists to let the engineer shape tone by balancing mics that each capture a different part of the sound, and to add depth or width beyond a single microphone.", "practical_application": "A tracking engineer might blend a dynamic mic close on the speaker cone with a condenser set further back, checking phase and moving mics until the combined tone is right.", "category": "Microphone Technique", "related_terms": ["Phase alignment", "Close miking", "Guitar layering (EF)", "Direct injection (DI)", "Comb filtering"], "common_mistakes": ["Blending mics at different distances without checking polarity, causing phase cancellation and a thin, hollow tone.", "Assuming more mics always sound better instead of choosing what each one adds.", "Ignoring the 3-to-1 distance rule so bleed between mics smears the tone."], "scenario_contexts": ["Recording an electric guitar amp with a close dynamic and a room mic.", "Blending a DI and a miked cabinet for a reamped tone.", "Combining two mics on an acoustic to balance body and string detail."]}, "2e82965d-24c9-40d0-a044-10b35b9b286b": {"definition": "The practice of attenuating excess low-midrange energy on a guitar — commonly around the 200 to 500 Hz region — where buildup from many instruments makes the mix sound thick, boxy, or muddy, so the guitar stays clear and defined.", "plain_english": "It means turning down the boomy low-middle tones that make a guitar sound thick and cloudy. Clearing that range is like wiping fog off a window so you can hear the guitar clearly.", "purpose_function": "It exists to remove the frequency buildup where many instruments overlap, restoring clarity and separation so the guitar and the whole mix sound cleaner.", "practical_application": "An engineer sweeps an EQ band to find the boxy frequency, usually a few hundred Hz, and cuts a few dB, often carving different amounts on each guitar so they do not stack up.", "category": "EQ & Filtering", "related_terms": ["Equalization", "Guitar low-cut filtering", "Frequency masking", "Low-mid buildup", "Subtractive EQ"], "common_mistakes": ["Cutting so much low-mid that the guitar loses warmth and body.", "Boosting highs to fix mud instead of cutting the offending low-mid range.", "Making the same cut on every track rather than targeting where the buildup actually is."], "scenario_contexts": ["Cleaning up two layered rhythm guitars that sound thick together.", "Fixing a boxy acoustic recorded in a small room.", "Making space for vocals by carving low-mids out of dense guitars."]}, "8e459b6a-0b91-41a2-90f6-3676d1f61583": {"definition": "A dynamics technique that splits a guitar signal into separate frequency bands and compresses each independently, allowing control of the dynamics in one range — such as boomy lows or harsh highs — without affecting the others.", "plain_english": "It means splitting the guitar sound into low, middle, and high ranges and controlling the loudness of each one on its own. It is like having a separate volume knob for each part of the tone, so you can tame just the boomy or harsh bits.", "purpose_function": "It exists to even out problem frequency ranges that a normal single-band compressor would over-process, giving finer control over a guitar's balance and consistency.", "practical_application": "An engineer might set a multiband compressor to tame only the low-mids of a strummed acoustic that jump out on hard hits, leaving the rest of the tone untouched.", "category": "Dynamics Processing", "related_terms": ["Compression", "Guitar mud reduction", "Dynamic EQ", "Sidechain compression", "Multiband processing"], "common_mistakes": ["Compressing every band hard, which squashes the life out of the guitar.", "Reaching for multiband when a simple EQ cut or single-band compressor would do the job.", "Setting the band crossovers carelessly so the tone sounds disjointed."], "scenario_contexts": ["Controlling an acoustic where low strums spike but the high strings stay quiet.", "Taming harsh pick attack in one band without dulling the whole tone.", "Smoothing a bass-heavy DI guitar that fluctuates across a performance."]}, "c19a4ec1-9488-47f4-9c4d-332feab47f1c": {"definition": "The clarity and prominence of the pick's attack — the sharp transient produced as the plectrum strikes the strings — in a recorded or mixed guitar sound, often enhanced through mic choice, EQ, or transient shaping.", "plain_english": "It means how clearly you can hear the pick hitting the strings. Good pick definition is like hearing each footstep in a room instead of a soft blur, so the guitar sounds crisp and clear.", "purpose_function": "It exists to keep a guitar sounding articulate and rhythmic, so individual notes and strums cut through the mix instead of turning into a wash.", "practical_application": "To bring out pick definition an engineer may choose a brighter mic position, add a small boost in the upper mids and highs, or use a transient shaper to emphasize the attack.", "category": "Tone Shaping", "related_terms": ["Transient", "Guitar presence enhancement", "Transient shaping", "Attack", "Equalization"], "common_mistakes": ["Boosting highs so hard the pick attack becomes clicky and harsh.", "Over-compressing, which flattens the transient and buries the pick.", "Blaming the mix when a worn pick or dull strings are the real cause of a soft attack."], "scenario_contexts": ["Making a fingerpicked or flatpicked acoustic sound crisp in a busy mix.", "Bringing out palm-muted electric chugs so the rhythm stays tight.", "Restoring attack on a guitar that a heavy compressor softened."]}, "19c27adb-0033-4b83-8b11-12ffdc9ad5e0": {"definition": "The boosting or emphasis of a guitar's presence range — roughly 2 to 6 kHz — to increase clarity, attack, and forwardness so the instrument cuts through the mix and feels closer to the listener.", "plain_english": "It means lifting the upper-middle frequencies so the guitar sounds clearer and more up-front. It is like bringing someone a step closer so their voice stands out in a crowded room.", "purpose_function": "It exists to help a guitar stand out and feel present in a dense mix, improving the clarity of notes and attack without raising overall volume.", "practical_application": "A mixer adds a gentle EQ boost in the presence band, listening in the full mix so the guitar comes forward without becoming harsh or brittle.", "category": "EQ & Filtering", "related_terms": ["Presence", "Equalization", "Guitar pick definition", "Frequency masking", "Guitar mud reduction"], "common_mistakes": ["Boosting presence too much, making the guitar harsh and tiring to hear.", "Adding presence while soloing the track instead of in the full mix, so it ends up overdone.", "Pushing presence to fix a dull tone that really needs a better source or mic."], "scenario_contexts": ["Helping a rhythm guitar cut through a wall of instruments in a chorus.", "Bringing a solo forward so it sits above the backing tracks.", "Adding clarity to a dark-sounding humbucker recording."]}, "9d343e3d-8409-45ac-9808-269557c660c1": {"definition": "The technique of recording four separate performances of the same guitar part and distributing them across the stereo field — typically two panned hard left and two hard right — to create an especially wide, thick, and powerful guitar sound.", "plain_english": "It means playing the same guitar part four times. You then spread the four takes across the stereo picture. Each take is a bit different, so stacking them is like four players at once. That makes the sound huge and wide.", "purpose_function": "It exists to create maximum width and thickness for heavy or layered guitar sections, going beyond simple double tracking by using more independent performances.", "practical_application": "For a heavy chorus a producer records four takes of a riff, pans two hard left and two hard right, and balances them so the section sounds massive but still tight.", "category": "Tracking Technique", "related_terms": ["Double tracking", "Guitar layering (EF)", "Guitar image placement", "Panning", "Overdubbing"], "common_mistakes": ["Copying and pasting one take four times instead of playing separate performances, which gives no real width.", "Sloppy timing between takes that smears the rhythm instead of tightening it.", "Quad tracking parts that do not need it, cluttering the arrangement and eating headroom."], "scenario_contexts": ["Building a massive rhythm guitar bed for a metal or rock chorus.", "Widening a riff so the lead and vocals have room in the center.", "Reinforcing a breakdown section with layered, hard-panned guitars."]}, "b5afcead-27a3-454a-ba0c-ef71d76c5ba0": {"definition": "The blending of a re-amplified guitar signal (a recorded direct-input track sent back out through a reamp box into a real amplifier and re-recorded through a microphone) with the original direct signal or a second reamped pass, to combine their tonal characteristics in the mix.", "plain_english": "A clean guitar take can be played back through a real amp and recorded again. This trick lets you mix that fresh amp sound with the first clean take to build a fuller tone.", "purpose_function": "It lets an engineer shape or change a guitar's amp tone after tracking is finished, then set the exact ratio of amp character to direct sound without asking the player to perform the part again.", "practical_application": "An engineer feeds a stored direct-input track through a reamp box to an amp and microphone, records the result, then rides that returned track against the clean direct signal on a fader to taste.", "category": "Guitar Recording", "related_terms": ["Reamping", "DI box", "Double tracking", "Parallel processing", "Mic placement", "Guitar-bus processing"], "common_mistakes": ["Not recording a clean direct-input track during tracking, which leaves nothing to reamp later", "Feeding a line-level signal into an amp without a proper reamp box, causing impedance mismatch, hum, and possible input damage", "Failing to time-align and phase-check the reamped track against the original, which causes hollow or thin blends", "Blending in so much dry direct signal that the amp character is lost"], "scenario_contexts": ["Re-recording a scratch direct-input guitar through a favorite amp after the band has left the studio", "Blending a clean direct signal with a heavily distorted reamped tone to keep note definition in a metal rhythm", "Trying several amps on the same performance to find the best fit during mixing", "Adding a second reamped layer through a different cabinet to thicken a guitar part"]}, "63709f24-8deb-4030-aed3-f19a02493e92": {"definition": "The practice of taming unwanted resonant peaks in a guitar recording, such as boxy body resonances on acoustic guitar or ringing frequencies on electric, typically using narrow-band equalization cuts or dynamic EQ.", "plain_english": "Some notes on a guitar ring out louder than the rest and sound boomy or harsh. Resonance control finds those spots and turns them down so the tone stays even.", "purpose_function": "It smooths a guitar's frequency balance by removing peaks that jump out and mask other parts, so the instrument sits evenly in the mix rather than jumping forward on certain notes.", "practical_application": "An engineer sweeps a narrow EQ band to locate a ringing frequency and cuts it, or uses a dynamic EQ to reduce that frequency only on the notes where it becomes too loud.", "category": "Guitar Processing", "related_terms": ["Parametric EQ", "Dynamic EQ", "Notch filter", "Resonance", "Feedback", "Body resonance"], "common_mistakes": ["Cutting with too wide an EQ band, which removes desirable tone instead of just the problem resonance", "Boosting to find the resonance but forgetting to switch the band to a cut", "Over-cutting until the guitar sounds thin and lifeless", "Using a static cut when the resonance only appears on certain notes, where a dynamic EQ works better"], "scenario_contexts": ["Taming a boomy body resonance on a close-miked acoustic guitar", "Removing a ringing frequency from an electric guitar amp recording", "Controlling a resonant note that jumps out during a sustained chord", "Cleaning up low-mid buildup where several stacked guitar tracks reinforce the same frequency"]}, "8548a4cd-f0dd-49d5-8e56-802722936c98": {"definition": "Mixing the signal from a distant room microphone with a close-miked guitar amp signal to add natural space, depth, and ambience to the recorded tone.", "plain_english": "One mic sits close to the amp for a tight sound. Another mic across the room catches the natural echo. Blending the two adds a sense of space and size.", "purpose_function": "It lets the engineer control how live or roomy a guitar sounds by balancing dry close-mic detail against ambient room reflections, without relying on artificial reverb.", "practical_application": "While tracking, the engineer places a room mic several feet back, checks it for phase against the close mic, and rides its level to taste against the close signal.", "category": "Guitar Recording", "related_terms": ["Room mic", "Close miking", "Phase", "Ambience", "Reverb", "Parallel processing"], "common_mistakes": ["Not phase-checking the room mic against the close mic, which causes thin or hollow tone when the two are blended", "Adding too much room signal so the guitar loses focus and clarity", "Placing the room mic where it captures unwanted noise or bleed from other instruments", "Assuming the room blend can replace close-mic detail rather than complement it"], "scenario_contexts": ["Adding natural space to a close-miked amp in a good-sounding live room", "Blending room ambience into a rock rhythm guitar for depth", "Capturing a big room sound behind a lead guitar solo", "Using room mics to make a small guitar part feel larger without artificial reverb"]}, "d027b62f-91b2-4caa-ae4b-8de31870986f": {"definition": "The deliberate addition of harmonic distortion to a guitar signal, via tube, tape, transformer, or plugin emulation, to add warmth, harmonics, perceived loudness, and thickness.", "plain_english": "Pushing a guitar signal a little past clean adds a gentle grit and warmth. It makes the tone feel fuller and louder without a big jump in volume.", "purpose_function": "It enriches a guitar's harmonic content and softly rounds off peaks, helping the part feel thicker and cut through a dense mix.", "practical_application": "An engineer runs a guitar track through a tape or tube saturation plugin, adding drive until the tone thickens but before it becomes obviously distorted.", "category": "Guitar Processing", "related_terms": ["Harmonic distortion", "Tape saturation", "Overdrive", "Tube stage", "Distortion", "Drive"], "common_mistakes": ["Adding so much saturation that the tone becomes muddy or obviously distorted", "Using saturation to rescue a poorly recorded guitar instead of improving the source", "Not compensating for the level boost saturation adds, so the track seems better only because it is louder", "Applying heavy saturation on every track until the whole mix becomes harsh and fatiguing"], "scenario_contexts": ["Warming up a clean direct-input guitar with gentle tube saturation", "Thickening a thin-sounding rhythm guitar in a dense mix", "Adding harmonics so a guitar still reads on small speakers", "Using tape saturation to soften harsh pick attack on an acoustic"]}, "f50a4d1b-ff97-4645-bdb1-97459d0fcbbb": {"definition": "A mix bus that combines multiple guitar tracks onto a single set of faders so they can be level-controlled, processed, and routed together as one unit.", "plain_english": "When you have many guitar tracks, you can send them all to one extra fader. Moving that single fader turns every guitar up or down at once.", "purpose_function": "It simplifies control of a whole guitar section and allows shared processing, keeping the guitars balanced together while reducing the number of moves needed on the main mix.", "practical_application": "An engineer routes rhythm and lead guitar channels to a stereo subgroup, then adjusts the whole section's level or adds bus compression on that one path.", "category": "Signal Routing", "related_terms": ["Bus", "Auxiliary send", "VCA group", "Bus compression", "Signal routing", "Stem"], "common_mistakes": ["Confusing a subgroup, which audio actually passes through, with a VCA or aux, which behave differently", "Processing the subgroup heavily without realizing it affects every guitar routed to it", "Leaving individual track levels unbalanced before grouping, so bus moves cannot fix the internal balance", "Routing a guitar to both the subgroup and the main output at once, causing doubled signal and level errors"], "scenario_contexts": ["Combining rhythm, lead, and clean guitars onto one fader for easy level control", "Adding bus compression across all guitars to glue them together", "Muting the whole guitar section at once during an arrangement change", "Printing a guitar stem from the subgroup for a mix handoff"]}, "50432619-cad6-414f-b579-9f682bac0c59": {"definition": "Shaping the attack and sustain portions of a guitar signal, using a transient designer, compressor, or limiter, to emphasize or soften the initial pick attack.", "plain_english": "The sharp pluck at the start of each note is called the transient. Transient control lets you make that attack punchier or softer to fit the song.", "purpose_function": "It manages how much the pick attack pokes out, helping a guitar feel tighter or smoother and sit better against drums and other rhythm parts.", "practical_application": "An engineer uses a transient shaper to boost attack on a palm-muted rhythm for tightness, or reduces attack on a strummed acoustic that sounds too clicky.", "category": "Guitar Processing", "related_terms": ["Transient designer", "Compression", "Attack", "Sustain", "Limiter", "Envelope"], "common_mistakes": ["Over-boosting attack until the guitar sounds clicky and unnatural", "Using a slow compressor attack that squashes the transient by accident", "Reducing attack so much that a rhythm part loses its punch and drive", "Applying one transient setting across parts that each need different treatment"], "scenario_contexts": ["Tightening palm-muted rhythm guitar so each chug hits cleanly", "Softening a too-clicky strummed acoustic", "Adding attack to a buried guitar so it cuts through the mix", "Evening out inconsistent picking dynamics across a take"]}, "8d96e7a8-ae0e-4aab-8e32-66130e3be313": {"definition": "Adjusting the stereo spread of guitar tracks using panning, double-tracking, or mid-side techniques to set how wide or narrow they appear across the stereo field.", "plain_english": "This decides how far apart guitars sit between the left and right speakers. You can make them feel wide and spacious or pull them tight toward the center.", "purpose_function": "It controls the stereo image of the guitars so they fill the sides without crowding the vocal or bass, and helps keep the mix balanced and mono-compatible.", "practical_application": "An engineer hard-pans double-tracked rhythms left and right for width, or uses a mid-side tool to widen a single part while checking mono for phase problems.", "category": "Stereo Imaging", "related_terms": ["Panning", "Double tracking", "Mid-side processing", "Stereo field", "Mono compatibility", "Hard-panned doubles"], "common_mistakes": ["Over-widening with stereo tools until the guitars collapse or weaken when summed to mono", "Hard-panning a single mono guitar and expecting real stereo width from it", "Widening guitars so far that they clash with vocal or bass placement", "Forgetting to check mono compatibility for club and broadcast playback"], "scenario_contexts": ["Setting the stereo spread of double-tracked rhythm guitars", "Narrowing a wide guitar part so it stops fighting the vocal", "Widening a single clean guitar with a mid-side plugin", "Balancing guitar width against keys and backing vocals in the stereo field"]}, "c63297da-4e0b-4f82-a68f-4b49c51c2628": {"definition": "Applying processing such as EQ, compression, or saturation across the combined guitar bus rather than on individual tracks, in order to glue the guitars into a cohesive whole.", "plain_english": "Instead of treating each guitar track one by one, you process them all together on one channel. This helps the guitars sound like one solid, glued-together part.", "purpose_function": "It creates cohesion across multiple guitar tracks and applies shared tone or dynamics in one place, saving effort and helping the section move as a single unit.", "practical_application": "An engineer places a compressor and EQ on the guitar bus, using gentle gain reduction to glue the tracks and a broad EQ move to shape the whole section at once.", "category": "Bus Processing", "related_terms": ["Guitar subgroup", "Bus compression", "Glue compression", "Parallel processing", "Equalization", "Signal routing"], "common_mistakes": ["Over-compressing the bus so the guitars lose their dynamics and energy", "Trying to fix a single track's problem on the bus, where it cannot be isolated", "Stacking heavy processing on both the individual tracks and the bus, causing an over-cooked sound", "Not gain-staging the bus, so its plugins receive too hot a signal"], "scenario_contexts": ["Gluing several guitar tracks together with gentle bus compression", "Shaping the whole guitar section's tone with one EQ move", "Adding saturation across the guitar bus for cohesion", "Automating the guitar bus level to duck under a solo"]}, "c5c5d381-103a-4c17-860e-006ded382a15": {"definition": "A production technique in which two separately performed takes of the same guitar part are panned fully left and right to create a wide, thick stereo image.", "plain_english": "You record the same guitar part twice, then send one take far left and the other far right. The tiny differences between them make the guitars sound big and wide.", "purpose_function": "It widens and thickens rhythm guitars by using the natural performance differences between two takes, creating stereo width that a single panned track cannot produce.", "practical_application": "A guitarist plays a rhythm part twice; the engineer pans take one hard left and take two hard right, building a wide wall of guitars around the centered vocal.", "category": "Stereo Imaging", "related_terms": ["Double tracking", "Panning", "Stereo field", "Guitar width control", "Overdub", "Comping"], "common_mistakes": ["Copying one recorded take to both sides instead of using two separate performances, which gives no real width, only more volume", "Assuming hard-panned doubles are automatically mono-compatible; timing and phase differences can thin or comb-filter the guitars in mono", "Playing the two takes so tightly identical that the natural variation which creates width is lost", "Neglecting tuning between takes, so the doubled guitars sound out of tune with each other"], "scenario_contexts": ["Recording two takes of a rock rhythm and panning them hard left and right", "Creating a wide wall of guitars behind a centered lead vocal", "Doubling a riff to make it sound bigger than a single track", "Setting up a classic hard-rock stereo guitar arrangement"]}, "8197e78b-7747-4415-a866-d3b5ecd19eb3": {"definition": "The practice of placing two (usually double-tracked) rhythm guitar parts at or near the extreme left and right of the stereo field, one fully left and the other fully right. It produces a wide guitar image while leaving the center free for vocals, bass, kick and snare.", "plain_english": "This means sending two guitar tracks to far opposite sides, one all the way left and one all the way right. It makes the guitars sound wide and keeps the middle clear for the vocals and drums.", "purpose_function": "It widens the stereo image and separates the guitars from center-panned elements, so a dense rhythm-guitar sound does not mask the lead vocal, bass and drums. The technique relies on two separate performances rather than one signal split to both sides.", "practical_application": "An engineer records the same rhythm part twice, then pans take one hard left and take two hard right; on a mixer or DAW this is a pan control set to 100 percent L and 100 percent R. They check the balance in mono to confirm both sides still hold up.", "category": "Stereo Imaging", "related_terms": ["Double-tracking", "Panning", "Stereo image", "Rhythm guitar", "Mono compatibility"], "common_mistakes": ["Hard-panning a single guitar take, which leaves one side of the mix empty and lopsided", "Copying one performance to both sides instead of recording two takes, so the image collapses to the center and gains no real width", "Never checking the result in mono, where poorly captured double-tracks can partly cancel"], "scenario_contexts": ["Mixing a rock or metal song with two rhythm guitar tracks that need to sound wide", "Freeing up center space so a lead vocal and bass stay clear under heavy guitars", "Setting up a stereo guitar bed during tracking so overdubs can be panned apart"]}, "5a147ec1-6b84-4520-b743-bbb467364730": {"definition": "Backing-vocal harmony parts placed at or near the extreme left and right of the stereo field rather than in the center. This spreads the harmonies wide and keeps them separated from the center-panned lead vocal.", "plain_english": "Backing vocal parts are placed at the far left and far right, away from the center. This spreads them wide so they wrap around the main singer instead of crowding it.", "purpose_function": "It widens the vocal image and stops the harmony parts from competing with the lead vocal for the same center space, giving the arrangement depth and clarity. It works best when there are paired parts that can be balanced left against right.", "practical_application": "An engineer pans one harmony take hard left and its double or a second part hard right, then trims levels so neither side pulls the image off-center. They confirm the lead stays anchored in the middle and check mono balance.", "category": "Stereo Imaging", "related_terms": ["Backing vocals", "Panning", "Double-tracking", "Stereo image", "Lead vocal"], "common_mistakes": ["Hard-panning a single harmony part so one side of the stereo image is empty", "Panning harmonies so wide that they overpower and distract from the lead vocal", "Ignoring level differences between the two sides, which shifts the whole vocal image left or right"], "scenario_contexts": ["Widening a chorus by spreading doubled harmony vocals to the sides", "Keeping a lead vocal clear in the center while backing parts fill the edges", "Building a big layered vocal section in a pop or rock mix"]}, "34d5a9ab-9287-418c-9309-9956c034c98e": {"definition": "An arrangement technique that stacks multiple parts sharing related pitch or chord content, using different instruments, voices or registers to build a fuller, richer harmonic texture. The layered parts reinforce the same underlying harmony rather than adding new melodic lines.", "plain_english": "This means stacking several parts that share the same notes or chords to build a bigger, fuller sound. It is like adding more voices to a choir so the music feels thicker.", "purpose_function": "It adds weight, width and richness to a section by combining timbres that reinforce the harmony, so a part sounds larger than a single instrument or voice could. It gives the arranger control over how full or sparse a moment feels.", "practical_application": "A producer might stack a pad, a doubled guitar and a vocal harmony that all outline the same chord, choosing registers so the parts do not clash. During tracking they record complementary layers and balance them so each is felt but none dominates.", "category": "Arrangement", "related_terms": ["Double-tracking", "Harmony arrangement", "Voicing", "Overdub", "Arrangement"], "common_mistakes": ["Piling on too many layers in the same register, which turns a full sound into a muddy one", "Assuming more layers always sound bigger, when clashing pitches can shrink the impact", "Failing to spread layers across registers so they mask each other"], "scenario_contexts": ["Thickening a chorus by adding stacked instrument and vocal parts", "Building a lush pad-and-vocal texture behind a sparse verse", "Arranging overdubs so several parts reinforce one chord progression"]}, "440a93b3-3e56-4ccd-b8a0-333c24125805": {"definition": "The editing process of matching the timing (and often the tuning) of harmony parts to the lead or to each other, so note onsets, phrasing and consonants line up tightly. It is typically done with region editing, time-warping or pitch-correction tools.", "plain_english": "This means lining up the timing and tuning of backing vocals so they match the lead singer. Tight matching makes the parts sound like one blended group, not a sloppy crowd.", "purpose_function": "It makes stacked harmonies sound like a single cohesive unit by removing timing and tuning discrepancies that would otherwise smear the blend. Well-aligned parts sit together instead of flamming or drifting.", "practical_application": "An engineer nudges or time-warps harmony phrases so word endings and breaths hit at the same moment as the lead, and may apply gentle pitch correction so parts agree in tune. They listen for tight consonants and a unified stereo blend.", "category": "Editing", "related_terms": ["Comping", "Time alignment", "Pitch correction", "Backing vocals", "Double-tracking"], "common_mistakes": ["Over-editing until harmonies sound robotic and lose their natural human feel", "Aligning timing but ignoring tuning, so parts stay tight yet still clash pitch-wise", "Quantizing every consonant so hard that the vocals lose energy and phrasing"], "scenario_contexts": ["Tightening stacked backing vocals in a chorus so they lock to the lead", "Cleaning up doubled harmony takes that drift in timing", "Preparing layered vocals for a wide, blended mix"]}, "4269b1e9-6db0-49c3-a130-2d13e3d8fb1b": {"definition": "The compositional and production task of writing and organizing the supporting harmony parts around a main melody, including how many parts there are, their intervals, voicings and registers. It shapes how full, tense or open a section feels.", "plain_english": "This is the work of writing the extra vocal or instrument parts that sit above or below the main tune. You choose how many parts there are and which notes each one sings.", "purpose_function": "It gives a song depth and emotional lift by adding supporting pitches around the lead, and it controls the density of a section so a chorus can feel bigger than a verse. Good voicing keeps the parts clear rather than cluttered.", "practical_application": "An arranger decides where to add a third above or a sixth below the melody, how many stacked voices a chorus needs, and how to spread them across registers before parts are tracked. They may sketch the parts and have singers or players record each one.", "category": "Arrangement", "related_terms": ["Voicing", "Harmonic layering", "Backing vocals", "Counterpoint", "Arrangement"], "common_mistakes": ["Writing harmony parts in the same register as the lead so they crowd and mask it", "Adding harmonies everywhere, which removes the contrast that makes a chorus feel bigger", "Using intervals that clash with the underlying chords"], "scenario_contexts": ["Planning vocal harmony stacks before a tracking session", "Deciding how dense a chorus should be compared with the verses", "Arranging backing-vocal parts to lift the emotional peak of a song"]}, "0e4d4afc-49aa-4a44-8cdd-849721ac563d": {"definition": "The use of mix automation, such as volume, pan, mute or effect-send moves, applied to harmony tracks so their level and presence change over the course of a song. The moves are recorded in the DAW or console and replayed on every pass.", "plain_english": "This means writing moves that change the harmony tracks over time, like turning them up in the chorus and down in the verse. The computer replays those moves on every playback.", "purpose_function": "It lets the harmonies rise and fall with the arrangement, so they support the lead where needed and step back where they would clutter, without a human riding faders every time. It keeps balance consistent across the whole mix.", "practical_application": "An engineer draws or records automation to bring harmony vocals up in choruses, mute them in verses, or open a reverb send on a held note. They fine-tune the curves until the harmonies breathe with the song.", "category": "Mix Automation", "related_terms": ["Fader automation", "Mute automation", "Harmony bus", "Backing vocals", "Mixing"], "common_mistakes": ["Setting one static level for harmonies instead of automating them, so they either fight the verse or vanish in the chorus", "Making automation jumps so abrupt that levels audibly lurch", "Automating individual tracks when a single move on a harmony bus would be cleaner"], "scenario_contexts": ["Lifting backing vocals only during the chorus of a song", "Muting harmony tracks in verses to keep them clean", "Opening an effect send on a specific held harmony note"]}, "b9049e41-2a0f-49e4-ba55-93b1e647da9c": {"definition": "An auxiliary or subgroup bus to which all harmony tracks are routed so they can be processed and controlled together, for example with shared EQ, compression, effects or a single level fader. It groups the harmonies into one manageable stereo or mono submix.", "plain_english": "This is one channel that all the harmony tracks are sent to together. It lets you shape or turn up every harmony at once instead of one at a time.", "purpose_function": "It simplifies mixing by letting an engineer balance, process and automate the whole harmony group with one set of controls, and it can glue the parts together with shared processing. It also saves CPU and console channels compared with processing each track alone.", "practical_application": "An engineer routes every harmony track's output to an aux bus, then places a compressor and EQ on that bus and rides one fader for the group. They can send the whole bus to a shared reverb for a unified space.", "category": "Signal Routing", "related_terms": ["Bus", "Subgroup", "Aux send", "Harmony compression", "Mixing"], "common_mistakes": ["Processing each harmony track separately when bus processing would blend them better and save effort", "Forgetting that heavy bus compression affects every harmony at once, including quiet parts", "Routing dry and effected sends incorrectly so the bus double-counts a signal"], "scenario_contexts": ["Grouping a stack of backing vocals under one fader for easy balance", "Applying shared compression to glue harmony parts together", "Sending all harmonies to one reverb for a unified sense of space"]}, "9049c626-565a-436e-b1e8-d50ba9882ba1": {"definition": "Dynamic-range compression applied to harmony vocal tracks, either individually or across a harmony bus, to reduce the difference between loud and soft passages. It evens out levels so the stacked parts stay consistent and blend under the lead.", "plain_english": "This tames the loud and soft spots in backing vocals so they stay even. It helps the harmony parts blend and sit smoothly under the main singer.", "purpose_function": "It keeps harmony levels steady so quiet notes are not lost and loud ones do not jump out, which helps a stack of voices read as one controlled unit. It also lets the harmonies sit at a stable level beneath the lead vocal.", "practical_application": "An engineer sets a moderate ratio and threshold on each harmony track or on the harmony bus, adjusting attack and release so the parts stay natural while the peaks are tamed. They watch gain reduction and listen for a smooth, even blend.", "category": "Dynamics Processing", "related_terms": ["Compression", "Harmony bus", "Vocal compression", "Gain reduction", "Backing vocals"], "common_mistakes": ["Over-compressing until the harmonies sound squashed and lifeless", "Using fast settings that pump or dull the vocal transients", "Compressing every track hard and then again on the bus, stacking too much gain reduction"], "scenario_contexts": ["Evening out an uneven backing-vocal performance", "Gluing a harmony stack together with gentle bus compression", "Keeping harmonies at a steady level under a dynamic lead vocal"]}, "3c5621a0-45a2-4962-b461-5f64aa822014": {"definition": "De-essing applied to harmony vocal tracks, using a frequency-dependent compressor or dynamic EQ to reduce excessive sibilance in the 's', 'sh' and 't' sounds. It is often needed because stacked harmonies pile up sibilant energy that a single voice would not produce.", "plain_english": "This softens the harsh 's' and 'sh' sounds in backing vocals. When many voices sing together those sounds pile up, so this tool turns them down.", "purpose_function": "It controls the harsh, whistling sibilance that becomes exaggerated when several harmony parts sing the same words, keeping the stack smooth and easy to listen to. It preserves clarity without dulling the whole vocal.", "practical_application": "An engineer places a de-esser on each harmony track or the harmony bus, tunes it to the sibilant frequency band and sets the threshold so only the harsh peaks are reduced. They check that speech stays clear and the 's' sounds are softened, not lisped.", "category": "Dynamics Processing", "related_terms": ["De-esser", "Sibilance", "Harmony bus", "Harmony compression", "Backing vocals"], "common_mistakes": ["Setting the de-esser too aggressively so the vocals lisp and lose their consonants", "De-essing only the lead and forgetting the stacked sibilance from the harmony parts", "Targeting the wrong frequency band so real sibilance is missed while body is dulled"], "scenario_contexts": ["Taming harsh sibilance in a chorus full of stacked harmony vocals", "Smoothing bright backing vocals recorded with a condenser mic", "Cleaning up sibilant peaks on a harmony bus before final mix"]}, "7c079c71-a101-4c5c-8c2b-85abd344b561": {"definition": "The application of a delay (echo) effect to backing harmony vocals, producing timed repeats that add depth, movement, or stereo spread and set the harmonies apart in space from the lead vocal.", "plain_english": "This is an echo effect put on the backing singers. It repeats their voices so they sound wider and sit behind the main singer.", "purpose_function": "It adds space and size to harmony vocals and pushes them back in the mix, so they support the lead without crowding it or fighting for the same spot.", "practical_application": "An engineer sends the harmony bus to a delay return, usually timed to the song tempo, and blends in enough repeats to widen the backing while keeping the lead vocal dry and up front.", "category": "Vocal Processing", "related_terms": ["Harmony reverb", "Harmony stack", "Backing vocals", "Slapback delay", "Tempo-synced delay", "Send effect"], "common_mistakes": ["Using so much delay that the harmony words smear and become hard to understand", "Not tempo-syncing the delay, so the repeats clash with the groove", "Adding the same heavy delay to the lead vocal, which blurs the main line", "Letting delayed harmony tails cover the lead in the gaps between phrases"], "scenario_contexts": ["Adding tempo-synced delay to chorus harmony vocals to make the backing feel wide", "Using a short delay on a doubled harmony to thicken it", "Throwing a delay on the last word of a harmony phrase for a spacious tail", "Panning harmony delay repeats opposite the dry signal for a stereo effect"]}, "a8a12030-4156-4cef-9aed-d7127d6d1894": {"definition": "The automatic reduction of harmony vocal level when the lead vocal is present, usually driven by a sidechain compressor keyed from the lead, so the harmonies dip out of the way and rise again in the gaps.", "plain_english": "This turns the harmony singers down a little whenever the lead sings. The backing voices dip out of the way, then come back up in the gaps between lines.", "purpose_function": "It keeps the lead vocal clear and in front by making the harmonies step back automatically, so a dense backing arrangement never masks the main line.", "practical_application": "An engineer puts a compressor on the harmony bus and feeds the lead vocal into its sidechain, then sets the threshold and release so the harmonies drop a few decibels under the lead and recover between phrases.", "category": "Vocal Processing", "related_terms": ["Sidechain compression", "Harmony-to-lead balance", "Ducking", "Harmony subgroup", "Lead vocal", "Automation"], "common_mistakes": ["Setting too much gain reduction, so the harmonies pump and jump in level", "Using a release time so fast or slow that the ducking sounds unnatural", "Ducking off the wrong source instead of the lead vocal", "Relying on ducking to fix a balance that a simple level or arrangement change would solve better"], "scenario_contexts": ["Sidechaining dense chorus harmonies to the lead so the words stay clear", "Keeping oohs and aahs under a busy lead verse", "Making a thick vocal stack breathe around the main melody", "Automating extra duck depth only in the wordiest sections"]}, "6cc5cbd8-9ce1-45f0-9f4a-7703c1ce51c2": {"definition": "The use of equalization to shape the tone of backing harmony vocals, typically cutting or contouring frequencies so the harmonies blend under and support the lead vocal rather than competing with it.", "plain_english": "This means shaping the tone of the harmony voices with EQ. You cut or boost certain pitches so the backing blends smoothly under the main singer.", "purpose_function": "It carves room for the lead by trimming frequencies where harmonies would otherwise clash or build up, so a stacked backing sits as a smooth bed under the main vocal.", "practical_application": "An engineer often rolls off low end and dips presence or harsh mids on the harmony bus, leaving those bands stronger on the lead so the two parts occupy slightly different tonal spaces.", "category": "Vocal Processing", "related_terms": ["Equalization", "High-pass filter", "Harmony subgroup", "Harmony-to-lead balance", "Frequency masking", "Backing vocals"], "common_mistakes": ["EQing each harmony track differently so the stack loses its blend", "Leaving heavy low end on many stacked voices, causing mud", "Boosting the same presence range as the lead, which makes them fight", "Cutting so aggressively that the harmonies sound thin and lifeless"], "scenario_contexts": ["High-passing a harmony stack to clear low-end buildup", "Dipping harsh upper mids on backing vocals so they sit behind the lead", "Matching EQ across a group of harmony tracks for a unified tone", "Shaping oohs and aahs to sound smooth and distant under the lead"]}, "c873c977-e548-4b4a-bde9-0969767a949b": {"definition": "The application of reverberation to backing harmony vocals, adding a sense of space and depth; harmonies are often given more or longer reverb than the lead to place them further back in the mix.", "plain_english": "This adds a sense of room or space to the backing singers. More reverb makes the harmonies feel further away than the main singer.", "purpose_function": "It sets the harmonies back in the depth of the mix and glues stacked voices together, creating a sense of distance that keeps the lead vocal closer and clearer.", "practical_application": "An engineer routes the harmony bus to a reverb send, usually a longer or wetter setting than the lead vocal uses, and blends the return to push the backing into the background.", "category": "Vocal Processing", "related_terms": ["Reverb", "Harmony delay", "Harmony stack", "Send effect", "Predelay", "Depth of field"], "common_mistakes": ["Drowning the harmonies in reverb so words and pitch blur", "Using the same short reverb as the lead, so the harmonies never sit back", "Ignoring predelay, which can smear the attack of the voices", "Letting long reverb tails wash over the lead in quiet moments"], "scenario_contexts": ["Adding a longer plate reverb to chorus harmonies to set them behind the lead", "Gluing a wide vocal stack with a shared reverb", "Using a lush hall on distant background oohs", "Blending harmony reverb to add depth without losing intelligibility"]}, "a6d2c19d-06a9-428b-b461-0d4d32fea4a6": {"definition": "The deliberate addition of harmonic distortion, via tube, tape, transformer, or plugin emulation, to backing harmony vocals to add warmth, density, and perceived loudness and help the stack blend.", "plain_english": "This adds a bit of warm grit to the harmony voices. It makes them thicker and helps them melt into the track.", "purpose_function": "It thickens and glues harmony vocals by adding harmonics, so a stack sounds fuller and more cohesive and cuts through without simply being turned up louder.", "practical_application": "An engineer inserts a saturation or tape emulation on the harmony bus and drives it gently, adding harmonics and density while watching that the effect does not make sibilance or noise harsh.", "category": "Vocal Processing", "related_terms": ["Saturation", "Harmonic distortion", "Tape emulation", "Harmony stack", "Harmony subgroup", "Parallel processing"], "common_mistakes": ["Driving the saturation so hard that the harmonies sound fizzy or harsh", "Exaggerating sibilance and breath noise along with the wanted harmonics", "Saturating each track separately, which stacks up as unwanted grit", "Using saturation to fix a level balance that a fader move would solve"], "scenario_contexts": ["Adding light tape saturation to a harmony bus for glue and warmth", "Driving background vocals with a tube emulation to help them cut without volume", "Thickening a thin doubled harmony", "Using parallel saturation to keep the dry stack clean while adding density"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"0b91c4b7-c93e-4230-81c9-d264304f7b79": {"definition": "A layered arrangement of multiple recorded harmony vocal takes or parts, combined to build a fuller, wider, and more powerful backing than a single harmony line could provide.", "plain_english": "This is layering several harmony takes on top of each other. Many voices build a fuller, choir-like wall of sound.", "purpose_function": "It thickens and widens the backing vocals by combining many parts and takes, turning a thin single harmony into a rich, impactful section, usually reserved for choruses and big moments.", "practical_application": "A singer records each harmony part several times, and the engineer layers and pans these takes, often doubling or tripling each note of the chord to build a wide, dense stack.", "category": "Vocal Arrangement", "related_terms": ["Double tracking", "Harmony width", "Harmony subgroup", "Backing vocals", "Comping", "Unison stacking"], "common_mistakes": ["Stacking so many takes that the pitch and timing smear into mush", "Not tuning or timing the layers, so the stack sounds sloppy", "Using the identical take twice, which does not widen anything", "Building a huge stack in every section, leaving no contrast for the chorus"], "scenario_contexts": ["Tripling each chorus harmony note for a big, wide backing", "Layering oohs and aahs to create a choir-like pad", "Stacking octave harmonies to reinforce a hook", "Building a dense harmony stack only in the final chorus for lift"]}, "43b4a49c-3b22-4f9c-be4e-fd39d90285ea": {"definition": "A subgroup (bus) that all backing harmony vocal channels are routed to, allowing collective level control and shared processing of the harmonies as a single unit before they reach the main mix.", "plain_english": "This sends all the harmony tracks to one control channel. Then you can shape or turn down every harmony at once with a single fader.", "purpose_function": "It lets an engineer balance and process the whole harmony section together, so one fader, EQ, or compressor treats every backing voice as a unified group rather than adjusting each track separately.", "practical_application": "An engineer routes every harmony channel to one bus, then applies shared compression and EQ and rides that single subgroup fader to set the harmonies against the lead and the rest of the mix.", "category": "Signal Routing", "related_terms": ["Subgroup", "Bus", "Harmony-to-lead balance", "Bus compression", "Harmony equalization", "VCA group"], "common_mistakes": ["Processing each harmony track and the bus without checking the total, causing over-compression", "Forgetting to route a stray harmony channel, so it escapes the group processing", "Confusing an audio subgroup with a VCA group, which only links faders", "Squashing the whole bus so hard the harmonies lose all dynamics"], "scenario_contexts": ["Bussing all backing vocals to one subgroup for glue compression", "Riding a single fader to set harmonies against the lead", "Applying one EQ curve across the entire harmony section", "Muting the harmony subgroup to audition the mix without backing vocals"]}, "da63d5b5-bf8c-44e5-8e21-acb7bcd49421": {"definition": "The perceived stereo spread of backing harmony vocals, controlled through panning, layering, and stereo effects to make the harmonies sound broad and open across the stereo field.", "plain_english": "This is how wide the harmony voices spread across the stereo picture. Panning them left and right makes the backing feel big and open.", "purpose_function": "It creates a sense of size and separation for the backing vocals, opening space around a centered lead so the harmonies frame it without crowding the middle of the mix.", "practical_application": "An engineer pans doubled harmony takes to opposite sides, or uses stereo delay, reverb, and widening, to spread the backing wide while keeping the lead vocal focused in the center.", "category": "Vocal Arrangement", "related_terms": ["Panning", "Double tracking", "Harmony stack", "Stereo image", "Harmony delay", "Mono compatibility"], "common_mistakes": ["Widening with stereo effects that collapse or thin out when heard in mono", "Panning a single take rather than separate doubles, giving no real width", "Spreading harmonies so wide the center of the mix feels empty", "Ignoring mono compatibility, so phase issues weaken the vocals on club or phone speakers"], "scenario_contexts": ["Panning doubled chorus harmonies hard left and right for a wide backing", "Using stereo reverb to spread a harmony stack", "Checking harmony width in mono to confirm it holds up", "Narrowing verse harmonies and widening chorus harmonies for contrast"]}, "59185d83-6f16-43d4-b2ae-4bcb7e329182": {"definition": "The relative level relationship between backing harmony vocals and the lead vocal, set so the harmonies support and enrich the lead while the main melody stays clearly out in front.", "plain_english": "This is how loud the backing voices are next to the main singer. You set it so the harmonies support the lead without covering it.", "purpose_function": "It keeps the lead vocal as the focus while letting the harmonies add fullness and emotion, finding the point where the backing is felt and heard but never masks the main line.", "practical_application": "An engineer rides the harmony fader or subgroup against the lead, often pulling harmonies back in verses and letting them come up in choruses, and checks the balance on several playback systems.", "category": "Mix Balance", "related_terms": ["Harmony subgroup", "Harmony ducking", "Lead vocal", "Level balance", "Automation", "Backing vocals"], "common_mistakes": ["Mixing harmonies so loud they compete with or bury the lead", "Setting one static balance instead of adjusting between verse and chorus", "Judging the balance only on studio monitors, not on phones or car speakers", "Turning harmonies up to fix a tone problem that EQ would solve better"], "scenario_contexts": ["Pulling harmonies down in the verse and up in the chorus", "Automating harmony level so the lead stays clear in busy sections", "Setting backing-vocal level against the lead during a mix", "Checking the harmony-to-lead balance on multiple playback systems"]}, "5e6a6352-008a-4bc4-887f-2c53bd8e393c": {"definition": "A sharp, cutting, aggressive attack character in a hi-hat's sound, produced by striking it hard or with the two cymbals held slightly open so they rebound against each other. Engineers use the term to describe a hi-hat that projects an edgy, forward high-mid and high-frequency bite in a recording.", "plain_english": "Bark is the sharp, snappy crack a hi-hat makes when it is hit hard or left a little open. It cuts through a mix the way a dog's bark cuts through other noise.", "purpose_function": "The term gives players and engineers a way to talk about how aggressive or cutting a hi-hat's attack sounds. Shaping the amount of bark helps a hi-hat sit right in a busy arrangement.", "practical_application": "A tracking engineer may angle or move the hi-hat mic, or ask the drummer to play more closed, to add or tame bark. In the mix, EQ around the high-mids and highs controls how much bark comes through.", "category": "Cymbal Tone", "related_terms": ["Hi-hat opening", "Hi-hat bleed", "Cymbal wash", "Transient", "High-frequency reinforcement"], "common_mistakes": ["Piling on high-frequency EQ to force bark, which also lifts hiss and mic bleed from other drums.", "Blaming the hi-hat mic for a harsh bark when the sound is really bleed from the overhead mics.", "Confusing bark (an aggressive attack tone) with wash (the sustained shimmer of an open hi-hat)."], "scenario_contexts": ["A metal drummer plays a tight, hard hi-hat and the engineer wants extra bark to cut through distorted guitars.", "During mixing a hi-hat sounds dull, so the engineer lifts the high-mids to bring back its bark.", "A producer asks the drummer to play the hi-hat slightly open to add bark to a chorus."]}, "0003c0f8-e86c-475c-9f6d-ed0278dfd17a": {"definition": "Hi-hat sound that leaks into microphones other than the dedicated hi-hat mic, most often the snare, tom, and overhead mics, because the hi-hat sits close to them and is loud and bright. It is a common form of microphone spill in drum recording.", "plain_english": "Bleed is hi-hat sound sneaking into the other drum mics, not just its own. It is like one person's voice getting picked up by everyone's phone on a group call.", "purpose_function": "Naming this spill helps engineers plan mic placement and mixing so the hi-hat does not smear the whole kit. Managing it keeps each drum clean and separately controllable.", "practical_application": "Engineers cut hi-hat bleed by using tight cardioid or hypercardioid mics, aiming a mic's null at the hi-hat, and gating or editing tracks. Heavy snare EQ or compression at mixdown can expose bleed, so it is checked early.", "category": "Mic Bleed", "related_terms": ["Snare bleed", "Microphone spill", "Overhead microphones", "Noise gate", "Off-axis rejection", "Hi-hat bark"], "common_mistakes": ["Assuming a gate fully removes hi-hat bleed from the snare track, when fast snare hits often open the gate and let bleed through.", "Boosting snare-mic highs without noticing it also lifts the bleeding hi-hat.", "Pointing the snare mic straight at the hi-hat instead of using its off-axis null to reject it."], "scenario_contexts": ["A close snare mic picks up so much hi-hat that soloing the snare sounds like a hi-hat track.", "During overdubs a loud hi-hat bleeds into the tom mics and muddies the fills.", "An engineer aims the snare mic's rear null toward the hi-hat to cut bleed at the source."]}, "9bb5623b-f3c9-4cff-b4a4-aee27a8a31e5": {"definition": "A small clamp assembly, threaded onto a hi-hat stand's upper pull rod, that grips the top cymbal between felt washers so it moves up and down with the foot pedal. It sets the top cymbal's playing height and how tightly it meets the fixed bottom cymbal.", "plain_english": "The clutch is the clamp that holds the top hi-hat cymbal onto the moving rod. It works like a nut and washers that grip the cymbal so the pedal can lift it and drop it.", "purpose_function": "It connects the top cymbal to the pedal mechanism so the drummer can open and close the hi-hat, and it sets playing height and cymbal tension. Without it the top cymbal could not be controlled by the foot.", "practical_application": "A drum tech tightens the clutch's felts and locknut so the cymbal does not slip or rattle, and adjusts the height for the player. A loose clutch is a common cause of buzzes and an inconsistent chick sound during tracking.", "category": "Drum Hardware", "related_terms": ["Hi-hat stand", "Hi-hat opening", "Drop clutch", "Cymbal felt", "Pull rod", "Hi-hat pedal"], "common_mistakes": ["Over-tightening the clutch against the cymbal so it chokes the sound and can crack the cymbal over time.", "Leaving the locknut loose, letting the clutch spin down during play and slowly closing the hi-hat.", "Forgetting the felt washers, so metal touches the cymbal and causes buzzing or edge cracks."], "scenario_contexts": ["Between takes a drum tech resets a slipped clutch that let the hi-hat close on its own.", "A drummer fits a drop clutch to lock the hi-hat closed for two-handed double-bass sections.", "Setting up a kit, the tech dials in hi-hat height and felt tension using the clutch."]}, "0b7d70c7-fec8-498f-80ad-425efa14a603": {"definition": "The distance the two hi-hat cymbals are held apart, controlled by pedal pressure or stand adjustment, which sets how loosely they vibrate together and how much sustain and wash the hi-hat produces. It ranges from fully closed (a tight chick) to fully open (a loose, sizzling sound).", "plain_english": "Opening is how far apart the two hi-hat cymbals are held. A small gap gives a tight tick, and a big gap gives a loud, splashy sizzle, like a light clap versus a hard one.", "purpose_function": "It lets the drummer vary the hi-hat's tone and loudness within a groove, from crisp closed notes to open accents. Engineers care because it changes level, brightness, and how much the hi-hat spills into other mics.", "practical_application": "During tracking an engineer may ask for a more closed hi-hat to get a cleaner sound with less bleed. Big openings raise the level and wash, so faders, gates, and automation must allow for them.", "category": "Hi-hat Technique", "related_terms": ["Hi-hat clutch", "Hi-hat bleed", "Cymbal wash", "Hi-hat bark", "Hi-hat pedal", "Dynamics"], "common_mistakes": ["Recording big open-hat accents at the same level as closed notes, causing sudden peaks and clipping.", "Setting a gate for the closed hi-hat, then cutting off open notes when their longer sustain trips it shut.", "Confusing hi-hat opening (cymbal spacing) with the clutch, which is the hardware that holds the cymbal."], "scenario_contexts": ["A drummer opens the hi-hat on the last beat of each bar for a splashy accent the engineer must ride.", "To reduce bleed, the producer asks for a tighter, more closed hi-hat during a quiet verse.", "An engineer writes automation to tame loud open-hat notes that jump out of the groove."]}, "c55d463a-3d31-48cc-b3c3-2a4340fc57f6": {"definition": "The deliberate boosting or supplementing of a signal's upper-frequency content, roughly above 5 to 8 kHz, using EQ, a harmonic exciter, or added program material to improve clarity, presence, and air. In a mix it strengthens fine detail such as cymbal shimmer, breath, and string or pick attack.", "plain_english": "This means adding or boosting the very high sounds in a track to make it crisper and more detailed. It is like turning up the treble so the top-end sparkle stands out.", "purpose_function": "It exists to recover or emphasize the brightness and detail that make a sound feel clear and open, especially when recording chains or dull sources soften the top end. Used well, it helps a part cut through a full band mix.", "practical_application": "An engineer adds a gentle high-shelf boost or an exciter to acoustic guitar, vocals, or drum overheads to bring back sparkle. It is used sparingly because too much lifts hiss, sibilance, and cymbal harshness.", "category": "Tone Shaping", "related_terms": ["Instrument air enhancement", "Equalization", "Harmonic exciter", "High-shelf filter", "Presence", "De-essing"], "common_mistakes": ["Boosting highs so hard that hiss, sibilance, and cymbal harshness become obvious.", "Adding top end to a noisy source instead of first fixing the noise or the dull recording.", "Reinforcing highs on every track, which stacks up into a harsh, tiring mix."], "scenario_contexts": ["A dull-sounding vocal gets a high-shelf lift so its consonants and breath read clearly.", "Overheads recorded with a soft mic get an exciter to restore cymbal sparkle.", "An acoustic guitar needs more pick detail to cut through a dense arrangement."]}, "dd5d0cf6-b330-4e9b-b614-2a8e2fd38f51": {"definition": "Boosting the extreme top end of an instrument, typically a broad, gentle lift above about 10 kHz (the air band), to add openness, sheen, and a sense of space. It is usually done with a high-shelf EQ or a dedicated air band on a channel or plugin.", "plain_english": "This is adding a touch of the highest, airiest sounds to an instrument so it feels open and spacious. It is like opening a window to let a room breathe.", "purpose_function": "It exists to give a source a polished, hi-fi sense of space without changing its core tone. A little air makes vocals and acoustic instruments feel expensive and close.", "practical_application": "Engineers use a broad high-shelf around 10 to 16 kHz, or a mastering-style air EQ, on vocals, acoustic guitar, and overheads. It is dialed in gently while listening for added hiss or sibilance.", "category": "Tone Shaping", "related_terms": ["High-frequency reinforcement", "Equalization", "High-shelf filter", "Presence", "Harmonic exciter", "Instrument articulation enhancement"], "common_mistakes": ["Adding air to a hissy or noisy track, which makes the noise stand out.", "Confusing air (very top-end openness) with presence (upper-mid clarity around 3 to 5 kHz).", "Pushing the air band so far that vocals turn sibilant and cymbals get brittle."], "scenario_contexts": ["A lead vocal sounds closed-in, so the engineer adds a gentle air-band lift for sheen.", "An acoustic guitar needs a more open, expensive top end in a sparse ballad.", "A mix bus gets a touch of air to make the whole record feel more spacious."]}, "1682248f-ab66-4f11-b01f-347fc4189c25": {"definition": "The balancing of an instrument's close-mic signal against room or ambient microphone signals to control how much natural space and reverberation is heard. Blending in more ambience adds depth and size, while less keeps the sound tight and dry.", "plain_english": "This is mixing the close-up mic with a room mic to decide how roomy an instrument sounds. It is like choosing how much of the room's echo you let into the recording.", "purpose_function": "It exists to place an instrument in a believable space and add depth without artificial reverb. The blend sets how big and live, or tight and controlled, the source feels.", "practical_application": "An engineer rides the level of room mics against close mics on drums, guitar amps, or piano to taste. Room mics can be compressed for extra size, and their timing is checked for phase against the close mics.", "category": "Room Sound", "related_terms": ["Room microphone", "Close miking", "Reverberation", "Phase", "Overhead microphones", "Instrument air enhancement"], "common_mistakes": ["Blending in room mics without checking phase, which thins or hollows the close-mic sound.", "Adding so much ambience that the instrument loses punch and sits too far back.", "Confusing natural room-mic ambience with plugin reverb added after the fact."], "scenario_contexts": ["A drum kit needs more size, so the engineer brings up compressed room mics under the close mics.", "A guitar amp sounds too dry, and a blend of a distant mic adds natural space.", "Tracking piano, the engineer balances close and room pairs for the right sense of depth."]}, "5a9a1c99-949f-4032-9da1-2711c05463e9": {"definition": "Processing that makes an instrument's note attacks and note-to-note definition clearer, so individual notes and rhythms are easy to follow. It is commonly done with transient shaping, attack-friendly compression settings, or EQ that lifts the attack region.", "plain_english": "This means making the start of each note sharper and easier to hear, so playing sounds clear and defined. It is like sharpening the edges of the sound so notes do not blur together.", "purpose_function": "It exists to keep fast or detailed parts intelligible in a busy mix, where soft or smeared attacks would get lost. Clear articulation helps rhythms lock and melody lines stay readable.", "practical_application": "An engineer uses a transient shaper or a slower compressor attack to emphasize pick, mallet, or key strikes, or lifts EQ around the attack frequencies. It is common on bass, acoustic guitar, and percussive keys.", "category": "Transient Shaping", "related_terms": ["Transient shaping", "Compression", "Attack time", "Equalization", "High-frequency reinforcement", "Instrument air enhancement"], "common_mistakes": ["Setting a fast compressor attack that squashes transients and dulls articulation instead of sharpening it.", "Over-emphasizing the attack until notes click and sound unnatural.", "Trying to fix a muddy arrangement with attack EQ instead of fixing masking between parts."], "scenario_contexts": ["A fingered bass line disappears in the mix, so the engineer shapes its transients to define each note.", "Fast acoustic-guitar strumming needs clearer pick attack to cut through a band.", "A synth part's soft attacks blur, so a transient shaper adds definition."]}, "4eebcf4b-c60b-43f9-90c7-28735b798bb6": {"definition": "The recording and automatic playback of parameter changes, such as volume, pan, mute, or plugin settings, on an instrument track over the course of a song. In a DAW these moves are drawn or written as automation data and replayed exactly on each pass.", "plain_english": "Automation lets the software record and replay changes to a track. It can turn a part up in the chorus or move it across the mix during a fill. It works like a player piano that repeats your fader moves the same way every time.", "purpose_function": "It exists so mix moves happen the same way every time and hands-free, letting one engineer control many changes across a whole song. It turns a static mix into one that breathes with the arrangement.", "practical_application": "Engineers write volume rides to keep a part even, automate mutes to clean up unused sections, and sweep filter or effect settings for transitions. Moves are drawn with the mouse or recorded live from a fader and then fine-tuned.", "category": "Mix Automation", "related_terms": ["Volume automation", "Fader ride", "DAW", "Mute automation", "Plugin automation", "Instrument articulation enhancement"], "common_mistakes": ["Leaving a track in write or latch mode and accidentally overwriting good automation.", "Automating a plugin, then changing the plugin so the saved moves point at the wrong parameter.", "Drawing choppy volume jumps that click instead of smooth ramps."], "scenario_contexts": ["An engineer automates a guitar to rise slightly in the chorus and drop back in the verse.", "Mute automation cleans up an instrument track between its parts to remove bleed and noise.", "A filter sweep is automated to build tension into a drop."]}, "34f5ad12-f475-4cf5-94c0-8a27db726271": {"definition": "The use of delay-based processing on an instrument track to position it within a mix, controlling its perceived depth and stereo width by adjusting delay time, feedback, and level against the dry signal.", "plain_english": "This means using short echoes to set where an instrument seems to sit. A small delay can push a sound back or spread it wider. It is like giving each player some space so the band does not feel crowded.", "purpose_function": "It gives each instrument its own place in the front-to-back and left-to-right space of a mix, cutting clutter and adding a sense of depth.", "practical_application": "An engineer adds a short slap or stereo delay to a rhythm guitar so it sits behind the lead parts and spreads across the stereo field without raising its fader.", "category": "Spatial Placement", "related_terms": ["Instrument panning", "Instrument image stability", "Slapback delay", "Reverb send", "Dry/wet balance"], "common_mistakes": ["Setting delay times so long that they blur the timing and push the instrument too far back", "Using too much feedback, so repeats build up and clutter the mix", "Not matching delay time to the song tempo, so echoes fight the groove"], "scenario_contexts": ["Adding a tempo-synced delay to a rhythm guitar to place it behind the lead vocal", "Using a stereo delay to widen a mono keyboard part", "Applying a short slapback to a snare to give it depth in a live-tracked band mix"]}, "d475bbec-3e35-47fa-9725-91aac3d24bf4": {"definition": "The combining of an instrument's direct (DI) signal with a miked amplifier or acoustic signal, mixed in proportion to shape tone and control transients and low-end.", "plain_english": "A DI takes the clean sound straight from the instrument, while a mic catches the sound from the amp or room. Blending them keeps the punch of the clean signal and the warmth of the mic. It is like mixing a close-up photo with a wider one to get the best of both.", "purpose_function": "It joins the clarity and low-end of the direct signal with the character of a miked source, giving fuller control over an instrument's recorded tone.", "practical_application": "When tracking bass, an engineer records the DI and a miked cabinet on separate tracks, then blends them for tight lows from the DI and grit from the amp.", "category": "Signal Blending", "related_terms": ["Instrument microphone blend", "Instrument phase coherence", "Direct box", "Reamping", "Impedance matching"], "common_mistakes": ["Blending DI and mic tracks without checking phase, causing thin or hollow tone", "Recording both to one track, so the blend cannot be adjusted later", "Relying only on the DI and losing the character of the amp"], "scenario_contexts": ["Recording bass with a DI and a miked cabinet, then balancing the two", "Blending a piezo pickup with a mic on an acoustic guitar", "Keeping a clean DI take of an electric guitar for reamping alongside the miked amp"]}, "a0ead9df-32b0-4305-9c01-d9c22eb110d0": {"definition": "The manual adjustment of an instrument's gain or fader level over time during tracking or mixing to keep its level consistent or to emphasize particular passages.", "plain_english": "Some parts of a performance are louder or softer than others. Riding the gain means moving the level up and down by hand to smooth them out. It is like turning the radio up in a quiet song and down in a loud one.", "purpose_function": "It evens out level changes that a compressor cannot handle musically, keeping an instrument sitting steadily in the mix.", "practical_application": "An engineer rides the fader on a bass track, nudging quiet notes up and loud notes down so every note is heard clearly.", "category": "Level Control", "related_terms": ["Fader automation", "Compression", "Gain staging", "Instrument masking control", "Dynamic range"], "common_mistakes": ["Riding gain so aggressively that the natural dynamics disappear", "Making moves too late, so they miss the note they were meant to fix", "Confusing gain riding with compression and using neither well"], "scenario_contexts": ["Smoothing an uneven bass performance before adding a compressor", "Lifting quiet words in a vocal so they stay intelligible", "Pulling down a loud strum in an acoustic guitar part during tracking"]}, "88b0cc7b-7322-4f36-92a1-7ce848bd1f39": {"definition": "The degree to which an instrument holds a consistent, well-defined position in the stereo image, without wandering or collapsing when the mix is summed to mono or played on different systems.", "plain_english": "In a stereo mix, each instrument should stay in one clear spot. Image stability means it does not drift or smear from side to side. It is like a singer standing still on stage instead of pacing around.", "purpose_function": "It gives listeners a solid, believable stereo picture where each part has a fixed place, which also helps the mix survive mono playback.", "practical_application": "When blending two overhead mics on a drum kit, an engineer checks phase and panning so the kit stays centered and stable rather than shifting.", "category": "Stereo Imaging", "related_terms": ["Instrument panning", "Instrument phase coherence", "Mono compatibility", "Stereo width", "Instrument delay placement"], "common_mistakes": ["Panning stereo tracks too wide, so the center image falls apart in mono", "Ignoring phase between mic pairs, which smears the position", "Adding heavy stereo effects that make the instrument wander"], "scenario_contexts": ["Checking a mix in mono to confirm instruments hold their place", "Balancing a stereo overhead pair so the drum kit stays centered", "Setting the width of a stereo synth so it does not smear across the mix"]}, "92a8b357-1592-4bba-a660-565e32231e5e": {"definition": "The combining of two or more recorded parts of the same or complementary instruments to create a fuller, thicker, or more complex result than a single take.", "plain_english": "Layering means stacking more than one recording of a part on top of each other. Two guitars playing the same riff sound bigger than one. It is like a choir sounding fuller than a single singer.", "purpose_function": "It builds size, width, and richness in an arrangement by combining sounds that reinforce one another.", "practical_application": "A guitarist double-tracks the same rhythm part, and the engineer pans the two takes left and right to widen and thicken the sound.", "category": "Arrangement", "related_terms": ["Double-tracking", "Instrument panning", "Instrument masking control", "Instrument phase coherence", "Overdub"], "common_mistakes": ["Layering so many parts that the mix becomes cluttered and loses clarity", "Stacking identical takes that phase-cancel instead of widening", "Not tuning or time-aligning layers, so they clash"], "scenario_contexts": ["Double-tracking a rhythm guitar and panning the takes wide", "Stacking a synth pad under a piano to thicken a chorus", "Adding a second harmony vocal to build a fuller backing part"]}, "eee0a18b-b535-46a0-9663-bfd0a01c0cdb": {"definition": "The management of frequency masking, where one instrument's energy hides another's in the same frequency range, using EQ, arrangement, panning, and level to keep each part audible.", "plain_english": "When two instruments use the same pitches, one can hide the other. Masking control means making room so both can be heard. It is like two people talking at once, so you ask one to change their tone.", "purpose_function": "It keeps every instrument clear and present by stopping parts from covering each other in shared frequency ranges.", "practical_application": "An engineer notices the bass and kick drum masking each other, so they carve a small EQ dip in one to let the other through.", "category": "Frequency Management", "related_terms": ["Auditory masking", "Equalization", "Instrument panning", "Frequency slotting", "Instrument gain ride"], "common_mistakes": ["Turning a masked instrument up instead of carving space, which just makes the mix louder", "Boosting the same frequency on many tracks, so they fight each other", "Ignoring arrangement, when playing parts in different registers would solve the clash"], "scenario_contexts": ["Separating kick and bass so both keep their low-end presence", "Carving space in a guitar so a vocal stays clear", "Panning two same-range instruments apart to reduce masking"]}, "bcf0511e-418f-4763-a5a3-b1aca8065d10": {"definition": "The combining of two or more microphones on a single instrument, mixed in proportion to shape tone by capturing different parts or perspectives of the sound source.", "plain_english": "You can put more than one mic on an instrument, and each hears it a bit differently. Blending them lets you mix the best of each. It is like taking photos from two angles and combining them.", "purpose_function": "It shapes an instrument's recorded tone by balancing mics placed at different spots, each capturing a different character.", "practical_application": "On a guitar amp, an engineer blends a close dynamic mic for punch with a ribbon mic further back for warmth, checking phase between them.", "category": "Signal Blending", "related_terms": ["Instrument DI blend", "Instrument phase coherence", "Microphone placement", "3-to-1 rule", "Room mic"], "common_mistakes": ["Blending mics without checking phase, causing thin or hollow tone", "Placing mics at very different distances without aligning timing", "Adding a second mic that only muddies rather than adds character"], "scenario_contexts": ["Blending a close mic and a room mic on a guitar amp", "Mixing top and bottom snare mics for body and snap", "Combining a spot mic and an overhead pair on a piano"]}, "3f81ab97-4428-46ac-ab3e-e2326affd528": {"definition": "The placement of an instrument's signal across the stereo field by adjusting its balance between the left and right channels.", "plain_english": "Panning sets how far left or right an instrument sounds. It spreads the band across the stereo picture so parts do not pile up in the middle. It is like seating players across a stage instead of all in one spot.", "purpose_function": "It separates instruments in the stereo field, improving clarity and creating a sense of width and space.", "practical_application": "An engineer pans rhythm guitars left and right and keeps bass and kick centered so the mix feels wide but balanced.", "category": "Stereo Imaging", "related_terms": ["Instrument image stability", "Stereo width", "Instrument masking control", "Balance control", "Mono compatibility"], "common_mistakes": ["Panning everything hard left or right, leaving a hole in the center", "Panning low-frequency parts like bass and kick off center, weakening the mix", "Not checking the mix in mono after panning"], "scenario_contexts": ["Spreading double-tracked guitars to the sides of a mix", "Placing backing vocals off center to make room for the lead", "Panning tom mics to match the drummer's kit layout"]}, "1c41a1a2-ad3b-406b-8d7e-fc59baccc663": {"definition": "The condition in which the signals from multiple microphones or sources on an instrument are aligned in phase, so they sum constructively rather than cancelling and causing comb filtering.", "plain_english": "When two mics catch the same sound, their waves must line up. If they do not, parts of the sound cancel out and it goes thin. Phase coherence means keeping them lined up so the sound stays full.", "purpose_function": "It makes combined mic or source signals reinforce each other, preserving full frequency response and avoiding hollow, filtered tone.", "practical_application": "When close-miking a snare top and bottom, an engineer flips the polarity of the bottom mic and checks phase so the two add up instead of thinning out.", "category": "Phase & Polarity", "related_terms": ["Instrument microphone blend", "Instrument DI blend", "Comb filtering", "Polarity", "3-to-1 rule"], "common_mistakes": ["Blending mics without a polarity or phase check, so the low-end cancels", "Confusing polarity flip with a true time alignment fix", "Placing mics at spacings that cause comb filtering when combined"], "scenario_contexts": ["Checking phase between top and bottom snare mics", "Aligning a DI and a miked amp so the blend stays full", "Time-aligning close and room mics before summing them"]}, "2158830c-a0f3-4349-942a-9d58aa9a2cc8": {"definition": "Emphasizing an instrument's upper-midrange and low-treble energy, roughly 2 to 6 kHz, so it sounds clearer and more forward in a mix, usually with equalization or subtle harmonic saturation. It increases the sense that the instrument is close and detailed without raising its overall level.", "plain_english": "Making an instrument stand out by boosting the tones that make it sound clear and up front. It is like turning up the clarity so the instrument feels closer to you.", "purpose_function": "It helps an instrument cut through a busy arrangement and feel detailed, so it stays easy to hear even when many parts play at once.", "practical_application": "A technician adds a gentle EQ boost around 3 to 5 kHz on a vocal or guitar during mixing so it sits on top of the band.", "category": "Tonal Shaping", "related_terms": ["Equalization", "Presence", "Frequency masking", "Midrange", "Harmonic saturation"], "common_mistakes": ["Boosting too much presence, which makes the instrument harsh or sibilant", "Adding presence to every track, so nothing stands out and the mix sounds brittle", "Confusing presence in the upper mids with air in the very high treble"], "scenario_contexts": ["Helping a lead vocal cut through a dense rock mix", "Bringing an acoustic guitar forward in a folk arrangement", "Adding clarity to a dull, muddy piano recording"]}, "c1ca0d95-8e06-46bf-a838-db74efa4640c": {"definition": "Identifying and controlling unwanted resonant frequencies, the narrow peaks where an instrument or room rings or builds up, typically by notching them with equalization or taming them with dynamic EQ. The goal is a smoother, more even tone without dulling the instrument.", "plain_english": "Finding the frequencies where an instrument rings out too loudly and gently turning them down. It is like softening one squeaky spring so the whole thing sounds even.", "purpose_function": "It removes honky or boomy buildups that draw attention, giving the instrument a balanced tone that blends better with the rest of the band.", "practical_application": "A technician sweeps a narrow EQ boost to find a ringing note on a snare or acoustic guitar, then cuts it a few dB to tame the resonance.", "category": "Tonal Shaping", "related_terms": ["Equalization", "Dynamic EQ", "Notch filter", "Q factor", "Standing wave"], "common_mistakes": ["Cutting too many resonances until the instrument sounds thin and lifeless", "Using a wide EQ cut instead of a narrow one, removing more tone than needed", "Treating a natural body resonance as a fault when it is part of the instrument's character"], "scenario_contexts": ["Taming a boomy low-mid note on a floor tom", "Removing a ringing frequency from an acoustic guitar body", "Controlling room buildup captured by a room microphone"]}, "3662d009-7c77-4b82-9d72-4ffde8f5300e": {"definition": "Using reverb, along with its pre-delay and level, to position an instrument at a chosen distance and space within a mix, from dry and close to distant and washed in ambience. It sets how far back, and in what environment, the instrument appears to sit.", "plain_english": "Using echo and room sound to decide how close or far away an instrument feels. A little reverb keeps it up front; a lot pushes it into the background.", "purpose_function": "It creates a sense of depth and a shared space, so separate recorded tracks sound like they belong in one room together.", "practical_application": "A technician sends a backing part to a reverb with a longer decay to push it behind the lead, keeping the lead drier and closer.", "category": "Spatial Processing", "related_terms": ["Reverb", "Pre-delay", "Stereo depth", "Send and return", "Ambience"], "common_mistakes": ["Adding so much reverb that the instrument loses clarity and detail", "Ignoring pre-delay, which can smear the attack and blur timing", "Using a different reverb on every track, so nothing shares a believable space"], "scenario_contexts": ["Placing a lead vocal in front of a reverberant backing arrangement", "Giving a dry, close-miked snare a sense of room", "Creating depth between rhythm and lead guitars"]}, "ded0d503-da06-4cd3-be4c-789b654514d3": {"definition": "Mixing a recorded room-microphone signal in with an instrument's close microphone to add natural ambience, size and depth. The blend ratio controls how much of the room's character is heard against the direct, close sound.", "plain_english": "Mixing in the sound picked up by a microphone placed farther away in the room. It adds natural space, so the drum seems to fill the room instead of sounding like just the drum itself.", "purpose_function": "It gives close-miked tracks a bigger, more natural sound and glues the band into a shared acoustic space.", "practical_application": "A technician blends a compressed room mic under the close drum mics to add weight and ambience without re-recording anything.", "category": "Spatial Processing", "related_terms": ["Room microphone", "Close microphone", "Ambience", "Phase alignment", "Reverb"], "common_mistakes": ["Blending the room mic without checking phase against the close mics, which thins the sound", "Adding too much room, which pushes the instrument back and muddies the mix", "Using a room mic recorded in a poor-sounding space and expecting it to help"], "scenario_contexts": ["Adding size to a drum kit with a pair of room mics", "Giving a close-miked guitar amp a sense of the live room", "Blending ambience into a piano recording"]}, "dcffbf7b-5df5-4fb2-8818-34b4a00bc087": {"definition": "Techniques that increase the perceived distinction between instruments in a mix, such as panning, complementary EQ, level balancing and timing, so each part is easy to hear on its own. It reduces masking, where one sound hides another.", "plain_english": "Making each instrument easier to pick out from the others in a mix. It is like seating band members apart so you can hear each one clearly instead of a blur.", "purpose_function": "It keeps a busy arrangement clear so a listener can follow every part, which matters most when many instruments share the same frequency range.", "practical_application": "A technician pans two rhythm guitars left and right and carves complementary EQ so they stop competing for the same space.", "category": "Mix Clarity", "related_terms": ["Panning", "Frequency masking", "Equalization", "Stereo width", "Arrangement"], "common_mistakes": ["Trying to fix a crowded arrangement with EQ instead of muting or rearranging parts", "Over-panning until the mix feels lopsided or hollow in mono", "Boosting every instrument to make it louder, which only increases masking"], "scenario_contexts": ["Separating two guitars playing similar parts", "Keeping bass and kick drum from masking each other", "Clarifying a dense arrangement with many layered keyboards"]}, "18c99eab-3c7f-417b-94f0-502d89b7a179": {"definition": "A submix that combines all the tracks of one instrument or instrument group, for example all drum tracks or all guitars, into a single stereo or mono file. Stems keep related parts grouped for easier mixing, delivery and remixing.", "plain_english": "One combined track that holds everything for a single instrument or group, like all the drums bounced together. It lets you handle a whole instrument as one piece instead of many separate tracks.", "purpose_function": "Stems make it easier to balance, hand off or remix a production, because a whole instrument group can be moved or adjusted at once.", "practical_application": "A technician bounces separate drum, bass, guitar and vocal stems so a mastering engineer or remixer can adjust each group without the full session.", "category": "Stems & Deliverables", "related_terms": ["Submix", "Bus", "Bounce", "Multitrack", "Master"], "common_mistakes": ["Confusing a stem, which is a grouped submix, with a single raw track", "Bouncing stems with master-bus effects still applied, causing double processing later", "Not keeping stems aligned to the same start point, so they drift when reimported"], "scenario_contexts": ["Delivering drum, bass and vocal stems for mastering", "Providing stems to a remixer", "Archiving a mix as stems for future recall"]}, "20a9b275-0287-43bf-b034-445b9df21b51": {"definition": "Recording, or printing, an instrument's stem to a new audio file in real time or offline, capturing that instrument group's processed submix as a fixed track. Printing commits the current balance and effects to disk.", "plain_english": "Recording an instrument's combined mix down to one finished file. It is like taking a photo of how that instrument sounds right now so you can use it later.", "purpose_function": "It locks in a group's sound and frees up computer power, and it creates a ready-to-share file for delivery, archiving or remixing.", "practical_application": "A technician prints a guitar stem through its plugins to a stereo file, then disables the original tracks to save processing.", "category": "Stems & Deliverables", "related_terms": ["Bounce", "Instrument stem", "Freeze", "Render", "Submix"], "common_mistakes": ["Printing a stem with the wrong routing, so effects or other tracks bleed in", "Forgetting to match the print's start point to the session, causing timing drift", "Printing at a lower bit depth or sample rate than the project, reducing quality"], "scenario_contexts": ["Printing stems to hand off to another studio", "Committing a processed drum group to save CPU", "Creating remix-ready stems at the end of a mix"]}, "e7e172ca-1e8c-4b1a-9f00-3589313a4128": {"definition": "The sense of front-to-back distance an instrument occupies in a stereo mix, created mainly by level, reverb amount, pre-delay and high-frequency roll-off. Greater depth makes an instrument seem farther away, while less depth brings it forward.", "plain_english": "How near or far away an instrument feels in a stereo mix, from front to back. Quieter, more echoey, and duller sounds seem farther away, like sounds across a room.", "purpose_function": "It adds a front-to-back dimension to a mix so instruments do not all sit at the same distance, making the arrangement sound more natural and layered.", "practical_application": "A technician pushes a pad back with reverb and a gentle treble cut while keeping the lead vocal loud and dry up front.", "category": "Stereo Imaging", "related_terms": ["Reverb", "Pre-delay", "Panning", "Stereo width", "Ambience"], "common_mistakes": ["Confusing depth, which is front-to-back, with width, which is left-to-right", "Making everything dry and up front, so the mix sounds flat and crowded", "Using bright EQ on a distant part, which fights the sense of distance"], "scenario_contexts": ["Setting a lead vocal in front of the band", "Layering pads behind rhythm instruments", "Creating a natural sense of distance in an acoustic recording"]}, "cde6daf7-3731-4e94-9106-98849625c922": {"definition": "How far an instrument's sound spreads across the left-to-right stereo field, set by panning, stereo miking, doubling, or width processing such as mid/side adjustment. A wide instrument fills the sides, while a narrow one stays near the center.", "plain_english": "How far an instrument spreads from left to right in a stereo mix. A wide sound fills both speakers; a narrow sound sits in the middle.", "purpose_function": "It gives each instrument its own place across the stereo image, which reduces clashing and makes a mix feel open and spacious.", "practical_application": "A technician widens a synth pad with a stereo doubler while keeping the bass and kick centered for a solid, mono-safe low end.", "category": "Stereo Imaging", "related_terms": ["Panning", "Mid/side processing", "Stereo image", "Mono compatibility", "Double tracking"], "common_mistakes": ["Widening the bass and kick, which weakens the low end and can cause mono problems", "Over-widening until the mix collapses or sounds hollow when played in mono", "Assuming wider always sounds better and ignoring mono compatibility"], "scenario_contexts": ["Widening backing vocals to frame a centered lead", "Keeping kick and bass mono while spreading guitars wide", "Checking mono compatibility after widening synths"]}, "e6a544f8-3d16-4c0b-9323-b71499cf4d74": {"definition": "A secondary mix bus on a console or in a DAW to which several related instrument channels are routed, so the whole set can be level-balanced, processed, and muted together before reaching the main output.", "plain_english": "A subgroup is one fader that controls a whole group of instruments at once. Instead of moving ten drum channels, you send them all to one drum fader and move just that. It is like putting many files into one folder so you can handle them as a set.", "purpose_function": "It simplifies control of many related channels, letting an engineer set relative balance once and then adjust, process, or mute the whole section as a single unit.", "practical_application": "A tracking engineer routes all drum, background-vocal, or keyboard channels to a subgroup so one fader move or one shared compressor can shape the entire section.", "category": "Signal Routing", "related_terms": ["Bus", "Auxiliary send", "Main mix bus", "VCA group", "Drum bus", "Gain staging"], "common_mistakes": ["Confusing a subgroup (audio actually flows through it) with a VCA/DCA group (which only remote-controls channel faders).", "Routing channels to a subgroup but forgetting to route the subgroup itself to the main mix, so the group is silent.", "Applying heavy processing on both the individual channels and the subgroup, causing unintended double processing."], "scenario_contexts": ["Bussing a multi-mic drum kit to one Drums fader for quick level rides.", "Compressing all background vocals together on a subgroup for a glued sound.", "Muting an entire keyboard section with one fader during a verse."]}, "57ac46fa-36c0-4744-92bb-41679956f284": {"definition": "The use of processing, typically downward compression or a dedicated sustainer, to raise and extend the decaying tail of an instrument's notes so they ring out longer and more evenly.", "plain_english": "This means making an instrument's notes last longer before they fade away. A compressor turns up the quiet tail of each note so it keeps ringing. It is like slowly raising the volume as a note dies so you still hear it.", "purpose_function": "It gives notes a longer, more even decay, helping sustained parts sit steadily in a mix instead of dropping away too quickly.", "practical_application": "On a clean electric guitar or electric piano, an engineer sets a compressor with a low threshold and slow release to hold each note's tail during tracking or mixing.", "category": "Dynamics Processing", "related_terms": ["Compression", "Release time", "Sustain", "Attack time", "Makeup gain", "Envelope"], "common_mistakes": ["Using very high ratios and low thresholds, which pulls up noise, hum, and hiss along with the sustain.", "Setting the release too fast, which causes audible pumping instead of smooth sustain.", "Confusing sustain (length of the decay) with attack (the initial hit)."], "scenario_contexts": ["Adding sustain to a clean electric guitar arpeggio.", "Evening out the decay of a Rhodes electric piano chord.", "Extending the ring of a plucked bass note."]}, "0d2f701e-d173-4ddd-89a5-41d45f6b3eb6": {"definition": "Keeping an instrument's timbre and frequency balance uniform across takes, sections, or an entire project, achieved through consistent mic placement, gain, and instrument setup.", "plain_english": "This means keeping an instrument sounding the same all the way through a song. You use the same mic spot and settings for every take so nothing suddenly changes. It is like keeping the same lighting for every photo so they all match.", "purpose_function": "It ensures parts recorded at different times cut together smoothly, preventing distracting jumps in tone when takes are comped or edited.", "practical_application": "When re-recording a guitar overdub the next day, the engineer restores the same mic position, amp settings, and gain to match the earlier tone.", "category": "Tonal Balance", "related_terms": ["Mic placement", "Gain staging", "Overdub", "Comping", "Timbre", "Recall"], "common_mistakes": ["Not documenting mic position and settings, making it hard to match tone in a later session.", "Changing headphone or monitor levels and assuming the recorded tone changed too.", "Swapping instruments or strings mid-session without noting the change in tone."], "scenario_contexts": ["Matching a punch-in to the surrounding performance.", "Recording the same guitar part across several days.", "Keeping horn-section tone even when players rotate mics."]}, "033e757c-982a-4522-a813-94014973b122": {"definition": "The deliberate boosting or reducing of the initial attack (transient) and sustain portions of an instrument's sound using a transient designer or fast compressor/expander, independent of overall level.", "plain_english": "A transient is the quick, punchy start of a sound, like the crack of a drum hit. Transient shaping lets you make that start harder or softer. It is like sharpening or softening the first hit you hear on each note.", "purpose_function": "It controls punch and impact, adding attack to make a drum cut through or softening it to sit back, without simply raising or lowering the whole track's volume.", "practical_application": "An engineer uses a transient designer on a snare to add crack, or reduces attack on an acoustic guitar to tame aggressive picking.", "category": "Dynamics Processing", "related_terms": ["Transient", "Attack time", "Compression", "Envelope", "Transient designer", "Punch"], "common_mistakes": ["Adding too much attack, which exaggerates noise and makes drums sound clicky and unnatural.", "Confusing transient shaping (which is level-independent) with simple volume automation.", "Boosting sustain heavily on a noisy source, which raises bleed and room ring."], "scenario_contexts": ["Increasing snare attack so it cuts through a dense rock mix.", "Reducing pick attack on a strummed acoustic guitar.", "Tightening a boomy kick by cutting its sustain."]}, "c58149e0-3cc8-4f1e-aec2-8f291496093f": {"definition": "Processing that adds low-mid weight and gentle harmonic content, through analog-style saturation, tube or tape emulation, or EQ roughly in the 100 to 400 Hz region, to make an instrument sound fuller and less harsh.", "plain_english": "Warmth means a full, smooth, pleasing lower-middle sound, not thin or harsh. Engineers add it with gentle saturation or a small boost in the lower-middle notes. It is like giving the sound a cozy, rounded feel.", "purpose_function": "It makes thin or clinical recordings feel richer and more pleasing, imitating the flattering coloration of analog tube and tape gear.", "practical_application": "An engineer runs a DI bass or a bright digital synth through a tape or tube saturation plugin, or boosts low mids slightly, to add perceived warmth.", "category": "Tonal Shaping", "related_terms": ["Saturation", "Harmonic distortion", "Equalization", "Low mids", "Tape emulation", "Timbre"], "common_mistakes": ["Adding so much low-mid boost that the mix becomes muddy and boxy.", "Overusing saturation until it becomes obvious distortion rather than subtle warmth.", "Assuming warmth is one fixed setting rather than a subjective, source-dependent balance."], "scenario_contexts": ["Warming up a clean DI bass with tape saturation.", "Softening a harsh digital synth pad.", "Adding body to a thin-sounding acoustic guitar."]}, "000a411a-0135-4f95-838e-e978ec262b78": {"definition": "The boosting of an instrument's fundamental and low-mid body frequencies, the region that gives fullness and resonance, to make it sound larger and more present without adding sub-bass.", "plain_english": "The body of an instrument is its full, resonant middle, like the woody sound of an acoustic guitar. Body enhancement boosts that region so the instrument sounds bigger. It is like filling out a sound so it does not seem thin.", "purpose_function": "It restores fullness lost to thin mic positions or bright instruments, helping a track feel solid and present in the mix.", "practical_application": "An engineer boosts around 100 to 250 Hz on an acoustic guitar or snare to add body, or blends in a body mic, while watching for muddiness.", "category": "Tonal Shaping", "related_terms": ["Equalization", "Fundamental frequency", "Low mids", "Resonance", "Proximity effect", "Timbre"], "common_mistakes": ["Boosting body frequencies on every track, which stacks up into a muddy low-mid buildup.", "Confusing body (low mids and fundamental) with sub-bass (very low frequencies).", "Adding body with EQ when the real fix is better mic placement."], "scenario_contexts": ["Thickening a thin-sounding acoustic guitar.", "Adding fullness to a snare that sounds papery.", "Restoring warmth to a close-miked cajon."]}, "faf18694-8437-4d4c-9f28-ec9f05d830b6": {"definition": "A damping device built inside a drum shell, typically a felt or foam pad on an adjustable arm, that presses against the inside of the drumhead to reduce ring and shorten sustain, controlled by a knob on the outside of the shell.", "plain_english": "An internal muffler is a soft pad inside a drum that touches the head to cut down ringing. You turn a knob on the shell to press it harder or softer. It is like resting your hand on a bell to stop it ringing so long.", "purpose_function": "It tames unwanted overtones and long sustain from a drum, giving a shorter, more controlled note without external tape or pads.", "practical_application": "When a vintage kit's tom or bass drum rings too long, a drummer or engineer turns the internal muffler knob to add damping before miking it up.", "category": "Drum Damping", "related_terms": ["Damping", "Overtone", "Sustain", "Drumhead", "Muffling", "Resonance"], "common_mistakes": ["Over-tightening the muffler, which chokes the drum and kills its tone and volume.", "Relying on a loose internal muffler that itself buzzes and adds noise to the recording.", "Assuming internal mufflers work as well as modern external damping; many engineers prefer external control."], "scenario_contexts": ["Taming a long-ringing vintage bass drum for a tight recording.", "Reducing tom overtones on a 1970s kit.", "Controlling snare ring without adding external tape."]}, "6b10c590-881f-4f5a-a61f-39c4e7705b62": {"definition": "The reduction of the mechanical clicking and clatter made by the keys and pads of woodwind instruments, and similar mechanism noise, through playing technique, instrument maintenance, mic placement, and post-recording editing.", "plain_english": "Woodwind instruments like sax and flute make clicking sounds when the keys move. Key-noise control means keeping those clicks from being too loud in a recording. You do it by moving the mic and keeping the instrument in good shape.", "purpose_function": "It keeps distracting mechanical noise from intruding on an otherwise clean instrument recording, especially in quiet or exposed passages.", "practical_application": "When recording flute, an engineer angles the mic away from the keys and toward the tone holes, and may edit out remaining clicks, to control key noise.", "category": "Noise Control", "related_terms": ["Mic placement", "Noise gate", "Editing", "Woodwind", "Bleed", "Signal-to-noise ratio"], "common_mistakes": ["Placing the mic right over the keys, which captures the loudest mechanical clatter.", "Trying to remove key noise entirely with heavy gating, which chops the natural note tails.", "Ignoring worn or dry pads that make the mechanism noisier than it needs to be."], "scenario_contexts": ["Recording an exposed solo flute passage.", "Miking a saxophone for an intimate ballad.", "Editing key clicks out of a quiet clarinet take."]}, "ec58750c-5485-4b94-9d4f-7b52194a520b": {"definition": "The use of a DAW's automation system to record and play back changes over time, such as volume, pan, filter cutoff, or effect levels, on a keyboard or synthesizer track.", "plain_english": "Automation lets the computer remember and repeat changes you make, like turning volume up in the chorus. Keyboard automation applies this to keyboard or synth parts. It is like teaching the mixer to move the knobs by itself at the right times.", "purpose_function": "It creates hands-free, repeatable changes in a keyboard part's level or tone across a song, keeping the part dynamic and consistent every playback.", "practical_application": "An engineer draws volume automation to lift a synth pad in the chorus and lower it under vocals, or automates a filter sweep on a synth for a build.", "category": "Mix Automation", "related_terms": ["Automation", "DAW", "Volume automation", "Filter cutoff", "Synthesizer", "Modulation"], "common_mistakes": ["Writing automation in the wrong mode (latch, touch, or write) and accidentally overwriting existing moves.", "Automating the channel fader and a plugin gain at once, causing confusing level jumps.", "Forgetting that a disabled automation lane still plays back its stored moves once re-enabled."], "scenario_contexts": ["Riding a synth pad's level under a lead vocal.", "Programming a filter sweep for a build-up.", "Balancing a piano part dynamically across a song."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"86afc2aa-bfd5-42d6-a3ce-18fe4a80395a": {"definition": "Keyboard layering is the practice of combining two or more keyboard or synthesizer sounds, played from the same performance or stacked in the arrangement, so they sound together as a single fuller composite tone. Layers are usually chosen to cover complementary frequency ranges or timbres, such as a piano paired with a pad or a sub-bass under an organ.", "plain_english": "It means playing two or more keyboard sounds at once so they blend into one bigger sound. Think of it like mixing paint colors to get a richer shade.", "purpose_function": "It exists to build a richer, more complete keyboard texture than any single patch can provide, filling out an arrangement and reinforcing chosen frequency ranges. Complementary layers add weight, brightness, or movement without needing a second player.", "practical_application": "A technician sets up a keyboard split or MIDI stack so several patches trigger together, then balances their levels and EQ so each layer contributes without masking the others. In tracking, the layers may be recorded to separate tracks for independent control at the mix stage.", "category": "Arrangement", "related_terms": ["Keyboard mixing", "Keyboard subgroup", "Doubling", "Synth pad", "Patch", "Arrangement"], "common_mistakes": ["Stacking too many layers so the parts clash and muddy the mix instead of blending.", "Layering sounds in the same frequency range without EQ, causing frequency buildup.", "Forgetting to check that layered patches are in tune and in phase with each other."], "scenario_contexts": ["Combining a grand piano patch with a soft string pad to thicken a ballad chorus.", "Stacking a sub-bass synth under an organ to add low-end weight in a live set.", "Layering an electric piano with a bell tone to brighten a verse."]}, "a20a87bd-8638-4985-b8c1-e31d0cb35e8d": {"definition": "Keyboard mixing is the process of balancing keyboard and synthesizer tracks within a mix using level, panning, EQ, dynamics, and effects so they support the arrangement without masking other instruments. Because keyboards often span a wide frequency range, mixing them usually involves carving out space for vocals and guitars.", "plain_english": "This is setting the volume, tone, and stereo position of the keyboard parts so they fit the song. It is like arranging furniture so nothing blocks the walkway.", "purpose_function": "Its purpose is to place keyboards at the right level and frequency position so they fill out the song while leaving room for lead elements. Careful keyboard mixing prevents the clutter that wide pads and pianos can otherwise create.", "practical_application": "A technician EQs a piano or pad to reduce buildup in the vocal range, pans parts to open the stereo field, and rides or automates levels through the song sections. Reverb and compression are added to seat the keyboards in the mix.", "category": "Mixing", "related_terms": ["Keyboard layering", "Keyboard subgroup", "EQ", "Panning", "Level balancing"], "common_mistakes": ["Letting keyboards mask the vocal or guitar because they share the same frequency range.", "Raising keyboard level instead of carving space with EQ and panning.", "Leaving wide stereo pads centered, cluttering the middle of the mix."], "scenario_contexts": ["Balancing a synth pad under a lead vocal so it supports without covering the voice.", "Panning two keyboard parts left and right to open up a busy arrangement.", "EQing a piano to make room for an acoustic guitar in the same range."]}, "ce5fab51-47e6-43d9-a546-665edeb27427": {"definition": "A keyboard subgroup is a bus to which multiple keyboard channels are routed so they can be processed and controlled together as one unit. The subgroup fader adjusts the overall keyboard level, and shared processing such as EQ, compression, or reverb can be applied to the whole group at once.", "plain_english": "It is a single fader that controls all the keyboard channels at once. Like a master switch that dims a whole group of lights together.", "purpose_function": "It exists to simplify control of many keyboard channels, letting a single fader move or shared processing affect the entire keyboard section. This keeps the internal balance between the keyboards intact while managing them as one group.", "practical_application": "A technician routes piano, pad, and synth channels to a subgroup (or a VCA/DCA group on a digital console), then rides that one fader to bring the keyboards up or down in the mix. Group compression or reverb on the subgroup glues the parts into a cohesive section.", "category": "Signal Routing", "related_terms": ["Subgroup", "Bus", "VCA group", "Keyboard mixing", "Auxiliary send"], "common_mistakes": ["Routing keyboards to a subgroup but leaving the subgroup fader down, so they vanish.", "Applying heavy subgroup compression that squashes the dynamics of every keyboard part.", "Double-routing channels to both the main bus and the subgroup, doubling the level."], "scenario_contexts": ["Routing piano, pad, and synth channels to one subgroup to ride all keyboards with a single fader.", "Applying shared reverb and compression to a keyboard subgroup for a cohesive sound.", "Muting the keyboard section quickly during a breakdown using the subgroup."]}, "e3d677a1-76d8-4b46-9847-8f0045796e3d": {"definition": "Elongation of a cymbal's central mounting hole into a keyhole shape, caused by repeated metal-to-metal contact between the cymbal and an unprotected stand rod. The deformation weakens the cymbal and can lead to cracks radiating from the center hole.", "plain_english": "When a cymbal is mounted on a bare metal rod, the constant banging slowly stretches its center hole into a keyhole shape. That worn hole can weaken the cymbal and make it crack.", "purpose_function": "Knowing about keyholing tells techs to protect the mounting point with a sleeve and felts, preventing costly cymbal damage and sudden failures during a session.", "practical_application": "A drum tech checks cymbals for an oval, worn center hole and always mounts them with a plastic or rubber sleeve and felt washers above and below to prevent keyholing.", "category": "Instrument maintenance", "related_terms": ["Kick beater definition", "Gel damper", "Body knock", "Kick click control"], "common_mistakes": ["Mounting a cymbal directly on a bare metal rod with no plastic sleeve", "Tightening the wing nut so hard the cymbal cannot move, which speeds up hole wear and cracking", "Ignoring an oval, elongated center hole until the cymbal cracks"], "scenario_contexts": ["Inspecting a drummer's cymbals before a session for keyholing damage", "Fitting new sleeves and felts to prevent hole wear on a touring kit", "Diagnosing a crack that started at a worn, keyholed center hole"]}, "7014b17e-a153-44da-96b7-052f133d5d6d": {"definition": "Kick attack enhancement is the emphasis of the initial transient (the beater click or knock) of a kick drum to increase its definition and audibility. It is achieved with EQ boosts in roughly the 2-5 kHz range, transient shaping, or by layering a sampled attack onto the recorded kick.", "plain_english": "This makes the sharp punch at the start of each kick drum hit stand out more. It helps the drum be heard clearly even in a loud band.", "purpose_function": "It exists to make the kick's front edge clear so the drum reads as rhythmic definition even on small speakers or within a dense mix. The attack is what listeners perceive as the kick's timing and punch.", "practical_application": "A technician boosts the click frequency with EQ, uses a transient designer to raise the attack, or blends in a kick sample to add a consistent click. This is common when the recorded kick sounds dull or lacks presence.", "category": "Drum Processing", "related_terms": ["Kick click control", "Kick beater definition", "Kick compression", "Transient shaper", "Beater"], "common_mistakes": ["Boosting click so hard the kick sounds thin and clicky, losing its low-end weight.", "Adding attack with EQ when the real problem is a slow compressor attack swallowing the transient."], "scenario_contexts": ["Adding beater click to a kick so it punches through a dense rock mix.", "Layering a sampled click onto a dull acoustic kick during editing.", "Using a transient shaper to bring out kick attack for a dance track."]}, "45c58b4e-6a91-4ee9-a163-33396835ce15": {"definition": "Kick beater definition refers to the clarity and character of the beater's impact (the audible click or attack) that the bass drum pedal beater produces against the drumhead. Beater material and hardness (felt, wood, plastic) strongly shape this attack, with harder beaters yielding a sharper, more defined click.", "plain_english": "This is how clear the click of the drum pedal's beater sounds on the kick drum. A harder beater gives a sharper click, and a soft one gives a duller thump.", "purpose_function": "It matters because the beater attack largely sets how clearly the kick's timing cuts through a mix at the source, before any processing. Getting the definition right at the beater reduces the need to manufacture attack later.", "practical_application": "A technician or drummer selects a harder beater or an impact pad to add a defined click for genres that need cut, or a softer felt beater for a rounder tone. Beater choice is set during drum tuning and sound check, before tracking.", "category": "Drum Sound", "related_terms": ["Kick attack enhancement", "Kick click control", "Beater", "Kick drum microphone", "Attack transient"], "common_mistakes": ["Blaming the mix for a dull kick when a soft felt beater is the real cause at the source.", "Expecting EQ alone to add attack that the beater never produced when the drum was played."], "scenario_contexts": ["Choosing a hard plastic beater to get a clear click for a metal recording.", "Switching from a felt to a wood beater to add attack before tracking drums.", "Comparing beater types during a kick sound check."]}, "3f8487d1-5933-488a-be66-7faabe083ff7": {"definition": "Kick click control is the adjustment of the amount of high-frequency click (the beater attack, roughly 2-5 kHz) present in the kick drum sound. It is managed through beater choice at the source and through EQ, transient shaping, or sample blending at the mix.", "plain_english": "This is adjusting how much sharp click you hear at the front of the kick drum sound. You can add click so the drum is clear, or cut it so the kick sounds softer and rounder.", "purpose_function": "Its purpose is to set how prominent the kick's attack is so the drum is clearly audible without becoming thin and clicky, or too dull to hear on small speakers. Balancing click against low-end weight keeps the kick translating across playback systems.", "practical_application": "A technician adds a focused EQ boost or a sample to bring up click for a pop or metal kick, or cuts the same range for a deep, rounded hip-hop kick. The amount is checked on both large monitors and small speakers to confirm it translates.", "category": "Drum Processing", "related_terms": ["Kick attack enhancement", "Kick beater definition", "Kick compression", "EQ", "Transient shaper"], "common_mistakes": ["Cutting all the click so the kick disappears on small speakers and phones.", "Adding click with a narrow, harsh EQ boost instead of finding the right frequency."], "scenario_contexts": ["Dialing in a boost around 3-5 kHz to add click for a pop kick.", "Cutting click on a hip-hop kick to keep it deep and round.", "Balancing click against sub weight so the kick reads on both club and phone speakers."]}, "e28fadd4-af0e-40d2-9d81-4971f65d6137": {"definition": "Kick clipping is the flattening of a kick drum signal's peaks when its level exceeds the maximum the system can pass, which adds harmonic distortion. It occurs unintentionally as an overload fault, or is applied deliberately with a clipper to tame sharp transients and add harmonic bite.", "plain_english": "Clipping happens when the kick drum signal is too loud and its peaks get cut off flat. Engineers sometimes do this on purpose for grit, but by accident it just sounds broken.", "purpose_function": "As a technique, clipping shaves the kick's fast peaks so the average level can rise without a limiter working hard, and adds harmonics that can make the kick feel more aggressive. As a fault, it signals that gain staging has pushed the signal past full scale.", "practical_application": "A technician may place a clipper on the kick to shave peaks before compression or limiting, using a small amount to keep the sound clean. During tracking, unwanted clipping shows on the meters and is fixed by lowering input gain to restore headroom.", "category": "Drum Processing", "related_terms": ["Kick compression", "Clipping", "Headroom", "Gain staging", "Limiter"], "common_mistakes": ["Letting the kick clip the master bus by accident, adding harsh digital distortion.", "Clipping in the box without checking gain staging, so the whole mix distorts.", "Confusing a compressor's gain-reduction meter with clipping and over-processing."], "scenario_contexts": ["Using a clipper to shave kick peaks so the mix can get louder without the limiter working hard.", "Spotting accidental kick clipping on the master meter during tracking.", "Clipping a kick lightly to add harmonic bite in an aggressive mix."]}, "783337ec-3a8c-4eb2-b955-64d9350589ba": {"definition": "Kick compression is the application of dynamic range compression to a kick drum to control its dynamics, even out hit-to-hit level differences, and shape its punch and sustain. Attack and release settings determine how much of the initial transient passes and how the body of the drum is emphasized.", "plain_english": "Compression evens out the loud and soft kick hits so they all punch at a steady level. It works like a fast hand that turns down the loudest hits so nothing jumps out.", "purpose_function": "It exists to make the kick level consistent and to sculpt its envelope, preserving or softening the attack and controlling the decay, so the drum sits solidly in the mix. Consistent kick dynamics anchor the groove and the low end.", "practical_application": "A technician sets attack and release to let the beater transient through while controlling the sustain, using moderate ratios to even out an inconsistent drummer. Parallel compression is often used to add body without crushing the natural dynamics.", "category": "Drum Processing", "related_terms": ["Kick clipping", "Kick attack enhancement", "Compression", "Attack time", "Release time", "Parallel compression"], "common_mistakes": ["Setting a fast attack that kills the kick's punch by clamping the transient.", "Over-compressing so the kick pumps and loses its natural dynamics.", "Using a slow release that never recovers before the next hit, causing gain buildup."], "scenario_contexts": ["Compressing a kick to even out an inconsistent drummer's dynamics.", "Using parallel compression to add sustain and body to a thin kick.", "Setting attack and release to shape kick punch for a rock mix."]}, "1a40992f-f503-4492-898c-634cc877a859": {"definition": "The use of equalization to shape the frequency balance of a kick-drum signal, typically boosting low-frequency weight around 50-100 Hz, cutting boxy or muddy midrange around 200-500 Hz, and adding beater attack in the upper mids around 2-5 kHz so the kick sits clearly in a mix.", "plain_english": "Using an EQ tool to change how a kick drum sounds. You can add deep boom, cut the muddy middle, and boost the click so the kick cuts through the song.", "purpose_function": "It carves out a defined frequency slot for the kick so it delivers low-end power and audible attack without clashing with the bass guitar or masking other instruments.", "practical_application": "An engineer sweeps a parametric EQ to find and cut boxy frequencies, then boosts the low thump and beater click, checking the result against the full mix on more than one set of speakers.", "category": "Drum Processing", "related_terms": ["Kick-drum mixing", "Kick resonance control", "Kick low-end enhancement", "Equalization", "Kick gating", "Kick microphone blend"], "common_mistakes": ["Boosting low frequencies so heavily that the kick and bass fight and the low end turns muddy", "Cutting all the midrange, leaving a kick with no body that disappears on small speakers", "EQ-ing the kick while soloed instead of in the context of the full mix", "Adding a huge click boost that sounds harsh over full-range monitors"], "scenario_contexts": ["Dialing in a rock kick so the beater click cuts through distorted guitars", "Making room for the bass guitar by cutting overlapping kick frequencies", "Tightening a boomy live-room kick recording during mixdown", "Matching the kick tone across songs on an album"]}, "4d0a9360-7b7a-4375-84ba-897c3361d39c": {"definition": "The application of a noise gate to a kick-drum channel so the signal passes only when the drum is struck, muting the microphone during rests and rejecting spill from snare, toms, and cymbals to keep the kick isolated and tight.", "plain_english": "A gate works like an automatic switch. It lets the kick sound through only when the drum is hit, and stays shut the rest of the time. This keeps out sounds from other nearby drums.", "purpose_function": "It isolates the kick by silencing its channel between hits, removing bleed from the rest of the kit and reducing low-frequency rumble that would otherwise build up in the mix.", "practical_application": "The engineer sets the gate threshold just above the level of the spill, then adjusts attack, hold, and release so the gate opens instantly on each strike and closes cleanly without cutting off the drum's natural decay.", "category": "Drum Processing", "related_terms": ["Noise gate", "Kick-drum mixing", "Kick microphone blend", "Kick sample blend", "Kick sustain control"], "common_mistakes": ["Setting the release too fast so the gate chops off the kick's natural tail", "Setting the threshold too high, so quieter hits are missed and cut out", "Using a slow attack that clips the start of soft hits", "Relying on a gate to fix bad mic placement instead of reducing bleed at the source"], "scenario_contexts": ["Tightening a live drum recording full of cymbal and snare bleed", "Cleaning up low-end rumble on a loud stage during a concert", "Isolating the kick before triggering a sample from it", "Prepping multitrack drums for a tight, modern mix"]}, "04631a56-ec1f-450a-b192-b20a8fe7fcc2": {"definition": "Techniques that reinforce the low-frequency content of a kick drum through low-shelf EQ boosts, sub-harmonic synthesis, or blended low-tuned samples, adding weight and power in the sub-bass and low-bass range of roughly 30-100 Hz.", "plain_english": "Making the deep, low part of the kick drum bigger and more powerful. Engineers do this so the kick has more punch and weight, like the boom you can almost feel in your chest.", "purpose_function": "It gives the kick the deep weight and physical impact a full mix needs, especially when the original recording lacks sub energy or must sound powerful on large systems.", "practical_application": "A technician adds a sub-harmonic generator or low-shelf boost, or layers a low-tuned sample, then checks the added energy on a spectrum analyzer and a subwoofer to avoid overloading the low end.", "category": "Drum Processing", "related_terms": ["Kick equalization", "Kick saturation", "Kick-drum mixing", "Kick sample blend", "Kick resonance control"], "common_mistakes": ["Adding so much sub energy that it eats headroom and causes the mix to distort", "UNSAFE: Pushing extreme sub-bass at high volume that can overheat and damage drivers not rated for it", "Boosting lows the small monitors cannot reproduce, so the problem goes unheard", "Enhancing low end without high-passing other tracks, leaving the bottom crowded"], "scenario_contexts": ["Adding club-ready sub weight to an electronic track's kick", "Reinforcing a thin kick recorded with a single dynamic mic", "Preparing a kick to translate on a large festival PA", "Rescuing a weak kick in a dense rock mix"]}, "3c501b1c-22e0-43f4-8cf0-2c708c043d9e": {"definition": "The practice of combining two or more kick-drum microphones, commonly an inside mic near the beater for attack and an outside or sub mic for low-end body, and adjusting their relative levels with attention to phase to build a composite kick sound.", "plain_english": "Using more than one mic on the kick drum and mixing them together. One mic catches the click of the beater, another catches the deep boom. Blending them lets you build a full sound.", "purpose_function": "It exists because no single microphone position captures both the sharp beater attack and the deep body of the drum, so combining mics builds a complete sound.", "practical_application": "The engineer sets levels between an inside beater mic and an outside or sub mic, checks that they are in phase, flipping polarity or nudging timing if the low end thins out, and blends to taste.", "category": "Drum Processing", "related_terms": ["Phase alignment", "Kick-drum mixing", "Kick equalization", "Kick gating", "Microphone placement", "Kick low-end enhancement"], "common_mistakes": ["Ignoring phase between the two mics, which cancels low end when they are combined", "Blending in so much sub mic that the beater attack disappears", "Placing both mics without checking each one soloed first", "Forgetting that moving one mic changes the phase relationship with the other"], "scenario_contexts": ["Combining an inside and outside kick mic in a studio drum session", "Adding a sub-kick mic to fatten a rock kick", "Balancing beater click and body for a punchy pop kick", "Phase-aligning kick mics before printing a drum mix"]}, "4d55f3f0-ed2a-4417-9d49-f0b10c24de3c": {"definition": "The reduction of unwanted resonant ringing or sustained tonal buildup in a kick drum, using narrow EQ cuts, physical damping inside the shell, or dynamic processing so a single dominant pitch does not linger and muddy the low end.", "plain_english": "Taming a ringing or humming note that a kick drum can make. If one note rings too long, it sounds muddy. Engineers cut that note or add padding inside the drum to fix it.", "purpose_function": "It stops a single resonant note or long ring in the kick from dominating and muddying the low end, keeping the drum tight and tonally neutral in the mix.", "practical_application": "The engineer finds the ringing frequency with a narrow EQ boost-and-sweep, then cuts it, or adds internal damping such as a pillow or muffling ring inside the drum before recording.", "category": "Drum Processing", "related_terms": ["Kick equalization", "Kick-drum mixing", "Drum damping", "Kick sustain control", "Kick low-end enhancement"], "common_mistakes": ["Confusing useful low-end body with unwanted resonance and cutting too much", "Over-damping the drum so it sounds dead and lifeless", "Using a wide EQ cut that removes more than the single problem note", "Fixing resonance only with EQ when a physical damping fix would work better"], "scenario_contexts": ["Removing a boomy ringing note from an untuned kick", "Tightening a resonant kick in a small untreated room", "Controlling sustain buildup in a fast double-kick part", "Cleaning a kick that rings at one note and clouds the bass"]}, "607ead3a-f026-4c9b-9c08-6435a99ad4e7": {"definition": "The mixing of a pre-recorded or triggered kick-drum sample underneath the recorded kick track, time-aligned to the original hits, to reinforce consistency, attack, or low-end when the source recording is weak or uneven.", "plain_english": "Adding a recorded kick sound under the real kick and playing them together. This helps when the real kick sounds weak or uneven, so every hit sounds strong and the same.", "purpose_function": "It adds consistency and power to a recorded kick, reinforcing weak or uneven hits with a reliable sampled sound while keeping the feel of the original performance.", "practical_application": "Using a trigger or sampler, the engineer aligns a chosen kick sample to each recorded hit, matches its timing and phase to the original, and blends the two so the sample supports rather than replaces the real drum.", "category": "Drum Processing", "related_terms": ["Drum replacement", "Kick gating", "Kick-drum mixing", "Kick microphone blend", "Transient shaping"], "common_mistakes": ["Not time-aligning the sample, causing phase problems that weaken the low end", "Using a sample so loud it replaces the real kick and sounds fake", "Choosing a sample whose tone clashes with the song or the rest of the kit", "Triggering off a bleedy track so the sampler fires on snare or tom hits"], "scenario_contexts": ["Reinforcing an inconsistent live kick recording", "Adding punch to a weak kick captured with poor mic placement", "Making every kick hit uniform for a tight modern mix", "Layering a sampled sub under an acoustic kick for extra weight"]}, "037a309c-e3cb-4f2e-becc-c64636de7d69": {"definition": "The deliberate addition of harmonic distortion to a kick-drum signal, via tape, tube, or transistor-style saturation, to generate extra harmonics that add warmth, perceived loudness, and presence and help the kick translate on small speakers.", "plain_english": "Adding a gentle, controlled distortion to the kick. This creates extra tones that make the kick sound warmer and louder. It also helps the kick be heard on small speakers like phones.", "purpose_function": "It adds harmonics that increase warmth, presence, and perceived loudness, helping the kick stay audible on small or bass-limited speakers that cannot reproduce deep bass.", "practical_application": "The engineer runs the kick through a tape, tube, or console-style saturation plug-in or hardware, adding drive until the kick gains harmonic bite while watching that it does not become harsh or lose its punch.", "category": "Drum Processing", "related_terms": ["Harmonic distortion", "Kick equalization", "Kick-drum mixing", "Kick low-end enhancement", "Tape saturation"], "common_mistakes": ["Adding so much saturation the kick sounds fuzzy and loses its clean attack", "Using saturation to fix a kick that really needs EQ or a better source", "Not gain-matching, so the louder distorted version only seems better", "Over-driving the low end into harshness that clashes with the bass"], "scenario_contexts": ["Helping a sub-heavy kick cut through on phone and laptop speakers", "Adding warmth and grit to an electronic kick", "Thickening a clean studio kick for a rock mix", "Giving a kick more presence without raising its fader"]}, "e10682e5-748e-4bbb-836f-643ccdae5e8e": {"definition": "The shaping of a kick drum's decay portion, lengthening or shortening the tail after the initial attack using transient shapers, gates, or compression, to control how long the low-end rings and how tight the drum feels.", "plain_english": "Changing how long the kick drum's boom lasts after it is hit. A short tail sounds tight and punchy. A longer tail sounds big and full. Tools called transient shapers help do this.", "purpose_function": "It controls how long the kick's low-end tail rings after the attack, letting the engineer make the drum tight and punchy or big and sustained to suit the song.", "practical_application": "The engineer uses a transient shaper to lengthen or shorten the tail, or a gate or compression to shape decay, listening for how the change affects tightness and how the kick locks with the bass.", "category": "Drum Processing", "related_terms": ["Transient shaping", "Kick gating", "Kick-drum mixing", "Kick resonance control", "Compression"], "common_mistakes": ["Cutting sustain so short the kick sounds clicky and thin", "Leaving too long a tail that overlaps notes and muddies the low end", "Confusing sustain shaping with simple volume changes", "Using a fast gate that chops the tail unnaturally instead of shaping it smoothly"], "scenario_contexts": ["Tightening a boomy kick for a fast punk song", "Shortening kick decay so it fits between quick double-kick hits", "Adding sustain to a thin kick for a big cinematic feel", "Matching kick length to the tempo and bass line of a track"]}, "69682fb5-0710-487f-89cc-9c53b8a627a6": {"definition": "The overall process of balancing, EQ-ing, compressing, and processing a kick-drum track so it fits its role in a mix, providing rhythmic foundation and low-end power while remaining clear against the bass guitar and the rest of the kit.", "plain_english": "Setting the kick drum's sound and volume so it fits the whole song. You balance it with the bass and other drums so the kick gives the beat its punch without covering everything else.", "purpose_function": "It places the kick correctly as the rhythmic and low-end foundation of the mix, keeping it powerful and clear even though it shares low frequencies with the bass guitar.", "practical_application": "The engineer sets the kick level, EQs and compresses it, manages its relationship with the bass through EQ carving or sidechain compression, and checks it on several speakers so the beat drives the song.", "category": "Drum Processing", "related_terms": ["Kick equalization", "Kick gating", "Kick saturation", "Kick sample blend", "Sidechain compression", "Kick low-end enhancement"], "common_mistakes": ["Mixing the kick too loud so it overpowers the rest of the track", "Letting the kick and bass occupy the same frequencies and turn muddy", "Judging the kick soloed instead of against the full mix", "Ignoring how the kick translates on small speakers"], "scenario_contexts": ["Building a drum mix around a solid kick foundation", "Balancing kick and bass guitar so both stay clear", "Setting up sidechain compression between kick and bass", "Getting a kick to hit hard on a club system and a laptop alike"]}, "3b1ee6c5-4870-4708-a23b-7e3735369ec2": {"definition": "The signal processing applied to the 'kick-in' microphone, an inner mic placed inside the drum near the beater in a dual-mic kick setup, typically emphasizing beater attack and midrange click through EQ, compression, and gating.", "plain_english": "Many engineers put two mics on the kick drum. The 'in' mic sits inside, near the beater. Processing this track means shaping its sound so the beater click cuts through the mix.", "purpose_function": "It isolates and shapes the beater-side attack of the kick so the drum defines timing and cuts through a dense mix, because a single kick mic rarely captures both punch and body well.", "practical_application": "An engineer boosts around 2-5 kHz for click, gates out cymbal bleed, and blends this track with the kick-out mic to dial in attack versus weight.", "category": "Drum Processing", "related_terms": ["Kick-out track processing", "Low-end reinforcement", "Sidechain compression", "Phase alignment", "Noise gate", "Kick-triggered bass ducking"], "common_mistakes": ["Boosting sub-lows on the kick-in mic, which muddies the mix instead of adding the click the mic is meant to provide", "Forgetting to check phase between the kick-in and kick-out mics, which cancels the low end", "Over-gating so soft hits disappear from the track"], "scenario_contexts": ["Tracking a rock drum kit with both an inside and outside kick mic", "Mixing a metal song where the beater click must cut through distorted guitars", "Reinforcing a weak beater attack on a recorded kick"]}, "69293e4b-2ea2-41ba-b294-39a24ef1b900": {"definition": "The signal processing applied to the 'kick-out' microphone, placed outside the resonant (front) head or in a tunnel in a dual-mic kick setup, usually shaping the low-frequency body, sustain, and tone of the kick drum.", "plain_english": "The 'out' mic sits by the front of the kick drum. It picks up the deep boom and body of the drum. Processing this track shapes that low, full sound.", "purpose_function": "It captures and shapes the deep weight and resonance a beater-side mic misses, so the kick has both punch and fullness in the mix.", "practical_application": "The engineer boosts lows around 60-100 Hz for weight, tames boom with EQ or compression, and blends it under the kick-in track for body.", "category": "Drum Processing", "related_terms": ["Kick-in track processing", "Low-end reinforcement", "Phase alignment", "Sub-bass", "Kick-triggered bass ducking", "Drum tuning"], "common_mistakes": ["Leaving the kick-in and kick-out mics out of phase, which cancels the low end you are trying to build", "Adding so much low boost that the kick masks the bass guitar", "Trying to fix a boomy drum only with EQ instead of also tuning the resonant head"], "scenario_contexts": ["Blending inside and outside kick mics for a full studio drum sound", "Adding weight to a thin-sounding kick in a rock mix", "Using a large-diaphragm or sub mic outside the kick for extra low end"]}, "687a6c18-8cd8-49f6-b16c-7f4ccced7141": {"definition": "A sidechain compression technique in which the kick-drum signal triggers a compressor on the bass, briefly reducing the bass level on each kick hit so the two low-frequency sources do not compete.", "plain_english": "Bass and kick drum both live in the low end, so they can clash. This trick uses the kick to briefly turn down the bass each time the kick hits. That gives the kick room to punch through cleanly.", "purpose_function": "It creates space in the low end so the kick's transient is heard clearly while the bass stays loud between hits, because kick and bass share the same frequency range and mask each other.", "practical_application": "The engineer routes the kick to the bass compressor's sidechain input and sets a fast attack and quick release so the bass dips only for the moment the kick strikes.", "category": "Dynamics Processing", "related_terms": ["Sidechain compression", "Low-end reinforcement", "Kick-out track processing", "Frequency masking", "Compression ratio", "Attack and release"], "common_mistakes": ["Setting the release too long, so the bass stays ducked and the low end sounds pumped or uneven", "Applying so much gain reduction that the bass audibly disappears on every beat", "Using a slow attack that lets the clash through before ducking begins"], "scenario_contexts": ["Tightening the low end in an electronic or pop mix where kick and bass overlap", "Making the kick punch through a busy rock mix without turning it up", "Cleaning up muddiness when bass and kick sit in the same octave"]}, "7b407dc0-bdcd-442a-9221-71c94f345b69": {"definition": "The process of blending the lead (melodic or solo) guitar into a mix through level, panning, EQ, dynamics, and effects so it occupies its intended role without masking the vocal or other lead elements.", "plain_english": "The lead guitar plays the solos and main riffs. Mixing it means setting its level, tone, and effects so it stands out. The goal is to make it clear without burying the singer.", "purpose_function": "It places the lead guitar at the right prominence and tone so solos and hooks are heard clearly while the part still sits within the arrangement.", "practical_application": "An engineer carves EQ space around the vocal, adds delay or reverb for depth, and automates the level so solos step forward while rhythm passages sit back.", "category": "Instrument Mixing", "related_terms": ["Lead-to-background balance", "Lead-vocal production", "Frequency masking", "Automation", "Panning", "Reverb"], "common_mistakes": ["Letting the lead guitar and lead vocal fight for the same midrange instead of carving space for each", "Leaving the solo at a fixed level so quiet phrases vanish and loud ones jump out", "Drowning the lead in reverb until it loses definition and timing"], "scenario_contexts": ["Bringing a guitar solo forward in a rock song's bridge", "Fitting a lead guitar hook around a lead vocal in a pop mix", "Balancing twin lead guitars panned left and right"]}, "d9d79cc3-2b43-4684-8c5c-6cf0eac42b7a": {"definition": "The relative level and tonal relationship set between the lead vocal (or lead element) and the supporting background vocals or parts, so the lead stays dominant while the backing adds depth and harmony.", "plain_english": "A song often has one main singer and softer backing voices. This balance sets how loud the backing voices are next to the lead. It keeps the main voice on top while the harmonies fill in behind.", "purpose_function": "It keeps the main melody or message clearly heard while background parts reinforce rather than compete, controlling the sense of size and support in the arrangement.", "practical_application": "The engineer sets background vocals several dB below the lead, often EQing and compressing them as a group and panning them wide so the lead stays centered and forward.", "category": "Vocal Mixing", "related_terms": ["Lead-vocal production", "Background vocals", "Vocal stacking", "Panning", "Bus compression", "Frequency masking"], "common_mistakes": ["Pushing background vocals too loud so they blur or overpower the lead", "Panning backing vocals to the same spot as the lead so the two smear together in the center", "Leaving backing vocals uncompressed so their level jumps above the lead on peaks"], "scenario_contexts": ["Balancing a stacked harmony chorus behind a solo lead vocal", "Setting a gospel or backing choir under a lead singer", "Mixing call-and-response vocal parts in pop"]}, "a8c06017-22ab-4858-84ba-58e005d66210": {"definition": "The full set of production tasks applied to the lead (main) vocal, including comping the best takes, tuning, timing correction, EQ, compression, de-essing, and effects, to deliver a clear, expressive, front-of-mix vocal.", "plain_english": "The lead vocal is the main singing part, and it usually grabs the most attention. Producing it covers picking the best takes, then tuning, timing, and adding effects. The aim is a clear, emotional voice that fits the song.", "purpose_function": "It shapes the most important element of most songs so it is intelligible, emotionally engaging, and sits consistently at the front of the mix.", "practical_application": "The engineer comps takes into one strong performance, tunes and de-esses it, then uses compression and automation so every word stays audible over the backing.", "category": "Vocal Production", "related_terms": ["Lead-to-background balance", "Comping", "De-essing", "Pitch correction", "Vocal compression", "Automation"], "common_mistakes": ["Over-tuning until the vocal sounds robotic and loses its natural emotion", "Compressing so hard the vocal sounds lifeless and loses all dynamics", "Skipping de-essing, leaving harsh sibilant 's' sounds that fatigue the listener"], "scenario_contexts": ["Comping and polishing a lead vocal for a pop single", "Getting a rap vocal to sit clearly over a dense beat", "Preparing a lead vocal for a live-to-broadcast performance"]}, "d4381a49-1e37-41b1-b2c2-0040b82ab320": {"definition": "The deliberate strengthening of low-frequency content, roughly below 250 Hz, through EQ, layering, sub-synthesis, or added subwoofers, to deliver a full and powerful bottom end in a mix or sound system.", "plain_english": "Low-end means the deep bass sounds you feel as much as hear. Reinforcing it means adding or boosting that weight so the mix feels full and strong. It is like adding a solid foundation under a house.", "purpose_function": "It adds weight, warmth, and physical impact that a thin source or small system lacks, and in live sound it extends output down to frequencies the main speakers cannot reproduce.", "practical_application": "In the studio an engineer layers a sub-bass or boosts fundamentals, while in live sound a technician adds and time-aligns subwoofers to reinforce the low end for the room.", "category": "Low-Frequency Management", "related_terms": ["Sub-bass", "Subwoofer alignment", "Kick-out track processing", "Kick-triggered bass ducking", "Equalization", "Headroom"], "common_mistakes": ["UNSAFE: Driving subwoofers or amplifiers past their limits to force more low end, risking driver damage and excessive sound-pressure exposure", "Boosting lows so much that the mix turns muddy and loses headroom", "Adding subs without checking phase and alignment, so the low end cancels instead of adding"], "scenario_contexts": ["Adding subwoofers to a live PA for a bass-heavy genre", "Layering a sine sub under a weak kick or bass in a mix", "Filling out the low end of a small-speaker recording for club playback"]}, "5a75d3b3-aae6-4e19-b935-18c32269ec20": {"definition": "The primary stereo microphone pair positioned to capture a choir as a whole, establishing the main stereo image and natural blend of the ensemble, with any spot or accent mics added only for support.", "plain_english": "When recording a choir, engineers often use two main mics set up as a stereo pair. This 'main pair' captures the whole group and its natural blend. Other spot mics just add support around it.", "purpose_function": "It provides the foundational stereo recording of the full choir with a natural sense of blend and space, so the result sounds cohesive rather than a collage of separate voices.", "practical_application": "The engineer places a coincident or near-coincident pair, such as XY or ORTF, in front of and slightly above the choir, then adds spot mics only where sections need reinforcement.", "category": "Microphone Technique", "related_terms": ["Stereo miking", "ORTF technique", "Spaced pair", "Spot microphone", "Room miking", "Lead-to-background balance"], "common_mistakes": ["Placing the main pair too close, so the front row dominates and the back of the choir disappears", "Ignoring the spacing or angle rules of the chosen stereo technique, causing a narrow or hole-in-the-middle image", "Relying on spot mics for the whole sound instead of building the balance from the main pair"], "scenario_contexts": ["Recording a choir in a church or concert hall", "Capturing a backing choir for an album with a main stereo pair", "Miking a large vocal ensemble where a single pair sets the core sound"]}, "68d2389d-d09e-4260-8fa5-50da1eaffde1": {"definition": "The reduction or removal of unwanted mechanical sounds captured during recording, such as pedal squeaks, key or valve clicks, chair creaks, page turns, and HVAC or motor rumble, achieved by treating the source or by editing and noise-reduction processing afterward.", "plain_english": "Instruments and rooms make unwanted little noises, like squeaky pedals or humming fans. Mechanical noise reduction means stopping or cleaning up these sounds. You can fix the source or remove the noise later with editing.", "purpose_function": "It clears distracting non-musical sounds out of a recording so the intended performance is heard clearly, because acoustic instruments, players, and rooms all generate incidental noise.", "practical_application": "A technician lubricates or dampens noisy mechanisms, repositions mics, and turns off HVAC before tracking, then uses spectral editing or a noise gate to clean remaining noise in post.", "category": "Noise Reduction", "related_terms": ["Noise gate", "Spectral editing", "Room treatment", "Microphone placement", "Signal-to-noise ratio", "High-pass filter"], "common_mistakes": ["Trying to remove all mechanical noise with heavy processing, which leaves audible artifacts on the music", "Ignoring the source when quieting a squeak or turning off the HVAC would prevent the noise entirely", "Setting a noise gate so aggressively that quiet musical detail is cut along with the noise"], "scenario_contexts": ["Cleaning pedal and mechanism noise from a piano recording", "Removing HVAC rumble picked up during a quiet acoustic session", "Editing out chair creaks and page turns in a classical recording"]}, "bdf7f635-23fb-4805-ab2e-374e3a3e49be": {"definition": "A small, deliberate displacement of a note or track relative to the metric grid, measured in milliseconds or ticks, used to shape groove and feel rather than to correct errors. Positive offsets place events slightly ahead of the beat (pushing) and negative offsets slightly behind it (laying back).", "plain_english": "It is a tiny shift of a note a little earlier or later than the exact beat. It gives music a human feel, the way a real drummer never plays perfectly in time.", "purpose_function": "It lets an engineer or producer control the groove and interaction between parts by nudging events off the strict grid, since perfectly quantized timing often sounds stiff. Small offsets create the sense of push or laid-back feel that defines a band's pocket.", "practical_application": "When editing tracked drums or MIDI, a technician nudges a snare or bass note a few milliseconds early or late, or dials in a percentage of quantize strength, to tighten timing without killing the feel.", "category": "Timing & Groove", "related_terms": ["Quantization", "Groove template", "Swing", "Pocket", "Beat grid"], "common_mistakes": ["Quantizing every part fully to 100 percent, which removes the natural push and pull and makes the performance feel mechanical.", "Confusing microtiming feel with sloppy timing, and correcting deliberate laid-back playing that was giving the track its groove.", "Applying the same offset to every track instead of judging each instrument's relationship to the beat by ear."], "scenario_contexts": ["Editing a live drum take so the kick sits tighter with the bass while keeping the drummer's natural feel.", "Programming a MIDI beat and nudging the snare slightly late to get a relaxed, laid-back groove.", "Aligning a doubled guitar to the main take without making both parts sound robotically locked."]}, "d639a063-71a7-4b68-a7e0-4add6a193114": {"definition": "A textural sonic layer built from broadband or colored noise, such as white, pink, vinyl crackle, tape hiss, or field-recorded ambience, added to an arrangement for atmosphere, glue, or character rather than for pitch or rhythm. It functions as a background bed or transitional element rather than a melodic part.", "plain_english": "It is a soft layer of noise, like static, hiss, or record crackle, added under a song. It fills empty space and sets a mood, like the faint hum you hear on an old record.", "purpose_function": "It fills gaps in the frequency spectrum and the stereo field, adds a sense of space or grit, and can glue disparate elements together into one cohesive bed. Producers use it to make sparse arrangements feel fuller and more intentional.", "practical_application": "A technician layers a low-level noise sample or synthesized noise under a mix, filters it to taste, and rides its level so it adds air or vibe without masking the main instruments.", "category": "Arrangement Texture", "related_terms": ["Ambience layer", "Sound bed", "Pink noise", "Field recording", "Foley"], "common_mistakes": ["Setting the noise layer too loud so it masks detail and raises the overall noise floor of the mix.", "Leaving noise textures unfiltered, so their high or low content clashes with the instruments they are meant to support.", "Adding noise as an afterthought instead of choosing its color and character to match the song's mood."], "scenario_contexts": ["Adding vinyl crackle under a lo-fi hip-hop beat to give it a warm, nostalgic feel.", "Placing a filtered noise sweep before a chorus to build tension into the drop.", "Layering quiet room ambience under an electronic track so it feels less sterile."]}, "88d9ccb2-e464-45cd-baae-c30e14fdc651": {"definition": "An arrangement technique in which a part is doubled by a copy pitched one or more octaves above or below the original and blended with it, reinforcing the line and thickening its timbre. The layers can be separate performances, transposed copies, or an octave-generating effect.", "plain_english": "It means playing the same part again one octave higher or lower and blending them. It makes the sound thicker and fuller, like two singers on the same tune but at different pitches.", "purpose_function": "It adds weight, fullness, and reinforcement to a melodic or harmonic line without changing the notes, and can extend a part's presence into higher or lower ranges. This helps a single instrument or voice occupy more of the frequency spectrum.", "practical_application": "A technician doubles a bass line an octave up to add definition on small speakers, or layers a synth lead an octave higher to make a hook cut through the mix.", "category": "Arrangement Technique", "related_terms": ["Octave stack", "Doubling", "Unison", "Layering", "Voicing"], "common_mistakes": ["Layering octaves in an already crowded frequency range, which causes buildup and masking instead of reinforcement.", "Assuming a higher or lower octave copy is always in tune, when transposition artifacts or timing drift can smear the result.", "Overusing octave layers so every part sounds oversized and the mix loses contrast."], "scenario_contexts": ["Doubling a synth bass an octave up so it stays audible on phone and laptop speakers.", "Reinforcing a vocal hook with a part sung an octave higher for a bigger chorus.", "Layering a guitar riff with an octave pedal to fatten a two-piece band's sound."]}, "34446eed-b017-4640-9062-6119588368bb": {"definition": "A group of two or more copies of the same sound spaced at octave intervals and played together as a single reinforced voice. It is common in synthesis, organ registration, and guitar or bass processing, where the stacked octaves fuse into one thick, full-range timbre.", "plain_english": "It is a set of copies of one sound spaced an octave apart and played at once. It makes a big, full sound, like a whole group singing the same note high and low together.", "purpose_function": "It creates a powerful, full-bodied tone from a single note or part by combining energy across several octaves, giving weight and richness that one voice alone cannot. It is a fast way to make leads, basses, and pads sound large.", "practical_application": "A technician stacks oscillators or organ drawbars at octave intervals, or uses an octave effect on guitar, to build a thick lead or a fat bass without adding new notes.", "category": "Arrangement Technique", "related_terms": ["Octave layering", "Unison", "Drawbar registration", "Oscillator", "Voicing"], "common_mistakes": ["Stacking so many octaves that the low end becomes boomy and the sound loses focus in the mix.", "Confusing an octave stack with a chord, when a stack reinforces one pitch class rather than adding harmony.", "Ignoring phase and tuning between the stacked layers, which can thin or smear the combined tone."], "scenario_contexts": ["Building a fat synth lead by stacking oscillators one and two octaves apart.", "Setting Hammond organ drawbars at octave intervals for a full band-supporting pad.", "Using a guitar octave pedal to create a thick riff for a stripped-down live set."]}, "8bf37faf-f5bd-478c-b80a-b40d5c9a0521": {"definition": "A hi-hat sound produced when the two cymbals are held apart, letting them ring and sizzle with sustained decay rather than a short, choked tick. On an acoustic kit the drummer lifts the foot off the pedal to open the cymbals; in sampled or programmed drums it is a separate sound in the hi-hat group.", "plain_english": "It is the sound of the two hi-hat cymbals held apart so they ring and sizzle. A drummer lifts the foot pedal to let them buzz instead of making a short, tight tick.", "purpose_function": "It provides an accent, a sustained sizzle, and rhythmic openness that contrasts with the tight closed hi-hat, adding movement and energy to a groove. Drummers use it to mark offbeats, transitions, and lifts.", "practical_application": "When tracking or programming drums, a technician places open hi-hat hits on offbeats or before fills, and ensures each open hit is choked or cut by the following closed hit so they do not overlap unnaturally.", "category": "Drum Sounds", "related_terms": ["Closed hi-hat", "Hi-hat", "Choke", "Cymbal", "Groove"], "common_mistakes": ["Letting an open hi-hat sample ring over the next closed hit, which sounds unnatural since a real hi-hat closes when the pedal is pressed.", "Using open hi-hats on every beat so the groove loses its tight, driving feel.", "Mixing the open hi-hat too bright or loud so its sustained sizzle masks vocals and cymbals."], "scenario_contexts": ["Programming a beat with an open hi-hat on the offbeat to add lift before a chorus.", "Choking an open hi-hat with the following closed hit so a sampled groove sounds like a real drummer.", "Miking a drum kit and checking that open hi-hat sizzle is captured without excessive bleed into the vocal mic."]}, "7a91f9aa-7489-44e2-9308-21863bba8da1": {"definition": "The set of techniques used to place an organ, typically a tonewheel or electric organ such as a Hammond, into a band mix by managing its level, frequency balance, dynamics, and spatial position. Because organ tone is broadband and sustained, mixing focuses on carving space so it supports rather than masks guitars, keys, and vocals.", "plain_english": "It is how you set the level, tone, and space of an organ in a song. The goal is to let it fill out the sound without covering the guitars or vocals.", "purpose_function": "It integrates a dense, sustained instrument into an arrangement so it adds warmth and body while leaving room for the other parts. Good organ mixing keeps the track full without turning it muddy or cluttered.", "practical_application": "A technician EQs out overlapping low-mids, adds compression to steady the sustained tone, and pans or adds rotary-speaker stereo width so the organ sits under the vocal and glues the band together.", "category": "Instrument Mixing", "related_terms": ["Rotary speaker", "Drawbar registration", "Equalization", "Compression", "Panning"], "common_mistakes": ["Leaving the organ full-range so its low-mids clash with guitars and bass and muddy the mix.", "Over-compressing the sustained tone until it pumps and loses its natural swell.", "Placing the organ too loud or dead center so it competes with the lead vocal instead of supporting it."], "scenario_contexts": ["Fitting a Hammond organ pad under a rock vocal by cutting overlapping low-mids.", "Adding rotary-speaker stereo spread so the organ widens the mix without crowding the center.", "Balancing organ and rhythm guitar in a soul track so both hold their own place."]}, "d21f77bb-a24e-4f50-991d-612cf91d1fe0": {"definition": "A sonic character that sounds natural, acoustic, and human rather than synthetic or rigidly programmed, arising from real instruments, room ambience, subtle timing and tuning variation, and unquantized performance. It is a descriptive quality of an arrangement or sound rather than a specific process.", "plain_english": "It is a sound that feels natural and alive, not stiff or robotic. It often comes from real instruments and small human flaws, like the warm buzz of an acoustic guitar in a room.", "purpose_function": "It gives a production warmth, life, and a human feel that listeners connect with, contrasting with clean but sterile digital sounds. Producers pursue it to make even electronic tracks feel more relatable.", "practical_application": "A technician introduces organic texture by tracking real instruments, keeping natural timing and tuning variation, adding room ambience, or layering acoustic and foley sounds into an otherwise programmed arrangement.", "category": "Arrangement Texture", "related_terms": ["Noise texture", "Ambience layer", "Room sound", "Microtiming offset", "Foley"], "common_mistakes": ["Assuming full quantization and pitch correction will still sound organic, when they remove the human variation that creates the feel.", "Confusing organic texture with a lack of polish, and leaving genuine mistakes that distract rather than add life.", "Over-processing real instruments until they sound as sterile as the synthetic parts they were meant to offset."], "scenario_contexts": ["Adding a live-tracked acoustic guitar to an electronic song to warm up the arrangement.", "Keeping a drummer's natural timing instead of hard quantizing to preserve a human feel.", "Layering room ambience and light foley under a sampled beat to make it feel real."]}, "3d750b1c-5913-460b-b1dd-a2eb2e380b17": {"definition": "Dynamic-range compression applied to the drum overhead microphone channels, which capture cymbals and a stereo image of the whole kit. It is used to control cymbal transients and level swings and to help the kit sound cohesive and fuller.", "plain_english": "It is squashing the loud and soft parts of the drum overhead mics so they sit steadier. It glues the cymbals and the whole kit together and can make the drums feel bigger.", "purpose_function": "It tames peaky cymbal hits, evens out the level of the overall kit image, and can add punch and glue when driven harder, since the overheads carry much of the kit's tone and stereo picture. This keeps the drums consistent and powerful in the mix.", "practical_application": "A technician patches a compressor across the stereo overhead bus, sets a moderate ratio and attack that lets transients through, and adjusts threshold so the cymbals and kit stay controlled without pumping.", "category": "Drum Processing", "related_terms": ["Overhead equalization", "Drum bus compression", "Transient", "Parallel compression", "Attack time"], "common_mistakes": ["Using too fast an attack, which dulls the cymbal transients and robs the kit of its snap.", "Over-compressing the overheads so the cymbals pump and the room sound becomes unnatural.", "Compressing overheads heavily while ignoring bleed, which pulls up snare and room spill in an uncontrolled way."], "scenario_contexts": ["Applying gentle bus compression to stereo overheads so the cymbal levels stay even across a take.", "Driving overhead compression harder for an aggressive rock drum sound with more room and glue.", "Balancing overhead and close-mic compression so the full kit sounds cohesive."]}, "f5cce9a9-b54c-4ecf-bc9b-e33279d8f7e7": {"definition": "Equalization applied to the drum overhead microphone channels to shape the tone of the cymbals and the overall kit image they capture. It typically involves cutting harshness or low-frequency spill and adjusting high-frequency content so cymbals sound clear without being brittle.", "plain_english": "It is shaping the tone of the drum overhead mics by boosting or cutting certain pitches. It keeps the cymbals crisp and clear while trimming harsh or muddy sounds.", "purpose_function": "It controls the brightness and clarity of the cymbals and the captured kit sound, and removes unwanted low-end rumble and bleed that the overheads pick up. This helps the overheads blend with the close mics instead of clashing.", "practical_application": "A technician high-passes the overhead channels to remove kick and low rumble, dips harsh upper-mid resonances, and gently lifts the highs so cymbals sound airy rather than clanky.", "category": "Drum Processing", "related_terms": ["Overhead compression", "High-pass filter", "Equalization", "Cymbal", "Bleed"], "common_mistakes": ["Boosting the highs too much so cymbals become harsh and fatiguing to listen to.", "Skipping a high-pass filter, leaving kick and rumble in the overheads that muddy the drum bus.", "EQing the overheads in isolation instead of in context with the close mics and full mix."], "scenario_contexts": ["High-passing overheads to strip low rumble before blending them with the snare and kick mics.", "Cutting a harsh upper-mid frequency so a bright ride cymbal stops piercing the mix.", "Adding a gentle high-shelf lift to give dull-sounding cymbals more air."]}, "b6ebde98-12c6-44eb-a448-2f4f9346502b": {"definition": "A tracking and mixing practice in which a high-pass (low-cut) filter is applied to drum overhead microphones to attenuate low-frequency energy below roughly 80-300 Hz, so the overheads capture cymbals and the overall kit image without excessive kick, tom, and stage rumble.", "plain_english": "This means cutting the deep, low sounds out of the drum mics placed above the kit. It lets those mics catch the bright cymbals and the whole drum sound, and keeps out the boomy low rumble.", "purpose_function": "It cleans up the overhead microphones so they add cymbal detail and kit balance rather than muddy low end, keeping the low frequencies under the control of the dedicated kick and tom mics.", "practical_application": "An engineer sweeps a low-cut filter up from around 80 Hz on each overhead channel until the cymbals stay clear but the low boom and rumble drop away.", "category": "Drum Recording", "related_terms": ["Overhead miking", "Low-cut filter", "Cymbal bleed", "Drum bus", "Parallel-drum bus"], "common_mistakes": ["Setting the cut frequency too high, which thins out the snare and removes the natural body of the kit.", "Forgetting that overheads also carry the main image of the whole kit, so over-filtering leaves the drums sounding small.", "Applying the same fixed cut to every session instead of tuning it to the actual kit and cymbals."], "scenario_contexts": ["Tracking a live drum kit where the overheads pick up unwanted low-end rumble from the room and stage.", "Cleaning up a drum mix so the kick and toms own the low end while the overheads handle cymbals.", "Reducing HVAC or foot-tap rumble captured by condenser overheads during a quiet take."]}, "4876625d-19c0-4a45-be62-1f9777ea4bb4": {"definition": "An arrangement and production technique in which two or more sustained synthesizer or keyboard 'pad' sounds are stacked to create a single, fuller, often evolving background texture that fills harmonic space beneath a mix.", "plain_english": "A pad is a soft, held background sound, like a warm cushion under the song. Pad layering means stacking two or more of these held sounds so the background feels fuller and richer.", "purpose_function": "It builds a thicker, more interesting sustained bed than one patch can give, filling out the harmony and adding warmth or movement without crowding the main parts.", "practical_application": "A producer layers a warm analog-style pad with a brighter, airy pad, then balances their levels and filtering so they blend into one supporting texture.", "category": "Arrangement", "related_terms": ["Layering", "Synth pad", "Sound stacking", "Percussion layering", "Doubling"], "common_mistakes": ["Layering pads that occupy the same frequency range, which causes mud instead of richness.", "Stacking so many pads that they overpower the lead and rhythm parts.", "Not checking the combined layers in mono, so phase problems between pads go unnoticed."], "scenario_contexts": ["Building a lush sustained background under a ballad chorus.", "Adding subtle movement to an otherwise static electronic arrangement.", "Reinforcing a held string section with a synth pad for extra warmth."]}, "eca28fef-53e9-4757-8c9c-fd71f2b7602b": {"definition": "A mixing setup in which the drum signals are sent to a duplicate (parallel) bus that is heavily processed - typically with aggressive compression and/or saturation - and then blended underneath the original dry drums to add weight and punch while preserving the natural transients.", "plain_english": "This is a copy of the drums on a second channel that gets squashed hard, then mixed back in under the normal drums. It adds power and punch while keeping the real drum hits sounding natural.", "purpose_function": "It lets an engineer add density, sustain, and aggression to drums by blending a crushed copy in, instead of destroying the dynamics of the main drum track.", "practical_application": "The engineer routes the drums to an aux, applies a fast, high-ratio compressor to the copy, and raises its fader until the kit sounds bigger without losing the punch of the dry hits.", "category": "Mix Processing", "related_terms": ["Parallel compression", "Drum bus", "New York compression", "Aux send", "Bus compression"], "common_mistakes": ["Bringing the crushed parallel channel up so loud that it swallows the natural dry drums.", "Forgetting to phase-check the parallel path against the dry drums, causing thin or hollow sound.", "Using heavy processing on the parallel bus without listening in the context of the full mix."], "scenario_contexts": ["Making a rock drum kit sound bigger and more aggressive in a dense mix.", "Adding sustain and body to a thin-sounding drum recording.", "Gluing a multi-mic drum kit together with a parallel crushed layer."]}, "7c304b3e-0f98-402d-bca1-c7eab3e9a556": {"definition": "The short, crisp 'chick' sound produced when a drummer closes the two hi-hat cymbals together using the foot pedal, without striking them with a stick; it marks the backbeat or subdivisions purely from the foot.", "plain_english": "It is the tight 'chick' sound a drummer makes by pressing the hi-hat pedal so the two cymbals snap shut. No stick is used, just the foot closing the cymbals.", "purpose_function": "It gives a steady rhythmic accent from the drummer's foot, keeping time and the backbeat even when the hands are busy on other drums.", "practical_application": "When recording, an engineer places the hi-hat mic to capture a clean pedal chick without excessive air blast from the closing cymbals.", "category": "Drum Recording", "related_terms": ["Hi-hat", "Backbeat", "Foot pedal", "Hi-hat miking", "Cymbal bleed"], "common_mistakes": ["Confusing the foot-closed pedal chick with a stick-struck closed hi-hat note.", "Miking too close to the edge, so the pedal chick is buried under the puff of air from the closing cymbals.", "Ignoring the pedal chick in the mix, which loses an important part of the groove."], "scenario_contexts": ["Recording a drum groove where the hi-hat foot keeps time on beats 2 and 4.", "Capturing a jazz ride pattern where the foot chick marks the pulse.", "Editing a drum take and needing the pedal chick to line up with the click."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"651e56ff-7dfd-47be-bf96-721aec9c967d": {"definition": "The set of techniques used to reduce unwanted mechanical noise made by foot pedals during tracking - such as kick-drum beater and spring squeak, hi-hat pedal clatter, or piano and keyboard sustain-pedal thumps - through maintenance, lubrication, isolation, and mic placement.", "plain_english": "This means stopping the squeaks, clicks, and thumps that pedals make while playing. You fix it by oiling the pedal, tightening parts, and aiming mics away from the noise.", "purpose_function": "It keeps distracting pedal squeaks and thumps out of the recording so the microphones capture the instrument, not the hardware.", "practical_application": "Before a take, a technician oils a squeaky kick pedal spring and repositions the mic so the beater's mechanical noise does not reach it.", "category": "Tracking Technique", "related_terms": ["Kick pedal", "Sustain pedal", "Mechanical noise", "Piano hammer-noise control", "Isolation"], "common_mistakes": ["Waiting until mixing to notice a squeak that could have been fixed with oil before tracking.", "Lubricating a pedal with the wrong product, which attracts dust or damages parts.", "Assuming EQ can remove pedal noise that overlaps the instrument's own frequencies."], "scenario_contexts": ["Silencing a squeaking kick-drum pedal spring before a quiet ballad take.", "Reducing sustain-pedal thumps captured by close piano mics.", "Taming hi-hat pedal clatter that bleeds into vocal mics on a live stage."]}, "cd343ea3-1b38-4bf1-a48d-bf4a38fc2ba8": {"definition": "An arrangement technique in which multiple percussion parts or samples - such as shakers, tambourines, congas, or claps - are stacked and blended to build a fuller, more detailed rhythmic texture than a single instrument provides.", "plain_english": "This means stacking several small percussion sounds, like shakers and tambourines, to make one fuller rhythm layer. Together they add energy and detail to the groove.", "purpose_function": "It thickens and enlivens the rhythm section by combining complementary percussion sounds that each fill a different part of the groove and frequency range.", "practical_application": "A producer layers a shaker on the offbeats with a tambourine on the backbeat, panning and balancing them so they lock into the drum groove.", "category": "Arrangement", "related_terms": ["Overdubbing", "Pad layering", "Groove", "Panning", "Shaker"], "common_mistakes": ["Stacking percussion parts that clash rhythmically instead of locking to the same grid.", "Layering many bright percussion sounds that pile up in the high frequencies and sound harsh.", "Leaving all layers dead center, so the added parts crowd the mix instead of widening it."], "scenario_contexts": ["Adding energy to a chorus by layering shaker, tambourine, and claps.", "Filling out a sparse verse groove with subtle hand percussion.", "Reinforcing a programmed beat with live overdubbed percussion for a human feel."]}, "c0d7eb40-030e-4603-9d1c-bebe356cf455": {"definition": "The application of dynamic-range compression to a piano recording to reduce the difference between its loudest and softest notes, producing a more even level and helping the piano sit consistently within a mix.", "plain_english": "A piano can jump from very soft to very loud. Compression gently turns down the loud notes so the whole part stays even and easier to hear in the song.", "purpose_function": "It controls the piano's wide dynamic range so quiet passages stay audible and loud chords do not jump out, keeping the instrument steady within the balance of a mix.", "practical_application": "An engineer sets a moderate ratio and a slower attack so chord strikes keep their initial punch while the sustain is brought up and the overall level evens out.", "category": "Mix Processing", "related_terms": ["Dynamic range", "Compressor", "Attack and release", "Piano equalization", "Makeup gain"], "common_mistakes": ["Using too fast an attack, which dulls the natural attack of the hammer strike.", "Over-compressing until the piano sounds squashed and lifeless.", "Adding heavy makeup gain that also lifts unwanted pedal and bench noise."], "scenario_contexts": ["Evening out an expressive piano performance so it stays present in a full band mix.", "Controlling loud chord stabs that otherwise poke out of a ballad.", "Bringing up the sustain of a solo piano so soft passages remain audible."]}, "d6ce6665-812f-4f9e-a636-44e25a129aa4": {"definition": "The use of equalization to shape the tonal balance of a piano recording - for example cutting low-mid buildup for clarity, controlling boxiness, or adding high-frequency air - so the instrument sounds balanced and fits the arrangement.", "plain_english": "This means using EQ to fix the tone of a recorded piano. You can cut muddy low notes or add sparkle up top so it sounds clear and fits the song.", "purpose_function": "It corrects tonal problems and carves space for the piano so it sounds clear on its own and does not clash with other instruments in the mix.", "practical_application": "An engineer dips a few decibels around the low mids to clear mud, then adds a gentle high shelf for air so the piano cuts through without harshness.", "category": "Mix Processing", "related_terms": ["Equalizer", "Frequency masking", "Piano compression", "High shelf", "Low-mid buildup"], "common_mistakes": ["Boosting the low end heavily, which clashes with the bass and muddies the mix.", "Adding too much high-frequency boost, which exaggerates hammer and pedal noise.", "Cutting so aggressively that the piano loses its natural body and character."], "scenario_contexts": ["Clearing low-mid mud so a piano and bass guitar do not fight for the same space.", "Brightening a dull piano recording to help it cut through a dense arrangement.", "Shaping a piano to sit as a supporting layer behind a lead vocal."]}, "327f23c3-4a20-4804-a5b0-1bd6f68fb4b8": {"definition": "The techniques used to reduce mechanical action and hammer noise - thumps, clicks, and key clatter - captured when close-miking a piano, achieved through mic placement, instrument maintenance and regulation, and careful gain and processing choices.", "plain_english": "Inside a piano, the hammers and keys make small thumps and clicks. This means keeping those mechanical noises out of the recording by moving the mics and keeping the piano well maintained.", "purpose_function": "It keeps distracting action and hammer noise from overpowering the musical tone, which matters most when mics are placed close to the strings and action.", "practical_application": "A technician moves the close mics slightly away from the hammers and has the action regulated so key clatter drops below the level of the notes.", "category": "Tracking Technique", "related_terms": ["Close miking", "Piano miking", "Mechanical noise", "Pedal-noise control", "Action regulation"], "common_mistakes": ["Placing mics right over the hammers, which exaggerates every click and thump.", "Blaming the room when the noise is actually a worn or unregulated action.", "Trying to fix loud hammer noise with EQ alone when it overlaps the note's own frequencies."], "scenario_contexts": ["Close-miking a grand piano for a pop record where hammer clicks become distracting.", "Recording a quiet solo piano passage where every mechanical thump is exposed.", "Diagnosing whether piano action noise comes from mic placement or from the instrument itself."]}, "d71f9edd-7c4d-4bf5-8e59-09b6f27680e9": {"definition": "The practice of combining the signals from two or more microphones on a piano - such as a spaced or coincident inner pair, lid mics, or added room mics - into one balanced, coherent tone. The engineer sets each mic's relative level and tonal weight so their captured regions merge without phase cancellation or tonal imbalance.", "plain_english": "It is mixing together the two or more mics used on one piano. You balance them so the piano sounds full and even. It is like blending a few photos of the same thing into one clear picture.", "purpose_function": "It merges several microphone perspectives on a physically large instrument into a single natural sound, capturing low strings, high strings, hammers, and room in proportion. It exists because no single mic position captures a piano's full range and scale convincingly.", "practical_application": "Tracking a grand, a technician balances an inner pair against lid or room mics in the console or DAW, adjusting relative levels and checking mono compatibility until the tone is even from bass to treble.", "category": "Piano Recording", "related_terms": ["Spaced pair", "Room microphone", "Piano phase alignment", "Stereo miking", "Microphone placement"], "common_mistakes": ["Blending mics without checking mono compatibility, so combining them causes comb filtering and a thin, hollow tone.", "Leaning too heavily on close mics, which yields a hard, boxy sound with no sense of the instrument's body or room.", "Matching mic levels by meter instead of by ear, ignoring how their tonal balance actually combines."], "scenario_contexts": ["Recording a jazz trio's grand piano with an inner pair plus a distant room mic and blending them for depth.", "Balancing lid and under-lid mics on a pop session so the piano is bright but still full.", "Adding a mono room mic to a close stereo pair to give a solo piano recording more space."]}, "639f3de7-dd58-413a-9946-55b12911c922": {"definition": "The set of processing and balancing decisions applied to recorded piano tracks within a mix - level, panning, EQ, dynamics, and effects - so the instrument sits clearly in the arrangement. It covers both solo-feature treatment and fitting the piano around vocals and other instruments.", "plain_english": "It is all the work you do to make a recorded piano sit well in a song. You set its volume, tone, and place across the speakers. The goal is a piano that is clear but does not cover the other parts.", "purpose_function": "It shapes the piano's level, tone, and space so it supports the song without masking or being masked by other parts. It exists because a raw piano recording rarely sits correctly against a full arrangement without deliberate balancing.", "practical_application": "A mix engineer cuts mud around 200 to 400 Hz, adds gentle compression, sets pan and level, and applies reverb so the piano supports the vocal rather than fighting it.", "category": "Piano Mixing", "related_terms": ["Equalization", "Compression", "Panning", "Frequency masking", "Piano subgroup"], "common_mistakes": ["Leaving the full, wide piano recording untouched so it masks the vocal and crowds the mix.", "Boosting highs for brightness without cutting low-mid buildup first, leaving the piano thin yet still muddy.", "Using heavy stereo width on a piano that must share space with other wide instruments, blurring the mix."], "scenario_contexts": ["Fitting a piano under a lead vocal in a ballad by carving low mids and narrowing its stereo width.", "Making a solo piano recording sound full and polished with EQ, light compression, and reverb.", "Balancing a rhythm piano against acoustic guitar so both stay clear."]}, "7a45da99-f1e1-4d0a-a71a-48d30982b895": {"definition": "Techniques for preventing mechanical noise from a piano's pedal mechanism - thumps, squeaks, and lyre or trapwork clatter - from being captured or heard in a recording. It combines instrument maintenance, mic placement away from the pedals, and corrective editing or gating.", "plain_english": "It means stopping the thumps and squeaks the piano pedals make from ending up in your recording. You keep mics away from the pedals, oil the parts, or edit the noise out later. It is like moving a mic away from a creaky chair.", "purpose_function": "It keeps distracting mechanical sounds out of an otherwise clean piano capture, since sensitive mics near the instrument readily pick up pedal and damper-lift noise. It exists because pedal noise can render an otherwise good take unusable.", "practical_application": "A technician lubricates or adjusts a squeaky pedal, positions mics away from the pedal lyre, and edits or gates residual thumps out of quiet passages in the DAW.", "category": "Piano Recording", "related_terms": ["Mechanical noise", "Microphone placement", "Noise gate", "Damper pedal", "Editing"], "common_mistakes": ["Placing a mic low toward the pedals for warmth and then capturing every pedal thump.", "Gating out pedal noise so aggressively that it chops the natural sustain and decay of notes.", "Ignoring a squeaky pedal on the instrument and hoping to fix a mechanical problem entirely in the mix."], "scenario_contexts": ["Recording a quiet solo piano piece where each damper-pedal thump is audible between phrases.", "Editing out a squeak from the sustain pedal that recurs through a ballad take.", "Repositioning mics after noticing pedal clatter during a classical session."]}, "97b4d333-4ee4-4e20-8fc4-b311a69ee1ae": {"definition": "The process of correcting timing and polarity relationships between multiple microphones on a piano so their signals sum coherently rather than cancelling. It addresses arrival-time differences between, for example, an inner pair and room mics, and the polarity of each mic relative to the others.", "plain_english": "When two mics record one piano, their sound can arrive at slightly different times. This can make the tone thin or hollow once you mix them together. Phase alignment lines the mics up in time so the sound stays full.", "purpose_function": "It prevents comb filtering and loss of low end that occur when time-offset mic signals combine, preserving a full, solid tone when the mics are blended or summed to mono. It exists because multiple mics at different distances capture the same sound at slightly different times.", "practical_application": "A technician checks polarity, nudges one mic's track in the DAW to align its waveform with another, or spaces mics by the 3:1 rule, listening in mono to confirm the blend stays full.", "category": "Piano Recording", "related_terms": ["Comb filtering", "Polarity", "3:1 rule", "Mono compatibility", "Piano microphone blend"], "common_mistakes": ["Confusing polarity inversion with time alignment and expecting a polarity switch to fix all arrival-time problems.", "Judging phase only in stereo and never checking mono, where cancellation is most obvious.", "Aligning waveforms visually without listening, so the tone that measures aligned still sounds thin."], "scenario_contexts": ["Blending close and room mics on a piano and flipping polarity to restore lost low end.", "Nudging a room-mic track earlier in the DAW so it lines up with the close pair.", "Setting mic spacing by the 3:1 rule to minimise phase issues before tracking."]}, "0c9b4ddd-7b88-487f-bc28-ca6c2897a450": {"definition": "The management of unwanted resonant buildup in a piano's sound - sympathetic string ringing, boomy low-mid notes, and room-excited resonances - so the recorded tone stays clear. It uses EQ, including narrow or dynamic cuts, physical damping, and mic placement.", "plain_english": "A piano can ring or boom on certain notes and sound muddy. Resonance control tames those loud, ringing notes. You might cut them with EQ or dampen the strings so the piano sounds clean.", "purpose_function": "It tames specific notes or frequency bands that ring or boom out of proportion, keeping the piano even across its range. It exists because a piano's many undamped and sympathetic strings can build resonances that muddy or dominate a mix.", "practical_application": "A technician sweeps a narrow EQ to find a booming note, applies a small static or dynamic cut, and may dampen strings or move mics to reduce sympathetic ringing at the source.", "category": "Piano Mixing", "related_terms": ["Resonant frequency", "Dynamic EQ", "Sympathetic resonance", "Notch filter", "Equalization"], "common_mistakes": ["Applying a wide, deep EQ cut that removes a resonant note but hollows out the whole instrument.", "Treating every boomy note with static EQ when a dynamic EQ would act only when the note sounds.", "Blaming the piano for resonance that is actually the room, and never testing mic position changes."], "scenario_contexts": ["Taming a single low note that booms every time it is played in a ballad.", "Using dynamic EQ to control sympathetic ringing that builds during sustained chords.", "Repositioning mics to reduce a room mode exciting the piano's low strings."]}, "caf89f50-d365-4714-a353-e7369db7a7fd": {"definition": "The shaping of a piano's width and spatial placement across the stereo field, including how far the bass-to-treble spread extends and where the instrument sits between the speakers. It is set through mic technique, panning of the mic pair, and stereo-width processing.", "plain_english": "This is how wide the piano sounds across your left and right speakers. You can make it narrow or spread it out. It also shapes where the low and high notes seem to sit in the stereo picture.", "purpose_function": "It controls how wide the piano appears and where it sits so it fits the arrangement and stays mono-compatible. It exists because a stereo piano can either add welcome width or crowd and unbalance a mix if left unchecked.", "practical_application": "A technician sets the pan spread of the two piano mics, may narrow the image so it does not swamp a dense mix, and checks in mono to ensure width does not cause cancellation.", "category": "Piano Mixing", "related_terms": ["Stereo width", "Panning", "Mono compatibility", "Spaced pair", "Stereo miking"], "common_mistakes": ["Panning the piano mics fully hard left and right so the image is unnaturally wide and collapses in mono.", "Mixing an audience-view and a player-view stereo perspective inconsistently across a project.", "Adding stereo-widening plugins that boost width but wreck mono compatibility."], "scenario_contexts": ["Narrowing a wide piano recording so a lead vocal and guitar have room in the center.", "Setting a natural left-to-right spread for a solo piano feature.", "Checking mono fold-down before committing to a wide piano image for broadcast."]}, "6a65b9d9-eefd-4404-a49d-abb175d276e4": {"definition": "A group bus to which all of a piano's microphone channels are routed so they can be controlled and processed together. A single fader adjusts the combined level, and bus processing such as EQ or compression can be applied to the whole instrument at once.", "plain_english": "It is a single fader that controls all the piano mic channels at once. You send every piano mic to this one group. Then you can raise, lower, or process the whole piano together.", "purpose_function": "It lets an engineer manage a multi-mic piano as one instrument, with one fader for level rides and one insert chain for shared processing, instead of adjusting each channel separately. It exists to simplify control and keep the mic blend consistent when riding levels.", "practical_application": "On a console or DAW, a technician routes the inner-pair and room mics to a stereo group, sets the internal blend, then rides and processes the group fader to place the whole piano in the mix.", "category": "Mix Routing", "related_terms": ["Subgroup", "Bus", "Group fader", "Bus compression", "Piano microphone blend"], "common_mistakes": ["Routing piano mics to a subgroup but still riding individual channels for level, which breaks the set blend.", "Applying heavy bus compression to the piano group without checking how it pumps against the mic balance.", "Forgetting to keep the group in stereo, collapsing a stereo piano to mono at the bus."], "scenario_contexts": ["Grouping four piano mics to one stereo subgroup for a single level ride during a live mix.", "Bus-compressing a multi-mic piano gently to glue the mics together.", "Muting the whole piano quickly during tracking by pulling one group fader."]}, "6052948c-b3f7-4fd2-8eb6-e02b6e77c461": {"definition": "The shaping of the sharp attack transient produced when a piano hammer strikes the string, using compression, limiting, or transient-shaping tools. It can soften percussive attacks for a smoother tone or emphasise them for more clarity and punch in a mix.", "plain_english": "Each piano note starts with a sharp knock as the hammer hits the string. Transient control shapes that sharp attack. You can soften it or make it punchier so the piano fits the track.", "purpose_function": "It manages the level and character of a note's initial attack so the piano's dynamics suit the arrangement and stay controlled through processing. It exists because a piano's percussive transients can be too aggressive or too soft for a given mix.", "practical_application": "A technician sets compressor attack and release, or uses a transient shaper, to tame spiky attacks that jump forward or to add bite so the piano cuts through a dense track.", "category": "Piano Mixing", "related_terms": ["Transient", "Compression", "Attack time", "Transient shaper", "Limiting"], "common_mistakes": ["Setting a fast compressor attack that clamps every hammer strike and dulls the piano's natural articulation.", "Boosting transients so hard the piano clicks and sounds unnatural.", "Confusing transient control with overall level compression and squashing dynamics instead of shaping the attack."], "scenario_contexts": ["Softening a pop piano's spiky attacks so they sit smoothly under a vocal.", "Adding attack with a transient shaper so a rhythm piano cuts through a busy band mix.", "Controlling loud hammer strikes on a close-miked upright before further processing."]}, "9855f55b-6804-437d-abb4-6486b98d6c5d": {"definition": "Techniques for reducing the scratchy, clicky noise a plectrum makes contacting guitar or bass strings so it does not distract in a recording. It combines playing technique and pick choice at the source with corrective EQ, de-essing, or editing afterward.", "plain_english": "A guitar pick can make a scratchy, clicky sound on the strings. Pick-noise control keeps that scratch from being too loud. You change how you pick, use a softer pick, or cut it with EQ later.", "purpose_function": "It keeps unwanted pick attack and string-scrape noise from dominating an otherwise clean guitar or bass tone. It exists because close miking and bright, articulate playing can exaggerate pick noise into a harsh, distracting artifact.", "practical_application": "A technician has the player adjust pick angle and attack or switch pick material, then tames residual high-frequency scratch with a gentle EQ cut or a de-esser tuned to the noise band.", "category": "Noise Control", "related_terms": ["De-essing", "Equalization", "Plectrum", "Piano transient control", "Direct injection"], "common_mistakes": ["Cutting broad high frequencies to kill pick noise and dulling the whole instrument's brightness.", "Trying to remove heavy pick noise in the mix instead of fixing pick angle and attack while tracking.", "Using a de-esser set so aggressively that it lisps the note attacks and flattens the tone."], "scenario_contexts": ["Reducing loud pick clicks on a close-miked acoustic guitar strum track.", "Taming scratchy attack on a bright bass DI played with a hard pick.", "De-essing the high scratch on a picked electric guitar part."]}, "8414e3cb-cc96-4483-90f6-df350d881512": {"definition": "A layering technique in which a copy of a recorded part is combined with the original after being shifted slightly in pitch, typically by a few cents up to a semitone, so the two versions fuse into a thicker, wider composite sound. The offset is often paired with small timing or panning differences to reinforce the effect.", "plain_english": "You copy a track and shift the copy a tiny bit up or down in pitch. Playing both at once makes the sound fuller and wider, like two singers who are almost but not quite in tune.", "purpose_function": "It thickens and widens a single part without recording a second performance, exploiting the small differences between the original and the pitch-shifted copy. This adds richness and stereo width from one take.", "practical_application": "An engineer duplicates a vocal or guitar track, nudges the copy a few cents sharp or flat, and pans the two apart to build width during mixing.", "category": "Layering Technique", "related_terms": ["Double tracking", "Quadruple tracking", "Detuning", "Chorus effect", "Stereo widening"], "common_mistakes": ["Shifting the pitch too far, so the layer sounds openly out of tune instead of thickened.", "Forgetting to pan the layers apart, which throws away the width the technique is meant to create.", "Applying it to a bass or lead line, where the detuning blurs the pitch and muddies the note."], "scenario_contexts": ["Widening a lead vocal in a pop mix.", "Thickening a synth pad going into a chorus.", "Building a wider rhythm-guitar bed from a single take."]}, "dfc78458-3b83-4e98-bd1a-467cd95d2fb5": {"definition": "A non-essential musical or sonic element added during production to enhance interest, movement, or polish, such as an ear-candy fill, an ornament, a percussion accent, or an effect flourish. It decorates the arrangement without carrying its core structure.", "plain_english": "A small extra sound added to a song to make it more interesting. The tune still works without it, like sprinkles on top of a cake.", "purpose_function": "It adds detail, surprise, and forward motion to an arrangement, keeping the listener engaged and giving sections their own identity.", "practical_application": "A producer drops in a reversed cymbal, a tambourine hit, or a filtered vocal chop at a transition to lift the moment.", "category": "Arrangement Technique", "related_terms": ["Ear candy", "Overdub", "Arrangement", "Fill", "Automation"], "common_mistakes": ["Adding so many embellishments that the arrangement becomes cluttered and busy.", "Letting an embellishment compete with the lead melody instead of supporting it.", "Treating an embellishment as a structural part the song depends on."], "scenario_contexts": ["Adding a riser just before a chorus.", "Placing a subtle shaker under a verse.", "Dropping an effect sweep at a section change."]}, "0c369905-3dd5-4325-832d-df4771af5cf7": {"definition": "A layering technique in which a performer records the same part four separate times and the four takes are combined, typically with two panned hard left and two hard right, to produce a thick, wide, powerful composite. It is most associated with distorted rhythm guitars in rock and metal.", "plain_english": "The same guitar part is played and recorded four times, then stacked together. This makes it sound huge and wide, like a small choir of the same guitar.", "purpose_function": "It builds a wall of sound with more thickness and stereo width than one take can give, because the small natural differences between takes fill out the stereo field.", "practical_application": "A metal guitarist plays the rhythm riff four times, and the engineer pans two takes hard left and two hard right for a wide, solid guitar bed.", "category": "Tracking Technique", "related_terms": ["Double tracking", "Pitch-offset layering", "Rhythm-guitar mixing", "Overdub", "Panning"], "common_mistakes": ["Playing the four takes so identically that the natural width disappears.", "Not checking tuning between takes, so intonation drifts and the stack sounds smeared.", "Stacking four tracks when the arrangement only needs two, which piles up mud."], "scenario_contexts": ["Tracking rhythm guitars for a metal record.", "Building a wide guitar wall in a rock chorus.", "Layering power chords for a heavy breakdown."]}, "7097d1c4-0823-43b0-96f7-a679ef2eaf93": {"definition": "The signal processing applied to rack toms, the smaller toms mounted above the kick drum, commonly including gating, EQ, transient shaping, and compression to control ring, tighten attack, and seat the toms in the mix.", "plain_english": "Shaping the sound of the small drums mounted over the bass drum. Engineers use tools to cut unwanted ringing and make each hit punchy.", "purpose_function": "It cleans up bleed and ring, sharpens the attack, and balances the toms so their fills cut through without muddying the rest of the kit.", "practical_application": "During a mix the engineer gates each rack tom to remove cymbal bleed, EQs out boxy mids, boosts attack, and adds a touch of compression.", "category": "Drum Processing", "related_terms": ["Noise gate", "Resonant head", "Transient shaping", "Equalization", "Compression"], "common_mistakes": ["Setting the gate threshold so tight that soft tom hits get cut off.", "Over-EQing until the toms sound thin and lifeless.", "Gating the close mics while ignoring loud tom bleed in the overheads."], "scenario_contexts": ["Mixing a rock drum kit with busy tom fills.", "Cleaning cymbal bleed off close tom mics.", "Tightening toms for a punchy modern drum sound."]}, "4b4dac84-f829-457c-9c89-7021fdb1112a": {"definition": "The drumhead mounted on the side of a drum opposite the struck batter head, which on most drums is the bottom head. It is not played directly but vibrates sympathetically to shape the drum's sustain, resonance, pitch, and tone.", "plain_english": "The drumhead on the side you do not hit, usually the bottom. It is not struck, but it rings along and controls how long and how full the drum sounds.", "purpose_function": "It sets the drum's sustain and overall tone; its tuning relative to the batter head decides pitch bend, how long the note rings, and how full it sounds.", "practical_application": "A drum tech tunes the resonant head to set sustain and pitch, tuning it near the batter head for a fuller, longer note or looser for more pitch drop.", "category": "Drum Component", "related_terms": ["Batter head", "Drumhead", "Drum tuning", "Rack-tom processing", "Sustain"], "common_mistakes": ["Thinking the resonant head is meant to be struck like the batter head.", "Removing the resonant head and losing the drum's natural sustain and tone.", "Tuning it with no regard for the batter head, which causes uncontrolled overtones."], "scenario_contexts": ["Tuning toms before a tracking session.", "Adjusting snare sustain from the reso-side tuning.", "Deciding whether to keep or remove the reso head for a drier sound."]}, "6390e355-085c-461e-a18a-297191cc12bd": {"definition": "The set of mixing decisions applied to rhythm-guitar parts, including level balance, panning, EQ, compression, and effects, to seat the chordal or riff-based guitar within the arrangement and control its interaction with vocals, bass, and drums.", "plain_english": "Balancing the chord-playing guitars in a song. The engineer sets their volume, spreads them left and right, and shapes their tone so they support the singer instead of covering it.", "purpose_function": "It positions the rhythm guitars for width and energy while carving space so they reinforce the groove without masking the vocal or clashing with the bass.", "practical_application": "The mixer pans doubled rhythm guitars left and right, high-passes to clear the low end for the bass, and dips mids that clash with the vocal.", "category": "Mixing Technique", "related_terms": ["Quadruple tracking", "Double tracking", "Panning", "Equalization", "Frequency masking"], "common_mistakes": ["Leaving too much low end in the guitars, so they fight the bass.", "Panning a single rhythm take to the center, wasting the stereo width.", "Setting the guitars so loud they bury the vocal."], "scenario_contexts": ["Mixing a rock band's chorus with doubled guitars.", "Fitting rhythm guitar around a lead vocal.", "Balancing guitars against bass in a dense arrangement."]}, "56e5e0ba-cd6c-47ee-9cf9-447bdeabe7bc": {"definition": "An arrangement and production technique of stacking several parts with complementary rhythmic patterns, such as a steady eighth-note part, a syncopated accent, and a percussion figure, so their combined interplay creates a fuller, more driving groove.", "plain_english": "Stacking several parts that each play a different rhythm. Together they lock into one bigger groove, like players whose patterns fit around each other.", "purpose_function": "It builds groove, energy, and density by combining patterns that fill different rhythmic spaces, giving the track motion without any single part being busy.", "practical_application": "A producer layers a straight rhythm guitar, an off-beat shaker, and a syncopated synth so the parts interlock into one groove.", "category": "Layering Technique", "related_terms": ["Rhythmic texture", "Production embellishment", "Pitch-offset layering", "Groove", "Arrangement"], "common_mistakes": ["Layering parts that share the same rhythm, which adds volume but no interest.", "Stacking too many busy patterns until the groove turns to clutter.", "Ignoring how the layers line up against the drums."], "scenario_contexts": ["Building a groove in a pop production.", "Adding percussion layers to a verse.", "Interlocking guitar and keys rhythms in a chorus."]}, "f6f34845-ea23-4792-8ea1-5fb864c9e822": {"definition": "The overall rhythmic character of a passage created by the combination and density of its rhythmic parts: how many rhythmic layers are present, how busy or sparse they are, and how their patterns interact. It is a quality of the whole arrangement rather than of one instrument's part.", "plain_english": "The overall feel made by all the rhythms in a section working together. A few simple parts feel open and calm; many busy parts feel thick and driving.", "purpose_function": "It shapes the energy and feel of each section, letting an arranger build contrast between sparse and dense moments to guide the listener.", "practical_application": "An arranger thins the rhythmic texture in a verse and thickens it in the chorus so the chorus feels like a lift.", "category": "Arrangement Concept", "related_terms": ["Rhythmic layering", "Production embellishment", "Arrangement", "Groove", "Dynamics"], "common_mistakes": ["Keeping the same dense texture through the whole song, so no section stands out.", "Confusing rhythmic texture with tempo.", "Adding parts without listening to how busy the whole texture becomes."], "scenario_contexts": ["Planning verse-to-chorus contrast.", "Arranging a build-up into a drop.", "Deciding how many rhythmic parts a section needs."]}, "9114a578-913a-4ae2-a4fc-7a51d3aec5c7": {"definition": "The raised, cup-shaped dome at the center of a ride cymbal. Struck with the shoulder or tip of the stick, it produces a bright, high-pitched, penetrating ping with less wash than the cymbal's bow, and is used for accents and clearly defined patterns.", "plain_english": "The raised cup in the middle of a ride cymbal. Hitting it gives a bright, bell-like ping that cuts through the band, clearer and sharper than the flat part.", "purpose_function": "It gives the drummer a cutting, clearly pitched accent that stands out over loud passages, useful for marking sections or driving a chorus.", "practical_application": "A drummer moves from the ride bow to the bell during the chorus for a louder, brighter pattern that cuts through the mix.", "category": "Cymbal Component", "related_terms": ["Ride cymbal", "Crash cymbal", "Hi-hat", "Overhead miking", "Cymbal wash"], "common_mistakes": ["Confusing the bell with the bow, the flat playing area of the ride.", "Miking the kit so the loud bell overpowers the overheads.", "Expecting the bell to give a washy sound like the cymbal's edge."], "scenario_contexts": ["Playing a driving bell pattern in a chorus.", "Accenting section changes on the ride bell.", "Setting overhead mic levels to tame a loud bell."]}, "3de7c438-d6ca-48ce-8108-16539652d06f": {"definition": "The bow is the broad, gently sloping playing surface of a ride cymbal that lies between the raised central bell and the outer edge. Struck with the stick tip, it produces the ride's defining articulate ping with a controlled amount of sustained wash.", "plain_english": "The bow is the wide, curved part of a ride cymbal between its raised center and its rim. When a drummer taps it with the stick tip, it makes a clear, steady ping.", "purpose_function": "It gives the ride cymbal a clear, repeatable stick sound for keeping time, with less wash than you get near the edge and less clang than the bell. This lets a drummer hold a steady pattern that the whole band can lock to.", "practical_application": "When miking a kit, a technician aims the overhead or a spot mic to capture the bow's articulate ping while keeping edge wash and bell ring under control.", "category": "Cymbals", "related_terms": ["Ride cymbal", "Bell", "Open hi-hat", "Overhead equalization", "Cymbal"], "common_mistakes": ["Confusing the bow with the bell, when the bell is the raised center that gives a louder, clangier accent.", "Playing or capturing the ride too near the edge, so wash builds up and the timekeeping ping gets lost.", "Boosting the highs on the overheads so much that the bow's ping turns harsh and brittle."], "scenario_contexts": ["Tracking a jazz kit where the drummer keeps time on the ride bow throughout a tune.", "Choosing a spot mic position that favors the bow's ping over edge wash in a loud rock mix.", "EQing overheads so a bright ride bow stays clear without piercing the vocal."]}, "a3c76174-69b3-4908-8288-03695ef0d683": {"definition": "The relative loudness and blend of the four standard choral voice parts, Soprano, Alto, Tenor and Bass, so that each line is heard clearly and the chords sit well together. It is judged both in a live ensemble and when capturing or mixing recorded voices.", "plain_english": "It means setting the four choir parts, high to low, so no part covers the others. Like a group photo, everyone should be seen, not just the tallest person in front.", "purpose_function": "It ensures the melody, harmony and bass line of a vocal arrangement are all audible and well blended, so the chords sound full and clear. Good balance keeps one section from masking another.", "practical_application": "A technician adjusts section levels, mic placement or fader rides so the sopranos, altos, tenors and basses each hold their place, often lifting the part carrying the tune.", "category": "Vocal Arrangement", "related_terms": ["Section microphone balance", "Sectional vocal panning", "Choir", "Blend", "Voicing"], "common_mistakes": ["Letting the sopranos dominate because they sit highest, so the inner alto and tenor lines disappear.", "Under-mixing the bass part, which removes the harmonic foundation and makes chords sound thin.", "Balancing sections in isolation instead of listening to how the four parts blend together as one chord."], "scenario_contexts": ["Setting choir section levels in a live worship service so all four parts are heard.", "Mixing a recorded vocal arrangement so the tenor line stays audible under the sopranos.", "Placing mics on a choir so no single section overpowers the others."]}, "d6ae82cb-33c3-44b8-b674-221d619c3f7a": {"definition": "The use of mix automation, recorded moves of level, mute, pan or effects, applied across a whole section of related tracks such as drums, horns or backing vocals grouped on a bus. It lets an engineer shape the section's part in the arrangement over time as a single unit.", "plain_english": "It means recording moves like volume or mute for a whole group of tracks at once. Instead of riding each track, you shape the whole section, like dimming a bank of lights together.", "purpose_function": "It lets an engineer bring a section forward or push it back at the right moments without editing every track by hand, keeping mix moves consistent and repeatable. This shapes how the arrangement builds and breathes.", "practical_application": "A technician groups the backing vocals or horns to a bus and writes automation on that bus to lift them in the chorus and duck them under the lead in the verse.", "category": "Mix Automation", "related_terms": ["Shell subgroup", "Section microphone balance", "Fader ride", "Bus", "Mute"], "common_mistakes": ["Writing automation on individual tracks when a single bus move would keep the section balanced and easier to edit.", "Making moves too abrupt, so a section jumps in level instead of rising or falling smoothly.", "Forgetting that bus automation stacks with track-level moves, causing unexpected jumps in loudness."], "scenario_contexts": ["Automating a horn section bus to swell into a chorus and drop back for the verse.", "Muting a backing-vocal group between phrases with one automation lane instead of many.", "Riding a whole drum submix down under a quiet breakdown section."]}, "90cfd531-75ae-444c-9a09-e8c44063002e": {"definition": "The setting of relative levels among the microphones capturing a section of players or singers, such as a horn line, string section or choir, so the section blends internally and sits correctly against the rest of the mix. It covers both the internal balance between section members and the section's overall level.", "plain_english": "It means setting the mics on a group of players so they blend well together and fit the mix. You want the group to sound like one unit, not a fight between loud and quiet mics.", "purpose_function": "It makes a multi-mic section sound like one coherent instrument and places that section at the right level under the lead parts. This avoids one player sticking out and keeps the section supportive.", "practical_application": "A technician sets each section mic's gain and fader by ear, matching players' levels and adjusting the group's total level, often with the mics grouped to a bus.", "category": "Microphone Technique", "related_terms": ["SATB balance", "Section automation", "Shell subgroup", "Bleed", "Blend"], "common_mistakes": ["Setting each mic loud on its own, so the summed section is far too prominent in the mix.", "Ignoring bleed between close mics, which changes the blend once all the faders are up.", "Balancing the section soloed instead of in the full mix, where its correct level is different."], "scenario_contexts": ["Balancing a three-piece horn section so no one player pokes out of the blend.", "Setting choir section mics so the whole ensemble sits under the lead vocal.", "Matching the levels of spot mics on a string section before grouping them to a bus."]}, "f9e57fc8-8dae-4d56-87d8-7b36cf0154ae": {"definition": "The placement of grouped vocal parts across the stereo field by section, for example spreading backing vocals or choir voice parts to the left and right rather than stacking them in the center. It is used to separate sections and widen the vocal arrangement.", "plain_english": "It means placing groups of voices to the left, right or center of the stereo image. Spreading the parts out lets each group be heard clearly, like seating singers across a stage.", "purpose_function": "It separates vocal sections so they do not mask each other and gives the arrangement width, while usually keeping the lead vocal centered. This clears space in the middle for the main voice.", "practical_application": "A technician pans doubled backing-vocal groups or choir parts out to the sides, balancing left and right, so the harmonies frame a centered lead.", "category": "Panning", "related_terms": ["SATB balance", "Section microphone balance", "Stereo image", "Double tracking", "Blend"], "common_mistakes": ["Panning sections so hard and wide that a chorus collapses to nothing when heard in mono.", "Leaving all vocal groups in the center, so the sections mask each other and the mix sounds cluttered.", "Panning unevenly, so one side of the stereo field is heavier than the other."], "scenario_contexts": ["Spreading two backing-vocal doubles left and right to widen a chorus around a centered lead.", "Placing choir voice parts across the stereo field so each section stays distinct.", "Checking a mono fold-down so hard-panned vocal sections still hold up."]}, "1a382e90-ecd8-4164-9044-c0246cf7287c": {"definition": "A mix bus that groups the microphones on the drum kit's shells, the kick, snare and toms, separately from the cymbals and overheads. Routing the shells to their own subgroup lets an engineer process and control the kit's body and punch as one unit.", "plain_english": "It is a group bus that brings the kick, snare and tom mics together, away from the cymbals. It lets you control the boomy, punchy part of the kit with one set of faders.", "purpose_function": "It lets an engineer level, EQ or compress the drum shells together for consistent punch, and ride or automate them without affecting the cymbals. This makes shaping and controlling the kit faster and more consistent.", "practical_application": "A technician routes the kick, snare and tom channels to a subgroup, then adds bus compression or a single fader move to control the whole low end of the kit at once.", "category": "Mix Grouping", "related_terms": ["Section automation", "Drum bus compression", "Bus", "Overhead compression", "Snare body enhancement"], "common_mistakes": ["Routing overheads and cymbals into the shell subgroup, which defeats the point of controlling the shells alone.", "Over-compressing the shell bus so the kit pumps and loses its natural attack.", "Forgetting that subgroup processing stacks on top of channel processing, causing a heavier effect than intended."], "scenario_contexts": ["Grouping kick, snare and toms to a bus to compress the body of the kit together.", "Riding a single shell-subgroup fader to control drum level during a quiet section.", "Adding EQ to the shell subgroup to tighten the kit's low end without touching the cymbals."]}, "8decb1c7-de54-44de-b781-f0c528d252b6": {"definition": "A snare-drum technique, also called rim click or cross-stick, in which the stick is laid across the drum with its tip on the head and its shaft struck against the rim, producing a short, dry, woodblock-like click instead of a full backbeat. It is notated as a distinct articulation and captured as a distinct sound in sampled kits.", "plain_english": "It is a quiet snare sound made by tapping the stick against the rim while its tip rests on the head. It gives a short, dry click, like a knock on a door, instead of a loud snare hit.", "purpose_function": "It provides a soft, understated backbeat for quiet or intimate passages, adding rhythm without the volume and crack of a full snare hit. Drummers use it to keep energy low in verses and ballads.", "practical_application": "When tracking or programming drums, a technician captures or selects the sidestick sound for softer sections and sets its level so the dry click sits clearly under the vocal.", "category": "Drum Technique", "related_terms": ["Snare", "Backbeat", "Snare body enhancement", "Groove", "Open hi-hat"], "common_mistakes": ["Confusing a sidestick with a rimshot, when a rimshot is a loud accent hitting head and rim together.", "Programming a sidestick at full snare level, so it loses its soft, intimate character.", "Placing the stick tip in the wrong spot on the head, which changes the pitch and dryness of the click."], "scenario_contexts": ["Playing sidestick through a ballad verse and switching to full snare in the chorus.", "Choosing the sidestick sample in a programmed beat for a laid-back groove.", "Setting the sidestick level so its dry click supports a quiet vocal without disappearing."]}, "fcb3ba91-7860-4a88-b306-eef44e1e0c5a": {"definition": "Processing that reinforces the fundamental tone and low-mid weight of a snare drum, the part that gives it fullness and thump, usually by boosting EQ in the roughly 150 to 250 Hz region or adding parallel or saturation processing. It aims to make a thin snare sound fuller without losing its crack.", "plain_english": "It means adding weight and fullness to a thin snare sound. You boost the lower part of its tone so it sounds fatter, while keeping the sharp crack on top.", "purpose_function": "It fills out a snare that sounds thin or papery so it has more body and power in the mix, balancing the low thump against the high crack. This helps the snare carry the backbeat.", "practical_application": "A technician boosts the snare's low-mid fundamental with EQ, or blends in parallel compression or gentle saturation, until the drum sounds full without becoming boxy.", "category": "Drum Processing", "related_terms": ["Snare", "Equalization", "Parallel compression", "Shell subgroup", "Snare clipping"], "common_mistakes": ["Boosting the low-mids too far, which makes the snare sound boxy and muddy instead of full.", "Adding body while forgetting the crack, so the snare loses its cut and disappears in the mix.", "Enhancing the snare in isolation, where the added weight clashes with the kick once both play together."], "scenario_contexts": ["Fattening a thin-sounding snare take with a low-mid EQ boost during mixdown.", "Blending parallel compression into a snare to add weight without killing its snap.", "Adding body to a tightly tuned snare so it holds the backbeat in a dense rock mix."]}, "460d4f37-e795-4692-8066-be916f8fc7a6": {"definition": "The use of a clipper, or hard limiting, on a snare drum to shave off the very top of its sharp transient, letting the track sit louder and more controlled without an audible level drop. Because the snare's peak is brief, a small amount of clipping raises its effective loudness while keeping the body intact.", "plain_english": "It means cutting off the very tip of the snare's loud spike so the drum can sit louder overall. The spike is so short that trimming a little of it is hard to hear.", "purpose_function": "It controls the snare's short, high peak so the drum can be pushed louder and steadier in a mix without triggering unwanted gain reduction elsewhere. This gives a consistent, up-front snare.", "practical_application": "A technician places a clipper on the snare channel and lowers the ceiling just enough to trim the sharpest transient peaks, checking by ear that the crack stays clean.", "category": "Drum Processing", "related_terms": ["Snare", "Transient", "Limiter", "Snare body enhancement", "Overhead compression"], "common_mistakes": ["Clipping too hard, which flattens the transient and turns the snare's crack into audible distortion.", "Confusing intentional clipping with accidental converter or preamp clipping while recording, which is a fault to avoid.", "Judging the clip amount soloed, when the acceptable amount is different once the full mix is playing."], "scenario_contexts": ["Trimming snare peaks with a clipper so the drum sits louder in a loud master.", "Using light snare clipping to keep the backbeat steady before bus compression.", "Controlling a sharp snare transient so it stops pulling down a bus limiter."]}, "2716709d-3fcb-4dc3-9f9d-8a8eb9b15a33": {"definition": "The application of dynamic-range compression to a snare drum signal, reducing the level difference between the loud initial transient and the quieter body and decay. Depending on attack and release settings it evens out hit-to-hit level, tames peaks, or adds sustain and perceived weight.", "plain_english": "A compressor makes the loud snare hits and the softer ones sit closer in volume. This keeps every hit even and can make the drum sound fuller and more powerful.", "purpose_function": "It controls the wide dynamic range of a struck snare so the drum stays consistent and present in a mix. By shaping the attack and decay it can also thicken the tone or hold back sharp peaks that would jump out.", "practical_application": "An engineer patches a compressor across the snare channel and sets ratio, threshold, attack and release to taste, often using a slower attack to preserve the crack. On live consoles the same is done with the channel's built-in dynamics section.", "category": "Drum processing", "related_terms": ["Snare equalization", "Snare gating", "Snare saturation", "Parallel compression", "Attack time", "Overhead compression"], "common_mistakes": ["Using too fast an attack, which crushes the snare's crack and makes it sound dull.", "Setting the release so slow that the compressor pulls up bleed and pumps between hits.", "Over-compressing so every hit sounds squashed and lifeless.", "Confusing compression with limiting and clamping down far harder than intended."], "scenario_contexts": ["Evening out a drummer whose snare hits vary in strength during tracking.", "Adding punch and sustain to a rock snare in a mix.", "Using parallel compression to add body while keeping the natural transient.", "Controlling snare peaks feeding a live front-of-house mix."]}, "8cb6f7bc-8585-4712-a5f0-c7330a7b36e3": {"definition": "Techniques that emphasise the sharp, high-frequency attack — the 'crack' — of a snare drum, typically through upper-mid and high-frequency EQ boosts, transient shaping, or parallel processing. The goal is to make the snare cut through a dense mix without simply raising its overall level.", "plain_english": "The crack is the sharp snap you hear the instant a stick hits the snare. Enhancing it means bringing out that snap so the drum cuts through the rest of the band.", "purpose_function": "It increases the snare's attack and definition so it reads clearly against loud guitars, cymbals and vocals. This keeps the drum punchy and articulate even when the whole mix is busy.", "practical_application": "An engineer boosts EQ around the attack and snap regions, adds a transient shaper to lift the initial hit, or blends in a parallel channel to bring out the crack, judging the amount against the full mix.", "category": "Drum processing", "related_terms": ["Snare equalization", "Snare compression", "Snare saturation", "Transient shaper", "Attack time", "Snare sample blend"], "common_mistakes": ["Boosting harsh high frequencies so much the snare becomes fatiguing or spitty.", "Chasing crack with EQ when the real problem is a slow compressor attack killing the transient.", "Using a transient shaper so aggressively the hit sounds clicky and unnatural.", "Enhancing the crack in solo without checking it against the full mix."], "scenario_contexts": ["Making a soft-sounding snare cut through a wall of distorted guitars.", "Adding a transient shaper to sharpen a dull recorded snare.", "Blending a parallel compressed channel to bring out attack on a pop snare.", "Lifting an attack EQ band so the snare reads clearly on small speakers."]}, "58f6790c-503f-4436-b0f1-35ece528b25a": {"definition": "The use of an equalizer to shape the tonal balance of a snare drum signal, for example adding body in the low mids, cutting boxy resonances in the low-to-mid range, and lifting attack and snap in the upper mids and highs. It tailors the snare's character so it fits the arrangement.", "plain_english": "EQ lets you turn different parts of the snare's tone up or down. You can add low-end thump, remove a boxy honk, or brighten the snap so the drum sounds the way you want.", "purpose_function": "It sculpts the snare's frequency balance so its body, attack and ring suit the song and sit clearly against the other instruments. It also removes problem resonances and bleed that muddy the drum.", "practical_application": "A technician cuts boxiness around a few hundred hertz, adds weight in the low mids, and lifts the highs for attack, checking the result in the full mix rather than in solo.", "category": "Drum processing", "related_terms": ["Snare compression", "Snare ring control", "Snare crack enhancement", "High-pass filter", "Overhead equalization", "Equalization"], "common_mistakes": ["Boosting the highs too much so the snare becomes harsh and fatiguing.", "Leaving boxy low-mid resonances that make the snare sound like a cardboard box.", "EQing the snare in solo instead of in context with the full kit and mix.", "Reaching for EQ to fix a problem that better tuning or damping would solve."], "scenario_contexts": ["Cutting a boxy low-mid frequency to clean up a dull recorded snare.", "Adding a high-shelf lift to brighten the snare's snap in a busy mix.", "High-passing a snare channel to remove kick and floor-tom rumble.", "Shaping snare tone to match the reference sound for a project."]}, "953ac7dc-d63e-4ad2-8f7a-a7ddb510d8e4": {"definition": "The use of a noise gate on the snare microphone channel to attenuate or mute the signal while the snare is not being struck, reducing bleed from the hi-hat, kick and rest of the kit. The gate opens on the snare's transient and closes during the gaps between hits.", "plain_english": "A gate is like an automatic switch that opens only when the snare is hit. It quiets the microphone in between hits so you hear less of the cymbals and other drums leaking in.", "purpose_function": "It cleans up the snare channel by removing spill from the rest of the kit, which tightens the drum sound and allows more aggressive EQ and processing. Cleaner isolation also makes the whole drum mix clearer.", "practical_application": "A technician sets the gate threshold above the bleed but below the snare hits, then adjusts attack, hold and release so the gate opens cleanly and closes without cutting the drum's natural decay.", "category": "Drum processing", "related_terms": ["Snare compression", "Snare microphone blend", "Snare sample blend", "Noise gate", "Threshold", "Bleed"], "common_mistakes": ["Setting the threshold so high the gate chops off soft ghost notes.", "Using a fast release that cuts the snare's natural decay and sounds choppy.", "Forgetting the gate can false-trigger from loud hi-hat or kick bleed.", "Gating so tightly the drums sound unnatural and disconnected."], "scenario_contexts": ["Removing hi-hat bleed from a snare track before heavy EQ and compression.", "Tightening a loose, ringy snare in a metal mix with a gate.", "Cleaning up spill on a live snare channel to get more gain before feedback.", "Key-triggering a gate from the snare mic to drive a sample or reverb."]}, "8dc2c494-2117-4226-94a3-7aa1ab5a12ad": {"definition": "The balancing of two or more snare mics — commonly a top mic capturing body and attack and a bottom mic capturing the wire snare's buzz — into a single composite snare tone. Because the mics face opposite drumheads, polarity and phase between them must be managed.", "plain_english": "Drummers often put one mic above the snare and one below. Blending means mixing the two so you get both the punch from the top and the buzz from the wires below.", "purpose_function": "It lets the engineer combine the strengths of each mic position to build a fuller, more controllable snare tone than a single mic gives. Managing their phase keeps the blended sound solid instead of thin.", "practical_application": "A technician flips the polarity of the bottom mic, then balances the two levels for the right mix of body and wire snap, checking the sound in mono to make sure the mics reinforce rather than cancel.", "category": "Drum miking", "related_terms": ["Snare gating", "Snare equalization", "Phase", "Polarity", "Bleed", "Overhead compression"], "common_mistakes": ["Leaving the bottom mic in the same polarity as the top, causing thin, hollow cancellation.", "Adding too much bottom mic so the snare sounds all buzz and no body.", "Ignoring hi-hat bleed the top mic picks up when both are blended.", "Blending without checking the result in mono for phase problems."], "scenario_contexts": ["Combining top and bottom snare mics to get both attack and wire snap.", "Flipping bottom-mic polarity so the blended snare sounds full instead of thin.", "Balancing snare mics against the overheads for a cohesive kit sound.", "Adjusting the top-to-bottom blend to add sizzle to a dead-sounding snare."]}, "f1352cae-3c16-47b5-9349-3c2a13370d95": {"definition": "The addition of artificial or natural reverberation to a snare drum to place it in a sense of space and add depth or sustain. Plate and room programs are common, and gated reverb — a reverb tail cut short by a gate — is a well-known snare effect.", "plain_english": "Reverb adds an echo-like sense of space around the snare. A little makes the drum sound like it is in a real room, while more can give the big, booming snare heard on many records.", "purpose_function": "It gives the snare depth, size and a place in a space so it sounds less dry and more produced, and it can add sustain to a short hit. The choice of reverb type strongly shapes the drum's character.", "practical_application": "A technician sends the snare to a reverb bus, chooses a plate or room program, and adjusts pre-delay, decay time and level so the effect adds space without washing out the mix.", "category": "Drum processing", "related_terms": ["Snare compression", "Snare gating", "Gated reverb", "Plate reverb", "Pre-delay", "Send"], "common_mistakes": ["Using so much reverb the snare loses punch and the mix sounds washed out.", "Setting pre-delay and decay without regard to the song's tempo, smearing the groove.", "Adding bright reverb that pushes an already harsh snare further into harshness.", "Printing reverb to the recorded track instead of using a send, losing later control."], "scenario_contexts": ["Sending a dry pop snare to a plate reverb for a classic sheen.", "Recreating an eighties gated-reverb snare for a retro production.", "Adding a short room reverb to glue close-miked drums together.", "Timing the reverb decay to the tempo so the tail clears before the next hit."]}, "004562bc-788f-44b4-bf2c-444845ceaf2f": {"definition": "The reduction of unwanted sympathetic ringing and overtones from a snare drum, achieved acoustically with dampening such as gel pads, tape or damping rings on the head, or electronically with narrow EQ cuts, gating or transient control. It tightens the snare's decay while preserving its fundamental tone.", "plain_english": "A snare often keeps ringing after it is hit. Ring control tames that long ring, using pads or tape on the drum or an EQ cut, so each hit sounds tighter.", "purpose_function": "It removes distracting overtones and sustain that clutter a mix or clash with other instruments, giving a focused snare sound. Controlling ring at the source usually beats trying to fix it later.", "practical_application": "A technician first tunes or dampens the drum with gel or a muffling ring, then, if needed, applies a narrow EQ cut at the ringing frequency or a gate to shorten the tail.", "category": "Drum damping", "related_terms": ["Snare equalization", "Snare gating", "Snare compression", "Damping", "Overtone", "Drum tuning"], "common_mistakes": ["Over-damping the head so the snare sounds dead and lifeless.", "Using a wide EQ cut that removes the ring but also the drum's tone.", "Treating all ring as bad when some ring gives the snare life and sustain.", "Reaching for EQ before trying to tune or dampen the drum itself."], "scenario_contexts": ["Placing a gel pad on the snare head to tame ring before tracking.", "Notching out a specific ringing frequency with a narrow EQ cut.", "Using a gate to shorten an overly long snare tail in a dense mix.", "Retuning the snare heads to remove sympathetic buzz from the bass."]}, "93add166-2158-43ca-8251-3ece5c95a633": {"definition": "The layering of a triggered or replacement snare sample underneath the recorded snare track, mixed in to reinforce attack, consistency or tone. The sample is usually triggered from the original snare hits so it stays in time, with its dynamics and phase matched to the live track.", "plain_english": "Sometimes engineers add a recorded snare sound under the real one. Blending the two gives a stronger, more consistent hit while keeping the feel of the live playing.", "purpose_function": "It shores up a weak, inconsistent or bleed-heavy recorded snare with a reliable sample, giving a bigger and more even sound while keeping the natural performance. It is a common fix when a re-record is not possible.", "practical_application": "Using a drum replacement or trigger plug-in, a technician detects each snare hit and plays a matched sample beneath it, then adjusts the blend and aligns timing and phase so the two sound as one.", "category": "Drum processing", "related_terms": ["Snare gating", "Snare compression", "Drum replacement", "Trigger", "Phase", "Snare crack enhancement"], "common_mistakes": ["Blending the sample so loud it replaces the natural drum and sounds fake.", "Ignoring timing and phase so the sample smears the original transient.", "False triggers from bleed adding sample hits where there was no snare hit.", "Choosing a sample whose tuning clashes with the recorded snare."], "scenario_contexts": ["Reinforcing a weak recorded snare with a triggered sample for more punch.", "Evening out an inconsistent drum take by blending a steady sample under it.", "Aligning a sample's phase with the live snare so the blend stays solid.", "Replacing a bleed-heavy snare while keeping the drummer's dynamics."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"0166d55a-3968-430b-90e0-e0af4f32947c": {"definition": "The application of harmonic saturation or mild distortion to a snare signal, adding harmonics that increase perceived loudness, weight and aggression. Tape, tube and transformer-style emulations are common, and it is often used in parallel so the clean transient is preserved.", "plain_english": "Saturation adds a bit of controlled grit to the snare, like gently overdriving it. This makes the drum sound louder, thicker and more aggressive without turning the volume up.", "purpose_function": "It adds harmonics that thicken the snare and help it cut through a mix, and the extra density can make the drum feel louder at the same level. Used in parallel it adds edge while keeping the natural attack.", "practical_application": "A technician inserts a tape, tube or console-style saturator on the snare or a parallel copy, drives it for the desired grit, and blends it in while matching levels so the change is about tone, not volume.", "category": "Drum processing", "related_terms": ["Snare compression", "Snare crack enhancement", "Snare equalization", "Harmonic distortion", "Parallel compression", "Tape saturation"], "common_mistakes": ["Adding so much saturation the snare sounds fizzy and harsh.", "Saturating the full channel and losing the clean attack instead of using a parallel path.", "Confusing gentle saturation with heavy distortion and overdoing the drive.", "Not level-matching, so the loudness boost is mistaken for a better tone."], "scenario_contexts": ["Driving a tape saturator on the snare to add weight to a rock mix.", "Using parallel saturation to add edge while keeping the natural crack.", "Thickening a thin sampled snare with tube-style harmonics.", "Adding grit to help a clean snare cut through distorted guitars."]}, "febcfda8-1da5-4f77-a771-154cfbd508f4": {"definition": "The practice of shaping how long a snare drum rings after each hit, using physical damping (moongel, tape, muffling rings) or signal processing (noise gating, expansion, transient shaping) to shorten or extend its decay so it suits the arrangement.", "plain_english": "This is how you control how long the snare rings after each hit. You can add a small gel pad to the head, or use a gate that cuts the sound off sooner. It is like resting your hand on a bell to stop the ringing fast.", "purpose_function": "It keeps the snare's ring from smearing the mix or masking other instruments, and stops the drum from sounding either too boomy or too lifeless. Controlling sustain helps the snare sit tightly with the rest of the kit and the song's tempo.", "practical_application": "A technician sticks a moongel pad on the batter head, tunes the drum, or sets a noise gate's hold and release, or dials in a transient shaper's sustain control to tighten a ringing snare during tracking or mixing.", "category": "Drum Processing", "related_terms": ["Snare-top processing", "Snare-drum mixing", "Noise gating", "Transient shaping", "Snare-wire control"], "common_mistakes": ["Gating a ringing snare so hard that soft ghost notes disappear", "Over-damping the head with tape until the drum sounds dead and toneless", "Confusing sustain (the ring after the hit) with the attack transient"], "scenario_contexts": ["Tightening a long-ringing snare in a fast rock song so it does not blur the groove", "Adding moongel during tracking to reduce overtones before the take", "Using a transient shaper in the mix to shorten snare decay that fights the guitars"]}, "cbc4b760-9747-446d-a217-29361021dd52": {"definition": "Signal processing applied to the bottom (snare-side) microphone of a snare drum, which chiefly captures the rattle of the snare wires; typical treatment includes high-pass filtering, EQ to lift wire crispness, gating to cut bleed, and phase alignment against the top mic.", "plain_english": "This is the work you do on the mic placed under the snare. That mic mostly picks up the buzzy wires on the bottom of the drum. You shape it with EQ and a gate so the snap of those wires is clear but not noisy.", "purpose_function": "It brings out the bright, buzzy 'snap' of the snare wires that the top mic misses, adding crispness and definition. It exists so the engineer can blend wire detail into the snare sound without extra bleed from the rest of the kit.", "practical_application": "A technician high-passes the bottom mic, boosts around the wire buzz, checks polarity so it adds instead of cancelling with the top mic, and often gates it to remove hi-hat bleed.", "category": "Drum Processing", "related_terms": ["Snare-top processing", "Snare-wire control", "Phase alignment", "Noise gating", "Snare-drum mixing"], "common_mistakes": ["Leaving the bottom mic out of polarity with the top mic, causing partial cancellation that thins the snare", "High-passing the bottom mic too aggressively, losing the wire crispness the mic is there to capture", "Boosting the bottom mic so much the hi-hat bleed becomes obvious"], "scenario_contexts": ["Blending a bottom-mic track under the top mic to add wire snap in a mix", "Gating the bottom mic to cut heavy hi-hat spill", "Checking polarity between top and bottom snare mics at the start of a session"]}, "dc07e0f8-2adc-4791-b63b-645c74aa90e0": {"definition": "The overall process of balancing and shaping the snare drum within a drum kit and full mix, combining level, EQ, compression, gating, transient shaping and often parallel compression or reverb across the top and bottom snare microphones.", "plain_english": "This is the whole job of making the snare sound right in a song. You set its level, shape its tone with EQ, and even it out with compression. The goal is a snare that cuts through clearly without being harsh.", "purpose_function": "It gives the snare the power, tone and consistency needed to anchor the backbeat and drive the song. Because the snare is a focal point of most drum parts, mixing it well shapes the whole feel of the rhythm section.", "practical_application": "A technician balances the top and bottom snare mics, applies EQ and compression, gates out bleed, and may add reverb or a parallel-compressed copy to make the snare sit strongly in the mix.", "category": "Drum Mixing", "related_terms": ["Snare-top processing", "Snare-bottom processing", "Parallel compression", "Noise gating", "Drum bus"], "common_mistakes": ["Over-compressing the snare until it pumps and loses dynamics", "Adding so much reverb the backbeat gets washed out and loses punch", "Ignoring phase between the snare mics and the overheads"], "scenario_contexts": ["Building a punchy snare sound for a rock mix from top and bottom mics", "Adding parallel compression to thicken a thin-sounding snare", "Matching snare tone and level across sections of a song"]}, "430ad23e-103d-436e-876d-f7ad8471cb73": {"definition": "Signal processing applied to the top (batter-side) microphone of a snare drum, which captures the drum's attack, body and tone; typical treatment includes EQ, compression, transient shaping and gating to control bleed.", "plain_english": "This is the work you do on the mic placed above the snare. That mic picks up the main crack and body of the drum. You shape it with EQ and compression so the hit is strong and even.", "purpose_function": "It shapes the core sound of the snare, the attack and fullness that most listeners hear as the backbeat. It exists so the engineer can make the main snare tone punchy, even and clear before blending in the bottom mic.", "practical_application": "A technician EQs the top mic for body and crack, compresses it for even hits, applies transient shaping for attack, and gates it to reduce hi-hat and tom bleed.", "category": "Drum Processing", "related_terms": ["Snare-bottom processing", "Snare-drum mixing", "Transient shaping", "Noise gating", "Parallel compression"], "common_mistakes": ["Boosting harsh high-mids until the snare sounds brittle", "Compressing so hard the natural attack is squashed flat", "Gating too tightly so quiet ghost notes are cut off"], "scenario_contexts": ["Shaping the main snare tone in a pop or rock mix", "Compressing the top mic to even out a drummer's uneven hits", "Gating the top mic to reduce spill from the hi-hat"]}, "7ddc2e05-2830-4908-bbb6-ebf7059e2447": {"definition": "Managing the sound of the snare wires (the coiled strands stretched across the bottom head) through tension adjustment via the throw-off/strainer, drum tuning, and mix processing such as gating or EQ to control unwanted sympathetic buzz.", "plain_english": "The snare wires are the springy strands under the drum that give it its buzz. Controlling them means setting how tight they sit and taming extra buzz. You adjust the strainer on the drum, or use a gate and EQ in the mix.", "purpose_function": "It sets how crisp or loose the snare's buzz sounds and reduces annoying sympathetic rattle when other instruments play. Good wire control keeps the snare lively without a constant buzzing ring bleeding into the rest of the kit.", "practical_application": "A technician adjusts the strainer tension on the drum, retunes the bottom head, or in the mix uses gating and EQ to reduce sympathetic snare buzz picked up from the bass or toms.", "category": "Drum Processing", "related_terms": ["Snare-bottom processing", "Snare sustain control", "Sympathetic resonance", "Noise gating", "Snare-drum mixing"], "common_mistakes": ["Cranking wire tension so tight the snare chokes and loses buzz", "Leaving wires so loose they rattle and sustain uncontrollably", "Blaming mic bleed for buzz that is really sympathetic wire rattle"], "scenario_contexts": ["Adjusting the strainer to fix a snare that buzzes when the bass plays", "Tuning the snare-side head for a crisper wire response before tracking", "Gating in the mix to cut sympathetic snare buzz between hits"]}, "a986e5a7-dcda-436d-97c0-67f0003bad98": {"definition": "Setting the level of a featured solo part relative to the accompaniment so the soloist stays clearly audible and prominent without overpowering the ensemble, using fader level, and often gain riding and light compression.", "plain_english": "This means setting how loud the soloist is against the rest of the band. You want them clearly on top but not so loud the band disappears. It is like making sure the lead singer stands out over the music.", "purpose_function": "It keeps the featured player or singer at the front of the mix where the listener's attention should be, while the accompaniment supports rather than covers them. It exists to preserve the musical hierarchy the arrangement intends.", "practical_application": "An engineer sets the soloist's fader above the accompaniment, rides the level through quiet and loud passages, and may add gentle compression so the solo stays present throughout.", "category": "Mix Balance", "related_terms": ["Soloist ride", "Fader riding", "Gain staging", "Vocal level", "Mix balance"], "common_mistakes": ["Setting the solo loud in one passage and losing it when the band gets louder", "Compressing the soloist so hard it sounds unnatural and pinned in place", "Boosting the soloist's level instead of pulling the accompaniment down when it is masking them"], "scenario_contexts": ["Keeping a guitar solo above the rhythm section during a build", "Balancing a saxophone feature over a full horn arrangement", "Riding a vocal ad-lib so it stays clear over the chorus"]}, "3fa5e10f-08bc-443d-930c-17e8d578d88a": {"definition": "The technique of continuously adjusting (riding) a soloist's fader or gain during a performance or mix so the solo stays at a consistent, prominent level against changing accompaniment dynamics.", "plain_english": "This is moving the soloist's fader up and down as the song plays. You push it up in quiet parts and ease it back when the band gets loud. It keeps the solo sitting at the same clear level the whole way through.", "purpose_function": "It smooths out the natural loud and soft moments of a solo so it never gets buried or jumps out too far. Riding by hand or with automation gives a more musical result than a compressor alone.", "practical_application": "An engineer keeps a hand on the soloist's fader (or draws automation) throughout the take, nudging it up on weak notes and down on strong ones to hold a steady balance.", "category": "Fader Automation", "related_terms": ["Soloist balance", "Fader riding", "Automation", "Gain riding", "Mix balance"], "common_mistakes": ["Making rides so large and sudden they sound unnatural and obvious", "Riding the level up but forgetting to bring it back down after the loud section", "Relying only on a compressor when small manual rides would sound smoother"], "scenario_contexts": ["Riding a fiddle solo up during a quiet verse in a live mix", "Automating a lead vocal fader to hold ad-libs steady", "Nudging a solo up over a loud band passage so it stays audible"]}, "aa4ebf06-3e83-4cdb-b451-570fcf0308fd": {"definition": "Setting the relative level and blend of the soprano (highest) voices within a choir or vocal ensemble so they carry the melody clearly while blending with the alto, tenor and bass sections, achieved through mic placement, section levels and EQ.", "plain_english": "In a choir the sopranos are the highest voices and often carry the tune. Balancing them means setting how loud they sit against the other sections. You want them clear on top but still blended, not sticking out too far.", "purpose_function": "It ensures the melody line the sopranos usually carry is present and clear without covering the harmony parts below. Balancing the section keeps the whole choir sounding unified rather than top-heavy or thin.", "practical_application": "An engineer positions or levels the soprano section mics, adjusts their fader against the other sections, and uses gentle EQ so the sopranos lead the blend without harshness.", "category": "Ensemble Balance", "related_terms": ["Alto section balance", "Choir balance", "Sectional balance", "Blend", "Stereo imaging"], "common_mistakes": ["Pushing the sopranos so loud the inner harmony parts vanish", "Boosting high frequencies until the sopranos sound harsh and sibilant", "Balancing sections in solo instead of in the context of the full choir"], "scenario_contexts": ["Bringing up the sopranos so the melody carries over a full choir", "Balancing choir sections with spaced overhead mics in a hall", "EQing the soprano section to reduce harshness on high notes"]}, "f97329bc-ec7b-45f9-aad4-0b647b802f19": {"definition": "A stereo-placement technique in which multiple vocal tracks (usually doubled or layered backing vocals) are panned to offset positions across the stereo field rather than stacked at center, widening the vocal image and separating individual parts.", "plain_english": "This is spreading backing vocals across the stereo field instead of piling them all in the middle. One take sits a bit left, another a bit right, and so on. It makes the vocals sound wider and easier to tell apart.", "purpose_function": "It widens the stereo image of layered or doubled vocals and keeps each part distinct so the stack does not sound crowded in the center. It exists to add width and clarity without simply turning parts up.", "practical_application": "An engineer records or copies several vocal takes and pans them to spread positions (for example hard left and right for a double, or fanned out for a three-part stack) to build a wide, clear vocal bed.", "category": "Stereo Imaging", "related_terms": ["Double tracking", "Backing vocals", "Panning", "Stereo width", "Mix balance"], "common_mistakes": ["Panning a single mono vocal take to one side, leaving the stereo field lopsided", "Spreading vocals so wide the center of the mix feels empty", "Panning identical copies of the same take, which just moves it rather than widening it"], "scenario_contexts": ["Panning a doubled backing vocal hard left and right for width", "Fanning out a three-part harmony stack across the stereo field", "Placing layered gang-vocal takes at staggered positions in a chorus"]}, "3856554a-3087-4b71-90b7-4c43facbc8b2": {"definition": "An arrangement and production technique in which multiple string parts or string recordings are stacked together, such as separate violin, viola, and cello lines or several passes of the same part, to build a fuller and richer string sound. The layers may be real players, sampled libraries, or synthesized strings blended into one section.", "plain_english": "It means stacking several string parts on top of each other to make one big, full string sound. It works like many singers on the same tune instead of just one.", "purpose_function": "It thickens and enriches a string section so it sounds larger and more emotional than a single part, and it fills out the arrangement behind the main instruments. Layering also lets a producer combine real and sampled strings to get both realism and size.", "practical_application": "A technician records or programs several string lines, tunes and times them together, then balances their levels and panning so the layers blend into one cohesive section without sounding cluttered.", "category": "Arrangement Layering", "related_terms": ["Octave layering", "Synthesizer layering", "Doubling", "Sustain reinforcement", "Panning"], "common_mistakes": ["Stacking so many string layers that they mask the vocals and mid-range instruments in the mix.", "Leaving layered parts slightly out of tune or out of time, which makes the section sound smeared instead of full.", "Piling on layers to fix a weak arrangement instead of choosing parts that actually complement each other."], "scenario_contexts": ["Building a lush string pad under a ballad chorus by combining sampled strings with a live quartet.", "Layering octave copies of a cello line to give a film cue more weight and depth.", "Blending synthesized strings with recorded strings so a small session sounds like a larger ensemble."]}, "fb65f643-3f5a-4fd8-b4f8-838a8dd24d84": {"definition": "The EQ, compression, gating, and phase alignment applied to a subkick signal, which is the output of a large-diaphragm transducer (often a repurposed loudspeaker such as a Yamaha SubKick) placed near the kick drum to capture very low sub-bass energy. It is processed and blended with the close kick mic to add weight and low-end extension.", "plain_english": "A subkick is a big speaker used like a mic to catch the deep low boom of a kick drum. Subkick processing is the EQ and other treatment on that signal, mixed under the normal kick mic to add extra low-end power.", "purpose_function": "It captures and shapes the very low frequencies a normal kick mic can miss, giving the drum extra depth and body in the mix. Careful processing and phase alignment keep this sub layer tight and in step with the main kick so it adds power without muddiness.", "practical_application": "A technician high-cut filters the subkick to keep only the lows, checks its phase against the close kick mic, and blends a controlled amount underneath to reinforce the bottom end of the drum.", "category": "Drum Processing", "related_terms": ["Kick drum miking", "Phase alignment", "Low-pass filter", "Parallel compression", "Gating"], "common_mistakes": ["Blending the subkick without checking polarity, so it fights the close kick mic and thins out the low end.", "Leaving the subkick full-range instead of filtering it, which adds boxy mid-range and clutter.", "Pushing the subkick too loud so the kick becomes boomy and swamps the bass guitar."], "scenario_contexts": ["Adding weight to a rock kick drum by blending a filtered subkick under the beater mic.", "Checking and flipping polarity between the subkick and inside kick mic to keep the low end solid.", "Reinforcing sub energy on a metal kick so it translates on large club systems."]}, "3cfea395-86fc-420e-8fcd-10fd269da076": {"definition": "A short, recurring melodic or rhythmic figure that reinforces the main theme of an arrangement without competing with it, often placed in a secondary instrument or lower in the mix. It adds interest and continuity while leaving the lead line as the focus.", "plain_english": "It is a small musical phrase that repeats to back up the main tune. It supports the melody the way a background chant supports a lead singer, without stealing attention.", "purpose_function": "It gives an arrangement extra depth and forward motion by echoing or answering the main theme, tying sections together. Because it sits behind the lead, it keeps the listener engaged without cluttering the focus of the song.", "practical_application": "An arranger writes a simple repeating figure for a guitar, synth, or string part, then places it lower in the mix and in a different register so it supports rather than masks the lead melody.", "category": "Arrangement", "related_terms": ["Counter-melody", "Hook", "Ostinato", "Call and response", "Sustain reinforcement"], "common_mistakes": ["Writing a supporting motif that is as loud or busy as the lead, so the two parts fight for attention.", "Placing the motif in the same register as the vocal, which masks both parts.", "Repeating the figure so often with no variation that it becomes tiring instead of supportive."], "scenario_contexts": ["Adding a repeating guitar figure under the verses to keep energy moving beneath the vocal.", "Writing a short synth phrase that answers the chorus melody in the gaps between vocal lines.", "Using a low string motif to tie the intro, verse, and bridge of a song together."]}, "03e11e19-eab0-43b5-a535-28d11be6b16c": {"definition": "Techniques used to extend or strengthen the sustained portion of a note or instrument, such as layering a pad or held part underneath, using compression to hold the tail up, or adding a sustaining effect. It fills the space between note attacks so a part rings out longer and more evenly.", "plain_english": "It means making a note hold and ring out longer and steadier. You can do this by layering a held sound under it or using a compressor, like adding a soft pad behind a piano chord so it does not fade too fast.", "purpose_function": "It keeps a part from dropping out or feeling thin between hits, giving the arrangement a smoother and more connected sound. Reinforcing sustain helps short, plucky, or decaying instruments sit fuller in a mix.", "practical_application": "A technician layers a quiet pad or long sample under a sparse part, or uses compression and reverb, so the sustained portion of the sound holds up and the gaps between notes feel filled.", "category": "Arrangement Layering", "related_terms": ["Pad", "Compression", "String layering", "Reverb", "Supporting motif"], "common_mistakes": ["Adding so much sustain or reverb that note articulation and rhythm get lost.", "Layering a sustaining pad that clashes in pitch or tuning with the original part.", "Over-compressing to force sustain, which pulls up noise and dulls the natural dynamics."], "scenario_contexts": ["Layering a soft synth pad under a staccato piano part so the chords do not feel empty between hits.", "Using compression on a clean guitar so its notes ring out longer and more evenly.", "Adding a held string layer under a plucked instrument to smooth over the gaps in an arrangement."]}, "1c8235c7-48db-4fb4-a75e-e7dfcad164b4": {"definition": "The production technique of stacking two or more synthesizer sounds or patches together to create one richer, fuller composite tone. Layers are often chosen to cover different frequency ranges, such as a sub layer, a body layer, and a bright top layer, and are blended and tuned to sit as a single sound.", "plain_english": "It means stacking two or more synth sounds to make one bigger sound. Each layer covers a different job, like one for the deep lows and one for the bright top, blended together like ingredients in a recipe.", "purpose_function": "It builds a wider and more powerful synth tone than a single patch can give, letting a producer combine the best parts of several sounds. Splitting layers by frequency range also keeps the composite clear instead of muddy.", "practical_application": "A technician stacks a sub-bass patch, a mid-body patch, and a bright layer, matches their tuning and timing, then filters and balances each so they fuse into one sound rather than clashing.", "category": "Arrangement Layering", "related_terms": ["Synthesizer layering", "Octave layering", "String layering", "Synthesizer subgroup", "Filtering"], "common_mistakes": ["Stacking layers that all occupy the same frequency range, which builds mud instead of richness.", "Leaving layers slightly detuned or out of time so the combined sound smears or beats unpleasantly.", "Using too many layers, making the sound huge in solo but impossible to fit in the full mix."], "scenario_contexts": ["Combining a sub patch and a bright saw patch to build one powerful lead sound.", "Layering a warm pad under a plucky synth so a hook has both attack and body.", "Splitting a big synth sound across sub, mid, and top layers to keep it clear in a busy mix."]}, "917c8272-ef6f-4f43-bb75-afdfcc6109aa": {"definition": "The process of balancing and processing a synthesizer bass part so it sits properly in a mix, covering EQ, compression, level, and its relationship to the kick drum and other low-end sources. It focuses on controlling the low frequencies so the synth bass is powerful yet clear and translates across playback systems.", "plain_english": "It is the work of getting a synth bass to sit right in a song. You use EQ, compression, and level so it feels powerful but stays clear, and share the low space with the kick drum instead of fighting it.", "purpose_function": "It makes the synth bass anchor the low end with a solid, even level while staying out of the way of the kick drum. Good processing also helps the bass sound consistent on big speakers, earbuds, and phone speakers alike.", "practical_application": "A technician EQs and compresses the synth bass, carves space so it and the kick each own part of the low end, and checks the mix on several systems to confirm the low end holds up.", "category": "Mixing Technique", "related_terms": ["Synthesizer mixing", "Sidechain compression", "Low-pass filter", "Kick drum miking", "Subkick processing"], "common_mistakes": ["Letting the synth bass and kick occupy the exact same frequencies so the low end turns muddy and weak.", "Mixing the bass only on one set of speakers, so it disappears or booms on other systems.", "Adding heavy sub without checking mono, causing the bass to vanish on club and phone speakers."], "scenario_contexts": ["Sidechaining a synth bass to the kick so both punch through cleanly in an electronic track.", "EQing a synth bass to sit under a vocal and guitars without clouding the mix.", "Checking a synth-bass mix on headphones, monitors, and a phone to confirm it translates."]}, "91d659ee-e5e4-4f4e-9d9a-5f3c0e71a860": {"definition": "The production technique of stacking two or more synthesizer sounds or patches into one composite tone that is fuller and richer than any single sound. Layers are commonly assigned to different frequency ranges and are tuned, timed, and filtered so they blend into a single perceived instrument.", "plain_english": "It means playing several synth sounds together so they act as one bigger sound. Each layer does a different job, like the deep low, the middle body, and the bright top, mixed into one.", "purpose_function": "It creates a larger, more complex synth tone than one patch could produce and lets a producer combine the strengths of several sounds. Dividing the layers by frequency keeps the result clear rather than cluttered.", "practical_application": "A technician stacks patches such as a sub, a body, and a bright layer, matches their tuning and timing, then balances and filters each so they fuse into one cohesive sound.", "category": "Arrangement Layering", "related_terms": ["Synth layering", "Octave layering", "String layering", "Synthesizer subgroup", "Synthesizer mixing"], "common_mistakes": ["Layering patches that share the same frequency range, which builds mud instead of size.", "Leaving the layers detuned or out of time so the combined sound smears.", "Using too many layers, so the sound is huge alone but will not fit in the full mix."], "scenario_contexts": ["Stacking a sub patch, a saw body, and a bright top to build one wide lead sound.", "Blending a warm pad with a sharp pluck so a hook has both punch and body.", "Dividing a big synth across sub, mid, and top layers to keep it clear in a busy arrangement."]}, "7696a1bc-369b-4381-9bc4-7810d52d4908": {"definition": "The balancing and processing of synthesizer parts within a mix, using level, panning, EQ, compression, and effects so each synth occupies its own space and supports the arrangement. It addresses how synth sounds, which are often wide and full-range, fit alongside vocals, guitars, drums, and bass.", "plain_english": "It is the work of fitting synth parts into a song. You use level, panning, EQ, and effects so each synth has its own space and does not cover the vocals or other instruments.", "purpose_function": "It keeps rich, full-range synth sounds from masking each other and the rest of the band, so the mix stays clear and balanced. Careful processing lets synths add color and size without swamping the arrangement.", "practical_application": "A technician EQs and pans each synth, controls its dynamics, and carves space around vocals and drums so the synth parts blend into the mix instead of dominating it.", "category": "Mixing Technique", "related_terms": ["Synth-bass mixing", "Synthesizer subgroup", "Equalization", "Panning", "Synthesizer layering"], "common_mistakes": ["Leaving wide, full-range synth patches unfiltered so they mask vocals and guitars.", "Panning every synth to the center, which crowds the middle of the mix.", "Judging synth levels in solo instead of against the full mix, so they end up too loud."], "scenario_contexts": ["EQing a lead synth to sit above the guitars while a pad fills the background.", "Panning layered synths across the stereo field to open up space for the vocal.", "Automating synth levels so they support the verse quietly and lift into the chorus."]}, "54bcc344-2ab6-4deb-baa0-438cc4188883": {"definition": "A subgroup or bus to which several synthesizer tracks are routed so they can be controlled and processed together as one unit. It allows shared level control, EQ, compression, or effects across all the grouped synths and simplifies balancing them against the rest of the mix.", "plain_english": "It is one bus that several synth tracks feed into so you can treat them as a group. It works like a single fader and set of effects for all the synths at once, so you can adjust them together.", "purpose_function": "It lets an engineer set the overall level and apply shared processing to a whole group of synths with one control instead of many. Grouping also helps glue the synths together and keeps the main mix session organized.", "practical_application": "A technician routes all the synth tracks to a subgroup bus, then uses that bus fader to balance the synths against the band and adds bus compression or EQ to glue and shape them as a unit.", "category": "Signal Routing", "related_terms": ["Subgroup", "Bus", "Bus compression", "Synthesizer mixing", "Synth layering"], "common_mistakes": ["Routing synths to a subgroup but still adjusting each track's fader, losing the benefit of one shared control.", "Applying heavy bus processing that suits some synths but crushes others in the group.", "Forgetting that muting or automating the subgroup affects every synth routed to it at once."], "scenario_contexts": ["Routing all synth parts to one subgroup so a single fader rides them under the vocal.", "Adding gentle bus compression on a synth subgroup to glue the layers into one texture.", "Muting the synth subgroup in a breakdown to drop out every synth part together."]}, "5aea73f6-251b-43ab-9499-b0606e049278": {"definition": "A layer of sound produced by synthesizers or other electronic sources rather than acoustic instruments, used to add atmosphere, color, or depth to an arrangement.", "plain_english": "A background sound made by a synth instead of a real instrument. It fills out a song and adds mood, like a soft pad humming under the band.", "purpose_function": "It adds sonic color and fills space in an arrangement without bringing in another acoustic instrument, shaping mood and depth.", "practical_application": "A producer records or programs synth pads, drones, or effects and blends them under the band to thicken the track.", "category": "Arrangement", "related_terms": ["Texture layering", "Timbre layering", "Tonal texture", "Pad", "Synthesizer"], "common_mistakes": ["Letting the synth texture compete with the lead parts instead of sitting underneath", "Choosing a patch that clashes with the song's key or mood", "Adding so many layers that the mix turns cluttered and muddy"], "scenario_contexts": ["Adding a warm pad under a sparse verse to keep the energy up", "Layering a synth drone beneath acoustic guitar for depth", "Building an electronic atmosphere for an intro before the band enters"]}, "535e7565-0120-4f81-8284-56282f334d83": {"definition": "The adjustment of relative loudness and blend among the tenor voices or parts within an ensemble section so they sit correctly against the other sections.", "plain_english": "Setting how loud the tenor singers or parts are next to the rest. The aim is for the tenor line to be heard clearly but still blend with the group.", "purpose_function": "It ensures the tenor line supports the harmony at the right level, neither buried nor sticking out.", "practical_application": "A tracking or mix engineer rides faders or coaches placement so the tenor part balances with the soprano, alto, and bass lines.", "category": "Sectional Balance", "related_terms": ["Sectional balance", "Blend", "Vocal layering", "Level balancing", "Tonal texture"], "common_mistakes": ["Pushing the tenors so loud they cover the melody", "Treating the tenor part as a solo line and ignoring blend", "Setting balance in solo instead of against the full section"], "scenario_contexts": ["Mixing a backing-vocal stack where the tenor part must sit under the lead", "Balancing a vocal group so each section stays clear", "Adjusting the tenor voices of a horn or string section in a band arrangement"]}, "e1131d3d-87ec-45be-a9be-4d3ceed114c2": {"definition": "The technique of combining multiple sound sources or parts to build a fuller, more complex overall texture in an arrangement.", "plain_english": "Stacking several sounds together to make the music feel bigger and richer. It is like layering clothes to build a fuller outfit.", "purpose_function": "It adds depth, width, and interest to an arrangement by combining complementary layers.", "practical_application": "A producer stacks rhythm parts, pads, and doubles, then balances them so the layers blend into one thick texture.", "category": "Arrangement", "related_terms": ["Timbre layering", "Synthetic texture", "Tonal texture", "Doubling", "Blend"], "common_mistakes": ["Layering sounds that share the same frequency range and clash", "Adding layers without checking the mix stays clear", "Forgetting to balance levels so one layer dominates"], "scenario_contexts": ["Building a big chorus by stacking guitars, keys, and vocals", "Adding subtle layers to fill a thin-sounding verse", "Blending acoustic and electronic parts into one texture"]}, "e0a8b552-b41e-483f-85bc-b8165cf63c0a": {"definition": "Combining sounds of differing tonal color, or timbre, so they fuse into a single composite tone that carries characteristics of each source.", "plain_english": "Mixing sounds with different tone colors so they blend into one new sound. It is like mixing paint colors to get a shade you cannot get from just one.", "purpose_function": "It creates richer or unique tones by blending the tonal qualities of several sources into one.", "practical_application": "A producer layers, for example, a smooth sub with a gritty synth, or doubles a vocal with a different take, to shape one blended timbre.", "category": "Arrangement", "related_terms": ["Texture layering", "Synthetic texture", "Tonal texture", "Doubling", "Timbre"], "common_mistakes": ["Layering timbres that mask each other instead of blending", "Not phase-aligning the layers so the combined tone thins out", "Choosing colors that clash rather than complement"], "scenario_contexts": ["Blending two synth patches to build one signature lead", "Layering a real snare with a sample for a fuller tone", "Doubling a vocal with a different mic or take for color"]}, "9a1ccf06-96f3-4a38-8254-4a9e940b9c74": {"definition": "Applying a noise gate to tom-tom drum tracks so a channel passes sound only when a tom is struck, removing bleed from other drums and cymbals and controlling ring.", "plain_english": "Using a gate so the tom mic is only open when the tom is hit. This cuts bleed from the rest of the kit and cleans up the drum sound.", "purpose_function": "It reduces spill from cymbals and other drums into open tom mics, tightening the drum mix.", "practical_application": "An engineer sets the gate threshold and timing on each tom channel so it opens on the hit and closes on the decay.", "category": "Drum Processing", "related_terms": ["Noise gate", "Tom mixing", "Tom sustain control", "Threshold", "Drum bleed"], "common_mistakes": ["Setting the threshold too high so soft tom hits are cut off", "Using a fast release that chops off the natural tom decay", "Forgetting that loud bleed can falsely retrigger the gate"], "scenario_contexts": ["Cleaning up open tom mics in a rock drum recording", "Live sound: gating toms to reduce spill and feedback risk", "Tightening a drum mix before adding room reverb"]}, "8474b933-3f7d-45a2-a0d6-7503b1e469fa": {"definition": "The process of balancing, equalizing, and processing tom-tom tracks within a drum mix so they sound clear and punchy and blend with the rest of the kit.", "plain_english": "Getting the toms to sound good in the drum mix. This means setting their level, tone, and effects so they hit hard and fit with the other drums.", "purpose_function": "It makes tom fills sit powerfully and clearly, without overpowering the kit or disappearing behind the other drums.", "practical_application": "An engineer sets tom levels, EQs out boxiness, may compress or gate them, and pans them to match the kit layout.", "category": "Drum Processing", "related_terms": ["Tom gating", "Tom resonance control", "Tom sustain control", "Panning", "Equalization"], "common_mistakes": ["Boosting low mids and leaving the toms boomy and boxy", "Panning toms opposite to how the kit is actually set up", "Setting tom level only during fills, so they jump out too loud"], "scenario_contexts": ["Mixing a drum kit for a rock track with big tom fills", "Balancing toms against kick and snare in a busy mix", "Panning toms across the stereo field to match the drummer's layout"]}, "d331349b-526c-42e5-9518-b6fbbdd7a183": {"definition": "Managing the resonant ringing of tom-toms through tuning, dampening, EQ, or gating so the sustained overtones support the drum sound rather than muddy it.", "plain_english": "Taming the long ring a tom makes after it is hit. You can tune it, add dampening, or use EQ so the ring helps the sound instead of making it muddy.", "purpose_function": "It keeps tom overtones musical and controlled, avoiding unwanted boom or clashing ring in the mix.", "practical_application": "A tech tunes the heads and adds dampening at the kit, then an engineer uses EQ or gating to further shape the resonance.", "category": "Drum Processing", "related_terms": ["Tom sustain control", "Tom gating", "Tom mixing", "Dampening", "Equalization"], "common_mistakes": ["Over-dampening so the toms sound dead and lifeless", "Cutting resonance with harsh EQ and losing the tom's body", "Ignoring room ring that adds to the resonance"], "scenario_contexts": ["Taming ringy toms at a drum tracking session", "Controlling boomy tom resonance in a live room", "Using dampening gel on tom heads before recording"]}, "7ae9fd82-f52d-438d-b88c-b76cf781c61c": {"definition": "Controlling how long a tom-tom rings on after it is struck, using dampening, gating, or envelope shaping to set the decay length.", "plain_english": "Deciding how long a tom keeps ringing after the hit. You can shorten it with dampening or a gate, or let it ring longer for a bigger sound.", "purpose_function": "It matches tom decay to the song, keeping fills tight or leaving them open as the arrangement needs.", "practical_application": "An engineer shortens tom sustain with a gate or dampening for tight modern styles, or leaves it long for a roomy, open sound.", "category": "Drum Processing", "related_terms": ["Tom gating", "Tom resonance control", "Tom mixing", "Dampening", "Decay"], "common_mistakes": ["Cutting sustain so short the toms lose punch and body", "Relying only on a gate and skipping physical dampening", "Leaving toms ringing so long they clash with the next hit"], "scenario_contexts": ["Tightening tom decay for a fast, punchy rock fill", "Leaving long sustain for an open, ambient drum sound", "Using moongel to shorten tom sustain during tracking"]}, "0aa8bcb1-6852-4734-8cf7-651b4afbb3d7": {"definition": "The overall tonal character of a sound or arrangement, arising from its harmonic and timbral content, describing how bright, warm, thick, or thin the combined sound feels.", "plain_english": "The overall tone color of a sound or a whole mix. It describes whether things feel warm, bright, thick, or thin when you listen.", "purpose_function": "It gives engineers a way to describe and shape the tonal feel of an arrangement so parts fit a wanted mood.", "practical_application": "An engineer adjusts EQ, part choices, and layering to steer the tonal texture warmer or brighter to match the song.", "category": "Arrangement", "related_terms": ["Timbre layering", "Texture layering", "Synthetic texture", "Timbre", "Equalization"], "common_mistakes": ["Confusing tonal texture with loudness", "Making every part bright so the whole mix turns harsh", "Judging tone only in solo and ignoring how parts combine"], "scenario_contexts": ["Shaping a warm tonal texture for a mellow ballad", "Brightening the tonal texture of a dull-sounding mix", "Matching the tonal texture of overdubs to the original band tracks"]}, "22ab3cc6-ec0a-4161-aa8c-3a31f28fea9a": {"definition": "A short passage of sound placed between two sections of an arrangement to bridge them, using changes in instrumentation, density, or effects rather than a fixed melody or groove. Common forms include filtered sweeps, drum fills, risers, cymbal swells, and drop-outs that carry the listener from one part into the next.", "plain_english": "It is a short bit of sound that joins two parts of a song, like a bridge between rooms. It might be a drum fill or a rising sweep that leads you into the next section.", "purpose_function": "It smooths the join between sections and builds or releases energy, so a change like verse to chorus feels natural instead of abrupt. It also cues the listener that something new is coming.", "practical_application": "A technician adds a riser, reverse cymbal, filter sweep, or drum fill in the last bar or two before a new section, riding its level so it lifts into the downbeat.", "category": "Arrangement Texture", "related_terms": ["Riser", "Drum fill", "Noise texture", "Ambience layer", "Automation"], "common_mistakes": ["Making the transition so loud or busy that it buries the downbeat it is supposed to lead into.", "Using the same fill or sweep at every section change so the transitions become predictable and stale.", "Forgetting a transition entirely, so section changes feel sudden and jarring."], "scenario_contexts": ["Adding a filtered white-noise riser in the bar before a chorus to build tension.", "Dropping the arrangement to a single element for one bar to reset energy before a new section.", "Placing a drum fill at the end of a verse to hand off into the chorus."]}, "8935b0c0-8b59-4ed5-98bf-1328515e8a54": {"definition": "The false firing of a drum trigger caused by vibration or acoustic energy from a neighboring drum or cymbal reaching that trigger's pad or sensor. For example, a hard snare hit can shake the rack tom shell enough to fire the tom trigger, producing an unwanted note.", "plain_english": "It is when hitting one drum accidentally sets off the trigger on another drum nearby. The shaking travels through the kit, like a slammed door making a picture on the wall rattle.", "purpose_function": "Understanding crosstalk matters because triggers convert drum hits into MIDI or samples, and false hits from a neighboring drum ruin the replaced or reinforced sound. Managing it keeps the triggered part clean and true to what was played.", "practical_application": "A technician raises the trigger threshold on sensitive channels, uses the module's crosstalk or cross-cancel setting, and mounts triggers firmly so a nearby drum does not fire the wrong pad.", "category": "Drum Triggering", "related_terms": ["Trigger threshold", "Trigger retrigger cancellation", "Drum trigger", "Sample replacement", "Bleed"], "common_mistakes": ["Setting trigger thresholds too low, so vibration from adjacent drums easily fires false hits.", "Blaming the drum module for stray notes when the real cause is loose trigger mounting picking up shell vibration.", "Ignoring crosstalk during setup and only discovering ghost hits after the whole take is recorded."], "scenario_contexts": ["A tom trigger firing on its own every time the drummer plays a hard snare backbeat.", "Setting cross-cancellation on a drum module so kick hits stop triggering the snare pad.", "Replacing sloppy live drums with samples and cleaning up false trigger notes caused by kit vibration."]}, "242b695d-73f6-43ac-8f36-aad9a0ec1e84": {"definition": "A drum-trigger setting that blocks a second false trigger from firing during the ringing or decay of a single hit, so one strike produces only one note. It works by holding off further triggering for a short masking time after the initial detection, preventing double hits from a drum head's secondary vibrations.", "plain_english": "It stops one drum hit from being counted as two. After a hit fires, the trigger briefly ignores the drum's ringing, like a light switch that will not flicker back on right away.", "purpose_function": "It exists because a struck drum head vibrates unevenly and can cross the trigger threshold more than once per hit, creating extra machine-gun notes. Cancellation guarantees one clean note per strike so triggered samples stay accurate.", "practical_application": "A technician sets the retrigger or mask time on each pad long enough to ignore the head's ring-down but short enough to still catch fast, genuine repeated hits.", "category": "Drum Triggering", "related_terms": ["Trigger threshold", "Trigger crosstalk", "Drum trigger", "Mask time", "Sample replacement"], "common_mistakes": ["Setting the mask time too long, which swallows fast genuine hits like drum rolls or double strokes.", "Setting it too short, so single hits produce stuttering double notes from head vibration.", "Confusing retrigger cancellation with crosstalk cancellation, which addresses a different problem between separate drums."], "scenario_contexts": ["Dialing in mask time so a single snare hit no longer fires two rapid samples.", "Tuning retrigger settings on a floor tom so its long decay stops causing extra notes.", "Balancing mask time on a fast kick pattern so real double-kick hits still register."]}, "5d8f8ef1-9797-4bd2-8f83-9b37d6297f59": {"definition": "The minimum input level a signal from a drum trigger or gate must exceed before a note or event is fired. Signals below the threshold are ignored, so it sets the dividing line between hits that count and low-level noise, bleed, or vibration that should not.", "plain_english": "It is the loudness a hit must reach before the trigger fires. Anything quieter is ignored, like a doorbell that only rings when you press it hard enough.", "purpose_function": "It separates real hits from unwanted low-level energy such as bleed from other drums, hum, or head vibration, so only intended strikes produce a note. Setting it correctly keeps triggered drums clean and reliable.", "practical_application": "A technician raises the threshold until stray bleed and crosstalk stop firing notes, then checks that the softest intended ghost notes still trigger dependably.", "category": "Drum Triggering", "related_terms": ["Trigger crosstalk", "Trigger retrigger cancellation", "Drum trigger", "Gate", "Sample replacement"], "common_mistakes": ["Setting the threshold too high, so quiet ghost notes and soft hits are missed entirely.", "Setting it too low, so bleed and crosstalk from other drums fire false notes.", "Setting the threshold once and not rechecking it when the drummer changes playing dynamics."], "scenario_contexts": ["Raising the trigger threshold so snare bleed stops firing the kick sample.", "Lowering the threshold so a drummer's soft ghost notes trigger reliably.", "Setting a gate threshold on a tom so it only opens when the tom is actually struck."]}, "6c13c92c-fd15-4ca7-8fce-e947b5b41ee4": {"definition": "A recording technique in which the same part is performed and recorded three separate times, then blended, to thicken and widen it. The natural timing and pitch differences between the three takes create a fuller, more powerful sound than a single take.", "plain_english": "It means playing or singing the same part three times and stacking the takes together. The tiny differences between them make the sound bigger and wider, like three people singing the same line.", "purpose_function": "It reinforces a part and adds width and weight because the small human variations between takes reduce phase cancellation and spread the sound across the stereo field. Producers use it to make guitars, vocals, or hooks sound larger than life.", "practical_application": "A technician records three passes of a rhythm guitar or vocal, often panning two of them left and right and keeping one centered, then balances their levels so they fuse into one thick part.", "category": "Arrangement Technique", "related_terms": ["Double tracking", "Unison layering", "Unison stack", "Panning", "Comping"], "common_mistakes": ["Copying and pasting one take three times instead of performing separate takes, which just raises level and causes phase issues rather than thickening.", "Letting the three takes drift so far in timing that the part smears and loses definition.", "Stacking three loud takes without balancing them, so the part overpowers the rest of the mix."], "scenario_contexts": ["Recording three passes of a distorted rhythm guitar to build a wide, heavy wall of sound.", "Triple tracking a chorus vocal so the hook sounds bigger than the verses.", "Layering three takes of a backing part and panning them for width in a dense mix."]}, "90824c17-090b-4ee2-a603-e042682881f4": {"definition": "The stacking of two or more parts that play the same notes at the same pitch to reinforce a line and thicken its tone. The layers may be separate performances of the same part or different sounds doubling the same pitch, blended so they sound like one bigger voice.", "plain_english": "It means stacking parts that play the exact same notes at the same pitch. Blending them makes one fuller sound, like several people singing the same note together.", "purpose_function": "It adds weight, richness, and power to a part without changing its notes, since combining sources at the same pitch reinforces the line. It is a core way to make leads, vocals, and hooks sound larger.", "practical_application": "A technician doubles a vocal or synth part at the same pitch, or layers a second instrument onto the same line, then balances levels and checks tuning so the layers fuse cleanly.", "category": "Arrangement Technique", "related_terms": ["Unison stack", "Double tracking", "Triple tracking", "Octave layering", "Voicing"], "common_mistakes": ["Layering identical digital copies that phase-cancel or just get louder instead of sounding fuller.", "Ignoring small tuning differences between layers, which makes the combined part sound out of tune.", "Stacking too many unison layers so the part becomes bloated and masks other elements."], "scenario_contexts": ["Doubling a lead vocal at the same pitch to give a chorus more body.", "Layering two synths on the same melody so the hook sounds thicker.", "Reinforcing a horn line with a second instrument playing the same notes."]}, "1d76799f-7d37-46eb-9a49-a74de5cea6fd": {"definition": "A group of two or more sounds or voices playing the same note at the same pitch, combined into a single reinforced part. In synthesis it often refers to a unison mode that layers several slightly detuned copies of one oscillator to fatten the tone.", "plain_english": "It is a set of sounds all playing the same note together to make one big sound. On a synth, a unison mode stacks slightly detuned copies so the tone sounds fat.", "purpose_function": "It creates a thicker, more powerful voice from a single note by piling up energy at the same pitch, with slight detuning adding width and movement. It is a fast way to make leads, basses, and pads sound huge.", "practical_application": "A technician engages a synth's unison mode and sets the number of voices and detune amount, or manually stacks several same-pitch takes, to build a fat lead or bass.", "category": "Arrangement Technique", "related_terms": ["Unison layering", "Octave stack", "Detune", "Oscillator", "Voicing"], "common_mistakes": ["Adding too much detune so the unison stack drifts noticeably out of tune instead of sounding rich.", "Piling on unison voices until the low end becomes muddy and the sound loses focus.", "Confusing a unison stack with a chord, when a stack reinforces one pitch rather than adding harmony."], "scenario_contexts": ["Using a synth's unison mode with light detune to fatten a lead for a chorus.", "Building a wide supersaw bass from a heavily stacked unison patch.", "Stacking several same-pitch vocal takes into one powerful shout in a bridge."]}, "5e99bb6f-f264-4c98-ba38-e8e1368c785f": {"definition": "The techniques used to place a double bass (upright acoustic bass) into a mix by managing its level, low-end weight, note definition, and any finger or bow noise. Because the instrument produces strong low frequencies with a soft attack and often uses both a pickup and a microphone, mixing focuses on keeping notes clear and even without boom or mud.", "plain_english": "It is how you set the level and tone of an upright bass in a song. The goal is a warm, even low end where each note is clear, not boomy or muddy.", "purpose_function": "It integrates a big, resonant acoustic instrument into an arrangement so it supports the low end and locks with the drums while staying defined. Good mixing keeps every note audible and stops the bass from swamping the mix.", "practical_application": "A technician blends the pickup and mic signals, high-passes out subsonic rumble, uses compression to even out note-to-note level, and adds gentle mid presence so the bass line stays clear against the kick.", "category": "Instrument Mixing", "related_terms": ["Bass compression", "Equalization", "High-pass filter", "Kick-bass balance", "DI box"], "common_mistakes": ["Boosting the lows to sound big, which makes the upright boomy and blurs the pitch of each note.", "Leaving note levels uneven, since an acoustic bass varies from note to note, so the line drops out on some notes and jumps out on others.", "Ignoring finger and string noise, letting slaps and squeaks distract from the notes."], "scenario_contexts": ["Blending a pickup and a microphone on an upright bass to get both punch and body in a jazz mix.", "Compressing an acoustic bass so each note sits at an even level under the drums.", "High-passing an upright bass to remove floor rumble while keeping its warmth."]}, "89c5106e-9b1a-40c0-abca-a905582d4035": {"definition": "The practices used to reduce unwanted noise from valve (vacuum-tube) audio equipment such as tube preamps, compressors, and guitar amplifiers, including hiss, hum, and microphonic ringing. It combines gain staging, quiet or matched tubes, proper grounding, and gating so the desirable valve tone is kept while the noise floor is managed.", "plain_english": "It is how you keep the hiss and hum from tube gear low while keeping its warm sound. Tubes are like old glowing bulbs that can whistle or buzz, so you set levels and fix grounding to keep them quiet.", "purpose_function": "It exists because valve equipment naturally adds hiss, hum, and microphonic noise, which can build up on quiet tracks and across many channels. Controlling it preserves the valve's warm character while keeping recordings clean.", "practical_application": "A technician sets sensible gain staging, replaces noisy or microphonic tubes, ensures a solid ground to kill hum, and uses a noise gate on high-gain valve amp tracks between phrases.", "category": "Signal Integrity", "related_terms": ["Noise floor", "Gain staging", "Ground loop", "Noise gate", "Hum"], "common_mistakes": ["Cranking valve gain far past what the part needs, which pushes the hiss and hum up with the signal.", "Blaming cables for hum when the real cause is a ground loop or a worn, noisy tube.", "UNSAFE: Opening a tube amplifier or preamp to swap valves without unplugging it and letting the high-voltage capacitors fully discharge, risking severe electric shock."], "scenario_contexts": ["Gating a high-gain valve guitar amp track so hiss disappears between riffs.", "Tracing and fixing a ground loop that is adding hum to a tube preamp channel.", "Swapping a microphonic tube in a valve compressor to stop it ringing during loud passages."]}, "06de1777-e922-424d-9627-187054aea70b": {"definition": "The process of adding or boosting very-high-frequency content on a vocal, typically above roughly 10 kHz, to give it a sense of openness, breathiness, and sheen. It is done with a high-shelf EQ or with a harmonic exciter that generates new high-frequency detail.", "plain_english": "It means adding a gentle lift to the very top of a voice so it sounds open and airy. It is like opening a window to let a little light and space into the sound.", "purpose_function": "It adds detail and presence so a lead vocal sits on top of the mix and sounds clear and modern. Without it a voice can feel dull or closed in.", "practical_application": "While mixing a lead vocal, a technician dials in a high-shelf boost around 10 to 16 kHz or inserts an air band or exciter, checking that sibilant sounds do not turn harsh.", "category": "Vocal EQ", "related_terms": ["Vocal brightness control", "High-shelf EQ", "Harmonic exciter", "De-essing", "Vocal body enhancement"], "common_mistakes": ["Pushing the air band so high that the vocal becomes harsh and the sibilant s and t sounds spit.", "Boosting broadband highs and raising hiss and noise along with the wanted air.", "Adding air on a dull raw recording instead of first fixing the source or mic choice."], "scenario_contexts": ["Brightening a close-miked lead vocal so it cuts through a dense band mix.", "Adding sheen to a vocal recorded with a darker dynamic microphone.", "Using an exciter to restore air to a vocal that lost highs after heavy compression."]}, "fa4613ba-92f4-4b48-8646-14d9d0a73573": {"definition": "The management of the room reverberation and spatial character heard around a recorded vocal, by capturing, reducing, gating, or adding natural and artificial reverb. It sets how close or distant and how wet or dry the voice sounds in the mix.", "plain_english": "It means setting how much room echo you hear around a voice. It decides if the singer sounds close and dry or far off in a big space.", "purpose_function": "It places the vocal at a chosen distance and mood so it matches the song and sits clearly against the band. Too much ambience blurs the words, while too little sounds flat.", "practical_application": "While mixing, a technician trims recorded room sound, gates spill between phrases, or adds reverb sends so the ambience supports the vocal without muddying it.", "category": "Vocal Processing", "related_terms": ["Reverb", "Room tone", "Noise gate", "Vocal background-noise repair", "Dry/wet balance"], "common_mistakes": ["Adding heavy reverb to a vocal already recorded in a live room, which washes out the words.", "Gating room spill so hard that phrase tails cut off abruptly and sound unnatural.", "Judging ambience on a solo vocal instead of against the full mix where the band fills space."], "scenario_contexts": ["Drying up a bedroom vocal take so it does not sound boxy behind the band.", "Adding a short plate reverb so a close, dry vocal feels natural in a ballad.", "Gating headphone bleed and room noise before adding controlled reverb of your own."]}, "6f123137-dda6-4679-b3b6-a0f8b51f9b6e": {"definition": "The planning and layering of the vocal parts in a song, including lead, harmonies, doubles, ad-libs, and backing vocals, along with their timing, register, and placement. It shapes the overall vocal texture of an arrangement and guides what gets tracked.", "plain_english": "It means deciding how all the sung parts fit together in a song. It covers the main tune plus harmonies and backup voices, and when each one comes in.", "purpose_function": "It shapes the emotion and fullness of a song's vocals and tells the engineer which parts to record and where. A strong arrangement keeps the lead clear while backing parts add depth.", "practical_application": "Before or during tracking, a producer maps out the lead, doubles, and harmony stacks, then records each part in turn to build the planned vocal texture.", "category": "Vocal Arrangement", "related_terms": ["Harmony vocals", "Double tracking", "Lead vocal", "Backing vocals", "Vocal comping"], "common_mistakes": ["Stacking so many harmony and backing parts that they bury the lead vocal and blur the lyric.", "Recording harmonies without a clear plan, so parts clash in register or timing.", "Doubling every section the same way instead of saving big stacks for choruses and hooks."], "scenario_contexts": ["Planning lead, double, and three-part harmonies for a chorus before a tracking session.", "Adding ad-libs and answer lines to fill space between the lead vocal phrases.", "Deciding which verse lines stay solo and which sections open up with backing vocals."]}}$j$::jsonb)) d
WHERE g.id = d.id;
COMMIT;
